using namespace std;

typedef pair<int, int> P;

int normalize(int s) {	//正整数n, mで「n * m^3 = s」と表すときの最大のmをMとおき、s/M^3を返す。
	int n, m;
	double eps1 = 1e-10;
	double eps2 = 1e-9;

	for (n = 1; n <= 316; n++) {
		if (s % n == 0) {
			double md = pow(s / n, 1.0 / 3) + eps1;
			int m = (int)md;
			if (md - m <= eps2) {
				return s / (m * m * m);
			}
		}
	}
	for (m = 316; m >= 1; m--) {
		if (s % (m * m * m) == 0) {
			return s / (m * m * m);
		}
	}
	return -1;
}

bitset<100000001> bset;
void prepare() {
	int i;

	for (i = 1; i <= 10000; i++) {
		bset[i * i] = 1;
	}
}

int findPair(int s) {	//正整数n, mで「n * m^2 = s」と表すときの最大のmをMとおき、(s / M^2)^2 * Mを返す。
	int n, m;
	double eps1 = 1e-10;
	double eps2 = 1e-9;

	for (n = 1; n <= 2200; n++) {
		if (s % n == 0) {
			if (n >= 100) {
				if (bset[s / n]) {
					m = (int)(sqrt((double)s / n) + eps1);
					return n * n * m;
				}
			}
			else {
				double md = sqrt((double)s / n) + eps1;
				int m = (int)md;
				if (md - m <= eps2) {
					return n * n * m;
				}
			}
		}
	}
	for (m = 2200; m >= 1; m--) {
		if (s % (m * m) == 0) {
			n = s / (m * m);
			if (n > 100000) return -1;
			return n * n * m;
		}
	}
	return -1;
}

int n;
int s[100000];
map<int, int> cntMp;
vector<P> pairs;

signed main() {
	int i;

	prepare();
	cin >> n;
	rep(i, n) { cin >> s[i]; s[i] = normalize(s[i]); cntMp[s[i]]++; }
	rep(i, n) {
		int t = findPair(s[i]);
		if (s[i] <= t) pairs.push_back(P(s[i], t));
		else pairs.push_back(P(t, s[i]));
	}
	sort(pairs.begin(), pairs.end());
	pairs.erase(unique(pairs.begin(), pairs.end()), pairs.end());

	int ans = 0;
	rep(i, pairs.size()) {
		int u = pairs[i].first;
		int v = pairs[i].second;
		if (u == 1) { ans++; continue; }
		ans += max(cntMp[u], cntMp[v]);
	}
	cout << ans << endl;
	return 0;
}

