    return upper_bound(a+1, a+1+n, x) - lower_bound(a+1, a+1+n, x);
}

long long cal(long long x){
    long long ans = 1;
    for (long long i = 2; i * i <= x; i++){
        if (prime[i] != i) continue;
        if (x % i != 0) continue;
        if (x % (i * i) == 0) ans *= i, x /= i * i;
        else ans *= i * i, x /= i;
        if (ans > 10000000000) return -1;
    }
    long long sqr = sqrt(x);
    if (sqr * sqr == x) ans *= sqr;
    else {
        if (x > 100000) return -1;
        ans *= x * x;
    }
    return ans;
}

