struct Millar{
  // const vl v = { 2 , 7 , 61 }; // < 4,759,123,141
  const vl v = { 2 , 3 , 5 , 7 , 11 , 13 , 17 , 19 , 23 }; // ??
  ll modpow( __int128 x , __int128 k , __int128 mo ){
    ll res = 1;
    while( k ){
      if( k & 1 ) res = res * x % mo;
      k /= 2;
      x = x * x % mo;
    }
    return res;
  }
  bool check( ll n ){
    if( n < 2 ) return false;
    ll d = n - 1, s = 0;
    while( d % 2 == 0 ) d /= 2, s++;
    YYS( a , v ){
      if( a == n ) return true;
      if( modpow( a , d , n ) != 1 ){
	bool ok = true;
	REP( r , s ) if( modpow( a , d * PW(r) , n ) == n-1 ) ok = false;
	if( ok ) return false;
      }
    }
    return true;
  }
};


struct Rho{
  mt19937 mt;
  Millar isp;
  ll c;
  Rho(){
    mt.seed( time(NULL) );
  }
  inline ll f( __int128 x , __int128 n ){
    return ( x*x%n + c ) % n;
  }
  ll check( ll n ){
    if( n == 4 ) return 2;
    c = mt() % n;
    ll x = mt() % n;
    ll y = x;
    ll d = 1;
    while( d == 1 ){
      x = f(x,n);
      y = f(f(y,n),n);
      d = __gcd( abs(x-y) , n );
    }
    if( d == n ) return -1;
    return d;
  }
  vl factor( ll n ){
    if( n <= 1 ) return {};
    if( isp.check( n ) ) return { n };
    ll res = -1;
    while( res == -1 ) res = check( n );
    vl fa = factor( res );
    vl fb = factor( n / res );
    fa.insert( fa.end() , ALL(fb) );
    return fa;
  }
} rho;


