using namespace std;
#define REP(i,n) for (int i=0;i<(n);i++)
#define REP2(i,m,n) for (int i=m;i<(n);i++)
typedef long long ll;

const ll MAX = 2500;
ll S[101010];
bool isP[MAX];

void solve() {
    int N;
    cin >> N;
    REP(i, N) cin >> S[i];

    REP2(i, 2, MAX) isP[i] = true;
    vector<ll> P;
    REP2(i, 2, MAX) if (isP[i]) {
        P.push_back(i);
        for (ll j = i + i; j < MAX; j += i) {
            isP[j] = false;
        }
    }

    unordered_map<ll, ll> cnt;

    REP(i, N) {
        for (auto p: P) {
            ll p3 = p * p * p;
            while (S[i] % p3 == 0) S[i] /= p3;
        }
        cnt[S[i]] += 1;
    }

    unordered_set<ll> used;
    ll ans = 0;

    for (const auto & [k, v] : cnt) {
        if (used.find(k) != used.end()) {
            continue;
        }
        ll counterpart = 1;
        for (auto p : P) {
            if (k % (p * p) == 0) {
                counterpart *= p;
            } else if (k % p == 0) {
                counterpart *= p * p;
            }
        }
        used.insert(k);
        used.insert(counterpart);
        if (k == counterpart) {
            ans += 1;
        } else {
            ans += max(v, cnt[counterpart]);
        }
    }

    cout << ans << endl;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    solve();
}

