                for (j = 0; j < v.size() && a[i] > 1; j++) {
                    int c = 0;

                    while (a[i] % v[j] == 0) {
                        c++;
                        a[i] /= v[j];
                    }

                    c %= 3;

                    if (c > 0) w.push_back(make_pair(v[j], c));
                }
            }
        }

        mp[w]++;
    }

    for (it = mp.begin(); it != mp.end(); it++) {
        if (it->second == -1) continue;

        if (it->first.size() == 0) {
            ans++;
        } else {
            vector <pair<long long, int> > w;

            for (j = 0; j < it->first.size(); j++) w.push_back(make_pair(it->first[j].first, 3 - it->first[j].second));

            if (mp.count(w)) {
                ans += max(it->second, mp[w]);
                mp[w] = -1;
            } else {
                ans += it->second;
            }
        }
    }

    printf("%d\n", ans);

    return 0;
}

