using pii = pair<uint64_t, uint64_t>;

pii Norm(uint64_t x) {
    vector<uint64_t> p, d;
    for (int i = 2; i * i <= x; ++i) {
        if (x % i == 0) {
            p.push_back(i);
            d.push_back(0);
            while (x % i == 0) {
                d.back()++;
                x /= i;
            }
        }
    }
    if (x != 1) {
        p.push_back(x);
        d.push_back(1);
    }
    uint64_t a = 1, b = 1;
    for (int i = 0; i < p.size(); ++i) {
        if (d[i] % 3 == 0) continue;
        a *= p[i];
        b *= p[i];
        if (d[i] % 3 == 1) {
            b *= p[i];
        } else {
            a *= p[i];
        }
    }
    return {a, b};
}

