	for(int i=2;i<=3000;++i)
	{
	//	if(1LL*i*i*i >= INF) break;
		if(p[0][i]) continue;
		p[1][tot] = i;
		p[2][tot] = i*i;
		p[3][tot++] = 1LL*i*i*i;
		for(int j=i;j <= 3000;j+=i)
		{
//			if(1LL*j*j*j >= INF) break;
			p[0][j] = 1;
