void init() {
	memset(ip,1,sizeof(ip));
	ip[0]=ip[1]=0;
	for (int i=2;i<=mx;i++)
		if (ip[i]) {
			p.push_back(i);
			for (int j=i*i;j<=mx;j+=i)
				ip[j]=0;
		}
	sz=p.size();
}
ll solve(ll x) {
	for (ll i=0;i<sz;i++) {
		ll t=p[i]*p[i]*p[i];
		if (t>x) break;
		while (x%t==0) x/=t;
	}
	return x;
}
ll S(ll x) {
	ll l=1,r=100000;
	while (l<r) {
		ll mid=(l+r+1)>>1;
		if (mid*mid<=x) l=mid;
		else r=mid-1;
	}
	return l;
}
ll T(ll x) {
	ll A=1,B=1;
	for (ll i=0;i<sz;i++) {
		if (p[i]*p[i]*p[i]>x) break;
		int ss=0;
		while (x%p[i]==0) {
			x/=p[i]; ss++;
		}
		if (ss==1) A*=p[i]; else if (ss==2) B*=p[i];
	}
	ll tmp=S(x);
	if (tmp*tmp==x) B*=tmp;
	else A*=x;
	ll res=A*B;
	if (res>INF/A+1) res=INF; else res*=A;
	return res;
}

