{
  std::ios::sync_with_stdio(false);

  const int N = 100000 + 10;
  bool prime[N];
  fill(prime, prime + N, true);
  prime[0] = prime[1] = false;
  for (int i = 2; i * i < N; ++i) {
    for (int j = 2; i * j < N; ++j) {
      prime[i * j] = false;
    }
  }

  vector<lli> P;
  for (int i = 0; i * i < N; ++i) {
    if (prime[i]) P.push_back(i);
  }

  constexpr int M = 100000 + 10;
  int n;
  while (scanf("%d", &n) == 1) {
    static lli s[M];
    for (int i = 0; i < n; ++i) {
      scanf("%lld", s + i);
    }

    static lli norm[M];
    for (int i = 0; i < n; ++i) {
      norm[i] = s[i];
      for (lli j = 2; j * j * j <= 10000000000LL; ++j) {
        lli k = j * j * j;
        while (norm[i] % k == 0) {
          norm[i] /= k;
        }
      }
    }

    map<lli, lli> pair;
    for (int i = 0; i < n; ++i) {
      lli q = 1;
      lli m = norm[i];
      each (p, P) {
        if (m % (p * p) == 0) {
          m /= (p * p);
          q *= p;
        }
        if (m % p == 0) {
          m /= p;
          q *= p * p;
        }
      }
      if (m != 1) {
        q *= m * m;
      }
      pair[norm[i]] = q;
    }

    map<lli, int> a, b;
    for (int i = 0; i < n; ++i) {
      ++a[norm[i]];
    }
    for (int i = 0; i < n; ++i) {
      ++b[pair[norm[i]]];
    }

    int sum = bool(a[1]);
    a[1] = b[1] = 0;

    for (int i = 0; i < n; ++i) {
      lli x = norm[i];
      lli y = pair[x];
      sum += max(a[x], b[y]);
      a.erase(x);
      a.erase(y);
      b.erase(x);
      b.erase(y);      
    }
    printf("%d\n", sum);
  }

  return 0;
}

