inline void jzp(int n){
	for(int x=2;x<=n;++x){
		if(!vis[x])pri.push_back(x);
		for(auto&y:pri){
			if((ll)x*y>n)break;
			vis[x*y]=1;
			if(!(x%y))break;
		}
	}
}

inline ll get_norm(ll x){
	for(auto&y:pri){
		ll z=1ll*y*y*y;
		if(z>x)break;
		while(!(x%z))x/=z;
	}
	return x;
}

inline ll get_pair(ll x){
	ll res=1;
	for(auto&y:pri){
		ll z=(ll)y*y*y;
		if(z<=x){
			while(!(x%z))x/=z;
			if(!(x%(y*y))){
				res*=y,x/=(y*y);
				if(res>=inf)
					return inf;
			}
			else if(!(x%y)){
				res*=(y*y),x/=y;
				if(res>=inf)
					return inf;
			}
		}
		else{
			ll w=(ll)y*y;
			if(w>x){
				if(inf/x/x<res)
					return inf;
				return res*=x*x;
			}
			else if(!(x%y)){
				if(x==w){
					res*=y;
					return res>=inf?inf:res;

				}
				else{
					if(inf/x/x<res)
						return inf;
					res*=x*x;
					return res;
				}
			}
		}
	}
	if(inf/x/x<res)
		return inf;
	res*=x*x;
	return res;
}

