map<ll,int> cnt;
map<ll,ll> match;

void init()
{
	ll LIM = pow(INF,1.0 / 3) + 1;
	for (int i = 2;i <= LIM;i++)
	{
		if (!mark[i])
			prime[++tot] = i;
		for (int j = 1;j <= tot && i * prime[j] <= LIM;j++)
		{
			mark[i * prime[j]] = true;
			if (i % prime[j] == 0)
				break;
		}
	}
}

int main()
{
	ios::sync_with_stdio(false);
	init();
	cin >> n;
	for (int i = 1;i <= n;i++)
	{
		ll a,spj;
		cin >> a;
		ll mat = 1,A = a;
		for (ll J = 1,j = prime[J];J <= tot && j * j * j <= a;j = prime[++J])
		{
			while (a % (j * j * j) == 0)
			{
				a /= j * j * j;
				A /= j * j * j;
			}
			if (a % (j * j) == 0)
			{
				a /= j * j;
				if (mat > INF / j)
				{
					mat = INF + 1;
					break;
				}
				mat *= j;
			}
			if (a % j == 0)
			{
				a /= j;
				if (mat > INF / j / j)
				{
					mat = INF + 1;
					break;
				}
				mat *= j * j;
			}
		}
		cnt[A]++;
		if (mat == INF + 1)
			continue;
		spj = pow(a,1.0 / 2);
		while (spj * spj < a)
			spj++;
		while (spj * spj > a)
			spj--;
		if (spj * spj == a)
		{
			a /= spj * spj;
			if (mat > INF / spj)
				continue;
			mat *= spj;
		}
		if (mat > INF / a / a)
			continue;
		mat *= a * a;
		match[match[mat] = A] = mat;
	}
	for (map<ll,int>::iterator i = cnt.begin();i != cnt.end();i++)
	{
		if ((*i).first == 1)
		{
			ans += (*i).second - 1;
			continue;
		}
		ll cur = min((*i).second,cnt[match[(*i).first]]);
		ans += cur;
		(*i).second -= cur;
		cnt[match[(*i).first]] -= cur;
	}
	cout << n - ans << endl;
	return 0;
}

