using namespace std;

const int SQRT = 110000;
const int CBRT = 2200;

bool prime[SQRT];
vector<int> primes;
vector<long> squares;

pair<long, long> func(long x) {
	long a = 1, b = 1;
	for (long d : primes) {
		if (d * d * d > x) {
			break;
		}
		int cnt = 0;
		while (x % d == 0) {
			x /= d;
			++cnt;
		}
		cnt %= 3;
		if (cnt == 1) {
			a *= d;
			b *= d * d;
		} else if (cnt == 2) {
			a *= d * d;
			b *= d;
		}
	}
	if (!binary_search(all(squares), x)) {
		a *= x;
		b *= x * x;
	} else {
		a *= x;
		b *= sqrt(x);
	}
	return {a, b};
}


