vector<ll>prime_list;
vector< bool > prime_table(ll n) {
  vector< bool > prime(n + 1, true);
  if(n >= 0) prime[0] = false;
  if(n >= 1) prime[1] = false;
  for(ll i = 2; i * i <= n; i++) {
    if(!prime[i]) continue;
    for(ll j = i + i; j <= n; j += i) {
      prime[j] = false;
    }
  }
  return prime;
}

vector<P>factoring(ll &n){
  vector<P>ret;
  rep(i,0,prime_list.size()){
    ll cnt=0;
    if(prime_list[i]>=3000)break;
    while(n%prime_list[i]==0){
      cnt++;
      n/=prime_list[i];
    }
    if(cnt%3>=1)ret.EB(i,cnt%3);
  }
  return ret;
}
