long long Slove(long long n)
{
    long long ret = 1;ret = n;
    for(vector<int>::size_type i = 0; i < prime.size(); ++i)
    {
    	long long tmp = prime[i] * prime[i] * prime[i];

        if(tmp > ret) break;
        while(ret % tmp == 0) ret /= tmp;
    }
    return ret;
}
int main()
{
    memset(isPrime, true, sizeof(isPrime));
    for(int i = 2; i <= 100000; ++i)
    {
        if(!isPrime[i])
            continue;
        prime.push_back(i);
        for(int j = i + i; j <= 100000; j += i)
            isPrime[j] = false;
    }
    int n;
