    for(int i = 1; i <= n; ++i)
        scanf("%lld", &arr[i]);
    int ans = 0;
    for(int i = 1; i <= n; ++i)
    {
        if(arr[i] == 1)
            ++cnt[1];
        else
        {
            long long a = Slove(arr[i]);
            long long b = Slove(a * a);

            if(b > 10000000000 || b < 0) {
            	ans++;
				continue;
			}
            if(a > b)
                swap(a, b);
            cnt[a]++;
            if(a != 1ll)
