  std::map<long long, int> counts;
  for (int i = 0; i < n; ++i) {
    std::cin >> numbers[i];
    long long copy = numbers[i];
    for (long long prime : primes) {
      long long cubed = prime * prime * prime;
      while ((numbers[i] % cubed) == 0) {
        numbers[i] /= cubed;
      }
      while ((copy % prime) == 0) {
        copy /= prime;
      }
    }
    if (copy != 1) {
      answer++;
      continue;
