      answer += (pr.second > 0);
      continue;
    }
    if (checked.find(copy) != checked.end()) {
      continue;
    }
    for (long long prime : primes) {
      if ((copy % (prime * prime)) == 0) {
        copy /= prime;
      } else if ((copy % prime) == 0) {
