typedef long long ll;

const int MAX_N=1e5,MAX_CURTS=1e4;
const ll MAX_S=1e10;

int N;
ll S[MAX_N];

bool pflg[MAX_CURTS+1];
vector<int> prime;

ll bsearch(ll x){
	ll l=2,r=x+1;
	while (l<r){
		ll mid=(l+r)/2;
		if (mid*mid==x){
			return mid;
		}
		if (mid*mid<x){
			l=mid+1;
		}else{
			r=mid;
		}
	}
	return -1;
}

ll pa(ll x){
	//xのペアを求める
	ll res=1;
	REP(i,(int)prime.size()){
		int p=prime[i];
		if (x%(p*p)==0){
			x/=p*p;
			res*=p;
		}else if (x%p==0){
			x/=p;
			res*=p*p;
		}
		if (res>MAX_S){
			return -1;
		}
	}
	ll sqrt=bsearch(x);
	if (sqrt==-1){
		res*=x*x;
	}else{
		res*=sqrt;
	}
	if (res>MAX_S){
		return -1;
	}else{
		return res;
	}
}

void sieve(){
	memset(pflg,true,sizeof(pflg));
	pflg[0]=pflg[1]=false;
	for (int i=2;(ll)i*i*i<=MAX_S;i++){
		if (!pflg[i]) continue;
		prime.push_back(i);
		for (int j=i*2;(ll)j*j*j<=MAX_S;j+=i){
			pflg[j]=false;
		}
	}
}

map<ll,int> mp;

int main(){
	scanf("%d",&N);
	REP(i,N){
		scanf("%lld",&S[i]);
	}
	sieve();
	REP(i,N){
		REP(j,(int)prime.size()){
			int p=prime[j];
			while(S[i]%(p*p*p)==0){
				S[i]/=p*p*p;
			}
		}
		mp[S[i]]++;
	}
	int ans=0;
	for(map<ll,int>::iterator ite=mp.begin();ite!=mp.end();ite++){
		if (ite->first==1){
			continue;
		}
		ll p=pa(ite->first);
		if (ite->second>mp[p]){
			ans+=ite->second;
		}else if (ite->second==mp[p] && ite->first<p){
			ans+=ite->second;
		}
	}
	if (mp[1]>0){
		ans++;
	}
	printf("%d\n",ans);
	return 0;
}

