  auto ps = sieve(2, 2154);
  for (int i = 0; i < n; ++i) {
    for (lint p : ps) {
      while (a[i] % (p * p * p) == 0) {
        a[i] /= p * p * p;
      }
    }
  }
  V<lint> cb;
  for (lint i = 2; i * i <= 1e10; ++i) {
    cb.push_back(i * i * i);
  }
  int res = 0;
  map<lint, int> mp;
  for (int i = 0; i < n; ++i) {
    if (a[i] == 1) {
      res = max(res, 1);
    } else {
      ++mp[a[i]];
    }
  }
  for (const auto& e : mp) {
    bool found = false;
    for (lint c : cb) {
      if (c % e.first == 0) {
        found = true;
        if (e.first > c / e.first) break;
        res += max(e.second, mp.count(c / e.first) ? mp[c / e.first] : 0);
        break;
      }
    }
    res += !found;
  }
  cout << res << '\n';
}

