void sieve() {
	for(int i=1 ; i<maxn ; i++) {
		pr[i]=true;
		cntdiv[i]=0;
		cntmul[i]=0;
		taken[i]=false;
	}
	pr[1]=false;
	for(int i=2 ; i<maxn ; i++) {
		if(pr[i]==true) {
			prime.push_back(i);
			for(int j=i*2 ; j<maxn ; j+=i) {
				pr[i]=false;
			}
		}
	}
