int mul(int n) {
	int ans=1;
	for(int i: prime) {
		if(n==1) return ans;
		if(n%i==0) {
			int cnt=0;
			while(n%i==0) {
				n/=i;
				cnt++;
			}
			if(cnt%3==1) ans*=(i*i);
			if(cnt%3==2) ans*=i;
		}
		if(ans>lim) return -1;
	}
	return ans;
}
int div(int n) {
	int ans=1;
	for(int i: prime) {
		if(n==1) return ans;
		if(n%i==0) {
			int cnt=0;
			while(n%i==0) {
				n/=i;
				cnt++;
			}
			if(cnt%3==1) ans*=i;
			if(cnt%3==2) ans*=(i*i);
		}
	}
	if(n>1) return -1;
	return ans;
}
