bool vis[233333];
map<int,int> mp,que;
int pr[10010],pnum;
vector <int> des[233333];
int work(long long w)
{
	long long p=1,q=1;
	for (int i=1;((pr[i]*pr[i]<=w)&&(i<=pnum));i++)
	{
		int js=0;
		while (w%pr[i]==0)
		{
			w/=pr[i];
			js++;
		}
		js%=3;
		if (js==1) {p*=pr[i];if ((double)q*pr[i]*pr[i]>1.1e12) {p=q=0;break;}q=q*pr[i]*pr[i];}
		else if (js==2) {p=p*pr[i]*pr[i];if ((double)q*pr[i]>1.1e12) {p=q=0;break;}q=q*pr[i];}
	}
	if (w!=1) {p*=w;if ((double)q*w*w>1.1e12) p=q=0;q=q*w*w;}
	if (p==0) return 0;
	mp[p]=q;mp[q]=p;//cout<<p<<' '<<q<<endl;
	return p;
}
pair<int,int> dfs(int s,int col=0)
{
	vis[s]=true;
	pair<int,int> p=make_pair((col==0)*num[s],(col==1)*num[s]);
	for (int k=0;k<des[s].size();k++) if (!vis[des[s][k]])
	{
		pair<int,int> q=dfs(des[s][k],col^1);
		p.first+=q.first;p.second+=q.second;
	}
	return p;
}
