		if (!err) pr[++pnum]=i;
	}//cerr<<pnum<<endl;
	int n,ans=0,gg=0;scanf("%d",&n);
	for (int i=1;i<=n;i++)
	{
		long long w;scanf("%lld",&w);
		w=work(w);
		if (w==0) {gg++;continue;}
		if (w==1) {ans=1;continue;}
		que[w]++;
	}
	ans+=gg;
	for (map<int,int>::iterator it=que.begin();it!=que.end();it++)
	{
		top++;
		st[top]=it->first;num[top]=it->second;
		it->second=top;
