const int MAXN = 100000 + 1000;
const int MAXM = 3000 + 10;

bool isp[MAXM];
int pri[MAXM], totp = 0;

void init()
{
	memset(isp, true, sizeof(isp));
	isp[0] = isp[1] = false;
	for(int i = 2; i < MAXM; i++)
	{
		if(isp[i])
			pri[++totp] = i;
		for(int j = 1; j <= totp && i * pri[j] < MAXM; j++)
		{
			isp[i * pri[j]] = false;
			if(i % pri[j] == 0)
				break;
		}
	}
}

bool is_square(long long x)
{
	int y = sqrt(x) + 0.5;
	return (long long)y * y == x;
}

int n;
long long a[MAXN];
set<long long> S;
map<long long, int> cnt1, cnt2;

void work()
{
	for(int i = 1; i <= n; i++)
	{
		long long val1 = 1, val2 = 1;
		long long tmp = a[i];
		for(int j = 1; j <= totp; j++)
			if(tmp % pri[j] == 0)
			{
				int cnt = 0;
				while(tmp % pri[j] == 0)
					tmp /= pri[j], cnt++;
				cnt %= 3;
				if(cnt == 1)
					val1 *= pri[j], val2 *= pri[j] * pri[j];
				else if(cnt == 2)
					val2 *= pri[j], val1 *= pri[j] * pri[j];
			}
		val1 *= tmp;
		if(is_square(tmp))
			val2 *= (int)(sqrt(tmp) + 0.5);
		else if((double)val2 * tmp * tmp < 1e18)
			val2 *= tmp * tmp;
		else
			val2 = 0;
		S.insert(val1), cnt1[val1]++, cnt2[val2]++;
	}
	int ans = n, rem = 0;
	if(S.count(1))
		ans -= cnt1[1], ans += 1, S.erase(1);
	for(set<long long>::iterator it = S.begin(); it != S.end(); it++)
	{
		long long val = *it;
		// cerr << val << ' ' << cnt1[val] << ' ' << cnt2[val] << endl;
		rem += min(cnt1[val], cnt2[val]);
	}
	ans = ans - rem / 2;
	cout << ans << endl;
}

