#include "bits/stdc++.h"
using namespace std;

const int maxn = 100005;
using ll = long long;

ll a[maxn];
map<ll, int> mp;
vector<ll> primes;
vector<bool> mark(maxn, 0);

void sieve(){
  mark[1] = 1;
  for(int i = 2; i * i < maxn; i++){
    for(int j = 2; i * j < maxn; j++){
      mark[i * j] = 1;
    }
  }
  primes.push_back(2);
  for(int i = 3; i < maxn; i += 2){
    if(mark[i] == 0){
      primes.push_back(i);
    }
  }
}

inline ll poww(ll x, int c){
  if(c == 1)return x;
  if(c == 0)return 1;
  if(c == 2)return x * x;
  return x;
}

ll fact(ll x){
  int p = 0;
  ll xx = 1;
  if(x % 2 == 0){
    while(x % 2 == 0){
      ++p;
      x /= 2;
    }
    p %= 3;
    xx = poww(2, p);
  }
  int sz = primes.size();
  for(int i = 1; primes[i] * primes[i] < x && i < sz; i++){
    if(x % primes[i] == 0){
      p = 0;
      while(x % primes[i]){
        ++p;
        x /= primes[i];
      }
      p %= 3;
      if(p != 0){
        xx *= poww(primes[i], p);
      }
    }
  }
  if(x > 1){
    xx *= x; 
  }
  return xx;
}

ll inv(ll x){
  ll xx = 1;
  int p = 0;
  while(x % 2 == 0){
    ++p;
    x /= 2;
  }
  p %= 3;
  if(p != 0){
    xx *= poww(2, 3 - p);
  }
  for(int i = 1; primes[i] * primes[i] < x; i++){
    if(x % primes[i] == 0){
      p = 0;
      while(x % primes[i] == 0){
        ++p;
        x /= primes[i];
      }
      p %= 3;
      if(p != 0){
        xx *= poww(primes[i], 3 - p);
      }
    }
  }
  if(x > 1){
    xx *= poww(x, 2);
  }
  return xx;
}

int main(int argc, char const *argv[])
{
//  freopen("in.txt", "r", stdin);
  int n;
  scanf("%d", &n);
  sieve();
  map<ll, ll> invv;
  set<ll> ms;
  for(int i = 1; i <= n; i++){
    scanf("%lld", &a[i]);
    a[i] = fact(a[i]);
    mp[a[i]]++;
    if(invv.find(a[i]) == invv.end()){
      invv[a[i]] = inv(a[i]);
    }
    ms.insert(a[i]);
  }
  int ans = n;
  for(auto i : ms){
    ll x = invv[i];
    int cnt = mp[i], cnt1 = mp[x];
    if(cnt > cnt1){
      ans -= cnt1;
    }else {
      ans -= cnt;
    }
    if(x == i && cnt > 1)ans++;
    mp[x] = mp[i] = 0;
  }
  printf("%d\n", ans);

  return 0;
}

