void calc_primes() {
    const size_t size = 1e5 + 10;
    bool used[size] = {};
    for(ll i = 2; i < size; i++) {
        if(used[i]) continue;
        primes.push_back(i);
        for(ll j = 1; i * j < size; j++) used[i * j] = true;
    }
}

int main() {
    calc_primes();
    ll N;
    cin >> N;
    ll ans = 0;
    map<ll, ll> cnt;
    map<ll, ll> anti;
    while(N--) {
        ll e;
        ll save_e = 1;
        cin >> e;
        ll anti_num = 1;
        for(ll p : primes) {
            ll cube_p = p * p * p;
            while(e % cube_p == 0) e /= cube_p;
            ll cnt_div = 0;
            while(e % p == 0) {
                e /= p;
                cnt_div++;
            }
            for(ll i = 0; i < cnt_div; i++) save_e *= p;
            ll anti_cnt_div = (3 - cnt_div) % 3;
            for(ll i = 0; i < anti_cnt_div; i++) anti_num *= p;
        }
        if(e != 1) {
            ans++;
            continue;
        }
        DEBUG(make_tuple(e, anti_num));
        anti[save_e] = anti_num;
        cnt[save_e]++;
    }
