        ll anti_num = anti[num];
        DEBUG(make_tuple(num, anti_num, cnt_v));
        if(anti_num < num) continue;
        auto ite = cnt.find(anti_num);
        if(num == anti_num) ans++;
        else ans += max(cnt_v, (ite == cnt.end() ? 0 : ite->second));
    }
    cout << ans << endl;
    return 0;
}

