	scanf("%d",&n);
	vector<long long> aa(n);

	for(int i=0;i<n;i++)scanf("%lld",&aa[i]);

	vector<numtype> a(n);
	map<numtype,int> cnt;
	for(int i=0;i<n;i++)a[i]=normalize(aa[i]);
	for(int i=0;i<n;i++)cnt[a[i]]++;

	//for(int i=0;i<n;i++)printf("%lld %lld\n",a[i].first,a[i].second);

	int ans=0;

	for(map<numtype,int>::iterator ite=cnt.begin();ite!=cnt.end();ite++){
		numtype d=(*ite).first;
		if(istriv(d)){
			ans++;
		}else{
			numtype dd=inv(d);
			if(cnt.count(dd)==0 || d<dd){
				ans+=max(cnt[d],cnt[dd]);
			}
		}
	}
	printf("%lld\n",ans);
}

