        bool add=true;
        for (int j=0; j<primes.size(); j++) if (i%primes[j]==0) {
            add=false;
            break;
        }
        if (add) primes.push_back(i);
    }

    //divided number + overflow
    vector<ll> divs(primes.size()+1);
    map<vector<ll>, int> mmap;
    int n; cin>>n;

    for (int i=0; i<n; i++) {
        ll num; cin>>num;
        for (int k=0; k<divs.size(); k++) divs[k]=0;
        for (int k=0; k<primes.size(); k++)
            while (num%primes[k]==0) divs[k]=(divs[k]+1)%3, num/=primes[k];
        if (num!=1) divs.back()=1;

        mmap[divs]++;
    }

    map<vector<ll>, int>::iterator it;
    int ans=0;
    for (it=mmap.begin(); it!=mmap.end(); it++) {
        for (int i=0; i<divs.size(); i++) divs[i]=(3-(it->first)[i])%3;

        map<vector<ll>, int>::iterator it2=mmap.find(divs);
        // no twin found
        if (it2==mmap.end()) ans+=it->second;
        else {
            //take bigger
            if ((it->second)>(it2->second)) ans+=it->second;
            // cant decide which is bigger
            if ((it->second)==(it2->second)) {
                //both cubes, take only one
                if (it==it2) ans+=1;
                //decide if my(it) vector is bigger than their(it2)
                else if (bigger(it->first, it2->first)) ans+=it->second;
            }
        }
    }

    cout<<ans<<endl;
    return 0;
}

