template<class T = ll> T lcm(T a, T b) {return a/gcd(a, b)*b;}

/// g:gcd(a, b), ax+by=g
template<class T> struct EG { T g, x, y; };

template<class T>
EG<T> ext_gcd(T a, T b) {
    if (b==0) {
        return EG<T>{a, 1, 0};
    } else {
        auto e = ext_gcd(b, a%b);
        return EG<T>{e.g, e.y, e.x-a/b*e.y};
    }
}

template<class T>
T pow(T x, ll n, T md) {
    T r = 1;
    while (n) {
        if (n & 1) r = (r*x)%md;
        x = (x*x)%md;
        n >>= 1;
    }
    return r;
}


