bool isPrime(ll n, int k = 20) {
    if (n <= 1) return false;
    if (n == 2) return true;
    if (n % 2 == 0) return false;
    ll d = n-1;
    while (d % 2 == 0) d /= 2;
    for (int i = 0; i < 20; i++) {
        ll a = rand_int(1, n), t = d;
        ll y = pow_mod(a, t, n);
        while (t != n-1 && y != 1 && y != n-1) {
            y = (y*y) % n;
            t <<= 1;
        }
        if (y != n-1 && t % 2 == 0) {
            return false;
        }
    }
    return true;
}

