typedef long long LL;
const int N = 1e5 + 5;

int n, ans;
LL a[N], c[N], cb[N], id[N], _tmp[N];
int prime[N], Index, vis[N];
unordered_map <LL, LL> M; //multiset会保留多个相同的迭代器!! 在本题中不如map实现

void inv_per(LL A[], LL p[]) {
    for(int i = 1; i <= n; i++) _tmp[i] = A[p[i]];
    for(int i = 1; i <= n; i++) A[i] = _tmp[i];
}

void init() {
    scanf("%d", &n);
    for(int i = 1; i < N; i++) cb[i] = 1ll * i * i * i;
    for(int i = 2; i < N; i++) {
        if(vis[i]) continue;
        prime[++Index] = i;
        for(int j = i + i; j < N; j += i) vis[j] = true;
    }
    for(int i = 1; i <= n; i++) {
        scanf("%lld", &a[i]);
        c[i] = 1;
        LL x = a[i];
        for(int j = 1; j <= Index; j++) {
            int p = prime[j];
            if(x < p) break;
            while(x % cb[p] == 0) x /= cb[p], a[i] /= cb[p];
            if(x % p == 0) c[i] *= p;
        }
    }
    for(int i = 1; i <= n; i++) id[i] = i;
    sort(id + 1, id + n + 1, [](int x, int y){ return c[x] < c[y]; });
    inv_per(a, id), inv_per(c, id);
    c[n + 1] = 0x3f3f3f3f;
    for(int i = 1; i <= n + 1; i++) {
        if(c[i] != c[i - 1]) {
            LL k = c[i - 1] * c[i - 1] * c[i - 1], x, y;
            if(k == 1) ans -= M[1], ans ++ ;
            else {
                for(auto tmp : M) {
                    x = tmp.first;
                    y = k / x;
                    if(x < y) ans -= min(M[x], M[y]);
                }
            }
            M.clear();
        }
        M[a[i]] ++ ;
    }
    ans += n;
    cout << ans << endl;
}

int main() {
    init();
    return 0;
}

