#include <bits/stdc++.h>
using namespace std;
long long a[100010];
long long b[100010];

long long Power(long long x, int q) {
	long long ans = 1;
	while(q--) {
		ans *= x;
	}
	return ans;
}

pair <long long, long long> func(long long x) {
	long long p = 1;
	long long q = 1;
	for(long long i = 2; i * i <= x; i++) {
		int cnt = 0;
		while(x % i == 0) {
			x /= i;
			++cnt;
		}
		cnt %= 3;
		p *= Power(i, cnt);
		q *= Power(i, (3 - cnt) % 3);
	}
	if(x > 1) {
		p *= Power(x, 1);
		q *= Power(x, 2);
	}
	return make_pair(p, q); 
}
int main(int argc, char const *argv[])
{
	int n;
	scanf("%d", &n);
	map <long long, int> cnt;
	set <pair <long long, long long>> s;
	for(int i = 1; i <= n; i+=1) {
		long long x;
		scanf("%lld", &x);
		auto y = func(x);
		long long P = y.first;
		long long Q = y.second;
		cnt[P] += 1;
		if(P > Q) swap(P, Q);
		s.insert(make_pair(P, Q)); 
	}
	int ans = 0;
	for(auto i : s) {
		if(i.first == i.second) {
			++ans;
		} else {
			ans += max(cnt[i.first], cnt[i.second]);
		}
	}
	printf("%d\n", ans);
	return 0;
}

