        for (;'0' <= c && c <= '9'; c = xchar()) x = x * 10 + c - '0';
        return x;
	  }
	  inline long long xull() {
		  int c = xchar();
		  long long x = 0;
		  while (c <= 32 && ~c) c = xchar();
		  if (c == -1) return -1;
		  for (;'0' <= c && c <= '9'; c = xchar()) x = x * 10 + c - '0';
		  return x;
	  }
	  inline int xint() {
		  int s = 1, c = xchar(), x = 0;
		  while (c <= 32) c = xchar();
		  if (c == '-') s = -1, c = xchar();
		  for (; '0' <= c && c <= '9'; c = xchar()) x = x * 10 + c - '0';
		  return x * s;
	  }
	  inline void xstring(char *s) {
		  int c = xchar();
		  while (c <= 32) c = xchar();
		  for(; c > 32; c = xchar()) *s++ = c;
		  *s = 0;
	  }
	  inline void wchar(int x) {
		  if (wpos == S) fwrite(wbuf, 1, S, stdout), wpos = 0;
		  wbuf[wpos ++] = x;
	  }
	  inline void wint(int x) {
		  if (x < 0) wchar('-'), x = -x;

		  char s[24];
		  int n = 0;
		  while (x || !n) s[n ++] = '0' + x % 10, x /= 10;
		  while (n--) wchar(s[n]);
	  }
	  inline void wstring(const char *s) {
		  while (*s) wchar(*s++);
	  }
	  ~FastIO() {
