int sieve(int n) {
	int p = 0;
	for (int i = 0; i <= n; i++){
		is_prime[i] = true; 
	}
	is_prime[0] = false;
	is_prime[1] = false;
	for (int i = 2; i <= n; i++) {
		if (is_prime[i]) {
			prime[p++] = i;
			//cout << "p = " << p << " i = " << i << endl;
			for (int j = 2 * i; j <= n; j += i){
				is_prime[j] = false;
			}
		} 
	}
	return p; 
}

