ull xor64(ull y) {
    y = y ^ (y<<13);
    y = y ^ (y>>7);
    y = y ^ (y<<17);
    return y;
}

ll pollard(ll n) {
    ll x = 2, y = 2, d = 1;
    int c = 0;
    constexpr int C = 30;
    while (c < C and d == 1) {
        x = xor64(x)%n;
        y = xor64(xor64(y)%n)%n;
        d = gcd(abs(x-y), n);
        c++;
    }
    if (c == C) return -2;
    if (d == n) return -1;
    return d;
}


