        return factsmall(n);
    }
    if (u == -1) {
        mp[n]++;
        return mp;
    }
    auto mp1 = factc(u);
    auto mp2 = factc(n/u);
    for (auto p: mp1) {
        mp[p.first] += p.second;
    }
    for (auto p: mp2) {
        mp[p.first] += p.second;
    }
    return mp;
}

