typedef long long LL;
int n,m,tot,prm[10000],ans;
LL a[100100];
bool flag[100100];
struct data
{
    LL x;
    bool flag;
    bool operator<(const data &t) const
    {
        return x<t.x;
    }
} b[100100];

LL getLL()
{
    char ch;
    while (!isdigit(ch=getchar()));
    LL x=ch-'0';
    for (; isdigit(ch=getchar()); x=x*10+ch-'0');
    return x;
}

void solve(LL x)
{
    LL u=1,v=1;
    for (int i=1; LL(prm[i])*prm[i]<=x; ++i)
    {
        int p=prm[i];
        if (!(x%p))
        {
            int cnt=0;
            for (; !(x%p); x/=p,(++cnt)%=3);
            repu(i,1,cnt)
                u*=p;
            repu(i,1,(3-cnt)%3)
                v=(1LL<<60)/v<p?1LL<<60:v*p;
        }
    }
    if (x>1)
        u*=x,v=1LL<<60/x/x<v?1LL<<60:v*x*x;
    if (u<v)
        b[++m]=(data){u,0};
    else
        b[++m]=(data){v,1};
}

int main()
{
    repu(i,2,1e5)
        if (!flag[i])
        {
            prm[++tot]=i;
            for (int j=i*2; j<=1e5; flag[j]=1,j+=i);
        }
    prm[tot+1]=1e6;
    n=getLL();
    repu(i,1,n)
        solve(getLL());
    sort(b+1,b+1+m);
    for (int i=1,j; i<=m; i=j)
    {
        int cnt=0;
        for (j=i; j<=m && b[i].x==b[j].x; cnt+=b[j].flag,++j);
        ans+=b[i].x>1?max(cnt,j-i-cnt):1;
    }
    printf("%d\n",max(ans,1));
    return 0;
}

