	}	
	if(t > 1){
		x *= t;
	}
	return x;
}

ll pairs(ll t){
	ll x = 1LL;
	for(int i = 0, j = 0;pr[i] * pr[i] <= t;i++){
		//cout << pr[i] << "\n";
		j = 0;
		while(t % pr[i] == 0){
			t /= pr[i];
			j++;
		}
		if(j % 3 == 2){
			x *= pr[i];
		}
		else if(j % 3 == 1){
			x *= pr[i] * pr[i];
		}
	}	
	if(t > 1){
		x *= t * t;
	}
	return x;
}

