struct Problem {

	void Solve() {
		vector<ULL> prime = { 2 };
		for(ULL i = 2; i < 100000; i++) {
			rep(j, prime.size()) {
				if (prime[j] * prime[j] > i) { prime.push_back(i); break; }
				if (i % prime[j] == 0) break;
			}
		}
		vector<ULL> cbPrime;
		rep(i, prime.size()) {
			ULL buf = prime[i] * prime[i] * prime[i];
			if (buf > 10000000000ull) break;
			cbPrime.push_back(buf);
		}
		map<ULL, UL> sq;
		rep(i, 100000) sq[i*i] = i;
		UL N; cin >> N;
		vector<ULL> S(N); rep(i, N) cin >> S[i];

		map<ULL, pair<UL, UL>> mp;

		rep(i, N) {
			rep(j, cbPrime.size()) {
				if (S[i] < cbPrime[j]) break;
				while (S[i] % cbPrime[j] == 0) S[i] /= cbPrime[j];
			}
			ULL tg; bool bsq;
			if (sq.count(S[i])) { tg = sq[S[i]]; bsq = true; }
			else { tg = S[i]; bsq = false; }
			if (mp.count(tg) == 0) mp[tg] = { 0, 0 };
			if (bsq) mp[tg].second++;
			else mp[tg].first++;
		}

		ULL ans = 0;
		for (auto i : mp) {
			if (i.first == 1) {
				ans++; continue;
			}
			ans += max(i.second.first, i.second.second);
		}
		cout << ans << endl;
	}


	Problem();
};
