void sieve(int size) {
	sieve_size = size;
	bs.set(); bs[0] = bs[1] = 0;
  	for (ll i = 2; i <= sieve_size; ++i) if (bs[i]) {
		for (ll j = i * i; j <= sieve_size; j += i) bs[j] = 0;
		pr.push_back(i);
	}
}

vector<ii> factorize(ll N) {
	vector<ii> factors;
  	ll idx = 0, pf = pr[idx];
	while (N != 1 && pf * pf <= N) {
		if (N % pf == 0) {
			factors.emplace_back(pf, 0);
			while (N % pf == 0) { N /= pf; ++factors.back().s; }
			if (factors.back().s % 3 == 0) factors.pop_back();
		}
		pf = pr[++idx];	
  	}
	if (N != 1) factors.emplace_back(N, 1);
	return factors;
}

