void init() {
	for(int i=2;i<=MAX;i++) {
		if( !is_prm[i] )
			prm[++pcnt] = i;
		for(int j=1;i*prm[j]<=MAX;j++) {
			is_prm[i*prm[j]] = true;
			if( i % prm[j] == 0 ) break;
		}
	}
}
ll s[MAXN + 5], a[MAXN + 5], b[MAXN + 5];
ll IsSqr(ll x) {
	ll le = 1, ri = 100000;
	while( le < ri ) {
		ll mid = (le + ri) >> 1;
		if( mid * mid >= x ) ri = mid;
		else le = mid + 1;
	}
	return (ri * ri == x) ? ri : 0;
}
int siz[2*MAXN + 5];
map<ll, int>mp;
int main() {
	init(); int N;
	scanf("%d", &N);
	int ans = 0, flag = false;
	for(int i=1;i<=N;i++) {
		a[i] = b[i] = 1;
		scanf("%lld", &s[i]);
		for(int j=1;j<=pcnt;j++) {
			int cnt = 0;
			while( s[i] % prm[j] == 0 ) {
				cnt++;
				s[i] /= prm[j];
			}
			cnt %= 3;
			if( cnt == 1 ) {
				a[i] *= prm[j];
				b[i] *= prm[j] * prm[j];
			}
			else if( cnt == 2 ) {
				a[i] *= prm[j] * prm[j];
				b[i] *= prm[j];
			}
		}
		if( IsSqr(s[i]) ) {
			a[i] *= s[i];
			b[i] *= IsSqr(s[i]);
		}
		else {
			a[i] *= s[i];
			b[i] *= s[i] * s[i];
		}
		if( !flag && a[i] == 1 && b[i] == 1 )
			flag = true;
	}
	for(int i=1;i<=N;i++) {
		if( a[i] == 1 && b[i] == 1 ) continue;
		if( mp.count(a[i]) )
			siz[mp[a[i]]]++;
		else {
			mp[a[i]] = i;
			mp[b[i]] = i+N;
			siz[i]++;
		}
	}
	for(int i=1;i<=N;i++) {
		if( mp[a[i]] == i )
			ans += max(siz[i], siz[i+N]);
	}
	if( flag ) ans++;
	printf("%d\n", ans);
}

#include <iostream>
#include <vector>
#include <map>
#include <bitset>
#include <cmath>

using namespace std;

const int kMax = 2200;

bitset < kMax > used;

void Init(vector < int > &prime) {

  int index = 0;
  for (int pr = 2; pr < kMax; pr ++) {
    if (used[pr]) {
      continue;
    }
    prime[++ index] = pr;

    for (int j = pr * 2; j < kMax; j += pr) {
      used[j] = true;
    }
  }

  prime[0] = index;
}

int main(int argc, char const *argv[]) {

  vector < int > prime(kMax);
  Init(prime);

  int n;
  cin >> n;

  map < long long, long long > hash;
  map < long long, long long > comp;
  vector < long long > element(n + 1);

  for (int i = 1; i <= n; i ++) {
    cin >> element[i];
    long long k = element[i];
    hash[k] = 1ll;
    comp[k] = 1ll;

    if (k == 1ll) {
      continue;
    }

    for (int j = 1; j <= prime[0]; j ++) {
      if (k % prime[j] != 0) {
        continue;
      }

      int elExp = 0;
      while (k % prime[j] == 0) {
        elExp ++;
        k /= prime[j];
      }

      elExp %= 3;
      if (elExp == 0) {
        continue;
      }

      if (elExp == 1) {
        hash[element[i]] *= 1ll * prime[j];
        comp[element[i]] *= 1ll * prime[j] * prime[j];
      }
      else {
        hash[element[i]] *= 1ll * prime[j] * prime[j];  
        comp[element[i]] *= 1ll * prime[j];
      }
    }

    if (k != 1) {
      hash[element[i]] *= 1ll * k;
      double sq_root = sqrt(k);
      if (sq_root * sq_root == (double) k) {
        comp[element[i]] *= 1ll * (int) sq_root;
      }
      else {
        comp[element[i]] *= 1ll * k * k;
      }
    }
  }


  map < long long, int > frecv;
  for (int i = 1; i <= n; i ++) {
    frecv[hash[element[i]]] ++;
  }

  int to_remove = 0;
  for (auto &x : frecv) {
    if (x.second == 0) {
      continue;
    }

    if (x.first == 1) {
      to_remove += x.second - 1;
      x.second = 0;
      continue;
    }

    int k = x.first;
    int c = frecv[comp[k]];
    if (c == 0) {
      continue;
    }

    if (x.second >= c) {
      to_remove += c;
    }
    else {
      to_remove += x.second;
    }
    x.second = 0;
    frecv[comp[k]] = 0;
  }

  cout << n - to_remove << '\n';
}

