#include <bits/stdc++.h>

using namespace std;
#define ll long long
#define N 100001

bool isNotPrime[N];
void solve() {
  int n;scanf("%d ", &n);
  int cubic = 0,ret = 0;
  set<ll> sq;
  const ll maxi = 1e10;
  for(ll i=1;i*i<=maxi;++i) {
    sq.insert(i*i);
  }
  vector<int> prime;
  set<ll> cubicList;
  cubicList.insert(1);
  for(int i=2;i<N;++i) {
    if(!isNotPrime[i]) {
      ll x = i;
      x *=i;
      x *=i;
      if(x<=maxi) {
        prime.push_back(i);
        cubicList.insert(x);
      } else {
        break;
      }
      for(int j=i+i;j<N;j+=i) {
        isNotPrime[j] = true;
      }
    }
  }
  map<ll,ll> op;
  map<ll,ll> pcount;
  for(int i=0;i<n;++i) {
    ll in;scanf("%lld ", &in);
    if(cubicList.count(in)) {
      cubic = 1;
      continue;
    } else {
      ll mn=1,mp=1;
      ll cur = in;
      for(int j = 0;j<prime.size();++j) {
        if(cur%prime[j]==0) {
          int cc = 0;
          while(cur%prime[j]==0) {
            ++cc;
            cur/= prime[j];
          }
          cc = cc%3;
          int pp = (3-cc)%3;
          for(int k=0;k<cc;++k) {
            mn *= prime[j];
          }
          for(int k = 0;k<pp;++k) {
            mp *= prime[j];
          }
        }
      }
      mn *= cur;
      if(sq.count(cur)) {
        ll x = sqrt(cur);
        if(x*x!=cur) {
          ++x;
        }
        assert(x*x==cur);
        mp *= x;
      } else {
        mp *= cur;
        mp *= cur;
      }
      op[mn] = mp;
      ++pcount[mn];
    }
  }
  for(map<ll,ll>::iterator it = op.begin();it!=op.end();++it) {
    ll x = it->first, y= it->second;
    if(x<y) {
      ret += max(pcount[x],pcount[y]);
    }
  }
  printf("%d\n", ret+cubic);
}
int main() {
    //freopen("input.txt","r",stdin);
    solve();
    return 0;
}

