ll dv(ll x){

  for(int i=2;; i++){

    ll t=i*i*i;
    if(t>x) break;
    while(x%t==0){
      x/=t;
    }

  }

  return x;

}

int tp(ll x){

  ll A=1,B=1; bool f1=0,f2=0;

  for(ll i=2;; i++){

    int cnt=0;

    if(x==1) break;
    while(x%i==0){
      x/=i;
      cnt++;
    }

    if(cnt==1){ A*=i; f1=1;}
    if(cnt==2){ B*=i*i; f2=1;}

  }

  if(f1&&!f2) return 1;
  if(!f1&&f2) return 2;
  if(f1&&f2){
    if(A*B<A*A*sqrt(B)) return 3;
    else return 4;
  }
  if(!f1&&!f2) return 5;

}

ll pr(ll x){

  ll A=1,B=1; bool f1=0,f2=0;

  for(ll i=2;; i++){

    int cnt=0;

    if(x==1) break;
    while(x%i==0){
      x/=i;
      cnt++;
    }

    if(cnt==1){ A*=i; f1=1;}
    if(cnt==2){ B*=i*i; f2=1;}

  }

  if(f1&&!f2) return A*A;
  if(!f1&&f2) return sqrt(B);
  if(f1&&f2) return A*A*sqrt(B);

}



