		auto paf = pf;
		for (auto &p : paf)p.second = (3 - p.second) % 3;
		long long a = f(pf), b=f(paf);
		++cnt[a];
		pa[a] = b;
	}
	int ans = 0;
	for (auto p : cnt) {
		long long a = p.first, b = pa[a];
		int c = cnt.find(b)==cnt.end()? 0:cnt[b];
		if (a == 1) {
			ans++;
		}
