vector<int> generate_primes() {
    vector<int> primes;
    vector<int> is_prime(5000, true);
    is_prime[0] = 0;
    is_prime[1] = 0;
    rep(i, is_prime.size()) {
        if(is_prime[i]) {
            primes.push_back(i);
            for(int j = i * 2; j < is_prime.size(); j += i) {
                is_prime[j] = 0;
            }
        }
    }
    return primes;
}

int main() {
    int N; cin >> N;
    vector<ll> S(N); rep(i, N) cin >> S[i];

    auto primes = generate_primes();

    map<map<int, int>, vector<int>> mp;
    bool have_one = false;
    rep(i, N) {
        if(S[i] == 1) {
            have_one = true;
            continue;
        }
        map<int, int> factor;
        for(ll p : primes) {
            if(S[i] % p == 0) {
                int cnt = 0;
                while(S[i] > 1 and S[i] % p == 0) {
                    S[i] /= p;
                    cnt++;
                }
                if(cnt % 3 != 0) factor[p] = cnt % 3;
            }
            if(S[i] == 1) break;
        }
        //cerr << "!!" << " ";
        if(S[i] != 1) factor[S[i]] = 1;
        if(factor.size()) {
            auto &m = mp[factor];
            if(factor.begin()->second == 2) {
                for(auto &p : factor) p.second = (3 - p.second) % 3;
                if(m.size() == 0) m.resize(2);
                m[1]++;
            } else {
                if(m.size() == 0) m.resize(2);
                m[0]++;
            }
        } else {
            have_one = true;
        }
    }
    int ans = 0;
    cerr << mp.size() << endl;
    for(auto p : mp) {        
        ans += max(p.second[0], p.second[1]);
    }
    cout << ans + have_one << endl;
    return 0;
}

#include <bits/stdc++.h>

using namespace std;

#define N 100000
#define ll long long

int n, a[N + 5], cnt, prime[N + 5], vis[N + 5], ans;
map<ll, int> rp, p2;
map<ll, ll> match;

void sieve() {
    vis[1] = 1;
    for (int i = 2; i <= N; ++i) {
        if (!vis[i])
            prime[++cnt] = i;
        for (int j = 1; j <= cnt && i * prime[j] <= N; ++j) {
            vis[i * prime[j]] = 1;
            if (i % prime[j] == 0)
                break;
        }
    }
    p2[1] = 1;
    for (int i = 1; i <= cnt; ++i)
        p2[1LL * prime[i] * prime[i]] = prime[i];
}

void pre() {
    // 预处理norm
    for (int i = 1; i <= n; ++i) {
        ll x = a[i], y = 1, z = 1;
        for (int j = 1; j <= 2200; ++j) {
            if (x % prime[j]) continue;
            int cnt = 0;
            while (x % prime[j] == 0) {
                x /= prime[j];
                cnt++;
            }
            cnt %= 3;
            if (cnt == 1) y = y * prime[j], z = z * prime[j] * prime[j];
            else if(cnt == 2) y = y * prime[j] * prime[j], z = z * prime[j];
        }
        rp[y * x]++;
        if (p2.count(x))
            match[y * x] = z * p2[x];
        else
            match[y * x] = z * x * x;
    }
}

void solve() {
    auto it = match.begin();
    if (it->first == 1) {
        ans++;
        it++;
    }
    while (it != match.end()) {
        if (rp.count(it->second)) {
            if (it->second > it->first)
                ans += max(rp[it->first], rp[it->second]);
        }
        else
            ans += rp[it->first];
        it++;
    }
}

int main() {
    sieve();
    scanf("%d", &n);
    for (int i = 1; i <= n; ++i)
        scanf("%lld", &a[i]);
    pre();
    solve();
    printf("%d\n", ans);
    return 0;
}

