void init()
{
    memset(isp, 1, sizeof isp);
    isp[1] = 0;
    tot = 0;
    for(int i = 2; i < MAXM; i++)
        if(isp[i])
        {
            p[++tot] = i;
            for(int j = 2 * i; j < MAXM; j += i)
                isp[j] = 0;
        }
}
void solve(int x, int k)
{
    a[k] = b[k] = 1;
    for(int i = 1; i <= tot && p[i]*p[i]*p[i] <= x; i++)
    {
        if(x % p[i] == 0)
        {
            int cnt = 0;
            while(x % p[i] == 0)
            {
                x /= p[i];
                cnt++;
            }
            if(cnt % 3 == 2)
            {
                a[k] *= p[i] * p[i];
                b[k] *= p[i];
            }
            else if(cnt % 3 == 1)
            {
                a[k] *= p[i];
                b[k] *= p[i] * p[i];
            }
        }
    }
    if(x > 1)
    {
        ll temp = sqrt(x);
        if(temp * temp == x)    //暴力开方再乘起来
            b[k] *= temp;
        else 
            b[k] *= x * x;
    }
    a[k] *= x;
}
int main()
{
    init();
    cin >> n;
    for(int i = 1; i <= n; i++)
    {
        ll x;
        scanf("%lld", &x);
        solve(x, i);
        sum[a[i]]++;
    }
    ll ans = 0;
    for(int i = 1; i <= n; i++)
    {
        if(sum[a[i]] == 0)    continue;
        if(a[i] == b[i])
            ans++;
        else
        {
            ans += max(sum[a[i]], sum[b[i]]);
            sum[b[i]] = 0;
        }
        sum[a[i]] = 0;
    }
    printf("%lld\n", ans);
    return 0;
}

