typedef pair<__int128, __int128> P2;
map<P2, ll> mp;

ll square(ll x) {
  // lb * lb <= x
  ll lb = 1, ub = sqrt(x) + 1000;
  while (lb + 1 < ub) {
    ll mid = (lb + ub) / 2;
    if (mid * mid <= x) lb = mid;
    else ub = mid;
  }
  if (lb * lb == x) return lb;
  return -1;
}

int main() {
