			if(x % p[j])    continue;
			int exp = 0;
			while(x % p[j] == 0)    {
				exp = (exp + 1) % 3;
				x /= p[j];
			}
			if(!exp)    continue;
			y *= p[j];
			z *= p[j];
			if(exp < 2) z *= p[j];
			else        y *= p[j];
		}
		if(x > 1)   {
			int t = sqrt(x);
