ll stupid_pow(ll base, int e) {
	ll ans=1;
	while (e>0) ans*=base, e--;
	return ans;
}

ll compute_norm(ll n) {
	ll i=1, ans=n;
	while (stupid_pow(i, 3)<=n) {
		ll tmp=stupid_pow(i, 3);
		if (n%tmp==0) ans=n/tmp;
		i++;
	}
	return ans;
}

bool is_square(ll n, int left, int right) {
	if (left+1==right) return primes[left]*primes[left]==n;

	int mid=(left+right)/2;
	if (primes[mid]*primes[mid]<=n) return is_square(n, mid, right);
	else return is_square(n, left, mid);
}

ll compute_pair(ll n) {
	ll ans=1;
	for (int i=0; primes[i]<2500; i++) {
		if (n%primes[i]!=0) continue;
		int e=0;
		while (n%primes[i]==0) e=(3+e-1)%3, n/=primes[i];
		ans*=stupid_pow(primes[i], e);
	}
	if (is_square(n, 0, primes.size())) ans*=sqrt(n);
	else ans*=n*n;
	return ans;
}

