}

const int N = 110000;

bool pp[N];
int primes[N], primesCnt;

void sieve() {
	for (int i = 2; i < N; i++) {
		if (!pp[i]) {
			for (int j = i + i; j < N; j += i) {
				pp[j] = true;
			}
		}
	}
	for (int i = 2; i < N; i++) {
		if (!pp[i]) {
			primes[primesCnt++] = i;
		}
	}
}

map<ll, int> cnt;
map<pair<ll, ll>, int> cnt2;
ll p[60], q[60], zz;

void getPrimeDivisors(ll x) {
	zz = 0;
	for (int i = 0; 1LL * primes[i] * primes[i] <= x; i++) {
		int cur = primes[i];
		if (x % cur == 0) {
			int z = 0;
			while (x % cur == 0) {
				++z;
				x /= cur;
			}
			p[zz] = cur;
			q[zz] = z;
			zz++;
		}
	}
	if (x != 1) {
		p[zz] = x;
		q[zz] = 1;
		zz++;
	}
}

pair<ll, ll> normalize(ll x) {
	getPrimeDivisors(x);
	ll prod = 1, prod2 = 1;
	for (int i = 0; i < zz; i++) {
		int tmp = q[i];
		q[i] %= 3;
		while (q[i]--) {
			prod *= p[i];
		}
		q[i] = tmp;
		q[i] = (3 - q[i] % 3) % 3;
		while (q[i]--) {
			if (prod2 != -1 && ll(1e12) / prod2 / p[i] > 0) prod2 *= p[i];
		}
	}
	return make_pair(prod, prod2);
}

