using namespace std;

mt19937 rnd;

const long SQRT  = 110000;
const long CBRT  = 2200;
const long MAXN = 1e10;
bool prime[SQRT];
vector<long> primes;
vector<long> squares;
long answer = 0;

long up(long a, long b) {
	assert(a >= 0 && b > 0);
	return (a + b - 1) / b;
}

pair<long, long> func(long x) {
	assert(x > 0);
	long a = 1, b = 1;
	for (long d : primes) {
		if (d * d * d > x) {
			break;
		}
		long cnt = 0;
		while (x % d == 0) {
			x /= d;
			++cnt;
		}
		cnt %= 3;

		if (cnt == 1) {
			if (a > up(MAXN, d) || b > up(MAXN, d * d)) {
				++answer;
				return {0, 0};
			}
			a *= d;
			b *= d * d;
		} else if (cnt == 2) {
			if (a > up(MAXN, d * d) || b > up(MAXN, d)) {
				++answer;
				return {0, 0};
			}
			a *= d * d;
			b *= d;
		}
		if (max(a, b) > MAXN) {
			++answer;
			return {0, 0};
		}
	}
	if (!binary_search(all(squares), x)) {
		if (a > up(MAXN, x) || b > up(MAXN, x * x)) {
			++answer;
			return {0, 0};
		}
		a *= x;
		b *= x * x;
	} else {
		if (a > up(MAXN, x) || b > up(MAXN, sqrt(x))) {
			++answer;
			return {0, 0};
		}
		a *= x;
		b *= sqrt(x);
	}
	if (max(a, b) > MAXN) {
		++answer;
		return {0, 0};
	}
	assert(1 <= a && 1 <= b);
	assert(a <= MAXN && b <= MAXN);
	return {a, b};
}


