typedef long long ll;
const int N = (int) 1e5 + 100;
bool ciur[N];
vector<int> primes;
vector<ll> primes3;
map<ll, int> f;
map<ll, ll> trans;
map<ll, ll> inv;

int main() {
  ios::sync_with_stdio(0);
  cin.tie(0);

  ciur[2] = 1;
  for (int i = 3; i < N; i += 2) {
    ciur[i] = 1;
  }
  for (int i = 3; i * i < N; i += 2) {
    if (ciur[i]) {
      for (int j = i * i; j < N; j += 2 * i) {
        ciur[j] = 0;
      }
    }
  }
  for (int i = 1; i < N; i++) {
    if (ciur[i]) {
      primes.push_back(i);
      primes3.push_back(1LL * i * i * i);
    }
  }
  int n;
  cin >> n;
  while (n--) {
    ll x;
    cin >> x;
    if (!trans.count(x)) {
      ll y = x;
      for (auto &p3 : primes3) {
        if (p3 > y) break;
        while (y % p3 == 0) {
          y /= p3;
        }
      }
      trans[x] = y;
      ll ii = 1;
      for (auto &p : primes) {
        if (p * p > y) break;
        int cnt = 0;
        while (y % p == 0) {
          y /= p;
          cnt++;
        }
        if (cnt == 1) {
          ii *= p * p;
        }
        if (cnt == 2) {
          ii *= p;
        }
      }
      ii *= y * y;
      inv[trans[x]] = ii;
    }
    f[trans[x]]++;
  }
  int sol = 0;
  for (auto &it : f) {
    ll x = it.first;
    if (x == 1) {
      if (f[x]) {
        sol++;
      }
    } else {
      if (f[x] > f[inv[x]]) {
        sol += f[x];
      }
      if (f[x] == f[inv[x]] && x > inv[x]) {
        sol += f[x];
      }
    }
  }
  cout << sol << "\n";
}

