void init() {
	for(int i=2;i<P;++i) {
		if(!flg[i]) p[++tot]=i;
		for(int j=1;j<=tot&&i*p[j]<P;++j) {
			flg[i*p[j]]=1;
			if(i%p[j]==0) break;
		}
