void solve() {
	scanf("%d",&n);
	for(int k=1;k<=n;++k) {
		long long x;
		scanf("%lld",&x);
		t[k]=1;
		for(int i=1;1LL*p[i]*p[i]*p[i]<=x;++i) {
			long long c=1LL*p[i]*p[i]*p[i];
			while(x%c==0) x/=c;
