#include <bits/stdc++.h>
using namespace std;

using ll = long long;

vector<ll> sieve() {
    const int max_v = 100001;
    vector<ll> res;
    vector<bool> is_prime(max_v, true);
    for(int i = 2; i < max_v; ++i) {
        if(!is_prime[i]) continue;
        res.push_back(i);
        for(int j = i + i; j < max_v; j += i) {
            is_prime[j] = false;
        }
    }
    return res;
}

pair<ll, ll> calc(vector<ll> const& primes, map<ll, ll>& p2, const ll x) {
    ll res1 = x, tmp = x, res2 = 1;
    for(auto const p : primes) {
        const ll p3 = p * p * p;
        if(p3 > x) break;
        while(res1 % p3 == 0) {
            res1 /= p3;
        }
        while(tmp % p == 0) {
            tmp /= p;
        }
        if(res1 % (p * p) == 0) {
            res2 *= p;
        } else if(res1 % p == 0) {
            res2 *= p * p;
        }
    }

    if(p2.count(tmp)) {
        res2 *= p2[tmp];
    } else {
        res2 *= tmp * tmp;
    }

    return make_pair(res1, res2);
}

int main() {
    const auto primes = sieve();
    map<ll, ll> p2;
    for(auto const p : primes) {
        p2[p * p] = p;
    }

    int n; cin >> n;
    vector<pair<ll, ll>> s(n);
    map<ll, int> cnt;
    for(int i = 0; i < n; ++i) {
        ll x; cin >> x;
        s[i] = calc(primes, p2, x);
        cnt[s[i].first] += 1;
    }

    int ans = 0;
    map<ll, int> maxi;
    for(auto const& p : s) {
        const ll x = p.first, y = p.second;
        if(x == 1) {
            ans = 1;
        } else {
            maxi[min(x, y)] = max(maxi[min(x, y)], cnt[x]);
        }
    }
    for(auto const& p : maxi) {
        ans += p.second;
    }

    cout << ans << endl;
}

