long long Slove(long long n)
{
    long long t = n;
    long long ret = 1;
    for(vector<int>::size_type i = 0; i < prime.size(); ++i)
    {
        if(static_cast<long long>(prime[i]) * prime[i] * prime[i] > t)
            break;
        if(n % prime[i] == 0)
        {
            int cnt = 0;
            while(n % prime[i] == 0)
            {
                n /= prime[i];
                ++cnt;
            }
            cnt %= 3;
            while(cnt--)
                ret *= prime[i];
        }
    }
    if(n > 1)
        ret *= n;
    return ret;
}
int main()
{
