    map<pair<long long ,long long >,int> cnt,vis;
    sieve(110000ll,primes);
    int n;
    pair<long long ,long long> s[100010]={};
    cin >> n;
    REP(i,n){
        LL tmp; cin >> tmp;
        s[i]=remove_cube(tmp);
        cnt[s[i]]++;
    }
    LL ans=0;
    REP(i,n){
        if(vis[s[i]]==1) continue;
        if(s[i]==make_pair(1ll,1ll)) {
            ans++;
        }
        else{
            ans+=max(cnt[s[i]],cnt[pairvec(s[i])]);
        }
        vis[s[i]]=1;
        vis[pairvec(s[i])]=1;
    }
    cout << ans <<endl;

    return 0;
}

