void findprime()
{
	memset(vis,0,sizeof(vis));
	np=0;
	for(int i=2;i<=2333;i++)
	{
		if(!vis[i])
			prime[++np]=i;
		for(int j=1;j<=np&&i*prime[j]<=2333;j++)
		{
			vis[i*prime[j]]=true;
			if(i%prime[j]==0)
				break;
		}
	}
}
long long findr(long long x)
{
	long long h;
	for(int i=1;i<=np;i++)
	{
		h=prime[i]*prime[i]*prime[i];
		if(h>x)
			break;
		while(x%h==0)
			x/=h;
	}
	return x;
}
long long findto(long long x)
{
	long long reta=1,retb=1;
	int h=0;
	for(int i=1;i<=np;i++)
	{
		h=prime[i]*prime[i]*prime[i];
		if(h>x)
			break;
		h=0;
		while(x%prime[i]==0)
		{
			h++;
			x/=prime[i];
		}
		if(h==1)
			reta*=prime[i];
		else if(h==2)
			retb*=prime[i];
	}
	long long hh=(long long)(sqrt(x)+0.5);
	if(hh*hh==x)
		retb*=hh;
	else
		reta*=x;
	long long ret=reta*retb;
	if(maxv/reta<ret)
		return -1;
	return ret*reta;
}
