ll counter(ll a){
    map<ll,ll> t;
    int j=0;
    while(j<prime2.size()){
        if(a<prime2[j])break;
        while(a%prime2[j]==0){
            if(t.find(prime2[j])==t.end())t[prime2[j]]=1;
            else t[prime2[j]]++;
            a/=prime2[j];
        }
        j++;
    }
    ll ans=1;
    for(auto itr=t.begin();itr!=t.end();itr++){
        if(itr->second==1)ans*=(itr->first*itr->first);
        if(itr->second==2)ans*=itr->first;
    }
    return ans;
}

