bool check(int x){
	for(int i=2;i*i<=x;i++)if(x%i==0)return false;return true;
}
map<Int,Int>inv,cnt;
int main(){
	cin>>n;
	for(int i=1;i<=n;i++){
		cin>>a[i];
	}
	for(int i=2;i<=2333;i++)if(check(i))p.push_back(i);
	for(int i=1;i<=n;i++){
		Int val=1,Inv=1;
		for(int tt=0;tt<p.size();tt++){
			int x=p[tt];int cnt=0;
			while(a[i]%x==0){
				cnt++;a[i]/=x;
			}
			cnt%=3;
			for(int j=1;j<=cnt;j++)val*=x;
			for(int j=1;j<=(3-cnt)%3;j++)Inv*=x;
		}
		if(a[i]>1){
			Int tmp=sqrt(a[i]);
			while(tmp*tmp<a[i])tmp++;
			while(tmp*tmp>a[i])tmp--;
			if(tmp*tmp==a[i]){
				val*=a[i];
				Inv*=tmp;
			}else{
				val*=a[i];
				Inv*=a[i]*a[i];
			}
		}
		cnt[val]++;inv[val]=Inv;
	}
	int ans=0;
	for(map<Int,Int>::iterator itr=cnt.begin();itr!=cnt.end();){
		pair<Int,Int>p=*itr;
		int now=p.first,nxt=inv[p.first];
		if(!cnt.count(nxt)){
			ans+=cnt[now];cnt.erase(itr++);continue;
		}
		if(now==nxt){
			ans++;cnt.erase(itr++);continue;
		}
		ans+=max(cnt[now],cnt[nxt]);
