int sieve_size;
bitset<10000001> bs;
vector<ll> pr;

void sieve(int size) {
	sieve_size = size;
	bs.set(); bs[0] = bs[1] = 0;
  	for (ll i = 2; i <= sieve_size; ++i) if (bs[i]) {
		for (ll j = i * i; j <= sieve_size; j += i) bs[j] = 0;
		pr.push_back(i);
	}
}

ll S[100001], a[100001], b[100001];
set<ll> sq;
map<ll, int> M;

int main() {
	ios_base::sync_with_stdio(0), cin.tie(0);

	int N; cin >> N;
	for (int i = 0; i < N; ++i) cin >> S[i];

	sieve(1e5);
	for (ll p : pr) sq.insert(p * p);

	int ans = 0;
	for (int i = 0; i < N; ++i) {
		a[i] = S[i];
		for (int j = 0; pr[j] < 2222; ++j) {
			ll x = pr[j] * pr[j] * pr[j];
			while (a[i] % x == 0) a[i] /= x;
		}
		++M[a[i]];

		b[i] = 1;
		for (int j = 0; pr[j] < 2222; ++j) {
			int cnt = 0;
			while (S[i] % pr[j] == 0) S[i] /= pr[j], ++cnt;
			if (cnt % 3 == 1) b[i] *= pr[j] * pr[j];
			else if (cnt % 3 == 2) b[i] *= pr[j];
		}
		if (sq.find(S[i]) != sq.end()) b[i] *= sqrt(S[i]);
		else b[i] *= S[i] * S[i];
	}

	if (M[1]) ++ans, M[1] = 0;	
	for (int i = 0; i < N; ++i) ans += max(M[a[i]], M[b[i]]), M[a[i]] = M[b[i]] = 0;
	cout << ans << '\n';
}

