map<ll, int> prefact(ll n) {
    map<ll, int> mp, mp1, mp2;
    for (ll d: pr) {
        if (1000 < d) break;
        while (n % d == 0) {
            n /= d;
            mp1[d]++;
        }
    }
    if (isPrime(n)) {
        mp[n]++;
        return mp;
    }
    if (n <= TEN(5)) mp2 = factsmall(n);
    else mp2 = factsmall(n);
    for (auto p: mp1) {
        mp[p.first] += p.second;
    }
    for (auto p: mp2) {
        mp[p.first] += p.second;
    }
    return mp;
}

