ll bsearch(ll x){
	ll l=0,r=prime.size();
	while (l<r){
		ll mid=(l+r)/2;
		if (prime[mid]*prime[mid]==x){
			return mid;
		}
		if (prime[mid]*prime[mid]<x){
			l=mid+1;
		}else{
			r=mid;
		}
	}
	return -1;
}

ll pa(ll x){
	//xのペアを求める
	ll res=1;
	for (int i=0;prime[i]*prime[i]*prime[i]<=MAX_S;i++){
		ll p=prime[i];
		if (x%(p*p)==0){
			x/=p*p;
			res*=p;
		}else if (x%p==0){
			x/=p;
			res*=p*p;
		}
		if (res>MAX_S){
			return -1;
		}
	}
	ll sqrt=bsearch(x);
	if (sqrt==-1){
		res*=x*x;
	}else{
		res*=sqrt;
	}
	return res;
}

