        if (my == 1) one = true;
        else if (my < oth) M[my].first++;
        else M[oth].second++;
    }
    res = int(one);
    for (auto it: M)
        res += max(it.second.first, it.second.second);
    printf("%d\n", res);
    return 0;
}

