        ll s = S[i];
        for ( ll k = 2; k*k <= s && k < 10e5+1; k++ ) {
            while ( s % k == 0 ) {
                ns[k] = (ns[k] + 1) % 3;
                s /= k;
            }
        }
        if ( s > 1 ) {
            ns[s] = (ns[s] + 1) % 3;
        }
        for ( auto it = ns.begin(); it != ns.end();) {
            if ( it->second == 0 ) {
                ns.erase(it++);
            } else {
                it++;
            }
        }
        m[enc_map(ns)]++;
    }

    ll ans = 0;
    set<string> checked;
    for ( auto mm : m ) {
        if ( mm.first == "" ) {
