const int N = 1e7 + 100;

vi primes;

bool prime[N];

int cnt_big;
bool zero;

map<ll, map<int, int>> msks;
map<ll, int> len;

void smain() {
    primes.reserve(N);
    fill(prime, prime + N, true);
    for (int i = 2; i * i <= N; ++i) {
        if (!prime[i])
            continue;
        primes.push_back(i);
        for (int j = i * i; j < N; j += i) {
            prime[j] = false;
        }
    }

    int n;
    cin >> n;
    fori (i, n) {
        ll x;
        cin >> x;
        vector<pll> f;
        for (auto p : primes) {
            if (x % p == 0) {
                int cnt = 0;
                while (x % p == 0) {
                    x /= p;
                    cnt++;
                }
                f.push_back({p, cnt});
            }
        }
        if (x > 1) {
            if (binary_search(ALL(primes), x)) {
                f.push_back({x, 1});
            } else {
                cnt_big++;
                continue;
            }
        }
        sort(ALL(f));
        int cnt = 0;
        ll base = 1;
        int mask = 0;
        for (auto x : f) {
            if (x.second % 3 != 0) {
                base *= x.first;
                mask |= (x.second % 3 - 1) << cnt;
                cnt++;
            }
        }
        if (base == 1) {
            zero = 1;
        } else {
            msks[base][mask]++;
            len[base] = cnt;
        }
    }
    ll ans = cnt_big + zero;
    for (auto item : msks) {
        ll base = item.first;
        for (auto x : item.second) {
            int inv = x.first ^ ((1 << len[base]) - 1);
            if (item.second.count(inv)) {
                if (inv < x.first)
                    ans += max(x.second, item.second[inv]);
            } else {
                ans += x.second;
            }
        }
    }
    cout << ans;
}

