#include <bits/stdc++.h>
#define ll long long
#define CUBE_S_MAX 2154
using namespace std;

int N;
vector<ll> s;
unordered_map<ll, int> nums;
bool is_prime[100001];
#define TEN_POWER_FIVE 100000
#define TEN_POWER_TEN 10000000000l

void set_eratosthenes() {
  for (int i = 2; i <= TEN_POWER_FIVE; i++) {
    is_prime[i] = true;
  }
  for (int i = 2; i <= TEN_POWER_FIVE; i++) {
    if (is_prime[i]) {
      for (int k = i + i; k <= TEN_POWER_FIVE; k += i) {
        is_prime[k] = false;
      }
    }
  }
}

void solve() {
  set_eratosthenes();

  // norm[s[i]]を求める
  for (int i = 0; i < N; i++) {
    for (ll k = 2; k <= CUBE_S_MAX; k++) {
      if (is_prime[k]) {
        while (s[i] % (k * k * k) == 0) {
          s[i] /= k * k * k;
        }
      }
    }
  }
  sort(s.begin(), s.end());

  // normをkey, 個数をvalueとしたunordered_mapに挿入
  for (int i = 0; i < N; i++) {
    if (nums.count(s[i])) {
      nums[s[i]]++;
    } else {
      nums[s[i]] = 1;
    }
  }

  int ans = 0;
  for (auto pair:nums) {
    ll key = pair.first;
    if (key != 1) {
      // pair(key) を求める
      ll acc = 1;
      double acc_double = 1.0;
      // 1. CUBE_S_MAXまでの素数
      for (ll k = 2; k <= CUBE_S_MAX; k++) {
        if (is_prime[k]) {
          if (key % (k * k) == 0) {
            key /= (k * k);
            acc *= k;
            acc_double *= k;
          } else if (key % k == 0) {
            key /= k;
            acc *= (k * k);
            acc_double *= (k * k);
          }
        }
      }
      if (key > 1) {
        // 2-1. 10^5までの素数の2乗
        int square_tmp = (int)(pow(float(key), 1.0/2.0) + 0.5);
        if (key == square_tmp * square_tmp && is_prime[square_tmp]) {
          acc *= square_tmp;
          acc_double *= square_tmp;
        }
        // 2-2. 10^5までの素数
        else if (key <= TEN_POWER_FIVE && is_prime[key]) {
          acc *= (key * key);
          acc_double *= (key * key);
        }
        else {
          acc = -1;
        }
      }

      if (acc_double <= (double)TEN_POWER_TEN && nums.count(acc)) {
        ans += max(nums[acc], nums[pair.first]);
        nums[acc] = 0;
        nums[pair.first] = 0;
      } else {
        ans += nums[pair.first];
      }
    }
  }
  if (nums.count(1)) ans++;
  cout << ans << endl;
}

int main() {
  cin >> N;
  for (int i = 0; i < N; i++) {
    ll x;
    cin >> x;
    s.push_back(x);
  }

  solve();
  return 0;
}

