vector <lint> asal;
void asllar()
{
    int n=100004;
    bool prime[100005]; 
    memset(prime, true, sizeof(prime)); 

    for (lint p=3; p*p<=n; p+=2) 
    { 
        if (prime[p] == true) 
        { 
            for (lint i=p*p; i<=n; i += 2*p) 
                prime[i] = false; 
        } 
    } 

    asal.push_back(2);
    for (int p=3; p<=n; p+=2) 
       if (prime[p]) 
            asal.push_back(p);
}
inline pair<lint,lint> deleteCubes(lint x)
{
    lint Val=1,reVal=1;
    for (auto i: asal)
    {
        if(i*i>x) break;
        if(x%i==0)
        {
            int cnt=0;
            while(x%i==0)
            {
                cnt++;
                x/=i;
            }
            cnt%=3;
            for (int j = 0; j < cnt; j++)
                Val*=i;
            if(cnt==1 || cnt==2)            
            for (int j = 0; j < 3-cnt; j++)
                reVal*=i;
        }
    }
    if(x>1)
    {
        int cnt=1;
        for (int j = 0; j < cnt; j++)
            Val*=x;
        if(cnt==1 || cnt==2)            
        for (int j = 0; j < 3-cnt; j++)
            reVal*=x;
    }
    return MP(Val,reVal);
}

unordered_map <lint,int> occurance;

