    for (int i = 0; i < n; i++)
    {
        lint o;
        cin >> o;
        if(calculated.count(o)==0)
        {
            pair<lint,lint> ret= deleteCubes(o);
            numbers.push_back(ret);
            calculated[o]=ret;
        }
        else
            numbers.push_back(calculated[o]);
        occurance[numbers.back().first]++;
    }
    lint ans=0;
    if(occurance[1]>=1)
        ans++;
    for (int i = 0; i < n; i++)
    {
