        int occuranceVal = occurance[value];
        if(occuranceVal==0) continue;
        if(value==1) continue;
        lint reverseValue = numbers[i].second;
        ans += max(occuranceVal, occurance[reverseValue]);
        occurance[reverseValue]=0;
        occurance[value]=0;
    }
    cout << ans << endl;
}

