int get(int x) {
	vector<ii> ret; 
	for(auto p : pr) {
		if(p * p > x) break; 
		if(x % p == 0) {
			int cnt = 0; 
			while(x % p == 0) {
				x /= p; 
				cnt++; 
			}
			cnt %= 3; 
			if(!cnt) continue; 
			ret.pb({p, cnt}); 
		}
	}
	if(x > 1) 
		ret.pb({x, 1});
	int ans = 1; 
	for(auto t : ret) {
		for(int i = 1; i <= t.se; i++) 
			ans *= t.fi; 
	}
	if(!comple[ans]) {
		int comp = 1; 
		for(auto t : ret) {
			for(int i = 1; i <= 3 - t.se; i++) 
			 	comp *= t.fi; 
		}
		comple[ans] = comp; 
	}
	return ans; 
}

