V<ll> primes;
V<ll> pow2_p;

void calc_primes() {
    const size_t size = 1e5 + 10;
    bool used[size] = {};
    for(ll i = 2; i < size; i++) {
        if(used[i]) continue;
        primes.push_back(i);
        pow2_p.push_back(i * i);
        for(ll j = 1; i * j < size; j++) used[i * j] = true;
    }
}

int main() {
    calc_primes();
    ll N;
    cin >> N;
    ll ans = 0;
    map<ll, ll> cnt;
    map<ll, ll> anti;

    while(N--) {
        ll e;
        cin >> e;
        ll save_e = 1;
        ll anti_num = 1;
        bool non = false;
        for(ll p : primes) {
            ll cube_p = p * p * p;
            if(1e10 < cube_p) break;
            while(e % cube_p == 0) e /= cube_p;
            ll cnt_div = 0;
            while(e % p == 0) {
                e /= p;
                cnt_div++;
            }
            for(ll i = 0; i < cnt_div; i++) save_e *= p;
            ll anti_cnt_div = (3 - cnt_div) % 3;
            for(ll i = 0; i < anti_cnt_div; i++) {
                anti_num *= p;
                if(1e10 < anti_num) {
                    non = true;
                    break;
                }
            }
            if(non) break;
        }

        if(!non && e != 1) {
            auto ite = lower_bound(ALL(pow2_p), e);
            save_e *= e;
            if(ite != pow2_p.end() && *ite != e) {
                auto idx = distance(pow2_p.begin(), ite);
                anti_num *= primes[idx];
            } else {
                anti_num *= e * e;
            }
            if(1e10 < anti_num) non = true;
        }

        if(non) {
            ans++;
            continue;
        }

        // DEBUG(make_tuple(e, anti_num));
        anti[save_e] = anti_num;
        cnt[save_e]++;
    }

    for(auto &&ele : cnt) {
        ll num, cnt_v;
        tie(num, cnt_v) = ele;
        ll anti_num = anti[num];
        // DEBUG(make_tuple(num, anti_num, cnt_v));
        auto ite = cnt.find(anti_num);
        if(ite == cnt.end()) {
            ans += cnt_v;
            continue;
        }
        if(anti_num != 0 && anti_num < num) continue;
        if(num == anti_num) ans++;
        else ans += max(cnt_v, ite->second);
    }
    cout << ans << endl;
    return 0;
}

