ll N;
vector<ll> S;
const ll M = 10000000000;
void solve(){
  sieve(100005);
  vector<ll> p2, p3;
  set<ll> x2;
  map<ll, ll> root;
  for(ll i = 2; i * i * i <= M; i++){
    if(is_prime[i] == 0) continue;
    p3.pb(i*i*i);
  }
  for(ll i = 2; i * i <= M; i++){
    if(is_prime[i] == 0) continue;
    p2.pb(i*i);
    x2.insert(i*i);
    root[i*i] = i;
  }

  vector<ll> A(N), B(N, -1);
  rep(i, N){
    ll s = S[i];
    rep(j, p3.size()){
      while(s % p3[j] == 0){
        s /= p3[j];
      }
    }
    A[i] = s;
    if(A[i] == 1){
      continue;
    }
    ll t = 1;
    rep(j, p3.size()){
      if(t == INFL) break;
      if(s % p2[j] == 0){
        s /= p2[j];
        t *= prime[j];
        if(t > M) t = INFL;
      }else if(s % prime[j] == 0){
        s /= prime[j];
        t *= p2[j];
        if(t > M) t = INFL;
      }
    }
    if(s == 1){
      B[i] = t;
      continue;
    }
    if(t == INFL){
      B[i] = t;
      continue;
    }
    bool l = 0;
    if(x2.count(s)){
      t *= root[s];
      if(t > M) t = INFL;
      l = 1;
    }
    if(l == 0){
      if(t == INFL){
        continue;
      }
      if(t <= M / s * 100) t *= s;
      else t = INFL;
      if(t > M) t = INFL;
      if(t == INFL){
        continue;
      }
      if(t <= M / s * 100) t *= s;
      else t = INFL;
      if(t > M) t = INFL;
    }
    B[i] = t;
  }

  ll e = 0;
  map<ll, ll> MS;
  for(ll i = 0; i < N; i++){
    if(A[i] == 1)e++;
    else{
      MS[A[i]]++;
    }
  }
  ll ans = 0;
  if(e != 0) ans++;
  for(ll i = 0; i < N; i++){
    if(A[i] == 1) continue;
    ll cntx = MS[A[i]];
    ll cnty = MS[B[i]];
    ans += max(cntx, cnty);
    MS[A[i]] = 0;
    MS[B[i]] = 0;
  }
  cout << ans << endl;
}

int main(){
  cin >> N;
  S.resize(N);
  rep(i, N) cin >> S[i];
  solve();
}

