		}
		if (A[i] != 1){
			assert(B[i] != 0);
			opp*= B[i];
		}
		assert(opp != act);
		if (opp > act){
			M[act].f++;
		}else{
			M[opp].s++;
		}
	}
	for (auto i : M)ans += max(i.s.f,i.s.s);
	if (ones)++ans;
	cout<<ans;
}

