    for (ll i=2; i*i<top; i++) {
    	bool ins=true;
    	for (int j=0; (j<primes.size())&&(ins); j++) if (i%primes[j]==0) ins=false;
    	if (ins) primes.emplace_back(i);
    }

    bool inserted_one=false;
    map<point, int> mmap;
    int ans=0;

    for (int i=0; i<n; i++) {
    	ll pr=compute_pair(input[i]), nm=compute_norm(input[i]);
    	if (pr==1) {
    		if (inserted_one==false) ans++, inserted_one=true;
    	}
    	else mmap[point(pr, nm)]++;
    }

    for (map<point, int>::iterator i1=mmap.begin(); i1!=mmap.end(); i1++) {
    	map<point, int>::iterator i2=mmap.find(point(i1->first.second, i1->first.first));
    	if (i2==mmap.end()) ans+=i1->second;
    	else if (i1->second==i2->second) {
    		if (i1->first.first>i2->first.first) ans+=i1->second;
    	}
    	else if (i1->second>i2->second) ans+=i1->second;
    }

    cout<<ans<<endl;
