ll hoge(ll n) {
	int i;
	FOR(i,NP) {
		ll a=prime[i];
		if(a>1000) break;

		while(n % (a*a*a)==0) n /= a*a*a;
	}
	return n;
}

ll rev(ll n) {
	ll nn=n*n;
	int i;
	FOR(i,NP) {
		ll a=prime[i];
		if(a>1000) break;

		while(nn % (a*a*a)==0) nn /= a*a*a;
	}
	return nn;
}

