static void get_primes() {
    const int LIM = 100000;
    bitset<LIM> s = 0;

    for (int i = 2; i * i < LIM; ++i) {
        if (s[i])
            continue;
        for (int j = i * i; j < LIM; j+= i)
            s[j] = 1;
    }
    for (int i = 2; i < LIM; ++i)
        if (!s[i])
            primes.push_back(i);
}

static i64 get_complement(i64 num) {
    i64 c = 1;
    for (auto p: primes) {
        if (p * p > num) {
            c*= num * num;
            break;
        }
        if (num % (p * p) == 0) {
            c*= p;
            num/= p * p;
        }
        else if (num % p == 0) {
            c*= p * p;
            num/= p;
        }
    }
    return c;
}

