		scanf("%lld", a + i);
		for(LL y = 2; y * y * y <= a[i]; ++y) {
			while(a[i] % (y * y * y) == 0) {
				a[i] /= (y * y * y);
			}
		}
		if(M.find(a[i]) == M.end()) {
			M[a[i]] = 0;
		}
		++M[a[i]];
	}
	for (int i = 1; i <= n; ++i) {
		if(M.find(a[i]) == M.end()) {
			continue;
		}
		if(a[i] == 1) {
			++ans;
			M.erase(a[i]);
			continue;
		}
		int m = a[i];
		LL y = 1;
		for (LL x = 2; x <= 2500; ++x) {
			if(a[i] % x == 0) {
				a[i] /= x;
				if(y > 10000000000ll / x) {
					y = 10000000001ll;
					break;
				}
				y *= x;
				if(a[i] % x == 0) {
					a[i] /= x;
				}
				else {
					y *= x;
				}
			}
		}
		if(y > 10000000000ll) {
			ans += M[m];
			M.erase(m);
			continue;
		}
		if(a[i] > 1) {
			LL x = (LL)(sqrt(1. * a[i]));
			while(x * x <= a[i]) {
				++x;
			}
			while(x * x > a[i]) {
				--x;
			}
			if(x * x != a[i]) {
				x = a[i];
			}
			if(y > 10000000000ll / x) {
				ans += M[m];
				M.erase(m);
				continue;
			}
			y *= x;
		}
		if(M.find(y) != M.end()) {
			ans += std::max(M[m], M[y]);
			M.erase(y);
			M.erase(m);
		}
		else {
			ans += M[m];
			M.erase(m);
		}
	}
	printf("%d\n", ans);
	return 0;
}

