#include <bits/stdc++.h>

#define MAXN 100005

typedef long long lint;

using namespace std;

const int N = 2200;
int n, total, ans;
int prime[MAXN], v[MAXN];
map<lint, int> record, same;
lint a[MAXN];

lint read() {
    char c = getchar();
    lint x = 0;
    while (!isdigit(c))
        c = getchar();
    while (isdigit(c)) {
        x = (x << 3) + (x << 1) + c - '0';
        c = getchar();
    }
    return x;
}

void sieve() {
    for (int i = 2; i <= N; ++i) {
        if (!v[i])
            prime[++total] = i;
        for (int j = 1; j <= total && i * prime[j] <= N; ++j) {
            v[i * prime[j]] = 1;
            if (i % prime[j] == 0)
                break;
        }
    }
}

lint power(lint a, int b) {
    lint res = 1;
    while (b) {
        if (b & 1)
            res = res * a;
        a = a * a;
        b >>= 1;
    }
    return res;
}

void divide(lint& x) {
    lint rev = 1, cur = 1;
    for (int i = 1; i <= total && prime[i] <= N; ++i)
        if (x % prime[i] == 0) {
            int sum = 0;
            while (x % prime[i] == 0) {
                x /= prime[i];
                ++sum;
            }
            sum %= 3;
            if (sum != 0) {
                rev = rev * power(prime[i], 3 - sum);
                cur = cur * power(prime[i], sum);
            }
        }
    if (x != 1) {
        ++ans;
        return ;
    }
//    cout << rev << " " << cur << " " << ans << " ";
    if (rev == cur) {
        ans += !record[cur];
//        cout << ans << endl;
        record[cur] = true;
        return ;
    }
    ans -= max(record[rev], record[cur]);
    ++record[cur];
    ans += max(record[rev], record[cur]);
//    cout << ans << endl;
}

int main() {
//    freopen("01.txt", "r", stdin);
    sieve();
    n = (int)read();
    for (int i = 1; i <= n; ++i)
        divide(a[i] = read());
    printf("%d\n", ans);
}

