using namespace std;
typedef long long int ll;

map <ll,int> mp;
map <ll,int>::iterator it;

ll to(ll x)
{
	for(ll i=2;;i++)
	{
		ll t=i*i*i;
		if(t>x) break;
		while(x%t==0) x/=t;
	}
	return x;
}
ll tg(ll x)//toしてる -> x=P*Q^2 に直したい -> そして、P^2*Qに
{
	ll A=1,B=1;
	for(ll i=2;;i++)
	{
		if(i*i*i>x) break;
		int cnt=0;
		while(x%i==0)
		{
			x/=i;
			cnt++;
		}
		if(cnt==1) A*=i;
		else if(cnt==2) B*=i;
	}
	//x/(A*B^2)=C*D^2だから、C=1 or D=1
	ll dt=(ll) floor(sqrt(x)+0.5);
	if(dt*dt==x) B*=dt;
	else A*=x;
	ll ret=A*B;
	if(ret>INF/A+1) ret=INF;
	else ret*=A;
	return ret;
}
int main()
{
	int n;
	scanf("%d",&n);
	for(int i=0;i<n;i++)
	{
		ll x;
		scanf("%lld",&x);
		x=to(x);
		//printf("%lld ",x);
		mp[x]++;
	}
	//puts("");
	int ret=0;
	for(it=mp.begin();it!=mp.end();it++)
	{
		ll x=it->first;
		int cnt=it->second;
		ll t=tg(x);
		//if(x<=t) printf("%lld %lld : %d %d\n",x,t,mp[x],mp[t]);
		if(x<t) ret+=max(cnt,mp[t]);
		else if(x==t) ret++;
	}
	printf("%d\n",ret);
	return 0;
}

