	while(b)
	{
		if(b & 1)
		{
			ret += a;
			if(ret > c) ret -= c;
		}
		a <<= 1;
		if(a > c) a -= c;
		b >>= 1;
	}
	return ret;
}
ll pow_mod(ll a, ll n, ll mod)
{
	ll ret = 1;
	a %= mod;
	while(n)
	{
		if(n & 1) ret = mul_mod(ret, a, mod);
		a = mul_mod(a, a, mod); n >>= 1;
	}
	return ret;
}
bool check(ll a, ll n, ll x, ll t)
{
	ll ret = pow_mod(a, x, n);
	ll last = ret;
	for(int i = 1; i <= t; ++i)
	{
		ret = mul_mod(ret, ret, n);
		if(ret == 1 && last != 1 && last != n - 1) return true;
		last = ret;
	}
	if(ret != 1) return true;
	else return false;
}
bool miller_rabin(ll n) 
{
	if(n < 2) return false;
	if(n == 2) return true;
	if((n & 1) == 0) return false;
	ll x = n - 1;
	ll t = 0;
	while((x & 1) == 0) { x >>= 1; ++t;}
	srand(time(0));
	for(int i = 0; i < S; ++i)
	{
		ll a = rand() % (n - 1) + 1;
		if(check(a, n, x, t)) return false;
	}
	return true;
}
ll pollard_rho(ll x, ll c)
{
	ll i = 1, k = 2;
	srand(time(0));
	ll x0 = rand() % (x - 1) + 1;
	ll y = x0;
	while(true)
	{
		++i;
		x0 = (mul_mod(x0, x0, x) + c) % x;
		ll d = abs(__gcd(y - x0, x));
		if(d != 1 && d != x) return d;
		if(y == x0) return x;
		if(i == k) { y = x0; k <<= 1;}
	}
}
void findfac(ll n, int k)
{
	if(n == 1) return;
	if(miller_rabin(n))
	{
		fact.push_back(n);
		return;
	}
	ll p = n;
	int c = k;
	while(p >= n) p = pollard_rho(p, c--);
	findfac(p, k);
	findfac(n / p, k);
}
void getnum(ll & num, const int & id)
{
	num = 1;
	for(auto v : d[id]) num *= pow(v.first, v.second);
}
bool getcnum(ll & cnum, const int & id)
{
	cnum = 1;
	for(auto v : d[id]) 
	{
		ll tmp = pow(v.first, 3 - v.second);
		if(log10(cnum) + log10(tmp) > 11) return false;
		cnum *= tmp;
	}
	return true;
}
