	return ((x*y-hh*p)%p+p)%p;
}

inline ll ksm(ll x,ll y,ll p)
{
	ll res=1;
	for (;y;y>>=1,x=tms(x,x,p)) if (y&1) res=tms(res,x,p);
	return res;
}

