	ll hh=ksm(x,y,n),now=hh;
	for (ll i=1;i<=z;i++)
	{
		hh=tms(hh,hh,n);
		if (hh==1&&now!=1&&now!=n-1) return true;
		now=hh;
	}
	if (hh!=1) return true;
	return false;
