		int cnt;
		for(int j=0; j<prime.size(); j++){
			if(prime[j] * prime[j] > x)	break;
			if(x%prime[j]!=0)	continue;
			cnt = 0;
			while(x%prime[j]==0){
				cnt++; x/=prime[j];
			}
			cnt=cnt%3;
			for(int k=0; k<cnt; k++){
				y *= prime[j];
			}
		}
		if(x!=1){
			if(x<prime.back()){
				y *= x;
