vi primes;

pi normalize(int n) {
	int norm = 1, want = 1;
	for(int prime:primes) {
		if(n % prime == 0) {
			int cnt = 0;
			while(n % prime == 0) cnt++, n /= prime;
			cnt %= 3;
			if(cnt == 1) {
				norm *= prime;
				want *= prime * prime;
			} else if(cnt == 2) {
				norm *= prime * prime;
				want *= prime;
			}
		}
	}
	norm *= n;
	if(sq[n]) {
		want *= sq[n];
	} else {
		want *= n * n;
	}
	return {norm, want};
}

