vec prime_list(int MAX_N){

    vector<bool> is_prime(MAX_N + 1, true);
    vec prime(0);
    is_prime[0] = false;
    is_prime[1] = false;

    FOR(i, 2, MAX_N + 1){
        if(is_prime[i]){
            prime.push_back(i);
            int tmp = i * 2;
            while(tmp <= MAX_N){
                is_prime[tmp] = false;
                tmp += i;
            }
        }
    }

    return prime;
}

void factmod3(int n, int &a, int &b, vec &prime){
    a = 1; b = 1;
    REP(i, prime.size()){
        int c = 0;
        while(n % prime[i] == 0){
            c++;
            n /= prime[i];
        }
        c %= 3;
        if(c > 0){
            REP(j, c) a *= prime[i];
            REP(j, 3 - c) b *= prime[i];
        }
    }
    //2155以上の素数を含む
    if(n > 1){
        a *= n;

        int r = (int)(sqrt(n) + 1e-3);
        if(r * r == n) b *= r;
        else if(n > 100000) b = INF;
        else b *= (n * n);
    }
    //out << a << " " << b << endl;
}

