vector<pair<long long, int> > ref(vector<pair<long long, int> > a, vector<pair<long long, int> > b){
	vector<pair<long long, int> > c, ret, reta;
	for(int i=0;i<a.size();++i){
		c.push_back(a[i]);
	}
	for(int i=0;i<b.size();++i){
		c.push_back(b[i]);
	}
	sort(c.begin(), c.end());
	int n = c.size();
	for(int i=0;i<n;++i){
		if(i == 0 || (c[i].first != c[i-1].first)){
			ret.push_back(c[i]);
		}else{
			ret.back().second += c[i].second;
		}
	}
	for(int i=0;i<n;++i){
		ret[i].second %= 3;
		if(ret[i].second > 0){
			reta.push_back(ret[i]);
		}
	}
	return reta;
}

pair<long long, bool> isQ(long long v){
	long long q = (long long)sqrt(v);
	if(((q-1) * (q-1)) == v){
		return make_pair(q-1, true);
	}
	if(q*q == v){
		return make_pair(q, true);
	}
	if((q+1)*(q+1) == v){
		return make_pair(q+1, true);
	}
	return make_pair(41, false);
}

vector<pair<long long, int> > factSmall(long long v){
	vector<pair<long long, int> > ret;
	while(v > 1){
		int k = l[v];
		int d = 0;
		while(v % k == 0){
			++d;
			v /= k;
		}
		d %= 3;
		if(d){
			ret.push_back(make_pair(k * 1LL, d));
		}
	}
	return ret;
}

vector<pair<long long, int> > fact(long long v){
	if(v < M){
		return factSmall(v);
	}
	pair<long long, bool> r = isQ(v);
	if(r.second){
		vector<pair<long long, int> > ret = fact(r.first);
		return ref(ret, ret);
	}
	for(int i=2;i<M;++i){
		if(v % i == 0){
			return ref(fact(i * 1LL), fact(v/i));
		}
	}
}

vector<pair<long long, int> > inv(vector<pair<long long, int> > a){
	vector<pair<long long, int> > ret;
	for(int i=0;i<a.size();++i){
		ret.push_back(make_pair(a[i].first, 3-a[i].second));
	}
	return ret;
}

struct Num{
	vector<pair<long long, int> > d, invD, minv;
	int ans;
	Num(){
		ans = 1;
	};	
	Num(long long v){
		ans = 1;
		d = fact(v);
		invD = inv(d);
		minv = min(d, invD);
	};
};

void sieve(){
	for(int i=2;i<M;++i){
		if(l[i] == 0){
			for(int j=i;j<M;j+=i){
				if(l[j] == 0 || l[j] > i){
					l[j] = i;
				}
			}
		}
	}
}

Num arr[N];

bool comp(Num a, Num b){
	if(a.minv == b.minv){
		return (a.d < b.d);
	}else{
		return (a.minv < b.minv);
	}
}

