il void init(){
	static bool kicked[M];
	rep(i,2,M-1){
		if(!kicked[i]) prime[++tot]=i;
		rep(j,1,tot){
			if(i*prime[j]>=M) break;
			kicked[i*prime[j]]=true;
			if(i%prime[j]==0) break;
		}
	}
}

int main(){
	init();
	scanf("%d",&n);
	rep(i,1,n){
		scanf("%lld",a+i);
		need[i]=rest[i]=1;
		ll tmp=a[i];
		rep(j,1,tot){
			int v=prime[j];
			if(tmp%v!=0) continue;
			int times=0;
			while(tmp%v==0) tmp/=v,++times;
			times%=3;
			if(times==1){
				rest[i]*=v;
				need[i]*=v*v; 
			}else if(times==2){
				rest[i]*=v*v;
				need[i]*=v;
			}
		}
		if(tmp>1){
			ll v=floor(sqrt(tmp));
			if(v*v==tmp){
				rest[i]*=tmp;
				need[i]*=v;
			}else{
				rest[i]*=tmp;
				need[i]*=tmp*tmp;
			}
		}
	//	cerr<<need[i]<<" "<<rest[i]<<endl;
		++cnt[mp(rest[i],need[i])];
	}
	int ans=0;
	while(cnt.begin()!=cnt.end()){
		pll p=cnt.begin()->X,q=mp(p.Y,p.X);
		if(p.X==1) ++ans;
		else{
			ans+=qmax(cnt[p],cnt[q]);
			cnt.erase(q);
		}
		cnt.erase(cnt.begin());
	}
	printf("%d\n",ans);
	return 0;
}

