	ll n;
	cin >> n;
	Array s(n);
	Array prime;
	map<ll, ll> prime2;
	rep(i, 2, 100001) {
		ll flag = 1;
		REP(j, prime.size()) {
			if (i % prime[j] == 0) {
				flag = 0;
				break;
			}
		}
		if (flag == 1) {
			prime.push_back(i);
			if (i > 2500) {
				prime2[i * i] = i;
			}
		}
	}
	map<ll, ll> mp;
	Array b(n, 1);
	Array p(n, 1);
	ll ans = 0;
	ll flag = 0;
	REP(i, n) {
		cin >> s[i];
		REP(j, prime.size()) {
			if (prime[j] > 2500)break;
			ll cnt = 0;
			while (true) {
				if (s[i] % prime[j] == 0) {
					cnt++;
					s[i] /= prime[j];
				}
				else {
					break;
				}
			}
			cnt %= 3;
			REP(k, cnt)b[i] *= prime[j];
			if (cnt != 0)REP(k, 3 - cnt)p[i] *= prime[j];
			if (p[i] > 10000000000LL)p[i] = 0;
		}
		if (b[i] == 1 && s[i] == 1) {
			flag = 1;
			p[i] = -INF;
			continue;
		}
		if (prime2[s[i]]) {
			b[i] *= s[i];
			p[i] *= prime2[s[i]];
			if (p[i] > 10000000000LL)p[i] = 0;
			mp[b[i]]++;
		}
		else  {
			b[i] *= s[i];
			REP(k, 2) {
				p[i] *= s[i];
				if (p[i] > 10000000000LL)p[i] = 0;
			}
			mp[b[i]]++;
		}
	}
	ans += flag;
	REP(i, n) {
		ll s, t;
		if (p[i] == -INF)continue;
		else {
			s = mp[b[i]];
			t = mp[p[i]];
			ans += max(s, t);
			mp[b[i]] = 0;
			mp[p[i]] = 0;
		}
	}
	cout << ans << endl;




