template<typename T> bool chmax(T& a,const T& b){return a < b ? (a = b,true) : false;}
template<typename T> bool chmin(T& a,const T& b){return b < a ? (a = b,true) : false;}
typedef long long ll;

int N;
vector<ll> prime;
map<ll,ll> sqr;
const ll MAX_A = 1e10;

ll calc_pair(ll x)
{
	ll res = 1;
	map<ll,int> fact;
	for(int i = 0;i < prime.size() && prime [i] * prime [i] * prime [i] <= x;i++){
		while(x % prime [i] == 0){
			fact [prime [i]]++;
			x /= prime [i];
		}
	}
	if(sqr.count(x) && res <= MAX_A / sqr [x]){
		res *= sqr [x];
	}
	else if(sqr.count(x) == 0 && res <= MAX_A / x / x){
		res *= x * x;
	}
	else{
		return -1;
	}
	for(auto&& it : fact){
		if(it.second == 1 && res <= MAX_A / it.first / it.first){
			res *= it.first * it.first;
		}
		else if(it.second == 2 && res <= MAX_A / it.first){
			res *= it.first;
		}
		else{
			return -1;
		}
	}

	return res;
}

int main()
{
	cin.tie(0);
	ios::sync_with_stdio(false);

	cin >> N;
	vector<ll> A(N);
	FOR(i,0,N){
		cin >> A [i];
	}

	for(ll i = 2;i * i <= MAX_A;i++){
		bool flag = true;
		for(int j = 0;j < prime.size() && prime [j] * prime [j] <= i;j++){
			if(i % prime [j] == 0){
				flag = false;
				break;
			}
		}
		if(flag){
			prime.push_back(i);
			sqr [i * i] = i;
		}
	}

	map<ll,int> cnt;
	FOR(i,0,N){
		for(int j = 0;j < prime.size() && prime [j] * prime [j] * prime [j] <= A [i];j++){
			while(A [i] % (prime [j] * prime [j] * prime [j]) == 0){
				A [i] /= prime [j] * prime [j] * prime [j];
			}
		}
		cnt [A [i]]++;
	}

	ll ans = 0;
	for(auto&& it : cnt){
		if(it.first == 1){
			ans++;
			continue;
		}
		ll tmp = calc_pair(it.first);
		if(tmp == -1 || cnt.count(tmp) == 0){
			ans += it.second;
		}
		else if(tmp > it.first){
			ans += max(it.second,cnt [tmp]);
		}
	}

	cout << ans << endl;

	return 0;
}

