using namespace std;

vector<int> pp;
void preparePrime( int maxp )
{
    int i;
    vector<int> a(maxp+1);
    for(i=2; i<=maxp; i++) {
        int k=i+i;
        while(k<=maxp) {
            a[k]=1;
            k+=i;
        }
    }
    for(i=2; i<=maxp; i++) {
        if(a[i]==0) pp.push_back( i );
    }
    return;
}

int main(int argc, char* argv[])
{
    preparePrime(2200);       // (10^10)^(1/3) 以下の数について素数を列挙
    const int num3=(int)pp.size();
    vector<ll> a2(num3);    // 2乗した数を列挙  a2[i]=i^2
    vector<ll> a3(num3);    // 3乗した数を列挙  a3[i]=i^3

    int i,j;
    for(i=0; i<num3; i++) {
        a2[i]=(ll)pp[i]*pp[i];
        a3[i]=a2[i]*pp[i];
    }

    int n;
    scanf("%d", &n);

    map<ll,int> cnt;
    for(i=0; i<n; i++) {
        ll s;
        scanf("%lld", &s);
        for(j=0; j<num3; j++) {      // 立方数で割っておく
            if(s<a3[j]) break;
            while(s%a3[j]==0) {
                s/=a3[j];
            }
        }
        cnt[s]++;
    }

    int ans=0;
    if(cnt.find(1)!=cnt.end()) {    // 1（つまり元々立方数だったもの）を答えに反映させて、mapから削除
        ans++;
        cnt.erase(1);
    }

    queue<ll> que;
    {
        auto it=cnt.begin();
        for(; it!=cnt.end(); ++it) {
            que.push(it->first);
        }
    }

    while(!que.empty()) {
        ll tt=que.front();
        que.pop();

        auto it=cnt.find(tt);
        if(it==cnt.end()) continue;

        ll curr=it->first;
        ll sub=1;
        for(j=0; j<num3; j++) {        // currを平方数と無平方数の積にする。ただし平方数はa2に列挙したもののみ考えればよい
            if(curr<a2[j]) break;
            while(curr%a2[j]==0) {
                curr/=a2[j];
                sub*=pp[j];
            }
            if(sub>num3 || curr<sub) break;
        }
        if(sub>num3 || curr<sub) continue;
        double chk=(double)curr*curr*sub;
        if(chk>1e12) continue;
        ll tmp=curr*curr*sub;         // currとペアになる数（積が立方数になるもの）を見つける
        auto it2=cnt.find(tmp);
        if(it2!=cnt.end()) {          // ペアが見つかったら答に追加して、currおよびペアをmapから削除
            ans += MAX(it->second, it2->second);
            ll tmp0=it->first;
            ll tmp1=it2->first;
            cnt.erase(tmp0);
            cnt.erase(tmp1);
        }
    }

    auto it=cnt.begin();
    for(; it!=cnt.end(); ++it) {    // ペアにならなかった分を答に反映
        ans+=it->second;
    }
    printf("%d\n", ans);

    return 0;
}

