            if (x % p == 0) {
                int k = 0;
                while (x % p == 0) {
                    k++;
                    x /= p;
                }
                k %= 3;
                if (k > 0) {
                    int r = (3 - k);
                    while (k-- > 0) {
                        px *= p;
                    }
                    while (r-- > 0) {
                        vx *= p;
                    }
                }
            }
        }
        if (x != 1) {
            int64_t sq = sqrt(x);
            if (sq * sq == x) {
                px *= sq * sq;
                vx *= sq;
            } else {
