int prime[N+1];
void getPrime(){
    for(int i = 2; i <= N; ++i){
        if(!prime[i]) prime[++prime[0]] = i;
        for(int j = 1; j <= prime[0] && prime[j] <= N / i; ++j){
            prime[prime[j]*i] = 1;
            if(i%prime[j] == 0) break;
        }
    }
}


ll factor[100][2];
int fatCnt;
int getFactors(ll x){
    fatCnt = 0;
    ll tmp = x;
    for(int i = 1; i < N && prime[i] <= tmp; ++i){
        factor[fatCnt][1] = 0;
        if(tmp % prime[i] == 0){
            factor[fatCnt][0] = prime[i];
            while(tmp % prime[i] == 0){
                factor[fatCnt][1]++;
                tmp /= prime[i];
            }
            fatCnt++;
        }
    }
    if(tmp != 1){
        ll x = sqrt(tmp + 1);
        if(x * x == tmp){
            factor[fatCnt][0] = x;
            factor[fatCnt++][1] = 2;
        }
        else{
            factor[fatCnt][0] = tmp;
            factor[fatCnt++][1] = 1;
        }
    }
    return fatCnt;
}

