const ll N = 1e5 + 10;

map<pi, ll> mp;
ll pri[N], vis[N], tot = 0;
ll n, a[N];

void get_prime(ll t) {
  for (ll i = 2; i <= t; i++) {
    if (!vis[i]) {
      pri[++tot] = i;
    }
    for (ll j = 1; j <= tot && i * pri[j] <= t; j++) {
      vis[i * pri[j]] = 1;
      if (i & pri[j] == 0) {
        break;
      }
    } 
  }
}

int solve(ll vl) {
  // cout<<vl<<"+++"<<endl;
  ll pre = 1, suf = 1;
  for (int i = 1; i <= tot && pri[i] <= vl; i++) {
    int cnt = 0;
    while (vl % pri[i] == 0) {
      vl /= pri[i];
      cnt++;
    }
    cnt %= 3;
    if (cnt == 1) {
      pre *= pri[i];
      suf *= pri[i] * pri[i];
    } else if (cnt == 2) {
      pre *= pri[i] * pri[i];
      suf *= pri[i];
    }
    if (pre > (ll) 1e10 && suf > (ll) 1e10) {
      return 1;
    }
  }
  ll now = sqrt(vl);
  if (now * now == vl) {
    vl = 1;
    pre *= now * now;
    suf *= now;
  }
  if (pre > (ll) 1e10 && suf > (ll) 1e10) {
    return 1;
  }
  // cout<<vl<<"+"<<endl;
  if (vl != 1) return 1;
  mp[pi(pre, suf)]++;
  // cout<<pre<<" "<<suf<<endl;
  return 0;
}

int main() {
  get_prime(30000);
  scanf("%d", &n);
  int ans = 0;
  for (ll i = 1; i <= n; i++) {
    scanf("%lld", &a[i]);
    ans += solve(a[i]);
  }
  for (auto cur : mp) {
    int w1 = cur.first.first, w2 = cur.first.second;
    if (w1 > w2 && mp[pi(w2, w1)]) continue;
    if (w1 == 1 && w2 == 1) {
      ans++;
    } else {
      ans += max(mp[pi(w1, w2)], mp[pi(w2, w1)]);
    }
  }
  printf("%d\n", ans);
  return 0;
}

