long long Power(long long x, int q) {
	long long ans = 1;
	while(q--) {
		ans *= x;
	}
	return ans;
}

pair <long long, long long> func(long long x) {
	long long p = 1;
	long long q = 1;
	for(long long i = 2; i * i <= x; i++) {
		int cnt = 0;
		while(x % i == 0) {
			x /= i;
			++cnt;
		}
		cnt %= 3;
		p *= Power(i, cnt);
		q *= Power(i, (3 - cnt) % 3);
	}
	if(x > 1) {
		p *= Power(x, 1);
		q *= Power(x, 2);
	}
	return make_pair(p, q); 
}
