		scanf("%lld", &x);
		auto y = func(x);
		long long P = y.first;
		long long Q = y.second;
		cnt[P] += 1;
		if(P > Q) swap(P, Q);
		s.insert(make_pair(P, Q)); 
	}
	int ans = 0;
	for(auto i : s) {
		if(i.first == i.second) {
			++ans;
		} else {
			ans += max(cnt[i.first], cnt[i.second]);
		}
	}
	printf("%d\n", ans);
	return 0;
}

