bool isPrime[10000000];
vector<ll> p;
int N;
ll s[100000];
ll pr[100000];
ll rd[100000];
map<ll, int> mp;
set<ll> used;

void init(){
    for(int i = 2; i <= 10000000; i++) isPrime[i] = true;
    for(int i = 2; i <= 10000000; i++){
        if(isPrime[i]){
            p.push_back(i);
            for(int j = 2; j*i <= 10000000; j++) isPrime[i*j] = false;
        }
    }
}

P reducedAndPair(ll n){
    ll rd = 1;
    ll pr = 1;
    for(int i = 0;i < p.size(); i++){
        int cnt = 0;
        while(n%p[i] == 0){
            n /= p[i];
            cnt++;
        }
        cnt %= 3;
        if(cnt > 0){
            for(int j = 0; j < cnt; j++) rd *= p[i];
            for(int j = 0; j < 3-cnt; j++) pr *= p[i];
        }
        if(n == 1) break;
    }
    if(n != 1) pr = -1;
    return P(rd*n,pr);
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout << setprecision(10) << fixed;
    init();
    cin >> N;
    for(int i = 0; i < N; i++) {
        cin >> s[i];
        P tmp = reducedAndPair(s[i]);
        ll pr_ = tmp.second;
        ll rd_ = tmp.first;
        if(mp.count(rd_) == 0){
            mp[rd_] = 1;
        }else{
            mp[rd_]++;
        }
        pr[i] = pr_;
        rd[i] = rd_;
        // cout << pr_ << ' ' << rd_ << endl;
    }
    int ans = 0;
    for(int i = 0; i < N; i++){
        if(rd[i] == -1) continue;
        if(used.count(rd[i]) > 0) continue;
        if(rd[i] == 1){
            ans++;
            used.insert(1);
            continue;
        }
        if(pr[i] == -1) {
            ans += mp[rd[i]];
            used.insert(rd[i]);
            continue;
        }
        if(mp.count(pr[i]) == 0){
            ans += mp[rd[i]];
            used.insert(rd[i]);
        }else{
            int m = max(mp[rd[i]], mp[pr[i]]);
            ans += m;
            used.insert(rd[i]);
            used.insert(pr[i]);
        }
    }
    cout << ans << endl;
}

