				inv *= p[j];
				x /= p[j];
				if (x % p[j] == 0) {
					x /= p[j];
				}
				else if(inv <= inf) {
					inv *= p[j];
				}
				else break;
			}
		}
		int val = square_root(x);
		if (1LL * val * val == x) {
			x = 1;
			if(inv <= inf) inv *= val;
		}
		else {
			if (inv <= inf) inv *= x;
			if (inv <= inf) inv *= x;
			x = 1;
		}
		if(d2[inv] == 0 || i.first < inv) ret += max(score, d2[inv]);
	}
	cout << ret << endl;
	return 0;
}

