LL L[MAX];
int sz;
pair<LL, LL> E[MAX];
int esz;
map<LL, int> mapp;

pair<LL,LL> get(LL a)
{
	LL r1 = 1;
	LL r2 = 1;
	map <LL, unsigned> mapp;
	//cout << a << ":" << endl;
	factorize(a, mapp, (long long)0);

	for (map <LL, unsigned>::iterator i = mapp.begin(); i != mapp.end(); ++i)
	{
		LL p = i->first;
		int cnt = i->second % 3;
		//cout << p << " " << cnt << endl;
		cnt %= 3;
		FOR(k, 0, cnt) r1 *= p;
		cnt = (cnt * 2) % 3;

		FOR(k, 0, cnt)
		{
			if (r2 >= MAX1) continue;
			r2 *= p;
		}
	}

	return MP(r1, r2);
}

