struct custom_hash {
    static uint64_t splitmix64(uint64_t x) {
        // http://xorshift.di.unimi.it/splitmix64.c
        x += 0x9e3779b97f4a7c15;
        x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9;
        x = (x ^ (x >> 27)) * 0x94d049bb133111eb;
        return x ^ (x >> 31);
    }

    size_t operator()(uint64_t x) const {
        static const uint64_t FIXED_RANDOM = chrono::steady_clock::now().time_since_epoch().count();
        return splitmix64(x + FIXED_RANDOM);
    }
};

mt19937 eng(chrono::steady_clock::now().time_since_epoch().count());

const int P = 2;
const int S = 80;
const int SQ = 1e3;
const ll MX = 1e9;

ll m, cube;
map<vector<pll>, int> cnt;
map<vector<pll>, bool> used;

bool isCube(ll x) {
    ll y = cbrt(x);
    return y * y * y == x;
}

ll pollardRho(ll n) {
    if(n % 2 == 0) {
        return 2;
    }

    ll x, y, g = 1, a;
    x = eng() % min(MX, n - 2) + 1;
    y = x;
    a = eng() % min(MX, n - 1) + 1;

    int steps = 0;
    while (g == 1 && steps < S) {
        x = ((x * x) + a) % n;
        y = ((y * y) + a) % n;
        y = ((y * y) + a) % n;
        g = __gcd(abs(x - y), n);
        ++steps;
    }
    return g;
}

vector<pll> factor(ll a) {
    vector<int> p;
    for (int i = 2; i * i < SQ;) {
        if (a % i == 0) {
            p.em_back(i);
            a /= i;
        } else {
            ++i;
        }
    }

    if (a > 1) {
        queue<ll> q;
        q.push(a);

        while (size(q)) {
            ll u = q.front();
            q.pop();

            bool prime = true;
            for (int i = 0; i < P; ++i) {
                ll x = pollardRho(u);
                if (x > 1 && x < u) {
                    q.push(x);
                    q.push(u / x);
                    prime = false;
                    break;
                }
            }

            if (prime) {
                p.em_back(u);
            }
        }
    }
    sort(all(p));

    vector<pll> res;

    for (int i = 0; i < size(p);) {
        int j = i;
        while (j < size(p) && p[i] == p[j]) {
            ++j;
        }
        if ((j - i) % 3 != 0) {
            res.em_back(p[i], (j - i) % 3);
        }
        i = j;
    }
    return res;
}

void solve() {
    cin >> m;
    for (int i = 0; i < m; ++i) {
        ll a;
        cin >> a;
        if (isCube(a)) {
            ++cube;
        } else {
            cnt[factor(a)]++;
        }
    }

    int res = 0;
    for (auto u : cnt) {
        if (used[u.first]) {
            continue;
        }

        vector<pll> pinv = u.first;
        for (pll& p : pinv) {
            p.second = 3 - p.second;
        }

        int cntInv = cnt.count(pinv);
        int add = max(u.second, cntInv);
        res += add;

        used[u.first] = used[pinv] = 1;
    }

    cout << res + (cube > 0) << "\n";
}

