std::vector<std::pair<ll, ll>> PrimeFact(ll n) {
	std::vector<std::pair<ll, ll>> result;
	for (ll i = 2; i*i <= n; ++i) {
		int divCount = 0;
		if (n%i == 0) {
			do {
				++divCount;
				n /= i;
			} while (n%i == 0);
			result.push_back(std::make_pair(i, divCount));
		}
	}
	if (n != 1) {
		result.push_back(std::make_pair(n, 1));
	}
	return result;
}

bool isPrime(ll n) {
	if (n<2) return false;
	for (ll i = 2; i*i <= n; i++)
		if (!(n%i))return false;
	return true;
}

signed main() {
	INIT;
