	VEC(ll, s, n);
	std::multiset<ll> mset;
	REP(i, n) {
		for (ll j = 2; j*j*j <= s[i]; ++j) {
			ll t = j*j*j;
			while (s[i] % t == 0) {
				s[i] /= t;
			}
		}
		mset.insert(s[i]);
	}
	int ans = 0;
	if (mset.count(1) != 0) {
		++ans;
		mset.erase(1);
	}
	while (!mset.empty()) {
		ll now = *mset.begin();
		if (isPrime(now)) {
			int t1 = mset.count(now);
			int t2 = mset.count(now*now);
			int t = std::max(t1, t2);
			if (t >= 2) {
				ans += 2;
			}
			else {
				++ans;
			}
			mset.erase(now);
			mset.erase(now*now);
		}
		else {
			auto vec = PrimeFact(now);
			ll inv = 1;
			REP(i, vec.size()) {
				inv *= vec[i].first*(3 - vec[i].second);
			}
			int t1 = mset.count(now);
			int t2 = mset.count(inv);
			int t = std::max(t1, t2);
			if (t >= 2) {
				ans += 2;
			}
			else {
				++ans;
			}
			mset.erase(now);
			mset.erase(inv);
		}
	}
	OUT(ans)BR;
	return 0;
