const int MAX_N = 100000 + 7;

ll A[MAX_N];
bool vis[MAX_N];
vector<int> prime;

ll norm(ll x) {
  for (int p : prime) {
    ll t = 1ll * p * p * p;
    if (t > x) break;
    while (x % t == 0) x /= t;
  }
  return x;
}

ll mul(ll a, ll b) {
  if (INF64 / b < a) return INF64;
  else return a * b;
}

ll conj(ll x) {
  ll res = 1;
  for (int p : prime) {
    if (1ll * p * p > x) break;
    if(x % p == 0) {
      if ((x / p) % p == 0) res = mul(res , p) , x /= p , x /= p;
      else res = mul(res , mul(p , p)) , x /= p;
    }
  }
  if (x > 1) res = mul(res, mul(x, x));
  return res;
}

int main() {
  REP1(i, 2, MAX_N - 1) {
    if (vis[i]) continue;
    prime.PB(i);
    for (int j = i + i; j < MAX_N; j += i) vis[j] = 1;
  }
  int N;
  RI(N);
  unordered_map<ll, int> cnt;
  REP(i, N) {
    RI(A[i]);
    A[i] = norm(A[i]);
    cnt[A[i]]++;
  }
  int ans = 0;
  unordered_set<ll> used;
  for (auto it : cnt) {
    ll x = it.F;
    if (used.count(x)) continue;
    ll y = conj(x);
    used.insert(x);
    if (x == y) {
      ans++;
      continue;
    }
    if (!cnt.count(y)) {
      ans += it.S;
      continue;
    }
    ans += max(it.S, cnt[y]);
    used.insert(y);
  }
  PL(ans);
  return 0;
}

