void Get_Prime(int n){
	pcnt=0;
	memset(vis,0,sizeof vis);
	for (int i=2;i<=n;i++){
		if (vis[i])
			continue;
		prime[++pcnt]=i;
		for (int j=i<<1;j<=n;j+=i)
			vis[j]=1;
	}
}
map <LL,int> cubic,sqr,cnt;
int check_cubic(){
	int f=0;
	int _n=0;
	for (int i=1;i<=n;i++)
		if (cubic[a[i]])
			f=1;
		else
			a[++_n]=a[i];
	n=_n;
	return f;
}
LL Get(LL x){
	LL res=1;
	for (int i=1;i<=pcnt;i++)
		if (x%prime[i]==0){
			LL cnt=1;
			x/=prime[i];
			if (x%prime[i]==0)
				x/=prime[i],cnt++;
			cnt=3-cnt;
			while (cnt>0){
				cnt--,res*=prime[i];
				if (res>1e11)
					return -1;
			}
		}
	if (x>1){
		LL t=x;
		if (sqr[x]>0)
			t=sqr[x];
		else {
			if (x>1e8)
				return -1;
			t=x*x;
		}
		if (t>1e11/res)
			return -1;
		res*=t;
	}
	return res>1e10?-1:res;
}
