		psqr[i]=1LL*prime[i]*prime[i]*prime[i];
	cnt.clear();
	for (int i=1;i<=n;i++){
		for (int j=1;j<=pcnt;j++)
			while (a[i]%psqr[j]==0)
				a[i]/=psqr[j];
		cnt[a[i]]++;
	}
	for (int i=1;i<=n;i++){
		if (!cnt[a[i]])
			continue;
		LL b=Get(a[i]);
		ans+=max(cnt[a[i]],cnt[b]);
		cnt[a[i]]=cnt[b]=0;
	}
	printf("%d",ans);
	return 0;
}

