#include <bits/stdc++.h>
#define MOD 1000000007
using namespace std;
typedef long long LL;
LL a[110000];
vector<LL> p1, p2;

LL powmod(LL a, LL n){
	if(n == 0) return 1;
	if(n % 2) return (a*powmod(a,n-1)) % MOD;
	LL c = powmod(a,n/2);
	return (c*c) % MOD;
}

int main(){
	int n;
	cin >> n;
	for(int i = 0; i < n; i++) cin >> a[i];
	map<LL,int> d;
	int n1 = 0;
	for(int i = 0; i < n; i++){
		p1.clear();
		p2.clear();
		for(LL j = 2; j < 2200; j++){
			LL p = j*j*j;
			while(a[i] % p == 0){
				a[i] /= p;
			}
			p = j;
			if(a[i] % (p*p) == 0){
				p2.push_back(p);
				a[i] /= (p*p);
			}
			if(a[i] % (p) == 0){
				p1.push_back(p);
				a[i] /= (p);
			}
		}
		if(a[i] > 1){
			LL c = sqrt(a[i]);
			if(c*c == a[i]){
				p2.push_back(c);
			} else {
				p1.push_back(a[i]);
			}
		}
		if(p1.empty() && p2.empty()){
			n1 = 1;
			continue;
		}
		LL h1 = 0;
		LL h2 = 0;
		for(int i = 0; i < p1.size(); i++){
			h1 += powmod(2350, p1[i]);
		}
		h1 %= MOD;
		for(int i = 0; i < p2.size(); i++){
			h2 += powmod(2350, p2[i]);
		}
		h2 %= MOD;
		d[h1-h2]++;
		d[h2-h1]++;
		d[h2-h1]--;
	}
	LL ans = 0;
	for(map<LL,int>::iterator it = d.begin(); it != d.end(); it++){
		ans += max(d[it->first],d[-it->first]);
	}
	ans /= 2;
	ans += n1;
	cout << ans << endl;
}

