using namespace std;

typedef long long llint;

const int MAXN = 100005;

llint n, jen, sol;
llint p[MAXN];
vector <int> v;
map < pair <llint, llint>, llint> mp[2];
set < pair <llint, llint> > st;

void precompute () {
    for (int i=2; i*i<MAXN; i++) {
        if (p[i] == 1) continue;
        for (int j=i*i; j<MAXN; j+=i) {
            p[j] = 1;
        }
    }
    for (int i=2; i<MAXN; i++) {
        if (p[i] == 0) v.push_back(i);
    }
}

void f (llint x) {
    vector < pair <llint, llint> > r;
    for (auto q : v) {
        llint cnt = 0;
        while (x % q == 0) {
            x /= q;
            cnt++;
        }
        if (cnt % 3 == 0) continue;
        r.push_back({q, cnt % 3});
    }
    if (x > 1) r.push_back({x, 1});
    if (r.empty()) {
        jen++;
        return;
    }
    llint tip = 0;
    if (r[0].second == 2) {
        tip = 1;
        for (int i=0; i<r.size(); i++) {
            r[i].second = 2 - r[i].second;
        }
    }
    llint a = 1, b = 1;
    for (int i=0; i<r.size(); i++) {
        a *= r[i].first;
        if (r[i].second == 2) b *= r[i].first;
    }
    mp[tip][{a, b}]++;
    st.insert({a, b});
}

int main () {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    precompute();
    cin >> n;
    for (int i=0; i<n; i++) {
        llint x;
        cin >> x;
        if (x == 1) jen++; else f(x);
    }
    for (auto par : st) {
        sol += max(mp[0][par], mp[1][par]);
    }
    cout << sol + !!jen;
    return 0;
}

