	if(a>b)
	{
		return a;
	}
	else
	{
		return b;
	}
}
void solve()
{
	scanf("%d",&n);
	for(int i=1;i<=n;i++)
	{
		scanf("%lld",&val[i]);

		ll tmp = val[i];
		ll rev=1;
		ll ori=1;
		for(int j=1;j<=cnt&&pri[j]<=tmp;j++)
		{
			if(tri[j]>1e10)break;
			if(tmp%pri[j]==0)
			{
				int c=0;
				while(tmp%pri[j]==0)
				{
					c++;
					tmp/=pri[j];
				}
				if(c%3==1)
				{
					rev*=two[j];
					ori*=pri[j];
				}
				else if(c%3==2)
				{
					rev*=pri[j];
					ori*=two[j];
				}
			}
		}
		//cout<<rev<<endl;
		//cout<<tmp*tmp<<endl;
		//cout<<1e18/rev<<endl;
		if(sqrt(1.0*tmp)*sqrt(1.0*tmp)==tmp)
		{
			rev*=sqrt(1.0*tmp);
			ori*=tmp;
		}
		else if(tmp*tmp<(1e18/rev))
		{
			ori*=tmp;
			rev*=tmp*tmp;
		}
		else
		{
			ori*=tmp;
			rev=-1;
		}
		con[ori]=rev;
		num[ori]++;

	}
	map<ll,int>::iterator it;
	int ans=0;
	/*
	for(it=num.begin(); it!=num.end(); it++)
	{
		cout<<it->first<<" "<<it->second<<" "<<con[it->first]<<endl;
	}
	*/
	for(it=num.begin(); it!=num.end(); it++)
	{
		if(it->first==1)continue;
		if(it->second==0)continue;
		ll tmp = it->first;
		ll s = con[tmp];
		if(num.find(s)==num.end())
		{
			ans+=it->second;
			it->second=0;
			continue;
		}
		//cout<<s<<" "<<num[s]<<endl;
		//cout<<it->second<<endl;
		ans+=max(it->second,num[s]);
		//cout<<"ans: "<<ans<<endl;
		it->second=0;
		num[s]=0;
	}
	if(num[1])ans++;
	printf("%d\n",ans);
}

