LL a[MAXN] , tr[MAXN];
int n , prim[MAXN] , is_pr[MAXN] , cnt;
map <int , int> M;
void pre(int m) {
	for (LL i = 1; i <= m; ++i) tr[i] = i * i * i;
	for (int i = 2; i <= m; ++i) {
		if(!is_pr[i]) prim[++cnt] = i;
		for (int j = 1; j <= cnt && prim[j] * i <= m; ++j) {
			is_pr[i * prim[j]] = 1;
			if(i % prim[j]) break; 
		}
	}
}
void update(LL &x) {
	for (int i = 2; i <= 3200; ++i) {
		if(tr[i] > x) break;
		while(x % tr[i] == 0) x /= tr[i];
	}
}
LL b[MAXN] , tot;
LL get_g(LL x) {
	LL res = 1;
	for (int i = 1; i <= cnt; ++i) {
		if(prim[i] > x) break;
		LL tot = 0;
		while(x % prim[i] == 0) x /= prim[i] , tot ++;
		if(tot) {
			tot = 3 - tot;
			while(tot -- > 0) res = res * prim[i];
		}
	}
	if(x == 1) return res;
	LL tmp = sqrt(x);
	if(tmp * tmp == x) return res * tmp;
	else return res * tmp * tmp;
}
int main() {
	scanf("%d" , &n);
	for (int i = 1; i <= n; ++i) scanf("%lld" , &a[i]);
	pre(3200);
	for (int i = 1; i <= n; ++i) {
		update(a[i]);
		if(!M[a[i]]) b[++tot] = a[i];
		M[a[i]] ++;
	}
	LL ans = 0;
	for (int i = 1; i <= tot; ++i) {
		if(b[i] == 1) ans ++;
		else {
			LL tmp = get_g(b[i]);
			ans += max(M[b[i]] , M[tmp]);
			M[b[i]] = M[tmp] = 0;
		}
	}
	printf("%lld" , ans);
	return 0;
}

