ll f(ll x, ll n) { return __int128_t(x)*x % n + 1 % n; }
ll pollard_single(ll n){
    ll i,x,y,p;
    if(is_prime(n)) return n;
    if(!(n&1)) return 2;
    for(i=1;i<40;i++){
        x=i; y=f(x,n); p=gcd(y-x,n);
        while(p==1) {x=f(x,n); y=f(f(y,n),n); p=gcd((y-x+n)%n,n)%n;}
        if(p==0||p==n) continue;
        return p;
    }
    assert(false);
}
V<ll> pollard(ll n) {
    if (n == 1) return {};
    ll x = pollard_single(n);
    if (x == n) return {x};
    V<ll> le = pollard(x);
    V<ll> ri = pollard(n/x);
    le.insert(end(le), begin(ri), end(ri));
    return le;
}


