		ll cnt = 0;
		while (x % i == 0)
			x /= i, cnt++;
		cnt %= 3;
		while (cnt --> 0)
			res *= i;
	}
	if (x > 1)
		res *= x;
	return res;
}
ll getrev(ll x) {
