                s[i] /= j;

                x /= j;
                x /= j;
                x /= j;
            }
            int cnt = 0;
            while (x % j == 0) {
                x /= j;
                ++cnt;
            }
            cnt = (3 - cnt) % 3;
            while (cnt--) {
