class Osak{
public:
    vector<int> div;
    Osak(int N) : div(N+1,0) {
        div[1] = 1;
        for(int i = 2; i*i <= N; ++i) {
            if(div[i]) continue;
            for(int j = i; j <= N; j += i) div[j] = i;
        }
    }
    inline vector<pair<long long,long long>> prime_factorization(int A) {
        assert(A < div.size());
        vector<int> tmp;
        while (A != 1) {
            int& p = div[A];
            tmp.push_back(p);
            A /= p;
        }
        sort(tmp.begin(),tmp.end());
        vector<pair<long long,long long>> ret;
        int prev = 0;
        for(int& p: tmp) {
            if(prev == p) ret.back().second++;
            else ret.push_back({p,1});
            prev = p;
        }
        return ret;
    }
};

/*
 * @title Eratosthenes
 * @docs md/math/Eratosthenes.md
 */
inline static vector<int> PrimeSieve(int N) {
    vector<int> res(N + 1, 1),sieve;
    res[0] = res[1%(N+1)] = 0;
    for (int i = 1; i*i <= N; i++) if (res[i]) for (int j = 2 * i; j <= N; j += i) res[j] = 0;
    for (int i = 2; i <= N; ++i) if (res[i]) sieve.push_back(i);
    return sieve;
}

int MillerRabin(const __uint128_t N) {
	if (N <= 1) return 0;
	if (N == 2) return 1;
	__uint128_t M = N - 1,cnt = 0;;
	for (; M % 2 == 0; M /= 2,cnt++);
	mt19937 mt(time(NULL));
	for (int k = 0; k < 10; k++) {
		__uint128_t a = uniform_int_distribution<__uint128_t>(2, N - 1)(mt), r = 1;
		for (__uint128_t K = M; K > 0; K >>= 1, (a *= a) %= N) if (K & 1) (r *= a) %= N;
		if (r == 1) continue;
		for (int i = 1; i < cnt && r != N - 1; i++) (r *= r) %= N;
		if (r != N - 1) return 0;
	}
	return 1;
}

// N <= 1e9 -> long long
// N > 1e9  -> int128
template<class T> int MillerRabin(const T N, int challenge = 10) {
	if (N <= 1) return 0;
	if (N == 2) return 1;
	T M = N - 1,cnt = 0;
	for (; M % 2 == 0; M /= 2,cnt++);
	mt19937 mt(time(NULL));
	for (int i = 0; i < 10; ++i) {
        T a = uniform_int_distribution<long long>(2, N - 1)(mt), r = 1;
		for (T K = M; K > 0; K >>= 1, (a *= a) %= N) if (K & 1) (r *= a) %= N;
		if (r == 1) continue;
		for (int j = 1; j < cnt && r != N - 1; j++) (r *= r) %= N;
		if (r != N - 1) return 0;
	}
	return 1;
}

/*
 * @title Gcd
 */
class Gcd{
public:
	inline static long long impl(long long n, long long m) {
		static constexpr long long K = 5;
		long long t,s;
		for(int i = 0; t = n - m, s = n - m * K, i < 80; ++i) {
			if(t<m){
				if(!t) return m;
				n = m, m = t;
			}
			else{
				if(!m) return t;
				n=t;
				if(t >= m * K) n = s;
			}
		}
		return impl(m, n % m);
	}
	inline static long long pre(long long n, long long m) {
		long long t;
		for(int i = 0; t = n - m, i < 4; ++i) {
			(t < m ? n=m,m=t : n=t);
			if(!m) return n;
		}
		return impl(n, m);
	}
	inline static long long gcd(long long n, long long m) {
		return (n>m ? pre(n,m) : pre(m,n));
	}
	inline static constexpr long long pureGcd(long long a, long long b) {
		return (b ? pureGcd(b, a % b):a);
	}
	inline static constexpr long long lcm(long long a, long long b) {
		return (a*b ? (a / gcd(a, b)*b): 0);
	}
	inline static constexpr long long extGcd(long long a, long long b, long long &x, long long &y) {
		if (b == 0) return x = 1, y = 0, a;
		long long d = extGcd(b, a%b, y, x);
		return y -= a / b * x, d;
	}
};


/**
 * Rho
 * @dependent Gcd
 * @dependent MillerRabin
 */
class Rho{
    array<int,6> seeds;
    inline long long rnd(long long x, long long n, int seed) {
        return (seeds[seed % 6]*x + seed) % n;
    }
    inline long long fact(long long n, int seed = 1) {
        if(!(n%2)) return 2;
        if(MillerRabin<__int128_t>(n)) return n;
        long long x=2,y=2,d=1,cnt=0;
        while(d==1) {
            cnt++;
            x = rnd(x,n,seed),y = rnd(rnd(y,n,seed),n,seed);
            d = Gcd::gcd(abs(x-y),n);
        }
        return fact(d,(d==n?seed:0)+1);
    }
public:
    Rho(void):seeds({3,5,7,11,13,17}) {
        //do nothing
    }
    inline vector<pair<long long,long long>> prime_factorization(long long N) {
        vector<int> tmp;
        while (N > 1) {
            long long p = fact(N);
            tmp.push_back(p);
            N /= p;
        }
        sort(tmp.begin(),tmp.end());

        vector<pair<long long,long long>> ret;
        int prev = 0;
        for(int& p: tmp) {
            if(prev == p) ret.back().second++;
            else ret.push_back({p,1});
            prev = p;
        }
        return ret;
    }
};


int main() {
    cin.tie(0);ios::sync_with_stdio(false);
    int N, SQRT_A = 100000, p3=0; cin >> N;
    int ans = 0;
    Rho rho;
    map<vector<pair<int,int>>,pair<int,int>> mp;
    for(int i = 0; i < N; ++i) {
        ll A; cin >> A;
        vector<pair<int,int>> l,r;
        auto pf = rho.prime_factorization(A);
        for(auto p:pf) if(p.second%3) l.push_back(p);
        if(l.empty()) {
            p3 = 1;
            continue;
        }
        if(l.back().first > SQRT_A) {
            ans++;
            continue;
        }
        for(auto& e:l) r.emplace_back(e.first,3-e.second);
        if(l.front().second > r.front().second) {
            swap(l,r);
            if(!mp.count(l)) mp[l]={0,0};
            mp[l].second++;
        }
        else {
            if(!mp.count(l)) mp[l]={0,0};
            mp[l].first++;
        }
    }
    for(auto& e:mp) ans += max(e.second.first,e.second.second);
    ans += p3;
    cout << ans << endl;
    return 0;
}

