LL isq(LL n) {
	LL m = sqrt(n + 0.5);
	for (LL i = max(1LL, m - 10); i <= m + 10; i++)
		if (i * i == n) {
			return i;
		}
	return -1;
}

bool get(LL n) {
	cnt = 0;
	if (n == 1) return false;
	for (int i = 0; i < pn; i++) {
		if (pri[i] > 3000) break;
		if (n % pri[i] == 0) {
			fac[cnt] = pri[i];
			num[cnt] = 0;
			while (n % pri[i] == 0) {
				n /= pri[i];
				num[cnt]++;
				if (num[cnt] == 3) num[cnt] = 0;
			}
			if (num[cnt]) cnt++;
		}
	}
	if (n == 1) return false;
	LL sq = isq(n);
	if (n != 1 && sq != -1) {
		fac[cnt] = sq;
		num[cnt++] = 2;
		return false;
	}
	if (n <= 100000LL && vis[n] == 0) {
		fac[cnt] = n;
		num[cnt++] = 1;
		return false;
	}
	return true;
}

