struct Node {
	vector<pii> p;
	Node() {p.clear();}
	bool operator < (const Node& c) const {
		if (p.size() != c.p.size()) return p.size() < c.p.size();
		for (int i = 0; i < p.size(); i++)
			if (p[i] < c.p[i]) return true;
		return false;
	}

	long long v1, v2;

	void gao() {
		v1 = 1, v2 = 1;
		for (int i = 0; i < p.size(); i++) {
			pii tmp = p[i];
			for (int j = 0; j < 3 - tmp.se; j++) v2 *= tmp.fi;
			for (int j = 0; j < tmp.se; j++) v1 *= tmp.fi;
		}
	}

} nd[N];

map<long long, int> sb;

int cc[N];

int id[N], cao[N];

bool cmp(int i, int j) {
	return cc[i] < cc[j];
}

