		for (int j = 0; j < cnt; j++)
			nd[i].p.push_back(mp(fac[j], num[j]));
		nd[i].gao();
		sb[nd[i].v1]++;
	}
	for (int i = 1; i <= n; i++) {
		if (cao[i]) continue;
		if (nd[i].p.size() == 0) {
			cc[i] = sb[nd[i].v2];
			cc[i]--;
			continue;
		}
		cc[i] = sb[nd[i].v2];
	}
	sort(id + 1, id + 1 + n, cmp);
	sb.clear();
	int ans = 0;
	for (int ii = 1; ii <= n; ii++) {
		int i = id[ii];
		if (cao[i]) {
			ans++;
			continue;
		}
		if (sb.count(nd[i].v2)) continue;
		sb[nd[i].v1]++;
		ans++;
	}
	printf("%d\n", ans);
	return 0;
}

