bool Cube[N],have[N],canuse[N];

ll bs(ll l,ll r,ll val)
{
	if(l==r) re l;
	if(r==l+1)
		if(r*r*r<=val) re r; else re l;
	ll m=(r+l)/2;
	if(m*m*m<=val) re bs(m,r,val); else bs(l,m,val);
}

bool cube(ll x)
{
	ll t=bs(1,2200,x);
	if(t*t*t==x) re true; else re false;
}

bool check(int x)
{
	for(int i=0;i<p.size()&&p[i]*p[i]<=x;i++)
		if(x%p[i]==0) re false;
	re true;
}

ll f(ll d)
{
	ll res=1;
	for(int i=0;i<2200;i++)
	{
		int cnt=0;
		while(d%p[i]==0)
		{
			cnt++;
			d/=p[i];
		}
		if(cnt>0)
		for(int j=0;j<3-cnt%3;j++)
			res*=p[i];
	}
	re res;
}

void fact(int x)
{
	ll t=s[x];
	ll res=1;
	for(int i=0;i<p.size();i++)
	{
		int cnt=0;
		while(t%p[i]==0)
		{
			cnt++;
			t/=p[i];
		}
		for(int j=0;j<cnt%3;j++)
			res*=p[i];
	}
	d[x]=res;
	if(t>1)have[x]=true;
	if(have[x])
	{
		bool done=false;
		if(t>100000)
		{
			P[x]=t;
			done=true;
			canuse[x]=true;
		}
		if(!done)
		{
			ll sq=(ll)(sqrt(t)+eps);
			if(sq*sq==t)
			{
				P[x]=sq;
				done=true;
				type[x]=2;
				canuse[x]=false;
			}
			if(!done)
			{
				if(pr.find(t)!=pr.end())
				{
					P[x]=t;
					done=true;
					canuse[x]=false;
					type[x]=1;
				}
				if(!done)
					canuse[x]=true;
			}
		}
	}
}

int main()
{
	ios:: sync_with_stdio(false);
	cin >> n;
	for(int i=0;i<n;i++)
	{
		cin >> s[i];
		all.insert(s[i]);
	}
	for(int i=2;i<100000;i++)
		if(check(i))p.pb(i);
	for(int i=0;i<p.size();i++)
		pr.insert(p[i]);
	for(int i=0;i<n;i++)
		if(cube(s[i]))
		{
			cubecnt++;
			Cube[i]=true;
		}
	if(cubecnt>=1)ans++;
	for(int i=0;i<n;i++)
	{
		if(Cube[i])continue;
		fact(i);
		if(!have[i])m[d[i]]++;
	}
	for(int i=0;i<n;i++)
		if(canuse[i])ans++;
	for(auto it=m.begin();it!=m.end();it++)
	{
		ll d=it->fi;
		ll cnt=it->se;
		if(done[d])continue;
		ll inv=f(d);
		ll invcnt=m[inv];
		done[inv]=true;
		ans+=max(cnt,invcnt);
	}
	for(int i=0;i<n;i++)
	{
		if(!have[i]||Cube[i]||canuse[i])continue;
		ll x;
		if(type[i]==1)
			x=d[i]*P[i]; else x=d[i]*P[i]*P[i];
		if(done[x])continue;
		ll invx;
		if(type[i]==1)
			invx=f(d[i])*P[i]*P[i]; else invx=f(d[i])*P[i];
		done[x]=true;
		done[invx]=true;
		ll cnt=all.count(x);
		ll invcnt=all.count(invx);
		ans+=max(cnt,invcnt);
	}
	cout << ans;
	return 0;
}

