#include <bits/stdc++.h>
using namespace std;
typedef long long int ll;
typedef pair<__int128,__int128> pll;
map <__int128, int> M;
set <pll> S;
// primality checking taken from anta's library
ll modmult(ll x, ll y, ll MOD) {
	ll a = x, r = 0;
	while(y) {
		if(y & 1)
			if((r += a) >= MOD) r -= MOD;
		if((a += a) >= MOD) a -= MOD;
		y >>= 1;
	}
	return r;
}
ll powmodll(ll a, unsigned long long k, const ll MOD) {
	a %= MOD;
	ll r = MOD == 1 ? 0 : 1;
	while(k) {
		if(k & 1)
			r = modmult(r, a, MOD);
		a = modmult(a, a, MOD);
		k >>= 1;
	}
	return (unsigned)r;
}

bool suspect(ll a, int s, ll d, ll n) {
	ll x = powmodll(a, d, n);
	if(x == 1) return true;
	for(int r = 0; r < s; ++r) {
		if(x == n - 1) return true;
		x = modmult(x, x, n);
	}
	return false;
}
// {2,7,61,-1}                 is for n < 4759123141 (= 2^32)
// {2,3,5,7,11,13,17,19,23,-1} is for n < 10^16 (at least)
bool isPrime(ll n) {
	if (n <= 1 || (n > 2 && n % 2 == 0)) return false;
	int test[] = {2,3,5,7,11,13,17,19,23,-1};
	ll d = n - 1; int s = 0;
	while (d % 2 == 0) ++ s, d /= 2;
	for(int i = 0; test[i] < n && test[i] != -1; ++i)
		if(!suspect(test[i], s, d, n)) return false;
	return true;
}
//
long long int get_sqrt(long long int x)
{
	long long int temp = sqrtl(x);
	for (long long int i = temp; i*i <= x; ++i)
	{
		if(i*i == x)
			return i;
	}
	return -1;
}
//
void get_fg(__int128 x, __int128 &f, __int128 &g)
{
	for (__int128 i = 2; i*i*i <= x; ++i)
	{
		if(x%i == 0)
		{
			int ctr = 0;
			while(x%i == 0)
			{
				x/=i;
				ctr++;
			}
			ctr%=3;
			for (int j = 0; j < ctr; ++j)
				f*=i;
			ctr = (3 - ctr)%3;
			for (int j = 0; j < ctr; ++j)
				g*=i;
		}
	}
	if(x > 1)
	{
		if(isPrime(x))
		{
			f*=x;
			g*=(x*x);
		}
		else
		{
			__int128 temp = get_sqrt(x);
			if(temp == -1)
			{
				f*=x;
				g*=(x*x);
			}
			else
			{
				f*=x;
				g*=temp;
			}
		}
	}
}
int main()
{
	int n;
	scanf("%d", &n);
	for (int i = 0; i < n; ++i)
	{
		long long int x;
		__int128 f = 1, g = 1;
		scanf("%lld", &x);
		get_fg(x, f, g);
		M[f]++;
		S.insert(pll(min(f,g),max(f,g)));
		// cout<<(long long int)f<<" "<<(long long int)g<<"\n";
	}
	int ans = 0;
	for (set <pll>::iterator it = S.begin(); it != S.end(); ++it)
	{
		__int128 f = (*it).first, g = (*it).second;
		if(f == g)
		{
			if(M[f])
				ans++;
		}
		else
		{
			ans+=max(M[f],M[g]);
		}
	}
	printf("%d\n", ans);
	return 0;
}

