			if (tmp % prime[j] == 0) {
				int cnt = 0;
				while(tmp % prime[j] == 0) ++cnt, tmp /= prime[j];
				cnt %= 3;
				if (cnt == 2) flag &= mul(anti, prime[j]), cur *= 1ll * prime[j] * prime[j];
				else if (cnt == 1) flag &= mul(anti, 1ll * prime[j] * prime[j]), cur *= prime[j];
			}
		}
		cur *= tmp;

		int x = (int)sqrt(tmp);
		if (1ll * x * x == tmp) flag &= mul(anti, x);
		else flag &= mul(anti, 1ll * tmp * tmp);

		++mp[cur];
		if (!flag) continue;

		if (anti != cur && mp[anti]) --mp[anti], --mp[cur], ++ans;
		else if (anti == cur) eq.push_back(cur);
	}
	sort(eq.begin(), eq.end());
	int cnt_eq = 0;
	for (int i = 0; i < (int)eq.size(); ++i) {
		if (i > 0 && eq[i] == eq[i - 1]) continue;
		++cnt_eq;
	} 

	cout << n - ans - (int)eq.size() + cnt_eq << endl;
}

