const int L = 2155;
bool is_composite[L];
vector<LL> ps, tris;

LL Reduce(LL v) {
  for (LL p : tris) {
    while (v%p == 0) v /= p;
  }
  return v;
}

LL Rev(LL v) {
  LL ret = 1;
  for (LL p : ps) {
    int e = 0;
    while (v%p == 0) {
      e++;
      v /= p;
    }

    assert(e <= 2);
    if (e == 1) ret *= p*p;
    else if (e == 2) ret *= p;
  }

  if (ret >= INF/v) return -1;
  ret *= v;
  if (ret >= INF/v) return -1;
  ret *= v;
  return ret;
}

int main() {
