void LinerSieve()
{
	npr[1]=true;
	for(int i=2;i<MAXP;i++)
	{
		if(!npr[i])
			prime[++pcnt]=i;
		for(int j=1;j<=pcnt&&prime[j]*i<MAXP;j++)
		{
			npr[prime[j]*i]=true;
			if(i%prime[j]==0)
				break;
		}
	}
}
int ans;
map<long long,int> cnt;
map<long long,bool> vis;
long long n,A[MAXN];
long long F(long long x)
{
	long long res=1;
	for(int j=1;j<=pcnt&&prime[j]*prime[j]<=x;j++)
		if(x%prime[j]==0)
		{
			int cnt=0;
			while(x%prime[j]==0)
				x/=prime[j],cnt++;
			cnt%=3;
			for(int k=1;k<=cnt;k++)
				res*=prime[j];
		}
	if(x!=1&&x<=prime[pcnt])
		res*=x;
	if(x>prime[pcnt])
		ans++,vis[res]=true;
	return res;
}

