static void GetPrimes() {
	for (int i = 0; i <= MAXPRIME; ++i) IsPrime[i] = true;
	IsPrime[0] = IsPrime[1] = false;

	IsPrime[2] = true;
	for (int j = 2 * 2; j <= MAXPRIME; j += 2) IsPrime[j] = false;
	for (int i = 3; i <= MAXPRIME; i += 2)
	{
		if (!IsPrime[i]) continue;

		for (int j = i * 2; j <= MAXPRIME; j += i)
		{
			IsPrime[j] = false;
		}
	}

	NumPrimes = 0;
	for (int i = 0; i < sizeof(ArrayPrimes) / sizeof(*ArrayPrimes); ++i) ArrayPrimes[i] = 0;
	SetPrimes.clear();

	for (int i = 1; i <= MAXPRIME; ++i)
		if (IsPrime[i]) {
			SetPrimes.insert(i);
			ArrayPrimes[NumPrimes++] = i;
		}
}

enum GetResult
{
	Normal,
	Big,
	One
};
static GetResult Get(s64 num, s64& norm, s64 &pair)
{
	norm = 1; pair = 1;
	for (auto prim : SetPrimes) {
		if (num == 1) break;
		int c = 0;
		while (num % prim == 0) { ++c; num /= prim; }

		c %= 3;

		if (c > 0) {
			for (int i = 0; i < c; ++i) norm *= prim;
			for (int i = 0; i < 3 - c; ++i) pair *= prim;
		}
	}

	if (num != 1) { norm *= num; return Big; }
	else if (norm == 1) return One;
	else return Normal;
}

