					if(td==2)tc+=(1LL)<<cnt;
					cnt++;
					tb=(tb*INT_MAX+p[b])%MOD;
				}
			}
		}
		if(ta!=1){
			td=lower_bound(pp.begin(),pp.end(),ta)-pp.begin();
			if(pp[td]==ta)tb=(tb*INT_MAX+p[td])%MOD,tc+=(1LL)<<cnt;
			else tb=(tb*INT_MAX+ta)%MOD;
			cnt++;
		}
		vx.pb(mp(mp(tb,cnt),tc));
	}
	sort(vx.begin(),vx.end());
	F1(a,0,n){
		ta=vx[a].se;
		tb=(1<<(vx[a].fi.se))-1;
		if(ta>=(ta^tb))vy.pb(mp(ta,0));
		else vy.pb(mp(ta^tb,1));
		if(a==n-1||vx[a].fi!=vx[a+1].fi){
			if(tb==0)ans++;
			else{
				sort(vy.begin(),vy.end());
				ta=tb=0;
				F1(b,0,vy.size()){
					if(vy[b].se)ta++;
					else tb++;
					if(b==vy.size()-1||vy[b].fi!=vy[b+1].fi){
						ans+=max(ta,tb);
						ta=tb=0;
					}
				}
			}
			vy.clear();
		}
	}
	printf("%lld\n",ans);
	#ifdef LOCAL_PROJECT
    system("pause");
    #endif
    return 0;
}

