// 素数判定 O( sqrt(N) log log N )
// 0からNに対して素数->1、それ以外->0の配列を返す関数
vector<int> Primes(int N){
  vector<int> A(N + 1 , 1);
  A[0] = A[1] = 0;
  for(int i = 2; i * i <= N ; i++) 
    if(A[i]==1) for(int j = i << 1 ; j <= N; j += i) A[j] = 0;
  return A;
}

// 因数 O( sqrt(N) log log N )
// 0からNに対して素数->1、それ以外->最小の素数である因数、の配列を返す
vector<int> Factors(int N){
  vector<int> A(N + 1 , 1);
  A[0] = A[1] = 0;
  for(int i = 2; i * i <= N ; i++) 
    if(A[i]==1) for(int j = i << 1 ; j <= N; j += i) A[j] = i;
  return A;
}

// オイラーのトーシェント関数 φ(N)=(Nと互いに素なN以下の自然数の個数)
vector<int> EulersTotientFunction(int N){
  vector<int> ret(N + 1 , 0);
  for(int i = 0; i <= N ; i++) ret[i] = i; 
  for(int i = 2 ; i <= N ; i++){
    if(ret[i] == i)
      for(int j = i; j <= N; j += i) ret[j] = ret[j] / i * (i - 1);
  }
  return ret;
}

// 約数列挙 O(sqrt(N))
// Nの約数を列挙した配列を返す
vector<long long> Divisor(long long N){
  vector<long long> v;
  for(long long i = 1; i * i <= N ; i++){
    if(N % i == 0){
      v.push_back(i);
      if(i * i != N) v.push_back(N / i);
    }
  }
  return v;
}

// 素因数分解
// 因数をkey、そのべきをvalueとするmapを返す
// ex) N=12 -> m={ (2,2) , (3,1) }
map<long long,int> PrimeFactors(long long N){
  map<long long,int> m;
  for(long long i=2; i * i <= N; i++)
    while(N % i == 0) m[i]++ , N /= i;
  if(N != 1) m[N]++;
  return m;
}

// 原始根 modでrが原始根かどうかを調べる
bool PrimitiveRoot(long long r , long long mod){
  r %= mod; if(r == 0) return false;
  auto modpow = [](long long a,long long b,long long m)->long long{
    a %= m; long long ret = 1;
    while(b){
      if(b & 1) ret = a * ret % m;
      a = a * a % m;
      b >>= 1;
    }
    return ret;
  };
  map<long long,int> m = PrimeFactors(mod - 1);
  each(x , m){
    if(modpow(r , (mod - 1) / x.fi , mod ) == 1) return false;
  }
  return true;
}

// 拡張ユークリッド ax+by=gcd(a,b)の解
// 返り値　最大公約数
long long extgcd(long long a,long long b, long long &x, long long &y){
  if(b == 0){
    x = 1; y = 0; return a;
  }
  long long d = extgcd(b , a%b , y , x);
  y -= a / b * x;
  return d;
}

// ブール代数ライブラリ
// Point. 乗法の単位元は-1 (UNIT & a = aを満たすUNITであるため)
struct BA{
  unsigned long long x;
  BA(): x(0){}
  BA(unsigned long long y):x(y){}

  BA operator += (const BA &p){
    x = x ^ p.x;
    return (*this);
  }
  BA operator *= (const BA &p){
    x = x & p.x;
    return (*this);
  }

  BA operator+(const BA &p)const {return BA(*this) += p;}
  BA operator*(const BA &p)const {return BA(*this) *= p;}
  bool operator==(const BA &p) const { return x == p.x; }
  bool operator!=(const BA &p) const { return x != p.x; }

  friend ostream &operator<<(ostream &os,const BA &p){
    return os << p.x;
  }
  friend istream &operator>>(istream &is, BA &a){
    unsigned int t;
    is >> t;
    a = BA(t);
    return (is);
  }
};

void solve(){
  ini(N);
  vl a(N); in(a);
  auto prime = Primes(100001);  
  vector<ll[2]> m(N);
  each(x , m) x[0] = x[1] = 1;
  rep1(p , 3000){
    if(prime[p] == 0) continue;
    rep(i , N){
      if(a[i] % p == 0){
        int cnt = 0;
        while(a[i] % p == 0) cnt++ , a[i] /= p;
        if(cnt % 3 == 1) m[i][0] *= p;
        if(cnt % 3 == 2) m[i][1] *= p;
      }
    }
  }

  auto isSquare = [&](ll a){
    return a == round( sqrt(double(a) ) );
  };

  ll ans = 0;

  map<P , int> M;
  rep(i , N){
    if(a[i] != 1){
      if(a[i] <= 100000 && prime[a[i]]) m[i][0] *= a[i];
      else if(isSquare(a[i])) m[i][1] *= round(sqrt(double(a[i])));
      else {
        ans++; continue;
      }
    }
    trc(i , m[i][0] , m[i][1]);
    M[P(m[i][0] , m[i][1])]++;
  }
  while(!M.empty()){
    auto it = M.begin();
    P val = it->first;
    int c = it->second;
    if(val == P(1 , 1)){
      ans++; M.erase(it); continue;
    }
    auto it2= M.find( P(val.second , val.first) );
    if(it2 != M.end()){
      ans += max(c , it2->second);
    }
    else{
      ans += it->second;
    }    
    M.erase(it);
    M.erase( P(val.second , val.first ));
  }
  out(ans);
}

