using namespace std;
typedef long long ll;

int n,tot,ans;
ll p[3333];
bool tag[3333];
ll a[111111],b[111111];
map<ll,int> m;

void init()
{
    for(int i=2; i<3333; i++)
    {
        if(!tag[i]) p[tot++]=i;
        for(int j=0; j<tot&&i*p[j]<3333; j++)
        {
            tag[i*p[j]]=1;
            if(i%p[j]==0) break;
        }
    }
}

void pre(int id)
{
    ll x=1,y=1;
    for(int i=0; p[i]*p[i]*p[i]<=a[id]; i++)
    {
        int cnt=0;
        while(a[id]%p[i]==0) cnt++,a[id]/=p[i];
        cnt%=3;
        if(cnt==1) x*=p[i],y*=p[i]*p[i];
        else if(cnt==2) x*=p[i]*p[i],y*=p[i];
    }
    if(a[id]!=1)
    {
        x*=a[id];
        ll sq=(ll)sqrt(a[id]);
        if(sq*sq==a[id]) y*=sq;
        else y*=a[id]*a[id];
    }
    a[id]=x,b[id]=y,m[x]++;
}

int main()
{
    init();
    cin>>n;
    for(int i=0; i<n; i++) cin>>a[i],pre(i);
    if(m[1]) ans++,m[1]=0;
    for(int i=0; i<n; i++) if(m[a[i]]) ans+=max(m[a[i]],m[b[i]]),m[a[i]]=m[b[i]]=0;
    cout<<ans;
    return 0;
}

