const int MAXN = 1e5 + 5;
const ll MAX_V = 1e10 + 5;

ll ar[MAXN];
map<ll, int> cnt;
bool not_prime[MAXN];
vector<ll> primes;
set<ll> visit;

int main() {
    for (int i = 2; i < MAXN; i++) {
        if (!not_prime[i]) primes.pb(( ll )i);
        for (int j = i * 2; j < MAXN; j += i)
            not_prime[j] = true;
    }
    int n;
    scanf("%d", &n);
    for (int i = 1; i <= n; i++) {
        scanf("%lld", &ar[i]);
        ll &num = ar[i];
        for (ll j : primes) {
            if (j * j * j > num) break;
            int cur = 0;
            while (num % j == 0) {
                num /= j;
                cur++;
            }
            cur %= 3;
            while (cur--) num *= j;
        }
        //printf("%d) %lld\n", i, num);
        cnt[num]++;
    }
    int ans = 0;
    for (int i = 1; i <= n; i++) {
        ll num = ( ll )cbrt(ar[i]);
        if (ar[i] == 1) continue;
        if (visit.count(ar[i])) continue;
        int other = 0;
        for (ll j = num, c = j * j * j; c <= MAX_V; j++, c = j * j * j) {
            if (c % ar[i] == 0) {
                other += cnt[c / ar[i]];
                if (other > 0) {
                    visit.insert(c / ar[i]);
                    break;
                }
            }
        }
        visit.insert(ar[i]);
        //printf("for %lld other is %d\n", ar[i], other);
        ans += max(cnt[ar[i]], other);
    }
    if (cnt[1] > 0) ans++;
    printf("%d\n", ans);
    return 0;
}

