#define FOR(i, a, b) for (int i=a; i<b; i++)
#define F0R(i, a) for (int i=0; i<a; i++)

#define f first
#define s second

vector<ll> prime;

void genprime() {
	FOR(i,2,100001) {
		bool f = 0;
		F0R(j,prime.size()) {
			if (i % prime[j] == 0) {f = 1; break;}
			if (prime[j]*prime[j]>i) break;
		}
		if (!f) prime.pb(i);
	}
}

pair<ll,ll> fac(ll x) {
	ll x1 = 1, x2 = 1;
	F0R(i,prime.size()) {
		int c = 0;
		while (x % prime[i] == 0) c++, x /= prime[i];
		c %= 3;
		if (c == 1) x1 *= prime[i], x2 *= (prime[i]*prime[i]);
		else if (c == 2) x1 *= (prime[i]*prime[i]), x2 *= prime[i];
		if (prime[i]*prime[i]>x) break;
	}
	x1 *= x, x2 *= (x*x);
	return mp(x1,x2);
}

int main() {
	ios_base::sync_with_stdio(0);cin.tie(0);
	map<pair<ll,ll>,ll> num;
	map<ll,bool> done;

	int N; cin >> N;
	genprime();
	// cout << prime.size() << "\n";

	F0R(i,N) {
		ll x; cin >> x;
		// cout << x << " " << fac(x).f << " " << fac(x).s << "\n";
		num[fac(x)]++;
	}

	ll ans = 0;
	for (auto i: num) {
		if (done[i.f.f]) continue;
		if (i.f.f == i.f.s) ans++;
		else if (num.find(mp(i.f.s,i.f.f)) != num.end()) {
			ans += max(num[mp(i.f.s,i.f.f)],i.s);
			done[i.f.s] = 1;
		} else ans += i.s;
	}
	cout << ans;
}

