void solve() {
    for (int i = 1; i <= N; ++i) {
        llint remain = a[i];
        for (llint j = 2; j * j * j <= a[i]; ++j) {
            llint j3 = j * j * j;
            llint j2 = j * j;

            while (a[i] % j3 == 0) {
                a[i] /= j3;
                remain /= j3;
            }
            if (remain % j2 == 0) {
                rev[i] *= j;
            }
            else if (remain % j == 0) {
                rev[i] *= j2;
            }

            if (rev[i] > INF) rev[i] = INF;
            while (remain % j == 0) remain /= j;
        }

        llint sqrt_rem = trunc(sqrt(remain));
        if (sqrt_rem * sqrt_rem == remain) {
            rev[i] *= sqrt_rem;
            if (rev[i] > INF) rev[i] = INF;
        }
        else {
            rev[i] *= remain;
            if (rev[i] > INF) rev[i] = INF;
            rev[i] *= remain;
            if (rev[i] > INF) rev[i] = INF;
        }
    }

    for (int i = 1; i <= N; ++i) if (rev[i] != INF) {
        ++sl[a[i]];
