//考虑把质数幂次模3，那么每个集合唯一对应一个集合，不同集合对之间独立，可以贪心。 

int main()
{
	scanf("%d",&n);
	for(int i=1; i<=n; i++)
	{
		scanf("%lld",&x);
		map<ll,int> fact;
		divide(x,fact);
		ll y=1,z=1;
		for(auto &u:fact)
		{
			int k=u.second%3;
			if(k==1)
				y*=u.first,z*=u.first*u.first;
			if(k==2)
				y*=u.first*u.first,z*=u.first;
		}
		s.insert(y);
		rev[y]=z;
		cnt[y]++;
	}
	while(!s.empty())
	{
		ll x=*s.begin(),y=rev[x];
		ans+=(x==1?1:max(cnt[x],cnt[y]));
		s.erase(x);s.erase(y);
	}
	printf("%d",ans);
	return 0;
}

