const int N = 1e5 + 5;
using namespace std;

map <long long, int> mymap;
int n, ans, pri[N], npri[N], nprime;
long long a[N], b[N];

long long po(long long x, int c){
    if (c == 0) return 1;
    if (c == 1) return x;
    return x * x;
}

int main(){
    for (int i = 2; i < N; i++) if (!npri[i]) {pri[++nprime] = i; for (int j = i; j < N; j += i) npri[j] = true;}
    scanf("%d", &n);
    for (int i = 1; i <= n; i++){
        long long x; scanf("%lld", &x);
        a[i] = b[i] = 1;
        for (int j = 1; j <= nprime && pri[j] <= a[i]; j++){
            int cnt = 0;
            while (x % pri[j] == 0) x /= pri[j], cnt++;
            cnt %= 3;
            if (cnt == 1) a[i] *= po(pri[j], 1), b[i] *= po(pri[j], 2);
            if (cnt == 2) a[i] *= po(pri[j], 2), b[i] *= po(pri[j], 1);
        }
        if (x != 1) a[i] *= po(x, 1), b[i] *= po(x, 2);
        mymap[a[i]]++;
    }
    for (int i = 1; i <= n; i++){
        if (mymap[a[i]] == 0) continue;
        if (a[i] == 1) {ans++; mymap[1] = 0; continue;}
        ans += max(mymap[a[i]], mymap[b[i]]), mymap[a[i]] = mymap[b[i]] = 0;
    }
    printf("%d", ans);
}

#include <bits/stdc++.h>
using namespace std;
bool is_cube(long long N){
  long long tv = 10000;
  long long fv = -1;
  while (tv - fv > 1){
    long long mid = (tv + fv) / 2;
    if (mid * mid * mid >= N){
      tv = mid;
    } else {
      fv = mid;
    }
  }
  return tv * tv * tv == N;
}
long long is_square(long long N){
  long long c = (long long) (sqrt(N) + 0.001);
  if (c * c == N){
    return c;
  } else if ((c + 1) * (c + 1) == N){
    return c + 1;
  } else if ((c - 1) * (c - 1) == N){
    return c - 1;
  } else {
    return -1;
  }
}
int main(){
  int N;
  cin >> N;
  vector<long long> s(N);
  for (int i = 0; i < N; i++){
    cin >> s[i];
  }
  int cnt = 0;
  vector<long long> t;
  for (int i = 0; i < N; i++){
    if (is_cube(s[i])){
      cnt++;
    } else {
      t.push_back(s[i]);
    }
  }
  int ans = 0;
  if (cnt >= 1){
    ans++;
  }
  map<long long, int> A;
  map<long long, int> B;
  map<pair<long long, long long>, int> C;
  int M = t.size();
  for (int i = 0; i < M; i++){
    long long t2 = t[i];
    for (long long j = 2; j * j * j <= t[i]; j++){
      while (t2 % (j * j * j) == 0){
        t2 /= j * j * j;
      }
    }
    t[i] = t2;
    long long c = is_square(t[i]);
    if (c != -1){
      B[c]++;
    } else {
      bool is_C = false;
      for (long long j = 2; j * j * j <= t[i]; j++){
        if (t[i] % j == 0 && is_square(j) == -1 && is_square(t[i] / j) != -1){
          C[make_pair(is_square(t[i] / j), j)]++;
          is_C = true;
          break;
        }
        if (t[i] % (j * j) == 0 && is_square(t[i] / (j * j)) == -1){
          assert(t[i] % (j * j * j) != 0);
          C[make_pair(j, t[i] / (j * j))]++;
          is_C = true;
          break;
        }
      }
      if (!is_C){
        A[t[i]]++;
      }
    }
  }
  set<long long> val;
  for (auto P : A){
    val.insert(P.first);
  }
  for (auto P : B){
    val.insert(P.first);
  }
  for (long long x : val){
    ans += max(A[x], B[x]);
  }
  set<pair<long long, long long>> val2;
  for (auto P : C){
    long long x = P.first.first;
    long long y = P.first.second;
    val2.insert(make_pair(min(x, y), max(x, y)));
  }
  for (auto P : val2){
    long long x = P.first;
    long long y = P.second;
    ans += max(C[make_pair(x, y)], C[make_pair(y, x)]);
  }
  cout << ans << endl;
}

