#define MAXQ 2500
bool isPrime[(MAXQ + 1)];
int pList[(MAXQ + 1)];

int sizeP;

int pairV(int x) {
  int val = 1;

  for (int i = 0; i < sizeP; i++) {
    int cnt = 0;
    int primeV = pList[i];
    while (1) {
      if (x % primeV == 0) {
        x /= primeV;
        cnt++;
      } else {
        break;
      }
    }
    if (cnt == 1)
      val *= pList[i] * pList[i];
    else if (cnt == 2)
      val *= pList[i];
    if (x == 1) break;
  }

  int sqX = sqrt(x);
  if (sqX * sqX == x)
    val *= sqX;
  else
    val *= x * x;
  return val;
}
