  isPrime[0] = isPrime[1] = false;
  for (int i = 2; i <= MAXQ; ++i) {
    if (isPrime[i]) {
      pList[cnt++] = i;
      for (int j = i * 1LL * i; j <= MAXQ; j += i) {
