using namespace std;

typedef long long ll;
const int N = 1e5 + 10;
ll n, s[N], a[N], b[N], ans;  // a[i] 存的是 s[i] 的最简数，b[i] 是 a[i] 的补数
map<ll, int> num;
map<ll, bool> vis;
int mark[N], p[N], tot;  // 10^{10/3} 以内质数有 326 个，10^{10/3}~10^5 以内质数有 9267 个

void euler(int n) {
    rep(i, 2, n) {
        if (!mark[i]) p[++tot] = i;
        for (int j = 1; j <= tot && p[j] * i <= n; j++) {
            mark[p[j] * i] = 1;
            if (i % p[j] == 0) break;
        }
    }
}

int main() {
    euler(100000);
    cin >> n;
    rep(i, 1, n) scanf("%lld", &s[i]);

    ll k, tmp;
    rep(i, 1, n) {
        k = s[i]; a[i] = b[i] = 1;
        rep(o, 1, tot) {  // 2200 ^ 3 约等于 1e10
            if (k == 1) break;
            ll j = p[o];
            if (j * j * j >= 1e10) break;
            if (mark[j]) continue;

            tmp = 1ll * j * j * j;
            while (k % tmp == 0) k /= tmp;  // 简化
            tmp = 1ll * j * j;
            if (k % tmp == 0) a[i] *= tmp, b[i] *= j;
            else if (k % j == 0) a[i] *= j, b[i] *= tmp;
            while (k % j == 0) k /= j;
        }
        if (k > 1) {
            tmp = (ll)sqrt(k);
            if (tmp * tmp == k) a[i] *= k, b[i] *= tmp;
            else a[i] *= k, b[i] *= k * k;
        }
    }
    rep(i, 1, n) num[a[i]]++;
    rep(i, 1, n) {
        if (vis[a[i]]) continue;
        vis[a[i]] = vis[b[i]] = 1;
        ans += (a[i] == b[i] ? 1 : max(num[a[i]], num[b[i]]));
    }
    printf("%lld\n", ans);
    return 0;
}

