	map<long long, long long> sq;
	for (long long i = 2; i < 101010; i++) {
		if (is_prime[i]) {
			ps.push_back(i);
			sq[i * i] = i;
			for (int j = i * 2; j < 101010; j += i) {
				is_prime[j] = false;
			}
		}
	}

	map<map<long long, int>, map<long long, int>> inv;
	map<map<long long, int>, int> cnt;
	for (int i = 0; i < n; i++) {
		map<long long, int> p, q;
		long long b = a[i];
		for (int j = 0; ps[j] <= 2500; j++) {
			int cnt = 0;
			while (a[i] % ps[j] == 0) a[i] /= ps[j], cnt++;
			cnt %= 3;
			if (cnt > 0) {
				p[ps[j]] = cnt;
				q[ps[j]] = 3 - cnt;
			}
		}
		if (a[i] != 1) {
			if (sq.count(a[i])) {
				p[sq[a[i]]] = 2;
				q[sq[a[i]]] = 1;
			} else {
				p[a[i]] = 1;
				q[a[i]] = 2;
			}
		}
		inv[q] = p;
		inv[p] = q;
		cnt[p]++;
	}

	long long ans = 0;
	for (auto &kv : inv) {
		auto &x = kv.first;
		auto &y = kv.second;
		if (x == y) {
			ans++;
		} else {
			if (x < y) {
				ans += max(cnt[x], cnt[y]);
			}
		}
	}
	cout << ans << endl;
}

