#include <bits/stdc++.h>
using LL = long long;
const int N = 1e5 + 5;
int visited[N], p[N], tot;

void Prime() {
  for (int i = 2; i < N; i++) {
    if (!visited[i]) p[tot++] = i;
    for (int j = 0; j < tot && i * p[j] < N; j++) {
      visited[i * p[j]] = p[j];
      if (i % p[j] == 0) break;
    }
  }
}

template<class T>
void in(T& x) {
  char c;
  while (isspace(c = getchar()));
  x = c - '0';
  while (!isspace(c = getchar())) x = 10 * x + c - '0';
}

int main() {
  std::ios::sync_with_stdio(0);
  Prime();
  int n;
  in(n);
  std::map<LL, LL> match, numbers;
  int zero = 0;
  for (int i = 0; i < n; i++) {
    LL x;
    in(x);
    LL now = 1, pair = 1;
    for (int j = 0; j < tot && 1LL * p[j] * p[j] <= x; j++) if (x % p[j] == 0) {
      int cnt = 0;
      while (x % p[j] == 0) {
        x /= p[j];
        cnt++;
      }
      cnt %= 3;
      for (int i = 0; i < cnt; i++) now *= p[j];
      for (int i = 0; i < (3 - cnt) % 3; i++) pair *= p[j];
    }
    if (x == 1 && now == 1) zero++;
    else if (x == 1) {
      numbers[now]++;
      match[now] = pair;
    }
    else if (x != 1 && x < N) {
      now *= x;
      pair *= x * x;
      numbers[now]++;
      match[now] = pair;
    }
  }
  int nouse = 0;
  for (auto &p: numbers) {
    auto number = p.first;
    if (!numbers.count(match[number])) continue;
    nouse += std::min(numbers[number], numbers[match[number]]);
  }
  std::cout << n - zero - nouse / 2 + (zero > 0) << std::endl;
  return 0;
}

