pii a[maxn];
bool isPrime[maxn];
int plist[maxn], pnum = 0;

map<lli, int> mp;

int main() {
//    freopen("xx/01.in", "r", stdin);
    isPrime[0] = 1;
    isPrime[1] = 1;
    for (int i = 2; i <= 4000; i++) {
        if (!isPrime[i]) {
            pnum++;
            plist[pnum] = i;
        }
        for (int j = 1; j <= pnum; j++) {
            if (i * plist[j] > 4000)
                break;
            isPrime[i * plist[j]] = 1;
            if (!(i % plist[j]))
                break;
        }
    }
    int n, ans = 0;
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        scanf("%lld", &a[i].first);
        lli tmp = a[i].first;
        a[i].first = 1;
        a[i].second = 1;
        for (int j = 1; j < pnum && 1ll * plist[j] * plist[j] * plist[j] <= tmp; j++) {
            int cnt = 0;
            while (tmp % (1ll * plist[j] * plist[j] * plist[j]) == 0) {
                tmp /= (1ll * plist[j] * plist[j] * plist[j]);
            }
            while (tmp % plist[j] == 0) {
                tmp /= plist[j];
                cnt++;
            }
            if (cnt == 1) {
                a[i].first *= plist[j];
                a[i].second *= (1ll * plist[j] * plist[j]);
            } else if (cnt == 2) {
                a[i].first *= (1ll * plist[j] * plist[j]);
                a[i].second *= plist[j];
            }
        }
        if (tmp != 1) {
            a[i].first *= tmp;
            lli x = (lli) sqrt(tmp);
            if (x * x == tmp) {
                a[i].second *= x;
            } else if (tmp <= 100000) {
                a[i].second *= (tmp * tmp);
            } else {
                a[i].second = 0;
            }
        }
        mp[a[i].first]++;
    }
    if(mp[1]) ans ++, mp[1] = 0;
    for(int i = 0; i < n; i ++){
        ans += max(mp[a[i].first],mp[a[i].second]);
        mp[a[i].first] = mp[a[i].second] = 0;
    }
    printf("%d\n",ans);
    return 0;
}

