map<LL,LL> cnt;
const int maxn=1e5+5;
const int maxpc=1000+5;
int notprime[maxpc];
vector<LL> prime;
inline void getprime()
{
    LL up=sqrt(maxpc+0.5);
    for(LL i=2;i<=up;i++)
        for(LL j=i*i;j<maxpc;j+=i)  notprime[j]=1;
    for(LL i=2;i<maxpc;i++) if(!notprime[i]) prime.PB(i);
}
vector<pair<LL , LL > > showclass;
LL num[maxn];
vector<pii> fac[maxn];
int N;
inline void getallfac()
{
    for(const LL& p:prime)
        for(int i=0;i<N;i++)
        {
            if(num[i]%p==0)
            {
                LL t=0;
                while(num[i]%p==0) t++,num[i]/=p;
                fac[i].PB(MP(p,t));
            }
        }
    for(int i=0;i<N;i++) if(num[i]!=1) fac[i].PB(MP(num[i],1));
}
int main()
{
    getprime();
    scanf("%d",&N);
    for(int i=0;i<N;i++) scanf("%lld",num+i);
    getallfac();
    for(int i=0;i<N;i++)
    {
        LL myclass=1,revclass=1;
        for(const auto& p:fac[i])
        {
            for(int j=0;j<(p.S%3);j++) myclass*=p.F;
            for(int j=0;j<(3-(p.S%3))%3;j++) revclass*=p.F;
        }
        cnt[myclass]++;

        if(myclass > revclass) swap(myclass,revclass);
        showclass.PB(MP(myclass,revclass));
    }

    sort(ALL(showclass));
    showclass.resize(unique(ALL(showclass)) - showclass.begin());

    LL ans=0;
    for(const auto& p:showclass)
    {
        if(p.F==1) ans+=(cnt[p.F]?1:0);
        else ans+=max(cnt[p.F],cnt[p.S]);
    }
    printf("%lld\n",ans);
}

