  V<lint> a(n); for (int i = 0; i < n; ++i) cin >> a[i];
  auto ps = sieve(2, 2154);
  for (int i = 0; i < n; ++i) {
    for (lint p : ps) {
      while (a[i] % (p * p * p) == 0) {
        a[i] /= p * p * p;
      }
    }
  }
  int res = 0;
  map<lint, int> mp;
  for (int i = 0; i < n; ++i) {
    if (a[i] == 1) {
      res = max(res, 1);
    } else {
      ++mp[a[i]];
    }
  }
  ps = sieve<int>(2, 1e5);
  for (const auto& e : mp) {
    lint b = 1;
    for (lint p : ps) {
      if (e.first % p == 0) {
        b *= p;
        if (e.first % (p * p)) {
          b *= p;
        }
      }
    }
    if (!mp.count(b)) {
      res += e.second;
    } else if (e.first < b) {
      res += max(e.second, mp[b]);
    }
  }
  cout << res << '\n';
}

