typedef uint64_t T;
static const T MAX = std::numeric_limits<uint32_t>::max();
static T p(T v)
{ 
    for(T i=2,i3; (i3=i*i*i)<=v; ++i)
        while(v%i3==0) v/=i3;
    return v;
}
int main()
{
    std::cin.tie(0);
    std::ios_base::sync_with_stdio(false);
    for(int N; std::cin >> N; )
    {
        std::vector<T> AS(N);
        std::map<T,int> b;
        for(auto& v:AS)
        {
            T t; std::cin >> t;
            v=t=p(t);
            ++b[t];
        }
        b[1]=std::min(1,b[1]);
        int m=0;
        for(auto v:AS)
        {
            if(!b.count(v)) continue;
            T w;
            if(v>MAX || !b.count(w=p(v*v))) w=v;
            m+=std::max(b[v],b[w]);
            b.erase(v);
            b.erase(w);
        }
        std::cout << m << std::endl;
    }
