				a[i]/=j*j*j;
	sort(a+1,a+n+1);
	for(int i=n;i>=1;i--)
		if(a[i]!=a[i+1])
			d[i]=1;
		else
			d[i]=d[i+1]+1;
	for(int i=1;i<=n;i++)
