int main() {
    int n;
    cin >> n;
    vector<ll> a(n);
    for (auto& x : a) cin >> x;

    vector<int> is_prime(1000001, 1);
    vector<ll> primes;
    primes.reserve(is_prime.size());

    is_prime[0] = 0;
    is_prime[1] = 0;

    for (int i = 2; i * i < is_prime.size(); ++i) {
        if (is_prime[i]) {
            primes.push_back(i);

            for (int j = i * i; j < is_prime.size(); j += i) {
                is_prime[j] = 0;
            }
        }
    }

    map<ll, int> cnt;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < primes.size(); ++j) {
            if (primes[j] * primes[j] * primes[j] > a[i]) break;

            while (a[i] % (primes[j] * primes[j] * primes[j]) == 0) {
                a[i] /= primes[j] * primes[j] * primes[j];
            }
        }
        cnt[a[i]]++;
    }

    int ans = 0;
    if (cnt[1] > 0) ans++;

    for (auto& x : cnt) {
        if (x.first == 1) continue;

        auto z = x.first;
        auto y = __int128(z) * z;
        for (int j = 0; j < primes.size(); ++j) {
            if (y < primes[j] * primes[j] * primes[j]) break;
            while (y % (primes[j] * primes[j] * primes[j]) == 0) {
                y /= primes[j] * primes[j] * primes[j];
            }
        }

        if (!cnt.count(y)) {
            ans += x.second;
        } else if (x.first > y) {
            ans += max(x.second, cnt[y]);
        }
    }

    cout << ans << endl;
}

