	for(int i = 1 ; i <= n ; ++i)   {
		int x, y, z;    cin >> x;
		y = z = 1;
		for(int j = 0 ; p[j] * p[j] * p[j] <= x ; ++j) {
			if(x % p[j])    continue;
			int exp = 0;
			while(x % p[j] == 0)    {
				exp = (exp + 1) % 3;
				x /= p[j];
			}
			if(!exp)    continue;
			y *= p[j];
			z *= p[j];
			if(exp < 2) z *= p[j];
			else        y *= p[j];
		}
		if(x > 1)   {
			int t = sqrt(x);
			if(t * t == x)  z *= t, y *= t * t;
			else            y *= x, z *= x * x;
		}
		s[y]++;
		f[y] = z;
	}

	if(s.count(1))  {
		ans = 1;
		s.erase(1);
	}

