map<T, Int> factorize(T x){
  map<T, Int> res;
  for(Int i=2;i<=500||i*i*i<=x;i++){
    while(x%i==0){
      x/=i;
      res[i]++;
    }
  }
  if(sq.count(x)) res[sq[x]]+=2,x=1;
  if(x!=1) res[x]++;
  return res;
}

