map<ll, int> ntarray(ll a) {
	map<ll, int> res;
	for(ll i = 2; i * i <= a; i++) {
		while(a % i == 0) {
			res[i]++;
			a /= i;
		}
	}
	if(a != 1) res[a]++;
	vector<ll> ng;
	for(auto& p : res) {
		p.sec %= 3;
		if(p.sec == 0) ng.pb(p.fst);
	}
	for(auto v : ng) {
		res.erase(v);
	}
	return res;

}

int N;
map<map<ll, int>, int> G;

void solve() {
	cin >> N;
	rep(i, 0, N) {
		ll a; cin >> a;
		G[ntarray(a)]++;
	}

	int cnt = 0;
	for(auto pp : G) {
		// debug(vector<pl>(all(pp.fst)), pp.sec);
		map<ll, int> tmp;
		int a = pp.sec;
		for(auto p : pp.fst) {
			tmp[p.fst] = 3 - p.sec;
		}
		if(tmp.empty()) {
			cnt += 2;
			continue;
		}
		int b = 0;
		if(G.find(tmp) != G.end()) b = G[tmp];
		if(b == 0) cnt += 2 * a;
		else cnt += max(a, b);

	}
	cout << cnt / 2 << "\n";
}

