{
	if(!b) return 1;
	int t = binpow(a, b/2, modv);
	if(b&1) return t*t%MOD[modv]*a%MOD[modv];
	return t*t%MOD[modv];
}
int C(int a, int b)
{
	return a*INT_MAX+b;
