bool is_prime(long long n){
	if(n == 2 || n == 3) return true; 
	if(n % 6 != 1 && n % 6 != 5) return false; 
	long long t = n; 
	for(long long k = 2; k * k <= n; k++){
		if(t % k == 0) return false; 
	}
	return true; 
}
int main(){
	int N; cin >> N; 
	long long S[100010] = {}; 
	for(int i = 0; i < N; i++) cin >> S[i]; 
	long long O[100010] = {}; 
	long long T[100010] = {}; 
	fill(O, O+N, 1); fill(T, T+N, 1); 
	map<pair<long long, long long>, int> M; 
	map<pair<long long, long long>, bool> B; 
	vector<long long> P; 
	for(long long i = 2; i < 100100; i++){
		if(is_prime(i)) P.push_back(i); 
	}
	for(int i = 0; i < N; i++){
		long long now = S[i]; 
		for(long long k = 0; P[k] < 2160; k++){
			if(now % (P[k] * P[k] * P[k]) == 0) now /= P[k] * P[k] * P[k]; 
			if(now == 1) break; 
		}
		long long now2 = now; 
		for(long long k = 0; P[k] * P[k] <= now2; k++){
			if(now % (P[k] * P[k]) == 0){
				T[i] *= P[k]; now /= P[k] * P[k]; 
			}
			if(now == 1) break; 
		}
		O[i] = now; 
		M[make_pair(O[i], T[i])] ++; 
	}
	int ans = 0; 
	if(M[make_pair(1, 1)]){
		ans ++; B[make_pair(1, 1)] = true; 
	}
	for(int i = 0; i < N; i++){
		if(B[make_pair(O[i], T[i])]) continue; 
		ans += max(M[make_pair(O[i], T[i])], M[make_pair(T[i], O[i])]); 
		B[make_pair(O[i], T[i])] = true; 
		B[make_pair(T[i], O[i])] = true; 
	}
	cout << ans << endl; 
}

