ll no_cubic(ll x) {
    for (ll i = 2; i * i * i <= x; i++) {
        while (x % (i * i * i) == 0) {
            x /= (i * i * i);
        }
    }
    return x;
}

ll get_pair(ll x) {
    ll sq = 1;
    ll tx = x;
    for (int t = 2; (ll)t * t * t <= tx; t++) {
        if (tx % ((ll)t * t) == 0) {
            sq *= t;
            tx /= t;
            tx /= t;
        } 
    }
    ll sl = x / (sq * sq);
    ll ans = sq * sl;
    if (ans > INF / sl) {
        return -1;
    } else {
        return ans * sl;
    }
}

signed main() {
