class divide_solver {
  bool is_prime[24];

  long long mul(long long x, long long y, long long mod) {
    return ((x * y - (long long) (((long double) x * y + 0.5) / mod) * mod) % mod + mod) % mod;
  }

  long long qpow(long long x, long long y, long long mod) {
    long long result = 1;
    for (; y; y >>= 1, x = mul(x, x, mod)) {
      if (y & 1) {
        result = mul(result, x, mod);
      }
    }
    return result;
  }

  long long randll() {
    return ((long long) rand() << 30) | (rand() << 15) | rand();
  }

  bool miller_rabin(long long n) {
    if (n <= 23 && is_prime[n]) {
      return true;
    } else if (n < 2 || !(n & 1) || !(n % 3)) {
      return false;
    } else {
      long long m = n - 1;
      int t = 0;
      while (!(m & 1)) {
        m >>= 1;
        ++t;
      }
      for (int times = 0; times < 10; ++times) {
        long long a = randll() % (n - 1) + 1, x = qpow(a, m, n), y;
        for (int j = 0; j < t; ++j, x = y) {
          if ((y = mul(x, x, n)) == 1 && x != 1 && x != n - 1) {
            return false;
          }
        }
        if (x != 1) {
          return false;
        }
      }
    }
    return true;
  }

  long long pollard_rho(long long n) {
    long long k = 2, x = randll() % n, y = x, c = randll() % (n - 1), p = 1;
    for (long long i = 1; p == 1; ++i) {
      x = (mul(x, x, n) + c) % n;
      p = __gcd(abs(x - y), n);
      if (i == k) {
        k <<= 1;
        y = x;
      }
    }
    return p;
  }

  void divide(long long n, vector<long long>& pfactor) {
    if (n == 1) {
      return;
    } else if (miller_rabin(n)) {
      pfactor.push_back(n);
    } else {
      long long x = n;
      while (x == n) {
        x = pollard_rho(x);
      }
      divide(x, pfactor);
      divide(n / x, pfactor);
    }
  }

 public:
  divide_solver() {
    is_prime[2] = true;
    is_prime[3] = true;
    is_prime[5] = true;
    is_prime[7] = true;
    is_prime[11] = true;
    is_prime[13] = true;
    is_prime[17] = true;
    is_prime[19] = true;
    is_prime[23] = true;
  }

  vector<long long> solve(long long n) {
    vector<long long> result;
    divide(n, result);
    sort(result.begin(), result.end());
    return result;
  }
};

