int powe(int x, int y)  {
    if(!y) return 1LL;
    int mid = powe(x, y/2);
    if(y & 1) return mid * mid * x;
    else return mid * mid;
}

void decomp(int x, int pos){
    divn = 0;
    //cout << "?spm x=" << x << '\n';
    for(int i = 1; i <= 450; ++i) if(x % prim[i] == 0)   {
        int tmp = 0, v = prim[i];
        while(x % v == 0)   {
            tmp ++; x /= v;
        }
        di[++divn] = ii(v, tmp);
    }

    int maxl = 1ll, maxr = 1ll;
    FOR(i, 1, divn) {
        //cout << di[i].fi << ' ' << di[i].se << '\n';
        int tmpl = di[i].se % 3;
        int tmpr = 3 - (di[i].se % 3 == 0 ? 3 :(di[i].se % 3));
        maxl *= 1ll * powe(di[i].fi, tmpl);
        maxr *= 1ll * powe(di[i].fi, tmpr);
    }
    maxl *= x;
    if(square[x] == true) maxr *= 1ll * (long long)sqrt(x);
    else maxr *= 1ll * x * x;

    //cout << "en?? " << maxl << ' ' << maxr << '\n';
    f[maxl] ++;
    in[pos] = maxl, op[pos] = maxr;
}

