vector<int> genPrimes(int n) {
    vector<bool> isPrime(n, true);
    for (int i = 2; i * i <= n; ++i) {
        if (isPrime[i]) {
            for (int j = i * i; j <= n; j += i) {
                isPrime[j] = false;
            }
        }
    }
    vector<int> ret;
    for (int i = 2; i <= n; ++i) {
        if (isPrime[i]) {
            ret.push_back(i);
        }
    }
    return ret;
