    map<map<ull,int>, ll> memo;
    rep(i, n) {
        rho(a[i]);
        for (auto& x : rho_ret) 
            if (x.se % 3 == 0) 
                rho_ret.erase(x.fi);
            else 
                x.se %= 3;
        memo[rho_ret]++;
    }
    ll flag = 0;
    ll ret = 0;
    for (auto&& x : memo) {
        if (x.fi.size() == 0) {
            flag = 1;
        } else {
            auto rev = x.fi;
            for (auto&& y : rev) {
                y.se = 3 - y.se;
            }
            if (memo.count(rev)) {
                ret += max({memo[x.fi], memo[rev]});
                memo.erase(x.fi), memo.erase(rev);
            } else {
                ret += memo[x.fi];
                memo.erase(x.fi);
            }
        }
    }
    ret += flag;
    cout << ret << endl;
