inline void solve( i64 x ) {
    i64 num1 = 1, num2 = 1;

    efor( y, pri ) {
        i32 cnt = 0;

        while( x % y == 0 ) {
            cnt ++;
            x /= y;
        }

        cnt %= 3;
        if( cnt != 0 ) {
            if( cnt == 1 ) {
                num1 *= y;
                num2 *= y * y;
            } else {
                num1 *= y * y;
                num2 *= y;
            }
        }
    }

    if( x != 1 ) {
        i64 y = sqrt( x );

        if( y * y == x ) {
            num1 *= y * y;
            num2 *= y;
        } else {
            num1 *= x;
            num2 *= x * x;
        }
    }

    mmp1[num1] ++;
    mmp2[num1] = num2;

    return;
}

