vector<ll> Primes;
set<ll> m;

P f(ll x){
	P ret = P(1,1);
	rep(i,Primes.size()){
		ll p = Primes[i];
		ll cnt = 0;
		while(x%p ==0){
			x /= p;
			cnt ++;
		}
		if(cnt%3 == 1){
			ret.fr *= p;
			ret.sc *= p*p;
		}
		else if(cnt%3 == 2){
			ret.fr *= p*p;
			ret.sc *= p;
		}
		if(ret.sc > 10000000000)return P(-1,-1);
	}
	if(m.find(x) != m.end()){
		ret.fr *= x;
		ret.sc *= (ll)(sqrt((ld)x)+0.5);
		x = 1;
	}
	if(x != 1)return P(-1,-1);
	else return ret;
}

