__int128 a[N<<1];
int main(){
	scanf("%d",&n);
	for(int i=2;i<N;i++){
		if(!vi[i])	b[++now]=i;
		for(int j=1;j<=now&&b[j]*i<N;j++){
			vi[i*b[j]]=1;
			if(i%b[j]==0)	break;
		}
	}
	for(int i=1;i<=n;i++){
		__int128 val=1,res=1;
		long long x;

		scanf("%lld",&x);
		int k=pow(x+0.5,1.0/3);
		for(int i=1;i<=now;i++)
			if(b[i]>k)	break;
			else{
				int d=0;
				while(x%b[i]==0)
					x/=b[i],++d;
				d%=3;
				if(!d)	continue;
				if(d==1)	val*=b[i],res*=b[i]*b[i];
				else	val*=b[i]*b[i],res*=b[i];
			}
		k=sqrt(x),val*=x;
		if(k*k==x)	res*=k;
		else	res*=(__int128)x*x;
		pos[val]=res,pos[res]=val,++ma[val],a[++cnt]=res,a[++cnt]=val;
	}
	sort(a+1,a+cnt+1);
	n=unique(a+1,a+cnt+1)-a-1;
