        long long a;
        scanf("%lld", &a);

        long long tmp = a;
        long long k = 1, n = 1;
        for (auto &p: primes) {
            int cnt = 0;
            while (tmp % p == 0) {
                tmp /= p;
                ++cnt;
            }
            if (cnt % 3 == 1) {
                k *= 1LL*p*p;
                n *= 1LL*p;
            }
            if (cnt % 3 == 2) {
                k *= 1LL*p;
                n *= 1LL*p*p;
            }

        }
        n *= tmp;

        long long s = sqrt(tmp);
        while (s*s < tmp) ++s;
        while (s*s > tmp) --s;
        if (s*s == tmp) {
            k *= s;
        }
        else {
            k *= tmp*tmp;
        }

        x[i] = k; y[i] = n;
        if (n > 1) {
            gs[k]++;
        }
    }

    int ans = 0;
