typedef long long ll;

ll sq(ll x){
	ll s=0,e=1<<20;
	while(e-s>1){
		ll m=(s+e)/2;
		if((m-1)*(m-1)<x)s=m;
		else e=m;
	}
	if(s*s==x)return s;
	return -1;
}

