using namespace std;

vector<int64_t> sieve(int64_t n){
    vector<int64_t> ret;
    vector<bool> is_prime(n+1);
    for(int64_t i=2; i<=n; i++) is_prime[i] = true;
    for(int64_t i=2; i<=n; i++){
        if(is_prime[i]){
            ret.push_back(i);
            for(int64_t j=2*i; j<=n; j+=i) is_prime[j] = false;
        }
    }
    return ret;
}

int main(){
    int N;
    int64_t S[100000];
    cin >> N;
    for(int i=0; i<N; i++) cin >> S[i];

    int64_t cbrt = pow(1e10, 1.0/3);
    while(cbrt*cbrt*cbrt <= 1e10) cbrt++;
    auto primes3 = sieve(cbrt);

    map<int64_t, int> num;
    bool has_one = false;
    for(int i=0; i<N; i++){
        for(int64_t p : primes3){
            int64_t cube = p*p*p;
            while(S[i] % cube == 0) S[i] /= cube;
        }
        if(S[i] == 1){
            has_one = true;
        }else{
            num[S[i]]++;
        }
    }

    auto primes2 = sieve(1e5);
    map<int64_t, int64_t> pr_sqrt;
    for(int64_t p : primes2) pr_sqrt[p*p] = p;

    set<int64_t> used;
    int ans = has_one;
    for(auto& p : num){
        int64_t a = p.first;
        if(used.count(a)) continue;
        int64_t b = (pr_sqrt.count(a) ? pr_sqrt[a] : (a <= 1e5 ? a*a : -1));
        if(num.count(b)){
            used.insert(b);
            ans += max(num[a], num[b]);
        }else{
            ans += num[a];
        }
    }

    cout << ans << endl;
    return 0;
}

