                int cnt=0;
                while(now%d==0){
                    now/=d;
                    cnt++;
                }
                cnt%=3;
                REP(j,cnt)key*=d;
                cnt=(3-cnt)%3;
                REP(j,cnt)rev*=d;
            }
        }
        if(q.count(now)){
            key*=now;
            rev*=q[now];
        }else{
            key*=now;
            rev*=now*now;
        }
        if(key==1)
            ans=1;
        else{
            if(key<=rev)
                memo[P(key,rev)].fi++;
            else memo[P(rev,key)].se++;
        }
    }
    for(auto &it:memo){
        //printf("%lld %lld:%lld %lld\n",it.fi.fi,it.fi.se,it.se.fi,it.se.se);
        res+=max(it.se.fi,it.se.se);
    }
    printf("%d\n",res+ans);
    return 0;
}

