LL T[100111], U[100111];
map<LL, LL> mp, inv;

LL safe_mul(LL x, LL y) {
    if (x < 0 || y < 0) return -1;
    if ((double)x * (double)y > 1e15) return -1;
    return x * y;
}


int main() {
