	    LL t = (LL)prime[p] * prime[p] * prime[p];
	    if (t > S[i]) break;
	    int c = 0;
	    while (S[i] % prime[p] == 0) {
		S[i] /= prime[p];
		c++;
	    }

	    c %= 3;
	    REP (j, c) T[i] *= prime[p];
	    REP (j, (3-c)%3) U[i] = safe_mul(U[i], prime[p]);
	}

	if (LL p = is_sq(S[i])) {
	    U[i] = safe_mul(U[i], p);
	} else {
	    U[i] = safe_mul(safe_mul(U[i], S[i]), S[i]);
	}
	T[i] *= S[i];
	if (U[i] != -1) inv[T[i]] = U[i];
	mp[T[i]]++; 
