struct prime{
  static const int N = 1e8;
  vector<ll> pr;
  ll z[N+1];
  prime(){
    for (int i=2; i<=N; ++i) {
      if(!z[i]) pr.push_back(z[i]=i);
      for(int j=0, k, p=pr.size(); j<p && (k=pr[j])<=z[i] && i*k<=N; ++j) z[i*k]=k;
    }
  }
  bool isPrime(ll n){
    if(n<2||n%2==0) return n==2;
    __uint128_t t=n-1, d=t/(t&-t);
    for(__uint128_t a:{2,325,9375,28178,450775,9780504,1795265022})if(a%n){
      t=d;
      a=modPow(a,t,n);
      while(t!=n-1 && a!=1 && a!=n-1) a=a*a%n, t=t*2%n;
      if(a!=n-1 && t%2==0) return false;
    }
    return true;
  }
  ll pollard_single(ll n) {
    auto f = [&](ll x) { return (__int128_t(x) * x + 1) % n; };
    if (isPrime(n)) return n;
    if (n % 2 == 0) return 2;
    ll st = 0;
    while (true) {
      st++;
      ll x = st, y = f(x);
      while (true) {
        ll p = __gcd((y - x + n), n);
        if (p == 0 || p == n) break;
        if (p != 1) return p;
        x = f(x);
        y = f(f(y));
      }
    }
  }

  V<ll> pollard(ll n) {
    if(n<=N){
      V<ll> ret;
      while(n>1){
        ret.pb(z[n]);
        n /= z[n];
      }
      return ret;
    }
    ll x = pollard_single(n);
    if (x == n) return {x};
    V<ll> le = pollard(x);
    V<ll> ri = pollard(n / x);
    le.insert(le.end(), ri.begin(), ri.end());
    return le;
  }
} pr;
