bool is_cube(ll x){
  ll ld = 1, rd = sqrt(x) + 1;
  while(rd - ld > 1){
    ll md = (rd + ld) / 2;
    if(md * md * md <= x)ld = md;
    else rd = md;
  }
  return ld * ld * ld == x;
}

