  return x;

}

P tp(ll x){

  ll A=1,B=1; bool f1=0,f2=0;

  for(int i=0;; i++){

    int cnt=0; ll q=prime[i];

    if(q==0){
      if(x==1) break;
      if(x>1){
        A*=x; f1=1;
      }
      break;
    }
    if(x==1) break;
    while(x%q==0){
      x/=q;
      cnt++;
    }

    if(cnt==1){ A*=q; f1=1;}
    else if(cnt==2){ B*=q*q; f2=1;}

  }

  int a;

  if(f1&&!f2) a=1;
  else if(!f1&&f2) a=2;
  else if(f1&&f2){
    if(A*B<A*A*sqrt(B)) a=3;
    else a=4;
  }
  else if(!f1&&!f2) a=5;

  if(f1&&!f2) return P(a,A*A);
  else if(!f1&&f2) return P(a,sqrt(B));
  else if(f1&&f2) return P(a,A*A*sqrt(B));
  else if(!f1&&!f2) return P(a,1);

}

