using namespace std;

int n;
long A[100000];

vector<int> primes;
map<long, long> squared;
set<long> cubed;
map<long, long> factorize(long n) {
  map<long, long> ret;
  for (int p : primes) {
    int cnt = 0;
    while (n % p == 0) {
      ++cnt;
      if (cnt == 3) cnt = 0;
      n /= p;
    }
    if (cnt > 0) {
      ret[p] = cnt;
    }
  }

  if (n == 1) return ret;
  if (squared.count(n)) {
    long p = squared[n];
    ret[p] = 2;
  } else {
    ret[n] = 1;
  }
  return ret;
}

bool is_prime(int n) {
  for (int i = 2; i * i <= n; ++i) {
    if (n % i == 0) return false;
  }
  return true;
}

void pre() {
  for (long i = 1; i < 40000; ++i) {
    squared[i * i] = i;
    cubed.insert(i * i * i);
  }

  for (int i = 2; i < 2155; ++i) {
    if (is_prime(i)) primes.push_back(i);
  }
}

map<long, long> anti(const map<long, long>& mp) {
  map<long, long> ret;
  for (auto&& p : mp) {
    ret[p.first] = 3 - p.second;
  }
  return ret;
}

map<map<long, long>, int> mp;
int main() {
  pre();
  cin >> n;
  for (int i = 0; i < n; ++i) cin >> A[i];

  bool cube_exists = false;
  for (int i = 0; i < n; ++i) {
    if (cubed.count(A[i])) {
      cube_exists = true; 
      continue;
    }
    ++mp[factorize(A[i])];
  }

  int sum = 2 * cube_exists;
  for (auto&& p : mp) {
    auto rev = anti(p.first);

    auto it = mp.find(rev);
    if (it == mp.end()) {
      sum += 2 * p.second;
    } else {
      sum += max(it->second, p.second);
    }
  }
  cout << sum / 2 << endl;
}

