vector<ll> p;

ll proc(int x) {
	ll y = a[x];
	ll prod = 1, prod1 = 1;
	for (int prime : p) {
		int ct = 0;
		while (y%prime == 0) {
			y /= prime; ct++;
		}

		ct %= 3;
		if (ct == 0)
			continue;
		prod *= prime;
		if (ct == 2)
			prod *= prime;
		if (prod1 != -1) {
			prod1 *= prime;
			if (ct == 1)
				prod1 *= prime;
		}
		if (prod1 > M*M*M)
			prod1 = -1;
	}

	if (y > 1 && sq[y] != 0) {
		int prime = sq[y], ct = 0;
		while (y%prime == 0) {
			y /= prime; ct++;
		}

		ct %= 3;
		prod *= prime;
		if (ct == 2)
			prod *= prime;
		if (prod1 != -1) {
			prod1 *= prime;
			if (prod1 > M*M*M)
				prod1 = -1;
			if (prod1 != -1 && ct == 1)
				prod1 *= prime;
		}
		if (prod1 > M*M*M)
			prod1 = -1;
	}

	prod *= y;
	if (prod1 != -1) {
		prod1 *= y;
		if (prod1 > M*M*M)
			prod1 = -1;
		if (prod1 != -1)
			prod1 *= y;
		if (prod1 > M*M*M)
			prod1 = -1;
	}

	red[x] = prod, comp[x] = prod1;
	m[red[x]]++;
}

