	for (int i = 0; i < n; ++i)
		cin >> a[i];
	for (ll i = 1; i <= 100000; ++i)
		sq[i*i] = i;
	for (int i = 2; i < M; ++i) {
		if (pr[i] == 0) {
			p.push_back(i);
			for (int k = 2*i; k < M; k += i)
				pr[k] = 1;
		}
	}

	ll tot = 0;
	for (int i = 0; i < n; ++i)
		proc(i);
	for (int i = 0; i < n; ++i) {
		if (red[i] == 1)
			continue;
		tot += max(m[red[i]], m[comp[i]]);
		m[red[i]] = m[comp[i]] = 0;
	}
	if (m[1] > 0)
		tot++;
	cout << tot << endl;
}

