#include <bits/stdc++.h>

using namespace std;

#define LL long long
#define FOE(i, s, t) for (int i = s; i <= t; i++)

LL ret;
map<LL, int> M;

int n;

vector<LL> S;

#define K 600001
int p[K];
int p1[K], cnt, cnt2;
LL p2[K], p3[K];

void init(){
        FOE(i, 2, 100000) if (!p[i]){
                for (int j = i + i; j <= 100000; j += i) p[j] = 1;
                cnt++;
                p1[cnt] = i;
                if (i <= 2155) {
                        cnt2 = cnt;
                        p3[cnt] = (LL)i * i * i;
                        p2[cnt] = (LL)i * i;
                }
        }
}

LL decompose(LL id){
        FOE(i, 1, cnt2){
                LL m3 = p3[i];
                while (id % m3 == 0) id /= m3;
        }
        return id;
}

void handle(LL id){
        if (id == 1){
                ret++;
                return;
        }

        LL opp = 1, cnt3 = M[id];

        LL left = id;

        FOE(i, 1, cnt2){
                LL m2 = p2[i];
                LL m1 = p1[i];

                if (id % m2 == 0) {
                        opp *= m1; left /= m2;
                }
                else if (id % m1 == 0) {
                        opp *= m2; left /= m1;
                }

                if (opp > (LL)10000000000){
                        ret += cnt3; return;
                }
        }

        LL y = sqrt(left);
        if (y * y == left && !p[y]){
                opp = opp * y;
        }
        else {
                if (left > (LL)100000 || opp * left > (LL)10000000000){
                        ret += cnt3; return;
                }
                opp = opp * left * left;
        }
        if (opp > (LL)10000000000){
                ret += cnt3; return;
        }

        LL cnt2 = M[opp];
        if (cnt2 > cnt3) cnt3 = cnt2;
        ret += cnt3;

        M[opp] = 0; M[id] = 0;
}

int main(){
        scanf("%d", &n);
        init();
//      cout << cnt2 << endl;
        FOE(i, 1, n){
                LL d; scanf("%lld", &d);

                d = decompose(d);
//              cout << "decomposed: " << d << endl;
                if (d != -1) {
                        M[d]++; S.push_back(d);
                }
        }

        sort(S.begin(), S.end());
        FOE(i, 1, n) if (i == 1 || S[i - 2] != S[i - 1]){
                LL foc = S[i - 1];
                handle(foc);
        }

        cout << ret << endl;
        return 0;
}

