    safe_map<ll, int> cnt;
    safe_map<ll, ll> rev;
    int n; cin>>n;
    rep(i, n) {
        ll x; cin>>x;
        if(x==1) cnt[1]++, rev[1]=1;
        else {
            ll val=1, rval=1;
            for(int i=2; 1LL*i*i*i<=x; i++) {
                if(x%i==0) {
                    int cnt=0;
                    while(x%i==0) x/=i, cnt++;
                    cnt%=3;
                    rep(j, cnt) val*=i;
                    rep(j, (3-cnt)%3) rval*=i;
                }
            }
            if(x>1) {
                if(sqrt(x)==trunc(sqrt(x))&&isprime[trunc(sqrt(x))]) rval*=trunc(sqrt(x));
                else {
                    if(rval>1e11/x/x) rval=-1;
                    else rval*=x*x;
                }
                val*=x;
            }
            cnt[val]++; rev[val]=rval;
        }
    }
    int ans1=0, ans2=0;
    for(auto& it: cnt) {
        cout<<it.fi<<' '<<it.se<<' '<<rev[it.fi]<<endl;
        if(rev[it.fi]!=it.fi&&cnt.find(rev[it.fi])!=cnt.end()) ans1+=max(it.se, cnt[rev[it.fi]]);
        else if(rev[it.fi]==it.fi) ans2++;
        else ans2+=it.se;
    }
    cout<<ans1/2+ans2<<endl;
}

