void solve() {
    int n, ans = 0;
    cin >> n;
    vi a(n);
    for (int i = 0; i < n; i++) {
        cin >> a[i];
        int res = 1;
        for (int d = 2; d * d * d <= a[i]; d++) {
            int cube = d * d * d;
            while(a[i] % cube == 0)
                a[i] /= cube;
        }
        int x = a[i];
        for (int d = 2; d * d <= x; d++) {
            if(x % d)
                continue;
            if(x % (d * d) == 0) {
                res *= d;
                x /= d * d;
            }
            else {
                res *= d * d;
                x /= d;
            }
        }
        if(x != 1)
            res *= x * x;
        rev[a[i]] = res;
        mp[a[i]]++;
    }
    for (auto u : mp) {
        if(u.first == 1)
            continue;
        ans += max(u.second, mp[rev[u.first]]);
        mp[rev[u.first]] = 0;
        mp[u.first] = 0;
    }
    cout << ans + !!mp[1];
}

