vector<ll> prime, square;

void genprime() {
	FOR(i,2,100001) {
		bool f = 0;
		F0R(j,prime.size()) {
			if (i % prime[j] == 0) {f = 1; break;}
			if (prime[j]*prime[j]>i) break;
		}
		if (!f) prime.pb(i), square.pb(i*i);
	}
}

pair<ll,ll> fac(ll x) {
	ll x1 = 1, x2 = 1;
	F0R(i,prime.size()) {
		int c = 0;
		while (x % prime[i] == 0) c++, x /= prime[i];
		c %= 3;
		if (c == 1) x1 *= prime[i], x2 *= square[i];
		else if (c == 2) x1 *= square[i], x2 *= prime[i];
		if (square[i]>x) break;
	}
	x1 *= x, x2 *= (x*x);
	return mp(x1,x2);
}

