bool prime(int v)
{
    for (int d = 2; d * d <= v; ++d)
    {
        if (v % d == 0)
            return 0;
    }

    return 1;
}


void smain()
{
    int n;
    cin >> n;

    vi kek(n);
    for (int i = 0; i < n; ++i)
        cin >> kek[i];

    vi pr;
    for (int d = 2; d * d * d <= 1e10; ++d)
    {
        if (prime(d))
            pr.push_back(d);
    }

    vi div = pr;

    int ans = 0;
    __int128 a = 1;

    map<map<int, int>, int> flex;
    for (int v : kek)
    {
        map<int, int> cur;
        for (int d : pr)
        {
            while (v % d == 0)
            {
                cur[d]++;
                v /= d;
            }
        }

        if (v != 1) {
            int c = sqrt(v);
            for (int i = max(0LL, c - 5); i <= c + 5; ++i) {
                if (i * i == v) {
                    cur[i]++;
                    cur[i]++;
                    div.push_back(i);
                }
                else if (i == c + 5)
                    cur[v]++;
            }
        }

        map<int, int> cur2;
        for (auto &p : cur)
        {
            p.second %= 3;
            if (p.second)
                cur2[p.first] = p.second;
        }

        if (SZ(cur2) == 0)
            ans = 1;
        else
            flex[cur2]++;
    }

    map<map<int, int>, int> used;

    for (auto p : flex) {
        if (used.count(p.first))
            continue;

        map<int, int> cur;
        for (auto p1 : p.first)
            cur[p1.first] = 3 - p1.second;

        if (flex.count(cur))
        {
            ans += max(p.second, flex[cur]);
            used[cur] = 1;
        }
        else
            ans += p.second;
    }

    cout << ans;
}

