map<ll, ll> opp_tbl;

vector<PI> inv(const vector<PI> &v) {
  vector<PI> opp(v.size());
  REP(i, 0, v.size()) {
    opp[i] = PI(v[i].first, 3 - v[i].second);
  }
  return opp;
}

/*
 * n |-> (r, (...)^3/r)
 * n / r = (...)^3
 * if n is not factored into a product of p <= 10^5, or the opposite is not in range, return (-1, ?).
 */
pair<ll, ll> opposite(ll v) {
  int oldv = v;
  vector<PI> fact;
  int p = 2;
  int e = 0;
  while ((v >= 2 || e >= 1) && p <= 3000) {
    if (v % p == 0) {
      v /= p;
      e++;
    } else {
      if (e % 3 != 0) {
	fact.push_back(PI(p, e % 3));
      }
      e = 0;
      p++;
    }
  }
  // Is v square?
  ll sq = sqrt(v);
  if (v >= 2 && v == sq * sq) {
    fact.push_back(PI(sq, 2));
    v = 1;
  }
  if (v >= 2) {
    return pair<ll, ll>(-1, -1);
  }
  vector<PI> opp = inv(fact);

  ll f_ll = 1, opp_ll = 1;
  REP(i, 0, fact.size()) {
    REP(j, 0, fact[i].second) {
      f_ll *= fact[i].first;
    }
  }
  REP(i, 0, opp.size()) {
    REP(j, 0, opp[i].second) {
      opp_ll *= opp[i].first;
      if (opp_ll > 10000000000) {
	return pair<ll, ll>(-1, -1);
      }
    }
  }
  opp_tbl[f_ll] = opp_ll;
  opp_tbl[opp_ll] = f_ll;
  return pair<ll, ll>(f_ll, opp_ll);
}

int main(void){
  int n;
  cin >> n;
  VL s(n);
  REP(i, 0, n) {
    cin >> s[i];
  }
  int cnt = 0;
  map<ll, int> tbl;
  REP(i, 0, n) {
    pair<ll, ll> norm = opposite(s[i]);
    if (norm.first == -1) {
      cnt++;
    } else {
      if (tbl.count(norm.first) == 0) {
	tbl[norm.first] = 1;
      } else {
	tbl[norm.first]++;
      }
    }
  }
  for (map<ll, int>::iterator it = tbl.begin(); it != tbl.end(); ++it) {
    pair<ll, int> w = *it;
    if (w.first == 1) {
      cnt++;
      continue;
    }
    ll opn = opp_tbl[w.first];
    int opc = tbl.count(opn) ? tbl[opn] : 0;
    cnt += max(w.second, opc);
    it->second = 0;
    tbl[opn] = 0;
  }
  cout << cnt << endl;
}

