			}
		}
		for (auto t : lv) if (t.second % 3 != 0)
			tl.emplace_back(t.first, t.second % 3);
		lv.clear();
		++M[tl];
	}
	int ans = (!!M[V()]) << 1;
	for (auto t : M) if (!t.first.empty())
		ans += std::max(t.second, M[al(t.first)]);
	std::cout << ans / 2 << std::endl;
	return 0;
}

