#define int long long
const int maxN = 2e3 + 13, maxK = 1e5 + 13;
int n, b[maxK], a[maxK], ans;
map<int, int> val;
map<int, bool> mark;
int32_t main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);
    cin >> n;
    for (int i = 0; i < n; i++) {
	cin >> a[i];
	int x = a[i];
	a[i] = b[i] = 1;
	for (int j = 2; j < maxN; j++) {
	    if(x % j == 0){
		int cnt = 0;
		while (x % j == 0) {
		    x /= j;
		    cnt++;
		}
		if (cnt % 3 == 1) {
		    a[i] *= j;
		    b[i] *= j * j;
		}
		else if (cnt % 3 == 2){
		    a[i] *= j * j;
		    b[i] *= j;
		}
	    }
	}
	if(x != 1){
	    int y = ceil(sqrt(x));
	    a[i] *= x;
	    if (y * y == x)
		b[i] *= y;
	    else
		b[i] *= x * x;
	}
	val[a[i]]++;
    }
    for (int i = 0; i < n; i++)
	if (!mark[a[i]]) {
	    mark[a[i]] = mark[b[i]] = 1;
	    if (a[i] == 1)
		ans++;
	    else
		ans += max(val[a[i]], val[b[i]]);
	}

    cout << ans << endl;
}

