int n,cnt;
int vis[maxn],pri[maxn];
ll val[maxn],two[maxn],tri[maxn];
map<ll,int>num;
map<ll,ll>con;

void init()
{
	cnt=0;
	int up=1e5;
	memset(vis,0,sizeof(vis));

	for(int i=2;i<=up;i++)
	{
		if(!vis[i])
		{
			vis[i]=1;
			cnt++;
			pri[cnt]=i;
		}
		for(int j=i+i;j<=up;j+=i)
		{
			vis[j]=1;
		}
	}
	for(int i=1;i<=cnt;i++)
	{
		two[i] = 1LL*pri[i]*pri[i];
		tri[i] = 1LL*two[i]*pri[i];
	}
}

int max(int a,int b)
{
	if(a>b)
	{
		return a;
	}
	else
	{
		return b;
	}
}
void solve()
{
	scanf("%d",&n);
	for(int i=1;i<=n;i++)
	{
		scanf("%lld",&val[i]);

		ll tmp = val[i];
		ll s=1;
		for(int j=1;j<=cnt&&pri[j]<=tmp;j++)
		{

			if(tmp%pri[j]==0)
			{
				int c=0;
				while(tmp%pri[j]==0)
				{
					c++;
					tmp/=pri[j];
				}
				if(c%3==1)
				{
					s*=two[j];
				}
				else
				{
					s*=pri[j];
				}
			}
		}
		if(tmp!=1)
		{
			s*=tmp*tmp;
		}
		con[val[i]]=s;
		num[val[i]]++;

	}
	map<ll,int>::iterator it;
	int ans=0;
	/*
	for(it=num.begin(); it!=num.end(); it++)
	{
		cout<<it->first<<" "<<it->second<<" "<<con[it->first]<<endl;
	}
	*/
	for(it=num.begin(); it!=num.end(); it++)
	{
		if(it->first==1)continue;
		if(it->second==0)continue;
		ll tmp = it->first;
		ll s = con[tmp];
		//cout<<s<<" "<<num[s]<<endl;
		//cout<<it->second<<endl;
		ans+=max(it->second,num[s]);
		//cout<<"ans: "<<ans<<endl;
		it->second=0;
		num[s]=0;
	}
	if(num[1])ans++;
	printf("%d\n",ans);
}

int main()
{
    init();
    solve();
	return 0;
}

#include<bits/stdc++.h>
#define L long long
#define M 100005
#define N 2154
using namespace std;

L pri[M],use=0;
bool isp(L x){
	for(L j=2;j*j<=x;j++)
	if(x%j==0) return 0;
	return 1;
}
void init(){
	for(L i=2;i<=N;i++)
	if(isp(i)) pri[++use]=i;
}

L f(L x){
	for(L i=1;i<=use;i++){
		L iii=pri[i]*pri[i]*pri[i];
		while(x%iii==0) x/=iii;
	}
	return x;
}
L cnt=0,mi[M]={0},p[M]={0};

L g(L x){
	cnt=0;
	for(L i=1;i<=use;i++){
		while(x%pri[i]==0){
			if(p[cnt]==pri[i]) mi[cnt]++;
			else p[++cnt]=pri[i],mi[cnt]=1;
			x/=pri[i];
		}
	}
	L hh=sqrt(x);
	if(hh*hh==x){
		mi[++cnt]=2; p[cnt]=hh;
	}else if(x<100000) mi[++cnt]=1,p[cnt]=x;
	L res=1;
	for(L i=1;i<=cnt;i++){
		if(mi[i]==1) res*=p[i]*p[i];
		if(mi[i]==2) res*=p[i];
	}
	return res;
}

map<L,L> mp;
int main(){
	init();
	L n; scanf("%lld",&n);
	for(L i=1;i<=n;i++){
		L x; scanf("%lld",&x);
		x=f(x);
		mp[x]++;
	}
	L ans=0;
	for(map<L,L>::iterator it=mp.begin(); it!=mp.end();it++){
		L now=it->first,nowp=g(now);
		if(now==1) {ans++; continue;}
		if(mp[now]>mp[nowp]) ans+=mp[now];
		else ans+=mp[nowp];
		mp[now]=mp[nowp]=0;
	}
	cout<<ans<<endl;
}

#include <bits/stdc++.h>
#define MOD 1000000007
using namespace std;
typedef long long LL;
LL a[110000];
vector<LL> p1, p2;

map<LL,int> r;
void gen(LL k){
	if(r.find(k) == r.end()){
		r[k] = rand() % MOD + 1249;
	}
}
int main(){
	srand(150);
	int n;
	cin >> n;
	for(int i = 0; i < n; i++) cin >> a[i];
	map<LL,int> d;
	int n1 = 0;
	vector<int> q;
	for(int j = 2; j < 2200; j++){
		int ok = 1;
		for(int z = 2; z*z <= j; z++){
			if(j % z == 0){
				ok = 0;
				break;
			}
		}
		if(ok) q.push_back(j);
	}
	for(int z = 0; z < n; z++){
		p1.clear();
		p2.clear();
		for(int i = 0; i < q.size(); i++){
			LL j = q[i];
			LL p = j*j*j;
			while(a[z] % p == 0){
				a[z] /= p;
			}
			p = j;
			if(a[z] % (p*p) == 0){
				p2.push_back(p);
				a[z] /= (p*p);
			}
			if(a[z] % (p) == 0){
				p1.push_back(p);
				a[z] /= (p);
			}
		}
		if(a[z] > 1){
			LL c = sqrt(a[z]);
			if(c*c == a[z]){
				p2.push_back(c);
			} else {
				p1.push_back(a[z]);
			}
		}
		if(p1.empty() && p2.empty()){
			n1 = 1;
			continue;
		}
		LL h1 = 0;
		LL h2 = 0;
		for(int i = 0; i < p1.size(); i++){
			gen(p1[i]);
			//cout << p1[i] << " " << r[p1[i]] << endl;
			h1 += r[p1[i]];
		}
		for(int i = 0; i < p2.size(); i++){
			gen(p2[i]);
			//cout << p2[i] << " " << r[p2[i]] << endl;
			h2 += r[p2[i]];
		}
		//cout << h1-h2 << endl;
		d[h1-h2]++;
		d[h2-h1]++;
		d[h2-h1]--;
	}
	LL ans = 0;
	for(map<LL,int>::iterator it = d.begin(); it != d.end(); it++){
		ans += max(d[it->first],d[-it->first]);
	}
	ans /= 2;
	ans += n1;
	cout << ans << endl;
}

