long long n;
long long a[(1<<20)];
pair < long long, long long > vals[(1<<20)];
map < long long, long long > cnt;

pair< long long, long long > gg ( long long x ) {
    long long a = 1, b = 1;

    for ( long long i = 2 ; i*i <= x ; i ++ ) {

        if ( x%i == 0 ) {
            long long cnt = 0;
            for ( ; x%i == 0 ; cnt ++ ) {
                x /= i;
            }
            cnt %= 3;
            for ( long long c = 0 ; c < cnt ; c ++ ) { a *= i; }
            cnt = (3-cnt)%3;
            for ( long long c = 0 ; c < cnt ; c ++ ) { b *= i; }

        }
    }

    if ( x != 1 ) {
        a *= x;
        b *= x*x;
    }
    return make_pair( a, b );
}

int main () {
    cin >> n;
    for ( long long i = 0 ; i < n ; i ++ ) {
        cin >> a[i];
        vals[i] = gg( a[i] );
        cnt[ vals[i].first ] ++;
    }
    sort ( vals, vals+n );

    long long ans = 0;
    for ( long long i = 0 ; i < n ; ) {
        long long j = i;
        for ( ; j < n && vals[i].first == vals[j].first ; j ++ ) {}

        long long ccnt = j-i, revcnt = cnt[ vals[i].second ];

        if ( vals[i].first == 1 ) { ans ++; }
        else {
            if ( ccnt > revcnt ) {
                ans += ccnt;
            }else if ( ccnt < revcnt ) {
                //ans += revcnt;
            }else {
                if ( vals[i].first < vals[i].second ) {
                    ans += ccnt;
                }
            }

        }

        i = j;
    }
    cout << ans << "\n";
    return 0;
}

