  function<vector<int>(int)> getPrimes = [&](int x) {
    vector<int> ret;
    vector<bool> vis(x + 1);
    for (int k = 2; k <= x; ++k)
      if (!vis[k]) {
        ret.push_back(k);
        for (int j = k; j <= x; j += k)
          vis[j] = true;
      }
