  for (int p : pr) pr3.push_back(p * (ll)p * p);

  int N;
  cin >> N;
  map<ll, int> cnt;
  int ans = 0;
  ll mx = 0;
  while (N--) {
    ll x;
    cin >> x;
    for (ll v : pr3)
      while (x % v == 0)
        x /= v;
    if (x == 1)
      ans = 1;
    else
      ++cnt[x];
    mx = max(mx, x);
  }
  function<int(ll)> pSQRT = [&](ll x) {
    int rt = sqrt(x);
    while (rt * (ll)rt < x) ++rt;
    while (rt * (ll)rt > x) --rt;
    return rt * (ll)rt == x ? rt : -1;
  };
  function<ll(ll)> dual = [&](ll x) {
    ll fact = 1;
    for (int p : pr)
      if (x % p == 0) {
        if (x / p % p == 0) {
          x /= p * p;
          fact *= p;
        } else {
