template<typename T> 
map<T, Int> factorize(T x){
  map<T, Int> res;
  for(Int i:pr){
    while(x%i==0){
      x/=i;
      res[i]++;
    }
    if(x<i) break;
  }
  if(x!=1) res[x]++;
  return res;
}

