    }
    if (M.find(s[i]) == M.end()) {
      M[s[i]] = 1;
    } else {
      M[s[i]]++;
    }
  }
  set<ll> visited;
  for (auto x : M) {
    ll k = x.first;
    int num = x.second;
    cerr << k << " " << num << endl;
