ll is_square(ll x) {
	ll t = sqrt(x);
	for(int i = max(-10ll, -t); i < 10; i++) if((t+i)*(t+i) == x) return t+i;
	return -1;
}
ll compress(ll x) {
	ll res = 1;
	for(auto i : primes) {
		if(x%i) continue;
		int c = 0;
		while(x%i == 0) x/=i, c++;
		c %= 3;
		while(c--) res *= i;
	}
	ll t = is_square(x);
	if(t >= 0 && t > 100000) return 1ll<<50;
	if(t == -1 && x > 100000) return 1ll<<50;
	return res*x;
}
ll inv(ll x) {
	ll res = 1;
	for(auto i : primes) {
		if(x%i) continue;
		int c = 0;
		while(x%i == 0) x/=i, c++;
		c = (3 - c%3)%3;
		while(c--) res *= i;
	}
	ll t = is_square(x);
	if(t != -1) return res*t;
	return res*x*x;
}
