void sieve(int n)
{
	int i, j, limit = sqrt(n*1.) + 2;

	mark[1] = 1;
	for (i = 4; i <= n; i += 2) mark[i] = 1;

	Prime.push_back(2);
	for (i = 3; i <= n; i += 2)
		if (!mark[i])
		{
			Prime.push_back(i);

			if (i <= limit)
			{
				for (j = i*i; j <= n; j += i * 2)
				{
					mark[j] = 1;
				}
			}
		}
}


vector<pair<LL, int>> V;

void factor(LL s, vector<pair<LL, int>> &V) {
	V.clear();
	int sz = Prime.size();
	for (int i = 0; i < sz && 1LL * Prime[i] * Prime[i] <= s; i++) {
		int cnt = 0;
		while (s % Prime[i] == 0) {
			cnt++;
			s /= Prime[i];
		}
		if ((cnt % 3) == 0) continue;
		V.push_back(make_pair(Prime[i], cnt % 3));
	}

	if (s > 1) {
		int cnt = 1;
		V.push_back(make_pair(s, cnt % 3));
	}
}

map<vector<pair<LL, int> >, int> M;

