		factor(S[i], V);
		M[V]++;
	}

	int ans = 0;
	for (const auto& ele : M) {
		vector<pair<LL, int> > VV = ele.first;
		int cnt = ele.second;

		int allZero = 1;
		for (auto& e : VV) {
