				e.second = 3 - e.second;
				allZero = 0;
			}
		}

		if (allZero) {
			ans++;
		}
		else {
			int op = 0;
			if (M.find(VV) != M.end()) op = M[VV];
			if (op == 0) {
				ans += cnt; continue;
			}
			if (VV[0].second == 2) continue;
			ans += MAX(cnt, op);
