map<ll, int> factsmall(ll n) {
    map<ll, int> mp;
    for (ll d: pr) {
        if (n < d*d) break;
        while (n % d == 0) {
            n /= d;
            mp[d]++;
        }
    }
    if (n > 1) mp[n]++;
    return mp;
}

bool isPrime(ll n, int k = 30) {
    if (n <= 1) return false;
    if (n == 2) return true;
    if (n % 2 == 0) return false;
    ll d = n-1;
    while (d % 2 == 0) d /= 2;
    for (int i = 0; i < k; i++) {
        ll a = rand_int(1, n), t = d;
        ll y = pow<__int128>(a, t, n); //over
        while (t != n-1 && y != 1 && y != n-1) {
            y = __int128(y)*y % n; //flow
            t <<= 1;
        }
        if (y != n-1 && t % 2 == 0) {
            return false;
        }
    }
    return true;
}

