    for (auto &&i : v) {
        scanf("%lld", &i);
    }
    map<map<ll, int>, int> m;
    int ans = 0;
    for (int i = 0; i < n; ++i) {
        int ok = 1;
        for (ll j = 2; j <= 2100; ++j) {
            if(v[i] == j*j*j) ok = 0;
            while(v[i]%(j*j*j) == 0) v[i] /= j*j*j;
        }
        if(ok && v[i] != 1) {
            auto x = prime_factor(v[i]);
            for (auto &&j : x) {
                j.second %= 3;
            }
            m[x]++;
        }else ans++;
    }
    ans = ans > 0;
    for (auto &&i : m) {
        if(!i.second) continue;
        map<ll, int> y = i.first;
        for (auto &&k : y) {
            k.second = (3-k.second)%3;
        }
        if(m.count(y)){
            ans += max(m[y], i.second);
            m[y] = 0;
        }else {
            ans += i.second;
        }
    }
    cout << ans << "\n";
    return 0;
}

