			pSqrt[i * i] = i;
		}
	}
	map<ll, ll> mp;
	Array b(n, 1);
	Array p(n, 1);
	ll ans = 0;
	ll flag = 0;
	REP(i, n) {
		ll s;
		cin >> s;
		REP(j, prime.size()) {
			if (prime[j] > 2500)break;
			ll cnt = 0;
			while (true) {
				if (s % prime[j] == 0) {
					cnt++;
					s /= prime[j];
				}
				else {
					break;
				}
			}
			cnt %= 3;
			REP(k, cnt)b[i] *= prime[j];
			if (cnt != 0)REP(k, 3 - cnt)p[i] *= prime[j];
			if (p[i] > 10000000000LL)p[i] = 0;
		}
		if (b[i] == 1 && s == 1) {
			flag = 1;
			p[i] = -INF;
			continue;
		}
		if (pSqrt[s]!=0) {
			b[i] *= s;
			p[i] *= pSqrt[s];
			if (p[i] > 10000000000LL)p[i] = 0;
			mp[b[i]]++;
		}
		else {
			b[i] *= s;
			REP(k, 2) {
				p[i] *= s;
				if (p[i] > 10000000000LL)p[i] = 0;
			}
			mp[b[i]]++;
		}
	}
	ans += flag;
	REP(i, n) {
		ll s, t;
		if (p[i] == -INF)continue;
		else {
			s = mp[b[i]];
			t = mp[p[i]];
			if (s > t)ans++;
			else if (s == t && b[i] > p[i])ans++;
		}
	}
	cout << ans << endl;

	return 0;
}

