    bool zero=false;

    vector<ll> cube;
    for(ll p:prime){
        if(p*p*p>10000000000) break;
        cube.push_back(p*p*p);
    }

    while(N--){
        ll a;cin>>a;

        for(ll c:cube){
            while(a%c==0) a/=c;
        }

        if(a==1){
