bool isPrime(int x)
{
	for (int i = 2; i*i <= x; i++)
	{
		if (x % i == 0) return false;
	}
	return true;
}

VI pr;
Q get(LL x)
{
	vector<PII> a;
	LL b;
	FOR (i, 0, SZ(pr))
	{
		int y = pr[i];
		if (x % y == 0)
		{
			int cnt = 0;
			while(x % y == 0)
			{
				x /= y;
				cnt++;
			}

			cnt %= 3;
			if (cnt) a.PB(MP(y, cnt));
		}
	}

	b = x;

	return MP(a, b);
}

LL sq(LL x)
{
	double m = x * (double) x;
	if (m > 1e18) return LINF;
	return x * x;
}

Q inverse(Q a)
{
	FOR (i, 0, SZ(a.first))
	{
		a.first[i].second = 3 - a.first[i].second;
	}

	a.second = sq(a.second);
	return a;
}

