            for(t = 0; t < k; t ++)
                f[i] *= Sieve::p[j];
            for(t = 0; t < (3 - k) % 3; t ++)
                g[i] *= Sieve::p[j];
        }
        f[i] *= a[i];

        t = (long long)sqrt((long double)a[i]);
