    is_prime[0] = 0;
    is_prime[1] = 0;

    for (int i = 2; i * i < is_prime.size(); ++i) {
        if (is_prime[i]) {
            for (int j = i * i; j < is_prime.size(); j += i) {
                is_prime[j] = 0;
            }
        }
    }

    for (int i = 2; i < is_prime.size(); ++i) {
