LL sqrt(LL a)
{
	LL l = 1, r = 100000 + 47;
	while (r - l > 1)
	{
		LL c = (r + l) / 2;
		if (c * c <= a)
		{
			l = c;
		}
		else
		{
			r = c;
		}
	}

	return l;
}

pair<LL, LL> norm(LL a)
{
	LL r1 = 1;
	LL r2 = 1;
	FOR(i, 0, sz)
	{
		LL l = L[i];
		if (a % l == 0)
		{
			int cnt = 0;
			while (a % l == 0)
			{
				a /= l;
				cnt++;
			}

			cnt %= 3;
			FOR(k, 0, cnt) r1 *= l;
			FOR(k, 0, 3 - cnt)
			{
				if (r2 > MAX2) continue;
				r2 *= l;
			}
		}
	}

	if (a == 1) return MP(r1, r2);
	LL l = sqrt(a);
	if (l * l == a && r2 * (double) l < 2 * MAX2) return MP(r1, r2 * l);
	return MP(r1, MAX2);
}

