void build() {
	for (int i = 2; i < N; ++i) {
		isPrime[i] = true;
	}
	for (ll i = 2; i < N; ++i) {
		if (isPrime[i]) {
			primes.push_back(i);
			for (ll j = i * i; j < N; j += i) {
				isPrime[j] = false;
			}
		}
	}
}

ll add(ll a, ll b) {
	ll res = a + b;
	if (res >= MOD) {
		res -= MOD;
	}
	return res;
}

ll mul(ll a, ll b) {
	return a * b % MOD;
}

ll binpow(ll a, ll n) {
	if (n == 0) {
		return 1ll;
	}
	if (n % 2 == 0) {
		return binpow(mul(a, a), n / 2);
	} else {
		return mul(binpow(a, n - 1), a);
	}
}

std::vector<ll> used;

void factr(ll n, std::vector<std::pair<ll, int>>& a) {
	for (auto i : primes) {
		if (i * i > n) {
			break;
		}
		if (n % i == 0) {
			int cnt = 0;
			while (n % i == 0) {
				++cnt;
				n /= i;
			}
			cnt %= 3;
			a.push_back(std::make_pair(i, cnt));
			used.push_back(i);
		}
	}
	if (n > 1) {
		a.push_back(std::make_pair(n, 1));
		used.push_back(n);
	}
}

