	std::sort(used.begin(), used.end());
	used.resize(std::unique(used.begin(), used.end()) - used.begin());
	for (int i = 0; i < n; ++i) {
		ll hash = 1, revHash = 1;
		for (auto j : f[i]) {
			for (int k = 0; k < j.second; ++k) {
				hash *= j.first;
			}
			int r = (3 - j.second) % 3;
			for (int k = 0; k < r; ++k) {
				revHash *= j.first;
			}
		}
		h.push_back(std::make_pair(hash, revHash));
		++cnt[hash];
	}
	int ans = 0;
	bool fl = false;
