long long Slove(long long n)
{
    long long ret = 1;ret = n;
    for(vector<long long>::size_type i = 0; i < prime.size(); ++i)
    {
    	long long tmp = prime[i] * prime[i] * prime[i];

        if(tmp > ret) break;
        while(ret % tmp == 0) ret /= tmp;
    }
    return ret;
}
