static set<int> SetPrimes;

static void GetPrimes() {
	for (int i = 0; i <= MAXPRIME; ++i) IsPrime[i] = true;
	IsPrime[0] = IsPrime[1] = false;

	IsPrime[2] = true;
	for (int j = 2 * 2; j <= MAXPRIME; j += 2) IsPrime[j] = false;
	for (int i = 3; i <= MAXPRIME; i += 2)
	{
		if (!IsPrime[i]) continue;

		for (int j = i * 2; j <= MAXPRIME; j += i)
		{
			IsPrime[j] = false;
		}
	}

	NumPrimes = 0;
	for (int i = 0; i < sizeof(ArrayPrimes) / sizeof(*ArrayPrimes); ++i) ArrayPrimes[i] = 0;
	SetPrimes.clear();

	for (int i = 1; i <= MAXPRIME; ++i)
		if (IsPrime[i]) {
			SetPrimes.insert(i);
			ArrayPrimes[NumPrimes++] = i;
		}
}



class Number {
public:
	enum Type
	{
		Normal = 0,
		One,
		Big
	};
	s64 norm, pair;
	Number() { }
	Type Assign(s64 num) {
		norm = 1; pair = 1;
		for (auto prim : SetPrimes) {
			if (num == 1) break;
			int c = 0;
			while (num % prim == 0) { ++c; num /= prim; }

			c %= 3;

			if (c > 0) {
				for (int i = 0; i < c; ++i) norm *= prim;
				for (int i = 0; i < 3 - c; ++i) pair *= prim;
			}
		}

		if (num != 1) { norm *= num; return Big; }
		else if (norm == 1) return One;
		else return Normal;
	}
	Number Pair() const {
		Number _pair;
		_pair.norm = pair;
		_pair.pair = norm;
		return _pair;
	}
	bool operator<(const Number& b) const {
		return norm < b.norm;
	}
};

int main(int argc, char* argv[])
{
	OPENOJIO;
	GetPrimes();

	int n;
	static Number norms[MAXN];

	ip >> n;
	int nn = 0;
	int cb = 0, c1 = 0;

	for (int i = 0; i < n; ++i) {
		s64 t; ip >> t;

		switch (norms[nn].Assign(t))
		{
		case Number::Normal:
			++nn;
			break;
		case Number::One:
			++c1;
			break;
		case Number::Big:
			++cb;
			break;
		default:
			throw "Error: ss[nn].type";
		}
	}

	sort(norms, norms + nn);

	int rst = 0;

	static bool used[MAXN];
	fill(used, used + nn, false);

	for (int i = 0; i < nn; ) {
		if (used[i]) ++i;
		else {
			const Number &norm = norms[i];
			Number *nbeg = norms + i;
			Number *nend = upper_bound(norms, norms + nn, norm);
			int cn = nend - nbeg;

			Number pair = norm.Pair();
			Number* pbeg = lower_bound(norms, norms + nn, pair);
			Number* pend = upper_bound(norms, norms + nn, pair);
			int cp = pend - pbeg;

			fill(used + (nbeg - norms), used + (nend - norms), true);
			fill(used + (pbeg - norms), used + (pend - norms), true);

			rst += MAX(cn, cp);
			i += cn;
		}
	}

	rst += cb;
	if (c1 > 0) rst += 1;

	cout << rst << endl;

	return 0;
}
