}

int main() {

    isPrime[0] = 1;
    isPrime[1] = 1;
    for (int i = 2; i <= 4000; i++) {
        if (!isPrime[i]) {
            pnum++;
            plist[pnum] = i;
        }
        for (int j = 1; j <= pnum; j++) {
            if (i * plist[j] > 4000)
                break;
            isPrime[i * plist[j]] = 1;
            if (!(i % plist[j]))
                break;
        }
    }
    int n, ans = 0;
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        scanf("%lld", &a[i].first);
        lli tmp = a[i].first;
        a[i].first = 1;
        a[i].second = 1;
        for (int j = 1; j < pnum && 1ll * plist[j] * plist[j] <= tmp; j++) {
            int cnt = 0;
            while (tmp % (1ll * plist[j] * plist[j] * plist[j]) == 0) {
                tmp /= (1ll * plist[j] * plist[j] * plist[j]);
            }
            while(tmp % plist[j] == 0){
                tmp /= plist[j];
                cnt ++;
            }
            if (cnt == 1) {
                a[i].first *= plist[j];
                a[i].second *= (1ll * plist[j] * plist[j]);
            } else if (cnt == 2) {
                a[i].first *= (1ll * plist[j] * plist[j]);
                a[i].second *= plist[j];
            }
        }
        if (tmp != 1) {
            a[i].first *= tmp;
            if (tmp > 10000000000ll / tmp / a[i].second) {
                ans++;
                a[i].second = -1;
            } else {
                a[i].second *= (tmp * tmp);
            }
        }

    }
//    printf("+++++++++++++++++++ \n");
    sort(a, a + n, cmp);
//    printf("************************* \n");
    int cnt = 1;

    for (int i = 1; i < n; i++) {

        if (a[i].first == a[i - 1].first) {
            cnt++;
        } else {
            nums[id] = a[i - 1].first;
            inv[id] = a[i - 1].second;
            ccnt[id] = cnt;
            id++;
            cnt = 1;
        }
    }
    if (cnt != 0) {
        nums[id] = a[n - 1].first;
        inv[id] = a[n - 1].second;
        ccnt[id] = cnt;
        id++;
    }
    for (int i = 0; i < id; i++) {
        if (inv[i] == -1) continue;
        if(nums[i] == 1){
            ans ++;
            continue;
        }
        lli p = inv[i];
        unsigned long x = lower_bound(nums, nums + id, p) - nums;
        if (x >= id) ans += ccnt[i];
        else {
            ans += max(ccnt[i], ccnt[x]);
            inv[x] = -1;
            inv[i] = -1;
        }
        inv[i] = -1;
    }
    printf("%d\n",ans);
    return 0;
}

