        if (mp2.count(a[t])){
            val=mp2[a[t]].first;
            rev=mp2[a[t]].second;
            a[t]=val,r[t]=rev;
            mp[a[t]]++;
            continue;
        }
        val=1,rev=1; aux=a[t];
        for (i=1; p[i]*p[i]<=a[t] && i<=K; i++)
            if (a[t]%p[i]==0){
                put=0;
                while (a[t]%p[i]==0) a[t]/=p[i],put++;
                if (put%3==1) val*=p[i],rev=rev*p[i]*p[i];
                else if (put%3==2) val=val*p[i]*p[i],rev*=p[i];
            }

        if (a[t]>1) val*=a[t],rev=rev*a[t]*a[t];
        a[t]=val,r[t]=rev;
