const int INF = 1 << 30;
const ll INFL = 1LL << 60;

vector<ll> generate_primes(ll N) {
    vector<int> is_prime(N, 1);
    vector<ll> primes;
    repeat(i, 2, N) {
        if(not is_prime[i]) continue;
        primes.push_back(i);
        for(ll j = i * 2; j < is_prime.size(); j += i) is_prime[j] = 0;        
    }
    return primes;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    auto primes = generate_primes(1e3*4);
    set<ll> primes2;
    for(ll p : primes) primes2.insert(p*p);

    int N; cin >> N;
    vector<ll> S(N); cin >> S;

    map<ll, int> normalized_s;

    for(ll s : S) {
        ll t = 1;
        for(ll p : primes) {
            int cnt = 0;
            while(s % p == 0) {
                s /= p;
                cnt++;
            }
            cnt %= 3;
            rep(i, cnt) t *= p;
            if(s == 1) break;
        }
        if(s > 1) t *= s;
        normalized_s[t]++;
    }
    int ans = 0;
    set<ll> used;
    for(auto s_ : normalized_s) {
        ll s = s_.first;
        int cnt = s_.second;
        if(used.count(s)) continue;

        ll t = primes2.count(s) ? sqrt(s) : s * s;
        used.insert(s);
        used.insert(t);

        int s_cnt = cnt;
        int t_cnt = normalized_s.count(t) ? normalized_s[t] : 0;

        ans += s == t ? 1 : max(s_cnt, t_cnt);
    }
    cout << ans << endl;

    return 0;
}

