inline ll factor(ll x) {
	for(ll j : p) {
		ll o = j * j * j;
		if(o > x) return x;
		for(;x % o == 0;x /= o);
	}
	exit(1);
}
inline ll rev(ll x) {
	static const ll none = 1145141919810;
	ll y = 1;
	for(ll j : p) {
		if(j > 5000) break;
		if(x % j == 0) {
			int c = 0;
			for(;x % j == 0;++ c) x /= j;
			if(c <= 2) y *= j;
			if(c <= 1) y *= j;
		}
	}
	ll p = round(sqrtl(x));
	if(p * p == x) y *= p, x = 1;
	return x == 1 ? y : none;
}
std::map<ll, int> map;
int main() {
