typedef unsigned long long ll;

const int MAXN = 100 * 1000 + 12, MXR3 = 2155 + 5;



map<ll, int> mp, tof;
int ans;

bool inp[MAXN];
vector<int> p;

void gh() {
	inp[0] = inp[1] = true;
	for (int i = 2; i < MAXN; i++)
		if (!inp[i]) {
		    tof[(ll)i * i] = i;
		    if (i < MXR3)
		    	p.push_back(i);
			for (ll j = (ll)i * i; j < MAXN; j += i)
				inp[j] = true;
		}
}
ll kam(ll x) {
	ll ret = 1;
	for (int i = 0; (i < (int)p.size()) && ((ll)p[i] * p[i] * p[i] <= x); i++) {
		ll j = p[i];
		if (x % j == 0) {
			ll m = j * j * j;
			while (x % m == 0)
				x /= m;
			while (x % j == 0)
				ret *= j, x /= j;
		}
	}
	return ret * x;
}
ll ziad(ll x) {
	ll ret = 1;
	for (int i = 0; i < (int)p.size() && (ll)p[i] * p[i] * p[i] <= x; i++) {
		ll j = p[i];
		if (x % j == 0) {
			ll m = j * j * j;
			while (x % m == 0)
				x /= m;
			while (x % j == 0)
				m /= j, x/= j;
			ret *= ((m == j * j * j)? 1: m);
		}
	}
	if (tof[x])
	    return ret * tof[x];
	return ret * x * x;
}


int main() {
	gh();
	{
		int n;
		ll a;
		cin >> n;
		for (int i = 0; i < n; i++) {
			cin >> a;
			mp[kam(a)]++;
			mp[ziad(a)] += 0;
		}
	}
	for (auto i : mp) {
	    ll x = ziad(i.ft);
	    if (i.ft == 1 && i.sd)
	        ans++;
	    else if (i.ft < x)
	        ans += max(i.sd, mp[x]);
	}
	cout << ans;
	return 0;
}

