typedef long long ll;

const int N = 2200;
const ll INF = 1e18;

vector<ll> pr;

void delCubes(ll& v) {
  for (ll p : pr) {
    while (v % (p * p * p) == 0) {
      v /= (p * p * p);
    }
  }
}

ll getPair(ll v) {
  ll res = 1;
  for (ll p : pr) {
    if (v % p == 0 && v % (p * p) != 0) {
      res *= p * p;
      v /= p;
    }
    else if (v % (p * p) == 0) {
      res *= p;
      v /= (p * p);
    }
  }
  if (v != 1) {
    ll sq = sqrt(v);
    if (sq * sq == v) {
      res *= sq;
    }
    else {
      res *= sq * sq;
    }
  }
  return res;
}

void solve() {
  int n; cin >> n;
  unordered_map<ll, int> mp;
  for (int i = 0; i < n; i++) {
    ll v; cin >> v;
    delCubes(v);
    mp[v]++;
  }
  ll ans = (mp[1] > 0);
  mp.erase(1);
  for (auto x : mp) {
    ll v = x.first, res = x.second;
    ll nv = getPair(v);
    //cout << v << " " << nv << endl;
    if (mp.count(nv) == 0) {
      ans += res;
    }
    else if (res > mp[nv] || res == mp[nv] && v < nv) {
      ans += res;
    }
  }
  cout << ans;
}

