map<long, long> factorize(long n) {
  map<long, long> ret;
  for (int p : primes) {
    int cnt = 0;
    while (n % p == 0) {
      ++cnt;
      if (cnt == 3) cnt = 0;
      n /= p;
    }
    if (cnt > 0) {
      ret[p] = cnt;
    }
  }

  if (n == 1) return ret;
  if (squared.count(n)) {
    long p = squared[n];
    ret[p] = 2;
  } else {
    ret[n] = 1;
  }
  return ret;
}

bool is_prime(int n) {
  for (int i = 2; i * i <= n; ++i) {
    if (n % i == 0) return false;
  }
  return true;
}

