    squared[i * i] = i;
    cubed.insert(i * i * i);
  }

  for (int i = 2; i < 2155; ++i) {
    if (is_prime(i)) primes.push_back(i);
  }
}

map<long, long> anti(const map<long, long>& mp) {
  map<long, long> ret;
  for (auto&& p : mp) {
    ret[p.first] = 3 - p.second;
  }
  return ret;
}

