    if (it == mp.end()) {
      sum += 2 * p.second;
    } else {
      sum += max(it->second, p.second);
    }
  }
  cout << sum / 2 << endl;
}

#include <bits/stdc++.h>
using namespace std;
bool is_cube(long long N){
  long long c = (long long) (cbrt(N) + 0.001);
  return (c * c * c == N) || ((c + 1) * (c + 1) * (c + 1) == N) || ((c - 1) * (c - 1) * (c - 1) == N);
}
long long is_square(long long N){
  long long c = (long long) (sqrt(N) + 0.001);
  if (c * c == N){
    return c;
  } else if ((c + 1) * (c + 1) == N){
    return c + 1;
  } else if ((c - 1) * (c - 1) == N){
    return c - 1;
  } else {
    return -1;
  }
}
int main(){
  int N;
  cin >> N;
  vector<long long> s(N);
  for (int i = 0; i < N; i++){
    cin >> s[i];
  }
  int cnt = 0;
  vector<long long> t;
  for (int i = 0; i < N; i++){
    if (is_cube(s[i])){
      cnt++;
    } else {
      t.push_back(s[i]);
    }
  }
  int ans = 0;
  if (cnt >= 1){
    ans++;
  }
  map<long long, int> A;
  map<long long, int> B;
  map<pair<long long, long long>, int> C;
  int M = t.size();
  for (int i = 0; i < M; i++){
    long long t2 = t[i];
    for (long long j = 2; j * j * j <= t[i]; j++){
      if (t2 % (j * j * j) == 0){
        t2 /= j * j * j;
      }
    }
    t[i] = t2;
    if (t[i] == 1){
      continue;
    }
    long long c = is_square(t[i]);
    if (c != -1){
      B[c]++;
    } else {
      bool is_C = false;
      for (long long j = 2; j * j * j <= t[i]; j++){
        if (t[i] % j == 0 && is_square(j) == -1 && is_square(t[i] / j) != -1){
          C[make_pair(is_square(t[i] / j), j)]++;
          is_C = true;
          break;
        }
        if (t[i] % (j * j) == 0 && is_square(t[i] / (j * j)) == -1){
          C[make_pair(j, t[i] / (j * j))]++;
          is_C = true;
          break;
        }
      }
      if (!is_C){
        A[t[i]]++;
      }
    }
  }
  set<long long> val;
  for (auto P : A){
    val.insert(P.first);
  }
  for (auto P : B){
    val.insert(P.first);
  }
  for (long long x : val){
    ans += max(A[x], B[x]);
  }
  set<pair<long long, long long>> val2;
  for (auto P : C){
    long long x = P.first.first;
    long long y = P.first.second;
    val2.insert(make_pair(min(x, y), max(x, y)));
  }
  for (auto P : val2){
    long long x = P.first;
    long long y = P.second;
    ans += max(C[make_pair(x, y)], C[make_pair(y, x)]);
  }
  cout << ans << endl;
}

#include <bits/stdc++.h>
using namespace std;
using ll = long long;

ll solve() {
    ll N;
    cin >> N;
    vector<ll> S(N);
    for ( int i = 0; i < N; i++ ) {
        cin >> S[i];
    }

    ll p_max = 10e5 + 1;
    vector<int> prime_tbl(p_max, 1);
    prime_tbl[0] = prime_tbl[1] = 0;
    for ( ll k = 2; k <= p_max; k++ ) {
        for ( ll h = 2; h*k <= p_max; h++ ) {
            prime_tbl[h*k] = 0;
        }
    }
    vector<ll> prime;
    for ( ll i = 0; i <= p_max; i++ ) {
        if ( prime_tbl[i] == 1 ) prime.push_back(i);
    }

    auto enc_map = [](map<ll, ll>& m) -> string {
        string r;
        for ( auto x : m ) {
            r.append(to_string(x.first));
            r.append("_");
            r.append(to_string(x.second));
            r.append("_");
        }
        return r;
    };
    auto dec_map = [](string& s) -> map<ll, ll> {
        map<ll,ll> r;
        int i = 0, len = s.size();
        while ( i < len ) {
            string k = "", v = "";
            while ( i < len && s[i] != '_' ) {
                k.push_back(s[i]);
                i++;
            }
            i++;
            while ( i < len && s[i] != '_' ) {
                v.push_back(s[i]);
                i++;
            }
            i++;
            r[stol(k)] = stol(v);
        }
        return r;
    };

    map<string, ll> m;
    for ( int i = 0; i < N; i++ ) {
        map<ll, ll> ns;
        ll s = S[i];
        for ( ll k : prime ) {
            while ( s % k == 0 ) {
                ns[k] = (ns[k] + 1) % 3;
                s /= k;
            }
        }
        if ( s > 1 ) {
            ns[s] = (ns[s] + 1) % 3;
        }
        for ( auto it = ns.begin(); it != ns.end();) {
            if ( it->second == 0 ) {
                ns.erase(it++);
            } else {
                it++;
            }
        }
        m[enc_map(ns)]++;
    }

    ll ans = 0;
    set<string> checked;
    for ( auto mm : m ) {
        if ( mm.first == "" ) {
            ans += 1;
        } else {
            if ( checked.find(mm.first) == checked.end() ) {
                string k1 = mm.first;
                auto tmp = dec_map(k1);
                for ( auto& p : tmp ) {
                    p.second = (3 - p.second) % 3;
                }
                string k2 = enc_map(tmp);
                ans += max(m[k1], m[k2]);
                checked.insert(k1);
                checked.insert(k2);
            }
        }
    }
    return ans;
}

int main() {
    auto ans = solve();
    cout << ans << "\n";
    return 0;
}

