				break;
			}
		}
		if(flag) prime.push_back(i);
	}
	FOR(i,0,prime.size()){
		sqr [prime [i] * prime [i]] = prime [i];
	}

	map<ll,int> cnt;
	FOR(i,0,N){
		FOR(j,0,prime.size()){
			while(A [i] % (prime [j] * prime [j] * prime [j]) == 0){
				A [i] /= prime [j] * prime [j] * prime [j];
			}
		}
		cnt [A [i]]++;
	}

	ll ans = 0;
	for(auto&& it : cnt){
		if(it.first == 1){
			ans++;
			continue;
		}
		ll tmp = calc_pair(it.first);
		if(tmp == -1 || (tmp > it.first && cnt.count(tmp) == 0)){
			ans += it.second;
		}
		else if(tmp > it.first && cnt.count(tmp)){
