void solve(int test) {
    int n = nxt();

    ll a[n];
    forn(i, n) a[i] = nxt();



    vi primes;

    for (ll j = 2; j * j * j <= 1e10; ++j) {
        if (checkp(j)) {
            primes.push_back(j);
        }
    }

    vll aprimes;

    for (ll j = 2; j * j <= 1e10; ++j) {
        if (checkp(j)) {
            aprimes.push_back(j);
        }
    }

    map <ll, pii> t;

    int ans = 0;
    int fl = 0;

    forn(i, n) {
        ll x = a[i];
        ll y = 1;
        ll z = 1;
        for (int j : primes) {
            int degree = 0;
            while (x % j == 0) {
                degree += 1;
                x /= j;
            }
            degree %= 3;
            if (degree == 2) {
                y *= j;
                z *= j;
                z *= j;
            }
            if (degree == 1) {
                y *= j;
                y *= j;
                z *= j;
            }
        }
        if (x != 1) {
            ll r = sqrt(x + 0.5);
            if (binary_search(all(aprimes), r)) {
                z *= r;
                z *= r;
                y *= r;
                goto l1;
            }
            if (binary_search(all(aprimes), x)) {
                z *= x;
                y *= x;
                y *= x;
                goto l1;
            }
            ++ans;
            continue;
            l1:;
        }
        if (y == z) {
            if (!fl) {
                ans += 1;
                fl = 1;
            }
        } else if (y < z) {
            t[y].x += 1;
        } else {
            t[z].y += 1;
        }
    }

    for (auto p : t) {
        ans += max(p.y.x, p.y.y);
    }

    cout << ans << "\n";
}


