vector<PI> inv(const vector<PI> &v) {
  vector<PI> opp(v.size());
  REP(i, 0, v.size()) {
    opp[i] = PI(v[i].first, 3 - v[i].second);
  }
  return opp;
}

/*
 * n |-> (r, (...)^3/r)
 * n / r = (...)^3
 * if n is not factored into a product of p <= 10^5, or the opposite is not in range, return (-1, ?).
 */
pair<vector<PI>, vector<PI> > opposite(ll v) {
  int oldv = v;
  vector<PI> fact;
  int p = 2;
  int e = 0;
  while ((v >= 2 || e >= 1) && p <= 3000) {
    if (v % p == 0) {
      v /= p;
      e++;
    } else {
      if (e % 3 != 0) {
	fact.push_back(PI(p, e % 3));
      }
      e = 0;
      p++;
    }
  }
  // Is v square?
  ll sq = sqrt(v);
  if (v >= 2 && v == sq * sq) {
    fact.push_back(PI(sq, 2));
    v = 1;
  }
  if (v >= 2) {
    return pair<vector<PI>, vector<PI> >(vector<PI>(1, PI(-1, -1)), vector<PI>());
  }
  vector<PI> opp = inv(fact);
  return pair<vector<PI>, vector<PI> >(fact, opp);
}

int main(void){
  int n;
  cin >> n;
  VL s(n);
  REP(i, 0, n) {
    cin >> s[i];
  }
  int cnt = 0;
  map<vector<PI>, int> tbl;
  vector<pair<vector<PI>, vector<PI> > > pool(n);
  REP(i, 0, n) {
    pair<vector<PI>, vector<PI> > norm = opposite(s[i]);
    pool[i] = norm;
    if (norm.first.size() == 1 && norm.first[0] == PI(-1, -1)) {
      cnt++;
    } else {
      if (tbl.count(norm.first) == 0) {
	tbl[norm.first] = 1;
      } else {
	tbl[norm.first]++;
      }
    }
  }
  for (map<vector<PI>, int>::iterator it = tbl.begin(); it != tbl.end(); ++it) {
    pair<vector<PI>, int> w = *it;
    if (w.first.size() == 0) {
      cnt++;
      continue;
    }
    vector<PI> opn = inv(w.first);
    int opc = tbl.count(opn) ? tbl[opn] : 0;
    cnt += max(w.second, opc);
    it->second = 0;
    tbl[opn] = 0;
  }
  cout << cnt << endl;
}

