map<ll, ll> prime_factor(ll n) {
    map<ll, ll> res;
    for(ll i = 2; i * i <= n; i++) {
        while(n % i == 0) {
            ++res[i];
            n /= i;
        }
    }
    if (n != 1) res[n] = 1;
    return res;
}

vector<ll> normalize_pairlize(ll x){
    vector<ll> np;
    map<ll,ll> pf=prime_factor( x );
    ll n=1,p=1,yobi=1;

    for (map<ll,ll>::iterator itr = pf.begin(); itr != pf.end(); itr++){
        ll xx=itr->first,yy=itr->second;
        if (yy >= 3){
            yy%=3;

        }
        n *= (ll)pow(xx,yy);
        if(yy!=0) {p *= (ll)pow(xx,3 - yy);}
    }
    np.push_back(n);
    np.push_back(p);
    return np;
}



