long long pw(long long x,long long y,long long p)
{
	x%=p;
	long long res=1;
	while (y)
	{
		if (y&1)
		{
			res=res*x%p;
		}
		x=x*x%p;
		y>>=1;
	}
	return res;
}
long long mul(long long x,long long y,long long p)
{
	x%=p;
	long long res=0;
	while (y)
	{
		if (y&1)
		{
			res=(res+x)%p;
		}
		x=x*2%p;
		y>>=1;
	}
	return res;
}
vector<long long> v;
int tot,fcnt[75];
long long fact[75];
bool isprime(long long x)
{
	if (x==2)
	{
		return true;
	}
	if (x==1 || !(x&1))
	{
		return false;
	}
	long long k=x-1;
	int t=0;
	while (!(k&1))
	{
		t++;
		k>>=1;
	}
	for (int i=0;i<12 && pri[i]<x;i++)
	{
		long long p=pw(pri[i],k,x);
		for (int j=0;j<t;j++)
		{
			long long p0=mul(p,p,x);
			if (p0==1 && p!=1 && p!=x-1)
			{
				return false;
			}
			p=p0;
		}
		if (p!=1)
		{
			return false;
		}
	}
	return true;
}
long long f(long long x,long long c,long long p)
{
	return (mul(x,x,p)+c)%p;
}
void pollardRho(long long x)
{
	if (isprime(x))
	{
		v.push_back(x);
		return;
	}
	while (true)
	{
		long long c=rand()%(x-1)+1;
		long long p=rand()%x;
		long long q=f(p,c,x);
		while  (p!=q)
		{
			long long g=__gcd(x,abs(p-q));
			if (g!=1)
			{
				pollardRho(g);
				pollardRho(x/g);
				return;
			}
			p=f(p,c,x);
			q=f(f(q,c,x),c,x);
		}
	}
}
void get(long long x)
{
	v.clear();
	pollardRho(x);
	sort(v.begin(),v.end());
	tot=0;
	fact[tot]=v[0];
	fcnt[tot]=1;
	for (int i=1;i<v.size();i++)
