template<typename T> inline T read() {
	T x(0), f(1);
	char ch = getchar();
	for(; !isdigit(ch); ch = getchar()) if(ch=='-') f=-1;
	for(; isdigit(ch); ch = getchar()) x = (x*10)+(ch^48);
	return x * f;
}

int n, cnt, ans;
ll p[3000];
bool np[3000];
multiset<ll> m;
set<pll> S;

inline void getprime() {
	for(int i = 2; i < 3000; i++) {
		if(!np[i]) p[++cnt] = i;
		for(int j = 1; j <= cnt && p[j]*i < 3000; j++) {
			np[p[j]*i] = true;
			if(i % p[j] == 0) break;
		}
	}
}

int main() {
	n = read<int>();
	getprime();
	for(int i = 1; i <= n; i++) {
		ll s = 1, r = 1;
		ll x = read<ll>();
		for(int j = 1; x != 1 && j <= cnt; j++) {
			if(x % p[j] == 0) {
				int e = 0;
				while(x % p[j] == 0) {
					x /= p[j];
					e++;
				}
				e %= 3;
				if(e == 1) s *= p[j], r *= p[j]*p[j];
				else if(e == 2) s *= p[j]*p[j], r *= p[j];
			}
		}
		s *= x;
		if(x != 1) {
			ll L = 1, R = x;
			while(L < R) {
				ll mid = (L+R+1)>>1;
				if(mid*mid <= x) L = mid;
				else R = mid-1;
			}
			if(L*L != x) r *= x*x;
			else r *= L;
		}
		//printf("%lld %lld\n", s, r);
		S.insert(s>r?mkp(s, r):mkp(r, s));
		m.insert(s);
	}

	for(spit i = S.begin(); i != S.end(); i++) {
		ll val1 = i->fst, val2 = i->snd;
		if(val1 == 1 && val2 == 1) {
			ans++;
			continue;
		}
		ll c1 = m.count(val1), c2 = m.count(val2);
		ans += max(c1, c2);
	}

	printf("%d\n", ans);
	return 0;
}

