    for(long long i = 1; i <= n; ++i)
    {
        if(arr[i] == 1)
            ++cnt[1];
        else
        {
            long long a, b;
            a = 1;
            b = 1;
            for(vector<long long>::size_type j = 0; j < prime.size(); ++j)
            {
                if(static_cast<long long>(prime[j]) * prime[j] > arr[i])
                    break;
                if(arr[i] % prime[j] == 0)
                {
                    long long cnt = 0;
                    while(arr[i] % prime[j] == 0)
                    {
                        ++cnt;
                        arr[i] /= prime[j];
                    }
                    cnt %= 3;
                    long long tmp;
                    tmp = 3 - cnt;
                    while(cnt--)
                        a *= prime[j];
                    while(tmp--)
                        b *= prime[j];
                }
            }
            if(arr[i] != 1)
            {
                a *= arr[i];
                b *= arr[i] * arr[i];
            }
            ++cnt[a];
            if(a != 1)
            {
                if(a > b)
                    swap(a, b);
                match[a] = b;
            }
        }
    }
    if(cnt.find(1) != cnt.end())
        ans = 1;
    for(auto it = match.begin();it != match.end();++it)
    {
        long long a, b;
