			while(ss%pr[2][j] == 0){
				s[i] /= pr[2][j];
				ss /= pr[2][j];
			}
			if(ss%pr[1][j] == 0){
				tmp *= pr[0][j];
				ss /= pr[1][j];
			}
			if(ss%pr[0][j] == 0){
				tmp *= pr[1][j];
				ss /= pr[0][j];
			}
			if(tmp > INF){
				tmp = 0;
				break;
			}
		}
