const int P2 = 1e5 + 10;
const int P3 = 3.2e3;

const ll NOP = 5e18;

int main() {
#ifdef NEREVAR_PROJECT
    freopen("input.txt", "r", stdin);
    freopen("output.txt", "w", stdout);
#endif
    int n;
    cin >> n;
