    for (int i = 2; i < P2; i++) {
        if (!used[i]) {
            primes.pb(i);
            for (int j = i + i; j < P2; j += i) {
                used[j] = true;
            }
        }
    }

    map<ll, int> cnt;
    map<ll, ll> opp;

    forn(i, n) {
        ll x = a[i];
        ll dir = 1, rev = 1;
        for (int p : primes) {
            if (p > P3) break;

            int deg = 0;
            while (x % p == 0) {
                x /= p;
                deg++;
            }

            if (deg) {
                deg %= 3;
                forn(j, deg) dir *= p;
                forn(j, (3 - deg) % 3) rev *= p;
            }
        }

        if (x > 1) {
            ll y = (ll)(sqrt(x + 0.5));
            dir *= x;
            if (y * y == x) {
                rev *= y;
            } else {
                if (rev * 1.0 * x * x <= 4e18) {
                    rev *= x * x;
                } else {
                    rev = NOP;
                }
            }
        }

        //cerr << a[i] << " " << dir << " " << rev << endl;

        opp[dir] = rev;
        cnt[dir]++;
    }

    int ans = 0;

    for (auto& p : cnt) {
        ll x = p.first;
        if (opp[x] == NOP) {
            ans += cnt[x];
        } else {
            ll y = opp[x];
            if (cnt.count(y) == 0) {
                ans += cnt[x];
            } else if (x < y) {
                ans += max(cnt[x], cnt[y]);
            }
        }
    }

    if (cnt.count(1ll)) ans++;

    cout << ans << endl;

    return 0;
}

