	for (int i = 1; i <= n; i++) {
		if (ss.find(a[i]) != ss.end()) continue;
		for (int j = 2154; j >= 1; j--) {
			if (a[i] % (1ll*j*j*j) == 0) {
				a[i] /= 1ll*j*j*j;
			}
		}
		f[a[i]]++;
	}
	for (int i = 1; i <= n; i++) {
		if (ss.find(a[i]) != ss.end()) continue;
		//cout << a[i] << endl;
		if (a[i] > 100000) {res += f[a[i]]; f[a[i]] = 0;};
		else {
			long long op = p(get(a[i]), 3)/a[i];
			res += max(f[a[i]], f[op]);
			f[op] = 0;
			f[a[i]] = 0;
		}
	}	
	cout << res;
}

