ull xor64(ull y) {
    y = y ^ (y<<13);
    y = y ^ (y>>7);
    y = y ^ (y<<17);
    return y;
}

ll pollard(ll n) {
    ll x = 2, y = 2, d = 1;
    int c = 0;
    constexpr int C = 30;
    while (c < C and d == 1) {
        x = xor64(x)%n;
        y = xor64(xor64(y)%n)%n;
        d = gcd(abs(x-y), n);
        c++;
    }
    if (c == C) return -2;
    if (d == n) return -1;
    return d;
}

map<ll, int> factsmall(ll n) {
    map<ll, int> mp;
    for (ll d: pr) {
        if (n < d*d) break;
        while (n % d == 0) {
            n /= d;
            mp[d]++;
        }
    }
    if (n > 1) mp[n]++;
    return mp;
}
int gc = 0;

map<ll, int> factc(ll n) {
    if (n <= TEN(5)) return factsmall(n);
    map<ll, int> mp;
    ll u = pollard(n);
    if (u == -2) {
        gc++;
        return factsmall(n);
    }
    if (u == -1) {
        mp[n]++;
        return mp;
    }
    auto mp1 = factc(u);
    auto mp2 = factc(n/u);
    for (auto p: mp1) {
        mp[p.first] += p.second;
    }
    for (auto p: mp2) {
        mp[p.first] += p.second;
    }
    return mp;
}

map<ll, int> prefact(ll n) {
    map<ll, int> mp, mp1, mp2;
    for (ll d: pr) {
        if (100 < d) break;
        while (n % d == 0) {
            n /= d;
            mp1[d]++;
        }
    }
    if (n <= TEN(5)) mp2 = factsmall(n);
    else mp2 = factc(n);
    for (auto p: mp1) {
        mp[p.first] += p.second;
    }
    for (auto p: mp2) {
        mp[p.first] += p.second;
    }
    return mp;
}

