vector<pair<LL , LL > > showclass;
LL num[maxn];
vector<pii> fac[maxn];
int N;
inline void getallfac()
{
    for(const LL& p:prime)
        for(int i=0;i<N;i++)
        {
            if(num[i]%p==0)
            {
                LL t=0;
                while(num[i]%p==0) t++,num[i]/=p;
                fac[i].PB(MP(p,t));
            }
        }
    for(int i=0;i<N;i++) if(num[i]!=1)
    {
        LL possible=sqrt(num[i]+0.5);
        if(possible*possible==num[i]) fac[i].PB(MP(possible,2));
        else fac[i].PB(MP(num[i],1));
    }
}
