        {
            for(int j=0;j<(p.S%3);j++) myclass*=p.F;
            for(int j=0;j<(3-(p.S%3))%3;j++) revclass*=p.F;
        }
        cnt[myclass]++;

        if(myclass > revclass) swap(myclass,revclass);
        showclass.PB(MP(myclass,revclass));
