V<int> multiplier = {3, 5, 7, 11, 13, 17, 19};//, 3, 5, 7, 11, 3*5, 3*7, 3*11, 5*7, 5*11, 7*11, 3*5*7, 3*5*11, 3*7*11, 5*7*11, 3*5*7*11};

ll gc = 0;
uint64_t SQUFOF( uint64_t N )
{
    if (isPrime(N)) return N;
    if (N % 2 == 0) return 2;
    for (int d: multiplier) {
        if (N % d == 0) return d;
    }
    __int128 D;
    uint64_t Po, P, Pprev, Q, Qprev, q, b, r, s;
    uint32_t L, B, i;
    s = (uint64_t)(sqrtl(N)+0.5);
    if (s*s == N) return s;
    for (int k = 0; k < (1 << int(multiplier.size())); k++) {
        D = N;
        for (int i = 0; i < int(multiplier.size()); i++) {
            if (k & (1<<i)) D *= multiplier[i];
        }
        Po = Pprev = P = sqrtl(D);
        Qprev = 1;
        Q = D - Po*Po;
        L = 2 * sqrtl( 2*s );
        B = 3 * L;
        for (i = 2 ; i < B ; i++) {                
            b = 0;
            for (int x = 1; x < 5; x++) {
                if (Po+P < (x+1)*Q) {
                    b = x;
                    break;
                }
            }
//            if (Po+P < 2*Q) b = 1;
            if (!b) b = (uint64_t)((Po + P)/Q);

            P = b*Q - P;
            q = Q;
            Q = Qprev + b*(Pprev - P);
            if ((i & 1) == 0) {
                gc++;
                r = (uint64_t)(sqrtl(Q)+0.5);
                if (r * r == Q) break;
            }
            Qprev = q;
            Pprev = P;
        };
        if (i >= B) continue;
        b = (uint64_t)((Po - P)/r);
        Pprev = P = b*r + P;
        Qprev = r;
        Q = (D - Pprev*Pprev)/Qprev;
        i = 0;
        do {
            b = 0;
            for (int x = 1; x < 5; x++) {
                if (Po+P < (x+1)*Q) {
                    b = x;
                    break;
                }
            }
//            if (Po+P < 2*Q) b = 1;
            if (!b) b = (uint64_t)((Po + P)/Q);
//            b = (uint64_t)((Po + P)/Q);
            Pprev = P;
            P = b*Q - P;
            q = Q;
            Q = Qprev + b*(Pprev - P);
            Qprev = q;
            i++;
        } while (P != Pprev);
        r = gcd(N, Qprev);
        if (r != 1 && r != N) return r;
    }
    return 0;
}

V<ll> pollard(ll n) {
    if (n == 1) return {};
    ll x;
//    x = pollard_single(n);
    x = SQUFOF(n);
    if (x == n) return {x};
    V<ll> le = pollard(x);
    V<ll> ri = pollard(n/x);
    for (ll d: ri) le.push_back(d);
    return le;
}

