#include<map>
#define x first
#define y second
namespace Luan_Gao
{
	typedef long long ll;
	typedef std::pair<ll,int> pii;
	bool iscubic(ll x)
	{
		ll y=floor(std::pow(double(x),1.0/3)+0.5);
		if(y*y*y==x)return 1;
		return 0;
	}
	const int N=100500,M=10010010,MOD=1004535809,H=19260817;
	int pri[M],minp[M],ep[M],nxt[M],tot;
	bool isit[M];
	void getpri()
	{
		for(int i=2;i<M;i++)
		{
			if(!isit[i])
			{
				pri[++tot]=i;
				minp[i]=i,ep[i]=1;
				nxt[i]=1;
			}
			for(int j=1,x;(x=i*pri[j])<M;j++)
			{
				isit[x]=1;
				if(i%pri[j]==0)
				{
					minp[x]=pri[j];
					ep[x]=ep[i]+1;
					nxt[x]=nxt[i];
					break;
				}
				minp[x]=pri[j];
				ep[x]=1;
				nxt[x]=i;
			}
		}
	}
	std::map<ll,int> G;
	ll s[N];
	pii t[40];
	int n,ans,cntp;
	void initialize()
	{
		scanf("%d",&n);ans=0;
		int tmp=0;
		for(int i=1;i<=n;i++)
		{
			scanf("%lld",s+i);
			if(iscubic(s[i]))ans=1;
			else s[++tmp]=s[i];
		}
		n=tmp;
	}
	void divide(ll x)
	{
		cntp=0;
		for(int i=1;i<=tot && x>=M;i++)
			if(x%pri[i]==0)
			{
				cntp++;
				t[cntp]=pii(pri[i],0);
				for(;x%pri[i]==0;x/=pri[i])
					t[cntp].y++;
				if((t[cntp].y%=3)==0)cntp--;
			}
		if(x>=M){t[++cntp]=pii(x,1);return;}

		for(;x>1;x=nxt[x])
			if(ep[x]%3!=0)
				t[++cntp]=pii(minp[x],ep[x]%3);
	}
	ll calc()
	{
		ll ret=0;
		for(int i=1;i<=cntp;i++)
			ret=(ret*H+t[i].x*t[i].y%MOD)%MOD;
		return ret;
	}

	void solve()
	{
		getpri();
		initialize();

//		for(int i=1;i<=n;i++)
//			printf("%lld ",s[i]);
//		printf("\n");
		for(int i=1;i<=n;i++)
		{
			divide(s[i]);
			ll hx=calc(),hy;
			for(int j=1;j<=cntp;j++)
				t[j].y=3-t[j].y;
			hy=calc();
//			printf("%lld : %lld , %lld\n",s[i],hx,hy);
			int cx=G[hx],cy=G[hy];
			if(cx>=cy)ans++;
			G[hx]++;
		}
		printf("%d\n",ans);
	}
}
int main()
{
	Luan_Gao::solve();
	return 0;
}

