ll dv(ll x){

  for(ll i=2;; i++){

    ll t=i*i*i;
    if(t>x) break;
    while(x%t==0) x/=t;

  }

  return x;

}

ll tp(ll x){
	ll A=1,B=1;
	for(ll i=2;;i++){
		if(i*i*i>x) break;
		int cnt=0;
		while(x%i==0)
		{
			x/=i;
			cnt++;
		}
		if(cnt==1) A*=i;
		else if(cnt==2) B*=i;
	}

      ll dt=(ll) floor(sqrt(x)+0.5);
	if(dt*dt==x) B*=dt;
	else A*=x;
	ll ret=A*B;
	if(ret>INF/A+1) ret=INF;
	else ret*=A;
	return ret;

}

