void get_prime()
{
	isnp[0]=isnp[1]=true;
	for(int i=2;i<maxv;++i)
	{
		if(!isnp[i])p[pnum++]=i;
		for(int j=0;j<pnum&&p[j]*i<maxv;++j)
		{
			isnp[p[j]*i]=true;
			if(i%p[j]==0)break;
		}
	}
}
