	for(int i=0;i<n;++i)
		scanf("%lld",&s[i]);
	LL rev,tri,sqr,tmp;
	int fans=0,dans=0;
	for(int i=0;i<n;++i)
	{
		rev=1;
		tmp=1;
		for(int j=0;j<pnum;++j)
		{
			tri=p[j]*p[j]*p[j];	
			while(s[i]%tri==0)s[i]/=tri;
			sqr=p[j]*p[j];
			if(s[i]%sqr==0)rev*=p[j],s[i]/=sqr,tmp*=sqr;
			else if(s[i]%p[j]==0)rev*=sqr,s[i]/=p[j],tmp*=p[j];
		}
		mp[s[i]*tmp]+=1;
		Rev[i]=rev;
		Tmp[i]=tmp;
	}
	LL ss,tt;
	bool has=false;
	for(int i=0;i<n;++i)
	{
		if(s[i]*s[i]>10000000000LL)
		{
			++fans;
			continue;
		}
		ss=s[i]*s[i]*Rev[i],tt=s[i]*Tmp[i];
		if(tt==1)
		{
			has=true;
			continue;
		}
		if(mp.find(ss)!=mp.end())
		{
			if(mp[ss]<mp[tt])
				++fans;
			else if(mp[ss]==mp[tt])
				++dans;
		}
		else ++fans;

	}
	//cout <<fans<<" "<<dans<<endl;
