int main(int argc, char* argv[])
{
    const int num3=2200;
    vector<ll> a2(num3+1);
    vector<ll> a3(num3+1);

    int i,j;
    for(i=1; i<=num3; i++) {
        a2[i]=(ll)i*i;
        a3[i]=a2[i]*i;
    }

    int n;
    scanf("%d", &n);

    map<ll,int> cnt;
    for(i=0; i<n; i++) {
        ll s;
        scanf("%lld", &s);
        for(j=2; j<=num3; j++) {
            if(s<a3[j]) break;
            while(s%a3[j]==0) {
                s/=a3[j];
            }
        }
        cnt[s]++;
    }

    int ans=0;
    if(cnt.find(1)!=cnt.end()) {
        ans++;
        cnt.erase(1);
    }

    queue<ll> que;
    {
        auto it=cnt.begin();
        for(; it!=cnt.end(); ++it) {
            que.push(it->first);
        }
    }

    while(!que.empty()) {
        ll tt=que.front();
        que.pop();

        auto it=cnt.find(tt);
        if(it==cnt.end()) continue;

        ll curr=it->first;
        ll sub=1;
        for(j=2; j<=num3; j++) {
            if(curr<a2[j]) break;
            while(curr%a2[j]==0) {
                curr/=a2[j];
                sub*=a2[j];
            }
        }
        if(curr<=sub) continue;
        ll tmp=curr*curr*sub;
        auto it2=cnt.find(tmp);
        if(it2!=cnt.end()) {
            ans += MAX(it->second, it2->second);
            ll tmp0=it->first;
            ll tmp1=it2->first;
            cnt.erase(tmp0);
            cnt.erase(tmp1);
        }
    }

    auto it=cnt.begin();
    for(; it!=cnt.end(); ++it) {
        ans+=it->second;
    }
    printf("%d\n", ans);

    return 0;
}

