void prime()    {
    for(int i = 2; i <= 1e5; ++i)   if(!kt[i])  {
        prim[++dem] = i;
        for(int idem = 2; i*idem <= 1e5; ++idem) kt[i*idem] = true;
    }
}

int powe(int x, int y)  {
    if(!y) return 1LL;
    int mid = powe(x, y/2);
    if(y & 1) return mid * mid * x;
    else return mid * mid;
}

void decomp(int x, int pos){
    divn = 0;
    //cout << "?spm x=" << x << '\n';
    for(int i = 1, v = prim[i]; i <= 450; ++i) if(x % v == 0)   {
        int tmp = 0;
        while(x % v == 0)   {
            tmp ++; x /= v;
        }
        di[++divn] = ii(v, tmp);
    }

    int maxl = 1, maxr = 1;
    FOR(i, 1, divn) {
        //cout << di[i].fi << ' ' << di[i].se << '\n';
        int tmpl = di[i].se % 3;
        int tmpr = 3 - (di[i].se % 3 == 0 ? 3 : di[i].se % 3);
        maxl *= powe(di[i].fi, tmpl);
        maxr *= powe(di[i].fi, tmpr);
    }
    maxl *= x;
    if(square[x] == true) maxr *= (int)sqrt(x);
    else maxr *= x * x;

    //cout << "en?? " << maxl << ' ' << maxr << '\n';
    f[maxl] ++; g[maxr] ++;
    in[pos] = maxl, op[pos] = maxr;
    rem.insert(maxl); rem.insert(maxr);
}

signed main()
{
