        decomp(a[i], i);

    }
    //FOR(i, 1, n) cout << in[i] << ' ' << op[i] << '\n';
    if(f.find(1) != f.end()) ans = 1;
    FOR(i, 1, n)    {
        if((rem.find(in[i]) != rem.end() || rem.find(op[i]) != rem.end() ) && in[i] != 1)    {
            ans += max(f[in[i]], g[op[i]]);
            rem.erase(in[i]); rem.erase(op[i]);
            f[in[i]] = g[op[i]] = 0;
        }
    }
    cout << ans;
}

