const ll UNDEF = -1;
const ll INF=1e18;
template<typename T> inline bool chkmax(T &aa, T bb) { return aa < bb ? aa = bb, true : false; }
template<typename T> inline bool chkmin(T &aa, T bb) { return aa > bb ? aa = bb, true : false; }
const ll MAXN=1e5+4;
const ll MAXP=MAXN;
bool sieve_array[MAXP+1];
ll sp[MAXP+1];
vector<ll> gpv;
void sieve() {
	for (ll i = 0; i <= MAXP; i++) {
		sieve_array[i] = true;
		sp[i]=INF;
	}
	sieve_array[0] = false; sieve_array[1] = false;
	ll lim = sqrt(MAXP)+1;
	for (ll i = 2; i <= lim; i++) {
		if(sieve_array[i]) {
			for (ll j = i*i; j <= MAXP; j+=i) {
				sieve_array[j] = false;
				chkmin(sp[j],i);
			}
		}
	}
	for (ll i = 2; i <= MAXP; i++) {
		if(sieve_array[i]) {
			gpv.PB(i);
			chkmin(sp[i],i);
		}
	}
}
map<ll,ll> factorize(ll x) {
	map<ll,ll> h;
	while(x>=MAXP) {
		bool found=false;
		for (auto &p:gpv) {
			if (p*p>x) break;
			if ((x%p)==0) {
				x/=p;
				h[p]++;
				found=true;
				break;
			}
		}
		if (!found) break;
	}
	if (x<MAXP) {
		while(x>1) {
		ll p=sp[x];
		x/=p;
		h[p]++;
		}
	}
	if (x>1) h[x]++;
	return h;
}
int main() {
  ll n; scanf("%lld",&n);
	sieve();
	map<vector<pair<ll,ll> >, ll> h;
	for (ll i=0;i<n;i++) {
		ll x; scanf("%lld",&x);
		map<ll,ll> factors=factorize(x);
		vector<pair<ll,ll> > get;
		for (auto &w:factors) {
			w.second%=3;
			if (w.second>0) {
				get.PB(MP(w.first,w.second));
			}
		}
		/*printf("%lld\n",a[i]);
		for (auto &w:factors) printf("%lld->%lld\n",w.first,w.second);*/
		h[get]++;
	}
	ll ans=0;
	{
		vector<pair<ll,ll> > empty;
		auto it=h.find(empty);
		if (it!=h.end()) {
			ans++;
			h.erase(it);
		}
	}
	for (auto &w:h) {
		vector<pair<ll,ll> > key=w.first;
		for (auto &w:key) {
			w.second=3-w.second;
		}
		auto it=h.find(key);
		ll other;
		if (it==h.end()) {
			other=0;
		}
		else {
			other=it->second;
			h.erase(it);
		}
		ans+=max(w.second,other);
	}
	printf("%lld\n",ans);
}

