            auto index = lower_bound(primeSqs.begin(), primeSqs.end(), y) -
                         primeSqs.begin();
            y = 1;
            z *= primes[index];
        }

        z *= y * y;

        if (cnt.count(z)) {
            ans += max(x.second, cnt[z]);
            used.insert(z);
        } else {
            ans += x.second;
        }
    }

