void sieve(){
    isP[1] = 1;
    for(int i = 2 ; i < M ; i++){
        if(isP[i]) continue;
        prime.push_back(i);
        for(ll j = i * 1LL * i ; j < M ; j += i){
            isP[j] = 1;
        }
    }
}

ll fin(ll x){
    ll res = x;
    for(int i = 0 ; i < prime.size() ; i++){
        ll ex = prime[i] * prime[i] * prime[i];
        if(ex > res) break;
        while(res%ex == 0) res /= ex;
    }
    return res;
}

ll complement(ll x){
    ll res = 1;
    for(int i = 0 ; i < prime.size() ; i++){
        if(prime[i] * prime[i] > x) break;
        ll ex = prime[i];
        if(x%ex == 0){
            x/=ex;
            if(x%ex == 0){
                x/=ex;
                res *= ex;
            }
            else{
                res *= ex;
                res *= ex;
            }
        }
    }
    if(x > 1){
        res *= x;
        res *= x;
    }
    return res;
}

