void Init()
{
	for(int i=2;i<=N;i++)
	{
		if(!vis[i])
            p[++pcnt]=i,calc[1ll*i*i]=i;
		for(int j=1;i*p[j]<=N;j++)
		{
			vis[i*p[j]]=true;
			if(i%p[j]==0)
                break;
		}
