		tmp=a;
		for(int j=1;j<=pcnt&&1ll*p[j]*p[j]*p[j]<=a;j++)
			if(tmp%p[j]==0)
			{
				int xcnt=0;
				while(tmp%p[j]==0)
                    tmp/=p[j],xcnt++;
				xcnt%=3;
				int xxcnt=xcnt;
				while(xxcnt--)
                    h*=p[j];
				for(int i=1;i<=(3-xcnt)%3;i++)
                    inv*=p[j];
			}
		if(tmp>1)
		{
			h*=tmp;
			miter it=calc.find(h);
			if(it!=calc.end())
                inv*=it->second;
			else
                inv*=tmp*tmp;
		}
		cnt[h]++;
		inver[h]=inv,inver[inv]=h;
	}
    if(cnt.find(1)!=cnt.end()){
        ans++;
        cnt.erase(1);
    }
	for(miter it=cnt.begin();it!=cnt.end();it++)
		if(cnt.find(inver[it->first])==cnt.end())
            ans+=it->second;
		else
		{
			ans+=max(it->second,cnt[inver[it->first]]);
			it->second=cnt[inver[it->first]]=0;
		}
	printf("%d\n",ans);
}

#include <bits/stdc++.h>
#define maxn 100010
#define ll long long
using namespace std;

int prime[maxn],check[maxn],tot,n;

ll p1[maxn],p2[maxn],ans;

map <ll,ll> s,vis;

void init(){
    check[1]=1;
    for(int i=2;i<=2200;i++){
        if(!check[i]) prime[++tot]=i;
        for(int j=1;j<=tot&&prime[j]*i<=2200;j++){
            check[prime[j]*i]=1;
            if(i%prime[j]==0) break;
        }
    }
}

int main(){
    init();
    scanf("%d",&n);
    for(ll cnt=1;cnt<=n;cnt++){
        ll x,a=1,b=1;
        scanf("%lld",&x);
        for(int i=1;i<=tot;i++){
            int sum=0;
            if(prime[i]>x) break;
            if(x%prime[i]!=0) continue;
            while(x%prime[i]==0) x/=prime[i],sum++;
            sum%=3;
            if(sum==0) continue;
            for(int j=1;j<=sum;j++) a*=prime[i];
            for(int j=sum+1;j<=3;j++) b*=prime[i];
        }
        ll tmp=1ll*sqrt(x);
        if(tmp*tmp==x) a*=tmp*tmp,b*=tmp;
        else a*=tmp,b*=tmp*tmp;
        p1[cnt]=a;p2[cnt]=b;
        s[a]++;
    }
    for(int i=1;i<=n;i++){
        ll x;
        if(vis[p1[i]]||vis[p2[i]]) continue;
        if(s[p1[i]]>s[p2[i]])  x=p1[i];
        else x=p2[i];
        vis[x]=1;
        if(x==1) ans++;
        else ans+=s[x];
    }
    printf("%lld",ans);
    return 0;
}

