ll lillrot(ll i){
    ll b = 1;
    if(i == 1){return 1;}


    ll a = round(pow(i , ld(1)/ld(3)));
    if(a*a*a == i){
        return 1;
    }
    a = round(pow(i , ld(1)/ld(4)));
    if(a*a*a*a == i){
        return a;
    }

    for(ll c2 = 1; c2*c2*c2 <= i; c2++){
        ll c = c2*c2*c2;
        if(i%c == 0){b = c;}
    }
    return i/b;
}

