using namespace std;
int n,t,p[3005],prime[3005],cnt,len;
long long s[100005];
struct num{
	long long ui;
	int vi;
}Num[100005];
int ans;

long long read(){
	long long x=0;char ch=getchar();
	while(!isdigit(ch)) ch=getchar();
	while(isdigit(ch)) x=(x<<3)+(x<<1)+(ch^48),ch=getchar();
	return x;
}

int main(){
	n=read();
	for(int i=1;i<=n;i++) s[i]=read();
	t=2200;
	for(int i=2;i<=t;i++){
		if(p[i]==0) prime[++cnt]=i;
		for(int j=1;j<=cnt&&i*prime[j]<=t;j++){
			p[i*prime[j]]=1;
			if(i%prime[j]==0) break;
		}
	}
	for(int i=cnt;i>=1;i--){
		long long P=1ll*prime[i]*prime[i]*prime[i];
		for(int j=1;j<=n;j++) while(s[j]%P==0) s[j]/=P;
	}
	sort(s+1,s+n+1);
	for(int i=1;i<=n;i++){
		if(s[i]!=s[i-1]) Num[++len].ui=s[i],Num[len].vi=1;
		else Num[len].vi++;
	}
	for(int i=1;i<=len;i++){
		long long Ans=1,si=Num[i].ui,oi;
		if(si==1){ans++;continue;}
		for(int j=1;j<=cnt;j++){
			oi=0;while(si%prime[j]==0) si/=prime[j],oi++;
			if(oi!=0&&Ans!=-1){
				oi=3-oi;
				for(int i=1;i<=oi;i++){
					Ans=1ll*Ans*prime[j];
					if(Ans>=1e10){Ans=-1;break;}
				}
			}
		}
		if(Ans>=1e10||Ans==-1) Ans=-1;
		else if(si!=1){
			int o=sqrt(si);
			if(1ll*o*o==si) Ans=1ll*Ans*o;
			else if(Ans<=(1e10)/(1ll*si*si)) Ans=1ll*Ans*si*si;
			else Ans=-1;
		}
		if(Ans>=1e10||Ans==-1) Ans=-1;
		int l=1,r=len,mid,op=0;
		while(l<=r){
			mid=(l+r)/2;
			if(Num[mid].ui<=Ans) op=max(op,mid),l=mid+1;
			else r=mid-1;
		}
		if(Num[op].ui==Ans&&op>i) ans+=max(Num[op].vi,Num[i].vi);
		else if(Num[op].ui!=Ans) ans+=Num[i].vi;
	}
	printf("%d\n",ans);

	return 0;
}

