pair<int, int> f(int n) {
    int ret1{1}, ret2{1};
    for (int i = 2; i * i <= n; i++) {
        if (n % i == 0) {
            int num = 0;
            while (n % i == 0) {
                num++;
                n /= i;
            }
            num %= 3;
            if (num > 0) {
                ret1 *= intpow(i, num);
                ret2 *= intpow(i, 3);
            }
        }
    }
    if (n != 1) {
        ret1 *= n;
        ret2 *= intpow(n, 3);
    }
    ret2 /= ret1;
    return {ret1, ret2};
}
int N, S[101010];
