        rev[tmp.first] = tmp.second;
    }
    int ans = 0;
    while (!M.empty()) {
        auto p = *M.begin();
        if (p.first == 1)
            ans++;
        else {
            ans += max(p.second, M.count(rev[p.first]) ? M[rev[p.first]] : 0ll);
        }
        //cout << p.first << " " << rev[p.first] << endl;
        M.erase(p.first);
        M.erase(rev[p.first]);
    }
    cout << ans << endl;
}

