#include <bits/stdc++.h>
using namespace std;
typedef long long LL;
typedef pair<int, int> pii;

const int maxn = (int)(1e5) + 5;
map<LL, pii> H;
int pr[maxn], chk[maxn];
LL db[maxn];
int qM;

int Find(LL x) {
	int p = lower_bound(db + 1, db + qM + 1, x) - db - 1;
	return 1LL * p * p == x ? p : 0;
}

int main() {
	int n, ret = 0;
	scanf("%d", &n);
	LL M = (LL)(1e10); 
	int mx = 0, c = 0, sgn = 0;
	for (LL i = 1; i * i <= M; ++i) db[++qM] = i * i;
	for (LL i = 1; i * i * i <= M; ++i, ++mx); 
	for (int i = 2; i <= mx; ++i) if (!chk[i]) {
		pr[++c] = i; for (int j = i + i; j <= mx; j += i) chk[j] = 1;
	} 
	for (int i = 1; i <= n; ++i) {
		LL x; scanf("%lld", &x); 
		int T = 0; LL now = 1;
		for (int j = 1; j <= c; ++j) if (x % pr[j] == 0) {
			int cnt = 0; 
			while (x % pr[j] == 0) x /= pr[j], ++cnt;
			cnt %= 3; if (cnt) {
				if (!T) T = cnt, now *= pr[j];
				else {
					if (T == 2) cnt = 3 - cnt; 
					while (cnt--) now *= pr[j];
				}
			}
		} int p = 0;
		if (x > 1) {
			if (p = Find(x)) {
				if (!T) T = 2, now *= p;
				else if (T == 1) now *= 1LL * p * p;
				else if (T == 2) now *= p;
			} else if (x <= qM) {
				if (!T) T = 1, now *= x;
				else if (T == 1) now *= x; 
				else if (T == 2) now *= x * x;
			} else {
				++ret; continue;
			}
		}
		if (now == 1) {
			if (!sgn) ++ret, sgn = 1;
		} else {
			int ww = 0;
			if (!H.count(now)) {
				H[now] = make_pair(0, 0); ww = 1; ++ret;
			} else ww = max(H[now].first, H[now].second);
			if (T == 1) H[now].first++; else H[now].second++;
			if (max(H[now].first, H[now].second) > ww) ++ret;
		}
	}
	return printf("%d\n", ret), 0;
}

