	for (int i = 1; i < 2000; i++) {
		long long P = 1LL * i*i*i*t[pos]; if (P > 10000000000LL)break;
		if (p[pos][i] == false)continue;
		int pos1 = lower_bound(vec.begin(), vec.end(), make_pair(P, 0)) - vec.begin(); cnt++;
		if (forced[pos1] == true)continue;
		forced[pos1] = true;
		while (pos1 < vec.size() && vec[pos1].first == P) {
			dfs(vec[pos1].second, depth ^ 1); pos1++;
		}
	}
}
