		for (int j = 0; j < n; j++)buckets[(u2[j] >> (16 * i))&(65535)].emplace_back(u2[j]);
		int cnt = 0;
		for (int j = 0; j < 65536; j++) {
			for (int k = 0; k < buckets[j].size(); k++) {
				u2[cnt] = buckets[j][k]; cnt++;
			}
		}
	}
}
