			cnt %= 3;
			if (cnt == 1){
				num *= pr[j];
				prod *= pr[j] * pr[j];
			}
			else if (cnt == 2){
				num *= pr[j] * pr[j];
				prod *= pr[j];
			}
			if (prod > 10000000000LL){
				sign = 1;
				break;
			}
		}
		if (sign){
			ans++;
			continue;
		}
		if (temp > 1){
			d = lower_bound(sqr + 1, sqr + tot + 1, temp) - sqr;
			if (sqr[d] == temp){
				num *= temp;
				prod *= pr[d];
				rec[num]++;
				sav[num] = prod;
			}
			else{
				if (10000000000LL / prod < temp * temp) ans++;
				else{
					num *= temp;
					prod *= temp * temp;
					rec[num]++;
					sav[num] = prod;
				}
			}
		}
		else{
			if (prod == 1) flag = 1;
			else{
				rec[num]++;
				sav[num] = prod;
			}
		}
	}
	for (auto it : sav){
		ans += max(rec[it.first], rec[it.second]);
		rec[it.first] = 0;
		rec[it.second] = 0;
	}
	ans += flag;
	printf("%d\n", ans);
	return 0;
}

