ll cubic_characteristic(ll x) {
	int i; ll C;
	for (i = 0; i < pn && (C = (ll)p[i] * p[i] * p[i]) <= x; ++i)
		for (; !(x % C); x /= C);
	return x;
}

ll Compl(ll x) {
	int i; ll t, y = 1;
	for (i = 0; i < pn && p[i] <= x; ++i)
		x % (p[i] * p[i]) ? (x % p[i] ? 0 : (y *= p[i] * p[i], x /= p[i])) : (y *= p[i], x /= p[i] * p[i]);
	return t = sqrt(x), y * min(INF / y, t * t == x ? t : x * x);
}

