void prelude() {
	memset(isp, 1, sizeof isp);
	isp[0] = isp[1] = 0;
	for( int i = 2; i < N; ++i )
		if( isp[i] )
			for( int j = i+i; j < N; j += i )
				isp[j] = 0;
	for( int i = 2; i < N; ++i )
		if( isp[i] ) prime[pcnt++] = i;
}

int n;
