  is_prime[0]=is_prime[1]=false;
  for(int i=2; i<=n; i++){
    if(is_prime[i]){
      prime[p++]=i;
      for(int j=2*i; j<=n; j+=i) is_prime[j]=false;
    }
  }
  return p;
}

ll dv(ll x){

  for(int i=0; i<NP; i++){

    ll q=prime[i];
    ll t=q*q*q;
    if(t>x) break;
    while(x%t==0) x/=t;

  }

  return x;

}

