#define MAXL (50000>>5)+1
#define GET(x) (mark[x>>5]>>(x&31)&1)
#define SET(x) (mark[x>>5] |= 1<<(x&31))
mt19937 rnd(chrono::steady_clock::now().time_since_epoch().count());
int mark[MAXL];
int P[50000], Pt = 0;
void sieve() {
	register int i, j, k;
	SET(1);
