        break;
      }
      if (x % p) {
        continue;
      }
      int ti = 0;
      for (; x % p == 0; x /= p) {
        ++ti;
      }
      ti %= 3;
      if (ti) {
        for (int j = 0; j < ti; ++j) {
          nx *= p;
        }
        for (int j = ti; j < 3; ++j) {
          y *= p;
        }
      }
    }

    if (x > 1) {
