ll conj(ll k) {
  ll l = k;
  ll A = 1;
  ll B = 1;
  for (auto x : prime_num) {
    int t = 0;
    while (l % x == 0) {
      l /= x;
      t++;
    }
    if (t == 1) {
      A *= x;
    } else if (t == 2) {
      B *= x;
    }
  }
  ll red = k / (A * B * B);
  ll sq = floor(sqrt(red)+0.1);
  // cerr << "red = " << red << " , sq = " << sq << endl;
  if (red == sq * sq) {
    B *= red;
  } else if (red > 100010) {
    return infty;
  } else {
    A *= red;
  }
  return A * A * B;
}

