pair<llint,pair<llint,llint>> han(llint in){//3乗を除いたもの,1乗部分,2乗部分の平方根
	pair<llint,llint> ans;
	ans=mp(1LL,1LL);
	int gen;
	for(auto i:prime){
		gen=0;
		while(in%i==0){in/=i;gen++;}
		if(gen%3==1){ans.fir*=i;}
		if(gen%3==2){ans.sec*=i;}
	}
	ans.fir*=in;
	return mp(ans.fir*ans.sec*ans.sec,ans);
}
int main(void){
	init();
	llint ans=0;
	int i,n;cin>>n;
	map<llint,pair<llint,pair<llint,llint>>> a;//惨状を除く,回数,1部,2部
	llint q;
	for(i=0;i<n;i++){
		cin>>q;
		auto ret=han(q);
		auto dai=mp(a[ret.fir].fir+1,ret.sec);
		a[ret.fir]=dai;
	}
	for(auto itr=a.begin();itr!=a.end();itr++){
		auto &it=*itr;
		if(it.fir==1){ans++;continue;}
		if(it.sec.sec.fir>100000){ans+=it.sec.fir;continue;}
		llint th=it.sec.sec.fir*it.sec.sec.fir*it.sec.sec.sec;
		if(a.count(th)!=0){
