int main() {
  vector<char> primes_(100000 + 10, 1);
  vector<int> primes;
  for (int i = 2; i <= 100000; ++i) {
    if (!primes_[i]) continue;
    primes.push_back(i);
    for (int j = i * 2; j < 100000; j += i) primes_[j] = 0;
  }

  int N;
  while (scanf("%d", &N) != EOF) {
    map<vector<ll>, int> cnt;

    for (int i : range(N)) {
      ll x;
      scanf("%lld", &x);

      vector<ll> v;
      for (int i : primes) {
        if (x % i != 0) continue;
        ll r = 0;
        while (x % i == 0) {
          x /= i;
          r = (r + 1) % 3;
        }
        if (r) {
          v.push_back(i);
          v.push_back(r);
        }
      }
      if (x > 1) {
        v.push_back(x);
        v.push_back(1);
      }

      //for (auto y : v) cout << y << " " ;
      //cout << endl;
      cnt[v]++;
    }

    ll res = 0;
    for (auto& it : cnt) {
      vector<ll> now = it.first, cmp = now;
      if (now.size() == 0) {
        // special element
        res += 1;
        continue;
      }

      for (int i = 1; i < cmp.size(); i += 2) cmp[i] = 3 - cmp[i];
      if (cnt.find(cmp) != cnt.end() && now > cmp) continue;

      res += max(it.second, cnt[cmp]);
    }
    printf("%lld\n", res);
  }
}

