map<ll, ll> mp;
bool mark[A];

vector<ll> p;

int main()
{
	ios::sync_with_stdio(false);

	int n, ans = 0;
	cin >> n;
	for (int i=2; i<A; i++)
	{
		if (mark[i])
			continue;
		p.push_back(i);
		for (int j=i; j<A; j+=i)
			mark[j] = 1;
	}
	for (int i=0; i<n; i++)
	{
		ll x;
		cin >> x;
		for (int j=0; j<(int)p.size(); j++)
		{
			ll t = p[j] * p[j] * p[j];
			while (x % t == 0)
				x /= t;
		}
		if (x == 1)
			ans = 1;
		else
			mp[x]++;
	}
	for (auto& x : mp)
	{
		ll tmp = x.first;
		ll num = 1;
		for (int i=0; i<(int)p.size(); i++)
		{
			if (tmp % (p[i] * p[i]) == 0)
				num *= p[i];
			else if (tmp % p[i] == 0)
				num *= p[i] * p[i];
			while (tmp % p[i] == 0)
				tmp /= p[i];
		}
		ll y = sqrt(tmp);
		if (y * y == tmp)
			num *= y;

		if (tmp != 1)
			ans += x.second;
		else if (num > x.first)
			ans += max(x.second, mp.count(num) ? mp[num] : 0LL);
	}
	cout << ans << "\n";
	return 0;
}

