const int N= (int)1e5+10;
const long oo= (long)1e10+1;
int n;
long a[N],rev[N];
map<long,int> cnt;

void input()
{
    cin>>n;
    up(i,1,n) cin>>a[i];
}

void solve()
{

    up(i,1,n)
    {
    	rev[i]= 1; long A= a[i]; long remain= a[i];
    	a[i]= 1;
        for (long j= 2; j*j*j<= A; j++)
		{
            long j3= j*j*j;
            while (remain%j3==0) remain/= j3;
            long j2= j*j;
            if (remain%j2==0)
			{
				rev[i]*= j; a[i]*= j2;
			}
            else if (remain%j==0)
			{
				rev[i]*= j2; a[i]*= j;
			};
            if (rev[i]>oo) rev[i]= oo;

            while (remain%j==0) remain/= j;
		}

		a[i]*= remain;
        long can= (long)sqrt(remain);
        if (can*can== remain)
		{
			rev[i]*= can;
			if (rev[i]>oo) rev[i]= oo;
		}
		else
		{
			rev[i]*= remain;
			if (rev[i]>oo) rev[i]= oo;
			rev[i]*= remain;
			if (rev[i]>oo) rev[i]= oo;
		};

		cnt[a[i]]++;
    }
    int res= 0;
    up(i,1,n)
    {
    	if (cnt[a[i]]==0) continue;
    	if (a[i]==1)
		{
			res++; cnt[a[i]]= 0;
		}
		else
		{
			res+= max(cnt[a[i]],cnt[rev[i]]);
			cnt[a[i]]= cnt[rev[i]]= 0;
		}
    }
    cout<<res;
}

