const ll magic = 2500;

int n, ans;
ll s[100*1000+5];

bool botherwithit;

void end(primes &p, ll x) {
    ll y = std::sqrt(double(x));
    for (ll d = y-1; d <= y+2; d++) {
        if (d*d == x) {
            x = 1;
            p.eb(d, 2);
        }
    }
    if (x > 1) {
        botherwithit = false;
        ans++;
    }
}

primes factor(ll x) {
    primes p;
    for (ll d = 2; d < magic && d*d <= x; ) {
        int k = 0;
        while ((x%d) == 0) {
            x /= d;
            k++;
        }
        if (k) p.eb(d, k);
        if (d == 2) d++;
        else d += 2;
    }
    if (x >= magic*magic) {
        end(p, x);
    } else if (x > 1) {
        p.eb(x, 1);
    }
    return p;
}

