ll p1[maxn],p2[maxn],ans,prime[maxn],check[maxn],tot,n;

map <ll,ll> s,sqr;
map <ll,bool> vis;

void init(){
    for(int i=2;i<=100000;i++){
        if(!check[i]) prime[++tot]=i,sqr[1ll*i*i]=i;
        for(int j=1;j<=tot&&prime[j]*i<=100000;j++){
            check[prime[j]*i]=1;
            if(i%prime[j]==0) break;
        }
    }
}

int main(){
    init();
    scanf("%lld",&n);
    for(ll cnt=1;cnt<=n;cnt++){
        ll x,a=1,b=1;
        scanf("%lld",&x);
        for(int i=1;i<=tot;i++){
            int sum=0;
            if(1ll*prime[i]*prime[i]*prime[i]>x) break;
            if(x%prime[i]!=0) continue;
            while(x%prime[i]==0) x/=prime[i],sum++;
            sum%=3;
            if(sum==0) continue;
            for(int j=0;j<sum;j++) a*=prime[i];
            for(int j=sum;j<3;j++) b*=prime[i];
        }
        ll tmp=sqr[x];
        if(tmp*tmp==x) a*=x,b*=tmp;
        else a*=x,b*=x*x;
        p1[cnt]=a;p2[cnt]=b;
        s[a]++;
    }
    for(int i=1;i<=n;i++){
        ll x;
        if(vis[p1[i]]||vis[p2[i]]) continue;
        if(s[p1[i]]>s[p2[i]]) x=p1[i];
        else x=p2[i];
        vis[p1[i]]=vis[p2[i]]=true;
        if(x==1) ans++;
        else ans+=s[x];
    }
    printf("%lld",ans);
    return 0;
}

