        {
            LL v = 1ll * d * d * d;
            if(v > x) break ;
            while(x % v == 0) x /= v;
        }
        G[x]++ , L[i] = x;
        LL y = 1;
        for(int d : pri) if(x % d == 0)
        {
            y *= (x % (1ll * d * d) == 0 ? d : 1ll * d * d);
            while(x % d == 0) x /= d;
        }
        y *= check(x) ? x : x * x;
        R[i] = y;
    }
    if(G[1])
        Ans += 1 , G[1] = 0;
    rep(i , 1 , n)
        Ans += max(G[L[i]] , G[R[i]]) , G[L[i]] = G[R[i]] = 0;
    cout << Ans << endl;
    return 0;
}

