#include <iostream>
#include <vector>
#include <map>
#include <bitset>
#include <cmath>

using namespace std;

const int kMax = 2200;
const int kMaxPr = 500;
const double eps = 1e-10;

void Init(vector < int > &prime) {

  bitset < kMax > used;
  int index = 0;
  for (int pr = 2; pr < kMax; pr ++) {
    if (used[pr]) {
      continue;
    }
    prime[++ index] = pr;

    for (int j = pr * 2; j < kMax; j += pr) {
      used[j] = true;
    }
  }

  prime[0] = index;
}

void solve(vector < long long > &element, vector < int > &prime, map < long long, long long > &hash, 
  map < long long, long long > &comp, map < long long, int > &frecv, int n) {

  for (int i = 1; i <= n; i ++) {
    cin >> element[i];

    long long k = element[i];
    if (hash[k]) {
      frecv[hash[k]] ++;
      continue;
    }

    hash[k] = 1ll;
    comp[k] = 1ll;
    for (int j = 1; j <= prime[0] and k != 1 and prime[j] * prime[j] <= k; j ++) {
      if (k % prime[j] != 0) {
        continue;
      }

      int elExp = 0;
      while (k % prime[j] == 0) {
        elExp ++;
        k /= prime[j];
      }

      elExp %= 3;
      if (elExp == 0) {
        continue;
      }

      if (elExp == 1) {
        hash[element[i]] *= 1ll * prime[j];
        comp[element[i]] *= 1ll * prime[j] * prime[j];
      }
      else {
        hash[element[i]] *= 1ll * prime[j] * prime[j];  
        comp[element[i]] *= 1ll * prime[j];
      }
    }

    hash[element[i]] *= k;
    double sq_root = sqrt(k);
    if (sq_root - floor(sq_root) < eps) {
      comp[element[i]] *= sq_root;
    }
    else {
      double aux = hash[element[i]];
      aux *= (double)k * (double)k;
      if (aux < 1e18) {
        comp[element[i]] *= k * k;
      }
      else {
        comp[element[i]] = 0;
      }
    }

    frecv[hash[element[i]]] ++;
    comp[hash[element[i]]] = comp[element[i]];
  }
}

int main(int argc, char const *argv[]) {

  vector < int > prime(kMaxPr);
  Init(prime);

  int n;
  cin >> n;

  vector < long long > element(n + 1);
  map < long long, long long > hash;
  map < long long, long long > comp;
  map < long long, int > frecv;

  solve (element, prime, hash, comp, frecv, n);

  map < long long, bool > used;
  used[1] = true;
  int to_remove = frecv[1] > 0 ? frecv[1] - 1 : 0;
  for (auto &x : frecv) {
    if (used[x.first]) {
      continue;
    }

    long long k = x.first;
    int c = frecv[comp[k]];

    to_remove += min(x.second, c);
    used[comp[k]] = true;
  }

  cout << n - to_remove << '\n';
}

