const int N = 100005;
int lpf[N];
vector<int> primes;

void pre(){
	memset(lpf, -1, sizeof(lpf));
	for(int n = 2; n < N; n++){
		if(lpf[n] == -1){
			primes.push_back(n);
			for(int m = n; m < N; m += n){
				if(lpf[m] == -1)lpf[m] = n;
			}
		}
	}
}

pair<ll, ll> reduce(ll n){
	ll ret1 = 1, ret2 = 1;
	if(n < N){
		while(n > 1){
			int cnt = 0;
			ll x = lpf[n];
			while(n%x == 0){
				cnt++;
				n /= x;
			}
			cnt %= 3;
			if(cnt == 1){
				ret1 *= x;
				ret2 *= x*x;
			}else if(cnt == 2){
				ret1 *= x*x;
				ret2 *= x;
			}
		}
		return {ret1, ret2};
	}
	for(auto x : primes){
		if(x*x > n)break;
		if(n%x)continue;
		int cnt = 0;
		while(n%x == 0){
			n /= x;
			cnt++;
		}
		cnt %= 3;
		if(cnt == 1){
			ret1 *= x;
			ret2 *= x*1LL*x;
		}else if(cnt == 2){
			ret1 *= x*1LL*x;
			ret2 *= x;
		}
	}
	if(n > 1){
		ret1 *= n;
		ret2 *= n*n;
	}
	return {ret1, ret2};
}

