	for(int i = 1; i <= n; i++){
		ll x; cin>>x;
		pair<ll, ll> tmp = reduce(x);
		if(tmp.first == 1){
			cnt++;
		}else{
			red[tmp.first] = tmp.second;
			mp[tmp.first]++;
		}
	}
	int ans = (cnt > 0);
	set<ll> st;
	for(auto x : mp){
		int val = x.first;
		if(st.find(val) != st.end())continue;
		ans += max(x.second, mp[red[val]]);
		st.insert(val);
		st.insert(red[val]);
	}
	cout<<ans<<endl;



	return 0;
}

