ll inv(ll x){
    ll res=1;
    for(int p:Q){
        if(x%p!=0) continue;
        ll pp=1LL*p*p, mul=1;
        if(x%pp==0){
            x/=pp; mul=p;
        }
        else if(x%p==0){
            x/=p; mul=pp;
        }
        if(mul>inf/res){
            return -1;
        }
        res*=mul;
    }
    if(x>1){
        ll mul=1;
        if(S[x]!=0) mul=S[x];
        else{
            if(x>inf/x) return -1;
            mul=x*x;
        }
        if(mul>inf/res){
            return -1;
        }
        res*=mul;
    }
    return res;
}

ll red(ll x){
    for(ll c:C)
        while(x%c==0)
            x/=c;
    return x;
}

