class Osak{
public:
    vector<int> div;
    Osak(int N) : div(N+1,0) {
        div[1] = 1;
        for(int i = 2; i*i <= N; ++i) {
            if(div[i]) continue;
            for(int j = i; j <= N; j += i) div[j] = i;
        }
    }
    inline vector<pair<int,int>> prime_factorization(int A) {
        assert(A < div.size());
        vector<int> tmp;
        while (A != 1) {
            int& p = div[A];
            tmp.push_back(p);
            A /= p;
        }
        sort(tmp.begin(),tmp.end());
        vector<pair<int,int>> ret;
        int prev = 0,cnt = 0;
        for(int& p: tmp) {
            if(prev == p) {
                cnt++;
            }
            else {
                cnt %= 3;
                if(cnt) ret.push_back({prev,cnt});
                cnt = 1;
            }
            prev = p;
        }
        {
            cnt %= 3;
            if(cnt) ret.push_back({prev,cnt});
        }
        return ret;
    }
};

/*
 * @title Eratosthenes
 * @docs md/math/Eratosthenes.md
 */
inline static vector<int> PrimeSieve(int N) {
    vector<int> res(N + 1, 1),sieve;
    res[0] = res[1%(N+1)] = 0;
    for (int i = 1; i*i <= N; i++) if (res[i]) for (int j = 2 * i; j <= N; j += i) res[j] = 0;
    for (int i = 2; i <= N; ++i) if (res[i]) sieve.push_back(i);
    return sieve;
}

int main() {
    cin.tie(0);ios::sync_with_stdio(false);
    int N, SQRT_A = 100000, p3=0; cin >> N;
    Osak osak(SQRT_A);
    auto P = PrimeSieve(SQRT_A);
    int ans = 0;
    map<vector<pair<int,int>>,pair<int,int>> mp;
    for(int i = 0; i < N; ++i) {
        ll A; cin >> A;
        vector<pair<int,int>> pf;
        if(A<=SQRT_A) {
            pf = osak.prime_factorization(A);
        }
        else {
            for(int& p:P) {
                int cnt = 0;
                while(A%p == 0) {
                    A /= p;
                    cnt++;
                }
                cnt %= 3;
                if(cnt) pf.emplace_back(p,cnt);
            }
            if(A != 1) {
                ans++;
                continue;
            }
        }
        if(pf.empty()) {
            p3 = 1;
            continue;
        }
        vector<pair<int,int>> mr;
        for(auto& e:pf) mr.emplace_back(e.first,3-e.second);
        if(pf.front().second > mr.front().second) {
            swap(pf,mr);
            if(!mp.count(pf)) mp[pf]={0,0};
            mp[pf].second++;
        }
        else {
            if(!mp.count(pf)) mp[pf]={0,0};
            mp[pf].first++;
        }
    }
    for(auto& e:mp) ans += max(e.second.first,e.second.second);
    ans += p3;
    cout << ans << endl;
    return 0;
}

