ll iss(ll n)
{
	ll t=sqrt(n);
	for(ll i=t-2;i<=t+2;i++) if(i>0)if(i*i==n) return i;
	return 0;
}

map<ll,ll> m,rev;ll cnt1;
void solve(ll n)
{
	if(n==1) 
	{
		cnt1++;
		return ;
	}
	ll nr=1,rr=1;ll cn=n;
	for(int i=0;i<ps.size();i++)
	{
		ll p=ps[i];
		if(n%p==0)
		{
			ll cnt=0;
			while(n%p==0) n/=p,cnt++;
			cnt%=3;
			if(cnt==0) continue;
			if(cnt==1) nr=nr*p,rr=rr*p*p;
			else nr=nr*p*p,rr=rr*p;
		}
	}
	ll tp=iss(n);
	if(tp)
		nr=nr*n,rr=rr*tp;
	else
		nr=nr*n,rr=rr*n*n;
	if(nr==1)
	{
		cnt1++;
		return ;
	}

	rev[nr]=rr,m[nr]++;
}
int main()
{
	ini();
	int n;scanf("%d",&n);
