mt19937 eng(chrono::steady_clock::now().time_since_epoch().count());

const int P = 1;
const int S = 60;
const int SQ = sqrt(1e3);

ll m, cube;
map<vector<pll>, int> cnt;
map<vector<pll>, bool> used;

bool isCube(ll x) {
    ll y = cbrt(x);
    return y * y * y == x;
}

ll pollardRho(ll n) {
    if(n % 2 == 0) {
        return 2;
    }

    ll x, y, g = 1, a;
    x = eng() % n + 1;
    y = x;
    a = eng() % n + 1;

    int steps = 0;
    while (g == 1 && steps < S) {
        x = ((x * x) + a) % n;
        y = ((y * y) + a) % n;
        y = ((y * y) + a) % n;
        g = __gcd(abs(x - y), n);
        ++steps;
    }
    return g;
}

vector<pll> factor(ll a) {
    vector<int> p;
    for (int i = 2; i * i < SQ;) {
        if (a % i == 0) {
            p.em_back(i);
            a /= i;
        } else {
            ++i;
        }
    }

    if (a > 1) {
        queue<ll> q;
        q.push(a);

        while (size(q)) {
            ll u = q.front();
            q.pop();

            bool prime = false;
            for (int i = 0; i < P; ++i) {
                ll x = pollardRho(u);
                if (x > 1 && x < u) {
                    q.push(x);
                    q.push(u / x);
                    prime = false;
                    break;
                }
            }

            if (prime) {
                p.em_back(u);
            }
        }
    }

    sort(all(p));
    vector<pll> res;

    for (int i = 0; i < size(p);) {
        int j = i;
        while (j < size(p) && p[i] == p[j]) {
            ++j;
        }
        if ((j - i) % 3 != 0) {
            res.em_back(p[i], (j - i) % 3);
        }
        i = j;
    }
    return res;
}

void solve() {
    cin >> m;
    for (int i = 0; i < m; ++i) {
        ll a;
        cin >> a;
        if (isCube(a)) {
            ++cube;
        } else {
            cnt[factor(a)]++;
        }
    }

    int res = 0;
    for (auto u : cnt) {
        if (used[u.first]) {
            continue;
        }

        vector<pll> pinv = u.first;
        for (pll& p : pinv) {
            p.second = 3 - p.second;
        }

        int cntInv = cnt.count(pinv);
        int add = max(u.second, cntInv);
        res += add;

        used[u.first] = used[pinv] = 1;
    }

    cout << res + (cube > 0) << "\n";
}

