  rep(i, 2, 100001){
    bool flag = true;
    for(ll j=2;j*j<=i;j++) if(i%j==0) flag = false;
    if(flag) table.push_back(i);
  }

  ll ans = 0;
  for(auto itr = m.begin();itr!=m.end();itr++){
    if((*itr).first==1) {
      ans++;
      continue;
    }
    if(z.find((*itr).first)!=z.end()) continue;
    ll now = (*itr).first, pat = 1;
    //-------------------------------------------------------------------
    for(int j=0;j<table.size()&&table[j]<=now;j++){
      int c = 0;
      while(now%table[j]==0) now/=table[j], c++;
      if(c!=0) pat *= (c==1?table[j]*table[j]:table[j]);
    }
    //-------------------------------------------------------------------
    if(m.find(pat)==m.end()) ans += (*itr).second;
    else{
      z.emplace((*itr).first, 0), z.emplace(pat, 0);
      ans += max((*itr).second, m.at(pat));
    }
  }
  std::cout << ans << '\n';
  return 0;
}

