typedef long long ll;
typedef pair <ll, ll> pii;

const ll MAX_N = 1e5 + 5;
ll n, ans;
ll Arr[MAX_N];
ll Brr[MAX_N];
ll rev[MAX_N];
ll lp[MAX_N];
ll pr[MAX_N];
ll ind;
bool OK;

unordered_map <ll, ll> cnt, mark;

void preProcess() {
	for (ll i = 2; i < MAX_N; i++) {
		if (lp[i] == 0) {
			lp[i] = i;
			pr[ind++] = i;
		}

		for (ll j = 0; j < ind && pr[j] <= lp[i] && i * pr[j] < MAX_N; j++)
			lp[i * pr[j]] = pr[j];
	}
}
pii calc (ll d) {
	ll res1 = 1, res2 = 1, tmp = 0;
	for (int i = 0; i < ind && pr[i] * pr[i] <= d; i++) {
		if (d % pr[i] == 0) {
			tmp = 0;
			int cnt = 0;
			while (d % pr[i] == 0) {
				cnt++;
				d /= pr[i];
			}

			cnt %= 3;
			if (cnt == 1) {
				res1 *= pr[i];
				res2 *= pr[i] * pr[i];
			}
			if (cnt == 2) {
				res1 *= pr[i] * pr[i];
				res2 *= pr[i];
			}
		}
		tmp++;
		if (tmp == 100)
			break;
	}

	if (d != 1) {
		res1 *= d;
		res2 *= d * d;
	}
	return {res1, res2};
}


int main() {
	preProcess();
	ios::sync_with_stdio(false), cin.tie(0);
	// cin >> n;
	n = 100000;
	for (ll i = 0; i < n; i++) {
		// cin >> Arr[i];
		Arr[i] = 1000000007;

		if ((ll)cbrt(Arr[i]) * (ll)cbrt(Arr[i]) * (ll)cbrt(Arr[i]) == Arr[i]) {
			i--;
			n--;
			OK = true;
		}
	}

	for (ll i = 0; i < n; i++) {
		pii p = calc(Arr[i]);

		Brr[i] = p.first;
		rev[i] = p.second;

		cnt[Brr[i]]++;
	}

	ans = n;
	for (int i = 0; i < n; i++)
		if (!mark[Brr[i]]) {
			mark[Brr[i]] = 1;
			mark[rev[i]] = 2;

			ans -= min(cnt[Brr[i]], cnt[rev[i]]);
		}

	cout << ans + OK << "\n";
	return 0;
}

