#define MAX(a , b) ((a < b) ? b : a)
int const nmax = 100000;
long long const inf = 10000000000;
map<long long ,int > h;
map<long long , long long > mir;
long long v[5 + 2 * nmax] ,vp = 0;
bool prim(int n){
  for(int i = 2 ; i * i <= n ;i++){
    if(n % i == 0){
      return 0;
    }
  }
  return 1;
}
long long primes[5 + nmax];
long long cubes[5 + nmax];
int sqr[5 + nmax];
int pp = 0;

int main()
{
  int n;
  cin>>n;
  long long a;
  int p = 1;
  while(1LL * p * p * p <= inf){
    p++;
  }
  p--;
  for(int i = 2 ; i <= p ;i++){
    if(prim(i) == 1){
      pp++;
      primes[pp] = i;
      cubes[pp] = 1LL * i * i * i;
      sqr[pp] = i * i;
    }
  }
  for(int i = 1; i <= n ;i++){
    cin>>a;
    long long mirror = 1 ,s = 1;
    for(int i = 1; i <= pp ;i++){
      int val = primes[i];
      while(a % cubes[i] == 0){
        a /= cubes[i];
      }
      if(a % sqr[i] == 0){
        mirror *= val;
        s *= sqr[i];
        a /= sqr[i];

      } else if(a % val == 0){
        mirror *= sqr[i];
        s *= val;
        a /= val;
      }
    }
    if(1 < a){
      long long a2 = sqrt(a);
      if(a2 * a2 == a){
        s *= a;
        mirror *= a2;
      } else{
        s *= a;
        mirror *= a * a;
      }
    }
    mir[s] = mirror;
    mir[mirror] = s;
    if(h[s] == 0)
      v[++vp] = s;
    h[s]++;
  }
  sort(v + 1 , v + vp + 1);
  long long sum = 0;
  for(int i = 1 ; i <= vp;i++){
    long long a = v[i];
    if(a == 1){
      if(i == 1){
        sum++;
      }
    } else if(h[a] != 0 || h[mir[a]] != 0){
      sum += MAX(h[a] , h[mir[a]]);
      h[a] = 0;
      h[mir[a]] = 0;
    }
  }
  cout<<sum;
  return 0;
}

