  if(p==1||p==3){
    ans+=max(mp[x],mp[y]);
  }
  else if(p==2||p==4){
    if(mp[y]==0) ans+=mp[x];
  }
  else if(p==5) ans++; 

 }

  cout<<ans<<endl;

 return 0;

}

