    ForE(i, 1, n){
        cin >> a[i];
    }
    ForE(i, 1, n){
        bool ck = 0;
        ll x = 1, y = 1; // chia di, nhan len
        For(j, 2, K){ // for uoc < cube root
            int z = 0;
            while (a[i] % j == 0){
                z++;
                a[i] /= j;
            }
            z %= 3;
            if (!z) continue;
            if (z == 1){
                x *= (ll)j;
                y *= (ll)j; if (y > M){ ck = 1; break; }
                y *= (ll)j; if (y > M){ ck = 1; break; }
            }
            else{
                x *= (ll)j;
                x *= (ll)j;
                y *= (ll)j; if (y > M){ ck = 1; break; }
            }
