VP fctr(long s) {
    VP v;
    while (s != 1) {
        long p = getminp(s);
        long cnt = 0;
        while (s % p == 0) {
            s /= p;
            cnt++;
        }
        if (cnt % 3) {
            v.push_back(P(p, cnt % 3));
        }
    }
    return v;
}

