void hoge(VP f) {
    if (m[f] == 0) return;
    VP v;
    for (P a: f) {
        v.push_back(P(a.first, (3 - a.second) % 3));
    }
    cnt += max(m[f], m[v]);
    m[f] = 0;
    m[v] = 0;
}

