ll counter(ll a){
    map<ll,ll> t;
    int j=0;
    while(j<prime.size()){
        if(a<prime[j])break;
        while(a%prime[j]==0){
            if(t.find(prime[j])==t.end())t[prime[j]]=1;
            else t[prime[j]]++;
            a/=prime[j];
        }
        j++;
    }
    ll ans=1;
    for(auto itr=t.begin();itr!=t.end();itr++){
        if(itr->second==1)ans*=(itr->first*itr->first);
        if(itr->second==2)ans*=itr->first;
    }
    return ans;
}

