    create();

    int N; cin>>N;
    vector<ll> s(N);
    REP(i,N)cin>>s[i];


    vector<ll> norm=s;
    REP(i,N){
        int j=0;
        while(j<prime.size()){
            ll div=prime[j]*prime[j]*prime[j];
            if(norm[i]<div)goto nextf;
            while(norm[i]%div==0)norm[i]/=div;
            j++;
        }
    nextf:;
    }

    /*REP(i,norm.size())cout<<norm[i]<<" ";
    cout<<endl;
    */

    map<ll,ll> cnt;
    REP(i,norm.size()){
        if(cnt.find(norm[i])==cnt.end())cnt[norm[i]]=1;
        else cnt[norm[i]]++;
    }

    ll ans=0;
    for(auto itr=cnt.begin();itr!=cnt.end();itr++){
        if(itr->first==1){
            ans++;
            itr->second=0;
        }else{
            ll part=counter(itr->first);
            if(cnt.find(part)!=cnt.end()){
                ans+=max(itr->second,cnt[part]);
