    for (LL p: primes) {
        if (x%p)    continue;
        if (p*p*p > x)  break;
        LL cnt = 0;
        while (x%p==0) x/=p, cnt++;

        if (cnt%3==1) {
            a *= p;
            if (b > LIM/(p*p))  b = LIM;
            else                b *= p*p;
        }
        if (cnt%3==2) {
            a *= p*p;
            if (b > LIM/p)  b = LIM;
            else            b *= p;
        }
    }

    if (x == 1)     return {a, b};

    LL rt = round(sqrt(x));
    if (rt*rt == x) {
        a *= rt*rt;
        if (b > LIM/rt)  b = LIM;
        else            b *= rt;
    }
    else {
        a *= x;
        if (b > (LIM/x)/x)  b = LIM;
        else                b*=x*x;
    }
    return {a, b};
}

