void sieve() {
	np[0] = np[1] = 1;
	for (int i = 2; i < N; ++i) if (!np[i]) {
		for (int j = i + i; j < N; ++j) np[j] = 1;
		prime.push_back(i);
	}
}

bool mul(long long &x, long long y) {
	if (x > inf / y) return false;
	x *= y;
	return true;
}

int main() {
