using namespace std;
using P = pair<long, long>;
using VI = vector<long>;

VI primes = {2};
VI primesl;
unordered_map<long, long> isp;
unordered_map<long, long> isps;

void addp() {
    for (long i = 3; i * i * i <= 1e10; i+=2) {
        bool fl = true;
        for (long p: primes) {
            if (i % p == 0) fl = false;
        }
        if (fl) primes.push_back(i);
    }
}

void addpl() {
    primesl = VI(primes);
    for (long i = primes.back(); i * i <= 1e10; i+=2) {
        bool fl = true;
        for (long p: primesl) {
            if (i % p == 0) fl = false;
        }
        if (fl) primesl.push_back(i);
    }

    for (long p: primesl) {
        isp[p] = true;
        isps[p * p] = true;
    }
}

long red(long s) {
    for (long p: primes) {
        while (s % (p * p * p) == 0) {
            s /= p * p * p;
        }
    }
    return s;
}

long oppb(long s) {
    for (long p: primes) {
        while (s % p == 0) {
            s /= p;
        }
    }
    return s;
}

long oppbr(long s) {
    long ans = 1;
    for (long p: primes) {
        if (s % (p * p) == 0) {
            ans *= p;
        } else if (s % p == 0) {
            ans *= p * p;
        }
        if (ans > 1e10) return -1;
    }
    return ans;
}

long opp(long s) {
    long p = oppb(s);
    long b = s / p;
    long br = oppbr(b);
    if (br == -1) return -1;

    if (p == 1) return br;
    if (isp[p]) {
        if (double(br) * p * p > 1e10) return -1;
        return br * p * p;
    }
    if (isps[p]) {
        if (double(br) * sqrt(p) > 1e10) return -1;
        return br * long(sqrt(p));
    }
    return -1;
}

unordered_map<long, long> m;

int main() {
    addp();
    addpl();
    bool hasOne = false;
    int n;
    cin >> n;
    REP(i,n) {
        long a;
        cin >> a;
        a = red(a);
        if (a == 1) hasOne = true;
        else m[a]++;
    }

    long ans = 0;
    for (auto i = m.begin(); i != m.end(); i++) {
        long rcnt = i->second;
        long op = opp(i->first);
        if (op == -1) {
            ans += i->second;
            i->second = 0;
        }
        else {
            ans += max(i->second, m[op]);
            i->second = 0;
            m[op] = 0;
        }
    }
    cout << ans + hasOne << endl;
}

