void prework()
{
    ll limit = 2560;
    for (ll i = 2; i <= limit; i++)
    {
        if (!vis[i])
            prime[++tot] = i;
        for (ll j = 1; j <= tot; j++)
        {
            ll t = prime[j] * i;
            if (t > limit)
                break;
            vis[t] = 1;
            if (i % prime[j] == 0)
                break;
        }
    }
}

bool check(ll x)
{
    ll y = sqrt(x);
    if (y * y == x)
        return true;
    return false;
}

int main()
{
    prework();
    scanf("%lld",&n);
    for (ll i = 1; i <= n; i++)
        scanf("%lld",&a[i]);
    for (ll i = 1; i <= n; i++)
    {
        ll x = a[i];
        c1[i] = c2[i] = 1;
        for (ll j = 1; j <= tot && prime[j] * prime[j] <= x; j++)
            if (x % prime[j] == 0)
            {
                ll num = 0;
                while (x % prime[j] == 0)
                {
                    num++;
                    x /= prime[j];
                }
                if (num % 3 == 1)
                {
                    c1[i] *= prime[j];
                    c2[i] *= prime[j] * prime[j];
                }
                else if (num % 3 == 2)
                {
                    c1[i] *= prime[j] * prime[j];
                    c2[i] *= prime[j];
                }
            }
        if (x != 1)
        {
            if (check(x))
            {
                c1[i] *= x;
                c2[i] *= sqrt(x);
            }
            else
            {
                c1[i] *= x;
                c2[i] *= x * x;
            }
        }
        if (c1[i] == 1 && c2[i] == 1)
            flag = true;
    }
    for (ll i = 1; i <= n; i++)
    {
        if (!M.count(c1[i]))
        {
            M[c1[i]] = i;
            M[c2[i]] = i + n;
            sizee[i]++;
        }
        else
            sizee[M[c1[i]]]++;
    }
    for (ll i = 1; i <= n; i++)
        if (i == M[c1[i]])
            ans += max(sizee[i],sizee[i + n]);
    if (flag)
        ans++;
    printf("%lld\n",ans);

    return 0;
}

