        --y;
    if (y * y != x)
        return -1;
    return y;
}

void add(ll x) {
    ll y = 1, z = 1;
    for (ll i = 2; i * i * i <= x; ++i) {
        if (x % i)
            continue;
        int deg = 0;
        while (x % i == 0)
            x /= i, ++deg;
        deg %= 3;
        if (deg == 0)
            continue;
        forn (j, deg)
            y *= i;
        forn (j, 3 - deg)
            z *= i;
    }
    ll rt = root(x);
    if (rt == -1) {
        y *= x;
        if (ld(x) * ld(x) * z > 1e12)
            z = infl;
        else
            z *= x * x;
    } else {
        y *= x;
        z *= rt;
    }
    bad[y] = z;
    cnt[y]++;
}

