map<LL,bool> vis;

LL calc(LL x){
	LL ret=1;
	for (LL i=2;i*i*i<=x;++i){
		LL k=0; for (;x%i==0;x/=i,++k); k%=3;
		ret=ret*(k>0?i:1)*(k>1?i:1);
	}
	ret=ret*x;
	return ret;
}

LL icalc(LL x){
	LL ret=1;
	for (LL i=2;i*i*i<=x;++i){
		LL k=0; for (;x%i==0;x/=i,++k); k%=3;
		ret=ret*(k>0?i:1)*(k==1?i:1);
	}
	LL t=sqrt(x);
	if (t*t<x) ++t; if (t*t>x) --t;
	if (t*t==x) ret=ret*t; else ret=ret*x*x;
	return ret;
}

int main(){
	scanf("%lld",&n);
	for (LL i=1;i<=n;++i){
		scanf("%lld",a+i);
		LL t=calc(a[i]);
