	}
	for (LL i=1;i<=n;++i){
		LL t=calc(a[i]);
		if (t==1||vis[t]) continue;
		LL tt=icalc(a[i]);
		vis[t]=vis[tt]=1;
		ans+=max(f[t],f[tt]);
	}
	printf("%lld\n",ans);

	return 0;
}

