        for (int j : p) {
            LL cube = (LL)j * j * j;
            while (s[i] % cube == 0) {
                s[i] /= cube;
                rem /= cube;
            }
            int cnt = 0;
            while (s[i] % j == 0) {
                s[i] /= j;
                ++cnt;
            }
            if (cnt == 1) {
                if (inv > INF / j) inv = INF;
                else inv *= j;
                if (inv > INF / j) inv = INF;
                else inv *= j;
            } else if (cnt == 2) {
                if (inv > INF / j) inv = INF;
                else inv *= j;
            }
        }
        if (s[i] > 1) {
            int lo = 2, hi = 100000, mid;
            while (lo < hi) {
                mid = (lo + hi) >> 1;
                if ((LL)mid * mid < s[i]) {
                    lo = mid + 1;
                } else {
                    hi = mid;
                }
            }
            if ((LL)lo * lo == s[i]) {
                if (inv > INF / lo) inv = INF;
                else inv *= lo;
            } else {
                if (inv > INF / s[i]) inv = INF;
                else inv *= s[i];
                if (inv > INF / s[i]) inv = INF;
                else inv *= s[i];
            }
        }
        if (inv <= 10000000000ll) {
            all.pb(mp(rem, inv));
        }
    }
    for (auto x : all) {
        ++ma[x.first];
        pp[x.first] = x.second;
    }
    int bad = 0;
    for (auto x : ma) {
        if (x.first == 1) {
            bad += 2 * (x.second - 1);
        } else {
            auto it = ma.find(pp[x.first]);
            if (it != ma.end()) {
                bad += min(x.second, it->second);
            }
        }
    }
    assert(bad % 2 == 0);
    bad /= 2;
    ans -= bad;
