using namespace std;
typedef long long ll;
#define MAX_X 10000000000LL
vector<ll> prime;
vector<ll> v;
int N;
int ans, ans2;

map<ll, int> mp;

void generate_prime(){
	prime.push_back(2);
	for(ll p = 3; p * p <= MAX_X; p+=2){
		bool tf = true;
		for(int j=0; j<prime.size(); j++){
			if(p%prime[j]==0){
				tf = false; break;
			}
			if(prime[j] * prime[j] > p)	break;
		}
		if(tf) prime.push_back(p);
	}
	//cout<<prime.size();
}

int main(){
	generate_prime();
	scanf("%d", &N);
	ll x; 
	for(int i=0; i<N; i++){
		scanf("%lld", &x); 
		ll y = 1;
		int cnt;
		for(int j=0; j<prime.size(); j++){
			if(prime[j] * prime[j] > x)	break;
			if(x%prime[j]!=0)	continue;
			cnt = 0;
			while(x%prime[j]==0){
				cnt++; x/=prime[j];
			}
			cnt=cnt%3;
			for(int k=0; k<cnt; k++){
				y *= prime[j];
			}
		}
		if(x!=1){
			//cout<<x<<' '<<prime.back()<<endl;
			if(x<=prime.back()){
				y *= x;
				//cout<<y<<endl;
			}else{
				ans++;
				continue;
			}
		}
		if(y==1){
			if(mp[1]==0){
				mp[1]++;
				ans++;
			}
			continue;
		}
		if(mp[y]==0)	v.push_back(y);
		mp[y]++;
	}
	for(int i=0; i<v.size(); i++){
		ll now = v[i];
		int cnt;
		ll y = 1;
		for(int j=0; j<prime.size(); j++){
			if(prime[j] * prime[j] > now)	break;
			if(now%prime[j]!=0)	continue;
			cnt = 0;
			while(now%prime[j]==0){
				cnt++; now/=prime[j];
			}
			for(int k=0; k<(3-cnt); k++){
				y*=prime[j];
			}
		}
		if(now!=1){
			y*=now*now;
		}
		//cout<<v[i]<<" "<<y<<endl;
		if(mp[y]==0){
			ans+=mp[v[i]];
		}
		else	ans2 += max(mp[v[i]], mp[y]);
	}
	ans = ans + ans2/2;
	printf("%d", ans);
	return 0;
}

