    init(100000);
    scanf("%d",&n);
    rep(i,1,n+1) {
        scanf("%lld",&a[i]);
        if (!U.count(a[i])) bat(a[i]);
        if (U[a[i]]>0) num[U[a[i]]]++;
    }
    for (auto x:num)
        if (x.fi==1) ans+=2; else
        if (num.count(D[x.fi])) ans+=max(x.se,num[D[x.fi]]); else 
            ans+=2*x.se;
