bool millerRabin(ull num) {
  static const ull witnesses[] = { 2, 325, 9375, 28178, 450775, 9780504, 1795265022 };
  if (num <= 1)
    return false;
  if (num <= 3)
    return true;
  if ((num & 1) == 0)
    return false;
  ull d = num - 1;
  int s = 0;
  for (; ~d & 1; s++)
    d >>= 1;
  for (int i = 0; i < 7; i++) {
    if (witnesses[i] > num - 2)
      break;
    ull x = power(witnesses[i], d, num);
    if (x == 1 || x == num - 1)
      continue;
    bool flag = false;
    for (int j = 0; j < s; j++) {
      x = power(x, 2, num);
      if (x == 1)
        return false;
      if (x == num - 1) {
        flag = true;
        break;
      }
    }
    if (!flag)
      return false;
  }
  return true;
}
