            m=p;
            x/=1LL*p*p;
        }
        else if(x%p==0){
            m=1LL*p*p;
            x/=p;
        }
        if(m>=inf/res) return -1;
        res=res*m;
    }
    if(x>1) return -1;
    return res;
}

