LL Sqrt(LL x)
{
	LL l=1,r=x,mid;
	while (l<r)
	{
		if (r-l>1) 	mid=(l+r)>>1;
		else mid=r;
		if (mid*mid>x) r=mid-1;
		else l=mid;
	}
	return l;
}
