int main()
{
	cin >> n;
	for (int i = 0; i < n; i++)
		cin >> s[i];

	isc[0] = isc[1] = true;
	for (int i = 2; i < N; i++)
	{
		if (isc[i]) continue;
		ps.push_back(i);
		for (int j = i+i; j < N; j += i) isc[j] = true;
	}

	for (int i = 0; i < n; i++)
	{
		ll x = s[i];
		ll b = 1;
		ll o = 1;
		for (ll p: ps)
		{
			if (p > x) break;
			ll p3 = p*p*p;
			while (x % p3 == 0) x /= p3;
			if (x % (p*p) == 0) x /= p*p, b *= p*p, o *= p;
			else if (x % p == 0) x /= p, b *= p, o *= p*p;
		}
		//cout << s[i] << ' ' << x << ' ' << b << ' ' << o << '\n';
		if (x != 1)
		{
			b = s[i];
			o = 0;
		}
		grp[b]++;
		if (b == 1 && grp[b] == 1) ans++;
		if (grp[b] > grp[o]) ans++;
	}
	cout << ans << '\n';
	return 0;
