const int MAXN = 1e5 + 239;
const ll INF = 1e10 + 239;

int prime[MAXN];
vector<int> primes;

void init() {
    fill(prime, prime + MAXN, 1);
    for (int i = 2; i < MAXN; i++) {
        if (prime[i]) {
            for (int j = 2 * i; j < MAXN; j += i) {
                prime[j] = 0;
            }
            primes.push_back(i);
        }
    }
}

ll no_cubic(ll x) {
    for (ll i = 2; i * i * i <= x; i++) {
        while (x % (i * i * i) == 0) {
            x /= (i * i * i);
        }
    }
    return x;
}

ll get_pair(ll x) {
    ll sq = 1;
    for (auto t : primes) {
        if (x % (ll)(t * t) == 0) {
            sq *= t;
        }
        if (x < (t * t)) {
            break;
        }
    }
    ll sl = x / (sq * sq);
    ll ans = sq * sl;
    if (ans > INF / sl) {
        return -1;
    } else {
        return ans * sl;
    }
}

signed main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);

    init();

    int n;
    cin >> n;
    map<ll, int> cnt;
    for (int i = 0; i < n; i++) {
        int x;
        cin >> x;
        x = no_cubic(x);
        cnt[x]++;
    }
    auto get_cnt = [&](ll x) {
        if (cnt.count(x)) {
            return cnt[x];
        } else {
            return (int)0;
        }
    };
    int ans = 0;
    if (cnt.count(1)) {
        ans++;
        cnt.erase(1);
    }
    set<pair<int, int>> seen;
    for (auto uu : cnt) {
        ll f, no_need;
        tie(f, no_need) = uu;
        ll pr = get_pair(f);
        if (pr == -1) {
            ans += cnt[f];
            continue;
        }
        ll a = pr;
        ll b = f;
        if (a > b) {
            swap(a, b);
        }
        if (!seen.count({a, b})) {
            ans += max(get_cnt(a), get_cnt(b));
            seen.insert({a, b});
        }
    } 
    cout << ans << endl;
}

