  map<ll,ll> dp;
  rep(i,n) {
    ll x = a[i];
    ll d = 1, e = 1;
    for (int p : ps) {
      int cnt = 0;
      while (x%p == 0) ++cnt, x /= p;
      cnt %= 3;
