            if(x % (p[i] * p[i]) == 0){
                x /= (p[i] * p[i]);
                v.push_back(p[i] * p[i]);
            }
            else if(x % p[i] == 0){
                x /= p[i];
                v.push_back(p[i]);
            }
        }
        if(x >= N){ r++; continue; }
        if(x > 1) v.push_back(x);
