				if (bag >= 100000)break;
				if (prime[bag]) {
					box.push_back(bag);
					bag = 1;
				}
				break;
			}
			if (bag == 1)break;
		}
		if (bag > 1) {
			ans += i.second;
			continue;
		}
		long long int num = 1;
		for (auto j : box) {
			num *= j;
			if (num > 10000000000)break;
			if (i.first % (j*j)) {
				num *= j;
				if (num > 10000000000)break;
			}
		}
		if (m.find(num) == m.end()) {
			ans += i.second;
			continue;
		}
		if (num < i.first)continue;
		ans += max(i.second, m[num]);
	}
	if (flag)ans++;
	cout << ans << endl;
	return 0;
}

