inline ll mul(ll x,ll y,ll MOD) {
  x%=MOD;y%=MOD;
  ll ans=0;
  while (y) {
    if (y&1) ans=(ans+x)%MOD;
    x=(x+x)%MOD;
    y>>=1;
  }
  return ans;
}

ll gcd(ll x,ll y) {
  return (x%y==0)?y:gcd(y,x%y);
}

ll pow_mod(ll x,ll k,ll MOD) {
  ll ans=1;
  while (k) {
    if (k&1) ans=mul(ans,x,MOD);
    x=mul(x,x,MOD);
    k>>=1;
  }
  return ans;
}

bool is_prime(int c,ll n) {
  ll d=n-1;
  while (!(d&1)) d>>=1;
  ll t=pow_mod(c,d,n);
  while (d!=n-1&&t!=n-1&&t!=1) {
    t=mul(t,t,n);
    d<<=1;
  }
  return (t==n-1)||(d&1);
}

