ll Norm[max_N],Pair[max_N];

int N_tot,P_tot,N_siz[max_N],P_siz[max_N];

inline void jzp(int n){
	for(int x=2;x<=n;++x){
		if(!vis[x])pri.push_back(x);
		for(auto&y:pri){
			if((ll)x*y>n)break;
			vis[x*y]=1;
			if(!(x%y))break;
		}
	}
}

inline ll get_norm(ll x){
	for(auto&y:pri){
		ll z=1ll*y*y*y;
		if(z>x)break;
		while(!(x%z))x/=z;
	}
	return x;
}

inline ll get_pair(ll x){
	ll res=1;
	for(auto&y:pri){
		ll z=(ll)y*y*y;
		if(z<=x){
			while(!(x%z))x/=z;
			if(!(x%(y*y))){
				res*=y,x/=(y*y);
				if(res>=inf)
					return inf;
			}
			else if(!(x%y)){
				res*=(y*y),x/=y;
				if(res>=inf)
					return inf;
			}
		}
		else{
			ll w=(ll)y*y;
			if(w>x){
				if(1.*res*x*x>=inf)
					return inf;
				return res*=x*x;
			}
			else if(!(x%y)){
				if(x==w){
					res*=y;
					return res>=inf?inf:res;

				}
				else{
					if(1.*res*x*x>=inf)
						return inf;
					res*=x*x;
					return res;
				}
			}
		}
	}
	if(1.*res*x*x>=inf)
		return inf;
	res*=x*x;
	return res;
}

int main(){
	jzp(1e5);
	scanf("%d",&n);
	for(int i=1;i<=n;++i){
		ll s; scanf("%lld",&s);
		Norm[i]=get_norm(s);
		Pair[i]=get_pair(s);
	}
	std::sort(Norm+1,Norm+1+n);
	std::sort(Pair+1,Pair+1+n);
	for(int i=1;i<=n;++i){
		if(Norm[i]!=Norm[i-1])Norm[++N_tot]=Norm[i];
		++N_siz[N_tot];
		if(Pair[i]!=Pair[i-1])Pair[++P_tot]=Pair[i];
		++P_siz[P_tot];
	}
