#include <bits/stdc++.h>
using namespace std;
vector <int> prime;
bitset <100010> flag;

void sieve () {
    const int maxn = 1e5;
    for(int i = 3; i * i <= maxn; i += 2) {
        if(flag[i] == 1) continue;
        for(int j = i * i; j <= maxn; j += (i << 1)) {
            flag[j] = 1;
        }
    }
    prime.push_back(2);
    for(int i = 3; i <= maxn; i += 2) {
        if(flag[i] == 0) {
            prime.push_back(i);
        }
    }
}

typedef long long Long;

pair <Long, Long> factor (Long n) {
    Long a = 1;
    Long b = 1;
    for(auto i : prime) {
        Long p = i;
        if(p * p > n) break;
        int cnt = 0;
        while(n % p == 0) {
            n /= p;
            ++cnt;
        }
        cnt %= 3;

        Long x, y;
        if(cnt == 0) {
            x = 1;
            y = 1;
        } else if (cnt == 1) {
            x = p;
            y = p * p;
        } else {
            x = p * p;
            y = p;
        }
        a *= x;
        b *= y;
    }
    if(n > 1) {
        a *= n;
        b *= n * n;
    }
    return make_pair(a, b);
}
int main() {
    sieve();

    int n;
    scanf("%d", &n);
    map <Long, int> cnt;
    map <Long, Long> func;

    bool baddy = false;
    for(int i = 1; i <= n; i++) {
        Long x;
        scanf("%lld", &x);
        auto h = factor(x);
        x = h.first;
        Long y = h.second;
        if(y == 1) {
            baddy = true;
            continue;
        }
        cnt[x] += 1;
        cnt[y];
        func[x] = y;
        func[y] = x;
    }
    int ans = 0;
    for(auto i : cnt) {
        Long x = i.first;
        Long y = func[x];
        ans += max(cnt[x], cnt[y]);
    }
    ans >>= 1LL;
    ans += 1;
    printf("%d\n", ans);
    return 0;
}

