bool naive_is_prime(ll x) {
	foreach(y, primes) {
		if (y * y > x)
			break;
		if (x == y)
			return true;
		if (x % y == 0)
			return false;
	}
	return true;
}

void naive_factor(Num& n) {
	foreach(y, primes) {
		if (n.first % y == 0)
			factor(n, y);
		if (n.first == 1)
			break;
	}
	if (n.first != 1)
		factor(n, n.first);
}

void cube_factor(Num& n) {
	foreach(y, primes) {
		if (n.first % y == 0) {
			factor(n, y);
		}
		if (n.first == 1 || y * y * y > LIM)
			break;
	}
	if (n.first != 1)
		factor(n, n.first);
}

