void norm() {
	vector<int> primes;
	for (int i = 1; i <= 3335; ++i) {
		if (prime(i)) {
			primes.push_back(i);
		}
	}
	for (int i = 1; i <= n; ++i) {
		ag[i] = lol[i] = 1;
		for (int x : primes) {
			if (x * x * x > a[i]) break;
			while (a[i] % (x * x * x) == 0) a[i] /= (x * x * x);
			int _A = a[i];
			int deg = 0;
			while (_A % x == 0) _A /= x, ++deg;
			deg = (3 - deg) % 3;
			if (deg == 1) ag[i] *= x, lol[i] *= (x * x);
			else if (deg == 2) ag[i] *= (x * x), lol[i] *= x;
			if (ag[i] > INF) ag[i] = INF + 228 - 1;
		}
	}
	map< pair<int, int>, int > cnt, cnt1;
	map< pair<int, int>, bool> ban;
