LL mult_mod(LL  a,LL   b,LL   c)  
{  
    a %= c;  
    b %= c;  
    LL ret = 0;  
    LL tmp = a;  
    while(b)  
    {  
        if(b & 1)  
        {  
        ret += tmp;  
        if(ret > c)ret -= c;  
        }  
        tmp <<= 1;  
        if(tmp > c)tmp -= c;  
        b >>= 1;  
    }  
    return ret;  
}  
LL  pow_mod(LL   a,LL   n,LL   mod)  
{  
    LL ret = 1;  
    LL temp = a%mod;  
    while(n)  
    {  
        if(n & 1)ret = mult_mod(ret,temp,mod);  
        temp = mult_mod(temp,temp,mod);  
        n >>= 1;  
    }  
    return ret;  
}  
bool check(LL a,LL n,LL x,LL t)  
{  
    LL ret = pow_mod(a,x,n);  
    LL last = ret;  
    for(int i = 1;i <= t;i++)  
    {  
    ret = mult_mod(ret,ret,n);  
    if(ret == 1 && last != 1 && last != n-1)return true;  
    last = ret;  
    }  
    if(ret != 1)return true;  
    else return false;  
}  
bool MiLLer_Rabin(LL n)  
{  
    if( n < 2)return false;  
    if( n == 2)return true;  
    if( (n&1) == 0)return false;  
    LL x = n - 1;  
    LL t = 0;  
    while( (x&1)==0 ){x >>= 1; t++;}  
    srand(time(NULL ));  
    for(int i = 0;i < S;i++)  
    {  
        LL a = rand()%(n-1) + 1;  
        if( check(a,n,x,t) )  
        return false;  
    }  
    return true;  
}  
LL calHash(LL num) {
	LL hash1 = 0, hash2 = 0;
	bool f = MiLLer_Rabin(num);
	for(LL x = 2; x * x <= num && f == 0; x ++) {
		if(num % x) continue;
		int c = 0;
		while(num % x == 0) num /= x, c ++;
		if(c % 3 == 0) continue;
		if(c % 3 == 1) hash1 = (hash1 * MOD1 + x * BASE1) % MOD1, hash2 = (hash2 * MOD2 + x * BASE1) % MOD2;
		if(c % 3 == 2) hash1 = (hash1 * MOD1 + x * BASE2) % MOD1, hash2 = (hash2 * MOD2 + x * BASE2) % MOD2;
		if(MiLLer_Rabin(num)) break;
	}
	if(num != 1) {
		hash1 = (hash1 * MOD1 + num * BASE1) % MOD1, hash2 = (hash2 * MOD2 + num * BASE1) % MOD2;
	}
	return (hash1 << 31) | hash2;
}

LL calvs(LL num) {
	LL hash1 = 0, hash2 = 0;
	bool f = MiLLer_Rabin(num);
	for(LL x = 2; x * x <= num && f == 0; x ++) {
		if(num % x) continue;
		int c = 0;
		while(num % x == 0) num /= x, c ++;
		if(c % 3 == 0) continue;
		if(c % 3 == 1) hash1 = (hash1 * MOD1 + x * BASE2) % MOD1, hash2 = (hash2 * MOD2 + x * BASE2) % MOD2;
		if(c % 3 == 2) hash1 = (hash1 * MOD1 + x * BASE1) % MOD1, hash2 = (hash2 * MOD2 + x * BASE1) % MOD2;
		if(MiLLer_Rabin(num)) break;
	}
	if(num != 1) hash1 = (hash1 * MOD1 + num * BASE2) % MOD1, hash2 = (hash2 * MOD2 + num * BASE2) % MOD2;
	return (hash1 << 31) | hash2;
}

