inline void Sieve(int N) {
	isprime[1] = isprime[0] = 1;
	for (int i = 2; i <= N; i++) {
		if (isprime[i] == 0) {
			prime[++tot] = i;
		}
		for (int j = 1; j <= tot && i * prime[j] <= N; j++) {
			isprime[i * prime[j]] = 1;
			if (i % prime[j] == 0) {
				break;
			}
		}
	}
}
unordered_map<int, int> q; 
int dl[maxn], now[maxn];
#define mp make_pair
pair<int, int> Fj(int x) {
	int tmp = x, asd = 1, dl = 1;
	for (int i = 1; i <= tot; i++) {
		if (tmp % prime[i] == 0) {
			int cnt = 0;
			while(tmp % prime[i] == 0) {
				cnt ++; tmp /= prime[i];
			}
			cnt = cnt % 3;
			for (int j = 1; j <= cnt; j++) asd *= prime[i];
			for (int j = 1; j <= (3 - cnt) % 3; j++) dl *= prime[i];
		}
	}
	//printf("%d %d %d %d\n", x, tmp, asd, dl);
	if (tmp == 1 || tmp == 0) return mp(asd, dl);
	int hhd = sqrt(tmp);
	if (hhd * hhd == tmp) return mp(asd * tmp, dl * hhd);
	return mp(asd * tmp, dl * tmp * tmp);
}
