typedef long long ll;

const int N = 2200;
const ll INF = 1e18;
const ll BRD = 1E10;

vector<ll> pr;

void delCubes(ll& v) {
  for (ll p : pr) {
    while (v % (p * p * p) == 0) {
      v /= (p * p * p);
    }
  }
}

ll mul(ll a, ll b) {
  ll c = a * b;
  if (c / a == b && c <= BRD) return c;
  else return INF;
}

ll getPair(ll v) {
  ll res = 1;
  for (ll p : pr) {
    if (v % (p * p) == 0) {
      res = mul(res, p);
      v /= (p * p);
    }
    else if (v % p == 0) {
      res = mul(res, p * p);
      v /= p;
    }
  }
  if (v != 1) {
    ll sq = sqrt(v);
    while (sq * sq < v) sq++;
    while (sq * sq > v) sq--;
    if (sq * sq == v) {
      res = mul(res, sq);
    }
    else {
      sq = mul(sq, sq);
      res = mul(res, sq);
    }
  }
  return res;
}

void solve() {
  int n; cin >> n;
  unordered_map<ll, int> mp;
  for (int i = 0; i < n; i++) {
    ll v; cin >> v;
    delCubes(v);
    mp[v]++;
  }
  ll ans = (mp[1] > 0); mp.erase(1);
  for (auto x : mp) {
    ll v = x.first, res = x.second;
    ll nv = getPair(v);
    if (mp.count(nv) == 0) {
      ans += res;
    }
    else if (res > mp[nv] || (res == mp[nv] && v < nv)) {
      ans += res;
    }
  }
  cout << ans;
}

