int N;
vector<long long> a;
vector<int> prs;

long long calc(long long n) {
    long long res = 1;
    for (auto p : prs) {
        int num = 0;
        while (n % p == 0) ++num, n /= p;
        if (num == 0) continue;
        else if (num == 1) res *= p * p;
        else res *= p;
    }

    long long left = 1, right = 1000000;
    while (right - left > 1) {
        long long mid = (left + right) / 2;
        if (mid * mid > n) right = mid;
        else left = mid;
    }
    if (left * left == n) {
        res *= left;
        return res;
    }
    else {
        if (left > 1000000) return -1;
        res *= left * left;
        if (res > 10000000000LL) return -1;
        return res;
    }
}

long long solve() {
    int res = 0;
    prs = Era();
    map<long long, int> ma;
    for (int i = 0; i < N; ++i) {
        long long tmp = 1;
        for (auto p : prs) {
            int num = 0;
            while (a[i] % p == 0) ++num, a[i] /= p;
            num %= 3;
            for (int j = 0; j < num; ++j) tmp *= p;
        }
        tmp *= a[i];

        if (tmp == 1) res = 1;
        else ma[tmp]++;
    }

    //COUT(ma);


    for (auto it = ma.begin(); it != ma.end(); ++it) {
        long long val = it->first;
        long long aite = calc(val);

        //cout << val << ": " << aite << "(" << it->second << ", " << ma[aite] << ")" << endl;

        int tmp = max(it->second, ma[aite]);
        it->second = ma[aite] = 0;
        res += tmp;
    }
    return res;
}

