void calc(int id) {
	for (int x : prm) {
		long long cub = 1ll * x * x * x;
		if (cub > a[id]) break;
		while (a[id] % cub == 0) a[id] /= cub;
	}
}

long long mul(long long x,long long y) {
	if (x > inf / y) return inf;
	return x * y;
}

long long needMul(long long x) {
	long long ret = 1;
	for (int v : prm) if (x % v == 0) {
		int cnt = 0;
		while (x % v == 0) cnt++, x /= v;
		for (int i = 1; i <= 3 - cnt; ++i) {
			ret = mul(ret, v);
		}
	}
	// if (issqr(x)) ret = mul(ret, (long long)(sqrt(x) + 0.5));
	ret = mul(ret, mul(x, x));
	return ret;
}

