			cnt = 0;
			while (temp % pr[j] == 0){
				cnt++;
				temp /= pr[j];
			}
			cnt %= 3;
			if (cnt == 1){
				num *= pr[j];
				prod *= pr[j] * pr[j];
			}
			else if (cnt == 2){
				num *= pr[j] * pr[j];
				prod *= pr[j];
			}
