int const MAX_N = 100010;
vector<ll> prime;
vector<bool> is_prime(MAX_N,true);
void Eratosthenes() {
    is_prime[0] = is_prime[1] = false;
    for (ll i = 2;i*i < MAX_N;++i) if (is_prime[i]) for (ll j = 2*i;j < MAX_N;j += i) is_prime[j] = false;
    for (ll i = 0;i < MAX_N;++i) if (is_prime[i]) prime.push_back(i);
}

vector<P> prime_factorization(ll a) {
    vector<P> prime_factor;
    if (is_prime[0]) Eratosthenes();
    for (ll& i : prime) {
        if (i*i > a) break;
        if (a%i == 0) {
            P p = P(i,0);
            while (a%i == 0) {
                a /= i;
                p.second++;
            }
            p.second %= 3;
            if (p.second) prime_factor.push_back(p);
        }
    }
    if (a != 1) prime_factor.push_back(P(a,1));
    return prime_factor;
}

int main() {
    Eratosthenes();
    int n;
    cin >> n;
    vector<P> s(n,P(1,1));
    unordered_map<ll,int> mp;
    for (int i = 0;i < n;++i) {
        ll a;
        cin >> a;
        for (ll& j : prime) {
            if (j*j > a) break;
            if (a%j == 0) {
                int cnt = 0;
                while (a%j == 0) {
                    a /= j;
                    cnt++;
                }
                cnt %= 3;
                if (cnt) {
                    for (int k = 0;k < cnt;++k) s[i].first *= j;
                    for (int k = 0;k < 3-cnt;++k) {
                        if ((ll)(1e11)/j < s[i].second) {
                            s[i].second = -1;
                            break;
                        }
                        s[i].second *= j;
                    }
                }
            }
        }
        if (a > 1) {
            for (int k = 0;k < 1;++k) s[i].first *= a;
            for (int k = 0;k < 2;++k) {
                if ((ll)(1e11)/a < s[i].second) {
                    s[i].second = -1;
                    break;
                }
                s[i].second *= a;
            }
        }
        mp[s[i].first]++;
        // mp[s[i].second]++;
        if (s[i].first > s[i].second) swap(s[i].first,s[i].second);
    }
    sort(s.begin(),s.end());
    s.erase(unique(s.begin(),s.end()),s.end());
    int ans = 0;
    for (P& p : s) {
        if (p.first == 1) ans += 1;
        else ans += max(mp[p.first],mp[p.second]);
    }
    cout << ans << endl;
}

