pair<LL,LL> get(LL a)
{
	LL r1 = 1;
	LL r2 = 1;

	FOR(i, 0, sz)
	{
		LL p = L[i];
		if (a == 1) break;
		if (a % p == 0)
		{
			int cnt = 0;
			while (a % p == 0)
			{
				cnt++;
				a /= p;
			}

			cnt %= 3;
			FOR(k, 0, cnt) r1 *= p;
			cnt = (3 - cnt + cnt * 3) % 3;
			FOR(k, 0, cnt)
			{
				if (r2 >= MAX1) continue;
				r2 *= p;
			}
		}
	}

	if (a != 1)
	{
		r1 *= a;
		if (r2 * (double)a * (double)a > 4 * MAX1)
		{
			r2 = MAX1;
		}
		else
		{
			r2 = r2 * a * a;
		}
	}

	return MP(r1, r2);
}

