const int S = 1e5 + 1; // S = sqrt(max)
bool is_prime[S];

bool check_prime(int n) {
    if (n < 2) return false;

    for (int d = 2; d * d <= n; d++)
        if (n % d == 0)
            return false;

    return true;
}

void calc_primes() {
    forsn(n, 2, S) 
        is_prime[n] = check_prime(n);
}

map<ll, int> sqrt;
void calc_squares() {
    forsn(n, 2, S) sqrt[(ll) n * n] = n;
}

ll cube(ll n) { return n * n * n; }

ll norm(ll n) {
    ll norm = 1;

    //cerr << "norm " << n << ' ';

    for (ll p = 0; cube(p) <= n; p++) if (is_prime[p]) {
        int e = 0;

        while (n % p == 0) n /= p, e++;
        e %= 3;

        while (e > 0) norm *= p, e--;
    }

    norm *= n;

    //cerr << norm << endl;

    return norm;
}

ll comp(ll n) {
    ll m = 1;

    for (ll p = 0; cube(p) <= n; p++) if (is_prime[p]) {
        int e = 0;

        while (n % p == 0) n /= p, e++;
        e %= 3;

        e = (3 - e) % 3;
        while (e > 0) m *= p, e--;
    }


    if (sqrt.count(n)){
        m *= (ll)sqrt[n];
    } 
    else {
        /*
        if (m * n *n  < 0) {
            cerr << "comp " << n << ' ';
            cerr <<"n: "<<n << " m: "<< m << " " ;
