#include <bits/stdc++.h>
#define int long long
#define fi first
#define se second
#define pb push_back
#define fastcin() ios_base::sync_with_stdio(0); cin.tie(0)
using namespace std;

typedef pair<int, int> ii;

const int maxn = 100500; 
map<int, int> M, comple; 

int n, ans; 
bool isp[maxn];

vector<int> pr; 

void sieve() {
	memset(isp, 1, sizeof isp); isp[1] = 0; 
	for(int i = 2; i <= 100000; i++) {
		if(isp[i]) {
			pr.pb(i);
			for(int j = i * i; j <= 100000; j += i) 
				isp[j] = 0;  
		}
	}
}

int get(int x) {
	vector<ii> ret; 
	for(auto p : pr) {
		if(p * p > x) break; 
		if(x % p == 0) {
			int cnt = 0; 
			while(x % p == 0) {
				x /= p; 
				cnt++; 
			}
			cnt %= 3; 
			if(!cnt) continue; 
			ret.pb({p, cnt}); 
		}
	}
	if(x > 1) 
		ret.pb({x, 1});
	int ans = 1; 
	for(auto t : ret) {
		for(int i = 1; i <= t.se; i++) 
			ans *= t.fi; 
	}
	if(!comple.count(ans)) {
		int comp = 1; 
		for(auto t : ret) {
			for(int i = 1; i <= 3 - t.se; i++) 
			 	comp *= t.fi; 
		}
		comple[ans] = comp; 
	}
	return ans; 
}

signed main()
{
	fastcin();
	cin >> n; 
	sieve(); 
	for(int i = 1, x; i <= n; i++) {
		cin >> x; 
		int mask = get(x); 
		if(mask == 1) ans = 1; 
		else M[mask]++; 
	}
	for(auto T : M) {
		int p = T.fi, q = comple[p]; 
		int x = T.se, y = M[q]; 
		if(x == -1 or y == -1) 
			continue; 
		ans += max(x, y); 
 		M[p] = -1; 
	}
	cout << ans; 
}

