#include <bits/stdc++.h>
using namespace std;

const int N = 1e5 + 10, M = 3e3;

typedef long long ll;

int pri[N], pcnt, n, realans;
bool mark[N];
map<ll, int> mp;
map<pair<ll, ll>, int> val;

void prework(void) {
  for(int i = 2; i < M; i++) {
    if(!mark[i]) {
      pri[++pcnt] = i;
    }
    for(int j = 1; j <= pcnt && i * pri[j] < M; j++) {
      mark[i * pri[j]] = true;
      if(i % pri[j] == 0) {
	break;
      }
    }
  }
}

void defact(ll x, int y) {
  ll ax = 1, ay = 1;
  for(int i = 1; i <= pcnt && pri[i] <= x; i++) {
    if(x % pri[i] == 0) {
      int cnt = 0;
      while(x % pri[i] == 0) {
	x /= pri[i];
	cnt++;
      }
      if(cnt % 3 == 1) {
	ax = ax * pri[i];
      } else if(cnt % 3 == 2) {
	ay = ay * pri[i];
      }
    }
  }
  ll lim = sqrt(x);
  if(lim * lim == x) {
    ay = ay * lim;
  } else {
    ax = ax * x;
  }
  val[{ax, ay}] += y;
  if(val.find({ay, ax}) == val.end()) {
    val[{ay, ax}] = 0;
  }
}

int main(void) {
  scanf("%d", &n);
  prework();
  for(int i = 1; i <= n; i++) {
    ll x;
    scanf("%lld", &x);
    mp[x]++;
  }
  for(auto it : mp) {
    defact(it.first, it.second);
  }
  for(auto it : val) {
    pair<ll, ll> p = it.first;
    if(p.first == p.second) {
      realans += !mark[1];
      mark[1] = true;
    }
    if(p.first > p.second) {
      realans += max(it.second, val[{p.second, p.first}]);
    }
  }
  cout << realans << endl;
  return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int MAXN = 100005;
const int MAXM = 100005;
typedef unsigned long long ull;
const ull bas = 19260817;

int prime[10000], top = 0;
int not_prime[MAXN];

void get_prime(int n)
{
	for (int i = 2; i <= n; i++) {
		if (!not_prime[i]) prime[++top] = i;
		for (int j = 1; j <= top && prime[j]*i <= n; j++) {
			not_prime[i*prime[j]] = 1;
			if (i%prime[j] == 0)
				break;
		}
	}
}

int n;
long long a[MAXN];
int powd[MAXN];
const int S = 1911589;

struct node {
	long long to;
	int next;
	int id;
} edge[MAXN*2];
int head[S], tot = 0;
inline void push(long long val, int id)
{
	int to = val%S;
	edge[++tot] = (node) {val, head[to], id}, head[to] = tot;
}
inline void visit(long long val, int i)
{
	int nd = val%S;
	for (register int i = head[nd]; i; i = edge[i].next) {
		long long to = edge[i].to;
		int id = edge[i].id;
		if (to == val)
			powd[id] = max(powd[id], i);
	}
}
map<pair<long long, long long>, int> stx, sty;

int main()
{
	get_prime(MAXM-1);
	ios::sync_with_stdio(false);
	cin >> n;
	for (int i = 1; i <= n; i++) {
		cin >> a[i];
		powd[i] = 1;
		for (int j = 1; j <= top; j++) {
			long long cur = (long long)prime[j]*prime[j]*prime[j];
			if (cur > a[i]) break;
			while (a[i]%cur == 0)
				a[i] /= cur;
		}
	}
	int B = 1300;
	for (register int i = 1; i <= B; i++)
		for (register int j = 1; j <= n; j++)
			if (a[j] % (i*i) == 0) 
				powd[j] = max(powd[j], i);
	for (register int i = B+1; i <= 100000; i++) {
		long long v = (long long)i*i;
		for (register long long j = v; j <= 10000000000; j += v)
			visit(j, i);
	}
	int cnt = 0;
	for (register int i = 1; i <= n; i++) {
		// cerr << powd[i] << " " << a[i] << endl;
		if (a[i] == 1) cnt = 1;
		else {
			auto v = make_pair(a[i]/powd[i]/powd[i], powd[i]);
			if (v.first < v.second) 
				stx[v]++;
			else {
				sty[v]++;
				if (!stx.count(make_pair(v.second, v.first)))
					stx[make_pair(v.second, v.first)] = 0;
			}
		}
	}
	for (register auto j : stx)
		cnt += max(j.second, sty[make_pair(j.first.second, j.first.first)]);
	cout << cnt << endl;
	return 0;
}

