void calc(ll x)
{
	ll s[2] = {1, 1};

	for (ll t : prm) {
		if (t * t * t > x) {
			break;
		}

		if (x % t == 0) {
			int c = 0;
			while (x % t == 0) {
				x /= t;
				++c;
			}
			c %= 3;

			if (c != 0) {
				s[c-1] *= t;
			}
		}
	}

	if (x != 1) {
		if (sq.count(x)) {
			s[1] *= rt[x];
		} else {
			s[0] *= x;
		}
	}

	if (s[0] == 1LL && s[1] == 1LL) {
		++cb;
	} else {
		mcnt[mp(s[0], s[1])]++;
	}
}

