    if(is_prime[i])
      for(int j=i*i;j<MAX_N;j++)
        is_prime[j] = false;

  for(int i=3;i<MAX_N;i+=2)
    if(is_prime[i])
      pr.push_back(i);

  int n; cin >> n;
  for(int i=0;i<n;i++) cin >> A[i];

  for(int i=0;i<n;i++)
