	if(x%j==0) return 0;
	return 1;
}
void init(){
	for(L i=2;i<=N;i++)
	if(isp(i)) pri[++use]=i;
}

L f(L x){
	for(L i=1;i<=use;i++){
		L iii=pri[i]*pri[i]*pri[i];
		while(x%iii==0) x/=iii;
	}
	return x;
}
L cnt=0,mi[M]={0},p[M]={0};

L g(L x){
	cnt=0;
	for(L i=1;i<=use;i++){
		while(x%pri[i]==0){
			if(p[cnt]==pri[i]) mi[cnt]++;
			else p[++cnt]=pri[i],mi[cnt]=1;
			x/=pri[i];
		}
	}
	L hh=sqrt(x);
	if(hh*hh==x){
		mi[++cnt]=2; p[cnt]=hh;
	}else mi[++cnt]=1,p[cnt]=x;
	L res=1;
	for(L i=1;i<=cnt;i++){
		if(mi[i]==1) res*=p[i]*p[i];
		if(mi[i]==2) res*=p[i];
	}
	return res;
}

