		for (ll j : primes[0])
		{
			tmp = j * j * j;
			while (s[i] % (tmp) == 0)
				s[i] /= tmp, dived[i] /= tmp;
			if (s[i] % (j * j) == 0)
			{
				dived[i] /= (j * j);
