	for (int i = 2; i <= 100000; i++) prime[i] = true;
	for (int i = 2; i <= 100000; i++) {
		if (prime[i]) {
			for (int j = i * 2; j <= 100000; j += i) {
				prime[j] = false;
			}
		}
	}
	for (int i = 2; i <= 100000; i++) {
		if (prime[i]) p[cur++] = i;
	}
