    p1[id] = p2[id] = 1;
    for (int i = 1; pri[i] * pri[i] * pri[i] <= x; i++) {
        int t = 0;
        while (x % pri[i] == 0) x /= pri[i], t++;
        t %= 3;
        for (int j = 0; j < t; j++) p1[id] *= pri[i];
        t = (3 - t) % 3;
        for (int j = 0; j < t; j++) p2[id] *= pri[i];
    }
    if (x) {
        LL t = sqrt(x);
        if (t * t == x)
            p1[id] *= x, p2[id] *= t;
        else
            p1[id] *= x, p2[id] *= x * x;
    }
}
map<LL, int> mp;
