inline ll Pow(int x, int cnt)
{
	ll res = 1;
	while(cnt--) res *= x;
	return res;
}

void work(ll x)
{
	ll res = 1, opp = 1;
	for(int i = 1; i <= tot; i++)
		if(x % pr[i] == 0)
		{
			int cnt = 0;
			while(x % pr[i] == 0)
				x /= pr[i], ++cnt;
			if(!(cnt %= 3)) continue;
			res *= Pow(pr[i], cnt);
			opp *= Pow(pr[i], 3 - cnt);
		}
	ll y = (ll) sqrt(x);
	if(y * y == x)
		res *= x, opp *= y;
	else res *= x, opp *= x * x;
	Sum[res]++, Opp[res] = opp, Opp[opp] = res;
}

