	init(2200);
	scanf("%d", &n);
	for(int i = 1; i <= n; i++)
	{
		scanf("%lld", &s[i]);
		work(s[i]);
	}
	int ans = 0;
	for(auto i : Sum)
	{
		if(i.first == 1) ans += 2;
		else ans += max(i.second, Sum[Opp[i.first]]);
	}
