	}

	for(spit i = S.begin(); i != S.end(); i++) {
		ll val1 = i->fst, val2 = i->snd;
		if(val1 == 1 && val2 == 1) {
			ans++;
			continue;
		}
		ll c1 = m.count(val1), c2 = m.count(val2);
		ans += max(c1, c2);
	}

	printf("%d\n", ans);
	return 0;
}

