typedef long long ll;

int prime[10055], cnt;
map<ll, int> squ, cntm;
map<ll, bool> cted;

bool b[100055], m3;
ll op[100050], yp[100050];

void Init(){
	for(int i = 2; i <= 100050; i++){
		if(!b[i]){
			prime[++cnt] = i;
			b[i] = 1;
			squ[i*i] = i;
		}
		for(int j = 1; j <= cnt && i * prime[j] <= 100050; j++){
			b[i * prime[j]] = 1;
			if(i%prime[j] == 0) break;
		}
	}
}

ll pow3(int x){return 1ll * x * x * x;}

int main(){
	int ans = 0, n;
	Init();
	scanf("%d", &n);
	for(int i = 1; i <= n; i++) {
		ll p;
		bool flag = 0;
		scanf("%lld", &p);
		yp[i] = op[i] = 1;
		for(int j = 1; pow3(prime[j]) <= p && j <= cnt; j++){
			int tot = 0;
			while(p%prime[j] == 0) p/=prime[j], tot++;
			tot%=3;
			if(tot == 1) yp[i] *= 1ll * prime[j], op[i] *= 1ll * prime[j] * prime[j], flag = 1;
			else if(tot == 2) yp[i] *= 1ll * prime[j] * prime[j], op[i] *= 1ll * prime[j], flag = 1;
		}

		if(p>1){
			if(squ[p]) yp[i] *= 1ll * p, op[i] *= 1ll * squ[p];
			else yp[i] *= 1ll * p, op[i] *= 1ll * p * p;
			flag = 1;
		}

		if(flag) cntm[yp[i]]++;
