	}
	for(int i = 1; i <= n; i++) if(yp[i]!=1 && !cted[op[i]] && !cted[yp[i]]){
		cted[op[i]] = cted[yp[i]] = 1;
		ans += max(cntm[yp[i]], cntm[op[i]]);
	}
	printf("%d", ans+m3);
}

