using namespace std;

typedef long long LL;

const int N = 1e5 + 10;
const LL lim = 1e10;

int n, m, p, q, ans;
bool flag, is_prime[N];
LL a[N], prime[N], prime2[N], prime3[N];
set<LL> ST;
map<LL, LL> MP, G;

void init(){
	LL s;
    for(LL i=1; ;i++){
		s = i * i * i;
		if(s > lim)	break;
		ST.insert(s);
    }
    for(LL i=1; ;i++){
		s = i * i;
		if(s > lim)	break;
		MP[s] = i;
    }

    memset(is_prime, 1, sizeof(is_prime));
    p = q = 0;

    for(int i=2; i<N; i++){
		if(is_prime[i]){
			prime[p] = i;
			prime2[p] = prime[p] * prime[p];
			s = prime2[p] * prime[p];
			p++;
			if(s <= lim){
				prime3[q++] = s;
			}
			for(int j=i<<1; j<N; j+=i){
				is_prime[j] = 0;
			}
		}
    }
}

void trans(LL x){
	if(ST.count(x)){
		flag = 1;
		return;
	}

    for(int i=0; i<q && prime3[i]<=x; i++){
        while(x % prime3[i] == 0){
			x /= prime3[i];
        }
    }

    LL y = 1, z = x;

    for(int i=0; prime[i]<3000 && prime2[i]<=x; i++){
		if(x % prime[i] == 0){
			if(x % prime2[i] == 0){
				y *= prime[i];
				x /= prime2[i];
			} else {
				x /= prime[i];
				y *= prime2[i];
			}
		}
    }

    if(x > 1){
		if(MP.count(x)){
			y *= MP[x];
			a[m++] = z;
			G[z] = y;
		} else if(x <= 100000){
			y = y * x * x;
			a[m++] = z;
			G[z] = y;
		} else {
			ans++;
		}
    } else {
    	a[m++] = z;
    	G[z] = y;
    }
}

int Cnt(LL x){
	int j = lower_bound(a, a+m, x) - a;
	int k = upper_bound(a, a+m, x) - a;
	return k - j;
}

int main(){
	init();
	LL x, y;
	int c, d;
    while(~scanf("%d", &n)){
		ans = m = 0;
		flag = 0;
		G.clear();
		for(int i=0; i<n; i++){
			scanf("%lld", &x);
			trans(x);
		}

		ans += flag;

		if(m){
			sort(a, a+m);

			y = G[a[0]];
			c = Cnt(a[0]);
			d = Cnt(y);
			ans += max(c, d);
			for(int i=1; i<m; i++){
				if(a[i]==a[i-1])	continue;
				y = G[a[i]];
				d = Cnt(y);
				if(y<a[i] && d)	continue;
                c = Cnt(a[i]);
                ans += max(c, d);
			}
		}

		printf("%d\n", ans);
    }
	return 0;
}

#include<bits/stdc++.h>

using namespace std;

const int N = 123456;

class divide_solver {
  long long mul(long long x, long long y, long long mod) {
    return ((x * y - (long long) (((long double) x * y + 0.5) / mod) * mod) % mod + mod) % mod;
  }

  long long qpow(long long x, long long y, long long mod) {
    long long result = 1;
    for (; y; y >>= 1, x = mul(x, x, mod)) {
      if (y & 1) {
        result = mul(result, x, mod);
      }
    }
    return result;
  }

  long long randll() {
    return ((long long) rand() << 30) | (rand() << 15) | rand();
  }

  bool miller_rabin(long long n) {
    if (n == 2) {
      return true;
    } else if (n < 2 || !(n & 1)) {
      return false;
    } else {
      long long m = n - 1;
      int t = 0;
      while (!(m & 1)) {
        m >>= 1;
        ++t;
      }
      for (int times = 0; times < 10; ++times) {
        long long a = randll() % (n - 1) + 1, x = qpow(a, m, n), y;
        for (int j = 0; j < t; ++j, x = y) {
          if ((y = mul(x, x, n)) == 1 && x != 1 && x != n - 1) {
            return false;
          }
        }
        if (x != 1) {
          return false;
        }
      }
    }
    return true;
  }

  long long pollard_rho(long long n) {
    long long k = 2, x = randll() % n, y = x, c = randll() % (n - 1), p = 1;
    for (long long i = 1; p == 1; ++i) {
      x = (mul(x, x, n) + c) % n;
      p = __gcd(abs(x - y), n);
      if (i == k) {
        k <<= 1;
        y = x;
      }
    }
    return p;
  }

  void divide(long long n, vector<long long>& pfactor) {
    if (n == 1) {
      return;
    } else if (miller_rabin(n)) {
      pfactor.push_back(n);
    } else {
      long long x = n;
      while (x == n) {
        x = pollard_rho(x);
      }
      divide(x, pfactor);
      divide(n / x, pfactor);
    }
  }

 public:
  vector<long long> solve(long long n) {
    vector<long long> result;
    divide(n, result);
    sort(result.begin(), result.end());
    return result;
  }
};

int n;
long long a[N], b[N];
map<long long, int> number;
map<long long, bool> used;

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);
  cout.tie(0);
  cin >> n;
  divide_solver solver;
  for (int i = 1; i <= n; ++i) {
    cin >> a[i];
    vector<long long> primes = solver.solve(a[i]);
    a[i] = b[i] = 1;
    for (int j = 0, k; j < primes.size(); j = k) {
      k = j;
      while (k < primes.size() && primes[j] == primes[k]) {
        ++k;
      }
      if ((k - j) % 3 == 1) {
        a[i] *= primes[j];
        b[i] *= primes[j] * primes[j];
      } else if ((k - j) % 3 == 2) {
        a[i] *= primes[j] * primes[j];
        b[i] *= primes[j];
      }
    }
    ++number[a[i]];
  }
  int answer = 0;
  for (int i = 1; i <= n; ++i) {
    if (!used[a[i]]) {
      used[a[i]] = used[b[i]] = true;
      if (a[i] == 1) {
        ++answer;
      } else {
        answer += max(number[a[i]], number[b[i]]);
      }
    }
  }
  cout << answer << '\n';
  return 0;
}

