bool prime(int v)
{
    for (int d = 2; d * d <= v; ++d)
    {
        if (v % d == 0)
            return 0;
    }

    return 1;
}


int square(int v)
{
    int l = 0, r = v;
    while (r - l > 1)
    {
        int m = l + r >> 1;
        if (m * m < v)
            l = m;
        else
            r = m;
    }

    return r * r == v;
}


int get_square(int v)
{
    int l = 0, r = v;
    while (r - l > 1)
    {
        int m = l + r >> 1;
        if (m * m < v)
            l = m;
        else
            r = m;
    }

    return r;
}


