int no_cubic(int x) {
    for (int i = 2; i * i * i <= x; i++) {
        while (x % (i * i * i) == 0) {
            x /= (i * i * i);
        }
    }
    return x;
}

int get_pair(int x) {
    int sq = 1;
    for (auto t : primes) {
        if (x % (t * t) == 0) {
            sq *= t;
        }
        if (x < (t * t)) {
            break;
        }
    }
    int sl = x / (sq * sq);
    int ans = sq * sl;
    if (ans > INF / sl) {
        return -1;
    } else {
        return ans * sl;
    }
}

signed main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);

    init();

    int n;
    cin >> n;
    map<int, int> cnt;
    for (int i = 0; i < n; i++) {
        int x;
        cin >> x;
        x = no_cubic(x);
        cnt[x]++;
    }
    auto get_cnt = [&](int x) {
        if (cnt.count(x)) {
            return cnt[x];
        } else {
            return (int)0;
        }
    };
    int ans = 0;
    if (cnt.count(1)) {
        ans++;
        cnt.erase(1);
    }
    set<pair<int, int>> seen;
    for (auto uu : cnt) {
        int f, no_need;
        tie(f, no_need) = uu;
        int pr = get_pair(f);
        if (pr == -1) {
            ans += cnt[f];
            continue;
        }
        int a = pr;
        int b = f;
        if (a > b) {
            swap(a, b);
        }
        if (!seen.count({a, b})) {
            ans += max(get_cnt(a), get_cnt(b));
            seen.insert({a, b});
        }
    } 
    cout << ans << endl;
}

