  for(int i = 2; i <= L; ++i) {
    is_prime[i] = true;
  }
  for(int i = 2; i <= SQRTL; ++i) {
    if(is_prime[i]) {
      for(int j = 2; j <= L / i; ++j) is_prime[j * i] = false;
    }
  }
  for(int i = 2; i <= L; ++i) {
    if(is_prime[i]) primes.push_back(i);
  }
  scanf("%d", &N);
  for(int i = 0; i < N; ++i) {
    long long s; scanf("%lld", &s);
    long long mod3_1 = 1, mod3_2 = 1;
    for(int p : primes) {
      int n = 0;
      while(s % p == 0) { ++n; s /= p; }
      n %= 3;
      if(n == 1) mod3_1 *= p;
      else if(n == 2) mod3_2 *= p;
      if(s == 1) break;
    }
    ++group_size[make_tuple(mod3_1, mod3_2, s)];
  }
  auto group_size2 = group_size;
  for(auto kv : group_size) {
    auto key = kv.first; auto val = kv.second;
    long long mod3_1 = get<0>(key), mod3_2 = get<1>(key), rest = get<2>(key);
    if(mod3_1 == 1 && mod3_2 == 1 && rest == 1) { group_size2[key] = 1; continue; }
    if(!group_size2.count(key)) continue;
    if(rest >= 100000) continue;
    auto it = group_size2.find(make_tuple(mod3_2, mod3_1, rest * rest));
    if(it == group_size2.end()) continue;
    if(it->second < val) group_size2.erase(it); else group_size2.erase(key);
  }
  int res = 0; for(auto kv : group_size2) res += kv.second;
  printf("%d\n", res);
  return 0;
}

