	}
	for(R i=1;i<=n;++i){
		a=in();b=c=1;l=sqrt(a);
		for(R j=1;j<=p&&pr[j]<=l;++j){
			if(a%pr[j])continue;
			for(cnt=0;!(a%pr[j]);a/=pr[j],++cnt);
			if((cnt%=3)&1)b*=pr[j],c*=pr[j]*pr[j];
			else if(cnt&2)c*=pr[j],b*=pr[j]*pr[j];
			l=sqrt(a);
		}
		if(a!=1){
			if(l*l==a)b*=a,c*=l;
			else b*=a,c*=a*a;
		}
		if(c<=M)++mp.insert(make_pair(b,(Data){c,0})).first->second.cnt;
		else ++ans;
	}
	if(mp[1].cnt)++ans;mp.erase(1);
	for(map<LL,Data>::iterator it=mp.begin();it!=mp.end();it=mp.begin()){
		ans+=max(it->second.cnt,mp[c=it->second.ant].cnt);
		mp.erase(it);mp.erase(c);
	}
	printf("%d\n",ans);
	return 0;
}

