long long cal(long long x){
    long long ans = 1;
    for (long long i = 2; i * i <= x; i++){
        if (x % i != 0) continue;
        if (x % (i * i) == 0) ans *= i, x /= i * i;
        else ans *= i * i, x /= i;
    }
    if (x != 1) ans *= x * x;
    return ans;
}

