using namespace std;

const int SQRT = 110000;
const int CBRT = 2200;

bool prime[SQRT];
vector<int> primes;
vector<long> squares;

long funcPair(long x) {
	long answer = 1;
	for (long d : primes) {
		if (d * d * d > x) {
			break;
		}
		int cnt = 0;
		while (x % d == 0) {
			x /= d;
			++cnt;
		}
		cnt %= 3;
		if (cnt == 1) {
			answer *= d * d;
		} else if (cnt == 2) {
			answer *= d;
		}
	}
	if (binary_search(all(squares), x)) {
		long k = round(sqrt(x));
		assert(binary_search(all(primes), k));
		answer *= k;
	} else {
		answer *= x * x;
	}
	return answer;
}

long funcNorm(long x) {
	return funcPair(funcPair(x));
}


