const int INF = (int)1e10 + 10;
const int N = (int)1e5 + 10;

int n, a[N], wyn;
VI prim;
bool zloz[N];
map<int, int> ile;
map<int, bool> vis;

int jeb(int x)
{
	int res = x;
	for (auto it: prim) {
		int sz = it*it*it;
		if (sz > x)
			break;
		while (x%sz == 0 && (x/sz)%it == 0)
			x /= sz;
	}
	return x;
}

int odpo(int x)
{
	int res = 1;
	if (x > N-5)
		return -1;
	for (auto it: prim) {
		if (res > INF)
			return -1;
		if (it > x)
			break;
		if (x%it == 0) {
			int sz = it*it*it;
			if (x%sz == 0)
				continue;
			if (res*it > INF)
				return -1;
			if (x%(it*it) == 0)
				res *= it;
			else
				res *= it*it;
		}
	}
	return res;
}

bool sze(int x)
{
	int co = pow(x, 0.3);
	while (co*co*co < x)
		++co;
	while (co*co*co > x)
		--co;
	return co*co*co == x;
}

