    		++wyn;
    	++ile[a[i]];
    }
    for (int i = 1; i <= n; ++i) {
    	if (vis[a[i]])
    		continue;
    	if (sze(a[i])) {
    		vis[a[i]] = true;
    		continue;
    	}
    	int co = odpo(a[i]);
