const int N = 1e5 + 4;

ll m, cube;
map<vector<pll>, int> cnt;
map<vector<pll>, bool> used;

vector<ll> cubes;

bool isCube(ll x) {
    return binary_search(all(cubes), x);
}

bool pused[N];
vector<int> prime;

vector<pll> factor(ll a) {
    vector<ll> p;
    for (int i = 0; i < size(prime);) {
        int pt = prime[i];
        if (pt * pt > a) {
            break;
        }
        if (a % pt == 0) {
            p.em_back(pt);
            a /= pt;
        } else {
            ++i;
        }
    }
    if (a > 1) {
        p.em_back(a);
    }
    sort(all(p));

    vector<pll> res;
    for (int i = 0; i < size(p);) {
        int j = i;
        while (j < size(p) && p[i] == p[j]) {
            ++j;
        }
        if ((j - i) % 3 != 0) {
            res.em_back(p[i], (j - i) % 3);
        }
        i = j;
    }
    return res;
}

void prepare() {
    for (int i = 2; i < N; ++i) {
        if (pused[i]) {
            continue;
        }
        for (ll j = (ll)i * i; j < N; j += i) {
            pused[j] = 1;
        }
    }
    for (int i = 2; i < N; ++i) if (!pused[i]) {
        prime.em_back(i);
    }

    for (ll i = 1; i * i * i < 1e10; ++i) {
        cubes.em_back(i * i * i);
    }
}

void solve() {
    prepare();

    cin >> m;
    for (int i = 0; i < m; ++i) {
        ll a;
        cin >> a;
        if (isCube(a)) {
            ++cube;
        } else {
            cnt[factor(a)]++;
        }
    }

    int res = 0;
    for (auto u : cnt) {
        if (used[u.first]) {
            continue;
        }

        vector<pll> pinv = u.first;
        for (pll& p : pinv) {
            p.second = 3 - p.second;
        }

        int cntInv = cnt.count(pinv);
        int add = max(u.second, cntInv);
        res += add;

        used[u.first] = used[pinv] = 1;
    }

    cout << res + (cube > 0) << "\n";
}

