		for (int j = 2; j < cube.size();j++) {
			while (i%cube[j] == 0)i /= cube[j];
		}
		if (i == 1) {
			flag = true;
			continue;
		}
		m[i]++;
	}
	for (unsigned long long int i = cube.size(); i*i*i <= (unsigned long long int)13000000000000000000; i++) {
		cube.push_back(i*i*i);
	}
	int ans = 0;
	for (auto i : m) {
