	bool flag=false;
	map<map<ll,int>,int>mp;
	rep(i,n){
		ll s;scanf("%lld",&s);
		map<ll,int>res;
		for(ll j:prime){
			while(s%j==0){
				res[j]++;
				s/=j;
			}
			if(j>2200)break;
		}
		auto it=lower_bound(prime.begin(),prime.end(),s);
		if(it!=prime.end()){
			res[s]++;
			s=1;
		}
		it=lower_bound(v.begin(),v.end(),s);
