int main(){
    bool f=false;
    getPrime(MAX_P+10);
    for(ll p : primes) prime2[p*p]=p;

    cin>>N;
    vector<ll> S(N);
    for(int i=0;i<N;i++) cin>>S[i];

    // Norm[t] : Norm(t)
    // NN[t] : Norm(t) の個数
    // Pair[t] : Pair(t)
    map<ll,ll> Norm,NN,Pair;
    for(int i=0;i<N;i++){
        ll s = S[i];
        ll n = 1;       // norm(s)
        ll r = 1;       // pair(s)
        for(ll p : primes){
            if(p>s) break;
            ll cnt=0;
            ll x=0;
            while(s%p==0){
                x++;
                assert(x<100);
                cnt++;
                s/=p;
            }
            cnt%=3;

            if(cnt==1){
                n *= p;
                r *= p*p;
            }else if(cnt==2){
                n *= p*p;
                r *= p;
            }
        }

        if(s > 1){
            if(prime2.count(s)){
                //sは素数の2乗
                n *= s;
                r *= prime2[s];
            }else{
                n *= s;
                r *= s*s;
            }
        }

        NN[n]++;
        Norm[S[i]]=n;
        Pair[S[i]]=r;
        if(n==1){
            assert(n==r);
        }
        if(n==1) f=true;
    }

    ll ans = 0;
    if(f) ans++;


    map<ll,bool> used;
    for(int i=0;i<N;i++){
        ll n = Norm[S[i]];
        ll p = Pair[S[i]];


        if(n==1) continue;
        if(used[n]){
            if(used[p]) continue;
            ans += NN[p];
        }else if(used[p]){
            if(used[n]) continue;
            ans += NN[n];
        }else{
            if(NN[n] >= NN[p]){
                ans += NN[n];
            }else{
                ans += NN[p];
            }
        }
        used[n]=used[p]=true;
    }

    cout << ans << endl;
}

