int main() {
	MakePrime(2155);
	cin >> n;
	unordered_map<LL, pair<LL, LL>> cnts;
	REP(i, n) {
		cin >> s[i];
		LL val = 1, another = 1;
		for (auto p : prime) {
			if (s[i] % p != 0)continue;
			int cnt = 0;
			while (s[i] % p == 0) {
				cnt++;
				s[i] /= p;
			}
			if (cnt % 3 == 1) {
				val *= p;
				another *= p*p;
			}
			else if (cnt % 3 == 2) {
				val *= p*p;
				another *= p;
			}
		}
		if (s[i] > 1) {
			LL tmp = sqrt(s[i]);
			LL root = 0;
			for (LL i = -1; i <= 1; i++) {
				if ((tmp + i)*(tmp + i) == s[i])root = tmp + i;
			}
			val *= s[i];
			if (root)another *= root;
			else another *= s[i] * s[i];
		}
		cnts[val].second = another;
		cnts[val].first++;
	}
	auto tmp = cnts;
	LL ans = 0;
	for (auto u : tmp) {
		if (u.first != 1 && cnts[u.second.second] < u.second)ans += u.second.first;
	}
	if (cnts[1].first != 0)ans++;
	cout << ans << endl;
