const int maxn(1e5 + 5);
const int mx(2200);

int n, tot, ans;
ll v[maxn], p[maxn], s, pri[mx];
map <ll, int> cnt, vis;

int main() {
	for (int i = 2; i < mx; ++i) {
		int flg = 0;
		for (int j = 2; j * j <= i && !flg; ++j)
			if (i % j == 0) flg = 1;
		if (!flg) pri[++tot] = i;
	}
	In(n);
	for (int i = 1; i <= n; ++i) {
		In(s), v[i] = p[i] = 1;
		for (int j = 1; j <= tot && s >= pri[j]; ++j)
			if (s % pri[j] == 0) {
				int num = 0;
				while (s % pri[j] == 0) s /= pri[j], ++num;
				if (!(num %= 3)) continue;
				if (num == 1) p[i] *= pri[j] * pri[j], v[i] *= pri[j];
				else v[i] *= pri[j] * pri[j], p[i] *= pri[j];
			}
		if (s > 1) {
			ll x = sqrt(s);
			if (x * x == s) p[i] *= x, v[i] *= x * x;
			else v[i] *= s, p[i] *= s * s;
		}
		++cnt[v[i]];
	}
	if (cnt[1]) cnt[1] = 1;
	for (int i = 1; i <= n; ++i)
		if (!vis[v[i]]) {
			ans += max(cnt[v[i]], cnt[p[i]]);
			vis[v[i]] = vis[p[i]] = 1;
		}
	printf("%d\n", ans);
    return 0;
}

