map<ll, ll> m1, m2;
inline void add(ll a){
	ll b = 1, c = 1;
	int d;
	for(int i = 0; i < (int) primes.size(); i++){
		if(a % primes[i] == 0){
			d = 0;
			while(a % primes[i] == 0){
				a /= primes[i];
				d++;
			}
			d %= 3;
			if(d == 1){
				b *= primes[i];
				c *= sqr((ll) primes[i]);
			}
			if(d == 2){
				b *= sqr((ll) primes[i]);
				c *= primes[i];
			}
		}
	}
	if(a > 1){
		ld s = sqrt(a) + E;
		ll e = s;
		if(e * e == a){
			b *= e * e;
			c *= e;
			a = 1;
		}
	}
	if(a > 1){
		ans++;
		return;
	}
	if(b == 1){
		cubes++;
		return;
	}

	m1[b]++;
	m2[b] = c;
}

