/*
D - Anticube
by.YXH_XianYu
   2018.6.15

题意:

给你n个数,分别为s1,s2,...,sn.
求一个s的子集，
使得不存在si*sj=平方数(i!=j).

----- ----- ----- ----- -----

题解:

我们将平方数质因数分解,可得每项指数均=3
那如果si*sj的每项质因数的指数均=3
则si,sj不能同时选取

将si分解质因数,把每个因子的指数%3,得到si(新).
寻找与si配对的sj(si*sj=平方数),
则si与sj不能同时选进子集,
最后判断si出现次数多,还是sj出现次数多,
选取出现次数多的记入答案.
 */
#include<algorithm>
#include<iostream>
#include<cstring>
#include<cstdio>
#include<cmath>
#define LLI long long
#define REG register
#define MXN 100010

LLI n,
	l1[MXN],
	l2[MXN];
#include<map>
std::map<LLI,int>cnt;

/* 欧拉筛法把1~3000质数筛出来 */
/* 筛到3000是因为3000^3 > 10^10 */
LLI pri_[MXN],	//3000内质数的立方
	pri[MXN];	//3000内质数
bool wth[MXN];	//wth[i]==0?i质:i合
void Euler(int n){
	wth[1]=1;
	for(int i=2;i<=n;i++){
		if(!wth[i])
			pri[++pri[0]]=i;
		for(int j=1;j<=pri[0]&&i*pri[j]<=n;j++){
			wth[i*pri[j]]=1;
			if(i%pri[j]==0)
				break;
		}
	}
	for(int i=1;i<=pri[0];i++)
		pri_[i]=pri[i]*pri[i]*pri[i];
}

int main(){

	scanf("%d",&n);
	Euler(3000);
	REG int i,j;
	for(i=1;i<=n;i++){
		LLI si,sj;

		scanf("%lld",&si);
		/* 将si的每个质因子的指数%3 */
		for(j=1;pri_[j]<=si;j++)
			while(si%pri_[j]==0)
				si/=pri_[j];
		cnt[si]++;	//记录si
		l1[i]=si;	//链表记录

		sj=1;		//寻找与si配对的sj
		for(j=1;pri_[j]<=si;j++)
			if(si%pri[j]==0){
				//使得si*sj的质因子指数=3
				sj*=(si%(pri[j]*pri[j])==0)?(pri[j]):(pri[j]*pri[j]);
				while(si%pri[j]==0)
					si/=pri[j];
			}
		//前面的循环退出条件为pri[j]^3>si
		//而会存在一种情况 si(现在)%pri[j]^2==0
		//这里对这个局面进行处理:
		//若si是平方数  ,则sj*=sqrt(si)
		//若si不为平方数,则sj*=si*si
		//均使得si*sj的质因子指数=3
		//赠:printf("<%lld>\n",si);
		sj*=((LLI)sqrt(si)*(LLI)sqrt(si)==si)?((LLI)sqrt(si)):(si*si);
		l2[i]=sj;//链表记录
	}
	/* 计算答案并输出 */
	int ans=0;
	if(cnt[1]>0) ans++,cnt[1]=0;//对质因数分解后为=1的数进行特判
	for(i=1;i<=n;i++)			//选取每对si,sj中,出现次数多的数选取
		ans+=std::max(cnt[l1[i]],cnt[l2[i]]),
		cnt[l1[i]]=cnt[l2[i]]=0;
	printf("%d\n",ans);
	//system("pause");
	return 0;
}

