LL znajdz_pierwiastek(LL co) {
	LL a = 1, b = 2155, sr;

	while(a != b) {
		sr = (a+b)/2;
		if(sr*sr*sr == co) return sr;
		if(sr*sr*sr > co) {
			b = sr;
		} else a = sr+1;
	}
	return a;
}

bool czy_szescian(LL co) {
	LL gdzie = znajdz_pierwiastek(co);
	if(gdzie*gdzie*gdzie == co) return 1;
	return 0;
}

void rozloz() {
	LL do_dod = 1, odw_dod = 1;
	for(int i = 0; i < liczbyPierwsze.size() && liczba > 1; i++) {
		pom.co = liczbyPierwsze[i];
		pom.wys = 0;
		while(liczba%pom.co == 0) {
			pom.wys = (pom.wys+1)%3;
			liczba /= pom.co;
		}
		if(pom.wys > 0) {
			do_dod *= pom.co;
			odw_dod *= pom.co;
			if(pom.wys == 2) do_dod *= pom.co;
			else odw_dod *= pom.co;
		}
	}
	if(liczba > 1) {
		LL sq = sqrt(liczba);
		if(sq*sq == liczba) {
			do_dod *= liczba;
			odw_dod *= sq;
		} else {
			if(liczba > 100000) {
				wynik++;
				return;
			}
			do_dod *= liczba;
			odw_dod *= liczba*liczba;
		}
	}
	if(odw_dod > duzo) wynik++;
	else {
		hasz.push_back(do_dod);
		hasz_uzup.push_back(odw_dod);
		mapa[do_dod]++;
	}
