  vector<long long> v(n);
  for(int i=0; i<n; i++){
    scanf("%lld", &v[i]);
  }
  sort(v.begin(), v.end());

  auto P = Eratosthenes(100000);

  vector<long long> cube;
  for(long long i=1; i*i*i <= 10_ten; i++){
    cube.push_back(i*i*i);
  }

  vector<vector<long long>> vp(n);
  vector<vector<long long>> vk(n);

  long long ans = 0;
  bool zero = false;
  map<int, long long> u;

  for(auto i : range(n) ){
    if(v[i] == 1) zero = true;
    else if( binary_search(cube.begin(), cube.end(), v[i] ) ) zero = true;
    else u[i] = v[i];
  }

  if(zero) ans++;

  map<vector<long long>, map<vector<long long>, long long>> G;

  for(auto p : P){
    if(u.size() == 0) break;
    map<int, long long> u_;
    for(auto& x : u){
      if(x.second % p != 0){
        u_.insert( x );
        continue;
      }

      int cnt = 0;
      while(x.second % p == 0){
        x.second /= p;
        cnt++;
      }

      if(cnt%3 != 0){
        vp[x.first].push_back( p );
        vk[x.first].push_back( cnt%3 );
      }

      if(x.second != 1){
        u_.insert(x);
      }
    }

    swap(u, u_);
  }

  for(auto& x : u){
    vp[x.first].push_back( x.second );
    vk[x.first].push_back( 1 );
  }

  for(int i=0; i<n; i++){
    if(vp[i].size() == 0) continue;
    G[ vp[i] ][ vk[i] ] += 1;
  }

  for(auto& ps : G){
    set<vector<long long>> used;
    for(auto& pr : ps.second){
      if( used.count( pr.first ) ) continue;
      auto inv = pr.first;
      for(auto& w : inv){
        w = w == 1 ? 2 : 1;
      }

      if( ps.second.count( inv ) == 0 ){
        ans += pr.second;
      }else{
        ans += max(pr.second, ps.second[inv]);
        used.insert(inv);
      }
    }
  }

  println(ans);

  return 0;
}

