using namespace std;
typedef long long ll;
const int N=200010,M=1000000,hs=19260817;
int cnt,tt=1,gg,S,T;
bool w[N];
map <ll,int> g;
int p[N],head[N],cur[N],to[M],nxt[M],s[M],lev[N],v[N];
inline int gi() {
    int x=0,o=1;
    char ch=getchar();
    while(ch!='-'&&(ch<'0'||ch>'9')) ch=getchar();
    if(ch=='-') o=-1,ch=getchar();
    while(ch>='0'&&ch<='9') x=x*10+ch-'0',ch=getchar();
    return x*o;
}
inline void pre(int n) {
    for(int i=2;i<=n;i++) {
	if(!w[i]) p[++cnt]=i;
	for(int j=1;j<=cnt&&i*p[j]<=n;j++) {
	    w[i*p[j]]=1;
	    if(i%p[j]==0) break;
	}
    }
}
inline void lnk(int x,int y,int z) {
    to[++tt]=y,nxt[tt]=head[x],s[tt]=z,head[x]=tt;
    to[++tt]=x,nxt[tt]=head[y],head[y]=tt;
}
inline bool bfs() {
    memset(lev,0,sizeof(lev));
    int t=0,sum=1;
    v[1]=S,lev[S]=1;
    while(t<sum) {
	int x=v[++t];
	for(int i=head[x];i;i=nxt[i]) {
	    int y=to[i];
	    if(s[i]&&!lev[y]) {
		lev[y]=lev[x]+1,v[++sum]=y;
		if(y==T) return 1;
	    }
	}
    }
    return 0;
}
inline int dfs(int x,int Mx) {
    if(x==T) return Mx;
    int ret=0;
    for(int &i=cur[x];i;i=nxt[i]) {
	int y=to[i];
	if(s[i]&&lev[y]==lev[x]+1) {
	    int f=dfs(y,min(Mx-ret,s[i]));
	    s[i]-=f,s[i^1]+=f,ret+=f;
	    if(ret==Mx) break;
	}
    }
    return ret;
}
int main() {
    int n,t=0,ans;
    cin>>n;
    pre(100000),S=0,T=N-1,ans=n;
    for(int i=1;i<=n;i++) {
	ll x=gi(),s1=0,s2=0,k=-1;
	for(int j=1;p[j]<=320;j++)
	    if(x%p[j]==0) {
		int t=0,q=p[j];
		while(x%q==0) x/=q,++t;
		if(t%=3) {
		    s1=s1*hs+q,s2=s2*hs+q;
		    if(t==2) s1=s1*hs+q,k=1;
		    else s2=s2*hs+q,k=0;
		}
	    }
	if(x>1) {
	    ll y=sqrt(x)+1e-9;
	    if(y*y==x) k=1,s1=y*hs+y,s2=y;
	    else if(x<=100000&&!w[x]) k=0,s1=x,s2=x*hs+x;
	    else continue;
	}
	if(k==-1) {t=1,--ans;continue;}
	if(!g[s1]) {
	    g[s1]=++gg;
	    if(g[s2]) {
		if(k) lnk(gg,g[s2],N);
		else lnk(g[s2],gg,N);
	    }
	}
	if(k) lnk(S,gg,1);
	else lnk(gg,T,1);
    }
    while(bfs()) {
	memcpy(cur,head,sizeof(cur));
	ans-=dfs(S,N);
    }
    cout<<ans+t;
    return 0;
}

