	for (int i = 2; i < X; i++)
		if (!pr[i]){
			p[pN++] = i;
			for (int j = i; j < X; j += i)
				pr[j] = i;
		}

	int n; cin >> n;
	for (int i = 0; i < n; i++){
		cin >> a[i];

		#define J ( ll(p[j]) * p[j] * p[j] )
		for (int j = 0; j < pN && J <= a[i]; j++) 
			while ( a[i] % J == 0 )
				a[i] /= J;
		#undef J

		//cerr << i << " : " << a[i] << endl;

		ll h1 = 0, h2 = 0, b = a[i], v = B;
		for (int j = 0; j < pN && p[j] <= b; j++){
			if (b % p[j] == 0){
				int c = 0;
				while(b % p[j] == 0) b /= p[j], c++;
				h1 = (h1 + v * c) % MOD;
				h2 = (h2 + v * (3 - c)) % MOD;
			}
			v = (v * B) % MOD;
		}

		//cerr << i << " : " << b << ", " << h1 << ", " << h2 << endl;
		comp[h2] = h1; comp[h1] = h2;
		cnt[ pll(b, h1) ]++;
	}

	int ans = 0;
	while(cnt.size()){
		ll b = cnt.begin()->first.first, h = cnt.begin()->first.second, x = cnt.begin()->second;
		cnt.erase(cnt.begin());

		if (h == 0 && b == 1){
			ans++; continue;
		}

		ll l = 1, r = 1e5 + 10;
		while(l + 1 < r){
			ll mid = (l + r) / 2;
			if (mid * mid <= b) l = mid;
			else r = mid;
		}

		pll other;

		if (l * l == b)
			other = pll(l, comp[h]);
		else
			other = pll( (b < 1e9 ? b * b : -1), comp[h] );

		ll y = cnt[other];
		cnt.erase(cnt.find(other));
		ans += max(x, y);
	}

	cout << ans << endl;

}

#include <cstdio>
