typedef long long LL;
const LL maxs=10000000000ll;
const int N=100005,M=2155;
bool u[M];
int p[330],m=0;
LL a[N],b[N];
std::map<LL,int> f;
void Pre(){
	for (int i=2;i<M;i++){
		if (!u[i]) p[++p[0]]=i;
		for (int j=1;j<=p[0] && i*p[j]<M;j++){
			u[i*p[j]]=1;
			if (i%p[j]==0) break;
		}
	}
}
int Sqrt(LL x){
	LL y=sqrt(x*1.0);
	for (;y*y<x;y++);
	return y*y==x?y:-1;
}
bool solve(){
	LL s,x=1,y=1;
	scanf("%lld",&s);
	for (int j=1;j<=p[0];j++){
		int cnt=0;
		for (;s%p[j]==0;s/=p[j]) cnt++;
		cnt%=3;
		if (cnt==1) x*=p[j],y*=p[j]*p[j];
			else if (cnt==2) y*=p[j],x*=p[j]*p[j];
		if (y>maxs) return 1;
	}
	int z=Sqrt(s);
	if (z!=-1) x*=s,y*=z;
		else if (y*s>maxs/s) return 1;
			else x*=s,y*=s*s;
	f[a[++m]=x]++;b[m]=y;
	return 0;
}
int main(){
	int n,ans=0;
	scanf("%d\n",&n);
	Pre();
	for (int i=1;i<=n;i++) ans+=solve();
	if (f[1]) ans++,f[1]=0;
	for (int i=1;i<=m;i++)
	if (f[a[i]]){
		ans+=std::max(f[a[i]],f[b[i]]);
		f[a[i]]=f[b[i]]=0;
	}
	printf("%d\n",ans);
}

