void EulerSieve(int n) {
    for (int i = 2; i <= n; i++) {
        if (!p[i]) prime[++pnum] = i;
        for (int j = 1; j <= pnum; j++) {
            if (i * prime[j] > n) break;
            p[i * prime[j]] = true;
            if (i % prime[j] == 0) break;
        }
    }
}
int main() {
    EulerSieve(S);
    scanf("%d", &n);
    for (int i = 1; i <= n; i++) {
        scanf("%lld", &s[i]);
        k[i] = len[i] = 0, t[i] = 1;
        for (int j = 1; j <= M; j++) {
            if (s[i] % prime[j]) continue;
            int m = 0;
            while (s[i] % prime[j] == 0) s[i] /= prime[j], m++;
            if (m %= 3) k[i] |= ((m & 1) << len[i]), len[i]++, t[i] *= prime[j];
        }
        if (s[i] > 1) {
            if (s[i] < S)
                k[i] |= (1 << len[i]), len[i]++, t[i] *= s[i];
            else {
                ll ss = sqrt(s[i]);
                if (ss * ss != s[i])
                    ans++, i--, n--;
                else
                    len[i]++, t[i] *= ss;
            }
        }
    }
    for (int i = 1; i <= n; i++) id[i] = i;
    sort(id + 1, id + n + 1, cmp);
    for (int l = 1, r = 1; l <= n; l = r + 1, r = l) {
