        for (int i = l; i <= r; i++) ms[k[id[i]]]++;
        for (int i = l; i <= r; i++) {
            int x = k[id[i]], ot = (maxn ^ k[id[i]]);
            if (ms[x] >= ms[ot]) ans += ms[x], ms[x] = ms[ot] = 0;
        }
    }
    printf("%d\n", ans);
    return 0;
}

