#include <bits/stdc++.h>
using namespace std;
using ll = long long;

ll solve() {
    ll N;
    cin >> N;
    vector<ll> S(N);
    for ( int i = 0; i < N; i++ ) {
        cin >> S[i];
    }

    ll p_max = 10e5 + 1;
    vector<int> prime_tbl(p_max, 1);
    prime_tbl[0] = prime_tbl[1] = 0;
    for ( ll k = 2; k <= p_max; k++ ) {
        for ( ll h = 2; h*k <= p_max; h++ ) {
            prime_tbl[h*k] = 0;
        }
    }
    vector<ll> prime;
    for ( ll i = 0; i <= p_max; i++ ) {
        if ( prime_tbl[i] == 1 ) prime.push_back(i);
    }

    auto enc_map = [](map<ll, ll>& m) -> string {
        string r;
        for ( auto x : m ) {
            r.append(to_string(x.first));
            r.append("_");
            r.append(to_string(x.second));
            r.append("_");
        }
        return r;
    };
    auto dec_map = [](string& s) -> map<ll, ll> {
        map<ll,ll> r;
        int i = 0, len = s.size();
        while ( i < len ) {
            string k = "", v = "";
            while ( i < len && s[i] != '_' ) {
                k.push_back(s[i]);
                i++;
            }
            i++;
            while ( i < len && s[i] != '_' ) {
                v.push_back(s[i]);
                i++;
            }
            i++;
            r[stol(k)] = stol(v);
        }
        return r;
    };

    map<string, ll> m;
    for ( int i = 0; i < N; i++ ) {
        map<ll, ll> ns;
        ll s = S[i];
        for ( ll k : prime ) {
            if ( k > s ) break;
            while ( s % k == 0 ) {
                ns[k] = (ns[k] + 1) % 3;
                s /= k;
            }
        }
        if ( s > 1 ) {
            ns[s] = (ns[s] + 1) % 3;
        }
        for ( auto it = ns.begin(); it != ns.end();) {
            if ( it->second == 0 ) {
                ns.erase(it++);
            } else {
                it++;
            }
        }
        m[enc_map(ns)]++;
    }

    ll ans = 0;
    set<string> checked;
    for ( auto mm : m ) {
        if ( mm.first == "" ) {
            ans += 1;
        } else {
            if ( checked.find(mm.first) == checked.end() ) {
                string k1 = mm.first;
                auto tmp = dec_map(k1);
                for ( auto& p : tmp ) {
                    p.second = (3 - p.second) % 3;
                }
                string k2 = enc_map(tmp);
                ans += max(m[k1], m[k2]);
                checked.insert(k1);
                checked.insert(k2);
            }
        }
    }
    return ans;
}

int main() {
    auto ans = solve();
    cout << ans << "\n";
    return 0;
}

