bool is_prime(long long x) {
  for (int i=2; i<=sqrt(x); i++) {
    if (x % i == 0) return false;
  }
  return true;
}

long long norm(long long x) {
  for (int k : p1) {
    while (x % (k*k*k) == 0) x /= k*k*k;
  }
  return x;
}

long long inv(long long x) {
  long long ret = 1;
  for (int k : p1) {
    int c = 0;
    while (x % k == 0) x /= k, c++;
    if (c > 0) {
      while (++c <= 3) {
        ret *= k;
        if (ret > M) return -1;
      }
    }
  }
  if (x == 1) return ret;
  int p = 0;
  for (int k : p2) {
    if (x % k == 0) {
      p = k;
      break;
    }
  }
  // - p1    -> p1^2
  // - p1*p2 -> -1
  // - p1^2  -> p1
  if (x == p) {
    ret *= p; if (ret > M) return -1;
    ret *= p; if (ret > M) return -1;
  }
  else if (x == p*p) {
    ret *= p; if (ret > M) return -1;
  }
  else {
    return -1;
  }
  return ret;
}

int main() {
  cin >> N;
