  }

  bool one = false;
  for (int i=0; i<N; i++) {
    long long s; cin >> s;
    long long n = norm(s);
    M = max(M, n);
    if (n == 1) one = true;
    else T[n]++;
  }

  int c = 0;
  for (auto p : T) {
    long long s = p.first;
    if (T[s] == 0) continue;
    long long v = inv(s);
    if (v == -1) c += p.second;
    else {
      c += max(T[v], p.second);
      T[v] = 0;
    }
  }
  cout << c + one << "\n";
  return 0;
}

