	{
		if(y&1) res=(res+x)%mod;
		x=(x+x)%mod;y=y/2;
	}
	return res;
}
ll qpow(ll x,ll y,ll mod)
{
	ll res=1;
	while(y)
	{
		if(y&1) res=res*x%mod;
		x=x*x%mod;y=y/2;
	}
