	IL bool Miller_Rabin(ll n){
		mod=n;
		rep(i,0,11)if(n%pri[i]==0)return n==pri[i];
		ll r,t;
		for(r=n-1,t=0;~r&1;r>>=1,++t);
		rep(i,0,11){
			ll x=fpw(pri[i],r);
			for(int j=0;j<t&&x>1;++j){
				ll y=mul(x,x);
				if(y==1&&x!=n-1)return false;
				x=y;
			}
			if(x!=1)return false;
		}
		return true;
	}
	IL ll gcd(ll x, ll y){return !y?x:gcd(y,x%y);}
	IL ll func(ll x, ll a){return pls(mul(x,x),a);}
	IL ll Find(ll n){
		static int test_time=150000;
		rep(i,0,11)if(n%pri[i]==0)return pri[i];
		ll a=rand();int tim=0;
		ll x=func(rand(),a),y=x;
		do{
			ll g=gcd(dec(x,y),n);
			if(g!=1&&g!=n)return g;
			x=func(x,a);y=func(func(y,a),a);++tim;
		}while(x!=y&&tim<test_time);
		return -1;
	}
	IL void Pollard_Rho(ll n,vector<ll>&D){
		while(!(n&1))n>>=1,D.pb(2);
		if(n==1||Miller_Rabin(n)){if(n!=1)D.pb(n);return;}
		ll d=-1;while(d==-1)d=Find(n);
		Pollard_Rho(d,D);Pollard_Rho(n/d,D);
	}
}
