using namespace std;

int n, pr[2005], p, ans;
LL s[100005], pal[100005];

map<LL, LL> M, M_pal;

bool isp(int x){
	FI(i, 1, p) if(x % pr[i] == 0) return false;
	return true;
}

int main(){
	FI(i, 2, 2200) if(isp(i)) pr[++p] = i;
	scanf("%d", &n);
	FI(i, 1, n){
		scanf("%lld", &s[i]);
		FI(j, 1, p){
			LL u = 1LL * pr[j] * pr[j] * pr[j];
			while(s[i] % u == 0) s[i] /= u;
		}
		//Now s[i] is p^3-free
		LL tmp = s[i];
		pal[i] = 1;
		FI(j, 1, p){
			if(tmp % pr[j] == 0){
				LL u = 1LL * pr[j] * pr[j] * pr[j];
				while(tmp % pr[j] == 0){
					tmp /= pr[j];
					u /= pr[j];
				}
				if(pal[i] <= LIM / u) pal[i] *= u;
				else pal[i] = LIM;
			}
		}
		if(tmp > 1){
			LL rt = sqrt(tmp);
			if(rt * rt == tmp && pal[i] <= LIM / rt) pal[i] *= rt;
			else if(pal[i] <= LIM / tmp / tmp) pal[i] *= tmp * tmp;
			else pal[i] = LIM;
		}
	}
	FI(i, 1, n){
		if(!M.count(s[i])) M[s[i]] = 1, M_pal[s[i]] = pal[i];
		else M[s[i]]++;
	}

	for(auto pi: M){
		LL u = pi.fi, cnt = pi.se;
		LL pa = M_pal[u];
		if(pa == u) ans++; //only if u == 1
		else if(!M.count(pa)) ans += cnt;
		else if(u > pa) ans += max(cnt, (LL)M[pa]);
	}
	printf("%d\n", ans);
	return 0;
}

