		    if(nonprime[x]) goto fail;
		    for(int i = 0 ; i < 2 ; ++i) {
			op = op * x;
			if(op > 1e10) goto fail;
		    }
		}
		else {
		    int64 t = sqrt(x);
		    if(t * t != x) goto fail;
		    else {
			op = op * t;
			if(op > 1e10) goto fail;
		    }
		}
	    }

	    if(op > num) ans -= min(zz[num],zz[op]);
	}
        fail:;
    }
    out(ans);enter;
