const ll RR = 2200;
vector<ll> cubes;

bool isCube(ll v) {
    ll l = 0, r = (int)cubes.size();
    while (l < r) {
        ll m = (l + r) >> 1;
        ll m3 = cubes[m];
        if (m3 >= v) {
            r = m;
        } else {
            l = m + 1;
        }
    }
    return cubes[l] == v;
}

ll sq(ll v) {
    ll t = (ll)sqrt(v);
    for (ll j = t - 1; j <= t + 1; ++j) {
        if (j * j == v) {
            return j;
        }
    }
    return -1;
}

inline void solve() {
    for (ll j = 1; j <= RR; ++j) {
        cubes.push_back(j * j * j);
    }
    int n;
    cin >> n;
    vector<ll> a(n);
    forn(i, n) {
        cin >> a[i];
    }
    vector<ll> b;
    int cnt_cubes = 0;

    forn(i, n) {
        bool ok = isCube(a[i]);
        if (ok) {
            ++cnt_cubes;
        } else {
            b.push_back(a[i]);
        }
    }
    int ans = 0;
    if (cnt_cubes) ++ans;
    a.swap(b);
    n = (int)a.size();
    b.clear();
    sort(all(a));

    vector<vector<int> > g(n);
    map<vector<pair<ll, int> >, int> mcnt;

    forn(i, n) {
        ll v = a[i];
        int ps = lower_bound(all(cubes), v) - cubes.begin();
        for (int j = ps; j > 0; --j) {
            if (v % cubes[j] == 0) {
                v /= cubes[j];
                break;
            }
        }
        a[i] = v;
    }
    vector<ll> pr;
    vector<char> u(100 * 100, 0);
    for (int i = 2; i < 100 * 100; ++i) {
        if (u[i]) continue;
        pr.push_back(i);
        for (int j = i + i; j < 100 * 100; j += i) {
            u[j] = 1;
        }
    }

    forn(j, n) {
        ll v = a[j];
        vector<pair<ll, int> > res;
        for (int i = 0; i < pr.size() && pr[i] < RR; ++i) {
            PII pa = PII(pr[i], 0);
            while (v % pr[i] == 0) {
                v /= pr[i];
                pa.second++;
            }
            if (pa.second) {
                res.push_back(pa);
            }
        }
        if (v > 1) {
            ll ss = sq(v);
            if (ss == -1) {
                res.push_back(mp(v, 1));
            } else {
                res.push_back(mp(ss, 2));
            }
        }
        mcnt[res]++;
    }
    ll ans2 = 0;
    for (const pair<vector<pair<ll, int>>, int> &pa : mcnt) {
        const vector<pair<ll, int> > &c1 = pa.first;
        vector<pair<ll, int> > c2 = c1;
        for (auto &elem : c2) {
            assert(elem.second != 0);
            assert(elem.second < 3);
            elem.second = 3 - elem.second;
        }
        if (mcnt.count(c2)) {
            ans2 += max(pa.second, mcnt[c2]);
        } else {
            ans2 += pa.second * 2;
        }
    }
    ans2 /= 2;
    ans += ans2;
    cout << ans << "\n";
}

