void solve(){
	int N;
	cin >> N;
	vector<LL> X(N);
	for(int i=0;i<N;++i){
		cin >> X[i];
	}
	const int P_MAX = 100001;
	vector<bool> Bprime(P_MAX+1,true);
	vector<int> prime;
	for(int i=2;i<=P_MAX;++i){
		if( Bprime[i] ){
			prime.push_back(i);
			for(int j=i+i;j<=P_MAX;j+=i){
				Bprime[j] = false;
			}
		}
	}
	const int P_size = prime.size();
	//cout << P_size << endl;
	int index = lower_bound(prime.begin(),prime.end(),2200) - prime.begin();
	//cout << index << endl;

	map< vector<vector<int> >,int > MAP;
	int rrr = 0;//立方数の個数
	int NoPair = 0;//ペアになれない数の個数
	for(int i=0;i<N;++i){
		LL temp = X[i];
		vector< vector<int> > dat(2);
		for(int j=0;j<index;++j){
			if( temp%prime[j] == 0 ){
				int pNum = 0;
				while(temp%prime[j] == 0 ){
					temp /= prime[j];
					++pNum;
				}
				if(pNum%3){
					dat[(pNum%3)-1].push_back( prime[j] );
				}
			}
		}

		if( temp != 1 ){//2200より大きい素数が残っている。
			vector<int>::iterator itr;
			itr = lower_bound(prime.begin(),prime.end(),temp);
			//素数の1乗
			//P_MAXより大きい素数は立方数のペアがいない(q<=10^10)
			if( itr != prime.end() ){
				if( (*itr) == temp ){
					dat[0].push_back( temp );
					temp = 1;
				}
			}
			if( temp != 1 ){//素数の2乗
				LL var = sqrt( 1.0*temp );
				if( var*var == temp ){
					dat[1].push_back( var );
					temp = 1;
				}
			}
			if( temp == 1 ){
				MAP[ dat ]++;
			}else{
				//pq型,ペアにならない
				NoPair++;
			}
		}else if( (dat[0].size() == 0) && (dat[1].size() == 0) ){
			//立方数
			++rrr;
			continue;
		}else{
			MAP[ dat ]++;
		}

	}

	map< vector<vector<int> >,int >::iterator itr,end;
	itr = MAP.begin();
	end = MAP.end();
	LL ans = 0;
	for(;itr!=end;++itr){
		int L = itr->second;
		if( L == 0 ) continue;
		vector< vector<int> > ter;
		ter = itr->first;
		swap( ter[0],ter[1] );
		int R = MAP[ ter ];
		ans += max(L,R);
		if( R ){
			MAP[ ter ] = 0;
		}
	}
	if( rrr ) ++ ans;//立方数は一つだけ加える
	cout << ans + NoPair << endl;
}

