pair<vl,vl> canonize(ll x) {
	vl self,anti;

	for(int p : P){
		if(p*1LL*p > x) break;
		if(x%p == 0) {
			int e = 0;
			while(x%p == 0) x /= p,e++;
			e %= 3;
			if(e == 0) continue;
			self.pb(p);
			anti.pb(p);
			if(e == 2) self.pb(p);
			else anti.pb(p);
		}
	}
	if(x > 1) {
		self.pb(x);
		anti.pb(x);
		anti.pb(x);
	}
	return mp(self,anti);
}

