    auto P3 = get_primes(2154);
    for (auto s : S) {
        Int norm = 1, pair = 1;
        for (auto p : P3) {
            int cnt = 0;
            while (s % p == 0) s /= p, cnt++;
            cnt %= 3;
            if (cnt == 1) { norm *= p, pair *= p * p; }
            if (cnt == 2) { pair *= p, norm *= p * p; }
        }
        if (P2.count(s)) {
            norm *= s, pair *= sqrt(s);
        } else {
            norm *= s, pair *= s * s;
        }
        M[norm] += 1;
        NP[norm] = pair;
        NP[pair] = norm;
    }
    int ans = 0;
    for (auto &p : M) {
        if (p.first == 1) {
            ans += 1;
        } else {
            ans += max(p.second, M[NP[p.first]]);
            p.second = M[NP[p.first]] = 0;
        }
    }
    cout << ans << endl;
    return 0;
}

