map <ll, vector <pair <ll, int> > > S ;
map <ll, bool> is_square ;
map <vector <pair <ll, int> >, int> last, times ;
bool vis[N] ; int n ; 
vector <pair <ll, int> > p[N] ;

void pre() {
	rep(i, 1, V) {
		is_square[(ll) i * i] = true ;
		int x = i ;
		vector <pair <ll, int> > it ;
		rep(j, 2, i) {
			if (j * j > i) break ;
			if (x % j) continue ;
			it.push_back(make_pair(j, 0)) ;
			int pos = (int) it.size() - 1 ;
			for ( ; x % j == 0 ; x /= j) it[pos].second += 2 ;
			it[pos].second %= 3 ;
			if (!it[pos].second) it.pop_back() ;
		}
		if (x > 1) it.push_back(make_pair(x, 2)) ;
		S[(ll) i * i] = it ;
	}
}

bool cmp(pair <ll, int> a, pair <ll, int> b) {
	return a.first < b.first ;
}

vector <pair <ll, int> > getvec(ll x) {
	vector <pair <ll, int> > ret ;
	pair <ll, int> d[105] ;
	int d0 = 0 ;
	rep(i, 2, M) {
		if (x % i) continue ;
		d[++ d0] = make_pair(i, 0) ;
		for ( ; x % i == 0LL ; x /= i) d[d0].second += 1 ;
	}
	if (is_square[x]) {
		rep(i, 0, (int) S[x].size() - 1) d[++ d0] = S[x][i] ;
	} else {
		d[++ d0] = make_pair(x, 1) ;
	}
	sort(d + 1, d + d0 + 1, cmp) ;
	for (int i = 1, j; i <= d0; i = j) {
		ret.push_back(d[i]) ;
		int pos = (int) ret.size() - 1 ;
		for (j = i + 1; j <= d0 && d[i].first == d[j].first; ++ j) ret[pos].second += d[j].second ;
		ret[pos].second %= 3 ;
		if (!ret[pos].second) ret.pop_back() ;
	}
	return ret ;
}

vector <pair <ll, int> > getrev(vector <pair <ll, int> > a) {
	vector <pair <ll, int> > b ;
	rep(i, 0, (int) a.size() - 1) {
		b.push_back(make_pair(a[i].first, 3 - a[i].second)) ;
	}
	return b ;
}

int main() {
	scanf("%d", &n) ;
	pre() ;
	rep(i, 1, n) {
		ll x ;
		scanf("%lld", &x) ;
		p[i] = getvec(x) ;
//		rep(j, 0, (int) p[i].size() - 1) printf(" (%lld, %d) ", p[i][j].first, p[i][j].second) ; printf("\n") ;
		++ times[p[i]], last[p[i]] = i ;
	}
	memset(vis, true, sizeof(vis)) ;
	int ans = 0 ;
	rep(i, 1, n) if (last[p[i]] == i && vis[i]) {
		if (!p[i].size()) {
			ans ++ ;
			continue ;
		}
		vector <pair <ll, int> > q = getrev(p[i]) ;
		if (!times[q]) {
			ans += times[p[i]] ;
			continue ;
		}
		vis[last[q]] = false ;
		ans += max(times[p[i]], times[q]) ;
	}
	printf("%d\n", ans) ;
	return 0 ;
}

