void prime_split(long long num){
	//cout << "num= " << num << endl;
	map<long long, long long> tmp;
	long long bak = num;
	for(long long i = 0; prime[i] <= sqrt(num); i++){
		//cout << "i=" << i << endl;
		//cout << "prme*prim" << prime[i]*prime[i] << " num= " << num << endl;
		while(bak % prime[i] == 0){
			tmp[prime[i]]++;
			tmp[prime[i]]%=3;
			if(tmp[prime[i]] == 0){
				tmp.erase(prime[i]);
			}
			bak /= prime[i];
		}
	}

	if(bak > 1){
		tmp[bak]++;
		tmp[bak]%=3;
		if(tmp[bak] == 0){
			tmp.erase(bak);
		}
	}

	if(tmp.size() == 0){
		squ = true;
	}else{
		hist[tmp]++;
	}
}


