		if (is.test(i)) pr[++ tot] = i;
		for (int j = 1; j <= tot && pr[j] * i <= n; ++ j) {
			is.reset(pr[j] * i);
			if (i % pr[j] == 0) break;
		}
	}
}

inline LL simplify(LL x) {
	For(i, 1, tot) {
		int cnt = 0;
		while (x % pr[i] == 0) x /= pr[i], ++ cnt;
		Rep(j, cnt %= 3) x *= pr[i];
	}
	return x;
}

inline LL complement(LL x) {
	LL ans = 1;
	For(i, 1, tot) {
		int cnt = 0;
		while (x % pr[i] == 0) x /= pr[i], ++ cnt;
		Rep(j, (3 - cnt % 3) % 3) ans *= pr[i];
	}
	LL qt = (int)sqrt(x);
	return (qt * qt == x) ? ans * qt : -1;
}

