				prod *= pr[d];
			}
			else ans++;
		}
		else{
			if (prod == 1) flag = 1;
			else{
				rec[num]++;
				sav[num] = prod;
			}
		}
	}
	for (auto it : sav){
		if (rec[it.first] > rec[it.second] || (rec[it.first] == rec[it.second] && it.first > it.second))
			ans += rec[it.first];
	}
	ans += flag;
	printf("%d\n", ans);
	return 0;
}

