#include <bits/stdc++.h>
#define ll long long
using namespace std;

const int N = 1e5 + 5;
const ll Mx = 1e10;

int prime[N], b[N], totnum = 0, tot = 0;
ll dprime[N];

ll Pow(ll x) {
	return 1ll * x * x * x;
}

void Pre() {
	for (int i = 2; i <= 2200; ++ i) {
		if (! b[i]) prime[++ totnum] = i;
		for (int j = 1; j <= totnum && i * prime[j] <= 2200; ++ j) {
			b[prime[j] * i] = 1;
			if (i % prime[j] == 0) break;
		}
	}
	tot = 0;
	for (int i = 1; i <= totnum; ++ i) {
		ll val = Pow(prime[i]);
		if (val > Mx) break;
		dprime[++ tot] = val;
	}
}

int n; ll a[N];
map <ll, int> Mp;

inline ll f(ll x) {
	ll res = 1ll;
	for (int i = 1; i <= totnum; ++ i) {
		if (prime[i] > x) break;
		int t = 0;
		while (x % prime[i] == 0) x /= prime[i], ++ t;
		if (t == 1) res *= prime[i] * prime[i];
		else if (t == 2) res *= prime[i];
	}
	if (x == 1) return res;
	ll sqr = sqrt(x);
	if (sqr * sqr == x) return res * sqr;
	else if (res * x * x <= Mx) return res * x * x;
	else return -1;
}

int main(void) {
	Pre(); Mp.clear();
	scanf("%d", &n);
	for (int i = 1; i <= n; ++ i) scanf("%lld", &a[i]);
	bool ok = false;
	for (int i = 1; i <= n; ++ i) {
		for (int j = 1; j <= tot && dprime[j] <= a[i]; ++ j) {
			while (a[i] % dprime[j] == 0) a[i] /= dprime[j];
		}
		if (a[i] == 1) ok = true; else ++ Mp[a[i]];
	}


//	for (int i = 1; i <= n; ++ i) printf("%d ", a[i]); puts("");
	sort(a + 1, a + 1 + n);
	int i = 1; while (a[i] == 1 && i <= n) ++ i;

	ll ans = 0;
	for (int last; (last = i) <= n; ++ i) {
		while (a[i] == a[i + 1]) ++ i;
		ll tar = f(a[i]);
		if (tar == -1) ans += i - last + 1;
		else if (tar < a[i] && (* lower_bound(a + 1, a + 1 + n, tar)) == tar) continue;
		else ans += max(i - last + 1, Mp[tar]);
//		printf("tar = %lld ans = %lld\n", tar, ans);
	}
	printf("%d\n", ans + ok);
	return 0;
}

