  f[0] = f[1] = false;
  for (int i = 2; i <= 100000; ++i) {
    if (f[i]) {
      if (i < 2200) prime.push_back(i);
      mp[i * i] = i;
      for (int j = 2 * i; j <= 100000; j += i) {
        f[j] = false;
      }
    }
  }

  for (int i = 0; i < n; ++i) {
    __int128_t m;
    cin >> m;

    __int128_t a, b;
    a = b = 1;

    for (auto &p : prime) {
      int cnt = 0;
      while (m % p == 0) {
        ++cnt;
        m /= p;
      }

      cnt %= 3;
      for (int j = 0; j < cnt; ++j) a *= p;
      for (int j = (3 - cnt) % 3; j > 0; --j) b *= p;
    }

    if (mp.count(m)) {
      a *= mp[m];
      b *= m;
    } else {
      a *= m * m;
      b *= m;
    }

    s.push_back(a);
    t.push_back(b);
  }
