    return gcd(b, a%b);
}
ll rev(ll n) {
    ll res = 1;
        // cout << "!" << n << endl;
    REP(t, 5) {
        ll x = 2, y = 2, d = 1;
        while (d == 1) {
            x = f(x, n);
            y = f(f(y, n), n);
            d = gcd(abs(x-y), n);
        }
        if (d != n) {
            // assert(n % d == 0);
            if (n % (d*d) == 0) {
                n /= d*d;
                res *= d;
            }
            else {
                n /= d;
                res *= d*d;
            }
        }
        else {
            ++C;
        }
    }
    if (n < 100) {
        EACH(i, p2) {
            ll ii = i*i;
            if (ii > n) break;
            if (n % ii == 0) {
