void pre() {
  for(int i = 2; i < 2200; i++) if(!P[i]) {
    primes.push_back(i);
    for(int j = 2 * i; j < 2200; j += i) {
      P[j] = 1;
    }
  }
}

LL reduce(LL x) {
  rep(i,0,primes.size()) {
    LL y = primes[i] * 1LL * primes[i] * 1LL * primes[i];
    while(x % y == 0) x /= y;
  }
  return x;
}

LL comp(LL x) {
  LL y = x;
  LL res = 1;
  rep(i,0,primes.size()) if(y % primes[i] == 0) {
    LL tmp = primes[i] * 1LL * primes[i] * 1LL * primes[i];
    while(y % primes[i] == 0) {
      y /= primes[i];
      tmp /= primes[i];
    }
    res *= tmp;
    if(res > LIM) return -1;
  }
  if(y > 1) {
    LL q = sqrt(y);
    if (q * q == y) {
      if(res * q > LIM) return -1;
      return res * q;
    }
    if(y > 100000) return -1;
    res *= y;
    if(res > LIM) return -1;
    res *= y;
    if(res > LIM) return -1;
  }
  return res;
}

int main() {
