  rep(i,0,n) {
    LL x;
    scanf("%lld",&x);
    x = reduce(x);
    A[i] = x;
    M[x]++;
  }
  bool one = false;
  rep(i,0,n) if(A[i] != -1) {
    if(A[i] == 1) {
      one = true;
      continue;
    }
    if(M.find(A[i]) == M.end()) continue;
    LL x = comp(A[i]);
    if(x == -1) ans += M[A[i]];
    else ans += max(M[A[i]], M[x]);
    M.erase(A[i]);
    M.erase(x);
  }
  P(ans+one);
  return 0;
}

