#include <bits/stdc++.h>
using namespace std;
bool is_cube(long long N){
  long long c = (long long) (cbrt(N) + 0.001);
  return (c * c * c == N) || ((c + 1) * (c + 1) * (c + 1) == N) || ((c - 1) * (c - 1) * (c - 1) == N);
}
int is_square(long long N){
  long long c = (long long) (sqrt(N) + 0.001);
  if (c * c == N){
    return c;
  } else if ((c + 1) * (c + 1) == N){
    return c + 1;
  } else if ((c - 1) * (c - 1) == N){
    return c - 1;
  } else {
    return -1;
  }
}
int main(){
  int N;
  cin >> N;
  vector<long long> s(N);
  for (int i = 0; i < N; i++){
    cin >> s[i];
  }
  int cnt = 0;
  vector<long long> t;
  for (int i = 0; i < N; i++){
    if (is_cube(s[i])){
      cnt++;
    } else {
      t.push_back(s[i]);
    }
  }
  int ans = 0;
  if (cnt >= 1){
    ans++;
  }
  map<long long, int> A;
  map<long long, int> B;
  map<pair<long long, long long>, int> C;
  int M = t.size();
  for (int i = 0; i < M; i++){
    for (long long j = 2; j * j * j <= t[i]; j++){
      if (t[i] % (j * j * j) == 0){
        t[i] /= j * j * j;
      }
    } 
    int c = is_square(t[i]);
    if (c != -1){
      B[c]++;
    } else {
      bool is_C = false;
      long long mx = -1;
      for (long long j = 1; j * j * j <= t[i]; j++){
        if (t[i] % j == 0){
          int c = is_square(t[i] / j);
          if (c != -1 && is_square(j) == -1){
            C[make_pair(c, j)]++;
            is_C = true;
            break;
          } else {
            if (t[i] % (j * j) == 0 && t[i] % (j * j * j) != 0 && !is_square(t[i] / (j * j))){
              mx = max(mx, j);
              break;
            }
          }
        }
      }
      if (mx != -1){
        C[make_pair(mx, t[i] / (mx * mx))]++;
        is_C = true;
      }
      if (!is_C){
        A[t[i]]++;
      }
    }
  }
  vector<long long> val;
  for (auto P : A){
    val.push_back(P.first);
  }
  for (auto P : B){
    val.push_back(P.first);
  }
  sort(val.begin(), val.end());
  val.erase(unique(val.begin(), val.end()), val.end());
  for (long long x : val){
    ans += max(A[x], B[x]);
  }
  set<pair<long long, long long>> val2;
  for (auto P : C){
    long long x = P.first.first;
    long long y = P.first.second;
    val2.insert(make_pair(min(x, y), max(x, y)));
  }
  for (auto P : val2){
    long long x = P.first;
    long long y = P.second;
    ans += max(C[make_pair(x, y)], C[make_pair(y, x)]);
  }
  cout << ans << endl;
}

#include <bits/stdc++.h>

typedef long long LL;
const int N = 100005, M = 2154;

int n, a[N], pr[M], pt, md[M], ans;
std::map<LL, std::pair<int, int>> s;
LL x;

void sieve(int n) {
	for (int i = 2; i <= n; ++i) {
		if (!md[i]) pr[++pt] = i, md[i] = i;
		for (int j = 1, t; j <= pt && (t = i * pr[j]) <= n; ++j) {
			md[t] = pr[j];
			if (pr[j] == md[i]) break;
		}
	}
}

void factor(LL x) {
	__int128 norm = 1, pair = 1;
	for (int i = 1; i <= pt && (LL) pr[i] * pr[i] * pr[i] <= x; ++i)
		if (x % pr[i] == 0) {
			int cnt = 0;
			do ++cnt, x /= pr[i]; while (x % pr[i] == 0);
			cnt %= 3;
			if (cnt) {
				for (int j = 0; j < cnt; ++j) norm *= pr[i];
				for (int j = cnt; j < 3; ++j) pair *= pr[i];
			}
		}
	int t = std::sqrt(x) + 0.5;
	if ((LL) t * t == x) norm *= t * t, pair *= t;
	else norm *= x, pair *= (__int128) x * x;
	if (norm == pair) ans = 1;
	else if (norm < pair) ++s[norm].first;
	else ++s[pair].second;
}

int main() {
	std::ios::sync_with_stdio(0), std::cin.tie(0);
	std::cin >> n, sieve(M - 1);
	for (int i = 1; i <= n; ++i) std::cin >> x, factor(x);
	for (auto i : s) ans += std::max(i.second.first, i.second.second);
	std::cout << ans << '\n';
	return 0;
}

