ll ksc(ll x,ll y,ll mod){//x*y
    ll res=0;
    x%=mod;
    while(y){
        if(y&1){
            res+=x;
            if(res>mod) res-=mod;
        }
        x+=x;
        if(x>mod) x-=mod;
        y>>=1;
    }
    return res;
}
ll ksm(ll x,ll y,ll mod){//x^y
    ll res=1;
    while(y){
        if(y&1){
            res=ksc(res,x,mod);
        }
        x=ksc(x,x,mod);
        y>>=1;
    }
    return res;
}
bool Test(ll q,ll d,ll n){
    ll x=ksm(q,d,n);
    if(x==1||x==n-1)
        return true;
    while(d!=n-1){
        x=ksc(x,x,n);
        if(x==n-1)
            return true;
        d<<=1;
    }
    return false;
}
bool Miller_Rabin(ll x){
    if(x==1)
        return false;
    if(x==2)
        return true;
    if(!(x&1))
        return false;
    ll d=x-1;
    while(!(d&1))
        d>>=1;
    for(int i=0;i<10;i++){
        if(p[i]>=x)
            break;
        if(!Test(p[i],d,x))
            return false;
    }
    return true;
}
ll f(ll x,ll a,ll mod){
    return (ksc(x,x,mod)+a)%mod;
}
ll gcd(ll x,ll y){
    if(!y)
        return x;
    return gcd(y,x%y);
}
ll myabs(ll x){
    return x>0?x:-x;
}
void Pollard_rho(ll n){
    if(n==1)
        return ;
    if(Miller_Rabin(n)){
        pr[n]++;
        return ;
    }
    if(!(n&1)){
        pr[2]++;
        Pollard_rho(n/2);
        return ;
    }
    ll x=rand()%(n-2)+2;
    ll y=x;
    ll a=rand()%(n-1)+1;
    ll d=1;
    while(d==1||d==n){
        x=f(x,a,n);
        y=f(f(y,a,n),a,n);
        d=gcd(n,myabs(x-y));
        if(x==y)
            a++;
    }
    Pollard_rho(d);
    Pollard_rho(n/d);
}
