        pr.clear();
        Pollard_rho(s);
        for(map<ll,int>::iterator it=pr.begin();it!=pr.end();it++){
            ll h=it->first;
            int pi=it->second;
            pi%=3;
            if(pi==1)
                t*=h,t1*=h*h;
            if(pi==2)
                t*=h*h,t1*=h;
        }
        if(t<t1)
            z[t]++;
        else{
            z[t1]++;
