int main(){
	FI(i, 2, 2200) if(isp(i)) pr[++p] = i;
	scanf("%d", &n);
	FI(i, 1, n){
		scanf("%lld", &s[i]);
		FI(j, 1, p){
			LL u = 1LL * pr[j] * pr[j] * pr[j];
			while(s[i] % u == 0) s[i] /= u;
		}
		//Now s[i] is p^3-free
		LL tmp = s[i];
		pal[i] = 1;
		FI(j, 1, p){
			if(tmp % pr[j] == 0){
				LL u = 1LL * pr[j] * pr[j] * pr[j];
				while(tmp % pr[j] == 0){
					tmp /= pr[j];
					u /= pr[j];
				}
				if(pal[i] <= LIM / u + 1) pal[i] *= u;
				else pal[i] = LIM;
			}
		}
		if(tmp > 1){
			LL rt = sqrt(tmp);
			if(rt * rt == tmp && pal[i] <= LIM / rt + 1) pal[i] *= rt;
			else if(pal[i] <= LIM / tmp / tmp + 1) pal[i] *= tmp * tmp;
			else pal[i] = LIM;
		}
	}
