int prime[MAXM]= {0}, pcnt = 0;
bool visit[MAXM]= {false};
const int MAX = 2200;
void sieve () {
	for (int i = 2; i <= MAX; i ++) {
		if (visit[i]) continue;
		prime[++ pcnt] = i;
		for (int j = i << 1; j <= MAX; j += i)
			visit[j] = true;
	}
}

tr1::unordered_map<LL, int> mapp, ccnt;
int ind = 0;
inline LL power (LL x, int p) {
	LL cnt = 1;
	for (int j = 1; j <= p; j ++)
		cnt *= x;
	return cnt;
}
pair<LL, LL> save[MAXN];
int solve () {
	int ans = 0;
	save[++ ind] = make_pair (1, 0);
	mapp[0] = mapp[1] = 1;
	for (int i = 1; i <= N; i ++) {
		int p = a[i];
		LL cnt = 1, ano = 1;
		for (int j = 1; j <= pcnt; j ++)
			if (! (p % prime[j])) {
				int times = 0;
				while (! (p % prime[j]))
					p /= prime[j], times ++;
				times %= 3;
				if (times > 0)
					ano *= power (prime[j], 3 - times);
				cnt *= power (prime[j], times);
			}
		// cout << "orin: " << a[i] << " and " << cnt << ' ' << ano << ' ' << p << endl;
		if (a[i] != 1 && cnt == 1 && p == 1) {
			ccnt[0] ++;
			continue;
		}
		ccnt[cnt * p] ++, newa[i] = cnt * p;
		if (mapp[cnt * p]) continue;
		if (p > 1) {
			LL sqr = sqrt (p);
			if (sqr * sqr == p) {
				// cout << "Suc: " << a[i] << endl;
				save[++ ind] = make_pair (cnt * p, ano * sqr);
				mapp[cnt * p] = mapp[ano * sqr] = ind;
			}
		}
		else {
			save[++ ind] = make_pair (cnt, ano);
			mapp[cnt] = mapp[ano] = ind;
		}
	}
	ccnt[0] = min (ccnt[0], 1), ccnt[1] = min (ccnt[1], 1);
	/*for (int i = 1; i <= ind; i ++) {
		cout << save[i].first << ' ' << save[i].second << ' ';
		cout << "and " << ccnt[save[i].first] << ' ' << ccnt[save[i].second] << endl;
	}*/
	for (int i = 1; i <= ind; i ++)
		ans += max (ccnt[save[i].first], ccnt[save[i].second]);
	/*for (int i = 1; i <= N; i ++)
		cout << newa[i] << ' ';
	puts ("");*/
	for (int i = 1; i <= N; i ++)
		if (! mapp[newa[i]])
			ans ++;
	return ans;
}

