	is_prime[0]=is_prime[1]=false;
	vector<ll>res;
	for(int i=2;i<=n;i++){
		if(!is_prime[i])continue;
		res.push_back(i);
		for(int j=2*i;j<=n;j+=i){
			is_prime[j]=false;
		}
	}
	return res;
}
int main(){
	auto prime=prime_enum(100000);
	vector<P>v;
	for(ll i:prime)v.push_back(P(i*i,i));
	int n;scanf("%d",&n);
	ll ans=0;
	bool flag=false;
	map<map<ll,int>,int>mp;
	rep(i,n){
		ll s;scanf("%lld",&s);
		map<ll,int>res;
		for(ll j:prime){
			while(s%j==0){
				res[j]++;
				s/=j;
			}
			if(j>2200)break;
		}
		auto it=lower_bound(prime.begin(),prime.end(),s);
		if(it!=prime.end()&&*it==s){
			res[s]++;
			s=1;
		}
		auto it2=lower_bound(v.begin(),v.end(),P(s,0));
		if(it2!=v.end()&&it2->first==s){
			res[it2->second]+=2;
			s=1;
		}
		if(s!=1){
			ans++;
			continue;
		}
		map<ll,int>m;
		for(auto p:res){
			if(p.second%3)m[p.first]=p.second%3;
		}
