map<ll, int> dp;

set<ll> used;

int countOther() {
  int ret = 0;
  for(auto x: dp) {
    if(used.count(x.first)) continue;
    // x == p * q*q
    ll pComp = 1;
    ll qComp = 1;
    ll amt = x.first;
    for(ll i = 2; i * i * i <= amt; i++) {
      if(amt%i) continue;
      if(amt%(i*i)==0) {
        qComp *= i;
        amt /= i*i;
      }
      else {
        pComp *= i;
        amt /= i;
      }
    }
    ll leftover = (ll)sqrt(amt);
    if(leftover * leftover != amt) {
      used.insert(x.first);
      ret += x.second;
      continue;
    }
    if(pComp >= 100000) {
      used.insert(x.first);
      ret += x.second;
      continue;
    }
    qComp *= leftover;
    ll real = pComp * pComp * qComp;
    if(dp.count(real)) {
      ret += max(dp[real], dp[x.first]);
      used.insert(real);
      used.insert(x.first);
    }
    else {
      used.insert(x.first);
      ret += x.second;
    }
  }
  return ret;
}

int countSquares() {
  int ret = 0;
  for(auto x: dp) {
    ll k = (ll)sqrt(x.first);
    if(k*k != x.first) continue;
    if(dp.count(k)) {
      used.insert(k);
      used.insert(x.first);
      ret += max(dp[k], dp[x.first]);
    }
    else {
      used.insert(x.first);
      ret += dp[x.first];
    }
  }
  return ret;
}

