const double pi = acos(-1.);
const ll inf = 1e10 + 7;
const ll inf2 = 1e18 + 7;
const int N = 3e5 + 17;

int n, m;
ll a[N];
int t[3000];
map<ll, int> cnt, cnto;
map<ll, ll> sqrs;
map<ll, pair<ll, ll>> fact;

int main() {
	ios::sync_with_stdio(0);
	cin.tie(0); cout.tie(0);
	for (int i = 2; i < 2200; i++)
		if (!t[i])
			for (int j = 2 * i; j < 2200; j += i)
				t[j] = 1;
	vi p;
	for (int i = 2; i < 2200; i++)
		if (!t[i]) p.pb(i);
	for (ll i = 2; i * i < inf; i++) sqrs[sqr(i)] = i;
	cin >> n;
	for (int i = 0; i < n; i++) cin >> a[i], cnto[a[i]]++;
	for (auto tmp: cnto) {
		auto x = tmp.fi;
		ll fi = 1, se = 1;
		for (auto d: p)
			if (x % d == 0) {
				int cur = 0;
				while (x % d == 0) {
				 	cur++;
				 	x /= d;
				}
				cur %= 3;
				if (cur == 1) fi *= d;
				if (cur == 2) se *= d;
			}
		if (sqrs.count(x)) se *= sqrs[x];
		else fi *= x;
		ll l = fi * sqr(se);
		if (l == 1) cnt[1] = 1;
		else {
			fact[l] = {fi, se};
			cnt[l] += tmp.se;
		}	
	}
	int ans = 0;
	for (auto q: cnt) {
		auto cur = q.fi;
		if (cur == 1) { ans += q.se; continue; }
		auto f = fact[cur];		
		if (f.fi < inf2 / (f.se * f.fi)) {
		    ll r = sqr(f.fi) * f.se;
			if (cnt.count(r)) {
				if (cur > r) ans += max(cnt[cur], cnt[r]);
			} else ans += cnt[cur];
		} else ans += cnt[cur];
	}
	cout << ans;
}

