#define FOR(i,a,b) for(int i=(a);i<(b);i++)
#define REP(i,a) FOR(i,0,a)

typedef long long ll;

const int MAX_N=1e5,MAX_SQRTS=3e3;
const ll MAX_S=1e10;

int N;
ll S[MAX_N];

bool pflg[MAX_SQRTS+1];
vector<ll> prime;

void sieve(){
	memset(pflg,true,sizeof(pflg));
	pflg[0]=pflg[1]=false;
	for (int i=2;i<=MAX_SQRTS;i++){
		if (!pflg[i]) continue;
		prime.push_back(i);
		for (int j=i*2;j<=MAX_SQRTS;j+=i){
			pflg[j]=false;
		}
	}
}

map<ll,int> mp;

int main(){
	scanf("%d",&N);
	REP(i,N){
		scanf("%lld",&S[i]);
	}
	sieve();
	REP(i,N){
		for(int j=0;j<prime.size();j++){
			ll p=prime[j];
			while(S[i]%(p*p*p)==0){
				S[i]/=p*p*p;
			}
		}
		mp[S[i]]++;
	}
	int ans=0;
	for(map<ll,int>::iterator ite=mp.begin();ite!=mp.end();ite++){
		if (ite->first==1){
			continue;
		}
		ll pa=ite->first*ite->first;
		for(int i=0;i<prime.size();i++){
			ll p=prime[i];
			while (pa%(p*p*p)==0){
				pa/=p*p*p;
			}
		}
		ans+=max<ll>(ite->second,mp[pa]);
		ite->second=0;
		mp[pa]=0;
	}
	if (mp[1]>0){
		ans++;
	}
	printf("%d\n",ans);
	return 0;
}

