            isP[j] = false;
    }
}

int getSqrt(long long x)
{
    long long l = 0, r = x;
    while (r - l > 1)
    {
        long long m = (l + r) / 2;
        if (m * m <= x)
            l = m;
        else
            r = m;
    }
    return l;
}

int main(int,  char **)
{
#ifdef LOCAL
