                if (k == 1)
                {
                    h1 ^= ph[i].first;
                    h2 ^= ph[i].second;
                }
                else if (k == 2)
                {
                    h1 ^= ph[i].second;
                    h2 ^= ph[i].first;
                }
            }
        }


        if (x != 1)
        {
//            eprintf("??\n");
