            if (pos != (int) ps.size() && ps[pos] == x)
            {
                h1 ^= ph[pos].first;
                h2 ^= ph[pos].second;
            }
            int sqrt = getSqrt(x);

            if (sqrt == -1)
            {    
                ans++;
                continue;
            }

            pos = lower_bound(ps.begin(), ps.end(), sqrt) - ps.begin();
            h1 ^= ph[pos].second;
            h2 ^= ph[pos].first;

        }

//        eprintf("%lld %lld\n", h1, h2);
        cnt[make_pair(h1, h2)]++;
