void init() {
    for (int i=2; i<maxn; i++) {
        if (!vis[i]) p[pCnt++]=i;
        for (int j=0; j<pCnt && p[j]*i<maxn; j++) {
            vis[i*p[j]]=1;
            if (i%p[j]==0) break;
        }
    }
