ll da1[maxn], da2[maxn];
void deal(int id) {
    ll ans1=1, ans2=1;
    ll tmp=da1[id];
    for (int i=0; p[i]*p[i]*p[i]<=tmp; i++) {
        int tot=0;
        while (tmp%p[i]==0) {
            tot++;
            tmp /= p[i];
        }
        tot%=3;
        if (tot==1) {
            ans1*=p[i];
            ans2*=p[i]*p[i];
        } else if (tot==2) {
            ans1*=p[i]*p[i];
            ans2*=p[i];
        }
    }
    ll sqrTmp=sqrt(tmp);
    if (sqrTmp*sqrTmp==tmp) {
        ans1*=tmp;
        ans2*=sqrTmp;
    } else {
        ans1*=tmp;
        ans2*=tmp*tmp;
    }
    da1[id]=ans1; da2[id]=ans2;
    cnt[ans1]++;
}
