void BF(){
	static bool vis[10000007]; vis[1] = 1;
	for(int i = 2 ; i <= M ; ++i)
		if(M % i == 0){
			int tms = P; while(!vis[tms]){vis[tms] = 1; tms = 1ll * tms * P % M;}
			for(int j = 1 ; j <= M / i ; ++j) vis[i * j] = 1;
			vector < int > ans; for(int i = 1 ; ans.size() < N && i < M ; ++i) if(!vis[i]) ans.push_back(i);
