/*
一个数是完全立方数的条件是 每个质因子的次数%3==0
先把输入里的完全立方数去掉并筛掉完全立方因子 得到s[i] 即原数l[i]
然后分解s[i]的 <= s[i]^{3}的质因数 算一下次数 计算s[i]的补数r[i]
*/
map<ll, int> cnt;
ll s[maxn], ans;
ll l[maxn], r[maxn];
int main() {
    n = read();
    for (int i = 1; i <= n; i++) {
        s[i] = read();
        for (ll j = 2; j * j * j <= s[i] ; j++){
            while (s[i] % (j * j * j) == 0) {
                s[i] /= (j * j * j);//相当于把所有质因子的次数%3
            }
        } 
        cnt[s[i]]++;
        l[i] = s[i];
        ll tmp = 1;
        for (ll j = 2; j * j * j <= s[i]; j++) {//计算补数tmp
            if (s[i] % j == 0) {
                if (s[i] % (j * j) == 0) tmp *= j;
                else tmp *= (j * j);
                //printf("s[i] == %lld tmp == %lld\n", s[i], tmp);
            }
            while (s[i] % j == 0) s[i] /= j;
        }
        // 剩下一个可能是一个较大的质因数或是一个较大质因数的平方 讨论一哈
        ll t = (ll)sqrt(s[i]);
        if (t * t == s[i]) {
            tmp *= t; //    s[i]被筛剩下一个质因数的平方 
        } else {
            tmp *= s[i] * s[i]; //s[i]是剩下的一个大质数
        }
        //这样筛完以后
        //补数即为tmp
        r[i] = tmp; 
    }
    if (cnt[1]) ans++, cnt[1] = 0;
    for (int i = 1; i <= n; i++) {
        ans += Max(cnt[l[i]], cnt[r[i]]);
        //printf("cnt[l[%d]==%lld] == %lld cnt[r[%d]==%lld] == %lld\n", i, l[i], cnt[l[i]], i, r[i], cnt[r[i]]);
        cnt[l[i]] = cnt[r[i]] = 0;
    }
    //ans += (cnt[1] > 0);
    printf("%lld\n", ans);
    return 0;
}

