const int N = 1e5 + 10;

map<ll, int> cnt;
int p[N];
int vis[N];
ll p2[N], lis[N];
Pr rec[N];
int n, m, cntp, cntpair, ans;

void prework(int n) {
  cntp = 0;
  vis[1] = 1;
  for (int i = 2; i <= n; ++i) {
    if (!vis[i]) p[++cntp] = i, p2[cntp] = 1LL * i * i;
    for (int j = 1; j <= cntp && i * p[j] <= n; ++j) {
      vis[i * p[j]] = 1;
      if (i % p[j] == 0) break;
    }
  }
}

void print(Pr x) { printf("(%lld,%lld)\n", x.first, x.second); }
void work(ll val) {
  int tmp = 0;
  ll nwval = 1, need = 1;
  for (int i = 1; p2[i] * p[i] <= val; ++i) {
    if (val % p[i]) continue;
    tmp = 0;
    while (val % p[i] == 0) tmp = (tmp + 1) % 3, val /= p[i];
    if (tmp == 0)
      continue;
    else if (tmp == 1)
      need *= p2[i], nwval *= p[i];
    else
      need *= p[i], nwval *= p2[i];
  }
  nwval *= val;
  if (val > 1) {
    ll ttmp = sqrt(val);
    if (ttmp * ttmp == val)
      need *= ttmp;
    else
      need *= val * val;
  }
  ++cnt[nwval];
  if (nwval > need)
    rec[++cntpair] = mp(need, nwval);
  else
    rec[++cntpair] = mp(nwval, need);
}

int main() {
  ll val;
  scanf("%d", &n);
  prework(1e5), cnt.clear();
  lis[0] = cntpair = 0;
  for (int i = 1; i <= n; ++i) scanf("%lld", &val), work(val);
  sort(rec + 1, rec + 1 + cntpair);
  cntpair = unique(rec + 1, rec + 1 + cntpair) - rec - 1;
  ans = 0;
  for (int i = 1; i <= cntpair; ++i)
    if (rec[i].first == 1 && rec[i].second == 1)
      ans += 1;
    else
      ans += max(cnt[rec[i].first], cnt[rec[i].second]);
  printf("%d\n", ans);
}

