map<LL, LL> mp, cont, sqr;

void seive() {
	ntpri[1] = 1, cnt = 0;
	rep (i, 2, V) {
		if (!ntpri[i]) {
			pri[++cnt] = i;
			mnp[i] = i;
			sqr[1LL * i * i] = i;
		}
		rep (j, 1, cnt) {
			if (1LL * i * pri[j] > V) break;
			int t = i * pri[j];
			ntpri[t] = 1;
			if (i % pri[j] == 0) {
				mnp[t] = mnp[i];
				break;
			}
			else mnp[t] = pri[j];
		}
	}
}

void gao(LL x) {
	++ m; b[m] = c[m] = 1;
	rep (i, 1, cnt) {
		if (pri[i] > Lim) break;
		LL p = pri[i], cc = 0;
		while (x % p == 0) ++ cc, x /= p;
		cc %= 3;
		if (cc == 0) continue;
		rep (j, 1, cc) b[m] *= p;
		rep (j, 1, 3 - cc) c[m] *= p;
	}
	if (sqr[x]) b[m] *= x, c[m] *= sqr[x];
	else b[m] *= x, c[m] *= x * x;
}

