struct Prime{
  vector<ll> pl;
  void init(int a){ // a以下の素数列挙
    pl.resize(0);
    vector<bool> z(a+1, true);
    for(int i=2; i<=a; i++){
      if(z[i])pl.push_back(i);
      for(int b=i*2; b <= a; b+=i) z[b]=false;
    }
  }
  void prime_division(ll a, vector<pair<ll, int>> &v){
    v.resize(0);
    for(ll b: pl){
      if(b*b > a) break;
      if(a%b) continue;
      int c = 0;
      while(a%b==0) a/=b, c++;
      c %= 3;
      if(c) v.push_back(make_pair(b, c));
    }
    if(a>1){
      ll b = (ll)round(sqrt((double)a));
      if(b*b == a){
        v.push_back(make_pair(b, 2));
      }else{
        v.push_back(make_pair(a, 1));
      }
    }
  }
} prime;

int n;
map<lll, int> c;
map<lll, vector<pair<ll, int>>> m;
lll inv(vector<pair<ll, int>> &v){
  lll s = 1;
  each(itr, v) FOR(i, 0, 3-itr->se) s *= itr->fi;
  return s;
}
main(){
  cin.tie(0);
  ios::sync_with_stdio(false);
  cin >> n;
  prime.init(N);
  FOR(t, 0, n){
    ll s;
    cin >> s;
    vector<pair<ll, int>> v;
    prime.prime_division(s, v);
    s = 1;
    each(itr, v) FOR(i, 0, itr->se) s *= itr->fi;
    if(m.find(s) == m.end()) m[s] = v;
    c[s]++;
  }
  ll ans = 0;
  each(itr, m){
    lll s = itr->fi, t = inv(itr->se);
    if(s==1){
      ans++;
      continue;
    }
    if(m.find(t) == m.end()){
      ans += c[s];
    }else{
      ans += max(c[s], c[t]);
      m.erase(t);
    }
  }
  cout << ans << endl;
}

#include <bits/stdc++.h>
#define maxn 100010
#define ll long long
using namespace std;

int prime[maxn],check[maxn],tot,n;

ll p1[maxn],p2[maxn],ans;

map <ll,int> s,vis;

void init(){
    check[1]=1;
    for(int i=2;i<=2200;i++){
        if(!check[i]) prime[++tot]=i;
        for(int j=1;j<=tot&&prime[j]*i<=2200;j++){
            check[prime[j]*i]=1;
            if(i%prime[j]==0) break;
        }
    }
}

int main(){
    init();
    scanf("%d",&n);
    for(int cnt=1;cnt<=n;cnt++){
        ll x,a=1,b=1;
        scanf("%lld",&x);
        for(int i=1;i<=tot;i++){
            int sum=0;
            if(prime[i]>x) break;
            if(x%prime[i]!=0) continue;
            while(x%prime[i]==0) x/=prime[i],sum++;
            sum%=3;
            if(sum==0) continue;
            for(int j=1;j<=sum;j++) a*=prime[i];
            for(int j=sum+1;j<=3;j++) b*=prime[i];
        }
        ll tmp=1ll*sqrt(x);
        if(tmp*tmp==x) a*=tmp*tmp,b*=tmp;
        else a*=tmp,b*=tmp*tmp;
        p1[cnt]=a;p2[cnt]=b;
        s[a]++;
    }
    for(int i=1;i<=n;i++){
        ll x;
        if(vis[p1[i]]||vis[p2[i]]) continue;
        if(s[p1[i]]>s[p2[i]])  x=p1[i];
        else x=p2[i];
        vis[x]=1;
        if(x==1) ans++;
        else ans+=s[x];
    }
    printf("%lld",ans);
    return 0;
}

