		ull norm = 1, pair = 1;
		for (auto f : fac) {
			int n = f.first;
			int c = f.second % 3;
			if (c == 1) {
				norm *= n;
				pair *= n*n;
			}
			else if (c == 2) {
				norm *= n*n;
				pair *= n;
			}
		}
		if (norm == 1) res = 1;
		else {
			if (norm < pair) cnt[norm].first++;
			else cnt[pair].second++;
		}
	}

	for (auto c : cnt) {
		res += max(c.second.first, c.second.second);
	}

