#include <cstdio>
#include <map>
#include <cmath>
const int P = 2154, V = 325;
int N, m[P + 1], pr[V + 1], v, O;
std::map < long long, int > MAP;
int main()
{
	for (int i = 2; i <= P; i++)
	{
		if (!m[i])
			m[i] = pr[++v] = i;
		for (int j = 1; j <= v && pr[j] * i <= P && pr[j] <= m[i]; j++)
			m[pr[j] * i] = pr[j];
	}
	scanf("%d", &N);
	for (int i = 1; i <= N; i++)
	{
		long long x;
		scanf("%lld", &x);
		for (int j = 1; j <= v; j++)
			while (x % (pr[j] * pr[j] * pr[j]) == 0)
				x /= pr[j] * pr[j] * pr[j];
		if (x == 1)
			O = 1;
		else
			MAP[x]++;
	}
	for (auto i : MAP)
	{
		long long tmp = i.first;
		static long long got[100];
		static int cnt[100];
		int D = 0;
		for (int j = 1; j <= v; j++)
			if (tmp % pr[j] == 0)
			{
				got[++D] = pr[j];
				cnt[D] = 0;
				do
				{
					cnt[D]++;
					tmp /= pr[j];
				}
				while (tmp % pr[j] == 0);
			}
		long long rest = sqrt(tmp) + 0.01;
		if (tmp > 1 && rest * rest == tmp)
		{
			got[++D] = rest;
			cnt[D] = 2;
		}
		long long Even = 1;
		for (int i = 1; i <= D; i++)
			if (cnt[i] == 2)
				Even *= got[i];
		long long Odd = i.first / Even / Even;
		long long Partner = Odd * Even;
		if (Partner <= 10000000000LL / Odd)
			Partner *= Odd;
		else
			Partner = 10000000001LL;
		auto partner = MAP.find(Partner);
		if (partner == MAP.end())
			O += i.second;
		else
		{
			O += std::max(i.second, partner -> second);
			MAP.erase(partner);
		}
	}
	printf("%d\n", O);
	return 0;
}

