bigint reduce(bigint x)
{
    for(auto& it: pcube)
        while(x%it==0)
            x/=it;
    return x;
}

int main()
{
    for(int i=2; i<=10000; i++)
        pr[i]=true;
    for(int i=2; i<=10000; i++) if(pr[i])
    {
        if(1LL*i*i*i<=20000000000LL)
