		cnt[now]++;hs[i]=now;
		a[i][0]=tot;
		for (int j=1;j<=tot;j++) a[i][j]=ans[j];
	}
	int res=0;
	bool flag=false;
	for (int i=1;i<=n;i++)
	{
		if (bo[hs[i]]) continue;
		bo[hs[i]]=true;
		if (!hs[i]) { flag=true;continue; }
		tot=a[i][0];
		for (int j=1;j<=tot;j++) ans[j]=a[i][j];ans[tot+1]=-1;
		ull now=0;
		for (int j=1;j<=tot;)
		{
			int k=j;
			for (;ans[k]==ans[j];k++);k--;
			int hh=(k-j+1)%3;
			if (hh==0) hh=0;
			else if (hh==1) hh=2;
			else hh=1;
			now+=(ull)bin[mp[ans[j]]]*(ull)hh;
			j=k+1;
		}
		bo[now]=true;
		if (cnt[hs[i]]>cnt[now]) res+=cnt[hs[i]];
		else if (cnt[hs[i]]==cnt[now]) res+=cnt[hs[i]];
		else res+=cnt[now];
	}
	printf("%d\n",(int)(res+0.3)+flag);
	return 0;
}

