int power(int x, int n, int p) {
	int res = 1;
	while (n > 0) {
		if (n & 1) res = (res * x) % p;
		x = (x * x) % p;
		n /= 2;
	}
	return res;
}

int power(int x, int n) {
	int res = 1;
	while (n > 0) {
		if (n & 1) res = (res * x);
		x = (x * x);
		n /= 2;
	}
	return res;
}

