using namespace std;
using P = pair<long, long>;
using VI = vector<long>;

using VP = vector<P>;

long getminp(long p) {
    if (p % 2 == 0) return 2;
    for (long i = 3; i * i <= p; i += 2) {
        if (p % i == 0) return i;
    }
    return p;
}

VP fctr(long s) {
    VP v;
    while (s != 1) {
        long p = getminp(s);
        long cnt = 0;
        while (s % p == 0) {
            s /= p;
            cnt++;
        }
        if (cnt % 3) {
            v.push_back(P(p, cnt % 3));
        }
    }
    return v;
}

bool safe(map<VP, long> *m, VP *f) {
    VP v;
    for (P a: *f) {
        v.push_back(P(a.first, (3 - a.second) % 3));
    }
    return (*m)[v] == 0;
}

