		for (int j = 2; j < cube.size();j++) {
			while (i%cube[j] == 0)i /= cube[j];
		}
		if (i == 1) {
			flag = true;
			continue;
		}
		m[i]++;
	}
	vector<int>prime(100001);
	for (auto i : P)prime[i] = 1;
	int ans = 0;
	for (auto i : m) {
		vector<long long int>box;
		unsigned long long int bag = i.first;
		for (auto j : P) {
			if (bag < j*j) {
				if (bag >= 100000)break;
				if (prime[bag]) {
					box.push_back(bag);
					bag = 1;
				}
				break;
			}
			if (bag%j == 0) {
				box.push_back(j);
				bag /= j;
			}
			if (bag%j == 0) {
				bag /= j;
			}
			if (bag == 1)break;
		}
		if (bag > 1) {
			ans += i.second;
			continue;
		}
		unsigned long long int num = 1;
		for (auto j : box) {
			num *= j;
			if (num > 10000000000)break;
			if (i.first % (j*j)) {
				num *= j;
				if (num > 10000000000)break;
			}
		}
		if (num < i.first)continue;
		if (m.find(num) == m.end())ans += i.second;
		else ans += max(i.second, m[num]);
	}
