#include <bits/stdc++.h>

#define MAXN 100005

typedef long long lint;
typedef unsigned long long ulint;

using namespace std;

const int H = 13331;
const int N = 100000;
int n, total, ans;
int prime[MAXN], v[MAXN];
bool visit[MAXN];
lint a[MAXN], c[MAXN];
ulint HASH[MAXN];
map<pair<ulint, ulint>, int> record;

lint read() {
    char c = getchar();
    lint x = 0;
    while (!isdigit(c))
        c = getchar();
    while (isdigit(c)) {
        x = (x << 3) + (x << 1) + c - '0';
        c = getchar();
    }
    return x;
}

void sieve() {
    for (int i = 2; i <= N; ++i) {
        if (!v[i])
            prime[++total] = i;
        for (int j = 1; j <= total && i * prime[j] <= N; ++j) {
            v[i * prime[j]] = 1;
            if (i % prime[j] == 0)
                break;
        }
    }
    HASH[0] = 1;
    for (int i = 1; i <= total; ++i)
        HASH[i] = HASH[i - 1] * H;
}

void divide(lint& x) {
    ulint h1 = 0, h2 = 0;
    for (int i = 1; i <= total && prime[i] <= x; ++i)
        if (x % prime[i] == 0) {
            int sum = 0;
            while (x % prime[i] == 0) {
                x /= prime[i];
                ++sum;
            }
            h1 += (sum % 3 == 1) * HASH[i];
            h2 += (sum % 3 == 2) * HASH[i];
        }
    if (x != 1)
        ++ans;
    else if (!record[make_pair(h2, h1)]) {
        ++ans;
        record[make_pair(h1, h2)] = true;
    }
}

int main() {
    sieve();
    n = (int)read();
    for (int i = 1; i <= n; ++i)
        divide(a[i] = read());
    printf("%d\n", ans);
}

