pr now[15];

pr calc(int n) {
  ull s1=0,s2=0;
  for(int i=1;i<=n;i++)
    if (now[i].SE%3) {
    	now[i].SE%=3;
    	s1^=getrd(now[i].FR*now[i].SE);
    	s2^=getrd(now[i].FR*(3-now[i].SE));
	}
  return pr(s1,s2);
}

