					break;
				}
				if (num % (p * p) == 0) {
					other *= p;
					if (other > INF) {
						other = INF;
					}
					num /= p;
					num /= p;
				}
				else if (num % p == 0) {
					other *= p;
					if (other > INF) {
						other = INF;
					}
					other *= p;
					if (other > INF) {
						other = INF;
					}
					num /= p;
