map<pair<ll, ll>, int> val;

void prework(void) {
  for(int i = 2; i < N; i++) {
    if(!mark[i]) {
      pri[++pcnt] = i;
    }
    for(int j = 1; j <= pcnt && i * pri[j] < N; j++) {
      mark[i * pri[j]] = true;
      if(i % pri[j] == 0) {
	break;
      }
    }
  }
}

void defact(ll x, int y) {
  ll ax = 1, ay = 1;
  for(int i = 1; i <= pcnt && pri[i] <= x; i++) {
    if(x % pri[i] == 0) {
      int cnt = 0;
      while(x % pri[i] == 0) {
	x /= pri[i];
	cnt++;
      }
      if(cnt % 3 == 1) {
	ax = ax * pri[i];
      } else if(cnt % 3 == 2) {
	ay = ay * pri[i];
      }
    }
  }
  if(x > 1) {
    realans++;
  } else if(ax == 1 && ay == 1) {
    realans += !mark[1];
    mark[1] = true;
  } else {
    val[{ax, ay}] += y;
    if(val.find({ay, ax}) == val.end()) {
      val[{ay, ax}] = 0;
    }
  }
}

