typedef long long in;
typedef vector<in> VI;
typedef vector<VI> VVI;
struct rpr{
  in x,y;
  rpr(in a=0, in b=0){
    x=a;
    y=b;
  }
  rpr sp()const{
    return rpr(y,x);
  }
  bool operator<(const rpr cp)const{
    if(x!=cp.x)
      return x<cp.x;
    return y<cp.y;
  }
};
const in ulm=in(1e10)+9;
const in crt=2500;
in sm=0;
map<rpr,in> mp;
void pr(in n){
  VI pm,pw;
  for(in i=2;i<=crt && i<=n;++i){
    if(n%i)
      continue;
    pm.PB(i);
    pw.PB(0);
    while(n%i==0){
      n/=i;
      ++pw.back();
    }
    pw.back()%=3;
  }
  if(n!=1 && n<crt*crt){
    pm.PB(n);
    pw.PB(1);
    n=1;
  }
  if(n>=crt*crt){
    in mn=crt-1;
    in mx=1e6;
    in md;
    while(mx-mn>1){
      md=(mx+mn)/2;
      if(md*md<=n)
	mn=md;
      else
	mx=md;
    }
    if(mn*mn!=n){
      ++sm;
      return;
    }
    pm.PB(mn);
    pw.PB(2);
    n=1;
  }
  in tx=1;
  in ty=1;
  forv(i,pm){
    forn(j,pw[i])
      tx*=pm[i];
    forn(j,(3-pw[i])%3){
      ty*=pm[i];
      if(ty>ulm){
	++sm;
	return;
      }
    }
  }
  ++mp[rpr(tx,ty)];
  mp[rpr(ty,tx)];
}
