  cin.tie(0);
  in n;
  cin>>n;
  in s;
  forn(i,n){
    cin>>s;
    pr(s);
  }
  in t=0;
  fors(i,mp){
    if(i->first.x==1)
      ++sm;
    else
      t+=max(i->second,mp[i->first.sp()]);
  }
  sm+=t/2;
  cout<<sm<<endl;
  return 0;
}

