const int MAX_PR = 300010;
// looking for all prime numbers
bool not_prime[MAX_PR];

map<LL, LL> prsquare;

vector<LL> a;

map<LL, pair<LL, int> > have;

int main() {	
	vector<LL> primes;
	primes.clear();
	SET(not_prime, 0);
	ffor (i, 2, MAX_PR)
		if (!not_prime[i]){
	    primes.pb(i);
			for (int j = 2 * i; j < MAX_PR; j += i)
				not_prime[j] = true;
	  }
	FOR (i, primes.sz)
		prsquare.insert(make_pair(1LL * primes[i] * primes[i], primes[i]));

	int n;
	cin >> n;
	FOR (i, n) {
		LL b;
		cin >> b;
		LL comp = 1LL;
		LL newb = 1LL;
		int idx = 0;
		while (primes[idx] <= 3333 && 1LL * primes[idx] * primes[idx] <= b) {
			int cnt = 0;
			while (b % primes[idx] == 0) {
				cnt++;
				b /= primes[idx];
			}
			cnt %= 3;
			FOR (j, cnt)
				newb *= primes[idx];
			FOR (j, (3 - cnt) % 3) {
				if (comp < 100000000000LL)
					comp *= primes[idx];
			}
			idx++;
		}
		newb *= b;
		if (prsquare.find(b) != prsquare.end()) {
			if (comp < 1000000000LL)
				comp *= prsquare[b];
			else
				comp = 100000000000LL;
		}
		else if (b < MAX_PR && !not_prime[b]) {
			FOR (j, 2)
				if (comp < 100000000000LL)
					comp *= b;
		}
		else
			comp = 100000000000LL;
		if (have.find(newb) != have.end()) {
			if (newb != 1) {
				pair<LL, int> pp = have[newb];
				have[newb] = make_pair(pp.first, pp.second + 1);
			}
		}
		else {
			have.insert(make_pair(newb, make_pair(comp, 1)));
			a.pb(newb);
		}
	}
	int cnt = 0;
	FOR (i, a.sz) {
		pair<LL, int> pp = have[a[i]];
		if (!pp.second)
			continue;
		if (have.find(pp.first) != have.end()) {
			pair<LL, int> pp1 = have[pp.first];
			cnt += max(pp.second, pp1.second);
			have[pp.first] = make_pair(pp1.first, 0);
		}
		else
			cnt += pp.second;
	}
	cout << cnt << endl;
	return 0;
}

