long long a[121212], L[2154], ln, ck[121212],P[121212], pn, cnt[121212];
map<long long, int>Q;
long long GT(long long x) {
	vector<int>L;
	long long res = 1;
	for(int i=0;i<pn&&P[i]<=x;i++) while (x%P[i] == 0)x /= P[i], L.push_back(P[i]);
	if (x > 1)return -1;
	for (int i = 0; i < L.size(); i++) {
		if (i + 1 < L.size() && L[i] == L[i + 1])res *= L[i], i++;
		else res *= L[i] * L[i];
	}
	return res;
}
int main() {
	long long n, i, j, ans=0;
	for (i = 1; i*i*i <= 1e10; i++)L[ln++] = i*i*i;
	for (i = 2; i*i <= 1e5; i++) if (!ck[i]) {
		for (j = i*i; j <= 1e5; j += i)ck[j] = 1;
	}
	for (i = 2; i <= 1e5; i++)if(!ck[i])P[pn++] = i;
	scanf("%lld", &n);
	for (i = 0; i < n; i++) {
		scanf("%lld", &a[i]);
		for (j = 1; j < ln; j++) {
			while (a[i] % L[j] == 0)a[i] /= L[j];
		}
		Q[a[i]] = Q[a[i]] + 1;
	}
	for (i = 0; i < n; i++) {
		if (Q.find(a[i]) == Q.end())continue;
		if (a[i] == 1) { ans++; Q.erase(1); continue; }
		long long gt = GT(a[i]);
		if(Q.find(gt)!=Q.end()) ans += max(Q[a[i]], Q[gt]), Q.erase(gt);
		else ans += Q[a[i]];
		Q.erase(a[i]);
	}
	printf("%lld", ans);
	return 0;
}

