ll get_norm(ll num){
  for(int i=0;i<cube_prime.size();i++){
    while((num%cube_prime[i])==0) num/=cube_prime[i];
  }
  return num;
}

int main(){
  int n;
  cin>>n;
  vector<ll> a(n);
  for(int i=0;i<n;i++){
    long long int buf;
    cin>>buf;
    a[i]=buf;
  }

  while(cubed_s*cubed_s*cubed_s<=MAX_S) cubed_s++;
  cubed_s=1e4;
  vector<int> is_prime(cubed_s+1,1);
  is_prime[0]=is_prime[1]=0;
  for(int i=0;i<=cubed_s;i++){
    if(is_prime[i]){
      prime.push_back(i);
      for(int j=2*i;j<=cubed_s;j+=i){
	is_prime[j]=false;
      }
    }
  }
  cube_prime.resize(prime.size());
  for(int i=0;i<prime.size();i++){
    cube_prime[i]=prime[i]*prime[i]*prime[i];
  }
  vector<ll> norm(n);
  for(int i=0;i<n;i++){
    norm[i]=get_norm(a[i]);
  }

  vector<ll> couple(n);
  for(int i=0;i<n;i++){
    couple[i]=get_norm(a[i]*a[i]);
  }

  set<ll> checked;
  long long int res=0;
  map<ll,long long int> norm_cnt;


  for(int i=0;i<n;i++){
    norm_cnt[norm[i]]++;
  }

  for(int i=0;i<n;i++){
    if(checked.count(norm[i])) continue;
    if(norm[i]==1){
      res++;
      checked.insert(1);
    }
