typedef long long LL;
const int S = 2155;
const int N = 1e5 + 10;
struct data {
	int cnt; LL val;
	data(int _cnt = 0, LL _val = 0) {cnt = _cnt, val = _val;}
};
int n, ans, tot, top, is[S], pri[N]; LL a[N]; map <LL, data> mp;

inline int max(int a, int b) {return a > b ? a : b;}
inline int min(int a, int b) {return a < b ? a : b;}
template <class T> inline void in(T &x) {
	x = 0; int f = 1; char ch = getchar();
	for (; ch<'0' || ch>'9';) {if (ch=='-') f=-1; ch = getchar();}
	for (; ch>='0' && ch<='9';) x = x*10 + (LL)ch-'0', ch = getchar();
	x *= f;
}

inline void init(int n) {
	for (int i = 2; i <= n; ++i) {
		if (!is[i]) pri[++tot] = i;
		for (int j = 1; j <= tot && i * pri[j] <= n; ++j) {
			is[i * pri[j]] = 1;
			if (i % pri[j] == 0) break;
		}
	}
}

int main() {
	int p, cnt; LL x, g, x1, x2;
	in(n), init(S - 1);
	for (int i = 1; i <= n; ++i) {
		in(x), x1 = x2 = 1;
		for (int i = 1; i <= tot; ++i) {
			p = pri[i];
			if (x % p) continue;
			for (cnt = 0; x % p == 0;) x /= p, ++cnt;
			cnt %= 3;
			if (!cnt) continue;
			if (cnt == 1) x1 *= p, x2 *= p * p;
			else x1 *= p * p, x2 *= p;
		}
		if (x > 1) {
			x1 *= x;
			g = sqrtl(x);
			if (g * g == x) x2 *= g;
			else {
				if (x > 100000) {++ans; continue;}
				x2 *= x * x;
			}
		}
		if (mp.count(a[++top] = x1)) ++mp[x1].cnt;
		else mp[x1] = data(1, x2);
	}
	sort(a + 1, a + top + 1);
	n = unique(a + 1, a + top + 1) - a - 1;
	for (int i = 1; i <= n; ++i) {
		x1 = a[i], x2 = mp[x1].val;
		if (x1 == x2) {++ans; continue;}
		if (x2 < x1) {
			if (mp.count(x2)) continue;
			ans += mp[x1].cnt;
		} else {
			if (!mp.count(x2)) ans += mp[x1].cnt;
			else ans += max(mp[x1].cnt, mp[x2].cnt);
		}
	}
	printf("%d\n", ans);
	return 0;
}

