int n,m,cntp,cntpair,ans;
void prework(int n){
	cntp=0;	
	vis[1]=1;
	for (int i=2;i<=n;++i){
		if (!vis[i])
			p[++cntp]=i,p2[cntp]=1LL*i*i;
		for (int j=1;j<=cntp&&i*p[j]<=n;++j){
			vis[i*p[j]]=1;
			if (i%p[j]==0) break;
		}
	}
