void print(Pr x){
	printf("(%lld,%lld)\n",x.first,x.second);
}
void work(ll val){
	int tmp=0;
	//if (val==1) return;
	ll nwval=1,need=1;
	for (int i=1;p2[i]*p[i]<=val;++i){
		if (val%p[i]) continue;
		tmp=0;
		while (val%p[i]==0) tmp=(tmp+1)%3,val/=p[i];
		if (tmp==0) continue;
		else if (tmp==1) need*=p2[i],nwval*=p[i];
		else need*=p[i],nwval*=p2[i];
	}
	nwval*=val;
	//if (nwval==1) return;
	if (val>1){
		ll ttmp=sqrt(val);
		if (ttmp*ttmp==val)
			need*=ttmp;
		else
			need*=val*val;
	}
	++cnt[nwval];
	//print(mp(nwval,need));
	if (nwval>need) rec[++cntpair]=mp(need,nwval);
	else rec[++cntpair]=mp(nwval,need);
}

