	tmp.X=tmp.Y=1;
	for(int i=1;i<=pcnt;i++)
	if(x%pri[i]==0){
		x/=pri[i];
		if(x%pri[i]==0)
		tmp.X*=pri[i]*pri[i],tmp.Y*=pri[i],x/=pri[i];
		else tmp.X*=pri[i],tmp.Y*=pri[i]*pri[i];
	}
	return x;
}
