int n;
lint ar[100005];

int prm[3005],pcnt;

bool isprm(int a){
  for(int i=2;i*i<=a;++i) if(a%i==0) return false;
  return true;
}
typedef vector<pi> vp;
vp flip(const vp& a){
  vp res(a.size());
  REP(i,a.size()){
    res[i]=mp(a[i].fr,3-a[i].sc);
  }
  return res;
}

int main(){
  cin>>n;
  REP(i,n) scanf("%lld",&ar[i]);

  for(int i=2;i<=3333;++i) if(isprm(i)) prm[pcnt++]=i;

  int res=0;
  map<vp,int> app;
  REP(i,n){
    lint x=ar[i];
    vp fct;
    for(int j=0;j<pcnt && prm[j]<=x;++j) if(x%prm[j]==0){
      int cnt=0;
      while(x%prm[j]==0) x/=prm[j],++cnt;
      cnt%=3;
      if(cnt) fct.pb(mp(prm[j],cnt));
    }
    if(x>1){
      lint s=sqrt((double)x)+0.5;
      if(s*s==x || (s+1)*(s+1)==x || (s-1)*(s-1)==x) fct.pb(mp(s,2));
      else if(x<=100000 && isprm(x)) fct.pb(mp(x,1));
      else{
        ++res;
        continue;
      }
    }
    app[fct]++;
  }
  for(auto& e:app){
    vp f=flip(e.fr);
    if(f.empty()) ++res;
    else if(app.count(f)){
      if(f[0].sc==1){
        res+=max(app[f],e.sc);
      }
    }else res+=e.sc;
  }
  cout<<res<<endl;
  return 0;
}

