#include <bits/stdc++.h>
using namespace std;
bool is_cube(long long N){
  long long c = (long long) (cbrt(N) + 0.001);
  return (c * c * c == N) || ((c + 1) * (c + 1) * (c + 1) == N) || ((c - 1) * (c - 1) * (c - 1) == N);
}
long long is_square(long long N){
  long long c = (long long) (sqrt(N) + 0.001);
  if (c * c == N){
    return c;
  } else if ((c + 1) * (c + 1) == N){
    return c + 1;
  } else if ((c - 1) * (c - 1) == N){
    return c - 1;
  } else {
    return -1;
  }
}
int main(){
  int N;
  cin >> N;
  vector<long long> s(N);
  for (int i = 0; i < N; i++){
    cin >> s[i];
  }
  int cnt = 0;
  vector<long long> t;
  for (int i = 0; i < N; i++){
    if (is_cube(s[i])){
      cnt++;
    } else {
      t.push_back(s[i]);
    }
  }
  int ans = 0;
  if (cnt >= 1){
    ans++;
  }
  map<long long, int> A;
  map<long long, int> B;
  map<pair<long long, long long>, int> C;
  int M = t.size();
  for (int i = 0; i < M; i++){
    long long t2 = t[i];
    for (long long j = 2; j * j * j <= t[i]; j++){
      if (t2 % (j * j * j) == 0){
        t2 /= j * j * j;
      }
    }
    t[i] = t2;
    long long c = is_square(t[i]);
    if (c != -1){
      B[c]++;
    } else {
      bool is_C = false;
      for (long long j = 2; j * j * j <= t[i]; j++){
        if (t[i] % j == 0 && is_square(j) == -1 && is_square(t[i] / j) != -1){
          C[make_pair(is_square(t[i] / j), j)]++;
          is_C = true;
          break;
        }
        if (t[i] % (j * j) == 0 && is_square(t[i] / (j * j)) == -1){
          assert(t[i] % (j * j * j) != 0);
          C[make_pair(j, t[i] / (j * j))]++;
          is_C = true;
          break;
        }
      }
      if (!is_C){
        A[t[i]]++;
      }
    }
  }
  set<long long> val;
  for (auto P : A){
    val.insert(P.first);
  }
  for (auto P : B){
    val.insert(P.first);
  }
  for (long long x : val){
    ans += max(A[x], B[x]);
  }
  set<pair<long long, long long>> val2;
  for (auto P : C){
    long long x = P.first.first;
    long long y = P.first.second;
    assert(x != y);
    val2.insert(make_pair(min(x, y), max(x, y)));
  }
  for (auto P : val2){
    long long x = P.first;
    long long y = P.second;
    ans += max(C[make_pair(x, y)], C[make_pair(y, x)]);
  }
  cout << ans << endl;
}

