#define LL long long

inline LL read(){
	LL x=0,f=1;char c=getchar();
	for(;!isdigit(c);c=getchar()) if(c=='-') f=-1;
	for(;isdigit(c);c=getchar()) x=x*10+c-'0';
	return x*f;
}
const LL INF=9999999;
const LL MAXN=200010;

LL N; LL a[MAXN+1]; 
LL pri[MAXN+1]; bool vis[MAXN+1];
vector<pair<LL,LL> > vec[MAXN+1];
LL cnt;

inline void init(){
	for(LL i=2;i<=1000;i++){
		if(!vis[i]) vis[i]=true,pri[++cnt]=i;
		for(LL j=1;j<=cnt&&1LL*pri[j]*i<=1000;j++){
			vis[i*pri[j]]=1;
			if(i%pri[j]==0) break;
		}
	} return ;
} LL s;
inline bool cmp(vector<pair<LL,LL> > a,vector<pair<LL,LL> > b){
	LL tmp1=1,tmp2=1;
	for(LL i=0;i<a.size();i++){
		for(LL j=1;j<=a[i].second;j++) tmp1*=a[i].first;
	}
	for(LL i=0;i<b.size();i++){
		for(LL j=1;j<=b[i].second;j++) tmp2*=b[i].first;
	} return tmp1<tmp2;
} LL ans=0;
inline LL calc(LL r){
	LL tmp=1;
	for(LL i=0;i<vec[r].size();i++){
		for(LL j=1;j<=vec[r][i].second;j++) tmp*=vec[r][i].first;
	} return tmp;
}
inline bool same(LL l,LL r){
	return calc(r)==calc(l);
}
inline LL calc_out(LL r){
	LL tmp=1;
	for(LL i=0;i<vec[r].size();i++){
		if(vec[r][i].second!=0)
			for(LL j=1;j<=3-vec[r][i].second;j++) tmp*=vec[r][i].first;
	} return tmp;
} LL col[MAXN+1],sz[MAXN+1],sg[MAXN+1];
inline bool isprime(LL x){
	for(int i=pri[cnt];1LL*i*i<=x;i++){
		if(x%i==0) return false;
	} return true;
}

int main(){
	//freopen("x.in","r",stdin);
	//freopen("x.out","w",stdout);
	N=read(); init(); bool flag=false;
	for(LL i=1;i<=N;i++) a[i]=read();
	memset(vis,false,sizeof(vis));
	//cout<<cnt<<endl;
	for(LL j=1;j<=N;j++){
		LL x=cbrt(a[j]);
		if(x*x*x==a[j]) {if(!flag) ++ans;flag=true; continue;}
		++s;  //cout<<j<<endl;
		for(LL i=1;i<=cnt;i++){
			LL tmp=0;
			while(a[j]%pri[i]==0){
				a[j]/=pri[i];
				++tmp;
			} if(tmp) vec[s].push_back(make_pair(pri[i],tmp%3));
		}if(a[j]!=1) {
			x=sqrt(a[j]);
			if(x*x==a[j]) vec[s].push_back(make_pair(x,2));
			//else if(a[j]*a[j]<=1e5&&isprime(a[j])) vec[s].push_back(make_pair(a[j],1)); 
			else ans++,vec[s].clear(),s--;
		}
	} //cout<<"true"<<endl;
	sort(vec+1,vec+1+s,cmp); LL tim=0;
	for(LL i=1,r=1;i<=s;i=r+1){
		r=i; col[i]=++tim; ++sz[tim];
		while(r+1<=s&&same(r+1,i)) ++r,col[r]=tim,++sz[tim];
		sg[tim]=calc(r); LL num=calc_out(r);
		LL x=lower_bound(sg+1,sg+tim,num)-sg;
		if(x>=tim||sg[x]!=num) continue; 
		vis[x]=vis[tim]=1; ans+=max(sz[tim],sz[x]);
	} for(LL i=1;i<=tim;i++){
		if(!vis[i]) ans+=sz[i];
	} printf("%lld\n",ans);
	return 0;
}

