int N;
long S[1<<17],T[2155];
map<long,int>M;
main()
{
	cin>>N;
	for(int i=1;i<=2154;i++)T[i]=1L*i*i*i;
	long Max=0;
	for(int i=0;i<N;i++)
	{
		cin>>S[i];
		for(int j=2;j<=2154&&T[j]<=S[i];j++)
		{
			while(S[i]%T[j]==0)S[i]/=T[j];
		}
		M[S[i]]++;
		Max=max(Max,S[i]);
	}
	int ans=0;
	if(M.find(1)!=M.end())ans=1;
	for(map<long,int>::iterator it=M.begin();it!=M.end();it++)
	{
		if(it->first==1||it->second==0)continue;
		long A=it->first,B=1;
		for(long j=2;j*j<=A;j++)
		{
			if(A%j==0)
			{
				if(A/j%j)
				{
					A/=j;
					if((Max+j-1)/j<B)
					{
						B=Max+1;
						break;
					}
					B*=j;
					if((Max+j-1)/j<B)
					{
						B=Max+1;
						break;
					}
					B*=j;
				}
				else
				{
					A/=j*j;
					if((Max+j-1)/j<B)
					{
						B=Max+1;
						break;
					}
					B*=j;
				}
			}
		}
		if((Max+A-1)/A<B);
		else
		{
			B*=A;
			if((Max+A-1)/A<B)B=Max+1;
			else B*=A;
		}
		if(M.find(B)==M.end())
		{
			ans+=it->second;
			it->second=0;
		}
		else
		{
			ans+=max(it->second,M[B]);
			it->second=M[B]=0;
		}
	}
	cout<<ans<<endl;
