void factor(int n) {
	// cout<<n<<" ";
	int num1=1,num2=1;
	for (int i=0 ; prime[i]<=3000 ; i++) {
		int cnt=0;
		while (n%prime[i]==0) {
			cnt++;
			n/=prime[i];
		}
		cnt%=3;
		if(cnt!=0) {
			for (int j=0 ; j<cnt ; j++)
				num1=num1*prime[i];
			cnt=3-cnt;
			for (int j=0 ; j<cnt ; j++)
				num2=num2*prime[i];
		}

	}
	if(n!=1) {
		int a=sqrt(n);
		if(a*a==n) {
			num1=num1*a*a;
			num2=num2*a;
		}
		else {
			num1=num1*n;
			num2=num2*n*n;		
		}
	}
	// cout<<num1<<" "<<num2<<endl;
	mpp[num1]++;
	mppp[num1]=num2;
}

