const int MAXN = 100000 + 5, MAXM = 10000 + 5;
const LL MAX = 10000000000LL;

int p[MAXM], p_cnt;
bool not_p[MAXN];
LL cube[MAXN];
std::map<LL, int> square;
std::map<std::pair<LL, LL>, int> s;

IL void init(int n) {
  not_p[1] = 1;
  For(i, 2, n) {
    if (!not_p[i]) {
      ++ p_cnt;
      p[p_cnt] = i, cube[p_cnt] = (LL)i * i * i;
      square[(LL)i * i] = i;
    }
    for (int j = 1; j <= p_cnt && i * p[j] <= n; ++ j) {
      not_p[i * p[j]] = 1;
      if (!(i % p[j])) {
        break;
      }
    }
  }
}

int main() {
  init(100000);
  int n;
  scanf("%d", &n);
  int answer = 0;
  For(i, 1, n) {
    LL cur;
    scanf("%lld", &cur);
    LL x = 1, y = 1;
    for (int j = 1; j <= p_cnt && cube[j] <= MAX; ++ j) {
      if (!(cur % p[j])) {
        while (!(cur % cube[j])) {
          cur /= cube[j];
        }
        if (!(cur % p[j])) {
          LL z = 1, w = cube[j];
          while (!(cur % p[j])) {
            cur /= p[j], z *= p[j], w /= p[j];
          }
          x *= z, y *= w;
          if (x > MAX || y > MAX) {
            ++ answer;
            goto NEXT;
          }
        }
      }
    }
    if (cur != 1) {
      x *= cur;
      if (square.count(cur)) {
        y *= square[cur];
      } else if (cur > 100000 || y > 2200) {
        ++ answer;
        goto NEXT;
      } else {
        y *= cur * cur;
      }
      if (x > MAX || y > MAX) {
        ++ answer;
        goto NEXT;
      }
    }
    ++ s[std::make_pair(x, y)];
    NEXT: ;
  }
  for (auto &x : s) {
    if (x.first.first == 1 && x.first.second == 1) {
      ++ answer;
      continue;
    }
    auto it = s.find(std::make_pair(x.first.second, x.first.first));
    if (it == s.end() || x.second >= it->second) {
      answer += x.second;
      x.second = INF;
    }
  }
  printf("%d\n", answer);
  return 0;
}

