ll mulmod (ll a, ll b, ll m) {
  ll q = (ll) ((long double) a * (long double) b / (long double) m);
  ll r = a * b - q * m;
  return (r + 5 * m)% m;
}

ll pollardRho(ll n) {
  if(n%2==0)
    return 2 ;

  ll x, y , g=1 , a;
  x = rand() % n + 1 ;
  y = x ;
  a = rand() % n + 1 ;

  while(g==1) {
   	if(a<0||x<0||y<0) while(1);
    x = (mulmod(x,x,n) + a)%n ;  
    y = (mulmod(y,y,n) + a)%n ;
    y = (mulmod(y,y,n) + a)%n ;  
    g = __gcd(abs(x - y), n) ;
  }
  return g ;
}
bool isprime[N];
ll fac[N];
map<ll,int> cur;
map<pair<tri,tri>,int> al;
void facto(ll x){
	if(x==1) return;
	ll z;
	if(x>=N){
		ll z = pollardRho(x);
	}else z = fac[x];
	if(z==x) {
		cur[z]++; return;
	}
	assert(z!=0);

	facto(z); facto(x/z);
}

