				y.X.X+=(3-it->Y)*it->X;
				y.X.Y+=(3-it->Y)*it->X*it->X;
				y.Y+=(3-it->Y)*it->X*it->X*it->X;
			}
		}
		al[mp(x,y)]++;
		ak.pb(mp(x,y));
	}
