int square(int v)
{
    int l = 0, r = v;
    while (r - l > 1)
    {
        int m = l + r >> 1;
        if (m * m < v)
            l = m;
        else
            r = m;
    }

    return r * r == v;
}


int get_square(int v)
{
    int l = 0, r = v;
    while (r - l > 1)
    {
        int m = l + r >> 1;
        if (m * m < v)
            l = m;
        else
            r = m;
    }

    return r;
}


