pii get_class(llint x) {
  llint ret1 = 1, ret2 = 1;
  REP(i, (int)p.size()) {
    int cnt = 0;
    while (x % p[i] == 0) {
      x /= p[i];
      ++cnt;
    }
    cnt %= 3;
    ret1 *= pp[cnt][i];
    ret2 *= pp[(3 - cnt) % 3][i];
  }

  if (x > 1) {
    llint root = sqrt(x);
    if (root * root == x) {
      ret1 *= root * root;
      ret2 *= root;
    } else {
      ret1 *= x;
      ret2 *= x * x;
    }
  }

  return {ret1, ret2};
}

