typedef long long LL;

const int N = 1e5 + 10;
const LL lim = 1e10;

int n, m, p, q, ans;
bool flag, is_prime[N];
LL a[N], prime[N], prime2[N], prime3[N];
set<LL> ST;
map<LL, LL> MP, G;

void init(){
	LL s;
    for(LL i=1; ;i++){
		s = i * i * i;
		if(s > lim)	break;
		ST.insert(s);
    }
    for(LL i=1; ;i++){
		s = i * i;
		if(s > lim)	break;
		MP[s] = i;
    }

    memset(is_prime, 1, sizeof(is_prime));
    p = q = 0;

    for(int i=2; i<N; i++){
		if(is_prime[i]){
			prime[p] = i;
			prime2[p] = prime[p] * prime[p];
			s = prime2[p] * prime[p];
			p++;
			if(s <= lim){
				prime3[q++] = s;
			}
			for(int j=i<<1; j<N; j+=i){
				is_prime[j] = 0;
			}
		}
    }
}

void trans(LL x){
	if(ST.count(x)){
		flag = 1;
		return;
	}

    for(int i=0; i<q && prime3[i]<=x; i++){
        while(x % prime3[i] == 0){
			x /= prime3[i];
        }
    }

    LL y = 1, z = x;

    for(int i=0; prime[i]<4000 && prime2[i]<=x; i++){
		if(x % prime[i] == 0){
			if(x % prime2[i] == 0){
				y *= prime[i];
				x /= prime2[i];
			} else {
				x /= prime[i];
				y *= prime2[i];
			}
		}
    }

    if(x > 1){
		if(MP.count(x)){
			y *= MP[x];
			a[m++] = z;
			G[z] = x;
		} else if(x <= 100000){
			y = y * x * x;
			a[m++] = z;
			G[z] = y;
		} else {
			ans++;
		}
    } else {
    	a[m++] = z;
    	G[z] = y;
    }
}

int Cnt(LL x){
	int j = lower_bound(a, a+m, x) - a;
	int k = upper_bound(a, a+m, x) - a;
	return k - j;
}

int main(){
	init();
	LL x, y;
	int c, d;
    while(~scanf("%d", &n)){
		ans = m = 0;
		flag = 0;
		G.clear();
		for(int i=0; i<n; i++){
			scanf("%lld", &x);
			trans(x);
		}

		ans += flag;

		if(m){
			sort(a, a+m);

			y = G[a[0]];
			c = Cnt(a[0]);
			d = Cnt(y);
			ans += max(c, d);
			for(int i=1; i<m; i++){
				if(a[i]==a[i-1])	continue;
				y = G[a[i]];
				d = Cnt(y);
				if(y<a[i] && d)	continue;
                c = Cnt(a[i]);
                ans += max(c, d);
			}
		}

		printf("%d\n", ans);
    }
	return 0;
}

