const ll MAX_A = 1e10;

ll calc_pair(ll x)
{
	ll res = 1;
	map<ll,int> fact;
	for(int i = 0;prime [i] * prime [i] * prime [i] <= x && i < prime.size();i++){
		while(x % prime [i] == 0){
			fact [prime [i]]++;
			x /= prime [i];
		}
	}
	if(sqr.count(x) && res <= MAX_A / sqr [x]){
		res *= sqr [x];
	}
	else if(sqr.count(x) == 0 && res <= MAX_A / x / x){
		res *= x * x;
	}
	else{
		return -1;
	}
	for(auto&& it : fact){
		if(it.second == 1 && res <= MAX_A / it.first / it.first){
			res *= it.first * it.first;
		}
		else if(it.second == 2 && res <= MAX_A / it.first){
			res *= it.first;
		}
		else{
			return -1;
		}
	}

	return res;
}

