void init() {

  for(int i=2;i<=M;i++) {
    if(!p[i]) {
      pr.push_back(i);
      for(int j=i+i;j<=M;j+=i) {
        p[j]=1;
      }
    }
  }

}

ll ters(ll x) {

  for(int i=0;i<pr.size();i++) {
    ll bol=1ll*pr[i]*pr[i]*pr[i];
    while(x%bol==0) x/=bol;
  }
  return x;

}

ll pai(ll x) {

  ll pi=1;
  vector<ll> carp;
  for(int i=0;i<pr.size();i++) {
    int no=0;
    while(x%pr[i]==0) x/=pr[i],no++;
    if(no) {
      for(int j=1;j<=3-no;j++,carp.push_back(pr[i]));
    }
  }
  ll sq=sqrt(x);
  if(sq*sq==x) {
    carp.push_back(sq);
  }
  else {
    for(int i=0;i<2;i++,carp.push_back(x));
  }
  for(int i=0;i<carp.size();i++) {
    pi*=carp[i];
    if(pi>1ll*N*N) {
      return 0;
    }
  }
  return pi;

}

