	for(int i=2;i<N;i++)
		if(vis[i]==false){
			pr[++pcnt]=i;p2.insert(i*1LL*i);p1.insert(i);
			cube[pcnt]=i*1LL*i*i;
			if(i<=2155) ccnt=pcnt;
			for(int j=i+i;j<N;j+=i) vis[j]=true;
		}
