LL op(LL v){
	LL ret=1;
	for(int i=1;i<=ccnt&&pr[i]<=v;i++){
		if(v%pr[i]==0){
			v/=pr[i];ret*=pr[i];
			if(v%pr[i]==0) v/=pr[i];
			else ret*=pr[i];
			if(ret>1e10) return -1;
		}
	}
	if(v==1) return ret;
	if(p1.find(v)!=p1.end()) return ret*v*v;
	if(p2.find(v)!=p2.end()) return ret*(int)(sqrt((long double)v)+0.5);
	return -1;
}
