int main(){

    std::ifstream in("text.txt");
    std::cin.rdbuf(in.rdbuf());
    cin.tie(0);
    ios::sync_with_stdio(false);

    sieve(MAX-3);
    int N;cin>>N;
    map<ll,int> MA;
    ll ans=0;
    bool zero=false;

    vector<ll> cube;
    for(ll p:prime){
        if(p*p*p>10000000000) break;
        cube.push_back(p*p*p);
    }

    while(N--){
        ll a;cin>>a;

        for(ll c:cube){
            while(a%c==0) a/=c;
        }

        if(a==1){
            zero=true;
            continue;
        }

        MA[a]++;
    }

    if(zero) ans++;

    for(auto it=MA.begin();it!=MA.end();it++){
        if((*it).second==0) continue;

        ll a=(*it).first,b=1;

        for(auto p:prime){
            int cnt=0;
            while(a/p*p==a){
                a/=p;
                cnt++;
            }

            if(cnt==1) b*=p*p;
            if(cnt==2) b*=p;

            if(a==1) break;
        }

        if(a>1){
            ans++;
            continue;
        }

        a=(*it).first;

        ans+=max(MA[a],MA[b]);

        MA[a]=0;
        MA[b]=0;
    }

    cout<<ans<<endl;

}

