        mp[s[i]]++;
    }
    int ans = 0;
    if (mp[1] > 0) { ans++, mp[1] = 0; }
    rep(i, N) {
        int cur = s[i], counter = 1;

        for (int j = 2; s[i] / j / j / j >= 1; j++) {
            if (cur % (j * j) == 0) {
                prod(counter, j);
                cur /= (j * j);
            } else if (s[i] % j == 0) {
                prod(counter, j * j);
                cur /= j;
            }
        }
        int rt = round(sqrt(cur));
        if (rt * rt == cur) { prod(counter, rt); }
        else { prod(counter, cur * cur); }
        ans += max(mp[s[i]], mp[counter]);
        mp[s[i]] = mp[counter] = 0;
    }
    cout << ans << endl;
