	for (int i=1;i<=n;i++) scanf("%lld",&a[i]);
	for (int i=1;i<=n;i++) solve(a[i]);
	for (int i=1;i<=m;i++) ord[i]=i;
	sort(ord+1,ord+m+1,comp);

	for (int i=1;i<=m;)
	{
		int pos=i,c1=0,c2=0;
		while (pos<=n&&t[ord[pos]]==t[ord[i]]) {
			a[ord[pos]]==a[ord[i]]?c1++:c2++;++pos;
		}
		ans+=max(c1,c2);i=pos;
	}
	printf("%d",ans+(cnt?1:0));
	return 0;
}

#include<bits/stdc++.h>

using namespace std;

#define int long long
#define pb push_back
#define fi first
#define se second
typedef vector<int> vi;

const int nunach = 2500, N = 1e5 + 5;
bool vis[nunach];
vi prime;
int ans, n;
long long a[N];
map<long long, int> mp;

void sieve() {
    for (int i = 2; i < nunach; ++i) {
        if(!vis[i]) {
            prime.pb(i);
            for (int j = 2 * i; j < nunach; j += i) vis[j] = 1;
        }
    }
}

void upd(long long &num) {
    for(int i : prime) {
        long long cube = 1LL * i * i * i;
        while(num % cube == 0) num /= cube;
    }
}

long long get(long long num) {
    int res = 1;
    for (int i : prime) {
        if(num % i == 0) {
            res *= i;
            if(num % (1LL * i * i) != 0) res *= i;
        }
    }
    return res;
}

signed main () {
    ios_base::sync_with_stdio(0); cin.tie(0); cout.tie(0);
    sieve();
    cin >> n;
    for (int i = 1; i <= n; ++i) {
        cin >> a[i];
        upd(a[i]);
        mp[ a[i] ] ++;
    }

    for(auto i : mp) {
        if(i.fi == 1) ans ++;
        else {
            long long rem = get(i.fi);
            if(mp.count(rem) ) {
                ans += max(i.se, mp[rem]);
                mp.erase(rem);
            }
            else ans += i.se;
        }
    }

    cout << ans;

    return 0;
}

