		if (t[i] != 1) {
			int re1 = reve(t[i],pr);
			int ind = lower(t, re1)-t.begin();
			if (i<ind &&ind < sz) {
				if (re1 == t[ind]) {
					ans -= min(co[i], co[ind]);
				}
			}
		}
	}
	cout << ans << endl;
	return 0;
}

