void get_prime(){
	memset(isprime,true,sizeof isprime);
	isprime[0]=isprime[1]=false;
	for (ll i = 2; i < maxn; ++i)
	{
		if(!isprime[i]) continue;
		prime[tot++]=i;
		for (ll j = i*i; j < maxn; j+=i)
		{
			isprime[j]=false;
		}
	}
}
int n;
unordered_map<ll,int> mp;
unordered_map<ll,ll> rvs;
ll L[maxn],R[maxn];
int main(int argc, char const *argv[])
{
	get_prime();
    scanf("%d", &n);
    for (int i = 0; i < n; ++i)
    {
    	ll x,y=1,z=1;
    	scanf("%lld", &x);
    	for (int j = 0; prime[j]*prime[j] <= x; ++j)
    	{
    		ll k=prime[j];
    		if(x%k==0){
    			int cnt=0;
    			while(x%k==0){
    				x/=k;
    				cnt++;
    			}
    			cnt%=3;
    			int tmp=(3-cnt)%3;
    			while(cnt--) y*=k;
    			while(tmp--){
    				z*=k;
    				if(z>1e10) z=0;
    			}
    		}
    	}
    	if(x>1){
    		y=y*x;
    		if(z*x>1e10 || z*x*x> 1e10) z=0;
    		z=z*x*x;
    	}
    	mp[y]++;
    	L[i]=y;
    	R[i]=z;
    	// rvs[y]=z;
    	// rvs[z]=y;
    }
    int ans=0;
    for (int i = 0; i < n; ++i)
    {
    	if(L[i]==1){
    		ans+=int(mp[1]>0);
    		mp[1]=0;
    	}
    	else{
    		ans+=max(mp[L[i]],mp[R[i]]);
    		mp[L[i]]=mp[R[i]]=0;
    	}
    }
    printf("%d\n", ans);
    return 0;
}

