void init()
{
	cnt=0;
	int up=1e5;
	memset(vis,0,sizeof(vis));

	for(int i=2;i<=up;i++)
	{
		if(!vis[i])
		{
			vis[i]=1;
			cnt++;
			pri[cnt]=i;
		}
		for(int j=i+i;j<=up;j+=i)
		{
			vis[j]=1;
		}
	}
	for(int i=1;i<=cnt;i++)
	{
		two[i] = 1LL*pri[i]*pri[i];
		tri[i] = 1LL*two[i]*pri[i];
	}
}

int max(int a,int b)
{
