		for(int j=1;j<=cnt;j++)
		{
			if(tri[j]>val[i])break;
			if(val[i]%tri[j]==0)
			{
				val[i]/=tri[j];
				while(val[i]%tri[j]==0)
				{
					val[i]/=tri[j];
				}
			}
		}
		ll tmp = val[i];
		ll s = 1;
		for(int j=1;j<=cnt;j++)
		{
			if(two[j]>tmp)break;
			if(tmp%two[j]==0)
			{
				s*=pri[j];
				tmp /= two[j];
			}
		}
		//cout<<"tmp:"<<tmp<<endl;
		s*=tmp*tmp;
		con[val[i]]=s;
		num[val[i]]++;
	}
