LL Get(LL x){
	LL res=1;
	for (int i=1;i<=pcnt;i++)
		if (x%prime[i]==0){
			LL cnt=1;
			x/=prime[i];
			if (x%prime[i]==0)
				x/=prime[i],cnt++;
			cnt=3-cnt;
			while (cnt>0){
				cnt--,res*=prime[i];
				if (res>1e11)
					return -1;
			}
		}
	if (x>1){
		LL t=x;
		if (sqr[x]>0)
			t=sqr[x];
		if (t>1e11/res)
			return -1;
		res*=t;
	}
	return res>1e10?-1:res;
}
