    a[i] = fact(a[i]);
    mp[a[i]]++;
    if(invv.find(a[i]) == invv.end()){
      invv[a[i]] = inv(a[i]);
    }
  }
  int ans = n;
  for(int i = 1; i <= n; i++){
    ll x = invv[a[i]];
    if(mp[x] == 0 && mp[a[i]] == 0)continue;
    int cnt = mp[a[i]], cnt1 = mp[x];
    if(x == a[i] && cnt == 1)continue;
