void addpl() {
    primesl[0] = 0;
    primesl[1] = 0;
    for (int i = 2; i < 100000; i++) {
        if (!primesl[i]) continue;
        for (int j = 2; i * j < 100000; j++) {
            primesl[i * j] = 0;
        }
    }

    for (int i = 2; i < 100000; i++) {
        if (primesl[i]) {
            long p = primesl[i];
            isp[p] = true;
            isps[p * p] = true;
        }
    }
}

long red(long s) {
    for (long p: primes) {
        while (s % (p * p * p) == 0) {
            s /= p * p * p;
        }
    }
    return s;
}

long findp(long s) {
    for (long p: primes) {
        while (s % p == 0) {
            s /= p;
        }
    }
    return s;
}

long brv(long s) {
    long ans = 1;
    for (long p: primes) {
        if (s % (p * p) == 0) {
            ans *= p;
        } else if (s % p == 0) {
            ans *= p * p;
        }
        if (ans > 1e10) return -1;
    }
    return ans;
}

long opp(long s) {
    long p = findp(s);
    long b = s / p;
    long br = brv(b);
    if (br == -1) return -1;

    if (p == 1) return br;
    if (isp[p]) {
        if (double(br) * p * p > 1e10) return -1;
        return br * p * p;
    }
    if (isps[p]) {
        if (double(br) * sqrt(p) > 1e10) return -1;
        return br * long(sqrt(p));
    }
    return -1;
}

