bool prime(long long x) { // 2 \leq x \leq MAX_SIZE^2
  if (x < MAX_SIZE) {
    return isprime[x];
  }
  for (auto e : prime_num) {
    if (x%e == 0) return false;
  }
  return true;
}

int N;
ll s[100010];
map<ll, int> M;

ll conj(ll k) {
  ll l = k;
  ll A = 1;
  ll B = 1;
  for (auto x : prime_num) {
    int t = 0;
    while (l % x == 0) {
      l /= x;
      t++;
    }
    if (t == 1) {
      A *= x;
    } else if (t == 2) {
      B *= x;
    }
  }
  ll red = k / (A * B * B);
  ll sq = sqrt(red);
  long long t = static_cast<long long>(sq);
  t = floor(t);
  // cerr << "red = " << red << " , sq = " << sq << endl;
  if (red == t * t) {
    B *= red;
  } else {
    A *= red;
  }
  return A * A * B;
}

