    vector<ll> vec(n);
    for (int i = 0; i < n; i++) cin >> vec[i];

    for (ll i = 2; i <= N; ++i) {
        if (lp[i] == 0) {
            lp[i] = i;
            s.push_back(i);
        }
        for (ll j = 0; j < (ll)s.size() && s[j] <= lp[i] && i*s[j] <= N; ++j)
            lp[i * s[j]] = s[j];
    }

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < s.size(); j++) {
            while (vec[i] % (s[j] * s[j] * s[j]) == 0) {
                vec[i] /= (s[j] * s[j] * s[j]);
            }
            if ((s[j] * s[j] * s[j]) > SIZE) break;
        }
    }

    ll ans = 0;

    map<ll, ll> cnt;
    for (int i = 0; i < n; i++) {
        if (vec[i] > SIZE) ans++;
        else {
            cnt[vec[i]]++;
        }
    }

    ll add = 0;
    set<ll> usd;
    for (auto cur : cnt) {
        ll vl = cur.first, sv = cur.first;
