using namespace std ; 

typedef long long ll ; 

vector<ll> cubes ; 
ll maxCubeBase ;
vector<ll> primes ; 

bool isPrime(ll v) {
    for(int i = 2 ; i*i <= v ; i++)
        if(v%i == 0)
            return false ; 
    return true ; 
}

ll inv(ll val) {
    ll rtn = 1 ; 
    ll origVal = val ; 
    for(int p = 0 ; p < primes.size() && primes[p] <= origVal ; p++) {
        int cnt = 0 ; 
        while(val % primes[p] == 0) {
            cnt++ ; 
            val /= primes[p] ; 
        }
        if(cnt) {
            for(int j = cnt ; j != 3 ; j++) {
                rtn *= primes[p] ; 
                if(rtn > 1e+10)
                    return -1 ; 
            }
        }
    }
    if(val != 1)
        return -1 ; 
    return rtn ; 
}

int main()
{
    for(int i = 2 ; i <= 1e+5 ; i++)
        if(isPrime(i))
            primes.push_back(i) ; 
    for(ll i = 2 ; i*i*i <= 1e+10 ; i++) {
        cubes.push_back(i*i*i) ;
        maxCubeBase = i ; 
    }
    int N ; 
    scanf("%d", &N) ; 
    map<ll, int> vals ;
    bool completeCubic = false ; 
    for(int i = 0 ; i != N ; i++) {
        ll s ; 
        scanf("%lld", &s) ; 
        for(auto& c: cubes) {
            while(s%c == 0)
                s /= c ; 
        }
        if(s == 1) {
            completeCubic = true ; 
            continue ; 
        }
        vals[s]++ ; 
 //       printf("\ns = %d\n", s) ; 
    }
    //printf("%d\n", inv(2)) ; 
    //while(1) ; 
    set<ll> invalid ; 
    int ans = 0 ; 
    for(auto p: vals) {
        if(invalid.find(p.first) != invalid.end())
            continue ; 
        ll i = inv(p.first) ; 
        auto iter = vals.find(i) ; 
        if(iter == vals.end())
            ans += p.second ; 
        else {
            ans += max(iter->second, p.second) ; 
            invalid.insert(i) ; 
        }
    }
    printf("%d\n", ans+completeCubic) ; 
    return 0 ; 
}

