    for (ll j = i * 2; j < 3000; j += i) is_prime[j] = false;
  }
  for (ll i = 0; i < n; i++) {
    ll x = 1, y = 1;
    for (ll j : prime) {
      ll counter = 0;
      while (s[i] % j == 0) s[i] /= j, counter++;
      counter %= 3;
      if (counter == 1) x *= j, y *= j * j;
      if (counter == 2) x *= j * j, y *= j;
      if (y > 10000000000LL) break;
    }
    if (y <= 10000000000LL && s[i] > 1) {
      ll sq = square(s[i]);
      if (sq > 0) {
        x *= sq * sq, y *= sq;
      } else {
        x *= s[i];
        y *= s[i];
        if (y <= 10000000000LL) y *= s[i];
      }
    }
    if (y > 10000000000LL) ans++;
    else mp[P(x, y)]++;
  }
  for (auto it = mp.begin(); it != mp.end(); it++) {
    if (it->first == P(1, 1)) {
      ans++;
