typedef basic_string<int> bsll;

bool isavl[M];
bsll avals;

bsll tajz(ll &x)
{
    bsll r1,r2;
    ll cnt=0;
    for (int p:avals)
    {
        //if (p*p>x) break;
        if (x%p!=0) continue;
        cnt=0;
        while (x%p==0)
        {
            x/=p;
            cnt++;
        }
        if (cnt%3==1) r1+=p;
        else if (cnt%3==2) r2+=p;
    }
    r1+=-1;
    r1+=r2;
    return r1;
}

ll n;
ll res;

bsll swp(bsll a)
{
    ll x=-1;
    bsll r1,r2;
    For(i,0,inf)
    {
        if (a[i]==-1)
            break;
        x=i;
        r1+=a[i];
    }
    x+=2;
    For(i,x,SZ(a))
    {
        r2+=a[i];
    }
    r2+=-1;
    r2+=r1;
    return r2;
}

