int main(){
  int n;
  cin>>n;
  vector<ll> a(n);
  for(int i=0;i<n;i++){
    long long int buf;
    cin>>buf;
    a[i]=buf;
  }

  while(cubed_s*cubed_s*cubed_s<=MAX_S) cubed_s++;
  vector<int> is_prime(1e5+1,1);
  int size_cube=0;
  is_prime[0]=is_prime[1]=0;
  for(int i=0;i<=1e5;i++){
    if(is_prime[i]){
      if(i>cubed_s && size_cube==0) size_cube=prime.size();
      prime.push_back(i);
      for(int j=2*i;j<=1e5;j+=i){
	is_prime[j]=false;
      }
    }
  }
  cube_prime.resize(size_cube);
  set<ll> prime_set;
  for(int i=0;i<prime.size();i++) prime_set.insert(prime[i]);
  for(int i=0;i<cube_prime.size();i++){
    cube_prime[i]=prime[i]*prime[i]*prime[i];
  }
  vector<ll> norm(n);
  for(int i=0;i<n;i++){
    norm[i]=get_norm(a[i]);
  }

  map<ll,ll> square_prime;
  for(int i=0;i<prime.size();i++){
    square_prime[prime[i]*prime[i]]=prime[i];
  }
  vector<ll> couple(n);
  for(int i=0;i<n;i++){
    ll num=norm[i];
    couple[i]=1;
    for(int j=0;j<cube_prime.size();j++){
      int cnt=0;
      while(num%prime[j]==0){

	num/=prime[j];
	cnt++;

      }

      if(cnt==1) couple[i]*=prime[j]*prime[j];
      if(cnt==2) couple[i]*=prime[j];

    }
    if(num!=1){
      if(square_prime.count(num)){
	couple[i]*=square_prime[num];

      }
      else if(prime_set.count(num)){
	couple[i]*=num*num;
      }
      else{
	couple[i]=-1;
      }
    }


  }

  set<ll> checked;
  long long int res=0;
  map<ll,long long int> norm_cnt;

  for(int i=0;i<n;i++){
    norm_cnt[norm[i]]++;
  }


  for(int i=0;i<n;i++){
    if(checked.count(norm[i])) continue;
    if(norm[i]==1){
      res++;
      checked.insert(1);
    }
    else{
      if(couple[i]==-1){
	res++;
      }
      else if(norm[i]==couple[i]){
	res++;
	checked.insert(norm[i]);
      }
      else{
	res+=max(norm_cnt[norm[i]],norm_cnt[couple[i]]);
	checked.insert(norm[i]);
	checked.insert(couple[i]);
      }
    }
  }

  cout<<res<<endl;
  return 0;

}

