//ミラーラビン素数判定法とポラード・ロー法のコードは http://quiz.fuqinho.net/blog/2012/06/12/poj-2429-gcd-and-lcm-inverse/ より

// return (a * b) % m
ll mod_mult(ll a, ll b, ll m) {
	ll res = 0;
	ll exp = a % m;
	while (b) {
		if (b & 1) {
			res += exp;
			if (res > m) res -= m;
		}
		exp <<= 1;
		if (exp > m) exp -= m;
		b >>= 1;
	}
	return res;
}

// return (a ^ b) % m
ll mod_exp(ll a, ll b, ll m) {
	ll res = 1;
	ll exp = a % m;
	while (b) {
		if (b & 1) res = mod_mult(res, exp, m);
		exp = mod_mult(exp, exp, m);
		b >>= 1;
	}
	return res;
}

// ミラー-ラビン素数判定法
bool miller_rabin(ll n, ll times) {
	if (n < 2) return false;
	if (n == 2) return true;
	if (!(n & 1)) return false;

	ll q = n - 1;
	int k = 0;
	while (q % 2 == 0) {
		k++;
		q >>= 1;
	}
	// n - 1 = 2^k * q (qは奇素数)
	// nが素数であれば、下記のいずれかを満たす
	// (i) a^q ≡ 1 (mod n)
	// (ii) a^q, a^2q,..., a^(k-1)q のどれかがnを法として-1
	//
	// なので、逆に(i)(ii)いずれも満たしていない時は合成数と判定できる
	//
	for (int i = 0; i < times; i++) {
		ll a = rand() % (n - 1) + 1; // 1,..,n-1からランダムに値を選ぶ
		ll x = mod_exp(a, q, n);
		// (i)をチェック
		if (x == 1) continue;
		// (ii)をチェック
		bool found = false;
		for (int j = 0; j < k; j++) {
			if (x == n - 1) {
				found = true;
				break;
			}
			x = mod_mult(x, x, n);
		}
		if (found) continue;

		return false;
	}
	return true;
}

ll get_gcd(ll n, ll m) {
	if (n < m) swap(n, m);
	while (m) {
		swap(n, m);
		m %= n;
	}
	return n;
}

// ポラード・ロー素因数分解法
ll pollard_rho(ll n, int c) {
	ll x = 2;
	ll y = 2;
	ll d = 1;
	while (d == 1) {
		x = mod_mult(x, x, n) + c;
		y = mod_mult(y, y, n) + c;
		y = mod_mult(y, y, n) + c;
		d = get_gcd((x - y >= 0 ? x - y : y - x), n);
	}
	if (d == n) return pollard_rho(n, c + 1);
	return d;
}

