	for (int i = 2; i <= MAX_PRIME; i++) {
		if (is_prime[i]) {
			primes.push_back(i);
			for (int j = i * 2; j <= MAX_PRIME; j += i) {
				is_prime[j] = false;
			}
		}
	}
}

// 素数かどうか判定。大きければミラーラビンを使う
bool isPrime(ll n) {
	if (n <= MAX_PRIME) return is_prime[n];
	else return miller_rabin(n, 10);
}

// 素因数分解する。小さい数は用意した素数で試し割り、大きければポラード・ロー
void factorize(ll n, map<ll, int>& factors) {
	if (isPrime(n)) {
		factors[n]++;
	}
	else {
		for (int i = 0; i < primes.size(); i++) {
			int p = primes[i];
			while (n % p == 0) {
				factors[p]++;
				n /= p;
			}
		}
		if (n != 1) {
			if (isPrime(n)) {
				factors[n]++;
			}
			else {
				ll d = pollard_rho(n, 1);
				factorize(d, factors);
				factorize(n / d, factors);
			}
		}
	}
}



void solve(){
	init_primes();
	int N; cin >> N;
	vector<ll>S(N);
	REP(i, N)cin >> S[i];
	map<ll, int>cnt;
	vector<map<ll, int>>facs(N);
	REP(i, N) {
		//DEBUG(S[i]);
		if (S[i] != 1) {
			factorize(S[i], facs[i]);
		}
		//print("factorize done");
		for (auto &x : facs[i]) {
			x.second %= 3;
		}
		S[i] = 1;
		//cerr << facs[i].size() << endl;
		for (auto x : facs[i]) {
			ll t = 1;
			//assert(x.second < 3);
			REP(_, x.second)t *= x.first;
			S[i] *= t;
		}
		cnt[S[i]]++;
	}

	map<ll, bool>done;
	int ans = 0;
	REP(i, N) {
		if (S[i] == 1) {
			if (!done[1])ans++;
			done[1] = true;
		}
		else {
			if (done[S[i]])continue;
			done[S[i]] = true;
			ll pa = 1;
			for (auto x : facs[i]) {
				if (x.second == 0)continue;
				int t = 1;
				REP(_, 3 - x.second)t *= x.first;
				pa *= t;
			}
			if (done[pa])continue;
			ans += max(cnt[S[i]], cnt[pa]);
			done[pa] = true;
		}
	}
	print(ans);
}


