void sieve(){
	for(int i=2;i<M;++i){
		if(l[i] == 0){
			for(int j=i;j<M;j+=i){
				if(l[j] == 0 || l[j] > i){
					l[j] = i;
				}
			}
		}
	}
}

pair<long long, long long> pushSmall(long long v){
	long long v1 = 1;
	long long v2 = 1;
	while(v > 1){
		int k = l[v];
		int d = 0;
		while(v % k == 0){
			++d;
			v /= k;
		}
		d %= 3;
		if(d > 0){
			for(int i=0;i<d;++i){
				v1 *= k;
			}
			for(int i=0;i<3-d;++i){
				v2 *= k;
				if(v2 > MAXV){
					return make_pair(v1, INF);
				}
			}
		}
	}
	return make_pair(v1, v2);
}

pair<long long, bool> isQ(long long v){
	long long c = sqrt(v);
	if((c-1)*(c-1) == v){
		return make_pair(c-1, true);
	}
	if(c*c == v){
		return make_pair(c, true);
	}
	if((c+1)*(c+1) == v){
		return make_pair(c+1, true);
	}
	return make_pair(41, false);
}

vector<pair<long long, int> > getFactV(long long v){
	vector<pair<long long, int> > ret;
	while(v > 1){
		int k = l[v];
		int d = 0;
		while(v % k == 0){
			v /= k;
			++d;
		}
		d %= 3;
		if(d > 0){
			ret.push_back(make_pair(k, d));
		}
	}
	return ret;
}

pair<long long, long long> push(long long v){
	if(v < M){
		return pushSmall(v);
	}else{
		for(int i=2;i<B;++i){
			if(l[i] == i && (v % i == 0)){
				int k = i;
				int d = 0;
				while(v % k == 0){
					v /= k;
					++d;
				}
				d %= 3;
				long long v1 = 1;
				long long v2 = 1;
				if(d > 0){
					for(int j=0;j<d;++j){
						v1 *= k;
					}
					for(int j=0;j<3-d;++j){
						v2 *= k;
						if(v2 > MAXV){
							return make_pair(v1, INF);
						}
					}
				}
				pair<long long, long long> ret = push(v);
				if(MAXV / v2 < ret.second){
					return make_pair(41, INF);
				}
				return make_pair(v1 * ret.first, v2 * ret.second);
			}
		}
		pair<long long, bool> q = isQ(v);
		if(q.second){
			vector<pair<long long, int> > fV = getFactV(q.first);
			long long v1 = 1;
			long long v2 = 1;
			for(int i=0;i<fV.size();++i){
				for(int j=0;j<3-fV[i].second;++j){
					v1 *= fV[i].first;
				}
				for(int j=0;j<fV[i].second;++j){
					v2 *= fV[i].first;
				}
			}
			return make_pair(v1, v2);
		}
		return make_pair(41, INF);
	}
}

