int Vis[MAXN + 5];
std::vector<int> P;

void GetPrimes(int n) {
	for (int i = 2; i <= n; i++) {
		if (!Vis[i])
			P.push_back(i);
		for (int j = 0; j < int(P.size()) && i * P[j] <= n; j++) {
			Vis[i * P[j]] = true;
			if (i % P[j] == 0)
				break;
		}
	}
}

std::map<LL, bool> Met;
std::map<LL, int> Cnt, Opp;

int main() {
	GetPrimes(MAXP);
	scanf("%d", &N);
	int Ans = 0;
	for (int i = 1; i <= N; i++) {
		scanf("%lld", &A[i]);
		LL tmp = A[i], res = 1, opp = 1;
		for (int j = 0; (LL)P[j] * P[j] * P[j] <= tmp; j++) {
			if (A[i] % P[j] == 0) {
				int cnt = 0;
				while (A[i] % P[j] == 0) {
					cnt++;
					A[i] /= P[j];
				}
				if (cnt % 3 == 1)
					res *= P[j], opp *= P[j] * P[j];
				else if (cnt % 3 == 2)
					res *= P[j] * P[j], opp *= P[j];
			}
		}
		res *= A[i];
//		printf("     [%lld]\n", res);
		if (res == 1) {
			Ans += !Ans;
			continue;
		}
		LL s = sqrt(A[i] + 0.01);
		if (s * s == A[i])
			Opp[res] = opp * s;
		else
			Opp[res] = opp * A[i] * A[i];
		Cnt[res]++;
//		printf("  -> [%lld]\n", Opp[res]);
	}
	for (std::map<LL, int>::iterator it = Cnt.begin(); it != Cnt.end(); ++it) {
		LL num = it->first; int cnt = it->second;
		if (!Met[num]) {
			if (Cnt.count(Opp[num]))
				Ans += std::max(Cnt[Opp[num]], cnt), Met[Opp[num]] = true;
			else
				Ans += cnt;
			Met[num] = true;
		}
	}
	printf("%d", Ans);
	return 0;
}

