        for (ll j = 1; j <= tot && prime[j] * prime[j] <= x; j++)
            if (x % prime[j] == 0)
            {
                ll num = 0;
                while (x % prime[j] == 0)
                {
                    num++;
                    x /= prime[j];
                }
                if (num % 3 == 1)
                {
                    c1[i] *= prime[j];
                    c2[i] *= prime[j] * prime[j];
                }
                else if (num % 3 == 2)
                {
                    c1[i] *= prime[j] * prime[j];
                    c2[i] *= prime[j];
                }
            }
        if (x != 1)
        {
