int n, m, ans, p, q;
bool flag;
LL a[N], prime[N], prime2[N], _prime[N];
set<LL> ST;
bool is_prime[N];

void trans(LL x){
    if(ST.count(x)){
        flag = 1;
        return;
    }
    for(int i=0; i<q && _prime[i]<=x; i++){
        while(x % _prime[i] == 0){
            x /= _prime[i];
        }
    }

    LL y = x;

    for(int i=0; i<p && prime2[i]<=x; i++){
        while(x % prime[i] == 0){
            x /= prime[i];
        }
    }
    if(x > prime[p-1]){
        ans++;
        return;
    }

    a[m++] = y;
}

LL change(LL x){
    LL y = 1;
    for(int i=0; i<p && prime2[i]<=x; i++){
        if(x % prime[i] == 0){
            if(x % prime2[i] == 0){
                y *= prime[i];
                x /= prime2[i];
            } else {
                x /= prime[i];
                y *= prime2[i];
            }
        }
    }
    if(x > 1){
        y = y * x * x;
    }
    return y;
}

void init(){
    LL s;
    for(LL i=1; ; i++){
        s = i * i * i;
        if(s > top) break;
        ST.insert(s);
    }

    p = q = 0;
    memset(is_prime, 0, sizeof(is_prime));
    for(int i=2; i<=100000; i++){
        if(!is_prime[i]){
            s = 1LL * i * i * i;
            prime[p] = i;
            prime2[p++] = 1LL  * i * i;
            if(s <= top){
                _prime[q++] = s;
            }
            for(int j=i; j<N; j+=i){
                is_prime[j] = 1;
            }
        }
    }
}

int Cnt(LL x){
    int i = lower_bound(a, a+m, x) - a;
    int j = upper_bound(a, a+m, x) - a;
    return j - i;
}

int main(){
    init();
    LL x, y;
    int c, d;
    while(~scanf("%d", &n)){
        m = ans = 0;
        flag = 0;
        for(int i=0; i<n; i++){
            scanf("%lld", &x);
            trans(x);
        }
        ans += flag;
        sort(a, a+m);
        if(m){
            y = change(a[0]);
            c = Cnt(a[0]);
            d = Cnt(y);
            ans += max(c, d);
            for(int i=1; i<m; i++){
                if(a[i]==a[i-1])   continue;
                y = change(a[i]);
                d = Cnt(y);
                if(y<a[i] && d) continue;
                c = Cnt(a[i]);
                ans += max(c, d);
            }
        }
        printf("%d\n", ans);
    }
    return 0;
}

