int sieve(int n){
  int p=0;
  for(int i=0; i<=n; i++) is_prime[i]=true;
  is_prime[0]=is_prime[1]=false;
  for(int i=2; i<=n; i++){
    if(is_prime[i]){
      prime[p++]=i;
      for(int j=2*i; j<=n; j+=i) is_prime[j]=false;
    }
  }
  return p;
}

ll dv(ll x){

  for(int i=0; i<NP; i++){

    ll q=prime[i]; //if(q>1000) break;
    ll t=q*q*q;
    if(t>x) break;
    while(x%t==0) x/=t;

  }

  return x;

}

ll tp(ll x){
	ll A=1,B=1;
	for(ll i=2;;i++){
		if(i*i*i>x) break;
		int cnt=0;
		while(x%i==0)
		{
			x/=i;
			cnt++;
		}
		if(cnt==1) A*=i;
		else if(cnt==2) B*=i;
	}

      ll dt=(ll) floor(sqrt(x)+0.5);
      if(dt*dt==x) return A*A*sqrt(B)*dt;
      else return A*A*sqrt(B)*x*x;

}

