const int N = 100000 + 5;

int vis[N];

vector<int> pri;

void sieve()
{
    rep(i , 2 , 2300)
    {
        if(!vis[i])
            pri.push_back(i);
        for(int x : pri)
        {
            if(i * x > 2300) break ;
            vis[i * x] = 1;
            if(i % x == 0) break ;
        }
    }
}

int n ; LL A[N] , Ans;

LL L[N] , R[N];

map<LL , int> G;

int check(LL x)
{
    LL v = sqrt(x);
    return v * v == x;
}

int main()
{
    read(n) , sieve();
    rep(i , 1 , n) read(A[i]);
    rep(i , 1 , n)
    {
        LL x = A[i];
        for(int d : pri)
        {
            LL v = 1ll * d * d * d;
            if(v > x) break ;
            while(x % v == 0) x /= v;
        }
        G[x]++ , L[i] = x;
        LL y = 1;
        for(int d : pri)
        {
            if(1ll * d * d * d > x) break ;
            if(x % d == 0)
            {
                y *= (x % (1ll * d * d) == 0 ? d : 1ll * d * d);
                while(x % d == 0) x /= d;
            }
        }
        y *= check(x) ? sqrt(x) : x * x;
        R[i] = y;
    }
    if(G[1])
        Ans += 1 , G[1] = 0;
    rep(i , 1 , n)
        Ans += max(G[L[i]] , G[R[i]]) , G[L[i]] = G[R[i]] = 0;
