    map<ll, ll> memo_for, memo_rev;
    ll flag = 0;
    rep(i, n) {
        rho(a[i]);
        long double tmp_for = 1;
        for (auto& x : rho_ret) 
            rep(j, x.se % 3)
                tmp_for *= x.fi;
        memo_for[tmp_for]++;

        flag |= tmp_for == 1;

        long double tmp_rev = 1;
        for (auto& x : rho_ret) 
            rep(j, ((3 - x.se) % 3 + 3) % 3)
                tmp_rev *= x.fi;
        memo_rev[tmp_for] = (tmp_rev > 1e10 ? INF : tmp_rev);
    }
    ll ret = flag;
    for (auto x : memo_for) if (x.fi != 1 && x.fi < memo_rev[x.fi]) {
        ll l = x.se;
        ll r = memo_for[memo_rev[x.fi]];
        ret += max({l, r});
    }
    cout << ret << endl;
    return 0;
}

