typedef long long LL;

const int N = 1e5 + 10;
const LL MAX = 1e11;

int n, ans;
map<LL, int> cnt;
map<LL, LL> M;

int main(){
	scanf("%d", &n);

	while(n--){
		LL x;
		scanf("%lld", &x);

		int r = pow(x, 1.0 / 3) + 3;
		LL sqr = 1, single = 1;

		For(i, 2, r) if(x % i == 0){
			int c = 0;
			while(x % i == 0) x /= i, ++c;
			c %= 3;

			if(c == 1) single *= i;
			else if(c == 2) sqr *= i;
		}

		LL s = LL(sqrt(x) + 1e-9);
		if(s * s == x) sqr *= s;
		else single *= x;

		if(single * sqr > MAX / single){
			++ans;
			continue;
		}

		LL b = single * single * sqr, a = sqr * sqr * single;
		cnt[a]++;
		M[a] = b;

	}

	for(auto s : cnt){
		LL y = M[s.x];

		if(s.x == y){
			++ans;
			continue;
		}

		if(!cnt.count(y)) ans += s.y;
		else if(s.x > y) ans += max(s.y, cnt[y]);
	}

	printf("%d\n", ans);
	return 0;
}

