                else
                    len[i]++, a[i] *= ss;
            }
        }
    }
    for (int i = 1; i <= n; i++) id[i] = i;
    sort(id + 1, id + n + 1, cmp);
    for (int l = 1, r = 1; l <= n; l = r + 1, r = l) {
        while (r < n && a[id[r]] == a[id[r + 1]]) r++;
        if (a[id[l]] == 1) {
            ans++;
            continue;
        }
        int maxn = (1 << len[id[l]]) - 1;
        for (int i = l; i <= r; i++) ms[kind[id[i]]]++;
        for (int i = l; i <= r; i++) {
            int x = kind[id[i]], ot = (maxn ^ kind[id[i]]);
            if (ms[x] >= ms[ot]) ans += ms[x], ms[x] = ms[ot] = 0;
        }
    }
    printf("%d\n", ans);
    return 0;
}

