const int maxn=1e5+10;
int n;
int pri[maxn],fl[maxn];
IL void sieve(){
	rep(i,2,maxn-1){
		if(!fl[i])pri[++pri[0]]=i;
		for(int j=1;i*pri[j]<maxn;++j){
			fl[i*pri[j]]=1;
			if(i%pri[j]==0)break;
		}
	}
}
map<ll,int>num,rev,vis;
const ll MaxL=1e10;
ll R(ll a, ll b){return a>MaxL?a:b;}
int main(){
#ifdef LOCAL
	freopen("/home/noilinux/Desktop/input.txt","r",stdin);
#endif
	sieve();
	n=gi();
	rep(i,1,n){
		ll ai,X=1,Y=1;
		scanf("%lld",&ai);
		if(ai==1){num[1]++;rev[1]=1;continue;}
		for(int i=1;1ll*pri[i]*pri[i]*pri[i]<=ai;++i){
			int cnt=0;
			while(ai%pri[i]==0)ai/=pri[i],cnt++;
			if(cnt%3==1)X=X*pri[i],Y=R(Y,Y*pri[i]*pri[i]);
			else if(cnt%3==2)X=X*pri[i]*pri[i],Y=R(Y,Y*pri[i]);
		}
		if(ai!=1){
			ll val=sqrt(ai);
			if(val*val==ai)X=X*val*val,Y=R(Y,Y*val);
			else X=X*ai,Y=R(Y,Y*ai*ai);
		}
		num[X]++;
		if(Y<=MaxL){
			rev[X]=Y,rev[Y]=X;
		}
		else rev[X]=0; 
	}
	int ans=0;
	for(auto v:num){
		if(vis[v.fr])continue;
		if(v.fr==1)ans+=v.se!=0;
		else {
			if(num.count(rev[v.fr]))ans+=max(v.se,num[rev[v.fr]]),vis[rev[v.fr]]=1;
			else ans+=v.se;
		}
	}
	cout<<ans<<endl;
	return 0;
}

