    bool used[size] = {};
    for(ll i = 2; i < size; i++) {
        if(used[i]) continue;
        primes.push_back(i);
        pow2_p.push_back(i * i);
        for(ll j = 1; i * j < size; j++) used[i * j] = true;
    }
}

