        ll anti_num = 1;
        bool non = false;
        for(ll p : primes) {
            ll cube_p = p * p * p;
            if(1e10 < cube_p) break;
            while(e % cube_p == 0) e /= cube_p;
            ll cnt_div = 0;
            while(e % p == 0) {
                e /= p;
                cnt_div++;
            }
            for(ll i = 0; i < cnt_div; i++) save_e *= p;
            ll anti_cnt_div = (3 - cnt_div) % 3;
            for(ll i = 0; i < anti_cnt_div; i++) {
                anti_num *= p;
                if(1e10 < anti_num) {
                    non = true;
                    break;
                }
            }
            if(non) break;
        }
        if(!non && e != 1) {
            auto ite = lower_bound(ALL(pow2_p), e);
            if(ite == pow2_p.end() || *ite != e) non = true;
        }
        if(non) {
            ans++;
            continue;
        }
        DEBUG(make_tuple(e, anti_num));
        anti[save_e] = anti_num;
        cnt[save_e]++;
    }
    for(auto &&ele : cnt) {
        ll num, cnt_v;
        tie(num, cnt_v) = ele;
        ll anti_num = anti[num];
        DEBUG(make_tuple(num, anti_num, cnt_v));
        if(anti_num < num) continue;
        auto ite = cnt.find(anti_num);
        if(num == anti_num) ans++;
        else ans += max(cnt_v, (ite == cnt.end() ? 0 : ite->second));
    }
    cout << ans << endl;
    return 0;
}

