ll cube(ll n) { return n * n * n; }

ll norm(ll n) {
    ll norm = 1;

    //cerr << "norm " << n << ' ';

    for (ll p = 0; cube(p) <= n; p++) if (is_prime[p]) {
        int e = 0;

        while (n % p == 0) n /= p, e++;
        e %= 3;

        while (e > 0) norm *= p, e--;
    }

    norm *= n;

    //cerr << norm << endl;

    return norm;
}

ll comp(ll n) {
    ll m = 1;

    for (ll p = 0; cube(p) <= n; p++) if (is_prime[p]) {
        int e = 0;

        while (n % p == 0) n /= p, e++;
        e %= 3;

        e = (3 - e) % 3;
        while (e > 0) m *= p, e--;
    }


    if (sqrt.count(n)){
        m *= (ll)sqrt[n];
    } 
    else {
        if (m * n *n  < 0) {
            cerr << "comp " << n << ' ';
            cerr <<"n: "<<n << " m: "<< m << " " ;
            cerr << "sq " << sqrt[n] << " ";
            cerr <<"m*sq[n] "<< m << endl;
            cerr <<"m*n*n "<< m << endl;
            exit(0);
        }
        m *= n * n;
    }

    return m;
}

