    std::map<i64, int> c;
    for (int i = 0; i < n; i++) {
        i64 a;
        std::cin >> a;
        int j = std::upper_bound(cubes.begin(), cubes.end(), a) - cubes.begin() - 1;
        for (; j >= 0; j--) {
            if (a % cubes[j]) continue;
            c[a / cubes[j]]++;
            break;
        }
    }

    int ret = 0;
    std::map<i64, int> used;
    for (const auto &e : c) {
        i64 m = e.first, sq = m * m;
        if (used[m]) continue;
