long long Slove(long long n)
{
    for(vector<long long>::size_type i = 0; i < prime.size(); ++i)
    {
        if(prime[i] * prime[i] * prime[i] > n)
            break;
        while(n % (prime[i] * prime[i] * prime[i]) == 0)
            n /= prime[i] * prime[i] * prime[i];
    }
    return n;
}
