inline ll poww(ll x, int c){
  if(c == 1)return x;
  if(c == 0)return 1;
  if(c == 2)return x * x;
  return x;
}

ll fact(ll x){
  int p = 0;
  ll xx = 1;
  if(x % 2 == 0){
    while(x % 2 == 0){
      ++p;
      x /= 2;
    }
    p %= 3;
    xx = poww(2, p);
  }
  int sz = primes.size();
  for(int i = 1; primes[i] * primes[i] < x && i < sz; i++){
    if(x % primes[i] == 0){
      p = 0;
      while(x % primes[i]){
        ++p;
        x /= primes[i];
      }
      p %= 3;
      if(p != 0){
        xx *= poww(primes[i], p);
      }
    }
  }
  if(x > 1){
    xx *= x; 
  }
  return xx;
}

ll inv(ll x){
  ll xx = 1;
  int p = 0;
  while(x % 2 == 0){
    ++p;
    x /= 2;
  }
  p %= 3;
  if(p != 0){
    xx *= poww(2, 3 - p);
  }
  for(int i = 1; primes[i] * primes[i] < x; i++){
    if(x % primes[i] == 0){
      p = 0;
      while(x % primes[i] == 0){
        ++p;
        x /= primes[i];
      }
      p %= 3;
      if(p != 0){
        xx *= poww(primes[i], 3 - p);
      }
    }
  }
  if(x > 1){
    xx *= poww(x, 2);
  }
  return xx;
}

