void erast(){
    for(int i=0;i<=ma;i++){
        v[i] = 1;
    }
    for(int i=2;i*i<=ma;i++){
        if(v[i]){
            for(int j=0;i*(j+2)<=ma;j++){
                v[i*(j+2)]=0;
            }
        }
    }
    v[1] = false;
    for(ll i=2;i*i*i<=MAX;i++){
        if(v[i]){
            prime.push_back(i);
        }
    }
}

using P = pair<int,int>;

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    int N;
    erast();
    cin >> N;
    int ans = 0;
    map<vec<P>,int> mp;
    bool cube = false;
    for(int i=0;i<N;i++){
        ll s;
        cin >> s;
        ll n = s;
        map<int,int> m;
        for(ll x:prime){
            if(x*x>s) break;
            while(n%x==0){
                n /= x;
                m[x]++;
            }
        }
        if(n!=1 && prime.back()>=n) m[n]++;
        if(n<=prime.back()){
            vec<P> v;
            bool iscube = true;
            for(auto& x:m){
                if(x.second%3) v.emplace_back(x.first,x.second%3);
                iscube &= x.second%3==0;
            }
            if(iscube) cube = true;
            else if(!v.empty()) mp[v]++;
        }else{
            ll a = sqrt(n);
            if(a*a==n || n<ma){
                vec<P> v;
                for(auto& x:m) if(x.second%3) v.emplace_back(x.first,x.second%3);
                if(a*a==n) v.emplace_back(a,2);
                else v.emplace_back(n,1);
            }else ans++;
        }
    }
    ans += cube;
    int ans2 = 0;
    for(auto& v:mp){
        vec<P> other;
        for(auto& x:v.first) other.emplace_back(x.first,3-x.second);
        if(!mp.count(other)) ans += v.second;
        else ans2 += max(v.second,mp[other]);
    }
    ans += ans2/2;
    cout << ans << "\n";
}

