    cin >> m;
    for (int i = 0; i < m; ++i) {
        ll a;
        cin >> a;
        if (isCube(a)) {
            ++cube;
        } else {
            factor(a);
        }
    }
}

void solve() {
    read();

    for (auto u : cnt) {
        auto fu = u.first;

        if (used[fu]) {
            continue;
        }

        auto fv = fu;
        for (pll& p : fv) {
            p.second = 3 - p.second;
        }

        int ucnt = u.second;
        int vcnt = (cnt.count(fv) ? cnt[fv] : 0);

        ans += max(ucnt, vcnt);

        used[fu] = used[fv] = 1;
    }

    cout << ans + (cube > 0) << "\n";
}

