	return res;
} 
inline void Init(){
	vis[1]=1;
	for(rint i=2;i<=4000;++i) {
		if(!vis[i]) prime[++cnt]=i;
		for(rint j=1;j<=cnt&&i*prime[j]<=4000;++j) {
			vis[i*prime[j]]=1;
			if(i%prime[j]==0) break;
		}
	}
	for(rint i=1;i<=4000;++i)  {
		ll tmp=1ll*i*i*i;
		iscube[tmp]=1;
	}
}

int main(){
	cin>>N;
	for(rint i=1;i<=N;++i) cin>>A[i];
	Init();
	int ans=0;
	for(rint i=1;i<=N;++i) {
		ll tmp=A[i];
		if(iscube[tmp]) {ans=1;continue;}
		rev[i]=1,cur[i]=1;
		for(rint j=1;j<=cnt;++j) {
			int tot=0;
			while(tmp%prime[j]==0) tmp/=prime[j],++tot;
			tot%=3;
			cur[i]=cur[i]*ksm(prime[j],tot);
			rev[i]=rev[i]*ksm(prime[j],(3-tot)%3);
		}
		if(tmp==1) {
			gg[i]=1;
			mp[cur[i]]++;
			continue;
		}
		else {
			ll t=sqrt(tmp);
			if(t*t==tmp) {
				gg[i]=1;
				cur[i]*=tmp;
				rev[i]*=t;
				mp[cur[i]]++;
			}
