	}
	for(rint i=1;i<=N;++i) {
		if(iscube[A[i]]) {continue;}
		if(gg[i]) {
			ans+=max(mp[rev[i]],mp[cur[i]]);
			mp[rev[i]]=mp[cur[i]]=0;
		}
	}
	for(rint i=1;i<=N;++i) {
		if(!gg[i]) {
			ans+=mp[cur[i]];
			mp[cur[i]]=0;
		}
	}
	cout<<ans;
	return 0;
}

