void fill(){
	int sqr = 47;
	s.push_back(2);
	for (int i = 3; i <= 2200; i += 2){
		if(!prim[i]){
			if(i <= sqr)
				for (int j = i*i; j <= 2200; j += i)
					prim[j] = true;
			s.push_back(i);
		}
	}
}

ll sqr(ll x){
	ll l = 1,r = x/10;
	while(l <= r){
		ll mid = (l+r)/2;
		ll ans = mid*mid;
		if(ans < x) l = mid+1;
		if(ans > x) r = mid-1;
		if(ans == x) return mid;
	}
	return 0;
}

