	rep(i, N){
		int X;
		cin >> X;
		for (int j = 0; j < cube.size() && cube[j] <= X; j++)while (X % cube[j] == 0)X /= cube[j];
		if (X == 1)answer = 1;
		else{
			auto itr = ms.find(X);
			if (itr == ms.end())ms[X] = 1;
			else ms[X]++;
		}
	}

	ITR(x, ms){
		int X = x->first*x->first;
		for (int j = 0; j < cube.size() && cube[j] <= X; j++)while (X % cube[j] == 0)X /= cube[j];
		auto itr = ms.find(X);
		if (itr == ms.end())answer += x->second;
		else{
			answer += max(x->second, itr->second);
			ms.erase(itr);
		}
	}
	cout << answer << endl;

}

