#define EPS	1e-6
template <typename T> void read(T &x) {
	x = 0; int f = 1;
	char c = getchar();
	for (; !isdigit(c); c = getchar()) if (c == '-') f = -f;
	for (; isdigit(c); c = getchar()) x = x * 10 + c - '0';
	x *= f;
}
int n, tot, f[MAXN];
long long a[MAXN], prime[MAXN], cube[MAXN];
map <long long, long long> another;
map <long long, int> cnt;
int main() {
	int n; read(n);
	for (int i = 1; i <= n; i++)
		read(a[i]);
	for (int i = 2; i <= MAXS; i++) {
		if (f[i] == 0) {
			prime[++tot] = f[i] = i;
			cube[tot] = prime[tot] * prime[tot] * prime[tot];
		}
		for (int j = 1; prime[j] <= f[i] && j <= tot; j++) {
			int tmp = prime[j] * i;
			if (tmp > MAXS) continue;
			f[tmp] = prime[j];
		}
	}
	for (int i = 1; i <= n; i++) {
		for (int j = 1; j <= tot; j++)
			while (a[i] % cube[j] == 0)
				a[i] /= cube[j];
		long long product = 1, tmp = a[i];
		for (int j = 1; j <= tot; j++)
			if (tmp % prime[j] == 0) {
				tmp /= prime[j];
				if (tmp % prime[j] == 0) {
					tmp /= prime[j];
					product *= prime[j];
				} else product *= prime[j] * prime[j];
			}
		if (fabs((long long) sqrt(tmp) - sqrt(tmp)) <= EPS) product *= (long long) sqrt(tmp);
		else product *= tmp * tmp;
		another[a[i]] = product;
		cnt[a[i]]++;
	}
	cnt[1] = min(cnt[1], 1);
	int ans = 0;
	for (int i = 1; i <= n; i++) {
		long long tmp = another[a[i]];
		ans += max(cnt[a[i]], cnt[tmp]);
		cnt[a[i]] = cnt[tmp] = 0;
	}
	cout << ans << endl;
	return 0;
}

