		if(o > x) return x;
		for(;x % o == 0;x /= o);
	}
	exit(1);
}
inline ll rev(ll x) {
	static const ll none = 1145141919810;
	ll y = 1;
	for(ll j : p) {
		if(j > 10000) break;
		if(x % j == 0) {
			int c = 0;
			for(;x % j == 0;++ c) x /= j;
			if(c <= 2) y *= j;
			if(c <= 1) y *= j;
		}
	}
	ll p = round(sqrtl(x));
	if(p * p == x) y *= p, x = 1;
	if((long double) x * x <= 1e11) y *= x * x, x = 1;
	return x == 1 ? y : none;
}
