bitset<101010> isp; vector<ll> ps;
void init(int n){
   rep(i,2,n)isp[i]=1; ps.clear();
   rep(i,2,n)if(isp[i]){
      ps.push_back(i);
      for(ll j=1LL*i*i;j<n;j+=i)isp[j]=0;
   }
