ll calc(ll n){
   ll res=1,d=n;
   for(ll p:ps){
      if(p*p*p>n)break;
      if(n%(p*p)==0){
         res*=p; d/=(p*p);
      }
      else if(n%p==0){
         res*=(p*p); d/=p;
      }
   } return res*d*d;
}

