struct rpr{
  in x,y;
  rpr(in a=0, in b=0){
    x=a;
    y=b;
  }
  rpr sp()const{
    return rpr(y,x);
  }
  bool operator<(const rpr cp)const{
    if(x!=cp.x)
      return x<cp.x;
    return y<cp.y;
  }
};
const in ulm=in(1e10)+9;
const in crt=2500;
