void pr(in n){
  VI pm,pw;
  for(in i=2;i<=crt && i<=n;++i){
    if(n%i)
      continue;
    pm.PB(i);
    pw.PB(0);
    while(n%i==0){
      n/=i;
      ++pw.back();
    }
    pw.back()%=3;
  }
  if(n!=1 && n<crt*crt){
    pm.PB(n);
    pw.PB(1);
    n=1;
  }
  if(n>=crt*crt){
    in mn=crt-1;
    in mx=1e6;
