map<LL,int> ma;
map<LL,bool> v;
void pre()
{
	for(int i=2;i<M;i++)
	{
		if(b[i]==0) p[++pl]=i;
		for(int j=1;j<=pl;j++)
		{
			if(i*p[j]>=M) break;
			b[i*p[j]]=1;
			if(i%p[j]==0) break;
		}
	}
}
LL cal(LL x)
{
	if(x==1)
	{
		ans=1;
		return 1;
	}
	LL res=1;
	for(int i=1;i<=pl;i++)
		if(x%p[i]==0)
		{
			LL t=p[i]*p[i];
			if(x%t==0) x/=t,res*=p[i];
			else x/=p[i],res*=t;
		}
	LL q=sqrt(x);
	while(q*q>x) q--;
	if(q*q==x) res*=q;
	else res*=x*x;
	return res;
}
int main()
{
	pre();
	scanf("%d",&n);
	for(int i=1;i<=n;i++)
	{
