	int tot = 0;
	for (int i = 2; i <= 100000; i++) valid[i] = 1;
	for (int i = 2; i <= 100000; i++){
		if (valid[i]){
			pr[++tot] = i;
			for (int j = i * 2; j <= 100000; j += i) valid[j] = 0;
		}
	}
	for (int i = 1; i <= tot; i++) sqr[i] = 1LL * pr[i] * pr[i];
	int n, flag, sign, cnt, d, ans;
	long long temp, num, prod;
	scanf("%d",&n);
	for (int i = 1; i <= n; i++) scanf("%lld",&a[i]);
	ans = 0; flag = 0;
	for (int i = 1; i <= n; i++){
		num = prod = 1; temp = a[i]; sign = 0;
