			cnt = 0;
			while (temp % pr[j] == 0){
				cnt++;
				temp /= pr[j];
			}
			cnt %= 3;
			if (cnt == 1){
				num *= pr[j];
				prod *= pr[j] * pr[j];
			}
			else if (cnt == 2){
				num *= pr[j] * pr[j];
				prod *= pr[j];
			}
			if (prod > 10000000000){
				sign = 1;
				break;
			}
		}
		if (sign){
			ans++;
			continue;
		}
		if (temp > 1){
			d = lower_bound(sqr + 1, sqr + tot + 1, temp) - sqr;
