template<class T,class S> inline void ch(T &x,const S y){x=(x+y)%mod;}
inline ll mul(ll x,ll y,ll mod){
	ll ans=0;
	while(y){
		if(y&1) ans=(ans+x)%mod;
		x=x*2%mod;y>>=1;
	}return ans;
}
inline ll exp(ll x,ll y,const ll mod=::mod){
	int ans=1;
	while(y){
		if(y&1) ans=mul(ans,x,mod);
		x=mul(x,x,mod);y>>=1;
	}return ans;
}

int p[N],tot,n,ans,c11;
map<ll,int> c;

inline bool check(ll x){
	if(exp(2,x-1,x)!=1) return 0;
	if(exp(3,x-1,x)!=1) return 0;
	if(exp(5,x-1,x)!=1) return 0;
	return 1;
}

void calc(){
	ll x,a=1,b=1;read(x);
	for(int j=1;j<=tot;j++){
		int p=::p[j],cnt=0;
		while(x%p==0) x/=p,cnt=(cnt+1)%3;
		if(cnt){
			for(int k=0;k<cnt;k++) a*=p;
			for(int k=0;k<3-cnt;k++){
				b*=p;
				if(b>inf){ans++;return;}
			}
		}
	}
	if(x>100000&&check(x)){ans++;return;}
	if(x>1&&x<=100000){
		a*=x;b*=x;if(b>inf){ans++;return;}
		b*=x;if(b>inf){ans++;return;}
	}
	else if(x>100000){
		ll t=sqrt(x)+0.5;
		if(t*t==x) a*=x,b*=t; else{ans++;return;}
	}
	if(a==1){c11=1;return;}
//	dprintf("%lld %lld\n",a,b);
	ans-=max(c[a],c[b]);
	c[a]++;
	ans+=max(c[a],c[b]);
}

