using namespace std;

#define int long long

map<int, int> Cnt, Inv;

void mul(int &a, int b) {
	if(a == -1 || b == -1) {a = -1;return;}
	int r = a * b;
	if(r / b != a) {a = -1;return;}
	a = r;
}

int GetSquare(int x) {
	int sqr = sqrt(x);

	for(int d = 2; d >= -2; --d) {
		if((x + d) * (x + d) <= x)
			return x + d;
	}
}

pair<int, int> FactorizeAndReduce(int x) {
	int no = 1, inv = 1;

	for(int d = 2; d <= x && d <= 700; ++d) {
		if(x % d) continue;

		int e = 0;
		while(x % d == 0)
			x /= d, e += 1;
		e %= 3;

		if(e == 0) continue;
		if(e == 1) {
			mul(inv, d); mul(inv, d); mul(no, d);
		} else {
			assert(e == 2);
			mul(inv, d); mul(no, d); mul(no, d);
		}

	}

	if(x != 1) {
		int d = GetSquare(x);
		if(d * d == x) {
			mul(inv, d);
			mul(no, x);
		} else {
			mul(no, x);
			mul(inv, x);
			mul(inv, x);
		}
	}

	// cerr << no << " " << inv << '\n';
	return make_pair(no, inv);
}

int32_t main() {
	int n;
	cin >> n;

	int ans = 0;

	bool take1 = 0;

	for(int i = 1; i <= n; ++i) {
		int x;
		cin >> x;

		auto p = FactorizeAndReduce(x);
		if(p.first == 1) {
			if(take1) continue;
			take1 = 1;
			ans += 1;
		} else {
			Inv[p.first] = p.second;
			Cnt[p.first] += 1;
		}
	}

	while(Cnt.size()) {
		int no = Cnt.begin()->first;
		ans += max(Cnt[no], Cnt[Inv[no]]);
		Cnt.erase(Inv[no]);
		Cnt.erase(no);
	}

	cout << ans << endl;

	return 0;
}

