template<class Int> V<Int> sieve(Int a, Int b) {
  a = max<Int>(2, a); V<Int> res; Int q = ceil(sqrt(b));
  V<bool> mem(b - a, true), sub(q - 2, true);
  for (Int i = 2; i < q; ++i) {
    if (sub[i - 2]) {
      for (Int j = max(i, (a + i - 1) / i) * i; j < b; j += i) mem[j - a] = false;
      for (Int j = i * i; j < q; j += i) sub[j - 2] = false;
    }
  }
  for (Int i = a; i < b; ++i) if (mem[i - a]) res.push_back(i);
  return res;
}

int main() {
  cin.tie(nullptr); ios_base::sync_with_stdio(false);
  int n; cin >> n;
  V<lint> a(n); for (int i = 0; i < n; ++i) cin >> a[i];
  auto ps = sieve(2, 2154);
  for (int i = 0; i < n; ++i) {
    for (lint p : ps) {
      while (a[i] % (p * p * p) == 0) {
        a[i] /= p * p * p;
      }
    }
  }
  int res = 0;
  map<lint, int> mp;
  for (int i = 0; i < n; ++i) {
    if (a[i] == 1) {
      res = max(res, 1);
    } else {
      ++mp[a[i]];
    }
  }
  return cout << res << '\n', 0;
  ps = sieve<int>(2, 1e5);
  for (const auto& e : mp) {
    lint b = 1;
    for (lint p : ps) {
      if (e.first % p == 0) {
        b *= p;
        if (e.first % (p * p)) {
          b *= p;
        }
      }
    }
    if (!mp.count(b)) {
      res += e.second;
    } else if (e.first < b) {
      res += max(e.second, mp[b]);
    }
  }
  cout << res << '\n';
}

