const int MX = 100010;
bool p[MX];
int n;
ll s[MX];

vector<ll> comp(const vector<ll> &m){
	if(m.size() == 0) return m;
	vector<ll> res;
	rep(i, m.size()){
		if(i + 1 < m.size() && m[i] == m[i + 1]) res.pb(m[i++]);
		else { res.pb(m[i]); res.pb(m[i]); }
	}
	return res;
}

int main(){
	cin.tie(0); cin.sync_with_stdio(0);
	vi prime;
	for(int i = 2; i * i < MX; i++) if(!p[i]) for(int j = i * i; j < MX; j += i) p[j] = 1;
	for(int i = 2; i < MX; i++) if(!p[i]) prime.pb(i);

	cin >> n;
	rep(i, n) cin >> s[i];
	map<vector<ll>, int> M;
	int ans = 0;

	rep(ii, n){
		ll m = s[ii];
		vector<ll> v;

		for(int i = 0; i < prime.size() && (ll)prime[i] * prime[i] <= m; i++) if(m % prime[i] == 0){
			ll q = m / prime[i];
			int cnt = 0;
			for(; m % prime[i] == 0; cnt++) m /= prime[i];
			cnt %= 3;
			rep(it, cnt){
				v.pb(prime[i]);
				if(m != q) v.pb(q);
			}
		}
		if(m > 1) v.pb(m);
		sort(all(v));
		M[v]++;
	}
	for(auto m: M){
		auto mm = comp(m.first);
		if(m.first == mm) continue;
		int l = m.second, r = M[mm];
		ans += max(l, r);
	}
	ans /= 2;
	if(M.count(vector<ll>())) ans++;
	cout << ans << endl;
	return 0;
}

