#define MAXN 100000
#define MAXV 20000
using namespace std;
typedef long long LL;
vector<int> prime;
LL seq[MAXN+5],a[MAXN+5],b[MAXN+5];
bool vis[MAXV+5];
map<LL,int> mp;
void prepare()
{
	for(int i=2;i<=MAXV;i++)
	{
		if(vis[i]==false)
			prime.push_back(i);
		for(int j=0;1LL*prime[j]*i<=MAXV;j++)
		{
			vis[i*prime[j]]=true;
			if(i%prime[j]==0)
				break;
		}
	}
}
void Work(int i,LL x)
{
	a[i]=b[i]=1;
	for(int j=0;1LL*prime[j]*prime[j]*prime[j]<=x;j++)
	{
		LL t1=prime[j],t2=1LL*prime[j]*prime[j],t3=1LL*prime[j]*prime[j]*prime[j];
		while(x%t3==0)	x/=t3;
		if(x%t2==0)			a[i]*=t2,b[i]*=t1;
		else if(x%t1==0)	a[i]*=t1,b[i]*=t2;
		while(x%t1==0)	x/=t1;
	}
	if(x!=1LL)
	{
		LL t=(LL)sqrt(x);
		if(t*t==x)	a[i]*=x,b[i]*=t;
		else		a[i]*=x,b[i]*=x*x;
	}
}
int main()
{
//	freopen("anticube.in","r",stdin);
//	freopen("anticube.out","w",stdout);
	prepare();
	int N;
	scanf("%d",&N);
	for(int i=1;i<=N;i++)
	{
		scanf("%lld",&seq[i]);
		Work(i,seq[i]);
		mp[a[i]]++;
	}
	int ans=0;
	for(int i=1;i<=N;i++)
		if(mp.find(a[i])!=mp.end())
		{
			if(a[i]==b[i])
			{
				ans++;
				mp.erase(mp.find(a[i]));
			}
			else
			{
				int ansn=mp[a[i]];
				mp.erase(mp.find(a[i]));
				if(mp.find(b[i])!=mp.end())
				{
					ansn=max(ansn,mp[b[i]]);
					mp.erase(mp.find(b[i]));
				}
				ans+=ansn;
			}
		}
	printf("%d\n",ans);
	return 0;
}

