int cnt,prime[MAXN],visit[MAXN];

void Euler (int up){
	for (Int i = 2;i <= up;++ i){
		if (!visit[i]) prime[++ cnt] = i;
		for (Int j = 1;j <= cnt && i * prime[j] <= up;++ j){
			visit[i * prime[j]] = 1;
			if (i % prime[j] == 0) break; 
		}
	}
}

signed main(){
	read (n);Euler (1e5);
	for (Int i = 1;i <= n;++ i){
		read (s[i]);
		for (Int p = 2;p * p * p <= s[i];++ p) while (s[i] % (p * p * p) == 0) s[i] /= p * p * p; 
		if (s[i] != 1) tot[s[i]] ++;
		else ans = 1;
	}
	for (Int i = 1;i <= n;++ i) 
		if (vis[s[i]] || s[i] == 1) continue;
		else{
			int now = s[i],nowto = 1;
			for (Int j = 1;j <= cnt && prime[j] * prime[j] <= now;++ j)
				if (now % (prime[j] * prime[j]) == 0){
					now /= prime[j] * prime[j],nowto *= prime[j];
				}
			nowto *= now * now;
			vis[s[i]] = vis[nowto] = 1,ans += max (tot[s[i]],tot[nowto]);
		}
	write (ans),putchar ('\n');
	return 0;
