long long fpow(long long i,long long j,long long p)
{long long ret=1;
 for(;j;i=mul(i,i,p),j/=2)
 	if(j&1) ret=mul(ret,i,p);
 return ret;
}

long long pollard_rho(long long p,int seed)
{long long x,y,k,i,z;

 x=y=1;
 k=2;
 i=1;
 while(1)
 {	x=(mul(x,x,p)+seed)%p;
	if(x==y) return p;
	i++;
	z=gcd((y-x+p)%p,p);
	if(z!=1 && z!=p) return z;
	if(i==k)
	{	y=x;
		k*=2;
	}
 }
}

int check(long long p,long long x)
{long long y,i;
 if(p==x) return 1;
 i=p-1;
 while(!(i&1)) i/=2;
 x=fpow(x,i,p);
 while(1)
 {	if(i==p-1) return x==1;
 	y=mul(x,x,p);
 	i*=2;
 	if(y==1)
 	{	if(x!=1 && x!=p-1) return 0;
	 	return 1;
	}
	x=y;
 }
}

int miller_rabin(long long p)
{if(!check(p,2)) return 0;
 if(!check(p,3)) return 0;
 if(!check(p,7)) return 0;
 if(!check(p,61)) return 0;
 if(!check(p,24251)) return 0;
 return 1;
}

void find(vector<long long> &A,long long p)
{int seed;
 long long x;

 if(p==1) return;
 if(miller_rabin(p))
 {	A.push_back(p);
 	return;
 }
 seed=3;
 x=pollard_rho(p,seed);
 while(x==p) x=pollard_rho(p,++seed);
 find(A,x);
 find(A,p/x);
}

