		for (int j = 1; pr[j] < 3000; j++){
			cnt = 0;
			while (temp % pr[j] == 0){
				cnt++;
				temp /= pr[j];
			}
			cnt %= 3;
			if (cnt == 1){
				num *= pr[j];
				prod *= pr[j] * pr[j];
			}
			else if (cnt == 2){
				num *= pr[j] * pr[j];
				prod *= pr[j];
			}
			if (prod > 10000000000LL){
				sign = 1;
				break;
			}
		}
		if (sign){
			ans++;
			continue;
		}
		if (temp > 1){
			d = lower_bound(sqr + 1, sqr + tot + 1, temp) - sqr;
			if (sqr[d] == temp){
				num *= temp;
				prod *= pr[d];
				rec[num]++;
				sav[num] = prod;
			}
			else ans++;
		}
		else{
			if (prod == 1) flag = 1;
			else{
				rec[num]++;
				sav[num] = prod;
			}
		}
	}
	for (auto it : sav){
		ans += max(rec[it.first], rec[it.second]);
		rec[it.first] = 0;
		rec[it.second] = 0;
	}
	ans += flag;
	printf("%d\n", ans);
	return 0;
}

