ll calc_pair(ll x)
{
	ll res = 1;
	map<ll,int> fact;
	for(int i = 0;prime [i] * prime [i] * prime [i] <= x;i++){
		while(x % prime [i] == 0){
			fact [prime [i]]++;
			x /= prime [i];
		}
	}
	ll y = sqrt(x) + eps;
	if(y * y == x){
		res *= y;
	}
	else{
		res *= x * x;
	}
	for(auto&& it : fact){
		FOR(i,0,it.second){
			res *= it.first;
		}
	}

	return res;
}

