ll mul(ll a, ll b, ll c){
    ll ans = 0;
    a%=c;
    b%=c;
    for(;b;b>>=1){
        if(b&1){
            ans += a;
            if(ans > c) ans -= c;
        }
        a <<= 1;
        if(a > c) a -= c;
    }
    return ans;
}

ll qpow(ll a, ll b, ll c){
    ll ans = 1;
    a %= c;
    b %= c;
    for(;b;b>>=1){
        if(b&1) ans = mul(ans, a, c);
        a = mul(a, a, c);
    }
    return ans;
}

bool check(ll a, ll n, ll x, ll t){
    ll ret = qpow(a, x, n);
    ll last = ret;
    rep1(i,t){
        ret = mul(ret,ret,n);
        if(ret == 1 && last != 1 && last != n-1) return true;
        last = ret;
    }
    if(ret != 1) return true;
    else return false;
}

bool Miller_Rabin(ll n){
    if(n < 2) return false;
    if(n == 2) return true;
    if((n&1) == 0) return false;
    ll x = n-1;
    ll t = 0;
    while((x&1) == 0) {x >>= 1; t++;}

    srand(time(NULL));
    rep(i,S){
        ll a = rand() % (n-1) + 1;
        if(check(a,n,x,t))
            return false;
    }
    return true;
}

ll pollard_rho(ll x, ll c){
    ll i = 1, k = 2;
    srand(time(NULL));
    ll x0 = rand()%(x-1) + 1;
    ll y = x0;
    for(;;){
        ++i;
        x0 = (mul(x0,x0,x) + c) % x;
        ll d = abs(__gcd(y-x0, x));
        if(d != 1 && d != x) return d;
        if(y == x0) return x;
        if(i == k) {y = x0; k += k;}
    }
}

void findfac(ll n, int k){
    if(n == 1) return;
    if(Miller_Rabin(n)){
        factor[tol++] = n;
        return;
    }
    ll p = n;
    int c = k;
    while(p >= n) p = pollard_rho(p,c--);
    findfac(p, k);
    findfac(n/p, k);
}


