inline void jzp(int n){
	for(int x=2;x<=n;++x){
		if(!vis[x])pri.push_back(x);
		for(auto&y:pri){
			if((ll)x*y>n)break;
			vis[x*y]=1;
			if(!(x%y))break;
		}
	}
}

inline void get_norm(ll x){
	for(auto&y:pri){
		ll z=1ll*y*y*y;
		if(z>x)break;
		while(!(x%z))x/=z;
	}
	if(!Norm.count(x)&&!Pair.count(x))
		tmp.push_back(x);
	++Norm[x];
}

inline void get_pair(ll x){
	ll t=x,res=1;
	for(auto&y:pri){
		ll z=(ll)y*y*y;
		if(z<=t){
			while(!(x%z))x/=z;
			if(!(x%(y*y))){
				res*=y;
				x/=(y*y);	
			}
			else if(!(x%y)){
				res*=(y*y);
				x/=y;
			}
		}
		else{
			ll w=(ll)y*y;
			if(w>x){
				res*=((ll)x*x);
				break;
			}
			else if(!(x%y)){
				if(x==w)res*=y;
				else res*=((ll)x*x);
				break;
			}
		}
	}
	if(!Pair.count(res)&&!Norm.count(res))
		tmp.push_back(res);
	++Pair[res];
}

