const int MAX_SIZE = 100010;
bool isprime[MAX_SIZE];
vector<ll> prime_num;
vector<ll> cubed;
ll maximum = 10000000010;

void init() {
  fill(isprime, isprime+MAX_SIZE, true);
  isprime[0] = isprime[1] = false;
  for (auto i=2; i<MAX_SIZE; i++) {
    if (isprime[i]) {
      prime_num.push_back(i);
      ll x = i;
      ll y = x*x*x;
      if (y < maximum) cubed.push_back(y);
      for (auto j=2; i*j<MAX_SIZE; j++) {
        isprime[i*j] = false;
      }
    }
  }
}

bool prime(long long x) { // 2 \leq x \leq MAX_SIZE^2
  if (x < MAX_SIZE) {
    return isprime[x];
  }
  for (auto e : prime_num) {
    if (x%e == 0) return false;
  }
  return true;
}

int N;
ll s[100010];
map<ll, int> M;

ll conj(ll k) {
  ll ans = 1;
  for (auto x : prime_num) {
    int t = 0;
    while (k % x == 0) {
      k /= x;
      t++;
    }
    if (t == 1) {
      ans *= x * x;
    } else if (t == 2) {
      ans *= x;
    }
  }
  return ans;
}

int main() {
  init();
  cin >> N;
  int ans = 0;
  for (auto i = 0; i < N; i++) {
    cin >> s[i];
    for (auto x : cubed) {
      while (s[i]%x == 0) s[i] /= x;
    }
    ll t = s[i];
    for (auto x : prime_num) {
      while (t % x == 0) {
        t /= x;
        if (t == 1) goto EXIT;
      }
    }
  EXIT:
    // cerr << s[i] << " becomes " << t << endl;
    if (t > 1) {
      ans += 1;
    } else {
      if (M.find(s[i]) == M.end()) {
        M[s[i]] = 1;
      } else {
        M[s[i]]++;
      }
    }
  }
  set<ll> visited;
  for (auto x : M) {
    ll k = x.first;
    int num = x.second;
    // cerr << k << " " << num << endl;
    if (k == 1 && num > 0) {
      ans += 1;
      continue;
    }
    ll c = conj(k);
    // cerr << "conj(" << k << ") = " << c << endl;
    if (visited.find(c) != visited.end()) continue;
    if (M.find(c) == M.end()) {
      ans += num;
    } else {
      ans += max(num, M[c]);
      visited.insert(k);
    }
  }
  cout << ans << endl;
}

