class Number {
public:
	enum Type
	{
		Normal = 0,
		One,
		Big
	};
	s64 norm, pair;
	Number() { }
	Type Assign(s64 num) {
		norm = 1; pair = 1;
		for (auto prim : SetPrimes) {
			if (num == 1) break;
			int c = 0;
			while (num % prim == 0) { ++c; num /= prim; }

			c %= 3;

			if (c > 0) {
				for (int i = 0; i < c; ++i) norm *= prim;
				for (int i = 0; i < 3 - c; ++i) pair *= prim;
			}
		}

		if (num != 1) { norm *= num; return Big; }
		else if (norm == 1) return One;
		else return Normal;
	}
	Number Pair() const {
		Number _pair;
		_pair.norm = pair;
		_pair.pair = norm;
		return _pair;
	}
	bool operator<(const Number& b) const {
		return norm < b.norm;
	}
};

int main(int argc, char* argv[])
{
