#include <bits/stdc++.h>
using namespace std;


map<long long,int> pFactorize(long long n){
	map<long long,int> memo;

	for(long long i = 2 ; i <= 1000 ; i++){
		while(n%i==0){
			memo[i]++;
			n/=i;
		}
	}
	if(n>1){
		long long x = sqrt(n) + 0.5;
		if( x * x == n ){
			memo[x] += 2;
		}else{
			memo[n] = 1;
		}
	}
	map<long long,int> res;
	for( auto i : memo ) if( i.second % 3 ) res[i.first] = i.second % 3;
	return res;
}
map<long long,int> inv(map<long long,int> x){
	map<long long,int> res;
	for( auto i : x ) res[i.first] = 3 - i.second;
	return res;
}
void output(map<long long,int> t){
	cout << "{";
	for( auto e : t ) cout << e.first << ":" << e.second << ",";
	cout << "}" << endl;
}
void solve(long long N, vector<long long> s){
	map<map<long long,int>,int> ps;

	for(int i = 0 ; i < s.size() ; i++){
		auto t = pFactorize(s[i]);

		ps[t]++;
	}
	long long ans = 0;
	while(ps.size()){
		auto it = ps.begin();
