typedef long long ll;
typedef long double ld;
const int MAXN = 100005;
int pfac[MAXN]; // pfac[i] = largest prime factor of i
vector<pair<int, int>> factorize(int x) {
	vector<pair<int, int>> factors;
	while (x > 1) {
		int p = pfac[x];
		int cnt = 0;
		while (pfac[x] == p) {
			++cnt;
			x /= p;
		}
		factors.emplace_back(p, cnt);
	}
	return factors;
}
int main() {
	for (int i = 2; i < MAXN; ++i) pfac[i] = i;
	for (int i = 2; i < MAXN; ++i)
		if (pfac[i] == i)
			for (int j = i + i; j < MAXN; j += i)
				pfac[j] = i;
	int n;
	scanf("%d", &n);
	int ans = 0;
	vector<int> A(100001);
	for (int i = 0; i < n; ++i) {
		ll s;
		scanf("%lld", &s);
		if (s > 100000) ++ans;
		else A[s]++;
	}
	map<vector<pair<int, int>>, int> amt;
	for (int a = 1; a <= 100000; ++a) {
		if (!A[a]) continue;
		auto ps = factorize(a);
		vector<pair<int, int>> qs, rs;
		for (auto& p : ps) {
			p.second %= 3;
			if (p.second) qs.push_back(p);
		}
		amt[qs] += A[a];
	}
	for (auto& v : amt) {
		if (v.first.empty()) {
			++ans;
			continue;
		}
		vector<pair<int, int>> rs;
		auto& qs = v.first;
		for (auto& q : qs) {
			rs.emplace_back(q.first, 3 - q.second);
		}
		if (!amt.count(rs)) {
			ans += v.second;
		} else if (qs < rs) {
			ans += max(v.second, amt[rs]);
		}
	}
	printf("%d\n", ans);
}

