}
int main(){
	int i, j, ans = 0; LL mx = 0LL, c, d, t;
	scanf("%d", &n);
	for(i = 1; i <= n; ++ i){
		scanf("%lld", &a[i]);
		if(a[i] > mx) mx = a[i];
		reci[i] = 1;
	}
	for(c = 1; LL(c) * c <= mx; ++ c) ;
	for(i = 2; i < c; ++ i){
		if(!isComp[i]) p1[++ pcnt] = i;
		for(j = 1; i * p1[j] < c; ++ j)
			isComp[i * p1[j]] = true;
	}
	for(i = 1; i <= pcnt; ++ i){
		p2[i] = p1[i] * p1[i];
		p3[i] = p2[i] * p1[i];
	}
	for(i = 1; i <= n; ++ i){
		for(j = 1, t = a[i]; j <= pcnt && t >= p3[j]; ++ j){
			while(t % p3[j] == 0)
				t /= p3[j], a[i] /= p3[j];
			if(t % p2[j] == 0)
				t /= p2[j], reci[i] *= p1[j];
			else if(t % p1[j] == 0)
				t /= p1[j], reci[i] *= p2[j];
		} d = int(sqrt(t * 1.0) + 1e-5);
		if(d * d == t) reci[i] *= d;
		else reci[i] *= t * t;
		ord[i] = i;
	} sort(ord + 1, ord + 1 + n, cmp);
	for(i = 1; i <= n; ++ i) val[i] = a[ord[i]];
	ans = int(val[1] == 1LL) * 2;
	for(i = 1; i <= n && val[i] == 1; ++ i) ;
	for(; i <= n; i = j){
		for(j = i; val[i] == val[j]; ++ j) ;
		t = upper_bound(val + 1, val + 1 + n, reci[ord[i]]) - lower_bound(val + 1, val + 1 + n, reci[ord[i]]);
		if(t) ans += max(LL(j - i), t);
		else ans += (j - i) * 2;
	} printf("%d\n", ans / 2);
	return 0;
}

