int N ;
map<long long,int> Map ;
map<long long,int>::iterator It ;
map<long long,long long> Inv ;
inline long long Squ( long long A ) {
	return A * A ;
}
inline void Sim( long long &A ) {
	long long B = 1 , C = 1 ;
	for(register int i = 1 ; ++i <= 2333 ; ) {
		int Times = 0 ;
		while( A % i == 0 ) {
			A /= i ;
			++Times ;
		}
		Times %= 3 ;
		if( Times ) B *= i , C *= i ;
		if( Times == 1 ) C *= i ;
		if( Times == 2 ) B *= i ;
	}
	if( Squ( (long long)sqrt( A ) ) == A )
		C *= (long long)sqrt( A ) ;
	else
		C *= A * A ;
	A = A * B ;
	if( Inv[A] ) assert( Inv[A] == C ) ;
	Inv[A] = C ;
}
int main() {
	Readin( N ) ;
	for(register int i = 0 ; ++i <= N ; ) {
		long long A ;
		Readin( A ) ;
		Sim( A ) ;
		++Map[A] ;
	}
	int Ans = 0 ;
	for( It = Map.begin() ; It != Map.end() ; ++It ) {
		if( It->first == Inv[It->first] ) ++Ans ;
			else if( It->second >= Map[Inv[It->first]] ) {
				Ans += It->second ;
				Map[Inv[It->first]] = 0 ;
			}
	}
	cout << Ans << endl ;
	return 0 ;
}

