vector <ll> p;
bool sieve[MAXP];
int main()
{
    //freopen("input.txt", "r", stdin);

    for (ll i = 2; i < MAXP; i++)
    {
        if (sieve[i]) continue;
        p.push_back(i);
        for (ll j = i; j < MAXP; j+=i)
        {
            sieve[j] = true;
        }
    }


    int n;
    cin >> n;

    ll ans = 0;
    for (int j = 0; j < n; j++)
    {
        ll a;
        cin >> a;

        ll huj = 1;
        ll pzd = 1;
        for (ll i = 0; a > 1 && p[i] * p[i] <= a; i++)
        {
            ll pwd = 0;

            while(a % p[i] == 0)
            {
                pwd++;
                a/=p[i];
            }
            pwd %= 3;

          //  cout << p[i] << " " << pwd << endl;

            for (int j = 0; j < pwd; j++) huj*=p[i];
            for (int j = 0; j < (3-pwd)%3; j++) pzd*=p[i];
        }

        if (a > MAXP)
        {
            ans++;
            continue;
        }

        huj *= a;
        pzd *= a*a;

        m[huj]++;
        inv[huj] = pzd;

    //    cout << huj << " " << pzd << endl;
    }

//    cout << endl;
    for (auto it = m.begin(); it != m.end(); it++)
    {
  //      cout << it-> first << " " << it-> second << endl;
