int N;

vector<int> makePrimeLst(int N)
{
    vector<int> ans;
    vector<int> alive(N+1, 1);
    lint now = 2;
    for (; now * now <= N; now++)
    {
        if (alive[now]) ans.push_back(now);
        for (int t = now; t <= N; t += now) alive[t] = 0;
    }
    for (; now <= N; now++) if (alive[now]) ans.push_back(now);
    return ans;
}

// 素因数分解
map<lint, int> primeFactorize(lint N, const vector<int> &primeLst)
{
    map<lint, int> ans;
    for (auto v : primeLst)
    {
        while (!(N % v))
        {
            N /= v;
            ans[v]++;
        }
        if (N == 1) return ans;
    }
    ans[N]++;
    return ans;
    // exit(1);
}

vector<int> primes;

int main()
{
    primes = makePrimeLst(100000);
    cin >> N;
    map<set<lint>, pint> ma;
    REP(_, N)
    {
        set<lint> se[3];

        lint s;
        cin >> s;
        map<lint, int> facs = primeFactorize(s, primes);
        for (auto pa : facs) se[pa.second % 3].insert(pa.first);

        int flg;
        if (se[1].empty()) flg = 0;
        else if (se[2].empty()) flg = 1;
        else flg = (*se[1].begin() < *se[2].begin());

        set<lint> key;
        for (auto v : se[2 - flg]) key.insert(v);
        for (auto v : se[2 - !flg]) key.insert(-v);

        if (flg) ma[key].first++;
        else ma[key].second++;
    }

    int ans = 0;
    for (auto pa : ma)
    {
        if (!pa.first.empty()) ans += max(pa.second.first, pa.second.second);
        else ans++;
    }
    cout << ans << endl;
}

