vector<pair<long long, long long> > paired(vector<pair<long long, long long> > v)
{
	vector<pair<long long, long long> > res;

	for (int i = 0; i < v.size(); i++)
	{
		if (v[i].second == -1)
		{
			res.push_back(make_pair(-1, -1));
			return res;
		}
	}

	for (int i = 0; i < v.size(); i++)
	{
		res.push_back(v[i]);
		res[i].second = 3 - res[i].second;
		res[i].second %= 3;
	}

}

bool perf_square(long long x)
{
	long long val = sqrt(x + .5);
	return (val*val == x);
}

vector<pair<long long, long long> > parse(long long x)
{
	vector<pair<long long, long long> > res;

	for (int i = 0; i < primes.size(); i++)
	{
		if (x%primes[i])
			continue;
		int cnt = 0;
		while (x%primes[i] == 0)
		{
			cnt++;
			x /= primes[i];
		}
		if (cnt % 3 == 0)
			continue;
		res.push_back(make_pair(primes[i], cnt % 3));
	}
	if (x == 1)
		return res;
	if (perf_square(x))
	{
		int ss = sqrt(x + .5);
		res.push_back(make_pair(ss, 2));
		return res;
	}
	if (x <= 100000)
	{
		res.push_back(make_pair(x, 1));
		return res;
	}

	res.push_back(make_pair(1, -1));
	return res;
}
