void euler(int n) {
    rep(i, 2, n) {
        if (!mark[i]) p[++tot] = i;
        for (int j = 1; j <= tot && p[j] * i <= n; j++) {
            mark[p[j] * i] = 1;
            if (i % p[j] == 0) break;
        }
    }
}

