            while (k % j == 0) k /= j;
            // printf("%d %lld %lld %lld ?\n", j, a[i], b[i], k);
        }
        if (k > 1) {
            tmp = (ll)sqrt(k);
            if (tmp * tmp == k) a[i] *= k, b[i] *= tmp;
            else a[i] *= k, b[i] *= k * k;
        }
        // printf("%lld %lld !\n", a[i], b[i]);
    }
    rep(i, 1, n) num[a[i]]++;
    rep(i, 1, n) {
        if (vis[a[i]]) continue;
        vis[a[i]] = vis[b[i]] = 1;
        ans += (a[i] == b[i] ? 1 : max(num[a[i]], num[b[i]]));
    }
    printf("%lld\n", ans);
    return 0;
}

