		  while (c <= 32 && ~c) c = xchar();
		  if (c == -1) return -1;
		  for (;'0' <= c && c <= '9'; c = xchar()) x = x * 10 + c - '0';
		  return x;
	  }
	  inline int xint() {
		  int s = 1, c = xchar(), x = 0;
		  while (c <= 32) c = xchar();
		  if (c == '-') s = -1, c = xchar();
		  for (; '0' <= c && c <= '9'; c = xchar()) x = x * 10 + c - '0';
		  return x * s;
