using pii = pair<long long int, int>;

vector<pii> factor(long long int x) {
    vector<pii> f;
    for(long long int curp: p) {
        int dc = 0;
        while(x % curp == 0) {
            dc ++;
            x /= curp;
        }
        dc %= 3;
        if(dc != 0) {
            f.push_back(make_pair(curp, dc));
        }
    }
    if(x != 1) {
        f.push_back(make_pair(x, 1));
    }
    return f;
}

long long int a[100005];
