unordered_map<unsigned long long int, int> m;

const unsigned long long int PR = 23;
unsigned long long int Ehash(vector<pii> &v) {
    unsigned long long int s = 0;
    unsigned long long int g = 23;
    for(auto x: v) {
           g *= PR;
           s += g*static_cast<unsigned long long int>(x.first);
           g *= PR;
           s += g*static_cast<unsigned long long int>(x.second);
    }
    return s;
}

vector<pii> dual(vector<pii> &x) {
    vector<pii> d = x;
    for(int i = 0; i < d.size(); i++) {
        d[i].second = 3-d[i].second;
    }
    return d;
}
