bool isPrime(int n) {
    for (int i = 2; i * i <= n; ++i)
        if (n % i == 0) 
            return false;
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    for (int i = 2; i < 100000; ++i) {
        if (isPrime(i)) 
            primes.push_back(i);
    }
    cin >> n;
    vector<pair<int,int>> cur;
    int add = 0;
    int result = 0;
    for (int i = 0; i < n; ++i) {
        long long x;
        cin >> x;
        cur.clear();
        for (auto& y : primes) {
            if (y > 20000) break;
            int cnt = 0;
            while (x % y == 0) {
                x /= y;
                ++cnt;
            }
            cnt %= 3;
            if (cnt > 0) {
                cur.emplace_back(y, cnt);
            }
        }
        if (x > 1) {
            if (x > 100000) {
                ++result;
                continue;
            }
            if (binary_search(primes.begin(), primes.end(), x)) {
                cur.emplace_back((int)x, 1);  
                ++mp[cur];
                continue;
            }
            int y = sqrt(x + 0.5) + 0.001;
            if (1LL * y * y != x) {
                ++result;
            } else {
                cur.emplace_back(y, 2);
                ++mp[cur];
            }
        } else {
            if (cur.empty()) {
                add = 1;
                continue;
            }
            ++mp[cur];
        }
    }
    result += add;	
	result *= 2;
    for (auto& x : mp) {
        cur.clear();
        vector<pair<int,int>> now = x.first;
        for (auto& y : now) 
            cur.emplace_back(y.first, 3 - y.second);
        if (mp.count(cur))
            result += max(mp[now], mp[cur]);
        else
            result += 2 * x.second;
    }
    result /= 2;
    cout << result << endl;
    return 0;
}

