    int rt = sqrt(x);
    while (rt * (ll)rt < x) ++rt;
    while (rt * (ll)rt > x) --rt;
    return rt * (ll)rt == x ? rt : -1;
  };
  function<ll(ll)> dual = [&](ll x) {
    ll fact = 1;
    for (int p : pr)
