pair< long long, long long > gg ( long long x ) {
    long long a = 1, b = 1;

    for ( int i = 0 ; prs[i]*prs[i] <= x ; i ++ ) {

        if ( x%prs[i] == 0 ) {
            int cnt = 0;
            for ( ; x%prs[i] == 0 ; cnt ++ ) {
                x /= prs[i];
            }
            cnt %= 3;
            for ( int c = 0 ; c < cnt ; c ++ ) { a *= prs[i]; }
            cnt = (3-cnt)%3;
            for ( int c = 0 ; c < cnt ; c ++ ) { b *= prs[i]; }

        }
    }

    if ( x != 1 ) {
        a *= x;
        b *= x*x;
    }
    return make_pair( a, b );
}

