long long pw(long long x,long long y,long long p)
{
	x%=p;
	long long res=1;
	while (y)
	{
		if (y&1)
		{
			res=res*x%p;
		}
		x=x*x%p;
		y>>=1;
	}
	return res;
}
long long mul(long long x,long long y,long long p)
{
	x%=p;
	long long res=0;
	while (y)
	{
		if (y&1)
		{
			res=(res+x)%p;
		}
		x=x*2%p;
		y>>=1;
	}
	return res;
}
