        t /= prime_v[j];
        f[j] = 1;
      }else{
        f[j] = 0;
      }
    }

    ll q = 1;

    auto it = sq.find(t);

    if(it != sq.end()){
      q = it->second; 
    }else if(t > 1){
      q = t*t;

      if(q > 1e10){
        ans += mm[s[i]];
