long long isqrt(long long x){
	long long a=x;
	for(;;){
		long long b=(a+x/a)/2;
		if(b>=a){
			return a;
		}else{
			a=b;
		}
	}
}


bool issq(long long x){
	long long a=isqrt(x);
	return a*a==x;
}

numtype normalize(long long x){
	long long K=2200;
	long long K1=1200,K2=3000;
	for(long long i=2;i<=K;i++)for(;x%(i*i*i)==0;)x/=i*i*i;
	long long p=1,q=1;
	for(long long i=1;i<=K1;i++){
		if(i%4!=0 && i%9!=0 && x%i==0 && issq(x/i)){
			//printf("x,i=%lld,%lld\n",x,i);
			q*=isqrt(x/i);
			for(long long d=2;d*d<=i;d++){
				for(;i%(d*d)==0;){i/=d*d;q*=d;}
				for(;i%d==0;){i/=d;p*=d;}
			}
			if(i>1)p*=i;
			return make_pair(p,q);
		}
	}

	for(long long d=2;d<=K2;d++){
		for(;x%(d*d)==0;){x/=d*d;q*=d;}
	}
	p*=x;
	return make_pair(p,q);
}

numtype inv(numtype x){
	return make_pair(x.second,x.first);
}

bool istriv(numtype x){return x==make_pair(1LL,1LL);}

main(){
	int n;
	scanf("%d",&n);
	vector<long long> aa(n);

	for(int i=0;i<n;i++)scanf("%lld",&aa[i]);

	vector<numtype> a(n);
	map<numtype,int> cnt;
	for(int i=0;i<n;i++)a[i]=normalize(aa[i]);
	for(int i=0;i<n;i++)cnt[a[i]]++;

	//for(int i=0;i<n;i++)printf("%lld %lld\n",a[i].first,a[i].second);
	//puts("a");
	int ans=0;

	for(map<numtype,int>::iterator ite=cnt.begin();ite!=cnt.end();ite++){
		numtype d=(*ite).first;
		if(istriv(d)){
			ans++;
		}else{
			numtype dd=inv(d);
			if(cnt.count(dd)==0 || d<dd){
				ans+=max(cnt[d],cnt[dd]);
			}
		}
	}
	printf("%lld\n",ans);
}

