			{
				cntp++;
				t[cntp]=pii(pri[i],0);
				for(;x%pri[i]==0;x/=pri[i])
					t[cntp].y++;
				if((t[cntp].y%=3)==0)cntp--;
			}
		if(x>=M){t[++cntp]=pii(x,1);return;}

		for(;x>1;x=nxt[x])
