LL Rev(LL v) {
  LL ret = 1;
  for (LL p : ps) {
    int e = 0;
    while (v%p == 0) {
      e++;
      v /= p;
    }

    assert(e <= 2);
    if (e == 1) ret *= p*p;
    else if (e == 2) ret *= p;
  }

  if (1 < v) { 
    assert(v > 2000);
    if (sq.count(v)) v = sq[v];
    else return -1;
    ret *= v;
  } 

  return ret;
}

