	int mr(ll n){
	    if(n<=1)return 0;
	    for (int i=0,a;i<9;i++){
		if((a=pr[i])==n)return 1;
		ll t=n-1;int k=0;
		while(~t&1)t>>=1,k++;
		ll c=qp(a,t,n);
		if(c==1)continue;
		int bo=0;
		for (int i=0;i<k;i++){
		    if(c==n-1){bo=1;break;}
		    c=mul(c,c,n);
		}
		if(!bo)return 0;
	    }
	    return 1;
	}
	void rho(ll n){
	    if(mr(n))tmp[++tot]=n;
	    else{
		for (int c=12345;;c++){
		    ll x=0,y=0;
		    while(1){
			x=(mul(x,x,n)+c)%n;
			y=(mul(y,y,n)+c)%n;
			y=(mul(y,y,n)+c)%n;
			ll d=gcd(n,abs(x-y));
			if(d!=1){
			    if(d!=n){
				rho(d);
				rho(n/d);
				return;
			    }else break;
			}
		    }
		}
	    }
	}
	void facto(ll n){
		tot=0;
		for (int i=0;i<9;i++)while(n%pr[i]==0){
		    tmp[++tot]=pr[i];
		    n/=pr[i];
