		if(n>1)rho(n);
		sort(tmp+1,tmp+1+tot);
		ptot=0;
		for (int i=1;i<=tot;i++)
			if(i==1 || tmp[i]!=tmp[i-1]){
				ps[++ptot]=tmp[i];
				ds[ptot]=1;
			}else ds[ptot]++;
	}
};

