  REP(i, N) {
    ll s = nextLong();
    ++mp[ factorize(s) ];
  }
  ll ans = 0;
  for (auto it = mp.begin(); it != mp.end(); ++it) {
    const auto a = it->first;
    const int ca = it->second;
    if (a.size() == 0) {
      if (ca > 0) ans++;
      continue;
    }
    const auto b = inverse(a);
    const int cb = mp[b];
    if (cb == 0) ans += ca;
    else if (a < b) {
      ans += max( ca, cb );
    }
  }
  cout << ans << endl;
  return 0;
}

