			long long V = 1LL * i*i*i*t[j];
			if (V > 10000000000LL) { u1[j] = 1; continue; }
			u2[cnt] = (V << 17) + j; cnt++;
		}
		radix_sort(); long long LL = 0;
		for (int j = 0; j < cnt; j++) {
			while (vec.size() > LL && vec[LL].first < (u2[j] >> 17)) LL++;
			if (LL == vec.size())break;
			if (vec[LL].first == (u2[j] >> 17))p[u2[j] & ((1 << 17) - 1)][i] = true;
		}
	}
	for (int i = 0; i < n; i++) {
		if (t[i] == 1 || used[i] == true)continue;
		num[0] = 0; num[1] = 0;
		dfs(i, 0); ret += max(num[0], num[1]);
	}
	cout << ret + K << endl;
	return 0;
}

