set<int> p;

int sqrt(int x){
	int l = 0, r = 1e9, res = 0;
	while(l <= r){
		int mid = (l + r) >> 1;
		if(mid * mid <= x) res = mid, l = mid + 1;
		else r = mid - 1;
	}
	return res;
}

int cbrt(int x){
	int l = 0, r = 1e6, res = 0;
	while(l <= r){
		int mid = (l + r) >> 1;
		if(mid * mid * mid <= x) res = mid, l = mid + 1;
		else r = mid - 1;
	}
	return res;
}

bool prime(int x){
	if(x < 2) return false;
	else if(x > 2){
		if(x % 2 == 0) return false;
		else for(int i = 3; i * i <= x; ++i) if(x % i == 0) return false;
	}
	return true;
}

void preset(){
	ios::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);
	cin >> n;
	for(int i = 1; i <= n; ++i) {
		cin >> a[i];
		++cnt[a[i]];
		int x = cbrt(a[i]);
		if(x * x * x == a[i]){
			ans |= 1;
			took[a[i]] = true;
		} 
	}
	for(int i = 2; 1LL * i * i * i <= 1e10; ++i)
		if(prime(i)) p.insert(i);
}

int complement(int x){ // calculate cubic complement
	int res = 1;
	for(auto num: p){
		int e = 0;
		while(x % num == 0) x /= num, e = (e + 1) % 3;
		e = (3 - e) % 3;
		while(e--)
			res = min(res * num, MAX);
	}
	int f = sqrt(x);
	if(f * f == x){
		res = min(res * x, MAX);
	}else{
		if(res * x > MAX / x) res = MAX;
		else res *= x * x;
	}
	return (res == MAX ? -1 : res);
}

signed main(){
	preset();
	for(int i = 1; i <= n; ++i){
		if(!took[a[i]]){
			int val = complement(a[i]);
			if(val == -1){
				ans += cnt[a[i]];
				took[a[i]] = true;
				continue;
			}
			if(!took[val]){
				ans += max(cnt[a[i]], cnt[val]);
				if(cnt[a[i]] >= cnt[val]) took[a[i]] = true;
				else took[val] = true;
			}
		}
	}
	cout << ans;
}

