    out[0]=out[1]=true;
    for(int i=2; i<=100000; i++){
        if(out[i]) continue;
        P.push_back(i);
        for(ll j=i; j*i<=100000; j++)
            out[j*i]=true;
    }
    for(int p:P)
        if(1LL*p*p*p<=1e10)
            C.push_back(1LL*p*p*p), Q.push_back(p);
}

ll inv(ll x){
    ll res=1;
    for(int p:Q){
        if(x%p!=0) continue;
        ll pp=1LL*p*p, mul=1;
        if(x%pp==0){
            x/=pp; mul=p;
        }
        else if(x%p==0){
            x/=p; mul=pp;
        }
        if(mul>=inf/res){
            return -1;
        }
        res*=mul;
    }
    if(x>1) return -1;
    return res;
}

ll red(ll x){
    for(ll c:C)
        while(x%c==0)
            x/=c;
    return x;
}

