void addPrimes() {
    for (int i = 3; i <= 100000; i += 2) {
        bool fl = true;
        for (long j: primes) {
            if (i % j == 0) {
                fl = false;
                break;
            }
        }
        if (fl) primes.push_back(i);
    }
}

void addCubes() {
    for (long i = 1; i * i * i <= 10000000000l; i++) {
        cubes[i * i * i]++;
    }
}

long getminp(long p, long start) {
    REPI(i, start, primes.size()) if (p % primes[i] == 0) return primes[i];
    return p;
}

VP fctr(long s) {
    VP v;
    long p = 2;
    while (s != 1) {
        p = getminp(s, p);
        long cn = 0;
        while (s % p == 0) {
            s /= p;
            cn++;
        }
        if (cn % 3) {
            v.push_back(P(p, cn % 3));
        }
    }
    return v;
}

long cnt = 0;
map<VP, long> m;

void hoge(VP f) {
    if (m[f] == 0) return;
    VP v;
    for (P a: f) {
        v.push_back(P(a.first, (3 - a.second) % 3));
    }
    cnt += max(m[f], m[v]);
    m[f] = 0;
    m[v] = 0;
}

