ll factor[100][2];
int fatCnt;
int getFactors(ll x){
    fatCnt = 0;
    ll tmp = x;
    for(int i = 1; prime[i] <= tmp / prime[i]; ++i){
        factor[fatCnt][1] = 0;
        if(tmp % prime[i] == 0){
            factor[fatCnt][0] = prime[i];
            while(tmp % prime[i] == 0){
                factor[fatCnt][1]++;
                tmp /= prime[i];
            }
            fatCnt++;
        }
    }
    if(tmp != 1){
        factor[fatCnt][0] = tmp;
        factor[fatCnt++][1] = 1;
    }
    return fatCnt;
}

