    for (int i=0; i<n; i++) {
    	ll pr=compute_pair(input[i]), nm=compute_norm(input[i]);
    	if (pr==1) {
    		if (inserted_one==false) ans++, inserted_one=true;
    	}
    	else mmap[point(pr, nm)]++;
    }

    while (!mmap.empty()) {
    	map<point, int>::iterator i1=mmap.begin();
    	map<point, int>::iterator i2=mmap.find(point(i1->first.second, i1->first.first));

    	if (i2==mmap.end()) {
    		ans+=i1->second;
    		mmap.erase(i1);
    	}
    	else {
    		ans+=max(i1->second, i2->second);
    		mmap.erase(i1);
    		if (i1!=i2) mmap.erase(i2);
