			FOR(k, 0, cnt)
			{
				if (r2 >= MAX1) continue;
				r2 *= p;
			}
		}
	}

	if (a != 1)
	{
		r1 *= a;
		if (r2 * (double)a * (double)a > 4 * MAX1)
		{
			r2 = MAX1;
		}
		else
		{
			r2 = r2 * a * a;
		}
	}

	return MP(r1, r2);
}

