#define int long long

long long MAX_PRIME = 3000;
vector<long long> primes;

typedef pair<string, int> Num;
map<long long, int> toIdx;
vector<Num> nums;

void addNum(long long x)
{
	Num num = {"", 0};
    for (long long p : primes) {
        if (x % p) continue;
        int r = 0;
        while (x % p == 0) {
            x /= p;
            ++r;
        }
		r %= 3;
		if (r > 0) {
            int i = toIdx[p];
            num.first += char(i);
            num.second = num.second * 2 + (r - 1);
		}
    }

    int y = sqrt(x);
    if (x == 1) {
		nums.push_back(num);
		return;
    }
    if (y * y == x) {
        if (toIdx.find(y) == toIdx.end()) toIdx[y] = toIdx.size();
        num.first += char(toIdx[y]);
        num.second = num.second * 2 + 1;
        nums.push_back(num);
    } else {
        if (toIdx.find(x) == toIdx.end()) toIdx[x] = toIdx.size();
        num.first += char(toIdx[x]);
        num.second = num.second * 2;
        nums.push_back(num);
    }
}

void printNum(Num n)
{
    for (char ch : n.first) cerr << long(ch);
    cerr << " " << n.second << endl;
}

signed main()
{
	// Initialize
	vector<bool> isPrime(MAX_PRIME + 1, 1);
	for (long long i = 2; i <= MAX_PRIME; ++i) {
		if (isPrime[i]) {
			toIdx[i] = primes.size();
			primes.push_back(i);
			for (long long j = i + i; j <= MAX_PRIME; j+=i) {
                isPrime[j] = 0;
			}
		}
	}

    int n;
    cin >> n;
    nums.reserve(n);
    for (int i = 0; i < n; ++i) {
        int x;
        cin >> x;
        addNum(x);
    }

    sort(nums.begin(), nums.end());

//    for (Num n : nums) printNum(n);
//    cerr << endl;

    int ans = n;
    for (int i = 0; i < nums.size(); ++i) {
		int si = i, ei = i;
        while (ei+1 < nums.size() && nums[si].first == nums[ei+1].first) ++ei;
        i = ei;
        int bitsum = (1 << nums[si].first.size()) - 1;

		if (nums[si].first.size() == 0) {
			ans -= (ei - si);
			continue;
		}

        while (1) {
            while (si < ei && nums[si].second + nums[ei].second != bitsum) {
                if (nums[si].second + nums[ei].second < bitsum) ++si;
                else --ei;
            }
            if (si >= ei) break;

			if (nums[si].second == nums[ei].second) {
                ans -= (ei - si);
                break;
			}

            int lc = 1, rc = 1;
            while (nums[si].second == nums[si+1].second) {
				++si;
				++lc;
            }
            while (nums[ei].second == nums[ei-1].second) {
				--ei;
				++rc;
            }

            ans -= min(lc, rc);

            ++si; --ei;
        }
    }
	cout << ans << endl;
}

