typedef long long ll;
const int N = 1e5 + 100, M = 2200;

ll n, ans, a[N];
bool prime[N];
vector<int> vec;
map<ll, ll> cnt, b;
map<ll, bool> ok;

int main() {
	ios::sync_with_stdio(false), cin.tie(0);
	fill(prime + 2, prime + N, true);
	for (int i = 2; i < N; i++)
		if(prime[i]) {
			for (int j = i << 1; j < N; j += i)
				prime[j] = false;
			if(i < M)
				vec.push_back(i);
			ok[1LL * i * i] = true;
		}
	cin >> n;
	for (int i = 0; i < n; i++) {
		cin >> a[i];
		ll help = 1, HELP = 1;
		for (int x: vec) {
			int cnt = 0;
			while(a[i] % x == 0)
				a[i] /= x, cnt++;
			if(cnt % 3 == 1)
				HELP *= x, help *= x * x;
			else if(cnt % 3 == 2)
				help *= x, HELP *= x * x;
		}
		cnt[a[i] * HELP]++;
		if(ok[a[i]])
			help *= sqrt(a[i]);
		else
			help *= a[i] * a[i];
		b[a[i] * HELP] = help;
	}
	for (auto p: cnt)
		if(p.first == 1)
			ans += (p.second > 0);
		else if(p.first < b[p.first])
			ans += max(cnt[p.first], cnt[b[p.first]]);
	cout << ans;
	return 0;
}

