    vi primes;
    mii unsquare;
    const int MED = 2200;
    const int BIG = 1e5+5;
    vi sieve(BIG);
    FOR(p, 2, BIG) {
        if (!sieve[p]) {
            if (p < MED) primes.push_back(p);
            unsquare[p*p] = p;
            for (int u=p*p; u<BIG; u+=p) {
                sieve[u] = p;
            }
        }
    }

    mii occ;
    FOR(i, 0, n) {
        for (int p : primes) {
            while (a[i] % (p*p*p) == 0) {
                a[i] = a[i]/p/p/p;
            }
        }
        ++occ[a[i]];
    }

    mii mp;
    for (pii pr : occ) {
        int x = pr.first;
        if (x != 1) {
            int y = 1;
            for (int p : primes) {
                if (x % p == 0) {
                    if (x % (p*p) == 0) {
