const ll MAXC=cbrt(1e10),sqC=1e5,C=1e10;
unordered_map<ll,pll> mp;
vector<ll> p;
int prime[MAXC+5];

int main()
{
    IOS();
    ll n,ans=0,bonus=0;
    for(int i=2;i<=MAXC;++i)
    {
        if(!prime[i])
            p.pb(i);
        for(ll j:p)
        {
            if(j*i>MAXC) break;
            prime[j*i]=j;
            if(i%j==0) break;
        }
    }
    cin >> n;
    for(int i=1;i<=n;++i)
    {
        ll x,v=1,flag=0;
        __int128 rv=1;
        cin >> x;
        for(ll j:p)
            if(x%j==0)
            {
                ll cnt=0;
                while(x%j==0) x/=j,++cnt;
                cnt%=3;
                if(cnt==1)
                    rv*=j*j,v*=j;
                else if(cnt==2)
                    rv*=j,v*=j*j;
            } 
        if(x==1&&v==1)
        {
            ++bonus;
            continue;
        }
        if(x!=1)
            if(x<=sqC)
                v*=x,rv*=x*x;
            else
            {
                ll sq=sqrt(x);
                if(sq*sq==x)
                    v*=x,rv*=sq;
                else
                    flag=1;
            }
        if(rv>C||flag)
            ++ans;
        else
        {
            auto q=mp.find(v);
            if(q!=mp.end()) ++q->Y.Y;
            else mp[v]=pll(rv,1);
        }
    }
    while(!mp.empty())
    {
        auto q=*mp.begin();
        mp.erase(mp.begin());
        ans+=max(q.Y.Y,mp[q.Y.X].Y);
        mp.erase(q.Y.X);
    }
    cout << ans+!!bonus << "\n";
}

