const int maxn = 100010;
LL p[maxn], n;


int sp[maxn];
vector<LL> prime;
int main() {
  #ifdef _TEST_
  freopen("input.txt", "r", stdin);
  //freopen("out.txt", "w", stdout);
  #endif
  scanf("%lld", &n);
  rep(i, n) scanf("%lld", &p[i]);
  map<LL, int> s;
  rep(i, n) {
    for (LL j = 2; j * j * j <= p[i]; j ++) {
      LL t = j * j * j;
      while (p[i] % t == 0) p[i] /= t;
    }
    s[p[i]] ++;
  }
  int res = s.count(1);
  s.erase(1);

  rep(i, 2, maxn) if (!sp[i]) {
    prime.pb(i);
    for (int j = i + i; j < maxn; j += i)
      sp[j] = 1;
  }
  //for (auto i : s) {
    //cout << i.fr << ' ' << i.sc << endl;
  //}
  for (auto i : s) {
    LL t = i.fr, r = 1;
    for (LL c: prime) {
      if (t % c == 0) {
        if (t % (c * c) == 0) r *= c, t /= c * c;
        else r *= c * c, t /= c;
      }
      if (c * c > t) break;
    }
    if (t >= maxn) {
      res += i.sc;
      continue;
    }
    r *= t * t;
    auto it = s.find(r);
    if (it != s.end()) res += max(it->sc, i.sc), s.erase(it);
    else res += i.sc;
  }
  cout << res << endl;
  return 0;
