int power(int x, int n, int p) {
	int res = 1;
	while (n > 0) {
		if (n & 1) res = (res * x) % p;
		x = (x * x) % p;
		n /= 2;
	}
	return res;
}

int power(int x, int n) {
	int res = 1;
	while (n > 0) {
		if (n & 1) res = (res * x);
		x = (x * x);
		n /= 2;
	}
	return res;
}

bool sv[100005];
vector<int> primes;

int sieve(int n) {
	For(i,1,n) sv[i] = true;
	sv[1] = false;
	For(i,2,n) {
		if (sv[i]) {
			primes.pb(i);
			for (int j = i * 2; j <= n; j += i) sv[j] = false; 
		}
	}
}

int Mod(int x, int p) {
	x %= p;
	while (x < 0) x += p;
	return x;
}

pii Hash(int n) {
	int res = 1, rev = 1;
	for (int p: primes) {
		int a = 0;
		while (n % p == 0) n /= p, a++;
		res *= power(p, Mod(a, 3));
		rev *= power(p, Mod(3 - a, 3));
		if (n == 1) break; 
	}
	if (n > 1) res = n, rev = n;
	return mp(res, rev);
}

