// primality checking taken from anta's library
ll modmult(ll x, ll y, ll MOD) {
	ll a = x, r = 0;
	while(y) {
		if(y & 1)
			if((r += a) >= MOD) r -= MOD;
		if((a += a) >= MOD) a -= MOD;
		y >>= 1;
	}
	return r;
}
ll powmodll(ll a, unsigned long long k, const ll MOD) {
	a %= MOD;
	ll r = MOD == 1 ? 0 : 1;
	while(k) {
		if(k & 1)
			r = modmult(r, a, MOD);
		a = modmult(a, a, MOD);
		k >>= 1;
	}
	return (unsigned)r;
}

bool isPrime(long long p,int iteration){
    if(p<2){
        return false;
    }
    if(p!=2 && p%2==0){
        return false;
    }
    long long s=p-1;
    while(s%2==0){
        s/=2;
    }
    for(int i=0;i<iteration;i++){
        long long a=rand()%(p-1)+1,temp=s;
        long long mod=powmodll(a,temp,p);
        while(temp!=p-1 && mod!=1 && mod!=p-1){
            mod=modmult(mod,mod,p);
            temp *= 2;
        }
        if(mod!=p-1 && temp%2==0){
            return false;
        }
    }
    return true;
}
