void get_fg(__int128 x, __int128 &f, __int128 &g)
{
	for (__int128 i = 2; i*i*i <= x; ++i)
	{
		if(x%i == 0)
		{
			int ctr = 0;
			while(x%i == 0)
			{
				x/=i;
				ctr++;
			}
			ctr%=3;
			for (int j = 0; j < ctr; ++j)
				f*=i;
			ctr = (3 - ctr)%3;
			for (int j = 0; j < ctr; ++j)
				g*=i;
		}
	}
	if(x > 1)
	{
		if(isPrime(x, 10))
		{
			f*=x;
			g*=(x*x);
		}
		else
		{
			__int128 temp = get_sqrt(x);
			if(temp == -1)
			{
				f*=x;
				g*=(x*x);
			}
			else
			{
				f*=x;
				g*=temp;
			}
		}
	}
}
int main()
{
	int n;
	scanf("%d", &n);
	int ans = 0;
	__int128 ub = 10000000000ll;
	for (int i = 0; i < n; ++i)
	{
		long long int x;
		__int128 f = 1, g = 1;
		scanf("%lld", &x);
		get_fg(x, f, g);
		if(g > ub)
		{
			ans++;
		}
		else
		{
			M[f]++;
			S.insert(pll(min(f,g),max(f,g)));
		}
		// cout<<(long long int)f<<" "<<(long long int)g<<"\n";
	}
	for (set <pll>::iterator it = S.begin(); it != S.end(); ++it)
	{
		long long int f = (*it).first, g = (*it).second;
		if(f == g)
		{
			if(M.find(f) != M.end())
				ans++;
		}
		else
		{
			if(M.find(f) != M.end())
				f = M[f];
			else
				f = 0;
			if(M.find(g) != M.end())
				g = M[g];
			else
				g = 0;
			ans+=max(f,g);
		}
	}
	printf("%d\n", ans);
	return 0;
}

