		FI(j, 1, p){
			LL u = 1LL * pr[j] * pr[j] * pr[j];
			while(s[i] % u == 0) s[i] /= u;
		}

		//Now s[i] is p^3-free
		LL tmp = s[i];
		pal[i] = 1;
		FI(j, 1, p){
			if(tmp % pr[j] == 0 && pal[i] != -1){
				LL u = 1LL * pr[j] * pr[j] * pr[j];
				while(tmp % pr[j] == 0){
					tmp /= pr[j];
					u /= pr[j];
				}
				if(1.0 * pal[i] * u > LIM) pal[i] = -1;
				else pal[i] *= u;
			}
		}

		if(tmp > 1 && pal[i] != -1){
			LL rt = sqrt(tmp);
			if(rt * rt == tmp && 1.0 * pal[i] * rt <= LIM) pal[i] *= rt;
