    vector<long long> enumerate_primes(long long a, long long b) {
    bool * memo_all = new bool[b];
    bool * memo_small = new bool[( long long )pow(b, 1.0 / 2) + 10];
    for (long long i = 0; (long long)i * i < b; i++) memo_small[i] = true;
    for (long long i = 0; i < b - a; i++)     memo_all[i] = true;

    for (long long i = 2; (long long)i * i < b; i++) {
        if (memo_small[i]) {
            for (long long j = 2 * i; (long long)j * j < b; j += i) memo_small[j] = false;
            for (long long j = max(2LL, (a + i - 1) / i) * i; j < b; j += i) memo_all[j - a] = false;
        }
    }


    vector<long long> primes;
    for (long long i = a; i < b; i++) {
        if (memo_all[i-a]) primes.push_back(i);
    }
    delete [] memo_all;
    delete [] memo_small;
    return primes;
}

    map<ll, ll> prime_factor(ll n,vector<ll> primes) {
        map<ll, ll> res;
        for(ll i = 0; primes[i] * primes[i] <= n; i++) {
            while(n % primes[i] == 0) {
                ++res[primes[i]];
                n /= primes[i];
            }
        }
        if (n != 1) res[n] = 1;
        return res;
    }

    vector<ll> normalize_pairlize(ll x,vector<ll> primes){
        vector<ll> np;
        map<ll,ll> pf=prime_factor( x , primes);
        ll n=1,p=1,yobi=1;

        for (map<ll,ll>::iterator itr = pf.begin(); itr != pf.end(); itr++){
            ll xx=itr->first,yy=itr->second;
            if (yy >= 3){
                yy%=3;

            }
            n *= (ll)pow(xx,yy);
            if(yy!=0) {p *= (ll)pow(xx,3 - yy);}
        }
        np.push_back(n);
        np.push_back(p);
        return np;
    }






