vector<int> genPrimes(int upperBound)
{
    vector<int> primes;
    vector<char> sieved(upperBound, false);
    for (int i = 2; i < upperBound; ++i) {
        if (!sieved[i]) {
            primes.pb(i);
            for (int j = 2 * i; j < upperBound; j += i) {
                sieved[j] = true;
            }
        }
    }
    return primes;
}

const int MAXP = 100000;

LL myPow(LL base, int val)
{
    if (val == 0) {
        return 1;
    }
    if (val == 1) {
        return base;
    }
    if (val == 2) {
        return base * base;
    }
    return -1;
}

