		for( ll i = 2; i*i*i <= a; ++i )
			while( a % (i*i*i) == 0 )
				a /= i*i*i;
		++cnt[a];
	}
	int ans = 0;
	for( miter it = cnt.begin(); it != cnt.end(); ++it ) {
		if( it->first == 1 ) continue;
		prm.clear();
		rhocnt = 0;
		pollard_rho(it->first);
		ll a = 1;
		for( miter mit = prm.begin(); mit != prm.end(); ++mit ) {
			a *= mit->first;
			a *= mit->second == 1 ? mit->first : 1;
		}
