bool inp[MAXN];
vector<int> p;

void gh() {
	inp[0] = inp[1] = true;
	for (int i = 2; i < MAXN; i++)
		if (!inp[i]) {
			p.push_back(i);
			for (ll j = (ll)i * i; j < MAXN; j += i)
				inp[j] = true;
		}
}

ll kam(ll x) {
	ll ret = 1;
	for (int i = 0; i < (int)p.size() && (ll)p[i] * p[i] <= x; i++) {
		ll j = p[i];
		if (x % j == 0) {
			ll m = j * j * j;
			while (x % m == 0)
				x /= m;
			while (x % j == 0)
				ret *= j, x /= j;
		}
	}
	return ret * x;
}
ll ziad(ll x) {
	ll ret = 1;
	for (int i = 0; i < (int)p.size() && (ll)p[i] * p[i] <= x; i++) {
		ll j = p[i];
		if (x % j == 0) {
			ll m = j * j * j;
			while (x % m == 0)
				x /= m;
			while (x % j == 0)
				m /= j, x/= j;
			ret *= ((m == j * j * j)? 1: m);
		}
	}
	return ret * x * x;
}

int main() {
	gh();
	cin >> n;
	cout << kam(n) << ' ' << ziad(n);
	return 0;
