const int MAXN = 1e5 + 5;
const int RNG2 = 1e5 + 5, RNG3 = 2205;

int N;
LL A[MAXN];

void input()
{
    read(N);
    for (int i = 1; i <= N; ++i) {
        read(A[i]);
    }
}

int primes[RNG2], totprimes;
bool composite[RNG2];

void sieve(int n)
{
    for (int i = 2; i < n; ++i) {
        if (!composite[i])
            primes[totprimes++] = i;
        for (int j = 0, x; (x = primes[j] * i) < n; ++j) {
            composite[x] = true;
            if (i % primes[j] == 0)
                break;
        }
    }
}

void solve()
{
    sieve(RNG2);

    std::map<pair<LL, Pii>, int> cnt;
    int ans = 0;

    for (int i = 1; i <= N; ++i) {
        LL x = A[i];
        LL sig = 1;
        int tot = 0, mask = 0;
        for (int j = 0; primes[j] < RNG3; ++j) {
            int t = 0;
            for (; x % primes[j] == 0; x /= primes[j]) {
                ++t;
            }
            if (t % 3 != 0) {
                sig *= primes[j];
                mask |= (t % 3 - 1) << tot++;
            }
        }
        if (x > 1) {
            int t = roundl(sqrtl((long double)x));
            if (t * t == x) {
                assert(!composite[t]);
                sig *= t;
                mask |= 1 << tot++;
            } else if (x < RNG2 && !composite[x]) {
                sig *= x;
                mask |= 0 << tot++;
            } else {
                // printf("choose %d directly\n", A[i]);
                ++ans;
                continue;
            }
        }
        ++cnt[MP(sig, MP(tot, mask))];
    }

    for (auto x : cnt) {
        if (x.x.y.x == 0)
            ++ans;
        else {
            auto y = cnt.find(MP(x.x.x, MP(x.x.y.x, ((1 << x.x.y.x) - 1) ^ x.x.y.y)));
            if (y == cnt.end() || y->y < x.y || (y->y == x.y && y->x.y.y < x.x.y.y))
                ans += x.y;
        }
    }

    printf("%d\n", ans);
}

