    if(invv.find(a[i]) == invv.end()){
      invv[a[i]] = inv(a[i]);
    }
  }
  int ans = n;
  for(int i = 1; i <= n; i++){
    ll x = invv[a[i]];
    if(mp[x] == 0 && mp[a[i]] == 0)continue;
    int cnt = mp[a[i]], cnt1 = mp[x];
    if(cnt > cnt1){
      ans -= cnt1;
    }else {
