bool isPrime(int x)
{
    for (int i = 2; i * i <= x; i++)
    {
        if (x % i == 0) return false;
    }
    return true;
}
ll make(ll n)
{
    ll nn = n;
    for (int i = 0; i < (int)primes.size(); i++)
    {
        ll x = primes[i];
        if (x * x * x > n) break;
        while (n % (x * x * x) == 0) n /= (x * x * x);
    }
    return n;
}
ll make2(ll n)
{
    ll sqmul = 1;
    for (ll i = 0; i < (int)primes.size(); i++)
    {
        ll x = primes[i];
        if (x * x > n) break;
        while (n % (x * x) == 0)
        {
            sqmul *= x;
            n /= (x * x);
        }
    }
    return n * n * sqmul;
}
