// Eratosthenes's sieve
// create list of prime numbers in O(N)
// check if the given number is prime in O(1)
struct Sieve {
    vector<bool> isPrime;
    Sieve(size_t max) : isPrime(max + 1, true) {
        isPrime[0] = false;
        isPrime[1] = false;

        for (size_t i = 2; i * i <= max; ++i)
            if (isPrime[i])
                for (size_t j = 2; i * j <= max; ++j)
                    isPrime[i * j] = false;
    }
    bool operator()(size_t n) { return isPrime[n]; }
};

int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    int n;
    cin >> n;
    vector<lint> s(n);
    for (int i = 0; i < n; i++) {
        cin >> s[i];
    }
    Sieve isPrime(100000);
    vector<lint> p3;
    map<lint, lint> p2tp;
    for (lint i = 1; i < 3000; ++i) {
        if (isPrime(i)) {
            p3.push_back(i * i * i);
        }
    }
    for (lint i = 1; i <= 100000; ++i) {
        p2tp[i * i] = i;
    }
    for (int i = 0; i < n; ++i) {
        for (auto &p : p3) {
            while (s[i] % p == 0)
                s[i] /= p;
        }
    }
    map<lint, pair<int, int>> pa;
    for (int i = 0; i < n; ++i) {
        lint t = s[i];
