            while (s[i] % p == 0) {
                cnt--;
                s[i] /= p;
            }
            if (cnt != 3) {
                for (int j = 0; j < cnt; ++j) {
                    v *= p;
                }
            }
        }
        if (p2tp.count(s[i]) == 0) {
            v *= s[i] * s[i];
        } else {
            v *= p2tp[s[i]];
        }
        if (t > v) {
            pa[v].second++;
        } else {
            pa[t].first++;
        }
    }
    lint ret = 0;
    for (auto &p : pa) {
        if (p.first == 1)
            ret++;
        else
            ret += max(p.second.first, p.second.second);
    }
    cout << ret << "\n";
    return 0;
}

