bool isp[maxn];

vector<int> pr; 

void sieve() {
	memset(isp, 1, sizeof isp); isp[1] = 0; 
	for(int i = 2; i <= 100000; i++) {
		if(isp[i]) {
			pr.pb(i);
			for(int j = i * i; j <= 100000; j += i) 
				isp[j] = 0;  
		}
	}
}

void get(int x, int id) {
	vector<ii> ret; 
	for(auto p : pr) {
		if(p * p > x) break; 
		if(x % p == 0) {
			int cnt = 0; 
			while(x % p == 0) {
				x /= p; 
				cnt++; 
			}
			cnt %= 3; 
			if(!cnt) continue; 
			ret.pb({p, cnt}); 
		}
	}
	if(x > 1) 
		ret.pb({x, 1});
	int ans = 1, comp = 1; 
	for(auto t : ret) {
		for(int i = 1; i <= t.se; i++) 
			ans *= t.fi; 
		for(int i = 1; i <= 3 - t.se; i++) 
		 	comp *= t.fi;
	} 
	b[id] = {ans, comp}; 
}

signed main()
{
	fastcin();
	cin >> n; 
	sieve(); 
	for(int i = 1, x; i <= n; i++) {
		cin >> x; 
		get(x, i); 
		if(b[i].fi == 1) ans = 1; 
		else M[b[i].fi]++; 
	}
	for(int i = 1; i <= n; i++) {
		if(b[i].fi == 1) continue; 
		int mask = b[i].fi, comple = b[i].se;
		int p = M[mask], q = M[comple]; 
		if(p == -1 or q == -1) continue; 
		ans += max(p, q); 
		M[mask] = M[comple] = -1;  
	}
	cout << ans; 
}

