map<ll, int> a2m;

bool ok(ll a, ll b) { return (a && b && (1e16)/a>b); }
int main() {
    int n; scanf("%d", &n);
    F0R(i, n) {
        scanf("%I64d", &a[i]); a1[i] = 1; a2[i] = 1;
    }
    for (int i=2; i<MAX; i++) {
        if (!comp[i]) {
            for (int j=2*i; j<MAX; j+=i) { comp[j] = true; }
        }
    }

    for (int i=2; cube(i)<=1e10; i++) {
        if (comp[i]) { continue; }
        F0R(j, n) {
            while (a[j]%cube(i) == 0) { a[j] /= cube(i); }
            if (a[j]%sq(i) == 0) {
                a1[j] *= (ok(a1[j], sq(i))?sq(i):0);
                a2[j] *= (ok(a2[j], i)?i:0);
                a[j] /= sq(i);
            }
            else if (a[j]%i == 0) {
                a1[j] *= (ok(a1[j], i)?i:0);
                a2[j] *= (ok(a2[j], sq(i))?sq(i):0);
                a[j] /= i;
            }
        }
    }
    F0R(j, n) {
        bool issq = false;
        for (int i=max(1, (int)sqrt(a[j])-2); i<=(int)sqrt(a[j])+2; i++) {
            if (comp[i]) { continue; }
            if (sq(i) == a[j]) {
                a1[j] *= (ok(a1[j], sq(i))?sq(i):0);
                a2[j] *= (ok(a2[j], i)?i:0);
                issq = !issq;
            }
        }
        if (!issq) {
            a1[j] *= (ok(a1[j], a[j])?a[j]:0);
            a2[j] *= (ok(a2[j], sq(a[j]))?sq(a[j]):0);
        }
        a1m[a1[j]]++; a2m[a2[j]]++;
    }
    int tot = 0;
    set<ll> s;
    for (auto i : a1m) { s.insert(i.f); }
    for (auto i : a2m) { s.insert(i.f); }
    for (ll i : s) {
        if (i == 1) { tot += 2; }
        else { tot += max(a1m[i], a2m[i]); }
    }

    // F0R(i, n) { cout << a[i] << " " << a1[i] << " " << a2[i] << endl; }
