		res *= x, tm.pb(x);
	if (!PR.count(res))
		PR[res] = tm;
	return res;
}
ll getrev(ll x) {
	ll res = 1;
	for (auto i : PR[x]) {
		ll cnt = 0, tmp = x;
		while (tmp % i == 0)
			tmp /= i, cnt++;
		cnt %= 3;
		cnt = (3 - cnt) % 3;
		while (cnt --> 0)
			res *= i;
	}
	return res;
}

