    set<ll> primes2;
    for(ll p : primes) primes2.insert(p*p);

    int N; cin >> N;
    vector<ll> S(N); cin >> S;

    map<ll, int> normalized_s;

    for(ll s : S) {
        ll t = 1;
        for(ll p : primes) {
            int cnt = 0;
            while(s % p == 0) {
                s /= p;
                cnt++;
            }
            cnt %= 3;
            rep(i, cnt) t *= p;
        }
        if(s > 1) t *= s;
        normalized_s[t]++;
    }
    int ans = 0;
    set<ll> used;
    for(auto s_ : normalized_s) {
        ll s = s_.first;
        int cnt = s_.second;
        if(used.count(s)) continue;

