vector<LL> prime;
inline void getprime()
{
    LL up=sqrt(maxpc+0.5);
    for(LL i=2;i<=up;i++)
        for(LL j=i*i;j<maxpc;j+=i)  notprime[j]=1;
    for(LL i=2;i<maxpc;i++) if(!notprime[i]) prime.PB(i);
}
inline void getdecomp(LL num,vector<pii>& pfac)
{
    LL up=sqrt(num+0.5);
    for(const LL& p:prime)
    {
        if(num%p==0)
        {
            LL t=0;
            while(num%p==0) t++,num/=p;
            pfac.PB(MP(p,t));
        }
        if(num==1 || p>up) break;
    }
    if(num!=1) pfac.PB(MP(num,1));
}
vector<pair<LL , LL > > showclass;
