vector<pair<ll, int>> prime_fact(ll x) {
    vector<pair<ll, int>> pf;
    for (int i = 2; 1ll * i * i <= x; i++) {
        if (x % i == 0) {
            int t = 0;
            while (x % i == 0) {
                x /= i;
                ++t;
            }
            pf.pb({i, t});
        }
    }
    if (x) {
        pf.pb({x, 1});
    }
    return pf;
}

