int reve(int n,vel &p) {
	int a = 1, b = 1;
	for (int i = 0; p[i] * p[i] * p[i] <= n; i++) {
		if (n%p[i] == 0) {
			n /= p[i];
			if (n%p[i] == 0) { b *= p[i]; }
			else { a *= p[i]; }
		}
	}
	if (n != 1) {
		int m = sqrt(n);
		rep(i, 3) {
			if ((m - 1 + i)*(m - 1 + i) == n) { b *= (m-1+i); n = 1; }
		}
	}
	a *= n;
	return a * a*b;
}
