int cnt1[MAXD+5],cnt2[MAXD+5],Pow[MAXD+5][2];
LL pri[MAXD+5],t;
map<PII,int> mp;
void prepare()
{
	for(int i=2;i<=MAXD;i++)
	{
		if(vis[i]==false)
			prime.push_back(i);
		for(int j=0;1LL*prime[j]*i<=MAXD;j++)
		{
			vis[i*prime[j]]=true;
			if(i%prime[j]==0)
				break;
		}
	}
	Pow[0][0]=Pow[0][1]=1;
	for(int i=1;i<=MAXD;i++)
		for(int j=0;j<2;j++)
			Pow[i][j]=1LL*Pow[i-1][j]*3LL%MO[j];
}
void Work(LL x)
{
	for(int j=0;1LL*prime[j]*prime[j]<=x;j++)
		if(x%prime[j]==0)
		{
			vis[j]=true;
			while(x%prime[j]==0)
				x/=prime[j];
		}
	if(x!=1LL)
		prime.push_back(x),vis[(int)prime.size()-1]=true;
}
void Work1(LL x,int id)
{
	for(int j=1;1LL*pri[j]*pri[j]<=x;j++)
	{
		cnt1[j]=0;
		if(x%pri[j]==0)
		{
			while(x%pri[j]==0)
			{
				cnt1[j]++;
				if(cnt1[j]>=3)
					cnt1[j]-=3;
				x/=pri[j];
			}
			cnt2[j]=3-cnt1[j];
			if(cnt2[j]>=3)
				cnt2[j]-=3;
			Mnum[id].first=(1LL*Mnum[id].first+1LL*Pow[j][0]*cnt1[j]%MO[0])%MO[0];
			Mnum[id].second=(1LL*Mnum[id].second+1LL*Pow[j][1]*cnt1[j]%MO[1])%MO[1];
			Anti[id].first=(1LL*Anti[id].first+1LL*Pow[j][0]*cnt2[j]%MO[0])%MO[0];
			Anti[id].second=(1LL*Anti[id].second+1LL*Pow[j][1]*cnt2[j]%MO[1])%MO[1];
		}
	}
	if(x!=1LL)
	{
		int pos=lower_bound(pri+1,pri+1+t,x)-pri;
		cnt1[pos]=0;
		cnt1[pos]++;
		cnt2[pos]=3-cnt1[pos];
		Mnum[id].first=(1LL*Mnum[id].first+1LL*Pow[pos][0]*cnt1[pos]%MO[0])%MO[0];
		Mnum[id].second=(1LL*Mnum[id].second+1LL*Pow[pos][1]*cnt1[pos]%MO[1])%MO[1];
		Anti[id].first=(1LL*Anti[id].first+1LL*Pow[pos][0]*cnt2[pos]%MO[0])%MO[0];
		Anti[id].second=(1LL*Anti[id].second+1LL*Pow[pos][1]*cnt2[pos]%MO[1])%MO[1];
	}
}
int main()
{
//	freopen("anticube.in","r",stdin);
//	freopen("anticube.out","w",stdout);
	prepare();
	memset(vis,0,sizeof(vis));
	scanf("%d",&N);
	for(int i=1;i<=N;i++)
		scanf("%lld",&seq[i]);
	sort(seq+1,seq+1+N);
	for(int i=1;i<=N;i++)
		Work(seq[i]);
	for(int j=0;j<(int)prime.size();j++)
		if(vis[j]==true)
			pri[++t]=prime[j];
	sort(pri+1,pri+1+t);
	t=unique(pri+1,pri+1+t)-pri-1;
	for(int i=1;i<=N;i++)
	{
		Work1(seq[i],i);
		mp[PII(Mnum[i])]++;
	}
	int ans=0,ansn;
	for(int i=1;i<=N;i++)
		if(mp.find(Mnum[i])!=mp.end())
		{
			if(Mnum[i]==Anti[i])
			{
				ans++;
				mp.erase(mp.find(Mnum[i]));
			}
			else
			{
				ansn=mp[Mnum[i]];
				mp.erase(mp.find(Mnum[i]));
				if(mp.find(Anti[i])!=mp.end())
				{
					ansn=max(ansn,mp[Anti[i]]);
					mp.erase(mp.find(Anti[i]));
				}
				ans+=ansn;
