i64 isqrt(i64 a) {
    i64 l = 0;
    i64 r = a;
    while (r - l > 1) {
        i64 m = (r + l) / 2;
        if (m * m > a) {
            r = m;
        } else {
            l = m;
        }
    }
    return l;
}

