typedef long long ll;
const ll mx=1e10;
const int T=100000,q3=2154;
int pr[10010];
bool np[T+10];
map<ll,int>rt,c;
map<ll,int>::iterator it;
void sieve(){
	int i,j,M=0;
	for(i=2;i<=T;i++){
		if(!np[i])pr[++M]=i;
		for(j=1;j<=M&&i*pr[j]<=T;j++){
			np[i*pr[j]]=1;
			if(i%pr[j]==0)break;
		}
	}
	for(i=1;i<=M;i++)rt[(ll)pr[i]*pr[i]]=pr[i];
}
ll no3(ll x){
	int i;
	ll t;
	for(i=1;pr[i]<=q3;i++){
		t=pr[i];
		while(x%(t*t*t)==0)x/=t*t*t;
	}
	return x;
}
ll rev(ll x){
	int i,c;
	ll s,t;
	s=1;
	for(i=1;pr[i]<=q3;i++){
		t=pr[i];
		c=0;
		while(x%t==0){
			x/=t;
			c++;
		}
		if(c){
			for(c=3-c;c--;s*=t);
		}
	}
	if(x!=1){
		if(rt.count(x))
			s*=rt[x];
		else{
			if(x*x<=mx/s)
				s*=x*x;
			else
				s=-1;
		}
	}
	return s;
}
int main(){
	sieve();
	int n,s;
	ll x,y;
	scanf("%d",&n);
	s=0;
	while(n--){
		scanf("%lld",&x);
		y=no3(x);
		if(y==1)
			s=1;
		else
			c[y]++;
	}
	for(it=c.begin();it!=c.end();it++){
		if(it->second){
			x=rev(it->first);
			if(!c.count(x))
				s+=it->second;
			else{
				s+=max(it->second,c[x]);
				c[x]=0;
			}
		}
	}
	printf("%d",s);
}

