LL mod;
LL mult(LL x, LL y)
{
	LL ret = x * y - LL(LD(x) * y / mod) * mod;
	if(ret < 0)
		ret += mod;
	return ret;
}
LL f(LL x)
{
	return (mult(x, x) + 1) % mod;
}
LL gcd(LL x, LL y)
{
	return x == 0 ? y : gcd(y % x, x);
}
LL pollard_rho(LL d)
{
	if(d < 100)
	{
		enum(i, 2, sqrt(d))
			if(d % i == 0)
				return i;
		return -1;
	}
	mod = d;
	int up = sqrt(sqrt(mod)) + 10;
	LL x = f(1), y = f(f(1));
	enum(i, 1, up)
	{
//		cerr << x << ' ' << y << endl;
		LL g = gcd((y - x + mod) % mod, mod);
		if(g != 1 && g != mod)
			return g;
		x = f(x);
		y = f(f(y));
	}
	return -1;
}
