  function<vector<int>(int)> getPrimes = [&](int x) {
    vector<int> ret;
    vector<bool> vis(x + 1);
    for (int k = 2; k <= x; ++k)
      if (!vis[k]) {
        ret.push_back(k);
        for (int j = k; j <= x; j += k)
          vis[j] = true;
      }
    return ret;
  };
  vector<int> pr = getPrimes(2200);
  vector<ll> pr3;
  for (int p : pr) pr3.push_back(p * (ll)p * p);

  int N;
  cin >> N;
  map<ll, int> cnt;
  int ans = 0;
  ll mx = 0;
  while (N--) {
    ll x;
    cin >> x;
    for (ll v : pr3)
      while (x % v == 0)
        x /= v;
    if (x == 1)
      ans = 1;
    else
      ++cnt[x];
    mx = max(mx, x);
  }
  int searchLimit = 1 + pow(mx, 1. / 3);
  function<int(ll)> pSQRT = [&](ll x) {
    int rt = sqrt(x);
    while (rt * (ll)rt < x) ++rt;
    while (rt * (ll)rt > x) --rt;
    return rt * (ll)rt == x ? rt : -1;
  };
  function<ll(ll)> dual = [&](ll x) {
    int cur;
    for (int k = 1; k <= searchLimit; ++k)
      if (x % k == 0 && (cur = pSQRT(x / k)) != -1)
        return k * k * (ll)cur;
    for (int k = searchLimit; k; --k)
      if (x % k == 0 && x / k % k == 0) {
        ll tmp = x / (k * k);
        if (tmp * k > mx / tmp)
          return -1LL;
        return tmp * tmp * k;
      }
    return -1LL;
  };

  while (!cnt.empty()) {
    ll x;
    int a;
    tie(x, a) = *cnt.begin();
    cnt.erase(cnt.begin());
    ll du = dual(x);
    ans += max(cnt[du], a);
    cnt.erase(du);
  }
  cout << ans;

#ifdef LBT
