const int maxN = 1e5 + 5;
const int maxM = 1e6 + 5;
const llint INF = 1ll * 1000 * 1000 * 1000 * 10;
const int mx = 2200;

int N;
llint a[maxN];
map<llint, int> sl;
map<llint, llint> match;

void enter() {
    scanf("%d", &N);
    for (int i = 1; i <= N; ++i) {
        scanf("%lld", &a[i]);
    }
}

void solve() {
    int res = 0;
    for (int i = 1; i <= N; ++i) {
        llint tmp = a[i];
        llint mul = 1;
        bool T = true;

        for (llint j = 2; j <= mx; ++j) {
            while (a[i] % (j * j * j) == 0) {
                a[i] /= (j * j * j);
                tmp /= (j * j * j);
            }

            int sl = 3;
            while (tmp % j == 0) {
                tmp /= j;
                --sl;
            }
            if (sl == 3) continue;

            while (sl --) {
                mul = mul * j;
                if (mul > INF) T = false;
            }

            if (!T) break;
        }

        if (!T) {
            res += 2;
            continue;
        }

        llint sqrt_tmp = trunc(sqrt(tmp));
        if (sqrt_tmp * sqrt_tmp == tmp) {
            mul = mul * sqrt_tmp;
            if (mul > INF) T = false;
            if (!T) {
                res += 2;
                continue;
            }

            ++sl[a[i]];
            match[a[i]] = mul;
            match[mul] = a[i];
        }
        else {
            for (int j = 0; j <= 1; ++j) {
                mul = mul * tmp;
                if (mul > INF) T = false;
            }
            if (!T) {
                res += 2;
                continue;
            }
            ++sl[a[i]];
            match[a[i]] = mul;
            match[mul] = a[i];
        }
    }

    for (map<llint, int> :: iterator it = sl.begin(); it != sl.end(); ++it) {
        llint val = it -> first;
        int cnt = it -> second;

        if (val == 1) {
            res = res + 2;
        }
        else {
            llint vava = match[val];
            res = res + max(cnt, sl[vava]);
        }
    }

    printf("%d", res / 2);
}

int main() {
    openFile();
    enter();
    solve();
    return 0;
}

