struct Sieve {
	vector<bool> sieve;
	vector<long long> primes;
	Sieve(int n) : sieve(n*n) {
		for (unsigned i = 2; i < sieve.size(); ++i) if (!sieve[i]) {
			primes.push_back(i);
			if (i < n) for (unsigned j = i*i; j < sieve.size(); j += i) sieve[j] = true;
		}
	}
};

int N;
Sieve sie(317);
map<long long, long long> p2;

// Norm
long long f(long long n) {
	for (auto p : sie.primes) {
		auto p3 = p*p*p;
		if (n < p3) break;
		while (n % p3 == 0) {
			n /= p3;
		}
	}
	return n;
}

// Pair
long long g(long long n) {
	long long x = n;
	long long m = 1;
	for (auto p : sie.primes) {
		if (p*p*p > n) break;
		int c = 0;
		while (x % p == 0) {
			x /= p;
			++c;
		}
		if (c % 3 == 1) {
			m *= p * p;
		} else if (c % 3 == 2) {
			m *= p;
		}
	}
	m *= p2.count(x) ? p2[x] : x * x;
	return m;
}

int main() {
	for (auto p : sie.primes) {
		p2[p*p] = p;
	}
	cin >> N;
	int one = 0;
	map<long long, pair<int, int>> cnt;
	for (int i = 0; i < N; ++i) {
		long long si;
		cin >> si;
		long long y = f(si);
		long long z = g(si);
		if (y == 1) {
			one = 1;
		} else {
			if (y < z) ++cnt[y].first; else ++cnt[z].second;
		}
	}
	int r = one;
	for (auto p : cnt) {
		r += max(p.second.first, p.second.second);
	}
	cout << r << endl;
}

