class solver{
    istream& is;
    ostream& os;

    vector<ll> cubic;
    unordered_map<ll, ll> square;
public:
    solver(istream& I, ostream& O) :is(I), os(O) {}

    ll remove_cubic(ll x){
        for (auto &&cc : cubic) {
            if(cc > x) return x;
            while(x % cc == 0) x /= cc;
        } // end cc
        return x;
    }

    void run(){
        ll N;
        is >> N;
        if(!is) return;
        init();
        map<ll, int> mp;
        for (int i = 0; i < N; ++i) {
            ll S;
            is >> S;
            S = remove_cubic(S);
            mp[S]++;
        } // end ss
        ll ans = 0;
        for (auto &&p : mp) {
            if(p.first == 1) ans += 1;
            else if(p.second > 0){
                ll fst = p.first;
                if(fst > 1'000'000 or square.count(fst) > 0){
                    ans += p.second;
                    continue;
                }
                ll ds = remove_cubic(fst * fst);
                if(mp.count(ds) > 0){
                    if(mp.at(ds) > p.second) {
                        continue;
                    }
                    else{
                        ans += p.second;
                        mp.at(ds) = 0;
                    }
                }
                else {
                    ans += p.second;
                }
            }
        } // end p

        cout << ans << endl;


    }

    void init(){
        ll pmx = 300'000;
        ll smax = 10'000'000'000;
        vector<bool> prime(pmx, true);
        for (ll i = 2; i < pmx; ++i) {
            if(prime[i]){
                ll cube = i * i * i;
                ll sq = i * i;
                if(cube <= smax) { cubic.push_back(cube); }
                if(sq <= smax){ square.emplace(sq, i); }
                else return;
                for (int j = i + i; j < pmx; j+=i) {
                    prime[j] = false;
                } // end j
            }
        } // end i
    }
};

