inline ll norm(ll x) {
    for(int p : prime) {
        ll t = ll(p) * ll(p) * ll(p);
        if(t > x) break;
        while(x % t == 0) x /= t;
    }
    return x;
}
inline ll mul(ll a , ll b) {
    if(INF / b < a) return INF;
    else return a * b;
}
inline ll conj(ll x) {
    ll res = 1;
    for(int p : prime) {
        if(ll(p) * ll(p) > x) break;
        if(x % p == 0) {
            if((x / p) % p == 0) res = mul(res , p) , x /= p , x /= p;
            else res = mul(res , mul(p , p)) , x /= p;
        }
    }
    if(x != 1) res = mul(res , mul(x , x));
    return res;
}
