	ll res = 1;
	for(auto i : primes) {
		if(x%i) continue;
		int c = 0;
		while(x%i == 0) x/=i, c++;
		c %= 3;
		while(c--) res *= i;
	}
	ll t = sqrt(x);
	for(int i = max(-10ll, -t); i < 10; i++) if((t+i)*(t+i) == x) {res *= t+i; x = 1; break;}
