ll times(ll a,ll b,ll mo)
{
	a%=mo;b%=mo;
	long long tmp=a*b-(long long)((long double)a/mo*b+1e-8)*mo;
	if (tmp<0) tmp+=mo;
	return tmp;
}
ll getmi(ll a,ll x,ll mo)
{
	ll ans=1;
	while (x)
	{
		if (x&1) ans=times(ans,a,mo);
		a=times(a,a,mo);
		x>>=1;
	}
	return ans;
}
ll gcd(ll a,ll b){if (!b) return a;return gcd(b,a%b);}
bool isprime(ll p)
{
	if ((p==2)||(p==3)||(p==5)) return true;
	if (p<=6) return false;
	if ((p&1)==0) return false;
	ll m=p-1,j=0;while ((m&1)==0) {m>>=1;j++;}
	for (int t=1;t<=10;t++)
	{
		ll b=rand()%(p-2)+2,v=getmi(b,m,p);
		if (v==1) continue;
		for (int i=1;i<=j;i++)
		{
			if (v==p-1) break;
			v=times(v,v,p);
		}
		if (v!=p-1) return false;
	}
	return true;
}
long long work(long long w)
{
	if (isprime(w)) return 0;
	long long p=1,q=1;
	for (int i=1;((pr[i]*pr[i]<=w)&&(i<=pnum));i++)
	{
		int js=0;
		while (w%pr[i]==0)
