const ll BRD = 1e10;

vector<ll> pr;

void delCubes(ll& v) {
  for (ll p : pr) {
    while (v % (p * p * p) == 0) {
      v /= (p * p * p);
    }
  }
}

ll getPair(ll v) {
  __int128 res = 1;
  for (__int128 p : pr) {
    if (v % (p * p) == 0) {
      res = res * p;
      v /= (p * p);
    }
    else if (v % p == 0) {
      res = res * p * p;
      v /= p;
    }
  }
  if (v != 1) {
    __int128 sq = sqrt(v);
    while (sq * sq < v) sq++;
    while (sq * sq > v) sq--;
    if (sq * sq == v) {
      res = res * sq;
    }
    else {
      res = res * v * v;
    }
  }
  if (res <= BRD) return res;
  else return INF;
}

void solve() {
  int n; cin >> n;
  unordered_map<ll, int> mp;
  for (int i = 0; i < n; i++) {
    ll v; cin >> v;
    delCubes(v);
    mp[v]++;
  }
  ll ans = (mp[1] > 0);
  mp.erase(1);
  for (auto x : mp) {
    ll v = x.first, res = x.second;
    ll nv = getPair(v);
    //cout << v << " " << nv << endl;
    if (mp.count(nv) == 0) {
      ans += res;
    }
    else if (res > mp[nv] || res == mp[nv] && v < nv) {
      ans += res;
    }
  }
  cout << ans;
}

