pair< long long, long long > gg ( long long x ) {

    if ( mem[x].first ) { return mem[x]; }

    long long a = 1, b = 1;

    for ( int i = 0 ; i < prs.size() && prs[i]*prs[i] <= x ; i ++ ) {

        if ( x%prs[i] == 0 ) {
            int cnt = 0;
            for ( ; x%prs[i] == 0 ; cnt ++ ) {
                x /= prs[i];
            }
            cnt %= 3;
            for ( int c = 0 ; c < cnt ; c ++ ) { a *= prs[i]; }
            cnt = (3-cnt)%3;

            for ( int c = 0 ; c < cnt ; c ++ ) {
                if ( b != -1 ) {
                    b *= prs[i];
                    if ( b >  (10000000000LL) ) { b = -1; }
                }
            }

        }
    }

    if ( x != 1 ) {
        a *= x;
        if ( x > 1000000 ) { b = -1; }
        if ( b != -1 ) {
            b *= x;
            if ( b > (10000000000LL) ) { b = -1; }
        }
        if ( b != -1 ) {
            b *= x;
            if ( b > (10000000000LL) ) { b = -1; }
        }
    }

    mem[x] = make_pair( a, b );
    return make_pair( a, b );
}

