typedef long long ll;

const int kN = 1e5 + 5;
const int kP = 2e3 + 5;
const int kEps = 1e-10;

int n, cnt = 0, p[kP]; ll s[kN], s2[kN], ns[kN];
std::map<int, bool> vis;
bool is_p[kP];
void Sieve() {
	memset(is_p, true, sizeof(is_p));
	is_p[1] = false;
	for(int i = 2; i < kP; ++i) {
		if(is_p[i]) p[++cnt] = i;
		for(int j = 1; j <= cnt && i * p[j] < kP; ++j) {
			is_p[i * p[j]] = false;
			if(i % p[j] == 0) break;
		}
	}
}

int main() {
	scanf("%d", &n); Sieve();
	for(int i = 1; i <= n; ++i) scanf("%lld", s + i);
	for(int i = 1; i <= n; ++i) {
		ns[i] = 1;
		for(ll j = 1; p[j] * p[j] * p[j] <= s[i]; ++j) {
			ll cp = p[j] * p[j] * p[j];
			while(s[i] % cp == 0) s[i] /= cp;
		}
		s2[i] = s[i];
		for(ll j = 1; p[j] * p[j] * p[j] <= s2[i]; ++j)
			if(s[i] % p[j] == 0) {
				if(s[i] % (p[j] * p[j]) == 0) ns[i] *= p[j];
				else ns[i] *= p[j] * p[j];
				while(s[i] % p[j] == 0) s[i] /= p[j];
			}
		ll sqr = (ll)(sqrt(s[i]) + kEps);
		if(sqr * sqr == s[i]) ns[i] *= sqr;
		else if(s[i] <= 1e5) ns[i] *= s[i] * s[i];
		vis[ns[i]] = false;
	}
	int ans = 0;
	for(int i = 1; i <= n; ++i) {
		if(!vis.count(s2[i])) ++ans;
		else if(!vis[s2[i]]) vis[ns[i]] = true, ++ans;
	}
	printf("%d", ans);
	return 0;
}

