vector<ll>divisor(ll n){
	vector<ll>res;
	for(ll i=1;i*i<=n;i++){
		if(n%i==0){
			res.push_back(i);
			if(i!=n/i)res.push_back(n/i);
		}
	}
	return res;
}
map<ll,int>prime_factor(ll n){
	map<ll,int>res;
	for(ll i=2;i*i<=n;i++){
		while(n%i==0){
			res[i]++;
			n/=i;
		}
	}
	if(n!=1)res[n]++;
	return res;
}

vector<int>prime_enum(int n){
	vector<bool>is_prime(n+1,true);
	is_prime[0]=is_prime[1]=false;
	vector<int>res;
	for(int i=2;i<=n;i++){
		if(!is_prime[i])continue;
		res.push_back(i);
		for(int j=2*i;j<=n;j+=i){
			is_prime[j]=false;
		}
	}
	return res;
}
int main(){
	auto prime=prime_enum(100000);
	int n;scanf("%d",&n);
	ll ans=0;
	bool flag=false;
	map<map<ll,int>,int>mp;
	rep(i,n){
		ll s;scanf("%lld",&s);
		map<ll,int>res;
		for(int j:prime){
			while(s%j==0){
				res[j]++;
				s/=j;
			}
		}
		if(s>100000){ans++;continue;}
		map<ll,int>m;
		for(auto p:res){
			if(p.second%3)m[p.first]=p.second%3;
		}
		if(m.size()==0){
			flag=true;
		}
		else mp[m]++;
	}
	ans+=flag;
	while(mp.size()){
		auto res=*mp.begin();mp.erase(mp.begin());
		map<ll,int>m;
		for(auto p:res.first){
			m[p.first]=3-p.second;
		}
		auto it=mp.find(m);
		if(it!=mp.end()){
			ans+=max(res.second,it->second);
			mp.erase(it);
		}
		else ans+=res.second;
	}
	cout<<ans<<endl;
}

