#include <iostream>
#include <vector>
#include <map>
#include <bitset>
#include <cmath>

using namespace std;

const int kMax = 2200;
const int kMaxPr = 500;
const double eps = 1e-10;

void Init(vector < int > &prime) {

  bitset < kMax > used;
  int index = 0;
  for (int pr = 2; pr < kMax; pr ++) {
    if (used[pr]) {
      continue;
    }
    prime[++ index] = pr;

    for (int j = pr * 2; j < kMax; j += pr) {
      used[j] = true;
    }
  }

  prime[0] = index;
}

void solve(vector < long long > &element, vector < int > &prime, map < long long, long long > &hash, 
  map < long long, long long > &comp, map < long long, int > &frecv, int n) {

  for (int i = 1; i <= n; i ++) {
    cin >> element[i];

    long long k = element[i];
    if (hash[k]) {
      frecv[hash[k]] ++;
      continue;
    }

    hash[k] = 1ll;
    comp[k] = 1ll;
    for (int j = 1; j <= prime[0] and k != 1 and prime[j] * prime[j] <= k; j ++) {
      if (k % prime[j] != 0) {
        continue;
      }

      int elExp = 0;
      while (k % prime[j] == 0) {
        elExp ++;
        k /= prime[j];
      }

      elExp %= 3;
      if (elExp == 0) {
        continue;
      }

      if (elExp == 1) {
        hash[element[i]] *= 1ll * prime[j];
        comp[element[i]] *= 1ll * prime[j] * prime[j];
      }
      else {
        hash[element[i]] *= 1ll * prime[j] * prime[j];  
        comp[element[i]] *= 1ll * prime[j];
      }
    }

    hash[element[i]] *= k;
    double sq_root = sqrt(k);
    if (sq_root - floor(sq_root) < eps) {
      comp[element[i]] *= sq_root;
    }
    else {
      double aux = hash[element[i]];
      aux *= (double)k * (double)k;
      if (aux < 1e18) {
        comp[element[i]] *= k * k;
      }
      else {
        comp[element[i]] = 0;
      }
    }

    frecv[hash[element[i]]] ++;
    comp[hash[element[i]]] = comp[element[i]];
  }
}

int main(int argc, char const *argv[]) {

  vector < int > prime(kMaxPr);
  Init(prime);

  int n;
  cin >> n;

  vector < long long > element(n + 1);
  map < long long, long long > hash;
  map < long long, long long > comp;
  map < long long, int > frecv;

  solve (element, prime, hash, comp, frecv, n);

  map < long long, bool > used;
  used[1] = true;
  int to_remove = frecv[1] - 1;
  for (auto &x : frecv) {
    if (used[x.first]) {
      continue;
    }

    long long k = x.first;
    int c = frecv[comp[k]];

    to_remove += min(x.second, c);
    used[comp[k]] = true;
  }

  cout << n - to_remove << '\n';
}

#include <bits/stdc++.h>
using namespace std;
typedef long long int ll;
typedef pair<__int128,__int128> pll;
map <__int128, int> M;
set <pll> S;
// primality checking taken from anta's library
ll modmult(ll x, ll y, ll MOD) {
	ll a = x, r = 0;
	while(y) {
		if(y & 1)
			if((r += a) >= MOD) r -= MOD;
		if((a += a) >= MOD) a -= MOD;
		y >>= 1;
	}
	return r;
}
ll powmodll(ll a, unsigned long long k, const ll MOD) {
	a %= MOD;
	ll r = MOD == 1 ? 0 : 1;
	while(k) {
		if(k & 1)
			r = modmult(r, a, MOD);
		a = modmult(a, a, MOD);
		k >>= 1;
	}
	return (unsigned)r;
}

bool isPrime(long long p,int iteration){
    if(p<2){
        return false;
    }
    if(p!=2 && p%2==0){
        return false;
    }
    long long s=p-1;
    while(s%2==0){
        s/=2;
    }
    for(int i=0;i<iteration;i++){
        long long a=rand()%(p-1)+1,temp=s;
        long long mod=powmodll(a,temp,p);
        while(temp!=p-1 && mod!=1 && mod!=p-1){
            mod=modmult(mod,mod,p);
            temp *= 2;
        }
        if(mod!=p-1 && temp%2==0){
            return false;
        }
    }
    return true;
}
//
long long int get_sqrt(long long int x)
{
	long long int temp = sqrtl(x);
	for (long long int i = temp; i*i <= x; ++i)
	{
		if(i*i == x)
			return i;
	}
	return -1;
}
//
void get_fg(__int128 x, __int128 &f, __int128 &g)
{
	for (__int128 i = 2; i*i*i <= x; ++i)
	{
		if(x%i == 0)
		{
			int ctr = 0;
			while(x%i == 0)
			{
				x/=i;
				ctr++;
			}
			ctr%=3;
			for (int j = 0; j < ctr; ++j)
				f*=i;
			ctr = (3 - ctr)%3;
			for (int j = 0; j < ctr; ++j)
				g*=i;
		}
	}
	if(x > 1)
	{
		if(isPrime(x, 10))
		{
			f*=x;
			g*=(x*x);
		}
		else
		{
			__int128 temp = get_sqrt(x);
			if(temp == -1)
			{
				f*=x;
				g*=(x*x);
			}
			else
			{
				f*=x;
				g*=temp;
			}
		}
	}
}
int main()
{
	int n;
	scanf("%d", &n);
	int ans = 0;
	__int128 ub = 100000000000ll;
	for (int i = 0; i < n; ++i)
	{
		long long int x;
		__int128 f = 1, g = 1;
		scanf("%lld", &x);
		get_fg(x, f, g);
		if(g > ub)
		{
			ans++;
		}
		else
		{
			M[f]++;
			S.insert(pll(min(f,g),max(f,g)));
		}
		// cout<<(long long int)f<<" "<<(long long int)g<<"\n";
	}
	for (set <pll>::iterator it = S.begin(); it != S.end(); ++it)
	{
		__int128 f = (*it).first, g = (*it).second;
		if(f == g)
		{
			if(M[f])
				ans++;
		}
		else
		{
			ans+=max(M[f],M[g]);
		}
	}
	printf("%d\n", ans);
	return 0;
}

