    }
  }
  return x;
}

ll complm (ll x) {
  ll ans = 1;
  for (ll p : primes) {
    if (x % sq(p) == 0) {
      ans *= p;
      x /= sq(p);
    } else if (x % p == 0) {
      ans *= sq(p);
      x /= p;
    }
  }
  if (x != 1) return -1;
  return ans;
}

