using ull = unsigned long long;
template<typename T>
struct FastPrime{
  mt19937_64 RNG;
  FastPrime():RNG(chrono::steady_clock::now().time_since_epoch().count()){};
  T modpow(T p, ull q, ull mod){
    T tmp = p % mod, ret = 1;
    while(q){
      if(q&1)ret = ret * tmp % T(mod); 
      q >>= 1;
      tmp = tmp * tmp % T(mod);
    }
    return ret;
  }
  vector<T>v32={2,7,61};
  bool isPrime32(ull n){
    ull d = n - 1;
    while(!(d&1))d >>= 1;
    for(auto a:v32){
      if(T(n) <= a)break;
      T now = modpow(a, d, n);
      ull q = d;
      while(q != n - 1 && now != T(1) && now != T(n - 1)){
        q <<= 1;
        now = now * now % T(n);
      }
      if(!(q&1) && now != T(n-1))return false;
    }
    return true;
  }
  vector<T>v64={2,325,9375,28178,450775,9780504,1795265022};
  bool isPrime64(ull n){
    ull d = n - 1;
    while(!(d&1))d >>= 1;
    for(auto a:v64){
      if(T(n) <= a)break;
      T now = modpow(a, d, n);
      ull q = d;
      while(q != n - 1 && now != T(1) && now != T(n - 1)){
        q <<= 1;
        now = now * now % T(n);
      }
      if(!(q&1) && now != T(n-1))return false;
    }
    return true;
  }
  bool isPrime(ull n){
    if(n == 2)return true;
    else if(n == 1 || n % 2 == 0)return false;
    else if(n < 1UL << 31)return isPrime32(n);
    else return isPrime64(n);
  }
  ll random_generate(ll n){
    uniform_int_distribution<ll>dist(0, n - 1);
    return dist(RNG);
  }
  ll func(ll x, ll mod){
    return T(x) * T(x) % T(mod);
  }
  void factorize(ll n, map<ll,ll>&ret){
    if(n == 1)return;
    while(!isPrime(n)){  
      ll val1 = random_generate(n);
      ll val2 = func(val1,n);
      ll dif = n;
      if(n&1){
        while(1){
        dif = __gcd(n, abs(val2 - val1));
        if(dif > 1)break;
        val1 = func(val1, n);
        val2 = func(func(val2, n), n);
        }
      }
      else dif = 2;
      if(dif != n){
        factorize(dif,ret);
        n /= dif;
      }
    }
    if(n != 1)ret[n]++;
  }
};
