const int MX = 2200;
typedef __int128_t lll;

int n;
map<ll, pair<int, int>> mm;
vector<ll> pr;

int main() {
	for (ll j = 2; j < MX; ++j) {
		int fl = 0;
		for (int i = 2; i * i <= j; ++i)
			if (j % i == 0) {
				fl = 1;
				break;
			}
		if (!fl)
			pr.push_back(j);
	}
	scanf("%d", &n);
	for (int i = 0; i < n; ++i) {
		ll x;
		scanf("%lld", &x);
		ll gr1 = 1;
		ll gr2 = 1;
		for (ll j: pr) {
			if (x % j != 0)
				continue;
			int cc = 0;
			while (x % j == 0)
				x /= j, ++cc;
			if (cc % 3 == 1)
				gr1 *= j;
			else if (cc % 3 == 2)
				gr2 *= j;
		}
		ll g = llround(sqrt(x));
		if (g * g == x)
			gr2 *= g;
		else
			gr1 *= x;
		lll y = (lll)gr1 * gr1 * gr2;
		x = gr1 * gr2 * gr2;
		if (y < x) {
			++mm[y].second;
		}
		else {
			++mm[x].first;
		}
	}
	int ans = 0;
	for (auto x: mm) {
		if (x.first != 1)
			ans += max(x.second.first, x.second.second);
		else
			ans += min(1, x.second.first);
	}
	cout << ans << "\n";
	return 0;
}

