int prime[100015];
int isPrime[100015];

int sieve(int n){
  int p = 0;
  for(int i = 0; i <= n; i++){
    isPrime[i] = 1;
  }
  isPrime[0] = 0;
  isPrime[1] = 0;
  for(int i = 2; i <= n; i++){
    if(isPrime[i] == 1){
      prime[p] = i;
      p++;
      for(int j = 2 * i; j <= n; j += i){
        isPrime[j] = 0;
      }
    }
  }
  return p;
}

