vector<long long> prms;

numtype normalize(long long x){
	long long p=1,q=1;
	for(int i=0;i<prms.size();i++){
		long long d=prms[i];
		if(d*d>x)break;
		int cnt=0;
		for(;x%d==0;){x/=d;cnt++;}
		if(cnt%3==1)p*=d;
		if(cnt%3==2)q*=d;
	}
	p*=x;
	return make_pair(p,q);
}

numtype inv(numtype x){
	return make_pair(x.second,x.first);
}

bool istriv(numtype x){return x==make_pair(1LL,1LL);}

