int b[N], a[N], c[N];
map < int, int > cnt, ind;
int sqr(int x){
    int l = 1;
    int r = 1e6;
    while(r - l > 1){
        int mid = (r + l) / 2;
        if (mid * mid > x) r = mid; else l = mid;
    }
    if (l * l == x) return l;
    return 1;
}
main(){
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    //freopen("input.txt", "r", stdin);
    int n;
    cin >> n;
    set < int > s, spr;
    vector < int > pr;
    int cube = 0;
    for (int i = 2; i < N; i++){
        if (c[i]) continue;
        pr.pb(i);
        spr.insert(i);
        for (int j = i; j < N; j += i){
            c[j] = 1;
        }
    }
    for (int i = 1; i <= n; i++){
        cin >> a[i];
        for (int j = 2; j * j * j <= a[i]; j++){
            while(a[i] % (j * j * j) == 0){
                a[i] /= (j * j * j);
            }
        }
        if (a[i] == 1) cube++;
        else{
            cnt[a[i]]++;
            if (s.find(a[i]) != s.end()) continue;
            b[i] = 1;
            int x = a[i];
            for (auto j: pr){
                if (j > 10000) break;
                if (x % j != 0) continue;
                if (x % (j * j) == 0){
                    b[i] *= j;
                    x /= (j * j);
                }
                else{
                    b[i] *= j * j;
                    x /= j;
                }
                if (b[i] > 1e10) break;
            }
            if (spr.find(x) != spr.end()){
                x = 1;
                if (b[i] * x < 1e10){
                    b[i] = b[i] * x * x;
                } else b[i] = 1e12;
            }
            if (spr.find(sqr(x)) != spr.end()){
                b[i] = b[i] * sqr(x);
                x = 1;
            }
            if (x != 1) b[i] = 1e12;
            ind[a[i]] = i;
            s.insert(a[i]);
        }
    }
    int ans;
    if (cube) ans = 1; else ans = 0;
    for (auto i: s){
        if (s.find(b[ind[i]]) != s.end() && b[ind[i]] < i) continue;
        ans += max(cnt[b[ind[i]]], cnt[i]);
    }
    cout << ans;
}

