    for (int i = 0; i < n; ++i) {
      norm[i] = s[i];
      for (lli j = 2; j * j * j <= 10000000000LL; ++j) {
        lli k = j * j * j;
        while (norm[i] % k == 0) {
          norm[i] /= k;
        }
      }
    }

    map<lli, lli> pair;
    for (int i = 0; i < n; ++i) {
      lli q = 1;
