#define gc() getchar()
template <typename tp>
inline void read(tp& x) {
  x = 0; char tmp; bool key = 0;
  for (tmp = gc() ; !(tmp >= '0' && tmp <= '9') ; tmp = gc())
    key = (tmp == '-');
  for ( ; tmp >= '0' && tmp <= '9' ; tmp = gc())
    x = (x << 3) + (x << 1) + tmp - '0';
  if (key) x = -x;
}
typedef long long ll;
const int MAX = 2500, M = 8, N = 100010;
const ll MAXV = (ll)(1e10);
int isp[MAX + 10],pri[MAX],pcnt;
void prework() {
  for (int i = 2 ; i <= MAX ; ++ i) {
    if (!isp[i]) pri[++pcnt] = i;
    for (int j = 1 ; j <= pcnt && pri[j] * i <= MAX ; ++ j) {
      isp[i * pri[j]] = 1;
      if (i % pri[j] == 0) break;
    }
  }
}
int n,val[N],fac[N][M],num[N][M],fcnt[N],res[N],ans;
map<int,int> match,mp,sqr;
signed main() {
  prework();
  read(n);
  for (int i = 1 ; i <= n ; ++ i)
    read(val[i]);
  for (int i = 1 ; i <= n ; ++ i)
    for (int j = 1 ; j <= pcnt && 1ll * pri[j] * pri[j] * pri[j] <= val[i]; ++ j)
      while (val[i] % (1ll * pri[j] * pri[j] * pri[j]) == 0)
	val[i] /= 1ll * pri[j] * pri[j] * pri[j];
  for (int i = 1 ; i <= n ; ++ i) {
    res[i] = val[i];
    ++ mp[val[i]];
    for (int j = 1 ; j <= pcnt && pri[j] <= res[i] ; ++ j)
      if (res[i] % pri[j] == 0) {
	num[i][++fcnt[i]] = pri[j];
	while (res[i] % pri[j] == 0)
	  fac[i][fcnt[i]] ++, res[i] /= pri[j];
      }
  }
  for (int i = 1 ; 1ll * i * i <= MAX ; ++ i)
    sqr[1ll * i * i] = i;
  for (int i = 1 ; i <= n ; ++ i) {
    __int128 tmp = 1;
    for (int j = 1 ; j <= fcnt[i] ; ++ j)
      if (fac[i][j] == 1) tmp *= num[i][j] * num[i][j];
      else tmp *= num[i][j];
    if (sqr.count(res[i]))
      tmp *= sqr[res[i]];
    else tmp *= res[i] * res[i];
    if (tmp > MAXV) tmp = -1;
    if (tmp < val[i] && tmp != -1)
      match[tmp] = val[i];
