                hs = hs * shift[x - d + 1] + 1 + (1 + x - d);
                invhs = invhs * shift[x - d + 1] + 2 + (1 + x - d);
                iscubic = 0;
            }

            if(iscubic) {
                if(!flag) {
                    flag = 1;
                    ans ++;
                }
                continue;
            }

            oposite[hs] = invhs;
            fr[hs] ++;
        }
    }

    int aux = 0;
    for(auto it : fr) {
        if(fr.find(oposite[it.first]) != fr.end())
            aux += max(it.second, fr[oposite[it.first]]);
        else
            aux += (2 * it.second);
        //cout << it.first << " " <<it.second << endl;
    }
    aux /= 2;

    ans += aux;
    cout << ans;

    return 0;
}

