inline i64 calc(i64 x){
	i64 res=1;
	rep(j,1,tot)if(x%prime[j]==0){
		if(x%(prime[j]*prime[j])==0)res*=prime[j];
		else res*=prime[j]*prime[j];
		while(x%prime[j]==0)x/=prime[j];
