	if(x!=1){
		i64 tmp=sqrt(x);
		while((tmp+1)*(tmp+1)<=x)tmp++;
		while(tmp*tmp>x)tmp--;
		if(tmp*tmp==x){
			res*=tmp;
		}else
			res*=x*x;
	}return res;
}
