template<typename T>
vector<pair<T, int>> prime_factor(T num) {
  vector<pair<T, int>> ret;
  for (T i=2; i*i<=num; ++i) {
    int cnt = 0;
    while (num%i == 0) {
      num /= i;
      ++cnt;
    }
    cnt %= 3;
    if (cnt != 0) ret.emplace_back(i, cnt);
  }
  if (num != 1) ret.emplace_back(num, 1);
  return ret;
}

void solve() {
  int n; cin >> n;
  vl arr(n); cin >> arr;

  map<vector<pair<ll, int>>, int> mp;
  for (auto &num : arr) {
    mp[prime_factor(num)]++;
  }

  int ans = 0;
  auto tmp = prime_factor(1LL);
  if (mp.count(tmp)) {
    ans = 1;
    mp.erase(tmp);
  }

  while (!mp.empty()) {
    auto a = mp.begin();
    auto b = a->first;
    for (auto &p : b) {
      p.second = 3 - p.second;
    }
    ans += max(a->second, mp[b]);
    mp.erase(a);
    mp.erase(b);
  }

  cout << ans << endl;
}


