typedef long long i64;
typedef vector<int> vi;
typedef vector<i64> vx;
typedef set<i64> sx;
typedef map<i64, int> mxi;

vi prime_sieve(int n) {
    vi primes(n);
    int i, j;
    for (i=2; i<n; i++)
        primes[i] = i;

    for (i=2; i*i<n; i++)
        if (primes[i])
            for (j=i*i; j<n; j+=i)
                primes[j] = 0;

    return primes;
}

i64 norm(i64 x, vx &pcubes) {
    for (i64 c: pcubes) {
        if (c > x) break;
        while (x%c==0) x/=c;
    }
    return x;
}

const i64 INF=1e12;
i64 mul(i64 m, i64 n) {
    return INF/n<m? INF:m*n;
}

i64 anti(i64 x, vx &primes) {
    i64 y=1;
    for (i64 p: primes) {
        if (1LL*p*p > x) break;
        if (x%p==0) {
            if ((x/p) % p) {
                y = mul(y, mul(p, p));
                x /= p;
            } else {
                y = mul(y, p);
                x /= p * p;
            }
        }
    }
    if (x != 1) y = mul(y, mul(x, x));
    return y;
}

int main(void) {
    int n;
    cin >> n;

    vi ps=prime_sieve(2154);
    vx primes, pcubes;
    int i;
    for (i=0; i<2154; i++) {
        if (ps[i]) {
            primes.push_back(i);
            pcubes.push_back(1LL*i*i*i);
        }
    }

    vx a(n);
    mxi count_;
    for (i=0; i<n; i++) {
        scanf("%lld", &a[i]);
        i64 n_=norm(a[i], pcubes);
        count_[n_]++;
    }

    int res=0;
    sx used;
    for (auto item: count_) {
        i64 x=item.key;
        int c=item.val;

        i64 y=anti(x, primes);
        if (used.count(x)) continue;
        if (x==y && x==1) {
            res++;
        } else {
            used.insert(x);
            if (count_.count(y)) {
                res += max(c, count_[y]);
                used.insert(y);
            } else {
                res += c;
            }
        }
    }
    cout << res << endl;
    return 0;
}

