vector<long long> Eratosthenes(long long N){
  vector<bool> v(N+1, true);
  v[0] = v[1] = false;
  long long sqN = sqrt(N);
  for(int i=2; i<=sqN; i++){
    if(v[i] == false) continue;
    for(long long j=i*i; j<=N; j+=i){
      v[j] = false;
    }
  }
  vector<long long> Prime;
  for(long long i=2; i<=N; i++){
    if(v[i]==true) Prime.push_back(i);
  }
  return Prime;
}

#include <unordered_map>


int main(){
  int n;
  cin >> n;
  vector<long long> v(n);
  for(int i=0; i<n; i++){
    scanf("%lld", &v[i]);
  }
  auto P = Eratosthenes(100000);

  unordered_map<long long, long long> square;
  for(auto p : P){
    square[p*p] = p;
  }
  long long ans = 0;

  map<long long, long long> cnt;

  for(auto& x : v){
    for(auto p : P){
      long long c = p*p*p;
      if(c > 10000000000LL) break;
      if(x == 1) break;
      while(x%c == 0) x/=c;
    }
    if(x == 1) ans = 1;
    else cnt[x]++;
  }

  for(auto& x : cnt){
    if(x.second == 0){
      continue;
    }

    long long tmp = x.first;
    long long target = 1;
    for(auto p : P){
      if(p*p*p > 10000000000LL) break;
      if(tmp == 1) break;
      if(tmp%p != 0) continue;
      target *= p;
      tmp /= p;
      if(tmp%p == 0) tmp /= p;
      else target *= p;
    }

    if(tmp != 1){
      target *= square.count(tmp) ? square[tmp] : tmp*tmp;
    }

    if(cnt.count(target)){
      ans += max(x.second, cnt[target]);
      cnt[target] = 0;
    }else{
      ans += x.second;
    }
  }
  println(ans);

  return 0;
}

