void prime(){
	for(int i = 2; i < SIZE; i++){
		if(p[i]) continue;
		for(int j = i*2; j < SIZE; j += i) p[j] = true;
	}
	for(ll i = 2; i < SIZE; i++){
		if(!p[i]){
			pr[0].push_back(i);
			pr[1].push_back(i*i);
			pr[2].push_back(i*i*i);
		}
	}
}

int main(){
	prime();
	int n;
	cin >> n;
	rep(i,n){
		cin >> s[i];
		ll tmp = 1, ss = s[i];
		rep(j,pr[2].size()){
			if(ss < pr[2][j]) break;
			while(ss%pr[2][j] == 0){
				s[i] /= pr[2][j];
				ss /= pr[2][j];
			}
			if(ss%pr[1][j] == 0){
				tmp *= pr[0][j];
				ss /= pr[1][j];
			}
			if(ss%pr[0][j] == 0){
				tmp *= pr[1][j];
				ss /= pr[0][j];
			}
			if(tmp > INF){
				tmp = 0;
				break;
			}
		}
		if(tmp == 0) continue;
		int st = 0, en = pr[0].size(), mid;
		while(en-st>1){
			mid = (st+en)/2;
			if(pr[1][mid] > ss){
				en = mid;
			} else{
				st = mid;
			}
		}
		if(ss == pr[1][st]){
			tmp *= pr[0][st];
		} else{
			tmp *= ss*ss;
		}
		if(tmp > INF) continue;
		m[s[i]]++;
		num[s[i]] = tmp;
		//cout << s[i] << " " << num[s[i]] << endl;
	}
	for(it = m.begin(); it != m.end(); it++){
		ama[counter] = (*it).first;
		counter++;
	}
	sort(ama,ama+counter);
	for(it = m.begin(); it != m.end(); it++){
		ll f = (*it).first;
		ll tmp = num[f];
		if(tmp == 0) continue;
		if(f == 1){
			hiku = hiku+(m[f]-1)*2;
			continue;
		}

		int st = 0, en = counter, mid;
		while(en-st>1){
			mid = (st+en)/2;
			if(ama[mid] > tmp) en = mid;
			else st = mid;
		}
		if(ama[st] == tmp) hiku += min(m[f],m[tmp]);
		//cout << " " << hiku << endl;
	}
	cout << n-hiku/2 << endl;
}

