ll mulmod(ll a, ll b, ll c) {
  ll x = 0, y = a % c;
  while (b) {
    if (b & 1) x = (x + y) % c;
    y = (y << 1) % c;
    b >>= 1;
  }
  return x % c;
}

ll fastPow(ll x, ll n, ll mod) {
  ll ret = 1;
  while (n) {
    if (n & 1) ret = mulmod(ret, x, mod);
    x = mulmod(x, x, mod);
    n >>= 1;
  }
  return ret;
}

vector<pair<ll,ll> >factors[ee5];
