bool isPrime(ll n) {
  if(n==1)return 1;
  ll d = n - 1;
  ll s = 0;
  while (d % 2 == 0) {
    s++;
    d >>= 1;
  }

  // It's guaranteed that these values will work for any number smaller than 3*10**18 (3 and 18 zeros)
  ll a[9] = { 2, 3, 5, 7, 11, 13, 17, 19, 23 };
  for(ll i = 0; i < 9; i++) {
    bool comp = fastPow(a[i], d, n) != 1;
    if(comp) for(ll j = 0; j < s; j++) {
      ll fp = fastPow(a[i], (1LL << (ll)j)*d, n);
      if (fp == n - 1) {
        comp = false;
        break;
      }
    }
    if(comp) return false;
  }
  return true;
}

bool issq(ll no,ll i){
	ll sqr=sqrt(no);
	ll x[3]={-1,0,1};
	for(ll j=0;j<3;j++){
		if((sqr+x[j])*(sqr+x[j])==no and !iscomposite[sqr+x[j]]){
			factors[i].eb(sqr+x[j],2);
			return true;
		}
	}
	return false;
}

