			}
			else if (ns%x1 == 0) {
				ns /= x1; nsd =kake(nsd,x2);
			}
		}
		int sq = sqrt(ns);
		if (sq*sq == ns) {
			nsd =kake(nsd,sq);
		}
		else nsd =kake(nsd, kake(ns,ns));
		spair[s[X]] = nsd;
		spair[nsd] = s[X];
		cnt[s[X]]++;
		S.insert(s[X]);
	}
	int ans = 0;
	if (cnt[1])ans++;
	while (S.size()) {
		auto itr = S.begin();
		if (*itr == 1) {
			S.erase(1);
		}
		else {
			int x = *itr, y = spair[x];
			ans += max(cnt[x], cnt[y]);
			S.erase(x);
			S.erase(y);
		}
	}
	cout << ans << endl;
}

