			res*=(t==1?i:i*i),ret*=(t==1?i*i:i);
		}
	if(c>1)
	{
		ll t=sqrt(c);
		if(t*t==c)
		{
			res*=c,ret*=t;
		}
		else
		{
			res*=c,ret*=c*c;
		}
	}
	a=res,b=ret;
}
