    	{
    		int k=prime[j];
    		if(x%k==0){
    			int cnt=0;
    			while(x%k==0){
    				x/=k;
    				cnt++;
    			}
    			cnt%=3;
    			int tmp=(3-cnt)%3;
    			while(cnt--) y*=k;
    			while(tmp--) z*=k;
    		}
    	}
    	if(x>1) y*=x,z*=(x*x);
    	mp[y]++;
    	rvs[y]=z;
    	rvs[z]=y;
    }
    int ans=0;
