map<vector<pair<int64, int>>, int> dict;

vector<pair<int64, int>> factorize3(int64 x) {
    vector<pair<int64, int>> res;
    int cnt = 0;
    while (x % 2 == 0) {
        ++cnt;
        x /= 2;
    }
    res.push_back({2, cnt});
    for (int64 i = 3; i * i <= x; i += 2) {
        if (x % i == 0) {
            cnt = 0;
            while (x % i == 0) {
                x /= i;
                ++cnt;
            }
            res.push_back({i, cnt});
        }
    }
    if (x != 1) {
        res.push_back({x, 1});
    }
    FOR(i, res.size()) {
        res[i].second %= 3;
    }
    res.erase(remove_if(all(res), [&](pair<int64, int> e) {
        return e.second == 0;
    }), res.end());
    // sort(all(res));
    return res;
}

vector<pair<int64, int>> get_rev(vector<pair<int64, int>> v) {
    for_each(all(v), [](pair<int64, int>& e) {
        e.second = 3 - e.second;
    });
    return v;
}

void solve(istream& in, ostream& out) {
    dict.clear();
    int n = next<int>(in);
    vector<int64> a = next_vector<int64>(in, n);
    for (int64 el : a) {
        auto factors = factorize3(el);
        dict[factors]++;
    }
    int res = 0;
    for (const auto& v : dict) {
        if (v.first.empty()) {
            ++res;
            continue;
        }
        auto rev_v = get_rev(v.first);
        res += max(v.second, dict[rev_v]);
        dict.erase(rev_v);
    }
    out << res << endl;
}


int main() {
    solve(cin, cout);
    return 0;
}

