void prework(int n) {
	memset(isp , 1 , sizeof(isp));
	isp[1] = 0;
	for(int i = 2;i <= n;++ i) {
		if(isp[i]) pr[++ cnt] = i;
		for(int j = 1;j <= cnt && pr[j] * i <= n;++ j) {
			isp[pr[j] * i] = 0;
			if(i % pr[j] == 0) break;
		}
	}
}

vector< pair<int,int> > Vec;

#define mp(x , y) make_pair(x , y)
#define pb push_back

void chg(int x) {
	int ano = 1 , yuan = x;
	for(int i = 1;i <= cnt;++ i) {
		int now = pr[i];
		now = now * now; now = now * 1ll * pr[i] * 1ll;
		while(x % now == 0) x /= now , yuan /= now;
		if(x % pr[i] == 0) {
			int push = pr[i] * 1ll *  pr[i];
			if(x % push) push = pr[i];
			x /= push;
			ano = ano * (now / push);
		}
	}
	if(x != 1) {
		ans ++; return;
	}
	Vec.pb(mp(yuan , ano));
//	cerr << yuan << " " <<  ano << endl;
	Map[yuan] ++;
}

void dance(void) {
	for(int i = 0;i < (int) Vec.size(); ++ i) {
