using Vec = std::vector<long long>;

int main() {
  int n;
  std::map<Vec, int> c;
  std::vector<bool> is_prime(100000, true);
  std::vector<long long> primes;
  for (int p = 2; p < 100000; ++p) {
    if (is_prime[p]) {
      primes.push_back(p);
      for (int k = 2; k * p < 100000; ++k) {
        is_prime[k * p] = false;
      }
    }
  }
  std::cin >> n;
  for (int ni = 0; ni < n; ++ni) {
    Integer x;
    std::cin >> x;
    Vec t{1, 1};
    for (int p : primes) {
      while (x % (p * p * p) == 0) x /= p * p * p;
      if (x % (p * p) == 0) {
        t[1] *= p;
        x /= p * p;
      }
      if (x % p == 0) {
        t[0] *= p;
        x /= p;
      }
    }
    t[0] *= x;
    ++c[t];
  }
  int a = 0;
  for (auto p : c) {
    auto t = p.first;
    if (Vec{c[t], t[0]} > Vec{c[{t[1], t[0]}], t[1]}) a += c[t];
  }
  std::cout << a + std::min(1, c[{1, 1}]) << std::endl;
  return 0;
}

