Int check(Int x)
{
    Int Min = 1, Max = UP2;
    while (Min < Max)
    {
        Int Mid = (Min+Max)/2;
        if (Mid*Mid < x)
            Min = Mid+1;
        else
            Max = Mid;
    }

    if (Min*Min == x)
        return Min;
    return 0;
}

map<Int, int> C;
