	int n,ans=0;
	cin>>n;
	while(n--)
	{
		s64 x;
		scanf("%lld",&x);
		s64 x1=1,x2=1;
		rep(i,1,pcnt)
		{
			int p=pr[i];
			if(x%p)continue;
			int cnt=0;
			while(x%p==0){x/=p;++cnt;}
			cnt%=3;
			if(!cnt)continue;
			if(cnt==1){x1*=p;x2*=p*p;}
			else{x1*=p*p;x2*=p;}
		}
		if(x>1)
		{
			x1*=x;
			s64 g=sqrtl(x);
			if(g*g==x)
			{
				x2*=g;
			}
			else
