	}
	for(auto pr:mp)
	{
		s64 x1=pr.first,x2=pr.second.second;
		if(x1==x2)
		{
			++ans;
			continue;
		}
		if(x2<x1)
		{
			if(mp.count(x2))continue;
			ans+=pr.second.first;
		}
		else
		{
			if(!mp.count(x2))ans+=pr.second.first;
			else ans+=max(pr.second.first,mp[x2].first);
		}
	}
	cout<<ans;
}

