#include <bits/stdc++.h>
using namespace std;
template <typename T > void read(T &t) {
	char ch=getchar();
	while (ch<'0'||ch>'9') ch=getchar();
	t=0;
	do { (t*=10)+=ch-'0'; ch=getchar(); } while ('0'<=ch&&ch<='9');
}
typedef long long ll;
const ll INF=1LL<<50;
int n;
map<ll,int> M;
map<ll,int> cnt;
ll ans;
ll solve(ll x) {
	for (ll i=2;;i++) {
		ll t=i*i*i;
		if (t>x) break;
		while (x%t==0) x/=t;
	}
	return x;
}
ll S(ll x) {
	ll l=1,r=100000;
	while (l<r) {
		ll mid=(l+r+1)>>1;
		if (mid*mid<=x) l=mid;
		else r=mid-1;
	}
	return l;
}
ll T(ll x) {
	ll A=1,B=1;
	for (ll i=2;;i++) {
		if (i*i*i>x) break;
		int ss=0;
		while (x%i==0) {
			x/=i; ss++;
		}
		if (ss==1) A*=i; else if (ss==2) B*=i;
	}
	ll tmp=S(x);
	if (tmp*tmp==x) B*=tmp;
	else A*=x;
	ll res=A*B;
	if (res>INF/A+1) res=INF; else res*=A;
	return res;
}

int main() {
	//freopen("2.txt","r",stdin);
	read(n);
	for (int i=1;i<=n;i++) {
		ll x; read(x);
		x=solve(x);
		//printf("%lld\n",x);
		M[x]++;
	}
	ans=0;
	for (map<ll,int>::iterator it=M.begin();it!=M.end();it++) {
		ll x=it->first;
		if (cnt[x]) continue;
		ll t=T(x);
		if (x!=t) ans+=max(it->second,M[t]);
		else ans++;
		cnt[t]++;
	}
	printf("%lld\n",ans);
	return 0;
}

