            while (i % (p * p * p) == 0)
                i/= p * p * p;
        }
        cnt[i]++;
        if (cmp[i] == 0) {
            i64 t = get_complement(i);
            cmp[i] = t;
            cmp[t] = i;
        }
    }

    int ans = 0;
