vector<int> sieve(int n){
    vector<bool> f(n+1);
    for(int i=3; i<=n; i+=2) f[i] = 1;
    for(int i=3; i<=sqrt(n); i+=2) if(f[i]) for(int j=i*3; j<=n; j+=i) f[j] = 0;
    vector<int> res{2};
    for(int i=3; i<=n; i+=2) if(f[i]) res.push_back(i);
    return res;
}

const ll MAX_S = 10000000000ll;

int main(){
    vi ps = sieve(3333);
    vi ps2 = sieve(100000);
    unordered_map<ll, int> sq;
    each(p, ps2)sq[p*p] = p;
    vi aaa = ps;
    each(a, aaa)a = a*a*a;

    int N;
    cin >> N;
    vll S(N);
    rep(i, N)scanf("%lld", &S[i]);

    int ans = 0, addOne = 0, cntBig = 0;

    unordered_set<ll> vals;
    unordered_map<ll, int> Norm, Pair;
    each(s, S){
        bool tooBig = false;
        ll n = s, pa = 1, m = s;
        rep(i, sz(ps)){
            int cnt = 0;
            while(n%ps[i] == 0){
                n /= ps[i];
                m /= ps[i];
                ++cnt;
            }
            cnt %= 3;
            rep(j, cnt)n *= ps[i];

            if(cnt)rep(j, 3 - cnt){
                pa *= ps[i];
                if(pa > MAX_S){
                    tooBig = true;
                    break;
                }
            }
            if(tooBig)break;
        }
        if(tooBig){
           ++cntBig;
            continue;
        }
        if(n == 1){
            addOne = 1;
            continue;
        }

        if(m != 1){
            if(sq.count(m)){
                pa *= sq[m];
            } else{
                pa *= m;
                if(pa > MAX_S)break;
                pa *= m;
            }
            if(pa > MAX_S){
                cntBig++;
                continue;
            }
        }
        vals.insert(n);
        vals.insert(pa);
        Norm[n]++;
        Pair[pa]++;
    }

    each(a, vals)
        ans += max(Norm[a], Pair[a]);
    ans /= 2;
    ans += addOne;
    ans += cntBig;
    cout << ans << endl;
}

