		if(g==2) w*=prime[i],o*=prime[i]*prime[i];
		if(x==1) break;
	}
	o*=x;
	if(x<=100002) w*=x*x;
	else w=0;
	if(mp.find(o)==mp.end()) mp[o]=0;
	mp[o]++;
	x=o;
}
