inline ll squ(ll x){ll r=sqrt(x)-1;while(r*r<x)r++;return r;}
inline ll gop(ll x){
	ll ret=1;int now=0;
	for(int p:prime){
		ll u=(ll)p*p*p;
		if(u>x)break;
