bool is_prime(int x){
    for(int i = 2;i * i <= x;i++){
        if (x % i == 0){return false;}
    }
    return true;
}

void build_primes(){
    reps(i,2,MAX){
        if (is_prime(i)) { prime_cubes.pb(1ll*i*i*i);}
    }
    reps(i,2,MAX2){
        if (is_prime(i)) { primes.pb(i);}
    }
}

ll norm(ll x){
    for (ll q:prime_cubes){
        if (q > x){ break;}
        while(x % q == 0){
            x /= q;
        }
    }
    return x;
}

const ll inf = 1e12;

ll mul(ll a, ll b) {
    if (inf / b < a)
        return inf;
    else
        return a * b;
}

ll contr(ll x){
    ll y = 1;
    for(int p: primes){
        if (1ll * p * p >x){ break;}
        // 最高で2回まで素数で割る
        // if (x % p == 0 and (x / p) % p == 0){
        if (x % (p * p) == 0){
            y = mul(y, p);
            x /= (p * p);
        }else if (x % p == 0){
            y = mul(y, mul(p,p));
            y *= (p * p);
            x /= (p);
        }
    }
    if (x != 1){
        y = mul(y, mul(x, x));
    }
    return y;
}


