inline long long Sqr(int n) {
  return (long long)n * n;
}

inline long long Cube(int n) {
  return (long long)n * n * n;
}

long long GetRest(long long a) {
  long long b = 1;
  for (int i = 0; i < cnt_prime; ++i) {
    if (a % Sqr(prime[i]) == 0) {
      b *= prime[i];
      a /= Sqr(prime[i]);
    } else if (a % prime[i] == 0) {
      b *= Sqr(prime[i]);
      a /= prime[i];
    }
  }
  long long sqrt_a = floor(sqrt(a + (long double)0.5));
  if (sqrt_a * sqrt_a == a) {
    b *= sqrt_a;
  } else {
    b *= a * a;
  }
  return b;
}

int main(void) {
  cnt_prime = 0;
  for (int n = 2; Cube(n) <= maxw; ++n) {
    bool is_prime = true;
    for (int i = 2; i * i <= n; ++i) {
      if (n % i == 0) {
        is_prime = false;
        break;
      }
    }
    if (is_prime) {
      prime[cnt_prime++] = n;
    }
  }

  scanf("%d", &n);
  for (int i = 0; i < n; ++i) {
    scanf("%lld", a + i);
    for (int j = 0; j < cnt_prime; ++j) {
