using namespace std;

long long nr[100005];
bool ciur[2505];
vector <long long> prim;
map <long long , long long> M;
map <long long , long long> inv;
long long n;

long long put (long long cont , long long x){
    long long ret = 1;
    for (long long i=1; i<=cont; i++){
        ret *= x;
    }
    return ret;
}

void Ciur(){
    for (long long i=2; i<=2500; i++){
        if (ciur[i] == false){
            prim.push_back(i);
            for (long long j =i+i; j<=2500; j++){
                ciur[j] = true;
            }
        }
    }
}

void read(){
    cin>>n;
    for (long long i=1; i<=n; i++){
        cin>>nr[i];
    }
}

void norm(){
    for (long long i=1; i<=n; i++){
        long long cop = nr[i];
        for (auto x : prim){
            if (x * x > nr[i]){
                break;
            }
            long long cont = 0;
            while (nr[i] % x == 0){
                cop /= x;
                nr[i] /= x;
                cont++;
            }
            nr[i] *= put(cont % 3 , x);
        }
        //inv_nr[i] = nr[i] * nr[i];
        M[nr[i]] ++;
        if (cop > 100000){
            //cout<<"da"<<'\n';
            continue;
        }
        inv[nr[i]] = 1LL * nr[i] * nr[i];
        //cout<<nr[i]<<'\n';
    }
    //cout<<'\n';
}

void norm2(){
    for (auto y : inv){
        for (auto x : prim){
            if (1LL * x * x > y.second){
                break;
            }
            long long cont = 0;
            while (y.second % (1LL * x) == 0){
                y.second /= 1LL * x;
                cont++;
            }
            y.second *= 1LL * put(cont % 3 , x);
        }
        //inv_nr[i] = nr[i] * nr[i];
        //cout<<y.first<<" "<<y.second<<'\n';
    }
}

void solve(){
    Ciur();
    read();
    norm();
    norm2();
    long long cont = n;
    for (auto x : M){
        if (x.first == 1){
            cont -= x.second - 1;
        }
        else{
            cont -= min(x.second , M[inv[x.first]]);
        }
    }
    cout<<cont;
}

int main() {

    ios::sync_with_stdio(false);
    cin.tie(NULL);

    solve();

    return 0;
}

