vector<int> sqf(int n) {
    vector<bool> b(n, true);
    for (int p = 2; p * p < n; p++) {
        if (b[p]) {
            for (int q = p * p; q < n; q += p * p)
                b[q] = false;
        }
    }
    vector<int> result;
    for (int p = 1; p < n; p++) if (b[p]) result.push_back(p);
    return result;
}

int main() {
    int n; cin >> n;
    unordered_map<long long, int> cnt;
    for (int i = 0; i < n; i++) {
        long long s; cin >> s;
        for (long long i = 2; i * i * i <= s; i++) {
            long long c = i * i * i;
            while (s % c == 0) s /= c;
        }
        cnt[s]++;
    }
    vector<pair<long long, long long> > S;
    vector<int> ns = sqf(100001);
    for (long long i = 0; i < ns.size(); i++) {
        long long a = ns[i];
