using Long = long long;

const int M = 2155;

bool visited[M];

Long int_sqrt(Long n)
{
    Long r = sqrt(n) + 1;
    while (r * r > n) {
        r --;
    }
    if (r * r == n) {
        return r;
    }
    return -1;
}

int main()
{
#ifdef LOCAL_JUDGE
    freopen("D.in", "r", stdin);
#endif
    for (int p = 2; p * p < M; ++ p) {
        for (int pd = p * p; pd < M; pd += p * p) {
            visited[pd] = true;
        }
    }
    std::vector<Long> free;
    for (int i = 1; i < M; ++ i) {
        if (!visited[i]) {
            free.push_back(i);
        }
    }
    int n;
    while (scanf("%d", &n) == 1) {
        int result = 0;
        std::map<Long, int> count;
        for (int i = 0; i < n; ++ i) {
            Long a;
            scanf("%lld", &a);
            for (auto p : free) {
                if (p > 1) {
                    while (a % (p * p * p) == 0) {
                        a /= p * p * p;
                    }
                }
            }
            if (a != 1) {
                Long b = 0;
                for (auto p : free) {
                    if (a % p == 0) {
                        auto q = int_sqrt(a / p);
                        if (~q) {
                            b = p * p * q;
                            break;
                        }
                    }
                }
                if (!b) {
                    for (int j = (int)free.size() - 1; j >= 0; -- j) {
                        auto q = free[j];
                        if (a % (q * q) == 0) {
                            auto p = a / (q * q);
                            b = p * p * q;
                            break;
                        }
                    }
                }
                assert(b);
                result += std::max(count[a] + 1, count[b]) - std::max(count[a], count[b]);
            }
            count[a] ++;
        }
        printf("%d\n", result + !!count[1]);
    }
}

