vector<ll>pr;
map<ll, ll>sq;
bool ispr[1000001];
void init()
{
	fill(ispr, ispr + 1000001, true);
	for (int i = 2; i <= 1000000; i++)
	{
		if (ispr[i])
		{
			for (int j = i + i; j <= 1000000; j += i)ispr[j] = false;
			pr.push_back(i);
		}
	}
	for (ll i = 2; i <= 1000000; i++)
	{
		if (ispr[i])sq[i*i] = i;
	}
}
ll getpair(ll n)
{
	ll p = 1;
	for (int i = 0;; i++)
	{
		if (pr[i] * pr[i] * pr[i] > n)break;
		if (n%pr[i] == 0)
		{
			int t = 0;
			for (;;)
			{
				if (n%pr[i] != 0)break;
				t++;
				n /= pr[i];
			}
			if (t % 3 == 1)p *= pr[i] * pr[i];
			if (t % 3 == 2)p *= pr[i];
		}
	}
	if (sq.count(n) != 0)
	{
		p *= sq[n];
		n = 1;
	}
	if (double(p)*double(n)*double(n) > (1e11))return -1;
	return p * n * n;
}
int main()
{
	int num;
	scanf("%d", &num);
	map<ll, ll>ma;
	init();
	int ans = 0;
	for (int i = 0; i < num; i++)
	{
		ll z;
		scanf("%lld", &z);
		ll t = getpair(z);
		if (t == -1)ans += 2;
		else ma[getpair(z)]++;
		//printf("%lld %lld\n", z, getpair(z));
	}
	map<ll, ll>::iterator it = ma.begin();
	for (;;)
	{
		if (it == ma.end())break;
		pii z = *it;
		it++;
		if (z.first == 1)
		{
			ans += 2;
			continue;
		}
		ll t = getpair(z.first);
		if (ma.count(t) == 0)ans += z.second * 2;
		else ans += max(z.second, ma[t]);
	}
	printf("%d\n", ans / 2);
}

