using namespace std;
typedef long long ll;
int p[200005], tot;
bool np[2205];
map<ll, ll> app, to;
int main()
{
	// freopen("AGC003-D.in", "r", stdin);
	for (int i = 2; i < 2205; i++)
	{
		if (!np[i])
			p[tot++] = i;
		for (int j = 0; j < tot && i * p[j] < 2205; i++)
		{
			np[i * p[j]] = true;
			if (!(i % p[j]))
				break;
		}
	}
	bool f = false;
	int n;
	scanf("%d", &n);
	for (int i = 0; i < n; i++)
	{
		ll x, y = 1, z = 1;
		scanf("%lld", &x);
		for (int j = 0; j < tot; j++)
		{
			int cnt = 0;
			while (!(x % p[j]))
			{
				x /= p[j];
				cnt = (cnt + 1) % 3;
			}
			int t = (3 - cnt) % 3;
			while (cnt--)
				y *= p[j];
			while (t--)
				z *= p[j];
		}
		if (x != 1)
		{
			ll k = sqrt(x);
			if (k * k == x)
			{
				y *= k * k;
				z *= k;
			}
			else
			{
				y *= x;
				z *= x * x;
			}
		}
		// cout << y << " " << z << endl;
		if (y == 1)
		{
			f = true;
			continue;
		}
		app[y]++;
		to[y] = z;
	}
	// cout << endl;
	ll ans = 0;
	for (map<ll, ll>::iterator it = to.begin(); it != to.end(); it++)
	{
		if (it->second >= it->first || !to.count(it->second))
		{
			// cout << it->first << " " << it->second << " " << app[it->first] << " " << app[it->second] << endl;
			ans += max(app[it->first], app[it->second]);
		}
	}
	printf("%lld\n", ans + f);
	return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    scanf("%d", &n);
    map<int64_t, int> s;
    for (int i = 0; i < n; ++i) {
        int64_t x;
        // x = 1LL * rand() * rand() % 10000000000 + 1;
        scanf("%lld", &x);
        s[x]++;
    }

    auto fmul = [&](int64_t a, int64_t b, int64_t p) {
        return (int64_t)((__int128)a * b % p);
        // a %= p;
        // b %= p;
        // int64_t res = 0;
        // while (b > 0) {
            // if (b & 1) (res += a) >= p ? res -= p : 0;
            // (a += a) >= p ? a -= p : 0;
            // b >>= 1;
        // }
        // return res;
    };

    auto fpow = [&](int64_t a, int64_t b, int64_t p) {
        int64_t res = 1;
        while (b > 0) {
            if (b & 1) res = fmul(res, a, p);
            a = fmul(a, a, p);
            b >>= 1;
        }
        return res;
    };

    auto Check = [&](int64_t a, int64_t u, int64_t n, int t) {
        a = fpow(a, u, n);
        if (a == 0 || a == 1 || a == n - 1) return true;
        for (int i = 0; i < t; ++i) {
            a = fmul(a, a, n);
            if (a == 1) return false;
            if (a == n - 1) return true;
        }
        return false;
    };

    auto IsPrime = [&](int64_t n) {
        constexpr array<int64_t, 4> kChk = {2, 13, 23, 1662803};
        if (n < 2) return false;
        if (n % 2 == 0) return n == 2;
        int64_t u = n - 1;
        int t = 0;
        for (; !(u & 1); u >>= 1, t++);
        for (auto v : kChk) {
            if (!Check(v, u, n, t)) return false;
        }
        return true;
    };

    auto Factorize = [&](int64_t x) {
        vector<int64_t> pr;
        function<void(int64_t)> PollardRho = [&](int64_t n) {
            if (n == 1) return;
            if (IsPrime(n)) {
                pr.push_back(n);
                return;
            }
            if (n % 2 == 0) {
                pr.push_back(2);
                PollardRho(n / 2);
                return;
            }
            int64_t x = 2, y = 2, d = 1, p = 1;

            auto f = [&](int64_t x, int64_t n, int p) {
                return (fmul(x, x, n) + p) % n;
            };

            while (true) {
                if (d != n && d != 1) {
                    PollardRho(d);
                    PollardRho(n / d);
                    break;
                }
                if (d == n) p++;
                x = f(x, n, p);
                y = f(f(y, n, p), n, p);
                d = __gcd(abs(x - y), n);
            }
        };

        PollardRho(x);
        sort(pr.begin(), pr.end());
        vector<pair<int64_t, int>> res;
        for (int i = 0, j = 0; i < pr.size(); i = j) {
            for (; j < pr.size() && pr[j] == pr[i]; ++j);
            if ((j - i) % 3) res.emplace_back(pr[i], (j - i) % 3);
        }
        return res;
    };

    int ans = 0;
    map<vector<pair<int64_t, int>>, int> mp;
    for (auto it : s) {
        auto f = Factorize(it.first);
        if (f.empty()) ans = 1;
        else mp[f] += it.second;
    }

    set<vector<pair<int64_t, int>>> seen;
    for (auto it : mp) {
        if (seen.count(it.first)) continue;
        vector<pair<int64_t, int>> inv(it.first.begin(), it.first.end());
        for (auto &k : inv) k.second = 3 - k.second;
        if (mp.find(inv) == mp.end()) {
            ans += it.second;
        } else {
            ans += max(it.second, mp[inv]);
            seen.insert(it.first);
            seen.insert(inv);
        }
    }
    printf("%d\n", ans);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
bool is_cube(long long N){
  long long c = (long long) (cbrt(N) + 0.001);
  return (c * c * c == N) || ((c + 1) * (c + 1) * (c + 1) == N) || ((c - 1) * (c - 1) * (c - 1) == N);
}
int is_square(long long N){
  long long c = (long long) (sqrt(N) + 0.001);
  if (c * c == N){
    return c;
  } else if ((c + 1) * (c + 1) == N){
    return c + 1;
  } else if ((c - 1) * (c - 1) == N){
    return c - 1;
  } else {
    return -1;
  }
}
int main(){
  int N;
  cin >> N;
  vector<long long> s(N);
  for (int i = 0; i < N; i++){
    cin >> s[i];
  }
  int cnt = 0;
  vector<long long> t;
  for (int i = 0; i < N; i++){
    if (is_cube(s[i])){
      cnt++;
    } else {
      t.push_back(s[i]);
    }
  }
  int ans = 0;
  if (cnt >= 1){
    ans++;
  }
  map<long long, int> A;
  map<long long, int> B;
  map<pair<long long, long long>, int> C;
  int M = t.size();
  for (int i = 0; i < M; i++){
    for (long long j = 2; j * j * j <= t[i]; j++){
      if (t[i] % (j * j * j) == 0){
        t[i] /= j * j * j;
      }
    } 
    int c = is_square(t[i]);
    if (c != -1){
      B[c]++;
    } else {
      bool is_C = false;
      for (long long j = 1; j * j * j <= t[i]; j++){
        if (t[i] % j == 0){
          int c = is_square(t[i] / j);
          if (c != -1 && is_square(j) == -1){
            C[make_pair(c, j)]++;
            is_C = true;
            break;
          } else {
            if (t[i] % (j * j) == 0 && is_square(t[i] / (j * j)) == -1){
              C[make_pair(j, t[i] / (j * j))]++;
              is_C = true;
              break;
            }
          }
        }
      }
      if (!is_C){
        A[t[i]]++;
      }
    }
  }
  vector<long long> val;
  for (auto P : A){
    val.push_back(P.first);
  }
  for (auto P : B){
    val.push_back(P.first);
  }
  sort(val.begin(), val.end());
  val.erase(unique(val.begin(), val.end()), val.end());
  for (long long x : val){
    ans += max(A[x], B[x]);
  }
  set<pair<long long, long long>> val2;
  for (auto P : C){
    long long x = P.first.first;
    long long y = P.first.second;
    assert(x != y);
    val2.insert(make_pair(min(x, y), max(x, y)));
  }
  for (auto P : val2){
    long long x = P.first;
    long long y = P.second;
    ans += max(C[make_pair(x, y)], C[make_pair(y, x)]);
  }
  cout << ans << endl;
}

