#include <bits/stdc++.h>
using namespace std;

map<long long, long long> match;
map<long long, int> cnt;
long long arr[100050];
bool isPrime[100050];
vector<int> prime;
long long Slove(long long n)
{
    int t = ceil(pow(n, 1.0 / 3));
    long long ret = 1;
    for(vector<int>::size_type i = 0; i < prime.size(); ++i)
    {
        if(prime[i] > t)
            break;
        if(n % prime[i] == 0)
        {
            int cnt = 0;
            while(n % prime[i] == 0)
            {
                n /= prime[i];
                ++cnt;
            }
            cnt %= 3;
            while(cnt--)
                ret *= prime[i];
        }
    }
    if(n > 1)
        ret *= n;
    return ret;
}
int main()
{
    memset(isPrime, true, sizeof(isPrime));
    for(int i = 2; i <= 100000; ++i)
    {
        if(!isPrime[i])
            continue;
        prime.push_back(i);
        for(int j = i + i; j <= 100000; j += i)
            isPrime[j] = false;
    }
    int n;
    scanf("%d", &n);
    for(int i = 1; i <= n; ++i)
        scanf("%lld", &arr[i]);
    int ans = 0;
    for(int i = 1; i <= n; ++i)
    {
        if(arr[i] == 1)
            ++cnt[1];
        else
        {
            long long a = Slove(arr[i]);
            long long b = Slove(a * a);
            ++cnt[a];
            if(a > b)
                swap(a, b);
            if(a != 1)
                match[a] = b;
        }
    }
    if(cnt.find(1) != cnt.end())
        ans = 1;
    for(auto it = match.begin(); it != match.end(); ++it)
    {
        long long a, b;
        a = it->first;
        b = it->second;
        ans += max(cnt[a], cnt[b]);
    }
    printf("%d\n", ans);
    return 0;
}

