long long create(long long numar)
{
	long long ans=1;
	for(int i=1;i<=k&&1ll*prime[i]*prime[i]<=numar;i++)
	{
		if(numar%prime[i]==0)
		{
			int power=0;
			while(numar%prime[i]==0)
			{
				power++;
				numar/=prime[i];
			}
	//		cout<<prime[i]<<" la puterea "<<power<<"\n";
			power=power%3;
			if(power==1) ans=ans*prime[i];
			else if(power==2) ans=ans*(prime[i]*prime[i]);
		}
	}
	//cout<<numar<<" la puterea 1"<<"\n";
	ans=ans*numar;
	return ans;
}

long long findcube(long long x)
{
	long long secondclass=1;
	for(int i=1;i<=k&&1ll*prime[i]*prime[i]<=x;i++)
	{
		if(x%prime[i]==0)
		{
			int power=0;
			while(x%prime[i]==0)
			{
				power++;
				x/=prime[i];
			}
			power=power%3;
			power=3-power;
	//		cout<<prime[i]<<" la puterea "<<power<<"\n";
			if(power==1) secondclass*=prime[i];
			else if(power==2) secondclass*=(prime[i]*prime[i]);
		}
	}
	secondclass=secondclass*1ll*x*x;
	return secondclass;
}

