Int powmod(Int x, Int y, Int m) {
    Int ans = 1;

    while (y > 0) {
        if (y % 2 == 1) ans = ans * x % m;

        x = x * x % m;
        y /= 2;
    }

    return ans;
}

bool suspect(Int a, int s, Int d, Int n) {
    Int x = powmod(a, d, n);

    if (x == 1) return true;

    for (int i = 0; i < s; i++) {
        if (x == n - 1) return true;

        x = x * x % n;
    }

    return false;
}

bool isprime(Int n) {
    int s = 0;
    Int d = n - 1;
    int test[9] = {2, 3, 5, 7, 11, 13, 17, 19, 23};

    if (n <= 1 || (n > 2 && n % 2 == 0)) return false;

    while (d % 2 == 0) {
        s++;
        d /= 2;
    }

    for (int i = 0; i < 9; i++) {
        if (test[i] == n) return true;
        if (suspect(test[i], s, d, n) == false) return false;
    }

    return true;
}

