    if (c > 0) {
      while (++c <= 3) {
        ret *= k;
        if (ret > M) return -1;
      }
    }
  }
  if (x == 1) return ret;

  // - p1^2  -> p1
  long long rt = sqrt(x);
  if (rt*rt == x) {
    ret *= rt;
    return ret>M?-1:ret;
  }

  auto it = lower_bound(p2.begin(), p2.end(), x);
  // - p1*p2 -> -1
  if (it == p2.end() || *it != x) return -1;
  // - p1 -> p1^2
  ret *= x; if (ret > M) return -1;
  ret *= x; if (ret > M) return -1;
  return ret;
}

