bool isCube(ll x) {
    ll y = cbrt(x);
    return y * y * y == x;
}

ll mul(ll x, ll y, ll mod) {
	ll ans = 0;
	while (y) {
		if (y & 1) ans = (ans + x) % mod;
		x = (x + x) % mod;
		y >>= 1;
	}
	re ans;
}

ll power(ll x, ll p, ll mod) {
	ll ans = 1 % mod;
	while (p) {
	 	if (p & 1) ans = mul(ans, x, mod);
	 	x = mul(x, x, mod);
	 	p /= 2;
	}
	re ans;
}

bool get(ll s, ll d, ll n) {
	ll a = 1 + eng() % (n - 1);
//	if (power (a, n - 1, n) != 1) re false;
	a = power(a, d, n);
	if (a == 1) re true;
	for (int i = 0; i < s; i++) {
		if (a == n - 1) re true;
		a = mul (a, a, n);
	}
	re false;
}

bool is_prime(ll n) {
	ll s = 0, d = n - 1;
	while (d % 2 == 0) { s++; d /= 2; }
	for (int i = 0; i < 10; i++)
		if (!get(s, d, n)) re false;
	re true;
}

ll func(ll x, ll n) {
	re (mul(x, x, n) + 1) % n;
}

void go(ll n, vll& ans) {
	if (n < inf) {
		for (ll j = 2; j * j <= n; j++)
			while (n % j == 0) {
				ans.pb(j);
				n /= j;
			}
	  	if (n > 1) ans.pb(n);
	  	re;
	}
	if (is_prime(n)) { ans.pb(n); re; }
	ll x = 1 + rand() % (n - 1);
	ll y = x;
	ll d = 1;
	while (d == 1) {
		x = func(x, n);
		y = func(func(y, n), n);
		d = (n + y - x) % n;
		d = __gcd(d, n);
	}
	go(d, ans);
	go(n / d, ans);
}

vll fact(ll n) {
	vll ans;
	go(n, ans);
	re ans;
}

vector<pll> factor(ll a) {
    vector<ll> p = fact(a);
    vector<pll> res;

    for (int i = 0; i < size(p);) {
        int j = i;
        while (j < size(p) && p[i] == p[j]) {
            ++j;
        }
        if ((j - i) % 3 != 0) {
            res.em_back(p[i], (j - i) % 3);
        }
        i = j;
    }
    return res;
}

void solve() {
    cin >> m;
    for (int i = 0; i < m; ++i) {
        ll a;
        cin >> a;
        if (isCube(a)) {
            ++cube;
        } else {
            cnt[factor(a)]++;
        }
    }

    int res = 0;
    for (auto u : cnt) {
        if (used[u.first]) {
            continue;
        }

        vector<pll> pinv = u.first;
        for (pll& p : pinv) {
            p.second = 3 - p.second;
        }

        int cntInv = cnt.count(pinv);
        int add = max(u.second, cntInv);
        res += add;

        used[u.first] = used[pinv] = 1;
    }

    cout << res + (cube > 0) << "\n";
}

int main() {
    ios::sync_with_stdio(0);
    cout.tie(0), cin.tie(0);

    int z = 1;
    /// cin >> z;

    while (z--) {
        solve();
    }

    return 0;
}

