const ll P = 239;
const ll MOD = (ll)998244353;

std::vector<ll> primes;
bool isPrime[N];
ll a[N];
std::vector<std::pair<ll, int>> f[N];

void build() {
	for (int i = 2; i < N; ++i) {
		isPrime[i] = true;
	}
	for (ll i = 2; i < N; ++i) {
		if (isPrime[i]) {
			primes.push_back(i);
			for (ll j = i * i; j < N; j += i) {
				isPrime[j] = false;
			}
		}
	}
}

ll add(ll a, ll b) {
	ll res = a + b;
	if (res >= MOD) {
		res -= MOD;
	}
	return res;
}

ll mul(ll a, ll b) {
	return a * b % MOD;
}

ll binpow(ll a, ll n) {
	if (n == 0) {
		return 1ll;
	}
	if (n % 2 == 0) {
		return binpow(mul(a, a), n / 2);
	} else {
		return mul(binpow(a, n - 1), a);
	}
}

std::vector<ll> used;

void factr(ll n, std::vector<std::pair<ll, int>>& a) {
	for (auto i : primes) {
		if (i * i > n) {
			break;
		}
		if (n % i == 0) {
			int cnt = 0;
			while (n % i == 0) {
				++cnt;
				n /= i;
			}
			cnt %= 3;
			a.push_back(std::make_pair(i, cnt));
			used.push_back(i);
		}
	}
	if (n > 1) {
		a.push_back(std::make_pair(n, 1));
		used.push_back(n);
	}
}

int main(void) {
	// freopen("test.txt", "r", stdin);
	// freopen("good.txt", "w", stdout);
	build();
	int n;
	scanf("%d", &n);
	for (int i = 0; i < n; ++i) {
		scanf("%lld", &a[i]);
	}
	std::vector<std::pair<ll, ll>> h;
	std::map<ll, int> cnt;
	for (int i = 0; i < n; ++i) {
		factr(a[i], f[i]);
		// std::cerr << cur.first << ' ' << cur.second << '\n';
		// h.push_back(cur);
		// ++cnt[cur.first];
	}
	// std::cerr << "#####\n";
	// for (auto i : cnt) {
	// 	std::cerr << i.first << ' ' << i.second << '\n';
	// }
	std::sort(used.begin(), used.end());
	used.resize(std::unique(used.begin(), used.end()) - used.begin());
	for (int i = 0; i < n; ++i) {
		ll hash = 1, revHash = 1;
		int cur = 0;
		int prev = 0;
		for (auto j : f[i]) {
			while (used[cur] < j.first) {
				++cur;
			}
			ll c = binpow(P, cur - prev);
			hash = mul(hash, c);
			revHash = mul(revHash, c);
			hash = add(hash, j.second);
			revHash = add(revHash, (3 - j.second) % 3);
			prev = cur;
		}
		ll c = binpow(P, (int)used.size() - prev);
		hash = mul(hash, c);
		revHash = mul(revHash, c);
		h.push_back(std::make_pair(hash, revHash));
		++cnt[hash];
	}
	int ans = 0;
	bool fl = false;
	for (auto i : h) {
		if (i.first == i.second) {
			fl = true;
			continue;
		}
		ans += std::max(cnt[i.first], cnt[i.second]);
		cnt[i.first] = 0;
		cnt[i.second] = 0;
	}
	if (fl) {
		++ans;
	}
	printf("%d", ans);
	// fclose(stdin);
	// fclose(stdout);
	return 0;
}

