void sieve(int n){
    memset(mk,1,sizeof(mk));mk[1]=0;
    rep(i,2,n){
        if(mk[i]) pr[++cnt]=i;
        for(int j=1;j<=cnt&&i*pr[j]<=n;++j){
            mk[i*pr[j]]=0;
            if(i%pr[j]==0) break;
        }
    }
}
int main(){
    scanf("%d",&n);
    rep(i,1,n) scanf("%lld",&a[i]);
    sieve(2200);
    rep(i,1,n){
        ll t1=1,t2=1;
        rep(j,1,cnt) if(a[i]%pr[j]==0){
            int dsy=0;
            while(a[i]%pr[j]==0) a[i]/=pr[j],++dsy;
            dsy%=3;
            rep(i,1,dsy) t1*=pr[j];
            rep(i,1,(3-dsy)%3) t2*=pr[j];
        }
        ll o=(ll)sqrt(a[i]+0.5);
        if(o*o==a[i]) t1*=o*o,t2*=o;
        else t1*=o,t2*=o*o;
        ++A[t1];B[t1]=t2;
        //printf("%lld %lld\n",t1,t2);
    }
    for(auto x:A){
        if(x.fi==1) A.erase(1),ans++;
        else ans+=max(x.se,A[B[x.fi]]),A.erase(B[x.fi]),A.erase(x.fi);
    }
    printf("%d\n",ans);
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef __int128 Int;
int n;
ll a[100005];
vector<int>p;
bool check(int x){
	for(int i=2;i*i<=x;i++)if(x%i==0)return false;return true;
}
map<Int,Int>inv,cnt;
int tag=0;
int main(){
	cin>>n;
	for(int i=1;i<=n;i++){
		cin>>a[i];
	}
	for(int i=2;i<=3333;i++)if(check(i))p.push_back(i);
	for(int i=1;i<=n;i++){
		Int val=1,Inv=1;
		for(int tt=0;tt<p.size();tt++){
			int x=p[tt];int cnt=0;
			while(a[i]%x==0){
				cnt++;a[i]/=x;
			}
			cnt%=3;
			if(!cnt)continue;
			if(cnt==1){
				val*=x;
				Inv*=x*x;
			}else{
				val*=x*x;
				Inv*=x;
			}
		}
		if(a[i]>1){
			Int tmp=sqrt(a[i]);
			while(tmp*tmp<a[i])tmp++;
			while(tmp*tmp>a[i])tmp--;
			if(tmp*tmp==a[i]){
				val*=a[i];
				Inv*=tmp;
			}else{
				val*=a[i];
				Inv*=a[i]*a[i];
			}
		}
		if(val==1){
			tag=1;continue;
		}
		cnt[val]++;inv[val]=Inv;
	}
	int ans=0;
	for(map<Int,Int>::iterator itr=cnt.begin();itr!=cnt.end();itr++){
		pair<Int,Int>p=*itr;
		int now=p.first,nxt=inv[p.first];
		if(!cnt.count(nxt)){
			ans+=cnt[now];cnt[now]=0;continue;
		}
		if(now==nxt){
			while(1);
			ans+=max((Int)1,cnt[now]);cnt[now]=0;continue;
		}
		ans+=max(cnt[now],cnt[nxt]);
		cnt[now]=cnt[nxt]=0;
	}
	cout<<ans+tag<<endl;
	return 0;
}

