// Make prime factorization faster using Sieve of Eratosthenes

constexpr ll inf = 1e+14;

class DAnticube {
public:

    ll find_pair(ll p, vector<ll>& primes) {
      map<ll, int> mp;
      int idx = 0;
      while(idx < primes.size() && primes[idx]*primes[idx] <= p) {
        while(p%primes[idx] == 0) {
          mp[primes[idx]]++;
          p /= primes[idx];
        }
        idx++;
      }
      if (p > 1) mp[p]++;

      ll ret = 1;
      for(auto e: mp) {
        if (e.second==1) {
          if (ret < inf/(e.first*e.first)) {
            ret *= e.first;
            ret *= e.first;
          } else {
            return inf;
          }
        } else {
          assert(e.second==2);
          if (ret < inf/e.first) {
            ret *= e.first;
          } else {
            return inf;
          }
        }
      }
      return ret;
    }

    void solve(istream& cin, ostream& cout) {
      SPEED;
      int n; cin >> n;

      vector<bool> check(100001, true);
      check[0] = false;
      check[1] = false;
      for(int i=2; i<=100000; i++) {
        if (check[i]) {
          for(int j=i+i; j<=100000; j+=i) {
            check[j] = false;
          }
        }
      }
      vector<ll> primes;
      for(int i=2; i<=100000; i++) {
        if (check[i]) primes.push_back(i);
      }

      vector<ll> s(n);
      rep(i, n) {
        cin >> s[i];
      }
      map<ll, int> mp;
      rep(i, n) {
        int idx = 0;
        while(idx < primes.size() && primes[idx]*primes[idx]*primes[idx]<=s[i]) {
          ll j = primes[idx];
          while (s[i]%(j*j*j)==0) {
            s[i] /= j*j*j;
          }
          idx++;
        }
        mp[s[i]]++;
      }

      int ans = 0;
      for(auto& e: mp) {
        if (e.first == 1) {
          ans++;
          continue;
        }
        ll p = find_pair(e.first, primes);
        int now = e.second;
        if (mp.find(p) != mp.end()) {
          chmax(now, mp[p]);
          mp[p] = 0;
          e.second = 0;
        }
        ans += now;
      }

      cout << ans << endl;



    }
};

signed main() {
  DAnticube solver;
  std::istream& in(std::cin);
  std::ostream& out(std::cout);
  solver.solve(in, out);
  return 0;
}

#include<bits/stdc++.h>

using namespace std;

typedef long long ll;
typedef pair<ll, ll> pi;

const ll N = 1e5 + 10;

map<pi, ll> mp;
ll pri[N], vis[N], tot = 0;
ll n, a[N];

void get_prime(ll t) {
  for (ll i = 2; i <= t; i++) {
    if (!vis[i]) {
      pri[++tot] = i;
    }
    for (ll j = 1; j <= tot && i * pri[j] <= t; j++) {
      vis[i * pri[j]] = 1;
      if (i % pri[j] == 0) {
        break;
      }
    } 
  }
}

void solve(ll vl) {
  // cout<<vl<<"+++"<<endl;
  ll pre = 1, suf = 1;
  for (int i = 1; i <= tot && pri[i] * pri[i] * pri[i] <= vl; i++) {
    int cnt = 0;
    while (vl % pri[i] == 0) {
      vl /= pri[i];
      cnt++;
    }
    cnt %= 3;
    if (cnt == 1) {
      pre *= pri[i];
    } else if (cnt == 2) {
      suf *= pri[i];
    }
  }
  ll now = sqrt(vl);
  if (now * now == vl) {
    suf *= now;
  } else {
    pre *= vl;
  }
  mp[pi(pre, suf)]++;
}

int main() {
  get_prime(30000);
  scanf("%d", &n);
  int ans = 0;
  for (ll i = 1; i <= n; i++) {
    scanf("%lld", &a[i]);
    solve(a[i]);
  }
  for (auto cur : mp) {
    int w1 = cur.first.first, w2 = cur.first.second;
    if (w1 > w2 && mp[pi(w2, w1)]) continue;
    if (w1 == w2) {
      ans++;
    } else {
      ans += max(mp[pi(w1, w2)], mp[pi(w2, w1)]);
    }
  }
  printf("%d\n", ans);
  return 0;
}

