vl prm;
bitset<3001> oki;
unordered_map<i64, i64> cnt;

inline i64 solve( i64 x ) {
    efor( y, prm ) {
        while( x % y == 0 )
            x /= y;
    }

    return x;
}

i32 main( void ) {
    ios::sync_with_stdio( false );
    cin.tie( 0 ); cout.tie( 0 );

    afor( i, 2, 3000 ) {
        if( oki[i] == false ) {
            prm.bi( 1LL * i * i * i );

            ffor( j, i + i, 3000, i )
                oki[j] = true;
        }
    }

    i64 n;
    cin >> n;

    afor( i, 1, n ) {
        i64 x;
        cin >> x;

        cnt[solve( x )] ++;
    }

    i64 ans = cnt[1] > 0; cnt[1] = 0;
    efor( pr, cnt ) {
        if( pr.first == 1 )
            continue;

        i64 aux = solve( pr.first * pr.first );

        ans += max( cnt[pr.first], cnt[aux] );
        cnt[pr.first] = cnt[aux] = 0;
    }

    cout << ans << endl;
    return 0;
}

