bool is_prime[L + 1];
std::vector<int> primes;

int main() {
  for(int i = 2; i < L; ++i) {
    is_prime[i] = true;
  }
  for(int i = 2; i < SQRTL; ++i) {
    if(is_prime[i]) {
      primes.push_back(i);
      for(int j = 1; j < L / i; ++j) is_prime[j * i] = false;
    }
  }
  scanf("%d", &N);
  for(int i = 0; i < N; ++i) {
    long long s; scanf("%lld", &s);
    long long left = 1, right = 1;
    for(int p : primes) {
      int n = 0;
      while(s % p == 0) { ++n; s /= p; }
      n %= 3;
      if(n == 1) left *= p;
      else if(n == 2) right *= p;
      if(s == 1) break;
    }
    left *= s;
    ++count[std::make_pair(left, right)];
    count[std::make_pair(right, left)];
  }
  int res = 0;
  for(auto kv : count) {
    long long left = kv.first.first, right = kv.first.second;
    if(left < right) {
      res += std::max(count[std::make_pair(left, right)], count[std::make_pair(right, left)]);
    } else if(left == right) {
      ++res;
    }
  }
  printf("%d\n", res);
  return 0;
}

