		if(y*y==x)return y;
		return 0;
	}
	const int N=100500,M=3000,MOD=1004535809,H=19260817,TOP=2200;
	int pri[M],tot;
	bool isit[M];
	void getpri()
	{
		for(int i=2;i<M;i++)
		{
			if(!isit[i])pri[++tot]=i;
			for(int j=1,x;(x=i*pri[j])<M;j++)
			{
				isit[x]=1;
				if(i%pri[j]==0)break;
			}
		}
	}
	std::map<ll,int> G;
	ll s[N];
	pii t[40];
	int n,ans,cntp;
	void initialize()
	{
		scanf("%d",&n);ans=0;
		int tmp=0;
		for(int i=1;i<=n;i++)
		{
			scanf("%lld",s+i);
			if(iscubic(s[i]))ans=1;
			else s[++tmp]=s[i];
		}
		n=tmp;
	}
	void divide(ll x)
	{
		cntp=0;
		for(int i=1;i<=tot;i++)
			if(x%pri[i]==0)
			{
				cntp++;
				t[cntp]=pii(pri[i],0);
				for(;x%pri[i]==0;x/=pri[i])
					t[cntp].y++;
				if((t[cntp].y%=3)==0)cntp--;
			}
		if(x>1)
		{
			ll y=ispsn(x);
			if(y)t[++cntp]=pii(y,2);
			else t[++cntp]=pii(x,1);
		}

	}
	ll calc()
	{
		ll ret=0;
		for(int i=1;i<=cntp;i++)
			ret=(ret*H+t[i].x*t[i].y%MOD)%MOD;
		return ret;
	}

	void solve()
	{
		getpri();
		initialize();

		for(int i=1;i<=n;i++)
		{
			divide(s[i]);
			ll hx=calc(),hy;
			for(int j=1;j<=cntp;j++)
				t[j].y=3-t[j].y;
			hy=calc();

			int cx=G[hx],cy=G[hy];
			if(cx>=cy)ans++;
			G[hx]++;
		}
		printf("%d\n",ans);
	}
