const long long Curt = 2154;
const long long MAX = 10000000000;

int main() {
	vector<bool> B(Curt + 1, true);
	vector<long long> Primes;
	for (int i = 2; i <= Curt; i++) {
		if (B[i]) {
			Primes.push_back(i);
			for (int j = 2; i * j <= Curt; j++) {
				B[i * j] = false;
			}
		}
	}
	int N;
	cin >> N;
	vector<long long> S(N);
	map<long long, long long> mp;
	for (int i = 0; i < N; i++) {
		cin >> S[i];
		for (long long P : Primes) {
			while (S[i] % (P * P * P) == 0) {
				S[i] /= (P * P * P);
			}
		}
		mp[S[i]]++;
	}
	int ANS = 0;
	vector<pair<long long, long long> > Chain;
	for (auto it = mp.begin(); it != mp.end(); it++) {
		long long X = it->first;
		long long Y = 1;
		long long Sq;
		if (X == 1) {
			ANS++;
			goto NEXT;
		}
		for (long long P : Primes) {
			if (X % (P * P) == 0) {
				Y *= P;
				X /= P * P;
			}
			else if (X % P == 0) {
				Y *= (P * P);
				X /= P;
			}
			if (Y > MAX) {
				ANS += it->second;
				goto NEXT;
			}
		}
		if (Y > MAX) {
			ANS += it->second;
			goto NEXT;
		}
		Sq = sqrt(X);
		if (Sq * Sq == X) {
			Y *= Sq;
		}
		else {
			if (X > sqrt(MAX)) {
				ANS += it->second;
				goto NEXT;
			}
			Y *= X;
			if (Y > MAX) {
				ANS += it->second;
				goto NEXT;
			}
			Y *= X;
		}
		if (Y > MAX) {
			ANS += it->second;
			goto NEXT;
		}
		Chain.push_back({ it->first, Y });
	NEXT:;
	}
	for (pair<long long, long long> C : Chain) {
		if (mp[C.second] > 0) {
			if (C.first < C.second) ANS += max(mp[C.first], mp[C.second]);
		}
		else {
			ANS += mp[C.first];
		}
	}
	cout << ANS << endl;
}

