typedef long long ll;

int n;
ll s[100000];
ll nrml[100000];
bool p[100000];
vector<int> pt;
vector<int> pm;
vector<ll> ps;
map<ll, int> cnrm;

void prm(){
	fill_n(p + 2, 100000 - 2, true);
	rep(i, 100000){
		if(p[i]){
			for(int j = 2 * i; j < 100000; j += i){
				p[j] = false;
			}

			if(i < 3000){
				pt.push_back(i);
			}
			pm.push_back(i);
			ps.push_back(ll(i) * i);
		}
	}
}

ll nrm(ll x){
	for(int v: pt){
		ll v3 = ll(v) * v * v;
		while(x % v3 == 0){
			x /= v3;
		}
	}
	return x;
}

ll pr(ll x){
	ll k = 1;
	for(int v: pt){
		if(x % (v * v) == 0){
			x /= (v * v);
			k *= v;
		}
		else if(x % v == 0){
			x /= v;
			k *= v * v;	
		}
	}
	if(binary_search(ps.begin(), ps.end(), x)){
		int idx = lower_bound(ps.begin(), ps.end(), x) - ps.begin();
		return pm[idx] * k;
	}
	return x * x * k;
}

int main(){
	cin >> n;
	rep(i, n){
		cin >> s[i];
	}

	prm();

	rep(i, n){
		nrml[i] = nrm(s[i]);
		++cnrm[nrml[i]];		
	}

	int ans = 0;
	rep(i, n){
		ll a = nrml[i];
		ll b = pr(a);

		if(a == 1 && cnrm[a]){
			++ans;
			cnrm[a] = 0;
		}
		else{
			ans += max(cnrm[a], cnrm[b]);
			cnrm[a] = cnrm[b] = 0;
		}
	}
	cout << ans << endl;
	return 0;
}

