	}

	if(s.count(1))  {
		ans = 1;
		s.erase(1);
	}

	auto it = s.begin();
	while(it != s.end())    {
		int x = it -> first;
		int y = f[x];
		if(s[x] < s[y]) swap(x,y);
		ans += s[x];
		s.erase(x);
		s.erase(y);
		it = s.lower_bound(x);
	}

	cout << ans << endl;
}

