inline pair<ll,ll> root(ll x)
{
    ll val=1,reverse_val=1;
    for (auto i: Pr)
    {
        if(i*i>x) break;
        if(x%i==0)
        {
            int num=0;
            while(x%i==0)
            {
                num++;
                x/=i;
            }
            num%=3;
            val = val * pow(i , num);
            reverse_val = reverse_val * pow(i , 3 - num);
        }
    }
    if(x>1)
    {
        val *= x; 
        reverse_val *= x * x; 
    }
    return mp(val,reverse_val);
}


