const int SIZE = 1000000;
vector<ll> primes;
bool isPrime[SIZE];

void make_primes() {
  if (primes.size() > 0) return;
  memset(isPrime, true, sizeof(isPrime));
  isPrime[0] = isPrime[1] = false;
  for (int i = 2; i * i < SIZE; i++) 
    if (isPrime[i])
      for (int j = i * i; j < SIZE; j += i)
        isPrime[j] = false;
  REP(i, SIZE) if (isPrime[i]) primes.push_back(i);
}


map<ll, int> factorize(ll n) {
  map<ll, int> ps;
  for (int i = 0; primes[i] * primes[i] <= n; i++) {
    while (n % primes[i] == 0) {
      ++ps[ primes[i] ];
      n /= primes[i];
    }
  }
  if (n > 1) ++ps[n];
  map<ll, int> res;
  for (auto it = ps.begin(); it != ps.end(); ++it) {
    int k = it->second % 3;
    if (k != 0) {
      res[it->first] = k;
    }
  }
  return res;
}

map<ll, int> inverse(const map<ll,int> a) {
  map<ll, int> b;
  for (auto it = a.begin(); it != a.end(); ++it) {
    b[ it->first ] = 3 - it->second;
  }
  return b;
}

int main2() {
  int N = nextInt();

  map< map<ll,int>, int > mp;
  REP(i, N) {
    ll s = nextLong();
    ++mp[ factorize(s) ];
  }
  ll ans = 0;
  ll tw = 0;
  for (auto it = mp.begin(); it != mp.end(); ++it) {
    const auto a = it->first;
    const int ca = it->second;
    if (a.size() == 0) {
      ans++;
      continue;
    }
    const auto b = inverse(a);
    const int cb = mp.find(b) == mp.end() ? 0 : mp[b];
    if (cb == 0) ans += ca;
    else {
      tw += max(ca, cb);
    }
  }
  ans += tw / 2;
  cout << ans << endl;
  return 0;
}

