			int cnt = 0;
			for(; m % prime[i] == 0; cnt++) m /= prime[i];
			cnt %= 3;
			rep(it, cnt) v.pb(prime[i]);
		}
		if(m > 1) v.pb(m);
		sort(all(v));
		M[v]++;
	}

	done.insert(vector<ll>());
	for(auto m: M){
		if(done.count(m.first)) continue;
		auto mm = comp(m.first);

		if(M.count(mm)){
			int l = m.second, r = M[mm];
			ans += max(l, r);
			done.insert(mm);
		}
		else ans += m.second;
	}
	if(M.count(vector<ll>())) ans++;
	cout << ans << endl;
	return 0;
}

