			int c = 0;
			while (x % prime[i] == 0) x /= prime[i],x1 *= prime[i],c++;
			F0R(j,3-c) x2 *= prime[i];
		}
	}
	for (;i<prime.size();++i) {
		if (prime[i]*prime[i]>x) break;
		if (x % prime[i] == 0) {
			int c = 0;
			while (x % prime[i] == 0) x /= prime[i], x1 *= prime[i],c++;
			F0R(j,3-c) x2 *= prime[i];
		}
	}
	if (x>1) x2 *= (x*x);
	return mp(x*x1,x2);
}

