inline bool is_prim(LL x) {
	LL y = sqrt(x);
	return y * y == x;
}
void pre(int n) {
	for(int i = 2, f = 1; i <= n; ++i, f = 1) {
		for(int j = 2; j < i && f; ++j)
			if(i % j == 0) f = 0;
		if(f) pr[++pcnt] = i;
	}
}
LL calc(LL x) {
	LL y = 1;
	for(int i = 1; i <= pcnt; ++i) {
		if(x % pr[i]) continue;
		int cnt = 0;
		while(x % pr[i] == 0)
			x /= pr[i], ++cnt;
		cnt %= 3;
		if(!cnt) continue;
		for(int j = 1; j <= 3 - cnt; ++j)
			y *= pr[i];
	}
	if(x == 1) return y;
	y *= is_prim(x) ? (LL) sqrt(x) : x * x;
	return y;
