#include<bits/stdc++.h>
using namespace std;

vector<int> primes;
const int CBRT = 2200;
long long cb[CBRT];
const long long LIM = 1e10+5;


void sieve() {
    vector<bool> isp(CBRT, 1);
    for (int i=2; i<CBRT; i++)
        if (isp[i]) {
            primes.push_back(i);
            for (int j=2*i; j<CBRT; j+=i)
                isp[j] = 0;
        }
    for (int i=0; i<CBRT; i++)  cb[i] = 1LL*i*i*i;
}

pair<long long, long long> process(long long x) {
    if (x == 1)     return {1, 1};

    for (long long p:primes)
        while (x%cb[p]==0)  x/=cb[p];

    long long a = x;

    for (int i=1; i<CBRT; i++)
        if (cb[i]%a==0)
            return {a, cb[i]/a};

    return {a, LIM};
}

const int N = 1e5+7;
long long a[N], b[N];

int main() {
    ios::sync_with_stdio(0);
    cin.tie(0);

    sieve();

    int n;
    cin>>n;

    map<long long, int> cnt;
    map<long long, long long> opp;

    for (int i=1; i<=n; i++) {
        long long x;
        cin>>x;

        auto pr = process(x);
        a[i] = pr.first;
        b[i] = pr.second;

//        cout<<x<<" "<<a[i]<<" "<<b[i]<<endl;

        cnt[a[i]]++;
        opp[a[i]] = b[i];
        opp[b[i]] = a[i];
    }
    cnt[LIM] = 0;

    long long ans = 0;
    for (auto pr: opp) {
        long long a = pr.first, b = pr.second;
        if (a == b)     ans += min(1, cnt[a]+cnt[b]);
        else if (a < b) ans += max(cnt[a], cnt[b]);
    }
    cout<<ans<<endl;
}

