		LL x=1,y=1;
		for(int j=1;j<=cnt;j++)
		{
			tot=0;
			if(a[i]<pri[j])break;
			if(a[i]%pri[j])continue;
			while(a[i]%pri[j]==0)
			{
				tot++;
				a[i]/=pri[j];
			}
			if(tot%3==0)continue;
			if(tot%3==1)x*=pri[j],y*=pri[j]*pri[j];
			if(tot%3==2)x*=pri[j]*pri[j],y*=pri[j];
		}
		if(a[i]!=1)
		{
			LL tmp=sqrt(a[i]);
			if(tmp*tmp==a[i])x*=a[i],y*=tmp;
			else x*=a[i],y*=a[i]*a[i];
		}
		mp[x]++;
		xiubi[x]=y,xiubi[y]=x;
	}
	map<LL,int>::iterator it;
	if(mp.find(1)!=mp.end())
	{
		ans=1;
		mp.erase(1);
	}
	for(it=mp.begin();it!=mp.end();it++)
	{
		if(mp.find(xiubi[it->first])==mp.end())
		{
			ans+=it->second;
		}else
		{
			ans+=max(it->second,mp[xiubi[it->first]]);
			it->second=mp[xiubi[it->first]]=0;
		}
	}
	printf("%d",ans);
}

