typedef long long ll;

using namespace std;

vector<ll> cubes;

void makeCubes(){
    for(ll i = 2; i*i*i<1e10; i++){
        cubes.push_back(i*i*i);
    }
    reverse(ALL(cubes));
}

bool isCube(ll n){
    ll root = pow(n, 1.0 / 3.0);
    if(n == root * root * root)return true;
    root++;
    if(n == root * root * root)return true;
    return false;
}

int main(){
    makeCubes();
    ll  n;
    cin >> n;
    vector<ll> v(n);
    rep(i, n){
        cin >> v[i];
        rep(j, cubes.size()){
            while(v[i] % cubes[j] == 0)v[i] /= cubes[j];
        }
    }
    map<ll, ll> num;
    rep(i, n){
        num[v[i]]++;
    }

    vector<ll> keys;
    FOR(it, num){
        keys.push_back(it->first);
    }

    ll ans = 0;
    if(keys[0] == 1)ans++;

    set<int> skips;
    REP(i, 1, keys.size()){
        bool found = false;
        if(skips.count(i))continue;
        REP(j, i+1, keys.size()){
            if(skips.count(j))continue;
            ll p = keys[i] * keys[j];
            if(isCube(p)){
                found = true;
                ans += max(num[keys[i]], num[keys[j]]);
                skips.insert(j);
                break;
            }
        }
        if(!found){
            ans += num[keys[i]];
        }
    }
    cout << ans <<endl;
    return 0;
}

