using lint = long long;

int main() {
  const int N = scan<int>();
  std::unordered_map<lint, int> count;
  std::unordered_map<lint, bool> used;
  for (int i: frep(0, N)) {
    lint x, max;
    std::cin >> x;
    for (lint t = 1; t * t * t <= x; ++t) {
      if (x % (t * t * t) == 0) { 
        max = t;
      }
    }
    count[x / (max * max * max)]++;
  }
  int ans = 0;
  for (auto p: count) {
    if (p.first == 1) {
      ++ans;
      used[p.first] = true;
      continue;
    }
    lint max;
    for (lint t = 1; t * t * t < p.first; ++t) {
      if (p.first % (t * t) == 0) {
        max = t;
      }
    }
    lint nx = p.first / (max * max);
    if (nx <= 10000000000ll / (nx * max)) {
      lint y = nx * nx * max;
      if (count.find(y) != count.end()) {
        ans += std::max(p.second, count[y]);
        used[p.first] = true;
        used[y] = true;
      }
    }
    if (!used[p.first]) {
      ans += p.second;
      used[p.first] = true;
    }
  }
  std::cout << ans << '\n';
  return 0;
}

