ll pow_mod(ll a, ll n, ll mod)
{
	ll ret = 1;
	a %= mod;
	while(n)
	{
		if(n & 1) ret = (__int128)ret * a % mod;
		a = (__int128)a * a % mod; n >>= 1;
	}
	return ret;
}
bool check(ll a, ll n, ll x, ll t)
{
	ll ret = pow_mod(a, x, n);
	ll last = ret;
	for(int i = 1; i <= t; ++i)
	{
		ret = (__int128)ret * ret % n;
		if(ret == 1 && last != 1 && last != n - 1) return true;
		last = ret;
	}
	if(ret != 1) return true;
	else return false;
}
bool miller_rabin(ll n) 
{
	if(n < 2) return false;
	if(n == 2 || n == 3 || n == 7 || n == 61 || n == 24251) return true;
	if((n & 1) == 0) return false;
	ll x = n - 1;
	ll t = 0;
	while((x & 1) == 0) { x >>= 1; ++t;}
	srand(time(0));
	for(int i = 0; i < S; ++i)
	{
		ll a = rand() % (n - 1) + 1;
		if(check(a, n, x, t)) return false;
	}
	return true;
}
ll pollard_rho(ll x, ll c)
{
	ll i = 1, k = 2;
	srand(time(0));
	ll x0 = rand() % (x - 1) + 1;
	ll y = x0;
	while(true)
	{
		++i;
		x0 = ((__int128)x0 * x0 % x + c) % x;
		ll d = abs(__gcd(y - x0, x));
		if(d != 1 && d != x) return d;
		if(y == x0) return x;
		if(i == k) { y = x0; k <<= 1;}
	}
}
