	ct = 0;
	find(n, 120);
	sort(fac, fac + ct);
	num[0] = 1;
	int k = 1;
	for(int i=1; i<ct; i++)
	{
		if(fac[i] == fac[i-1])
			++num[k-1];
		else
		{
			num[k] = 1;
			fac[k++] = fac[i];
		}
	}
	cnt = k;
}

