      else if (!(A[i] % j))
        B[i] *= P_2[j];
    }
    mp[A[i]]++;
  }
  for (int i = 1; i <= N; i++) {
    if (!mp[A[i]]) continue;
    if (A[i] != B[i])
      Ans += max(mp[A[i]], mp[B[i]]), mp[A[i]] = mp[B[i]] = 0;
    else
      Ans += (mp[A[i]] + 1) / 2, mp[A[i]] = 0;
  }
  printf("%d\n", Ans);
  return 0;
}

