#include <bits/stdc++.h>
using namespace std;

const int N = 100010;
const long long inf = 1e18;

int np[N];
vector<int> prime;
int n;
int matching;
map <long long, int> mp;

void sieve() {
	np[0] = np[1] = 1;
	for (int i = 2; i < N; ++i) if (!np[i]) {
		for (int j = i + i; j < N; j += i) np[j] = 1;
		prime.push_back(i);
	}
}

int main() {
	ios_base::sync_with_stdio(false); cin.tie(0);
	sieve();
	cin >> n;
	for (int i = 1; i <= n; ++i) {
		long long s; cin >> s;
		long long cur = 1;
		long long rcur = 1;
		for (int j = 0; j < (int)prime.size() && 1ll * prime[j] * prime[j] <= s; ++j) {
			if (s % prime[j]) continue;
			int cnt = 0;
			while(s % prime[j] == 0) s /= prime[j], ++cnt;
			cnt %= 3;
			for (int k = 0; k < cnt; ++k) cur *= prime[j];
			cnt = (3 - cnt) % 3;
			for (int k = 0; k < cnt; ++k) {
				if (rcur > inf / prime[j]) { rcur = inf; continue; }
				rcur *= prime[j];
			}
		}

		if (s >= N) continue;
		else {
			if (s != 1) {
				cur *= s;
				if (rcur > inf / (s * s)) rcur = inf;
				else rcur *= s * s;
			}
			if (rcur != inf && mp[rcur] != 0) --mp[rcur], ++matching;
			else ++mp[cur];
		}
	}

	cout << n - matching << endl;
}

