void gh() {
	inp[0] = inp[1] = true;
	for (int i = 2; i < MAXN; i++)
		if (!inp[i]) {
		    tof[(ll)i * i] = i;
		    if (i < MXR3)
		    	p.push_back(i);
			for (ll j = (ll)i * i; j < MAXN; j += i)
				inp[j] = true;
		}
