					cnt++;
					s[i] /= prime[j];
				}
				else {
					break;
				}
			}
			cnt %= 3;
			b[i] *= mod_pow(prime[j], cnt, MOD);
			if (cnt != 0)p[i] *= mod_pow(prime[j], 3 - cnt, MOD);
		}
		if (b[i] == 1 && s[i] == 1) {
			flag = 1;
			p[i] = -INF;
			continue;
