					temp2 /= 10;
					cnt++;
				}
				if (cnt >= 12)p[i] = INF;
				else p[i] *= prime2[s[i]];
			}

			mp[b[i]]++;
		}
		else if (s[i] == 1) {
			mp[b[i]]++;
		}
		else {
