		long long x; cin >> x;
		long long Norm = 1, Pair = 1;
		for(int v : primes){
			int cnt = 0;
			while(x % v == 0) x /= v, cnt++;
			cnt %= 3;
			if(!cnt) continue;
			if(cnt == 1){
				Norm *= v;
				Pair *= v;
				Pair *= v;
			} else {
				Norm *= v;
				Norm *= v;
				Pair *= v;
			}
		}
		if(x > 1){
			long long sq = sqrtl(x);
			while(sq * sq <= x) sq++;
			while(sq * sq > x) sq--;
			if(sq * sq == x){
				Norm *= x;
				Pair *= sq;
			} else {
				Norm *= x;
				Pair *= x;
				Pair *= x;
			}
		}
		rev[Norm] = Pair;
		rev[Pair] = Norm;
		occ[Norm]++;
		occ[Pair];
	}
