const int MAX = 10000000;
int min_factor[MAX+1];
vector<int>prime;
void make_prime() {
    for (int i=2; i<=MAX; i+=2) min_factor[i] = 2;
    for (int i=3; i<=MAX; i+=3) if (!min_factor[i]) min_factor[i] = 3;
    for (int i=5, d=2; i*i<=MAX; ) {
	if (!min_factor[i]) {
	    min_factor[i] = i;
	    for (int j=i*i; j<=MAX; j+=i)
		if (!min_factor[j]) min_factor[j] = i;
	}
	i += d; d = 6 - d;
    }
    for (int i=2; i<=MAX; i++) {
	if (min_factor[i]==0) min_factor[i] = i;
	if (min_factor[i]==i) prime.push_back(i);
    }
}

typedef unsigned long long ULL;

inline ULL mulMod(ULL x, ULL y, ULL m) {
    if (x >= m) x %= m;
    if (y >= m) y %= m;
    if (x < (1ULL<<31) && y < (1ULL<<31)) return x * y % m;
    ULL r = 0;
    for (; y; y>>=1) {
	if (y&1) { if ((r += x) >= m) r -= m; }
	if ((x += x) >= m) x -= m;
    }
    return r;
}
ULL powMod(ULL x, ULL y, ULL m) {
    if (x >= m) x %= m;
    ULL r = 1;
    for (; y; y>>=1) {
	if (y&1) r = mulMod(r, x, m);
	x = mulMod(x, x, m);
    }
    return r;
}
bool suspect(ULL a, unsigned s, ULL d, ULL n) {
    ULL x = powMod(a, d, n);
    if (x == 1) return true;
    for (unsigned r = 0; r < s; ++r) {
	if (x == n - 1) return true;
	x = mulMod(x, x, n);
    }
    return false;
}
// {2,7,61,-1}                 is for n < 4759123141 (= 2^32)
// {2,3,5,7,11,13,17,19,23,-1} is for n < 10^16 (at least)
bool is_prime(ULL n) {
    if (n <= 1 || (n > 2 && n % 2 == 0)) return false;
    if (n < MAX) return (ULL) min_factor[n] == n;
    int test[] = {2,3,5,7,11,13,17,19,23,-1};
    ULL d = n - 1, s = 0;
    while (~d & 1) { ++s; d>>=1; }
    for (int i = 0; (ULL)test[i] < n && test[i] != -1; ++i)
	if (!suspect(test[i], s, d, n)) return false;
    return true;
}

inline LL rnd(LL y, LL c, LL n) {
    // return (y * y + c) % n;
    LL r = mulMod(y, y, n);
    if ((r+=c) >= n) r -= n;
    return r;
}
// !! To check MIllar Rabin n, must be a composite number
// Pollard's rho Algorithm Brent's improvement
// find a divisor of n (if n is not a prime).
LL divisor(LL n, LL c = 1) { 
    LL y = n, r = 1, q = 1, ys = 0, x = 0, m = 256;
    LL g = 1;
    while (g == 1) {
	x = y;
	for (int i=0; i<r; i++) y = rnd(y, c, n);
	int k = 0;
	while (k < r && g == 1) {
	    ys = y;
	    for (int i=0, i_len=min(m, r-k); i<i_len; i++) {
		y = rnd(y, c, n);
		q = mulMod(q, llabs(x-y), n);
	    }
	    g = __gcd(q, n);
	    k += m;
	}
	r *= 2;
    }
    if (g == n) {
	do {
	    ys = rnd(ys, c, n);
	    g = __gcd(llabs(x-ys), n);
	} while (g == 1);
	if (g == n) return divisor(n, c+1);
    }
    return g;
}


