vector<pair<LL, int> > fast_prime_factor(int n) { // n<=MAX
    vector<pair<LL, int> >r;
    while (n > 1) {
	int t = min_factor[n], cnt = 0;
	while (n%t == 0) { n /= t, cnt++; }
	r.push_back(make_pair(t, cnt));
    }
    return r;
}
vector<pair<LL, int> > hard_prime_factor(LL n) {
    if (n <= MAX) {
	return fast_prime_factor(n);
    } else if (is_prime(n)) {
	return vector<pair<LL, int> >(1, make_pair(n, 1));
    } else {
	LL d = divisor(n);
	vector<pair<LL, int> > a = hard_prime_factor(d);
	vector<pair<LL, int> > b = hard_prime_factor(n/d);
	sort(a.begin(), a.end());
	sort(b.begin(), b.end());
	for (int i=0, j=0; j<(int)b.size(); j++) {
	    while (i < (int)a.size() && a[i].first < b[j].first) i++;
	    if (i < (int)a.size() && a[i].first == b[j].first) a[i].second += b[j].second;
	    else a.push_back(b[j]);
	}
	return a;
    }
}


LL nm[100111], inv[100111];

pair<LL, LL> nm_inv(LL n) {
    vector<pair<LL, int> > f = hard_prime_factor(n);
    LL nm = 1, inv = 1;
    EACH (e, f) {
	if (e->second % 3 == 1) {
	    nm *= e->first;
	    inv *= e->first * e->first;
	} else if (e->second % 3 == 2) {
	    inv *= e->first;
	    nm *= e->first * e->first;
	}
    }
    return make_pair(nm, inv);
}

int N;
LL S[100111];
