    for (int j = i + i; j < MAX_N; j += i) vis[j] = 1;
  }
  int N;
  RI(N);
  unordered_map<ll, int> cnt;
  REP(i, N) {
    RI(A[i]);
    A[i] = norm(A[i]);
    cnt[A[i]]++;
  }
  int ans = 0;
  unordered_set<ll> used;
  for (auto it : cnt) {
    ll x = it.F;
    if (used.count(x)) continue;
    ll y = conj(x);
    used.insert(x);
    if (y == INF64 || x == y || !cnt.count(y)) {
      ans += it.S;
      continue;
    }
    ans += max(it.S, cnt[y]);
    used.insert(y);
  }
  PL(ans);
  return 0;
}

