const int S=8;
ll mult_mod(ll a,ll b,ll c){
    a%=c; b%=c;
    ll ret=0,tmp=a;
    while (b){
        if (b&1){
            ret+=tmp;
            if (ret>c) ret-=c;
        }
        tmp<<=1;
        if (tmp>c) tmp-=c;
        b>>=1;
    }
    return ret;
}
ll pow_mod(ll a,ll n,ll M){
    ll ret=1,tmp=a%M;
    while (n){
        if (n&1) ret=mult_mod(ret,tmp,M);
        tmp=mult_mod(tmp,tmp,M);
        n>>=1;
    }
    return ret;
}
bool check(ll a,ll n,ll x,ll t){
    ll ret=pow_mod(a,x,n);
    ll last=ret;
    for (int i=1;i<=t;i++){
        ret=mult_mod(ret,ret,n);
        if (ret==1 && last!=1 && last!=n-1) return true;
        last=ret;
    }
    if (ret!=1) return true; else return false;
}
bool Miller_Rabin(ll n){
    if (!(n&1)) return false;
    ll x=n-1,t=0;
    while (!(x&1)){
        x>>=1;
        t++;
    }
    mt19937 mt(time(0));
    for (int i=0;i<S;i++){
        ll a=mt()%(n-1)+1;
        if (check(a,n,x,t)) return false;
    }
    return true;
}
