LL decompose(int id){
        FOE(i, 1, cnt2){
                LL m3 = p3[i];
                while (id % m3 == 0) id /= m3;
        }
        return id;
}

void handle(LL id){
        if (id == 1){
                ret++;
                return;
        }

        LL opp = 1, cnt3 = M[id];

        LL left = id;

        FOE(i, 1, cnt2){
                LL m2 = p2[i];
                LL m1 = p1[i];

                if (id % m2 == 0) {
                        opp *= m1; left /= m2;
                }
                else if (id % m1 == 0) {
                        opp *= m2; left /= m1;
                }

                if (opp > (LL)10000000000){
                        ret += cnt3; return;
                }
        }

        LL y = sqrt(left);
        if (y * y == left && !p[y]){
                opp = opp * y;
        }
        else {
