			if(Seive[temp] == false)
			{
				x *= temp;
				y *= temp * temp;
			}
		}
		if(x > 10000000000ll or y > 10000000000ll)
		{
			ans++;
			continue;
		}
		if(x == y)
		{
			t++;
			continue;
		}
		M[mp(x, y)]++;
	}
	while(M.empty() == false)
	{
		auto xx = *M.begin();
		ans += max(xx.se, M[mp(xx.fi.se, xx.fi.fi)]);
		M.erase(xx.fi);
		M.erase(mp(xx.fi.se, xx.fi.fi));
	}
	cout << ans + (t > 0);
}

