    int rt = sqrt(x);
    while (rt * (ll)rt < x) ++rt;
    while (rt * (ll)rt > x) --rt;
    return rt * (ll)rt == x ? rt : -1;
  };
  function<ll(ll)> dual = [&](ll x) {
    int cur;
    for (int k = 1; k <= searchLimit; ++k)
      if (x % k == 0 && (cur = pSQRT(x / k)) != -1)
        return k * k * (ll)cur;
