using namespace std;

vector<int> primes(int n) {
    vector<bool> b(n, true);
    for (int p = 2; p * p < n; p++) {
        if (b[p]) {
            for (int q = p * p; q < n; q += p)
                b[q] = false;
        }
    }
    vector<int> ps;
    for (int p = 2; p < n; p++) if (b[p]) ps.push_back(p);
    return ps;
}

int main() {
    int n; cin >> n;
    vector<int> ps = primes(100000);
    unordered_map<long long, int> dual, cnt;
    int ans = 0;
    for (int i = 0; i < n; i++) {
        long long s; cin >> s;
        long long u = 1, v = 1;
        for (long long p : ps) {
            if (p * p > s) break;
            if (s % p == 0) {
                int e = 0;
                do { e++; s /= p; } while (s % p == 0);
                e %= 3;
                if (e == 1) u *= p;
                else if (e == 2) v *= p;
            }
        }
        if (s > 1) u *= s;
        if (u > 1e5 || u * u * v > 1e10) ans++;
        else {
            long long x = u * v * v, d = u * u * v;
            dual[min(x, d)] = max(x, d);
            cnt[x]++;
        }
    }
    for (auto &[x, y] : dual) ans += (x > 1 ? max(cnt[x], cnt[y]) : 1);
    cout << ans << endl;
}

