    vector<pair<int,int>> cur;
    int add = 0;
    int result = 0;
    for (int i = 0; i < n; ++i) {
        long long x;
        cin >> x;
        cur.clear();
        for (auto& y : primes) {
            if (y > x) break;
            int cnt = 0;
            while (x % y == 0) {
                x /= y;
                ++cnt;
            }
            cnt %= 3;
            if (cnt > 0) {
                cur.emplace_back(y, cnt);
            }
        }
        if (x > 1) {
            ++result;
        } else {
            if (cur.empty()) {
                add = 1;
                continue;
            }
            ++mp[cur];
        }
    }
    result += add;
    result *= 2;
    for (auto& x : mp) {
        cur.clear();
        vector<pair<int,int>> now = x.first;
        for (auto& y : now) 
            cur.emplace_back(y.first, 3 - y.second);
        if (mp.count(cur))
            result += max(mp[now], mp[cur]);
        else
            result += 2 * x.second;
    }
    result /= 2;
    cout << result << endl;
    return 0;
}

