            {
                m[plint(i, sqrt(v / i + 0.5))]++;
                finished = true;
                break;
            }
        }
        if (!finished) IFOR(i, 1, M + 1)
        {
            if (v / i / i * i * i == v and !squares.count(v / i / i))
            {
                m[plint(v / i / i, i)]++;
                finished = true;
                break;
            }
        }
        if (!finished) ans++;
