        ll vl = cur.first, sv = cur.first;
        if (usd.find(cur.first) != usd.end()) continue;
        if (vl > SIZE) {
            add += cur.second;
            continue;
        }
        map<ll, ll> dls;
        while (vl != 1) {
            dls[lp[vl]]++;
            vl /= lp[vl];
        }

        ll snd = 1;
        for (auto cur : dls) {
            ll am = 3 - cur.second % 3;

            if (am == 1) snd *= cur.first;
            if (am == 2) snd *= cur.first * cur.first;
        }

        usd.insert(sv);
        usd.insert(snd);
        if (sv == 1) {
            add++;
            continue;
        }
        if (cnt.find(snd) == cnt.end()) {
            add += cnt[sv];
            continue;
        }
        add += max(cnt[sv], cnt[snd]);
    }

    cout << ans + add;
    return 0;
}

