void factmod3(int n, int &a, int &b, vec &prime){
    a = 1; b = 1;
    REP(i, prime.size()){
        int c = 0;
        while(n % prime[i] == 0){
            c++;
            n /= prime[i];
        }
        c %= 3;
        if(c > 0){
            REP(j, c) a *= prime[i];
            REP(j, 3 - c) b *= prime[i];
        }
    }
    //2155以上の素数を含む
    if(n > 1){
        a *= n;

        int r = (int)(sqrt(n) + 1e-3);
        if(r * r == n) b *= r;
        else if((double)b * (double)n * (double)n > INF) b = INF;
        else b *= (n * n);
    }
    //out << a << " " << b << endl;
}

