  for(int i = 2; i <= L; ++i) {
    is_prime[i] = true;
  }
  for(int i = 2; i <= SQRTL; ++i) {
    if(is_prime[i]) {
      for(int j = 1; j <= L / i; ++j) is_prime[j * i] = false;
    }
  }
  for(int i = 2; i <= L; ++i) {
    if(is_prime[i]) primes.push_back(i);
  }
  scanf("%d", &N);
  for(int i = 0; i < N; ++i) {
