      n %= 3;
      if(n == 1) left *= p;
      else if(n == 2) right *= p;
      if(s == 1) break;
    }
    left *= s;
    ++count[std::make_pair(left, right)];
    count[std::make_pair(right, left)];
  }
  int res = 0;
