LL is_sq(LL x) {
    LL y = sqrt(x);

    if (y) y--;
    while (y*y < x) y++;
    if (y*y == x) return y;
    else return 0;
}

int N;
LL S[100111];
LL T[100111], U[100111];
map<LL, LL> mp, inv;

LL safe_mul(LL x, LL y) {
    if (x < 0 || y < 0) return -1;
    if ((double)x * (double)y > 1e15) return -1;
    return x * y;
}


int main() {
