    scanf("%d", &N);
    REP (i, N) scanf("%lld", S+i);

    REP (i, N) {
	T[i] = 1;
	U[i] = 1;
	for (int p=0; ; p++) {
	    LL t = (LL)prime[p] * prime[p] * prime[p];
