ll powmod(__int128_t a, ll k, ll m){
	__int128_t ap=a, ans=1;
	while(k){
		if(k&1){
			ans*=ap;
			ans%=m;
		}
		k>>=1;
		ap=ap*ap%m;
	}
	return ans;
}
bool is_prime(ll n){
    if(n<=1 || !(n&1)) return (n==2);
	ll d=n-1;
	int k=0;
	while(!(d&1)){
		d>>=1;
		k++;
	}
	vector<ll> va{2, 325, 9375, 28178, 450775, 9780504, 1795265022};
	for(auto aa:va){
		ll a=aa%n;
		if(a==0) continue;
		bool comp=1;
		ll ap=powmod(a, d, n);
		if(ap==1 || ap==n-1) continue;
		for(int r=1; r<k; r++){
			ap=(__int128_t)ap*ap%n;
			if(ap==n-1){
				comp=0;
				break;
			}
		}
		if(comp) return false;
	}
	return true;
}
ll gcd(ll a, ll b){
	if(a==0) return b;
	if(b==0) return a;
	if(a<0) a=-a;
	if(b<0) b=-b;
	const int s=__builtin_ctzll(a|b);
	a>>=__builtin_ctzll(a);
	while(b){
		b>>=__builtin_ctzll(b);
		if(a>b) swap(a, b);
		b-=a;
	}
	return a<<s;
}
ll rho(ll n, ll& c){
	if(!(n&1)) return 2;
	while(1){
		ll x=2, y=2, d=1;
		while(d==1){
			x=((__int128_t)x*x+c)%n;
			y=((__int128_t)y*y%n+c)%n;
			y=((__int128_t)y*y%n+c)%n;
			d=gcd(abs(x-y), n);
		}
		if(d==n){
			c++;
			continue;
		}
		return d;
	}
}
vector<pair<ll, int>> factorize(ll n){
	if(n<=1){
		vector<pair<ll, int>> ret;
		return ret;
	}
	map<ll, int> mp;
	vector<ll> v(1, n);
	ll c=1;
	while(!v.empty()){
		ll x=v.back();
		v.pop_back();
		if(is_prime(x)){
			mp[x]++;
			continue;
		}
		ll p=rho(x, c);
		v.push_back(p);
		v.push_back(x/p);
	}
	vector<pair<ll, int>> ret;
	for(auto p:mp) ret.push_back(p);
	return ret;
}
int main()
{
	int n;
	cin>>n;
	map<ll, int> mp;
	const ll INF=1e11;
	vector<pair<ll, ll>> v(n);
	for(int i=0; i<n; i++){
		ll s;
		cin>>s;
		vector<P> fac=factorize(s);
		ll x=1, y=1;
		for(auto p:fac){
			if(p.second%3==1){
				x*=p.first;
				if(y>INF/p.first) y=INF;
				else y*=p.first;
				if(y>INF/p.first) y=INF;
				else y*=p.first;
			}else if(p.second%3==2){
				x*=(p.first*p.first);
				if(y>INF/p.first) y=INF;
				else y*=p.first;
			}
		}
		mp[x]++;
		if(x>y) swap(x, y);
		v[i]=make_pair(x, y);
	}
	sort(v.begin(), v.end());
	v.erase(unique(v.begin(), v.end()), v.end());
	int ans=0;
	for(auto p:v){
		if(p.first==1) ans++;
		else{
			int mx=0;
			if(mp.find(p.first)!=mp.end()) mx=max(mx, mp[p.first]);
			if(mp.find(p.second)!=mp.end()) mx=max(mx, mp[p.second]);
			ans+=mx;
		}
	}
	cout<<ans<<endl;
	return 0;
}

