const int MAXcomb = 200010;
ll fac[MAXcomb], finv[MAXcomb], inv[MAXcomb];
//facはn!,finvは1/n!
//invは逆元
void COMinit(){
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for(int i = 2; i < MAXcomb; i++){
        fac[i] = fac[i-1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD/i) % MOD;
        finv[i] = finv[i-1] * inv[i] % MOD;
    }
}
ll comb(int n, int k){
    if(n < k) return 0;
    if(n < 0 || k < 0) return 0;
    return fac[n] * finv[k] % MOD * finv[n-k] % MOD;
}

//素因数分解O(√n)
vector<pair<ll, ll>> MakePrimeList(ll x) {
    vector<pair<ll, ll>> res;
    for(ll k=2; k*k<=x; k++) {
        if(x % k == 0) {
            ll cnt = 0;
            while(x % k == 0){
              x /= k;
              cnt++;
            }
            cnt %= 3;
            if(cnt%3 == 0) continue;
            res.pb({k, cnt%3});
        }
    }
    if(x > 1) res.push_back({x, 1});
    sort(res.begin(), res.end());
    return res;
}

ll N;
vector<ll> S;

void solve(){
  ll ans = 0;
  map<ll, ll> MS;
  set<ll> exi;
  ll e = 0;
  rep(i, N){
    vector<pair<ll, ll>> primeList = MakePrimeList(S[i]);
    if(primeList.size() == 0){
      e++;
      continue;
    }
    if(primeList.back().f >= 100010LL) ans++;
    else{
      ll x = 1;
      rep(j, primeList.size()){
        x *= pow_long(primeList[j].f, primeList[j].s);
      }
      MS[x]++;
      exi.insert(x);
    }
  }

  if(e != 0) ans++;

  for(auto itr = exi.begin(); itr != exi.end(); itr++){
    ll x = *itr;
    ll cntx, cnty;
    cntx = MS[x];
    if(cntx == 0) continue;
    vector<pair<ll, ll>> primex = MakePrimeList(x);
    ll y = 1;
    rep(i, primex.size()){
      if(primex[i].s == 1){
        y *= primex[i].f * primex[i].f;
      }else{
        y *= primex[i].f;
      }
    }
    cnty = MS[y];
    ans += max(cntx, cnty);
    MS[x] = 0;
    MS[y] = 0;
  }
  cout << ans << endl;
}

