VLL primes;
const ll LIM = 1e10;
const ll HALF = 1e5;

VPII square_reduce(VPII v)
{
	foreach(x, v)
	{
		x.second *= 2;
		x.second %= 3;
	}
	return v;
}

void factor(Num& n, ll x)
{
	assert(n.first % x == 0);
	n.second.emplace_back(x, 0);
	while (n.first % x == 0) {
		n.first /= x;
		n.second.back().second++;
	}
}

bool naive_is_prime(ll x) {
	foreach(y, primes) {
		if (y * y > x)
			break;
		if (x == y)
			return true;
		if (x % y == 0)
			return false;
	}
	return true;
}

void naive_factor(Num& n) {
	foreach(y, primes) {
		if (n.first % y == 0)
			factor(n, y);
		if (n.first == 1)
			break;
	}
	if (n.first != 1)
		factor(n, n.first);
}

void cube_factor(Num& n) {
	foreach(y, primes) {
		if (n.first % y == 0) {
			factor(n, y);
		}
		if (n.first == 1 || y * y * y > LIM)
			break;
	}
}

void force(Num& n) {
	if (n.first != 1)
		factor(n, n.first);
}

void reduce(Num& n)
{
	auto& v = n.second;
	ji(v.size()) {
		v[i].second %= 3;
		if (v[i].second == 0) {
			v.erase(v.begin() + i);
			--i;
		}
	}
}

int main()
{
	for (int i = 2; i <= HALF; i++) {
		if (naive_is_prime(i))
			primes.pb(i);
	}
	int n;
	rint(n);
	vector<Num> v(n);
	ji(n) rint(v[i].first);
	ji(n) cube_factor(v[i]);
	map<ll, VI> m;
	ji(n) m[v[i].first].pb(i);
	ji(n) if (v[i].first <= HALF) {
		naive_factor(v[i]);
		if (v[i].second.size() == 1 && v[i].second[0].second == 1) {
			ll x = v[i].second[0].first;
			ll y = x * x;
			auto it = m.find(y);
			if (it != m.end()) {
				foreach(idx, it->second) {
					factor(v[idx], x);
				}
			}
		}
	}
	ji(n) force(v[i]);
	ji(n) assert(v[i].first == 1);
	ji(n) reduce(v[i]);

	map<VPII, int> cm;
	ji(n) ++cm[v[i].second];
	int loss = 0;
	set<VPII> s;
	ji(n) {
		if (!v[i].second.empty() && s.insert(v[i].second).second)
			loss += cm[square_reduce(v[i].second)];
	}
	loss /= 2;
	loss += max(0, cm[{}] - 1);
	cout << n - loss << endl;
}

