	for(int i=0;i<n;i++) {
		cin >> x;
		ll tx = x;
		ll first = 1, second = 1;

		for(ll j=2;j*j<=x;j++) {
			int cnt = 0;
			while(tx and tx%j==0) {
				cnt++;
				tx /= j;
			}
			first *= pot(j, cnt%3);
			second *= pot(j, (3-cnt%3)%3);
		}
		if(tx != 1) {
			first = tx;
			second = tx*tx;
		}

		ile[first]++;
		X.push_back(pll(first,second));
	}

	int res = 0;

	for(pll x: X) {
		if(x.first == 1 and ile[x.first] > 0) {
			res++;
			ile[x.first] = 0;
		}
		res += max(ile[x.first], ile[x.second]);

		ile[x.first] = 0;
		ile[x.second] = 0;
	}

	cout << res << endl;
}

