bool miller_robin(LL n)
{
	if (n==2)  return 1;
	if ((n==1)||(!(n&1)))  return 0;
	LL m=n-1,k=0;
	while (!(m&1))  m>>=1,k++;
	for (int i=1; i<=10; i++)
		{
			LL x=ksm(rand()%(n-1)+1,m,n),y;
			for (int j=1; j<=k; j++)
				{
					y=mul(x,x,n);
					if (y==1)  {if ((x!=1)&&(x!=n-1))  return 0;  else  break;}
					x=y;
				}
			if (y!=1)  return 0;
		}
	return 1;
}

