LL f(LL x,LL c,LL n){return (mul(x,x,n)+c)%n;}

void pollard_rho(LL n)
{
	while (!(n&1))  n>>=1,ans.push_back(2);
	if (n==1)  return;
	if (miller_robin(n))  {ans.push_back(n);  return;}
	LL x=rand()%(n-1)+1,y=x,c=rand()%(n-1)+1,g;
	for (LL i=1,j=1; ; i++)
