			x=f(x,c,n);
			g=gcd(abs(x-y),n);
			if (x==y)  x=rand()%(n-1)+1,y=x,c=rand()%(n-1)+1,i=0,j=1;
			if ((g>1)&&(g<n))  break;
			if (i==j)  y=x,j<<=1;
		}
	pollard_rho(g),pollard_rho(n/g);
}

