long long isqrt(long long x){
	long long a=x;
	for(;;){
		long long b=(a+x/a)/2;
		if(b>=a){
			return a;
		}else{
			a=b;
		}
	}
}

bool issq(long long x){
	long long a=isqrt(x);
	return a*a==x;
}

