typedef vector<int> vi;

const int nunach = 2500, N = 1e5 + 5;
bool vis[nunach];
vi prime;
int ans, n;
long long a[N];
map<long long, int> mp;

void sieve() {
    for (int i = 2; i < nunach; ++i) {
        if(!vis[i]) {
            prime.pb(i);
            for (int j = 2 * i; j < nunach; j += i) vis[j] = 1;
        }
    }
}

void upd(long long &num) {
    for(int i : prime) {
        long long cube = 1LL * i * i * i;
        while(num % cube == 0) num /= cube;
    }
}

long long get(long long num) {
    long long res = 1;
    for (int i : prime) {
        if(num % i == 0) {
            res *= i;
            if(num % (1LL * i * i) != 0) res *= i;
            while(num % i == 0) num /= i;
        }
    }
    long long rem = sqrt(num);
    if(rem * rem == num) res *= rem;
    else res *= num * num;
    return res;
}

int main () {
    ios_base::sync_with_stdio(0); cin.tie(0); cout.tie(0);
    sieve();
    cin >> n;
    for (int i = 1; i <= n; ++i) {
        cin >> a[i];
        upd(a[i]);
        mp[ a[i] ] ++;
    }

    for(auto i : mp) {
        if(i.fi == 1) ans ++;
        else {
            long long rem = get(i.fi);
            if(mp.count(rem) ) {
                ans += max(i.se, mp[rem]);
                mp.erase(rem);
            }
            else ans += i.se;
        }
    }

    cout << ans;

    return 0;
}

