	vis[j] = 1;
    }
}

int N;

map<i64, i64> back, NUM;
map<i64, i64>::iterator iter;

bool mul(i64 &x, i64 y) {
  if ((double) LIM / x < y) return false;
  x *= y;
  return true;
}

int main() {
  init_prime();

  scanf("%d", &N);
  for (int i = 1; i <= N; ++i) scanf("%lld", &S[i]);

  int res = 0;

  for (int i = 1; i <= N; ++i) {
    i64 temp = S[i], anti = 1;
    bool flag = 1;
    for (int j = 1; 1LL * pr[j] * pr[j] * pr[j] <= temp; ++j) 
      if (temp % pr[j] == 0) {
	int cnt = 0;
	while (temp % pr[j] == 0) temp /= pr[j], S[i] /= pr[j], cnt++;
	cnt %= 3;
	if (cnt == 1) S[i] *= pr[j], flag &= mul(anti, pr[j] * pr[j]);
	else if (cnt == 2) S[i] *= pr[j] * pr[j], flag &= mul(anti, pr[j]);
      }

    int x = sqrtl(temp);
    if (1LL * x * x == temp) flag &= mul(anti, x);
    else flag &= mul(anti, temp * temp);

    if (temp > 1000000000 || !flag) {
      res++;
      continue;
    }

    NUM[S[i]]++, back[S[i]] = anti, back[anti] = S[i];
  }

  for (iter = back.begin(); iter != back.end(); ++iter) {
    if (iter->first == 1) {
      res++;
      continue;
    }
    if (iter->first > iter->second) continue;
    res += max(NUM[iter->first], NUM[iter->second]);
  }

  printf("%d\n", res);

  return 0;
}

