class prime {
private:
public:
	std::vector<ull> primes;
	std::vector<bool> isPrime;
	prime(ull num) {
		isPrime.resize(num + 1);
		fill(isPrime.begin(), isPrime.end(), true);
		ull ma = sqrt(num) + 1;
		isPrime[0] = isPrime[1] = false;
		ull cnt = 0;
		for (ull i = 2; i <= ma; ++i) if (isPrime[i]) {
			for (ull j = 2; i*j <= num; ++j) {
				isPrime[i*j] = false;
				cnt++;
			}
		}
		primes.reserve(cnt);
		for (ull i = 0; i<isPrime.size(); ++i) if (isPrime[i]) {
			primes.push_back(i);
		}
	}

	bool IsPrime(ull num) {
		if (num < isPrime.size()) return isPrime[num];
		for (auto p : primes) {
			if (num%p == 0) return false;
		}
		ull ma = sqrt(num) + 1;
		for (ull i = primes.back(); i <= ma; i += 2) {
			if (num%i == 0) return false;
		}
		return true;
	}

	std::vector<ull> GetFactor(ull num) {
		std::vector<ull> res;
		ull ma = sqrt(num) + 1;
		ull sma = std::min(ma, (ull)isPrime.size() - 1);
		while (num != 1) {
			for (auto a : primes) {
				if (num % a == 0) {
					res.push_back(a);
					num /= a;
				}
			}
			break;
		}
		assert(num);
		return res;
	}

	std::map<ull, ull> GetFactorMap(ull num) {
		std::map<ull, ull> res;
		ull ma = sqrt(num) + 1;
		ull sma = std::min(ma, (ull)isPrime.size() - 1);
		ull index = 0;
		while (num >= primes[index]*primes[index]) {
			ull a = primes[index];
			if (num%a == 0) {
				res[a]++;
				num /= a;
			}
			else {
				++index;
			}
		}
		if (num != 1) res[num]++;
		return res;
	}
};

int main() {
	int N; cin >> N;
	prime p(sqrt(1e10));

	vector<ull> S(N); for (auto &a : S) cin >> a;

	int res = 0;

	map<ull, pair<ull, ull> > cnt; //first: norm, second: pair
	for (auto &s : S) {
		auto fac = p.GetFactorMap(s);
		ull norm = 1, pair = 1;
		for (auto f : fac) {
			int n = f.first;
			int c = f.second % 3;
			if (c == 1) {
				norm *= n;
				pair *= n*n;
			}
			else if (c == 2) {
				norm *= n*n;
				pair *= n;
			}
		}
		if (norm == 1) res = 1;
		else {
			if (norm < pair) cnt[norm].first++;
			else cnt[pair].second++;
		}
	}

	for (auto c : cnt) {
		res += max(c.second.first, c.second.second);
	}

	cout << res << endl;
	return 0;
}

