    int n;
    cin >> n;
    rep(i,n){
        cin >> s[i];
    }
    int m = 2155, cnt = 0;
    sieve(m);
    rep(i,n){
        ll num = s[i];
        vector<pll> vec;
        each(val, prime){
            cnt = 0;
            while(num > 0 && num % val == 0){
                num /= val;
                cnt++;
            }
            cnt %= 3;
            if(cnt){
                vec.pb(pll(val, cnt));
            }
        }
        if(num > 1){
            if(num <= MAX_N){
                vec.pb(pll(num, 1));
            }else{
                ll hoge = (ll)floor(sqrt(num));
                bool flag = false;
                for(ll j = hoge-2; j <= hoge+2; ++j){
                    if(j*j == num){
                        flag = true;
                        vec.pb(pll(j, 2));
                    }
                }
                if(!flag){
                    vec.pb(pll(num, -1));
                }
            }
        }
        mp[vec]++;
    }
    int ans = 0, ans2 = 0;
    each(v, mp){
        if(len(v.fi) == 0){
            ans++;
            continue;
        }
        if(v.fi.back().se < 0){
            ans += v.se;
            continue;
        }
        vector<pll> gyaku;
        each(p,v.fi){
            gyaku.pb(pll(p.fi, 3-p.se));
        }
        auto it = mp.find(gyaku);
        if(it != mp.end()){
            ans2 += max(v.se, it->se);
        }else{
            ans += v.se;
        }
    }
    cout << ans + ans2/2 << "\n";
    return 0;
}

