		F0R(j,prime.size()) {
			if (i % prime[j] == 0) {
				f = 1;
				break;
			}
			if (prime[j]*prime[j]>i) break;
		}
		if (!f) {
			prime.pb(i);
			squares.pb(mp(i,i*i));
		}
	}
}

pair<ll,ll> fac(ll x) {
	ll x1 = 1, x2 = 1, i = 0;
	for (;i<prime.size();++i) {
		ll t = prime[i]*prime[i]*prime[i];
		if (t>x) break;
		while (x % t == 0) x /= t;
		if (x % prime[i] == 0) {
			int c = 0;
			while (x % prime[i] == 0) x /= prime[i],x1 *= prime[i],c++;
			F0R(j,3-c) x2 *= prime[i];
		}
	}
	pii y = *lower_bound(squares.begin(),squares.end(),mp((ll)0,x));
	if (y.s == x)  x2 *= y.f;
	else x2 *= (x*x);
	return mp(x1*x,x2);
}

