pair<ll, ll> calc(ll t){
	ll x = 1, y = 1;
	for(int i = 0;i < (int)pr.size() && pr[i] * pr[i] <= t;i++){
		int cnt = 0;
		while(t % pr[i] == 0){
			t /= pr[i];
			cnt++;
		}
		if(cnt % 3 == 1){
			x *= pr[i];
			y *= pr[i] * pr[i];
		}
		else if(cnt % 3 == 2){
			x *= pr[i] * pr[i];
			y *= pr[i];
		}
	}

	x *= t;
	if(t > 1){
		ll ss = sqrt(t);
		if(ss * ss == t){
			y = y * ss;
		}
		else{
			y = y * t * t;
		}
	}
	return MP(x, y);
}

