int main()
{
	// freopen("AGC003-D.in", "r", stdin); 
	for (int i = 2; i < 2205; i++)
	{
		if (!np[i])
			p[tot++] = i; 
		for (int j = 0; j < tot && i * p[j] < 2205; i++)
		{
			np[i * p[j]] = true; 
			if (!(i % p[j]))
				break; 
		}
	}
	bool f = false; 
	int n; 
	scanf("%d", &n); 
	for (int i = 0; i < n; i++)
	{
		ll x, y = 1, z = 1; 
		scanf("%lld", &x);
		for (int j = 0; j < tot; j++)
		{
			int cnt = 0; 
			while (!(x % p[j]))
			{
				x /= p[j]; 
				cnt = (cnt + 1) % 3; 
			}
			int t = (3 - cnt) % 3; 
			while (cnt--)
				y *= p[j]; 
			while (t--)
				z *= p[j]; 
		}
		if (x != 1)
		{
			ll k = sqrt(x); 
			if (k * k == x)
			{
				y *= k * k; 
				z *= k; 
			}
			else
			{
				y *= x; 
				z *= x * x; 
			}
		}
		// cout << y << " " << z << endl; 
		if (y == 1)
		{
			f = true; 
			continue; 
		}
		app[y]++; 
		to[y] = z; 
	}
	// cout << endl; 
