using namespace std;
inline LL read()
{
	LL f=1,x=0;char ch=getchar();
	while(ch<'0'||ch>'9'){if(ch=='-')f=-1;ch=getchar();}
	while(ch>='0'&&ch<='9'){x=x*10+ch-'0';ch=getchar();}
	return x*f;
}
int stack[20];
template<typename T>inline void write(T x)
{
	if(x<0){putchar('-');x=-x;}
    if(!x){putchar('0');return;}
    int top=0;
    while(x)stack[++top]=x%10,x/=10;
    while(top)putchar(stack[top--]+'0');
}
template<typename T>inline void pr1(T x){write(x);putchar(' ');}
template<typename T>inline void pr2(T x){write(x);putchar('\n');}
const int MAXN=100005;
int pr[MAXN],plen,is[MAXN];
void init()
{
	for(int i=2;i<MAXN;i++)
	{
		if(!is[i])pr[++plen]=i;
		for(int j=1;j<=plen&&i*pr[j]<MAXN;j++)
		{
			is[i*pr[j]]=1;
			if(!(i%pr[j]))break;
		}
	}
}
int n;LL a[MAXN],fac[MAXN],inv[MAXN];
LL cube(int x){return 1LL*x*x*x;}
map<LL,int> mp;
int main()
{
	init();
	n=read();int ans=0;
	for(int i=1;i<=n;i++)
	{
		LL x=a[i]=read();
		for(int j=1;cube(pr[j])<=x;j++)
			while(!(x%cube(pr[j])))x/=cube(pr[j]);
		mp[x]++;fac[i]=x;
		LL temp=1;
		for(int j=1;cube(pr[j])<=x;j++)if(!(x%pr[j]))
		{
			if(!(x%(1LL*pr[j]*pr[j])))temp*=pr[j];
			else temp*=1LL*pr[j]*pr[j];
			while(!(x%pr[j]))x/=pr[j];
		}
		if(1LL*sqrt(x)*sqrt(x)==x)temp*=sqrt(x);
		else temp*=1LL*x*x;
		inv[i]=temp;
	}
	for(int i=1;i<=n;i++)if(mp[fac[i]])
	{
		if(fac[i]!=1)
		{
			int u=mp[fac[i]],v=mp[inv[i]];
			ans+=max(u,v);mp[fac[i]]=mp[inv[i]]=0;
		}
		else ans++,mp[fac[i]]=0;
	}
	pr2(ans);
	return 0;
}

