ll calc_pair(ll x)
{
	ll res = 1;
	map<ll,int> fact;
	for(int i = 0;prime [i] * prime [i] * prime [i] <= x && i < prime.size();i++){
		while(x % prime [i] == 0){
			fact [prime [i]]++;
			x /= prime [i];
		}
	}
	ll y = sqrt(x) + eps;
	if(y * y == x){
		res *= y;
	}
	else{
		res *= x * x;
	}
	for(auto&& it : fact){
		if(it.second == 1){
			res *= it.first * it.first;
		}
		else{
			res *= it.first;
		}
	}

	return res;
}

