			while(x * x <= a[i]) {
				++x;
			}
			while(x * x > a[i]) {
				--x;
			}
			if(x * x != a[i]) {
				x = a[i];
				if(x > 10000000000ll / x) {
					ans += M[m];
					M.erase(m);
					continue;
				}
				x *= x;
			}
			if(y > 10000000000ll / x) {
				ans += M[m];
				M.erase(m);
				continue;
			}
			y *= x;
		}
		if(M.find(y) != M.end()) {
			ans += std::max(M[m], M[y]);
			M.erase(y);
			M.erase(m);
		}
		else {
			ans += M[m];
			M.erase(m);
		}
	}
	printf("%d\n", ans);
	return 0;
}

