template <typename T>
constexpr T INF = numeric_limits<T>::max() / 10;

inline ll rt(const ll n)
{
    ll inf = 0;
    ll sup = sqrt(n) * 2;
    while (sup - inf > 1) {
        const ll mid = (inf + sup) / 2;
        const ll v = mid * mid;
        if (v == n) {
            return mid;
        } else if (v < n) {
            inf = mid;
        } else {
            sup = mid;
        }
    }
    return inf * inf == n ? inf : sup * sup == n ? sup : 0;
}

