#include <bits/stdc++.h>
using namespace std;

class BigInt {
public:
	BigInt() {}

	BigInt(long long n) {
		a[0] = n;
		normalize();
	}

	BigInt &operator+=(const BigInt &r) {
		for (int i = 0; i < N; i++) {
			a[i] += r.a[i];
		}
		normalize();
		return *this;
	}

	BigInt operator+(BigInt r) {
		return r += *this;
	}

	BigInt &operator*=(const BigInt &r) {
		for (int i = N - 1; i >= 0; i--) {
			long long s = 0;
			for (int j = 0; j <= i; j++) {
				s += a[j] * r.a[i - j];
			}
			a[i] = s;
		}
		normalize();
		return *this;
	}

	BigInt operator*(BigInt r) {
		return r *= *this;
	}

	bool operator<(const BigInt &r) const {
		for (int i = N - 1; i >= 0; i--) {
			if (a[i] != r.a[i]) {
				return a[i] < r.a[i];
			}
		}
		return false;
	}

	bool operator<=(const BigInt &r) const {
		for (int i = N - 1; i >= 0; i--) {
			if (a[i] != r.a[i]) {
				return a[i] < r.a[i];
			}
		}
		return true;
	}

	bool operator==(const BigInt &r) const {
		for (int i = 0; i < N; i++) {
			if (a[i] != r.a[i]) return false;
		}
		return true;
	}

	bool operator>(const BigInt &r) const {
		return !(*this <= r);
	}

	bool operator>=(const BigInt &r) const {
		return !(*this < r);
	}

	string to_string() const {
		int i = N - 1;
		while (i > 0 && a[i] == 0) i--;
		string s = std::to_string(a[i--]);
		for (; i >= 0; i--) {
			string t = std::to_string(a[i]);
			s += string(L - t.length(), '0') + t;
		}
		return s;
	}

private:
	static const int N = 3;
	static const int L = 8;
	static const long long B = 100000000;
	long long a[N] = {};

	void normalize() {
		long long carry = 0;
		for (int i = 0; i < N; i++) {
			a[i] += carry;
			carry = a[i] / B;
			a[i] %= B;
		}
	}
};

int main() {
	int n;
	cin >> n;

	vector<long long> a(n);
	for (int i = 0; i < n; i++) {
		scanf("%lld", &a[i]);
	}

	vector<bool> is_prime(101010, true);
	vector<long long> ps;
	map<long long, long long> rt;

	for (long long i = 2; i < 101010; i++) {
		if (is_prime[i]) {
			ps.push_back(i);
			rt[i * i] = i;
			for (int j = i * 2; j < 101010; j += i) {
				is_prime[j] = false;
			}
		}
	}

	map<BigInt, BigInt> inv;
	map<BigInt, int> cnt;

	for (int i = 0; i < n; i++) {
		BigInt p = 1, q = 1;
		for (int j = 0; ps[j] <= 2500; j++) {
			int c = 0;
			while (a[i] % ps[j] == 0) a[i] /= ps[j], c++;
			c %= 3;
			if (c > 0) {
				for (int i = 0; i < c; i++) p *= ps[j];
				for (int i = 0; i < 3 - c; i++) q *= ps[j];
			}
		}
		p *= a[i];
		if (a[i] != 1) {
			if (rt.count(a[i])) {
				q *= rt[a[i]];
			} else {
				q *= a[i];
				q *= a[i];
			}
		}
		inv[p] = q;
		inv[q] = p;
		cnt[p]++;
	}

	int ans = 0;
	for (auto &kv : inv) {
		auto &x = kv.first;
		auto &y = kv.second;

		if (x == y) {
			ans++;
		} else if (x < y) {
			ans += max(cnt[x], cnt[y]);
		}
	}
	cout << ans << endl;
}

