#include <bits/stdc++.h>
using LL = long long;
const int N = 1e5 + 5;
int visited[N], p[N], tot;

void Prime() {
  for (int i = 2; i < N; i++) {
    if (!visited[i]) p[tot++] = i;
    for (int j = 0; j < tot && i * p[j] < N; j++) {
      visited[i * p[j]] = p[j];
      if (i % p[j] == 0) break;
    }
  }
}

int main() {
  Prime();
  int n;
  //std::cin >> n;
  scanf("%d", &n);
  std::map<std::vector<std::pair<int, int>>, int> s;
  int zero = 0;
  for (int i = 0; i < n; i++) {
    LL x;
    //std::cin >> x;
    scanf("%lld", &x);
    std::vector<std::pair<int, int>> tmp;
    for (int j = 0; j < tot && 1LL * p[j] * p[j] <= x; j++) if (x % p[j] == 0) {
      int cnt = 0;
      while (x % p[j] == 0) {
        x /= p[j];
        cnt++;
      }
      cnt %= 3;
      if (cnt) {
        tmp.emplace_back(p[j], cnt);
      }
    }
    if (x == 1 && !tmp.size()) zero++;
    else if (x == 1) s[tmp]++;
    else if (x != 1 && x < N) {
      tmp.emplace_back(x, 1);
      s[tmp]++;
    }
  }
  int nouse = 0;
  for (auto &factor: s) {
    std::vector<std::pair<int, int>> tmp = factor.first;
    for (auto &p: tmp) {
      p.second = (3 - p.second) % 3;
    }
    if (!s.count(tmp)) continue;
    nouse += std::min(s[factor.first], s[tmp]);
  }
  std::cout << n - zero - nouse / 2 + (zero > 0) << std::endl;
  return 0;
}

