unordered_map<ll,mp>mas;

class setmas{
  public:
  mp mem;
  ll divi(ll x){
    mem.clear();
    for(auto y:prime){
      while(x%y==0){
	mem[y]++;
	x/=y;
      }
    }
    return x;
  }
  void insert(ll x){
    ll p=divi(x);
    ll res=1;
    for(auto t:mem){
      ll val=t.first;
      ll cnt=t.second;
      for(int i=0;i<cnt%3;i++){
	res*=val;
      }
    }
    //cout<<x<<" "<<res<<" "<<p<<endl;
    mas[res][p]++;
  }
  bool erase(ll x){
    ll p=divi(x);
    ll res=1;
    for(auto t:mem){
      ll val=t.first;
      ll cnt=t.second;
      for(int i=0;i<cnt%3;i++){
	res*=val;
      }
    }

    if(mas[res][p]<1)return 0;
    mas[res][p]--;

    ll rev=1;
    for(auto t:mem){
      ll val=t.first;
      ll cnt=t.second;
      cnt%=3;
      for(int i=0;i<(3-cnt)%3;i++){
	rev*=val;
      }
    }
    if(p==1){
      if(mas[rev][p]>=1){
	mas[rev][p]--;
	return 1;
      }
      return 0;
    }
    if(p>Y){
      mas[x/p][p]++;
      return 0;
    }
    if(mas[rev][p*p]>=1){
      mas[rev][p*p]--;
      return 1;
    }
    return 0;
  }
};setmas setmass;
