ll complm (ll x) {
  auto pfs = prime_factor(x);

  ll ans = 1;
  for (auto it = pfs.begin(); it != pfs.end(); it++) {
    if (it->second == 1) {
      if (blog(ans) + 2 * blog(it->first) > 40) return -1;
      ans *= sq(it->first);
    } else if (it->second == 2) {
      if (blog(ans) + blog(it->first) > 40) return -1;
      ans *= it->first;
    }
  }
  return ans;
}

