int prime[N], snum = 325, pnum;
bool p[N];
void EulerSieve(int n) {
    for (int i = 2; i <= n; i++) {
        if (!p[i]) prime[++pnum] = i;
        for (int j = 1; j <= pnum; j++) {
            if (i * prime[j] > n) break;
            p[i * prime[j]] = true;
            if (i % prime[j] == 0) break;
        }
    }
}
map<ll, int> mp;
int n, ans;
int main() {
    EulerSieve(N);
    scanf("%d", &n);
    while (n--) {
        ll s, a = 1, kind = 0;
        scanf("%lld", &s);
        for (int j = 1; j <= snum; j++) {
            int num = 0;
            while (s % prime[j] == 0) s /= prime[j], num++;
            if (num %= 3) a *= prime[j], kind = kind << 1 | (num & 1);
        }
        // printf("%lld %lld %lld\n", s, a, kind);
        if (s > 1) {
            if (s < N)
                a *= s, kind = kind << 1 | 1;
            else {
                ll ss = sqrt(s);
                if (ss * ss != s) {
                    ans++;
                    continue;
                }
                a *= ss, kind = kind << 1;
            }
        }
        mp[a << 1 | (!!kind)]++;
    }
    if (mp[2] || mp[3]) ans++, mp[2] = mp[3] = 0;
    for (auto &it : mp) {
        // printf("%lld %d\n", it.first, it.second);
        if (it.first & 1)
            ans += max(mp[it.first - 1], it.second);
        else {
            ans += max(mp[it.first + 1], it.second);
            mp[it.first + 1] = mp[it.first] = 0;
        }
    }
    printf("%d\n", ans);
    return 0;
}

