using namespace std;

using ll = long long;
using pii = pair<ll, ll>;

class union_find {
public:
    union_find(int n) : par(n, -1) {}

    int root(int x) {
        return par[x] < 0 ? x : par[x] = root(par[x]);
    }

    void unite(int x, int y) {
        x = root(x), y = root(y);
        if(x == y) return;
        if(par[x] > par[y]) swap(x, y);
        par[x] += par[y];
        par[y] = x;
    }

    int size(int x) {
        return -par[root(x)];
    }

private:
    vector<int> par;
};

vector<pii> factorize(ll x) {
    vector<pii> res;
    for(ll y = 2; y * y <= x; ++y) {
        if(x % y == 0) {
            ll cnt = 0;
            while(x % y == 0) {
                ++cnt;
                x /= y;
            }
            cnt %= 3;
            if(cnt != 0) {
                res.emplace_back(y, cnt);
            }
        }
    }
    if(x > 1) {
        res.emplace_back(x, 1);
    }
    return res;
}

int main() {
    int n; cin >> n;
    vector<ll> s(n);
    for(auto& x : s) cin >> x;

    map<vector<pii>, int> idx;
    map<int, int> cnt;
    int ans = 0;
    for(auto const x : s) {
        const auto p = factorize(x);
        if(p.empty()) {
            ans |= 1;
            continue;
        }
        if(idx.count(p) == 0) {
            const int nid = idx.size();
            idx[p] = nid;
        }
        const int id = idx[p];
        cnt[id] += 1;
    }

    union_find uf(idx.size());
    for(auto const& p : idx) {
        auto tps = p.first;
        for(auto& tp : tps) {
            tp.second = 3 - tp.second;
        }
        if(idx.count(tps) == 0) continue;
        uf.unite(p.second, idx[tps]);
    }

    map<int, int> maxi;
    for(int i = 0; i < (int)idx.size(); ++i) {
        maxi[uf.root(i)] = max(maxi[uf.root(i)], cnt[i]);
    }

    for(auto const& p : maxi) {
        ans += p.second;
    }

    cout << ans << endl;
}

