bool isCube(ll x) {
	if (x == 1) return false;
	ll z = pow((double)x, (double)1 / 3) + 0.5;
	if (z * z * z == x) return true;
	return false;
}

const int N = 110000;

bool pp[N];
int primes[N], primesCnt;

void sieve() {
	for (int i = 2; i < N; i++) {
		if (!pp[i]) {
			for (int j = i + i; j < N; j += i) {
				pp[j] = true;
			}
		}
	}
	for (int i = 2; i < N; i++) {
		if (!pp[i]) {
			primes[primesCnt++] = i;
		}
	}
}

map<ll, int> cnt, cnt2;
ll p[60], q[60], zz;

void getPrimeDivisors(ll x) {
	zz = 0;
	for (int i = 0; 1LL * primes[i] * primes[i] <= x; i++) {
		int cur = primes[i];
		if (x % cur == 0) {
			int z = 0;
			while (x % cur == 0) {
				++z;
				x /= cur;
			}
			p[zz] = cur;
			q[zz] = z;
			zz++;
		}
	}
	if (x != 1) {
		p[zz] = x;
		q[zz] = 1;
		zz++;
	}
}

ll normalize(ll x) {
	getPrimeDivisors(x);
	ll prod = 1;
	for (int i = 0; i < zz; i++) {
		q[i] %= 3;
		while (q[i]--) {
			prod *= p[i];
		}
	}
	return prod;
}

ll getInv(ll x) {
	getPrimeDivisors(x);
	ll prod = 1;
	for (int i = 0; i < zz; i++) {
		q[i] = (3 - q[i] % 3) % 3;
		while (q[i]--) {
			if (ll(1e12) / prod / p[i] == 0) return -1;
			prod *= p[i];
		}
	}
	return prod;
}

