  }
  sieve(2222);
  map<ll,int> mp;
  map<ll,ll> dp;
  rep(i,n) {
    ll x = a[i];
    ll d = 1, e = 1;
    for (int p : ps) {
      int cnt = 0;
      while (x%p == 0) ++cnt, x /= p;
      cnt %= 3;
      if (cnt) {
        d *= p;
        e *= p;
        if (cnt == 2) d *= p; else {
          if (e > LINF || e == -1) e = -1;
          else e *= p;
        }
      }
    }
    if (x != 1) {
      ll b = fb(x);
      if (b) {
        d *= x;
        e *= b;
      } else {
        d *= x;
        e = -1;
      }
    }
    dp[d] = e;
    mp[d]++;
  }
  int ans = 0;
  for (auto p : mp) {
    ll d = p.fi; int c = p.se;
    if (!c) continue;
    if (d == 1) ans++;
    else {
      ll e = dp[d];
      if (mp.count(e)) {
        maxs(c,mp[e]);
        mp[e] = 0;
      }
      mp[d] = 0;
      ans += c;
    }
  }
  cout<<ans<<endl;
  return 0;
}

