void find_prime()
{
	FOE(i, 2, 10000)
	{
		if (p[i] == 1) continue;
		for (int j = i * i; j <= 10000; j += i) p[j] = 1;
	}

	FOE(i, 2, 10000) if (p[i] == 0) 
	{
		prime[k] = i;
		prime_3[k++] = 1ll * i * i * i;
	}
}

ll inv(ll x)
{
	ll tmp = x, ret = 1ll;

	FOR(i, 0, k)
	{
		if (prime_3[i] > tmp) break;
		y = 0;
		while (tmp % prime[i] == 0) 
		{
			tmp /= prime[i];
			y++;
		}

		if (y == 1) ret *= prime[i] * prime[i];
		else if (y == 2) ret *= prime[i];

		if (ret > 10000000000ll) return -1;
	}

	ll t = (ll)sqrt(tmp);
	if (t * t == tmp) ret *= t;
	else ret *= tmp * tmp;

	if (ret > 10000000000ll) return -1;
	return ret;
}

