	if(x==1||x==mod-1) return 1;
	while(d){
		x=mul(x,x,mod);
		if(x==mod-1||x==1) return 1;
		d--;
	}
	return 0;
}
bool miller_rabin(ll a){
	if(a==1||a==2) return 1;
	if(!(a&1)) return 0;
	ll s=a-1,d=0;
	while(!(s&1)) d++,s>>=1;
	for(int i=0;i<5;i++){
		ll g=1LL*rand()*rand()%(a-1)+1;
		if(!wit(g,s,d,a)) return 0;
	}
	return 1;
}
