ll gcd(ll a,ll b){
	if(a<0) a=-a;
	if(b<0) b=-b;
	ll t;
	while(b){
		t=a;a=b;b=t%b;
	}
	return a;
}
ll rho(ll a,ll c){
	ll q,qq,p;
	q=qq=2;const ll mod=a;
	int i=0,k=2;
	while(k<=32){
		i++;
		q=(mul(qq,qq,mod)+c)%mod;
		p=gcd(q-qq,a);
		if(p>1&&p!=a) return p;
		if(q==qq) return a;
		if(i==k){
			qq=q;
			k<<=1;
		}
	}
	return a;
}
