	is_p[1] = false;
	for(int i = 2; i < kP; ++i) {
		if(is_p[i]) p[++cnt] = i;
		for(int j = 1; j <= cnt && i * p[j] < kP; ++j) {
			is_p[i * p[j]] = false;
			if(i % p[j] == 0) break;
		}
	}
}

