void sieve() {
	np[0] = np[1] = 1;
	for (int i = 2; i < N; ++i) if (!np[i]) {
		for (int j = i + i; j < N; ++j) np[j] = 1;
		prime.push_back(i);
	}
}

bool mul(long long &x, long long y) {
	if (x > inf / y) return false;
	x *= y;
	return true;
}

int main() {
	ios_base::sync_with_stdio(false); cin.tie(0);
	sieve();
	cin >> n;
	for (int i = 1; i <= n; ++i) cin >> s[i];

	for (int i = 1; i <= n; ++i) {
		long long tmp = s[i]; bool flag = true; long long anti = 1, cur = 1;

		for (int j = 0; j < (int)prime.size() && 1ll * prime[j] * prime[j] * prime[j] <= tmp; ++j) {
			if (tmp % prime[j] == 0) {
				int cnt = 0;
				while(tmp % prime[j] == 0) ++cnt, tmp /= prime[j];
				cnt %= 3;
				if (cnt == 2) flag &= mul(anti, prime[j]), cur *= 1ll * prime[j] * prime[j];
				else if (cnt == 1) flag &= mul(anti, 1ll * prime[j] * prime[j]), cur *= prime[j];
			}
		}
		cur *= tmp;

		int x = (int)sqrt(tmp);
		if (1ll * x * x == tmp) flag &= mul(anti, x);
		else flag &= mul(anti, 1ll * tmp * tmp);

		++mp[cur];
		if (!flag) continue;
		an[cur] = anti; an[anti] = cur;
	}

	for (map<long long,int>::iterator iter = mp.begin(); iter != mp.end(); ++iter) {
		long long cur = iter->first;
		if (iter->first == 1) ++ans;
		else {
			if (!an.count(cur) || !mp.count(an[cur])) ans += mp[cur];
			else if (cur < an[cur]) ans += max(mp[cur], mp[an[cur]]);
		}
	}

	cout << ans << endl;
}

