    map<int,int> C;
    for(auto&s:S) C[s]++;

    int ans = 0;
    for(auto iter = C.begin(); iter != C.end(); ++iter) {
        int a = iter->x;
        if (a==1) { ans += 1; continue; }
        ll b = 1;
        for (auto &p: P) {
            if (a == 1) break;
            if (a % p==0) {
                if (b * p < b) { b = -1; break; }
                b *= p;
                a /= p;
                if (a % p == 0) {
                    a /= p;
                } else {
                    if (b * p < b) { b = -1; break; }
                    b *= p;
                }
            }
            if ((ll)p*p>a) break;
        }
        if (a != 1) {
            if (b * a < b) { b = -1; }
            else {
                b *= a;
                if (b * a < b) { b=-1; }
                else b *= a;
            }
        }

        auto bi = C.find(b);
        if (bi == C.end()) {
            ans += iter->y;
        } else if (bi->y < iter->y) {
            ans += iter->y;
        } else if (bi->y == iter->y && iter->x < b) {
            ans += iter->y;
        }
    }
    cout << ans << endl;
}

