    map<ll,ll> Norm,NN,Pair;
    for(int i=0;i<N;i++){
        ll s = S[i];
        ll n = 1;       // norm(s)
        ll r = 1;       // pair(s)
        for(ll p : primes){
            if(p>s) break;
            ll cnt=0;
            ll x=0;
            while(s%p==0){
                x++;
                assert(x<100);
                cnt++;
                s/=p;
            }
            cnt%=3;

            if(cnt==1){
                n *= p;
                r *= p*p;
            }else if(cnt==2){
                n *= p*p;
                r *= p;
            }
        }

        if(s > 1){
            if(prime2.count(s)){
                //sは素数の2乗
                n *= s;
                r *= prime2[s];
            }else{
                n *= s;
                r *= s*s;
            }
        }

        NN[n]++;
