    for (int i = 1; i <= N; ++i) {
        llint tmp = a[i];
        llint mul = 1;
        bool T = true;

        for (llint j = 2; j <= mx; ++j) {
            while (a[i] % (j * j * j) == 0) {
                a[i] /= (j * j * j);
                tmp /= (j * j * j);
