            while (tmp % j == 0) {
                tmp /= j;
                --sl;
            }
            if (sl == 3) continue;

            while (sl --) {
                mul = mul * j;
                if (mul > INF) T = false;
            }
        }

        if (!T) {
            res += 2;
            continue;
        }

        llint sqrt_tmp = trunc(sqrt(tmp));
        if (sqrt_tmp * sqrt_tmp == tmp) {
            mul = mul * sqrt_tmp;
            if (mul > INF) T = false;
