using namespace std;
const int MAXN=1e5+10;
const int N=1e5;
struct node{
	ll x,y;
};
node a[MAXN];
ll prime[MAXN],s[MAXN],s1[MAXN];
bool p[MAXN];
int n,len;
map<ll,int>mp;
void init()
{
	for (int i=2;i<=N;i++) {
		if (!p[i]) {
			p[i]=1; prime[++len]=i;
		}
		for (int j=1;j<=len&&prime[j]*i<=N;j++) {
			p[prime[j]*i]=1;
			if (i%prime[j]==0) break;
		}
	}
}
void pan(ll x,int now){
	ll ans1=1;
	ll ans2=1;
	for (int i=1;i<=len&&prime[i]*prime[i]<=x;i++) 
	if (x%prime[i]==0)
	{
        int sum=0;
        while (x%prime[i]==0) {
        	x/=prime[i]; sum++;
        }
        sum=(sum%3);
        for (int j=1;j<=sum;j++) ans1*=(ll)prime[i];
        for (int j=1;j<=(3-sum)%3;j++) ans2*=(ll)prime[i];
	}
    if (x>1) {
    	ans1*=x; ans2*=(x*x);
    }
    a[now].x=ans1; a[now].y=ans2;
}
bool cmp(node x,node y)
{
	return x.x<y.x;
}
int main()
{
	scanf("%d",&n);
	init();
	for (int i=1;i<=n;i++) {
		scanf("%lld",&s[i]);
		pan(s[i],i);
		mp[a[i].x]++;
	}
	sort(a+1,a+n+1,cmp);
	int ans=0;
	for (int i=1;i<=n;i++) 
		if (a[i].x!=1) 
			if (a[i].x!=a[i-1].x) {
				ans+=max(mp[a[i].x],mp[a[i].y]);
				mp[a[i].x]=0; mp[a[i].y]=0;
			}
	if (a[1].x==1) ans++;	
	cout << ans << endl;
}

