using namespace std;

typedef long long ll;

const ll INF = 10000000000;

int n,ans;

map<ll,int> cnt;
map<ll,ll> match;

int main()
{
	ios::sync_with_stdio(false);
	cin >> n;
	for (int i = 1;i <= n;i++)
	{
		ll a,spj;
		cin >> a;
		ll mat = 1;
		for (ll j = 2;j * j * j <= a;j++)
			while (a % (j * j * j) == 0)
				a /= j * j * j;
		cnt[a]++;
		ll A = a;
		for (ll j = 2;j * j * j <= a;j++)
		{
			if (a % (j * j) == 0)
			{
				a /= j * j;
				if (mat > INF / j)
				{
					mat = INF + 1;
					break;
				}
				mat *= j;
			}
			if (a % j == 0)
			{
				a /= j;
				if (mat > INF / j / j)
				{
					mat = INF + 1;
					break;
				}
				mat *= j * j;
			}
		}
		if (mat == INF + 1)
			continue;
		spj = pow(a,1.0 / 2);
		while (spj * spj < a)
			spj++;
		while (spj * spj > a)
			spj--;
		if (spj * spj == a)
		{
			a /= spj * spj;
			if (mat > INF / spj)
				continue;
			mat *= spj;
		}
		if (mat > INF / a / a)
			continue;
		mat *= a * a;
		match[match[mat] = A] = mat;
	}
	for (map<ll,int>::iterator i = cnt.begin();i != cnt.end();i++)
	{
		if ((*i).first == 1)
		{
			ans += (*i).second - 1;
			continue;
		}
		ll cur = min((*i).second,cnt[match[(*i).first]]);
		ans += cur;
		(*i).second -= cur;
		cnt[match[(*i).first]] -= cur;
	}
	cout << n - ans << endl;
	return 0;
}

