long long arr[100050];
bool isPrime[100050];
vector<int> prime;
int main()
{
    memset(isPrime, true, sizeof(isPrime));
    for(int i = 2; i <= 100000; ++i)
    {
        if(!isPrime[i])
            continue;
        prime.push_back(i);
        for(int j = i + i; j <= 100000; j += i)
            isPrime[j] = false;
    }
    int n;
    scanf("%d", &n);
    for(int i = 1; i <= n; ++i)
        scanf("%lld", &arr[i]);
    int ans = 0;
    for(int i = 1; i <= n; ++i)
    {
        if(arr[i] == 1)
            ++cnt[1];
        else
        {
            long long a, b;
            a = 1ll;
            b = 1ll;
            for(vector<int>::size_type j = 0; j < prime.size(); ++j)
            {
                if(static_cast<int>(prime[j]) * prime[j] > arr[i])
                    break;
                if(arr[i] % prime[j] == 0)
                {
                    int cnt = 0;
                    while(arr[i] % prime[j] == 0)
                    {
                        ++cnt;
                        arr[i] /= prime[j];
                    }
                    cnt %= 3;
                    int tmp = 0;
                    if(cnt)
                        tmp = 3 - cnt;
                    while(cnt--)
                        a *= prime[j];
                    while(tmp--)
                        b *= prime[j];
                }
            }
            if(arr[i] != 1)
            {
                a = a * arr[i];
                b = b * arr[i] * arr[i];
            }
            ++cnt[a];
            if(a != 1)
            {
                if(a > b)
                    swap(a, b);
                match[a] = b;
            }
        }
    }
    if(cnt.find(1) != cnt.end())
        ans = 1;
    for(auto it = match.begin(); it != match.end(); ++it)
    {
        long long a, b;
        a = it->first;
        b = it->second;
        ans += max(cnt[a], cnt[b]);
    }
    printf("%d\n", ans);
    return 0;
}

