map<long long,long long> mp,que;
int pr[10010],pnum;
vector <int> des[233333];
int work(long long w)
{
	long long p=1,q=1;
	for (int i=1;((pr[i]*pr[i]<=w)&&(i<=pnum));i++)
	{
		int js=0;
		while (w%pr[i]==0)
		{
			w/=pr[i];
			js++;
		}
		js%=3;
		if (js==1) {p*=pr[i];if ((double)q*pr[i]*pr[i]>1.1e12) {p=q=0;break;}q=q*pr[i]*pr[i];}
		else if (js==2) {p=p*pr[i]*pr[i];if ((double)q*pr[i]>1.1e12) {p=q=0;break;}q=q*pr[i];}
	}
	if (w!=1) {p*=w;if ((double)q*w*w>1.1e12) p=q=0;q=q*w*w;}
	if (p==0) return 0;
	mp[p]=q;mp[q]=p;//cout<<p<<' '<<q<<endl;
	return p;
}
pair<int,int> dfs(int s,int col=0)
{
	vis[s]=true;
	pair<int,int> p=make_pair((col==0)*num[s],(col==1)*num[s]);
	for (int k=0;k<des[s].size();k++) if (!vis[des[s][k]])
	{
		pair<int,int> q=dfs(des[s][k],col^1);
		p.first+=q.first;p.second+=q.second;
	}
	return p;
}
int main()
{
	pr[1]=2;pnum=1;
	for (int i=3;i<=30000;i+=2)
	{
		bool err=false;
		for (int j=2;j*j<=i;j++) if (i%j==0) {err=true;break;}
		if (!err) pr[++pnum]=i;
	}//cerr<<pnum<<endl;
	int n,ans=0,gg=0;scanf("%d",&n);
	for (int i=1;i<=n;i++)
	{
		long long w;scanf("%lld",&w);
		w=work(w);
		if (w==0) {gg++;continue;}
		if (w==1) {ans=1;continue;}
		que[w]++;
	}
	ans+=gg;
	for (map<long long,long long>::iterator it=que.begin();it!=que.end();it++)
	{
		top++;
		st[top]=it->first;num[top]=it->second;
		it->second=top;
	}
	for (int i=1;i<=top;i++) if (que.count(mp[st[i]]))
	{
		des[i].push_back(que[mp[st[i]]]);
	}
	for (int i=1;i<=top;i++) if (!vis[i])
	{
		pair<int,int> p=dfs(i);//cout<<p.first<<' '<<p.second<<endl;
		ans+=max(p.first,p.second);
	}
	printf("%d\n",ans);
}

