{
    long long maxv = 0;
    int n;
    cin >> n;
    for (int i = 1; i <= n; ++i) {
        cin >> v[i];
        dense[v[i]]++;
        maxv = max(maxv, v[i]);
    }

    for (long long i = 1; i <= 3000; ++i) {
        long long cube = i * i * i;
        if (i <= 1000) {
            for (int j = 1; j <= n; ++j) {
                if (v[j] % cube == 0) {
                    reduced[v[j]] = v[j] / cube;
                }
            }
        } else {
            for (long long j = cube; j <= maxv; j += cube) {
                if (dense.find(j) != dense.end()) {
                    reduced[j] = j / cube;
                }
            }
        }
    }

    maxv = 0;
    dense.clear();
    for (int i = 1; i <= n; ++i) {
        v[i] = reduced[v[i]];
        dense[v[i]]++;
        maxv = max(maxv, v[i]);
    }

    for (long long i = 1; i <= 100000; ++i) {
        long long square = i * i;
        if (i <= 1000) {
            for (int j = 1; j <= n; ++j) {
                if (v[j] % square == 0) {
                    opposite[v[j]] = (v[j] / square) * (v[j] / square) * i;
                }
            }
        } else {
            for (long long j = square; j <= maxv; j += square) {
                if (dense.find(j) != dense.end()) {
                    opposite[j] = (j / square) * (j / square) * i;
                }
            }
        }
    }

    int ans = 0;
    for (int i = 1; i <= n; ++i) {
        if (V.find(v[i]) != V.end()) {
            continue;
        }
        V.insert(v[i]);
        if (v[i] == 1) {
            ans++;
            continue;
        }
        long long op = opposite[v[i]];
        int val1 = dense[v[i]];
        int val2;
        if (dense.find(op) != dense.end()) {
            val2 = dense[op];
            V.insert(op);
        } else {
            val2 = 0;
        }
        ans += max(val1, val2);
    }
    cout << ans;
}

