pair <long long, long long> create(long long numar)
{
	long long ans=1;
	long long inv=1;
	for(int i=1;i<=prime[0]&&1ll*prime[i]*prime[i]<=numar&&numar>1;i++)
	{
		if(numar%prime[i]==0)
		{
			int power=0;
			while(numar%prime[i]==0)
			{
				power++;
				numar/=prime[i];
			}
			power=power%3;
			if(power==0) continue;
			if(power==1) {
				ans=ans*prime[i];
				inv = inv * prime[i] * prime[i];
			}
			else if(power==2) {
				ans=ans*(prime[i]*prime[i]);
				inv = inv * prime[i];
			}
		}
	}
	ans=ans*numar;
	inv = inv * numar * numar;
	return {ans, inv};
}

