#define INF numeric_limits<double>::infinity()
constexpr long MOD = 1e9 + 7;
using namespace std;
using P = pair<long, long>;
using VI = vector<long>;

using VP = vector<P>;

VI primes = {2};
unordered_map<long, long> cubes;

void addPrimes() {
    for (int i = 3; i <= 100000; i += 2) {
        bool fl = true;
        for (int j: primes) {
            if (i % j == 0) fl = false;
            break;
        }
        if (fl) primes.push_back(i);
    }
}

void addCubes() {
    for (long i = 1; i * i * i <= 10000000000l; i++) {
        cubes[i * i * i]++;
    }
}

long getminp(long p) {
    for (int j: primes) if (p % j == 0) return j;
    return p;
}

VP fctr(long s) {
    VP v;
    while (s != 1) {
        long p = getminp(s);
        long cnt = 0;
        while (s % p == 0) {
            s /= p;
            cnt++;
        }
        if (cnt % 3) {
            v.push_back(P(p, cnt % 3));
        }
    }
    return v;
}

long cnt = 0;
map<VP, long> m;

void hoge(VP f) {
    if (m[f] == 0) return;
    VP v;
    for (P a: f) {
        v.push_back(P(a.first, (3 - a.second) % 3));
    }
    if (m[f] == 2 || m[v] == 0) {
        cnt += m[f];
        m[f] = 0;
        m[v] = 0;
    } else {
        cnt += m[v];
        m[f] = 0;
        m[v] = 0;
    }
}

int main() {
    addPrimes();
    addCubes();
    long n;
    cin >> n;
    bool hasCube;
    long s;
    REP(i,n) {
        cin >> s;
        if (cubes[s]) {
            hasCube = true;
        } else {
            VP f = fctr(s);
            m[f]++;
        }
    }

    for (auto itr = m.begin(); itr != m.end(); itr++) {
        hoge(itr->first);
    }
    cout << cnt + hasCube << endl;
}

