ll mul(ll x, ll y) {
    return (x * y) % MOD;
}
ll bin_pow(ll x, ll p) {
    if (p == 0) return 1;
    if (p & 1) return mul(x, bin_pow(x, p - 1));
    return bin_pow(mul(x, x), p / 2);
}

ll mult(ll x, ll y) {
    if (INF / x < y) return INF;
    return min(INF, x * y);
}
ll mySqrt(ll x) {
    ll y = (ll)sqrt(x);
    while(y * y > x) y--;
    while(y * y < x) y++;
    if (y * y == x) return y;
    return -1;
}

map<ll, int> mapchik;

ll cubeFree(ll x) {
    ll res = 1;
    for (ll p = 2; p * p * p <= x; p++) {
        if (x % p) continue;
        int t = 0;
        while(x % p == 0) {
            x /= p;
            t++;
        }
        t %= 3;
        while(t--) res *= p;
    }
    return res * x;
}
ll getPair(ll x) {
    ll res = 1;
    for (ll p = 2; p * p * p <= x; p++) {
        if (x % p) continue;
        int t = 0;
        while(x % p == 0) {
            x /= p;
            t++;
        }
        assert(t < 3);
        if (t == 1) {
            res = mult(res, p);
            res = mult(res, p);
        } else {
            res = mult(res, p);
        }
    }
    if (x > 1) {
        ll y = mySqrt(x);
        if (y == -1) {
            res = mult(res, x);
            res = mult(res, x);
        } else {
            res = mult(res, y);
        }
    }
    return res;
}

