			gpv.PB(i);
			chkmin(sp[i],i);
		}
	}
}
map<ll,ll> factorize(ll x) {
	map<ll,ll> h;
	if (MAXP*MAXP*MAXP>x) {
		ll r=round(sqrt(x));
		if (r*r==x) {
			h[r]=2;
		}
		else h[x]=1;
		return h;
	}
	while(x>=MAXP) {
		/*if (isPrime(x)) { // Increase speed, reduce accuracy
			h[x]++;
			return h;
		}*/
		bool found=false;
		for (auto &p:gpv) {
			if (p*p>x) break;
			while ((x%p)==0) {
				x/=p;
				h[p]++;
				found=true;
			}
			if (x<MAXP) break;
		}
		if (!found) break;
	}
	if (x<MAXP) {
		while(x>1) {
		ll p=sp[x];
		x/=p;
		h[p]++;
		}
	}
	if (x>1) h[x]++;
	return h;
}
