            for (int j = 2 * i; j < MAXN; j += i) {
                prime[j] = 0;
            }
            primes.push_back(i);
        }
    }
}

ll no_cubic(ll x) {
    for (ll i = 2; i * i * i <= x; i++) {
        while (x % (i * i * i) == 0) {
            x /= (i * i * i);
        }
    }
    return x;
}

ll get_pair(ll x) {
    ll sq = 1;
    ll tx = x;
    for (int t = 2; (ll)t * t <= tx; t++) {
        if (tx % ((ll)t * t) == 0) {
            sq *= t;
            tx /= t;
            tx /= t;
        } 
    }
    ll sl = x / (sq * sq);
    ll ans = sq * sl;
    if (ans > INF / sl) {
        return -1;
    } else {
        return ans * sl;
    }
}

signed main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);

    init();

    int n;
    cin >> n;
    map<ll, int> cnt;
    for (int i = 0; i < n; i++) {
        ll x;
        cin >> x;
        x = no_cubic(x);
        cnt[x]++;
    }
    auto get_cnt = [&](ll x) {
        if (cnt.count(x)) {
            return cnt[x];
        } else {
            return (int)0;
        }
    };
    int ans = 0;
    if (cnt.count(1)) {
        ans++;
        cnt.erase(1);
    }
    set<pair<ll, ll>> seen;
    for (auto uu : cnt) {
        ll f, no_need;
        tie(f, no_need) = uu;
        ll pr = get_pair(f);
        if (pr == -1) {
            ans += cnt[f];
            continue;
        }
        ll a = pr;
        ll b = f;
        if (a > b) {
            swap(a, b);
        }
        if (!seen.count({a, b})) {
