pair<ll,int> canon(ll n) {
    ll a = 1, b = 1;
    for (int d : p) if (n%d == 0) {
        int pot = 0;
        while (n%d == 0) {
            n /= d;
            pot++;
        }
        pot %= 3;
        if (pot) {
            forn(_,pot) a *= d;
            forn(_,3-pot) b *= d;
        }
    }
    if (n > 1) return mp(-1,0);

    if (a <= b) return mp(a,0);
    else return mp(b,1);
}

