void work(long long o,long long x)
{
	a[o]=b[o]=1;
	for(long long i=1;pr[i]*pr[i]*pr[i]<=x;i++)
	{
		long long jl=0;
		while(x%pr[i]==0)
		{
			x/=pr[i];
			jl++;
		}
		jl%=3;
		if(jl==1)
			a[o]*=pr[i],b[o]*=pr[i]*pr[i];
		if(jl==2)
			b[o]*=pr[i],a[o]*=pr[i]*pr[i];
	}
	if(x!=1)
	{
		long long k=sqrt(x);
		if(k*k==x)
			a[o]*=k*k,b[o]*=k;
		else
			a[o]*=x,b[o]*=x*x;
	}
}
