ll get(ll x) {
	ll res = 1;
	vector<ll> tm, f;
	llfactorize(x, f);
	sort(f.begin(), f.end());
	f.resize(unique(f.begin(), f.end()) - f.begin());
	for (auto i : f) {
		if (x % i == 0)
			tm.pb(i);
		ll cnt = 0;
		while (x % i == 0)
			x /= i, cnt++;
		cnt %= 3;
		while (cnt --> 0)
			res *= i;
	}
	if (x > 1)
		res *= x, tm.pb(x);
	if (!PR.count(res))
		PR[res] = tm;
	return res;
}
ll getrev(ll x) {
	ll res = 1;
	for (auto i : PR[x]) {
		ll cnt = 0, tmp = x;
		while (tmp % i == 0)
			tmp /= i, cnt++;
		cnt %= 3;
		cnt = (3 - cnt) % 3;
		while (cnt --> 0)
			res *= i;
	}
	return res;
}

