void work(int id,ll x){
    a[id]=b[id]=1;
    for(ll i=2;i*i*i<=x;i++){
        if(x%i) continue;
        int cnt=0;
        while(x%i==0) cnt++,x/=i;
        if(cnt%3==1) a[id]*=i,b[id]*=i*i;
