    rep(i,2,N - 10) {
        if (!a[i]) p[++l] = i;
        rep(j,1,l) {
            int k = i * p[j]; if (k > N - 10) break;
            a[k] = true;
            if (i % p[j] == 0) break;
        }
    }
}

int main() {
    int n; scanf("%d",&n);
    init();
    int ans = 0;
    rep(i,1,n) {
        LL a; scanf("%lld",&a);

        LL t1 = 1, t2 = 1;
        rep(j,1,l) {
            if (p[j] > a) break;
            int c = 0;
            while (a % p[j] == 0) {
                a /= p[j];
                c++;
            }
            if (c % 3 == 1) t1 *= p[j], t2 *= p[j] * p[j];
            else if (c % 3 == 2) t1 *= p[j] * p[j], t2 *= p[j];
        }

        t1 *= a;
        int t = (int)sqrt(a) - 1;
        while (1LL * t * t < a) t++;
        if (1LL * t * t != a) t2 *= a * a;
        else t2 *= t;

        if (t2 == 1) ans = 1;
        else {
            rev[t1] = t2, rev[t2] = t1;
            if (cnt.find(t1) == cnt.end()) cnt[t1] = 1;
            else cnt[t1] += 1;
        }
    }
    for(map<LL, int>::iterator it = cnt.begin(); it != cnt.end(); it++) {
        LL x = it->first; LL y = rev[x];
        if (x < y) ans += max(cnt[x], cnt[y]); 
    }
    printf("%d\n",ans);
    return 0;
}

