vector<LL> ps, tris;
map<LL, LL> sq2p, p2sq;

LL Reduce(LL v) {
  for (LL p : tris) {
    while (v%p == 0) v /= p;
  }
  return v;
}

LL Rev(LL v) {
  LL ret = 1;
  for (LL p : ps) {
    int e = 0;
    while (v%p == 0) {
      e++;
      v /= p;
    }

    assert(e <= 2);
    if (e == 1) ret *= p*p;
    else if (e == 2) ret *= p;
  }

  if (1 < v) { 
    assert(v > 2000);
    if (sq2p.count(v)) v = sq2p[v];
    else if (p2sq.count(v)) v = p2sq[v];
    else return -1;
    ret *= v;
  } 

  return ret;
}

