    LL p = i;
    if (p < L) {
      ps.eb(p);
      tris.eb(p*p*p);
    } else {
      sq2p[p*p] = p;
      p2sq[p] = p*p;
    }

    for (int j=i+i; j<M; j+=i) {
      is_composite[j] = true;
