using namespace std;

typedef long long LL;
vector<LL> primes;
const LL CBRT = 2200;
LL cb[CBRT];
const LL LIM = 1e11+5;


void sieve() {
    vector<bool> isp(CBRT, 1);
    for (LL i=2; i<CBRT; i++)
        if (isp[i]) {
            primes.push_back(i);
            for (LL j=2*i; j<CBRT; j+=i)
                isp[j] = 0;
        }
    for (LL i=0; i<CBRT; i++)  cb[i] = 1LL*i*i*i;
}

pair<LL, LL> process(LL x) {
    if (x == 1)     return {1, 1};

    for (LL p:primes)
        while (x%cb[p]==0)  x/=cb[p];

    LL a = x;

    for (LL i=1; i<CBRT; i++)
        if (cb[i]%a==0)
            return {a, cb[i]/a};

    return {a, LIM};
}

const LL N = 1e5+7;
LL a[N], b[N];

int main() {
    ios::sync_with_stdio(0);
    cin.tie(0);

    sieve();

    LL n;
    cin>>n;

    map<LL, LL> cnt;
    map<LL, LL> opp;

    for (LL i=1; i<=n; i++) {
        LL x;
        cin>>x;

        auto pr = process(x);
        a[i] = pr.first;
        b[i] = pr.second;

        cnt[a[i]]++;
        opp[a[i]] = b[i];
        opp[b[i]] = a[i];
    }
    cnt[LIM] = 0;

    LL ans = 0;
    for (auto pr: opp) {
        LL a = pr.first, b = pr.second;
        if (a == LIM)   continue;
        if (a == b) assert(a == 1);
        if (a == b)     ans += min(1LL, cnt[a]+cnt[b]);
        else if (a < b) ans += max(cnt[a], cnt[b]);
    }
    cout<<ans<<endl;
}

