        for (long long j = i * i; j < SMAX; j += i) {
            resh[j] = true;
        }
    }

    for (long long i = 0; i < SMAX; i++) {
        if (!resh[i]) primes.push_back(i);
    }


    int answer = 0;
    map <long long, int> mp;

    for (auto &x : a) {
        long long max_cube = 1;
        for (long long i = 1; i * i * i <= x; i++) {
            if (x % (i * i * i) == 0) {
                max_cube = i * i * i;
            }
        }
        x /= max_cube;
        mp[x] = 0;
    }

    for (auto &x : a) {
        mp[x]++;
    }

    for (auto &kv : mp) {
        long long INF = 1e11, num = kv.first, rev = 1;
