class Osak{
public:
    vector<int> div;
    Osak(int N) : div(N+1,0) {
        div[1] = 1;
        for(int i = 2; i*i <= N; ++i) {
            if(div[i]) continue;
            for(int j = i; j <= N; j += i) div[j] = i;
        }
    }
    inline vector<pair<long long,long long>> prime_factorization(int A) {
        assert(A < div.size());
        vector<int> tmp;
        while (A != 1) {
            int& p = div[A];
            tmp.push_back(p);
            A /= p;
        }
        sort(tmp.begin(),tmp.end());
        vector<pair<long long,long long>> ret;
        int prev = 0;
        for(int& p: tmp) {
            if(prev == p) ret.back().second++;
            else ret.push_back({p,1});
            prev = p;
        }
        return ret;
    }
};

