            int ex = 0;
            while(x % i == 0){
                x /= i;
                ex++;
            }
            ex %= 3;
            for(int j = 0 ; j < ex ; j++){
                a *= i;
            }
            for(int j = 0 ; j < (3 - ex) % 3 ; j++){
                b *= i;
                if(b > A) b = 0;
            }
        }
