void preprocess(void)
{
	int i;
	for(i=2 ; i<=sqcut ; i++)
	{
		primechk[i]=1;
	}
	int j;
	for(i=2 ; i<=sqcut ; i++)
	{
		if(primechk[i]==1)
		{
			sqofp.insert(i*i);
			for(j=2 ; i*j<=sqcut ; j++)
			{
				primechk[i*j]=0;
			}
		}	
	}
}

ll getnorm(ll x)
{
	int i;
	for(i=2 ; i<=cucut ; i++)
	{
		if(primechk[i]==1)
		{
			while(x%(i*i*i)==0)
			{
				x=x/(i*i*i);
			}
		}
	}
	return x;
}

ll getpart(ll x)
{
	ll ret=1;
	for(int i=2 ; i<=cucut; i++)
	{
		int cnt=0;
		if(primechk[i]==1)
		{
			while(x%i==0)
			{
				x=x/i;
				cnt++;
			}
			if(cnt%3==1)
			{
				ret*=(i*i);
			}
			else if(cnt%3==2)
			{
				ret*=i;
			}
		}
	}
	if(sqofp.lower_bound(x)==sqofp.upper_bound(x))
	{
		ret*=(x*x);
	}
	else
	{
		ret*=(ll)sqrt(x);
	}
	return ret;
}

