		part[i]=getpart(a[i]);
		if(part[i]==1 && exist1==false)
		{
			ans++; exist1=true;
		}
		else if(part[i]!=1)
		{
			fin[make_pair(part[i],norm[i])]++;
		}
	}
	for(map<pair<ll,ll>, int>::iterator it1=fin.begin() ; it1!=fin.end() ; it1++)
	{
		map<pair<ll,ll>, int>::iterator it2=fin.find(make_pair(it1->first.second,it1->first.first));
		if(it2==fin.end()) ans+=it1->second;
		else if(it1->second==it2->second)
		{
			if(it1->first.first>it2->first.first)
