}

pii Hash(int n) {
	int res = 1, rev = 1;
	for (int p: primes) {
		int a = 0;
		while (n % p == 0) n /= p, a++;
		res *= power(p, Mod(a, 3));
		rev *= power(p, Mod(3 - a, 3));
		if (n == 1) break; 
	}
	if (n > 1) res = n, rev = n;
	return mp(res, rev);
}

