            while (x % sqr3(primes[i]) == 0) {
                x /= sqr3(primes[i]);
            }
        }
        ll base1 = 1;
        ll base2 = 1;
        for (int i = 0; i < sz && sqr3(primes[i]) <= x; ++i) {
            if (x % primes[i] == 0) {
                int cnt = 0;
                while (x % primes[i] == 0) {
                    cnt++;
                    x /= primes[i];
                }
                assert(cnt < 3);
                if (cnt == 1) {
                    base1 *= primes[i];
                } else {
                    base2 *= primes[i];
                }
            }
        }
        if (x > 1) {
            ll s = sqrt(x);
            while (s * s < x) ++s;
            while (s * s > x) --s;
            if (s * s == x) {
                if (base2 *= s);
            } else {
                base1 *= x;
            }
        }
        if (base1 == 1 && base2 == 1) {
            zero = 1;
        }
        cnt[{base1, base2}]++;
    }
