        pll key = x.first;
        pll inv = {key.second, key.first};
        if (cnt.count(inv)) {
            if (inv < key) {
                ans += max(x.second, cnt[inv]);
            }
        } else {
            ans += x.second;
        }
    }
    cout << ans + zero;
}

