	for (ll i=0;i<n;i++) {
		ll x; scanf("%lld",&x);
		for (auto &w:cpv) {
			if (x<w) break;
			while (x%w==0) x/=w;
		}
		h[x]++;
	}
	ll ans=0;
	if (h[1]>0) {
		ans++;
		h.erase(1);
	}
	for (auto &w:h) {
		map<ll,ll> factors=factorize(w.first);
		ll key=1;
		for (auto &w:factors) {
			ll ex=3-w.second;
			for (ll i=0;i<ex;i++) key*=w.first;
		}
		auto it=h.find(key);
		ll other;
		if (it==h.end()) {
			other=0;
		}
		else {
			other=it->second;
			h.erase(it);
		}
		ans+=max(w.second,other);
	}
	printf("%lld\n",ans);
}

