template<class T, class U> void assign(V<T>& v, int n, const U& a) { v.assign(n, a); }
template<class T, class... Args> void assign(V<T>& v, int n, const Args&... args) { v.resize(n); for (auto&& e : v) assign(e, args...); }


template<class Int> V<Int> sieve(Int a, Int b) {
  a = max<Int>(2, a); V<Int> res; Int q = ceil(sqrt(b));
  V<bool> mem(b - a, true), sub(q - 2, true);
  for (Int i = 2; i < q; ++i) {
    if (sub[i - 2]) {
      for (Int j = max(i, (a + i - 1) / i) * i; j < b; j += i) mem[j - a] = false;
      for (Int j = i * i; j < q; j += i) sub[j - 2] = false;
    }
  }
  for (Int i = a; i < b; ++i) if (mem[i - a]) res.push_back(i);
  return res;
}

map<int, int> factor(lint n) {
  static auto ps = sieve<int>(2, 1e5);
  map<int, int> res;
  for (int p : ps) {
    while (n % p == 0) {
      ++res[p];
      n /= p;
    }
  }
  if (n != 1) ++res[n];
  return res;
}

int main() {
  cin.tie(nullptr); ios_base::sync_with_stdio(false);
  int n; cin >> n;
  V<lint> a(n); for (int i = 0; i < n; ++i) cin >> a[i];
  V< map<int, int> > mp(n);
  for (int i = 0; i < n; ++i) {
    mp[i] = factor(a[i]);
    for (auto itr = begin(mp[i]); itr != end(mp[i]); ) {
      if ((itr->second %= 3) == 0) {
        mp[i].erase(itr++);
      } else {
        ++itr;
      }
    }
  }

  map< map<int, int>, int > mp1, mp2;
  int res = 0;
  for (auto&& e : mp) {
    if (e.empty()) {
      res = max(res, 1);
      continue;
    }
    if (begin(e)->second == 1) {
      ++mp1[e];
    } else {
      for (auto&& f : e) {
        f.second = 3 - f.second;
      }
      ++mp2[e];
    }
  }
  for (const auto& e : mp1) {
    if (mp2.count(e.first)) {
      res += max(e.second, mp2[e.first]);
    } else {
      res += e.second;
    }
  }
  cout << res << '\n';
}

