std::map<ll,int>Norm,Pair;

std::vector<ll>tmp;

inline void jzp(int n){
	for(int x=2;x<=n;++x){
		if(!vis[x])pri.push_back(x);
		for(auto&y:pri){
			if((ll)x*y>n)break;
			vis[x*y]=1;
			if(!(x%y))break;
		}
	}
}

inline void get_norm(ll x){
	for(auto&y:pri){
		ll z=1ll*y*y*y;
		if(z>x)break;
		while(!(x%z))x/=z;
	}
	if(++Norm[x]==1)
		tmp.push_back(x);
}

inline void get_pair(__int128 x){
	__int128 res=1;
	for(auto&y:pri){
		__int128 z=(__int128)y*y*y;
		if(z<=x){
			while(!(x%z))x/=z;
			if(!(x%(y*y))){
				res*=y;
				x/=(y*y);
			}
			else if(!(x%y)){
				res*=(y*y);
				x/=y;
			}
		}
		else{
			__int128 w=(__int128)y*y;
			if(w>x){
				res*=(__int128)x*x;
				break;
			}
			else if(!(x%y)){
				if(x==w)res*=y;
				else res*=(__int128)x*x;
				break;
			}
		}
	}
	if(res>1e10){++ans; return;}
	if(++Pair[(ll)res]==1)
		tmp.push_back((ll)res);
}

int main(){
	jzp(1e5);
	scanf("%d",&n);
	while(n--){
		ll s;
		scanf("%lld",&s);
		get_norm(s),get_pair(s);
	}
	std::sort(tmp.begin(),tmp.end());
	tmp.erase(std::unique(tmp.begin(),tmp.end()),tmp.end());
	for(auto&x:tmp)
		if(x!=1){
			ans+=std::max(Norm[x],Pair[x]);
		}
	assert(~ans&1),ans>>=1;
	if(tmp[0]==1)++ans;
	printf("%d\n",ans);
	return 0;
}

