				for(;x%pri[i]==0;x/=pri[i])
					t[cntp].y++;
				if((t[cntp].y%=3)==0)cntp--;
			}
	}
	ll calc()
	{
		ll ret=0;
		for(int i=1;i<=cntp;i++)
			ret=(ret*H+t[i].x*t[i].y%MOD)%MOD;
		return ret;
	}

	void solve()
	{
		getpri();
		initialize();

//		for(int i=1;i<=n;i++)
//			printf("%lld ",s[i]);
//		printf("\n");
		for(int i=1;i<=n;i++)
		{
			divide(s[i]);
			ll hx=calc(),hy;
			for(int j=1;j<=cntp;j++)
				t[j].y=3-t[j].y;
			hy=calc();
//			printf("%lld : %lld , %lld\n",s[i],hx,hy);
			int cx=G[hx],cy=G[hy];
			if(cx>=cy)ans++;
			G[hx]++;
		}
		printf("%d\n",ans);
	}
}
