map<lint, int> record, same;
lint a[MAXN];

lint read() {
    char c = getchar();
    lint x = 0;
    while (!isdigit(c))
        c = getchar();
    while (isdigit(c)) {
        x = (x << 3) + (x << 1) + c - '0';
        c = getchar();
    }
    return x;
}

void sieve() {
    for (int i = 2; i <= N; ++i) {
        if (!v[i])
            prime[++total] = i;
        for (int j = 1; j <= total && i * prime[j] <= N; ++j) {
            v[i * prime[j]] = 1;
            if (i % prime[j] == 0)
                break;
        }
    }
}

lint power(lint a, int b) {
    lint res = 1;
    while (b) {
        if (b & 1)
            res = res * a;
        a = a * a;
        b >>= 1;
    }
    return res;
}

void divide(lint x) {
    lint rev = 1, cur = 1;
    for (int i = 1; i <= total; ++i)
        if (x % prime[i] == 0) {
            int sum = 0;
            while (x % prime[i] == 0) {
                x /= prime[i];
                ++sum;
            }
            sum %= 3;
            if (sum != 0) {
                rev = rev * power(prime[i], 3 - sum);
                cur = cur * power(prime[i], sum);
            }
        }
//    if (cur == 10034)
//        cout << 10034 * 10034 << endl;
    if (x != 1) {
        if (x >= M) {
            if ((lint)sqrt(x) * (lint)sqrt(x) != x) {
                ++ans;
                return ;
            }
            rev = rev * sqrt(x);
            cur = cur * x;
        }
        else {
            rev = rev * x * x;
            cur = cur * x;
        }
    }
    if (rev == cur) {
        ans += !record[cur];
        record[cur] = true;
        return ;
    }
    ans -= max(record[rev], record[cur]);
    ++record[cur];
    ans += max(record[rev], record[cur]);
}

