vl SieveEratos(int n,map<ll,ll>& m){
	vl a(n+1,1),b;
	for(ll i=2;i<=n;i++) if(a[i]){
		if(i*i*i<=MAX) b.push_back(i);
		m[i*i]=i;
		b.push_back(i);
		for(int j=i;j<=n;j+=i) a[j]=0;
	}
	return b;
}

