int main(){
	cin>>n;
	set<ll> st;
	map<ll,ll> m,m1,m2;
	a=SieveEratos(1e5,m);
	int res=0,S=a.size(),B=1;
	for(int i=0;i<n;i++){
		ll A,Norm=1,Pair=1;
		cin>>A;
		for(int j=0;j<S;j++){
			int cnt=0,p=a[j];
			while(A%p==0){
				A/=p;
				cnt++;
			}
			cnt%=3;
			if(cnt==1){
				Norm*=p;
				Pair*=p*p;
			}
			if(cnt==2){
				Norm*=p*p;
				Pair*=p;
			}
		}
		Norm*=A;
		if(Norm==1){
			res+=2*B;
			B=0;
			continue;
		}
		st.insert(Norm);
		m1[Norm]++;
