        if(n==1) continue;
        if(used[n]){
            if(used[p]) continue;
            ans += NN[p];
        }else if(used[p]){
            if(used[n]) continue;
            ans += NN[n];
        }else{
            if(NN[n] >= NN[p]){
                ans += NN[n];
            }else{
                ans += NN[p];
            }
        }
        used[n]=used[p]=true;
    }

    cout << ans << endl;
}

