	unordered_map<unsigned long long int, int>m;
	for (auto &i : v) {
		cin >> i;
	}
	for (long long int i = 0; i*i*i <= 10000000000; i++) {
		cube.push_back(i*i*i);
	}
	for (auto i : v) {
		for (int j = 2; j < cube.size();j++) {
			while (i%cube[j] == 0)i /= cube[j];
		}
		if (i == 1) {
			flag = true;
			continue;
		}
		m[i]++;
	}
	unsigned long long int border = 1300000000;
	border *= 10000000000;
	for (unsigned long long int i = cube.size(); i*i*i <= border; i++) {
		cube.push_back(i*i*i);
	}
	vector<int>prime(100001);
	for (auto i : P)prime[i] = 1;
	int ans = 0;
	for (auto i : m) {
		vector<long long int>box;
		unsigned long long int bag = i.first;
		for (auto j : P) {
			if (bag < j*j) {
				if (bag >= 100000)break;
				if (prime[bag]) {
					box.push_back(bag);
					bag = 1;
				}
				break;
			}
			if (bag%j == 0) {
				box.push_back(j);
				bag /= j;
			}
			if (bag%j == 0) {
				bag /= j;
			}
			if (bag == 1)break;
		}
		if (bag > 1) {
			ans += i.second;
			continue;
		}
		unsigned long long int num = 1;
		for (int j = 1; j < box.size(); j++)num *= box[j];
		if (num*box.front() > cube.size()) {
			ans += i.second;
			continue;
		}
		int cnt = 2;
