const int MaxN(100003);
ll s[MaxN], a[MaxN];
int pr[MaxN], tot;
map<ll, int> Sum;
map<ll, ll> Opp;
bool p[MaxN];

void init(int n)
{
	for(int i = 2; i <= n; i++)
		if(!p[i])
		{
			pr[++tot] = i;
			for(int j = i * i; j <= n; j += i)
				p[j] = true;
		}
}

inline ll Pow(int x, int cnt)
{
	ll res = 1;
	while(cnt--) res *= x;
	return res;
}

void work(ll x)
{
	ll res = 1, opp = 1;
	for(int i = 1; i <= tot; i++)
		if(x % pr[i] == 0)
		{
			int cnt = 0;
			while(x % pr[i] == 0)
				x /= pr[i], ++cnt;
			cnt %= 3;
			res *= Pow(pr[i], cnt);
			opp *= Pow(pr[i], (3 - cnt) % 3);
		}
	if(x > 1)
	{
		ll y = sqrt(x);
		if(y * y == x)
			res *= x, opp *= y;
		else res *= x, opp *= x * x;
	}
	Sum[res]++, Opp[res] = opp, Opp[opp] = res;
}

int main()
{
	int n;
	init(400);
	scanf("%d", &n);
	for(int i = 1; i <= n; i++)
	{
		scanf("%lld", &s[i]);
		work(s[i]);
	}
	int ans = 0;
	for(auto i : Sum)
	{
		if(i.first == 1) ans += 2;
		else ans += max(i.second, Sum[Opp[i.first]]);
	}
	printf("%d\n", ans >> 1);
	return 0;
}

