void sieve() {
	memset(isp, 1, sizeof isp); isp[1] = 0; 
	for(int i = 2; i <= 100000; i++) {
		if(isp[i]) {
			pr.pb(i);
			for(int j = i * i; j <= 100000; j += i) 
				isp[j] = 0;  
		}
	}
}

void get(int x, int id) {
	vector<ii> ret; 
	for(auto p : pr) {
		if(p * p > x) break; 
		if(x % p == 0) {
			int cnt = 0; 
			while(x % p == 0) {
				x /= p; 
				cnt++; 
			}
			cnt %= 3; 
			if(!cnt) continue; 
			ret.pb({p, cnt}); 
		}
	}
	if(x > 1) 
		ret.pb({x, 1});
	int ans = 1, comp = 1; 
	for(auto t : ret) {
		for(int i = 1; i <= t.se; i++) 
			ans *= t.fi; 
		for(int i = 1; i <= 3 - t.se; i++) 
		 	comp *= t.fi;
	} 
	b[id] = {ans, comp}; 
}

