const int N = 1e5 + 1;

void solve() {
    int n;
    cin >> n;
    vector<ll> a0(n), a(n, 1), b(n, 1);
    vb prime(N, 1);
    prime[0] = prime[1] = 0;
    vll primes;
    for1(i, 1, N){
        if (!prime[i]) continue;
        primes.pb(i);
        for (int j = 2 * i; j < N; j += i) prime[j] = 0;
    }
    map<ll, ll> m;
    forn(i, n){
        cin >> a0[i];
        map<ll, int> f;
        ll x = a0[i];
        if (m.count(a0[i])){
            a[i] = a[m[a0[i]]];
            b[i] = a[m[a0[i]]];
            continue;
        }
        m[a0[i]] = i;
        while(true){
            bool flag = false;
            for (ll y : primes){
                if (y * y > x) break;
                while (x % y == 0){
                    f[y] = (f[y] + 1) % 3;
                    x /= y;
                    flag = true;
                }
                if (flag) break;
            }
            if (!flag){
                f[x] = (f[x] + 1) % 3;
                break;
            }
        }
        for (pll p : f){
            forn(j, p.S) a[i] *= p.F;
            forn(j, (3 - p.S) % 3) b[i] *= p.F;
        }

    }
    map<ll, int> cnt;
    forn(i, n) cnt[a[i]]++;
    ll ans = 0;
    set<ll> used;
    forn(i, n){
        if (used.count(a[i])) continue;
        used.insert(a[i]);
        used.insert(b[i]);
        if (a[i] == 1){
            ans++;
            continue;
        }
        ans += max(cnt[a[i]], cnt[b[i]]);
    }
    cout << ans << '\n';
}

