	for(i=0;i<n;i++){
		scanf("%lld",&a);
		b = c = 1;
		for(j=2;j<=2500 && j<=a;j++) if(a % j == 0){
			for(k=0;a%j == 0;k++) a /= j;
			if(k % 3 == 1) b *= j, c *= j * j;
			else if(k % 3 > 0) b *= j * j, c *= j;
		}
		if(a == 1 && b == 1) f = 1;
		else V.push_back({b, c, a});
	}

	sort(V.begin(), V.end(), [&](tp ca, tp cb){
		if(ca.f != cb.f) return ca.f < cb.f;
		else return ca.t < cb.t;
	});

	for(i=s=0;i<V.size();i++){
		if(!i || (V[i].f != V[i-1].f || V[i].t != V[i-1].t)){
			s ++;
			F[s] = V[i].f;
			S[s] = V[i].s;
			T[s] = V[i].t;
			K[s] = 1;
		}
		else K[s] ++;
	}

	for(i=1;i<=s;i++){
		if(F[i] > S[i] || T[i] > 1e9 || T[i] * T[i] > 1e10) continue;

		l = lower_bound(F+1, F+s+1, S[i]) - F;
		r = upper_bound(F+1, F+s+1, S[i]) - F;
		k = lower_bound(T+l, T+r, T[i] * T[i]) - T;
		if(T[k] == T[i] * T[i]){
			ans += max(K[i], K[k]);
			K[k] = 0;
		}
		else ans += K[i];
		K[i] = 0;
	}

	for(i=1;i<=s;i++) ans += K[i];

	printf("%lld\n",ans + f);

	return 0;
}

