PLL reg (PLL p) {
    ll x = p.first;
    ll y = 0;

    for (ll d=2; d*d<=x; d++) {
        if(x%d==0){
            while(x%d==0){
                y++;
                x/=d;
            }

            if(x==1){
                return make_pair(d,y);
            }
        }
    }
    return p;
