// https://img.atcoder.jp/data/agc/003/editorial.pdf
#include <bits/stdc++.h>
using namespace std;
using LL = long long;
#define repex(i, a, b, c) for(int i = a; i < b; i += c)
#define repx(i, a, b) repex(i, a, b, 1)
#define rep(i, n) repx(i, 0, n)
#define repr(i, a, b) for(int i = a; i >= b; i--)
#define pb push_back
const int MAX = 101010;
LL S[MAX], a[MAX], Norm[MAX], Pair[MAX];
vector<LL> Prime;    // 素数を保存.
vector<LL> vPrime2;  // 素数の二乗を保存.
map<LL, LL> mPrime2; // 素数の二乗を保存.

int main(){

    // 1. 入力情報.
    int N;
    scanf("%d", &N);
    rep(i, N) scanf("%lld", &S[i]);

    // 2. 素数を取得.
    repx(i, 2, 101010){
        if(a[i]) continue;
        repex(j, i * 2, 101010, i) a[j]++;
    }

    // 3. 素数, 素数の二乗 を 保存.
    repx(i, 2, 101010){
        LL p = (LL)i;
        if(!a[i]){
            Prime.pb(p);
            vPrime2.pb(p * p);
            mPrime2[p * p] = p; // 素数の二乗から, 素数を逆引き.
        }
    }
    // for(auto &x : Prime) printf("%d ", x);
    // puts("");
    // for(auto &x : Prime2) printf("%d ", x);
    // puts("");

    // 4. 標準系(Norm, Pair), 出現回数 を 保存.
    map<LL, LL> mNorm, mPair;
    rep(i, N){
        LL t = S[i];
        // Norm を 保存.
        // 同じ素因数を, 3つ以上含まなくなるまで立方数で割る.
        for(auto &x : Prime){
            LL x3 = x * x * x;
            while(t % x3 == 0) t /= x3;
            if(x3 >= t) break;
        }
        Norm[i] = t;

        // Pair を 保存.
        LL p = 1;
        if(t > 101010){
            if(mPrime2.count(t)) p = mPrime2[t];
            else                 p = t * t;
        }else{
            for(auto &x : Prime){
                if(t % x == 0){
                    LL x2 = x * x;
                    if(t % x2 == 0) t /= x2, p *= x;
                    else            t /= x,  p *= x2;
                }
                if(x >= t) break;
            }
        }
        Pair[i] = p;

        // 各標準形の出現回数を保存.
        mNorm[Norm[i]]++;
        mPair[Pair[i]]++;
    }
    // rep(i, N) printf("%lld ", Norm[i]);
    // puts("");
    // rep(i, N) printf("%lld ", Pair[i]);
    // puts("");

    // 5. 標準形 が Norm となるような要素数 と 標準形が Pair となるような要素数 のうち, 大きいほうをすべて加算.
    LL ans = 0;
    set<LL> nMemo, pMemo; // すでに出現したか確認.
    rep(i, N){
        LL n = Norm[i], p = Pair[i];
        if(nMemo.count(n) == 0 && nMemo.count(p) == 0 && pMemo.count(n) == 0 && pMemo.count(p) == 0){
            // 標準形 が Norm で, Norm が 1 の 場合は, 1回だけ加算.
            if(n == 1) ans++;
            else       ans += max({mNorm[n], mNorm[p], mPair[n], mPair[p]});
            nMemo.insert(n);
            nMemo.insert(p);
            pMemo.insert(n);
            pMemo.insert(p);
        }
    }

    // 6. 出力.
    printf("%lld\n", ans);
    return 0;

}

