using namespace std;

int nr, N, M, pr[50009];
bool cr[100009];
long long INF = 10000000000LL;
map < long long, int > mp, ops;

void prod (long long &x, long long y) {if (INF / x >= y) x = 1LL * x * y; else x = INF + 1;}

int main ()
{
//freopen ("input", "r", stdin);
//freopen ("output", "w", stdout);

scanf ("%d", &N), M = 1e5;
for (int i=2; i * i <= M; i++)
    if (cr[i] == 0)
        for (int j=i * i; j<=M; j+=i)
            cr[j] = 1;
for (int i=2; 1LL * i * i * i <= INF; i++)
    if (cr[i] == 0)
        pr[++nr] = i;
for (int POS = 1; POS <= N; POS ++)
{
    long long x;
    scanf ("%lld", &x);
    for (int i=2; 1LL * i * i * i<=x; i++)
    {
        long long q = 1LL * i * i * i;
        while (x % q == 0) x /= q;
    }
    long long OPS = 1, CURR = x;
    for (int i=1; i<=nr && 1LL * pr[i] * pr[i] * pr[i] <= x; i++)
    if (x % pr[i] == 0)
    {
        int e = 0;
        while (x % pr[i] == 0) x /= pr[i], e ++;
        if (e == 2) prod (OPS, pr[i]);
        else prod (OPS, 1LL * pr[i] * pr[i]);
    }
    int p = 1, u = M, mij, ras = -1;
    while (p <= u)
    {
        mij = (p + u) >> 1;
        if (1LL * mij * mij <= x) ras = mij, p = mij + 1;
        else u = mij - 1;
    }
    if (1LL * ras * ras == x && cr[ras] == 0) prod (OPS, ras);
    else prod (x, x), prod (OPS, x);
    //printf ("%lld %lld\n", CURR, OPS);
    mp[CURR] ++, ops[CURR] = OPS;
}
int ans = 0;
for (auto it = mp.begin (); it != mp.end (); it ++)
{
    if (it->first == 1) ans ++;
    else
    {
        int curr = mp[ops[it->first]];
        if (it->second > curr || (it->second == curr && it->first < ops[it->first]))
            ans += it->second;
    }
}
printf ("%d\n", ans);
return 0;
