			while (a[i] % (x * x * x) == 0) a[i] /= (x * x * x);
			int _A = a[i];
			int deg = 0;
			while (_A % x == 0) _A /= x, ++deg;
			deg = (3 - deg) % 3;
			if (deg == 1) ag[i] *= x, lol[i] *= (x * x);
			else if (deg == 2) ag[i] *= (x * x), lol[i] *= x;
		}
	}
	map< pair<int, int>, int > cnt, cnt1;
	map< pair<int, int>, bool> ban;
	for (int i = 1; i <= n; ++i) {
		int sq = (int)sqrt(a[i]);
		if (sq * sq != a[i]) {
			++cnt[make_pair(a[i], ag[i])];
		}
	}
	int res = 0;
	int OK = 0;
	for (int i = 1; i <= n; ++i) {
		if (a[i] == 1) {
			OK = 1;
			continue;
		}
		int sq = (int)sqrt(a[i]);
		if (sq * sq == a[i]) {
			++cnt1[make_pair(sq, lol[i])];
		}
	}
	res += OK;
	for (auto p : cnt1) {
		res += max(p.second, cnt[make_pair(p.first.first, p.first.second)]);
		ban[make_pair(p.first.first, p.first.second)] = 1;
	}
	for (auto p : cnt) {
		if (!ban[p.first]) {
			res += max(p.second, cnt1[make_pair(p.first.first, p.first.second)]);
		}
	}
	cout << res << '\n';
}

