int no_cubic(int x) {
    for (int i = 2; i * i * i <= x; i++) {
        while (x % (i * i * i) == 0) {
            x /= (i * i * i);
        }
    }
    return x;
}

int get_pair(int x) {
    int sq = 1;
    for (auto t : primes) {
        if (x % (t * t) == 0) {
            sq *= t;
        }
    }
    int sl = x / (sq * sq);
    int ans = sq * sl;
    if (ans > INF / sl) {
        return -1;
    } else {
        return ans * sl;
    }
}

