        if (pr == -1) {
            ans += cnt[f];
            continue;
        }
        int a = pr;
        int b = f;
        if (a > b) {
            swap(a, b);
        }
        if (!seen.count({a, b})) {
            cerr << "count " << a << ' ' << b << endl;
            ans += max(get_cnt(a), get_cnt(b));
            seen.insert({a, b});
        }
    } 
