bool mrrun(ll x, const bool iscut = true) {
	if(2 == x) return true;
	if(x < 2 || !(x&1)) return false;
	if(iscut && x < 10000) {
		for(int i = 3; i*i <= x; i += 2)
			if(!(x%i)) return false;
