const int MAX = 1e5 + 10;
const int CRT = 2200;

vector<int> lp(MAX, 0);
vector<long long> pr;

void init() {
  for(int i = 2; i < MAX; i++) {
    if(!lp[i]) {
      pr.push_back((long long) i);
      for(int j = 2 * i; j < MAX; j += i) {
        lp[j] = 1;
      }
    }
  }
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);
  init();
  int n;
  cin >> n;
  vector<long long> a(n);
  map<vector<pair<long long, int>>, int> mp;
  int ans = 0;
  for(int i = 0; i < n; i++) {
    cin >> a[i];
    vector<pair<long long, int>> Vp;
    for(int j = 0; j < MAX && pr[j] < CRT; j++) {
      int cn = 0;
      while(a[i] % pr[j] == 0) {
        cn++;
        a[i] /= pr[j];
      }
      cn %= 3;
      if(cn) Vp.push_back({pr[j], cn});
    }
    if(a[i] != 1) {
      if(a[i] < MAX && lp[a[i]] == 0) {
        Vp.push_back({a[i], 1});
        a[i] = 1;
      }
      else {
        long long msrt = sqrt(a[i]);
        if(msrt * msrt == a[i]) {
          Vp.push_back({msrt, 2});
          a[i] = 1;
        }
      }
    }
    if(a[i] != 1) ans++;
    else {
      mp[Vp]++;
    }
  }
  for(auto it = mp.begin(); it != mp.end(); it++) {
    int cnt1 = (*it).second, cnt2 = 0;
    if(cnt1 != 0) {
      vector<pair<long long, int>> Vp = (*it).first;
      if(Vp.size() == 0) {
        ans++;
        continue;
      }
      for(int i = 0; i < (int) Vp.size(); i++) {
        Vp[i].second = 3 - Vp[i].second;
      }
      auto it2 = mp.find(Vp);
      if(it2 != mp.end()) {
        cnt2 = (*it2).second;
        (*it2).second = 0;
      }
      ans += max(cnt1, cnt2);
    }
  }
  cout << ans << '\n';
  return 0;
}

