const int MAX_P = 4010; //max
bool prime[MAX_P+1];

void Eratosthenes(void){
  for(int i=2;i<=MAX_P;i++)
    prime[i]=true;

  for(int i=2;i*i<=MAX_P;i++)
    if(prime[i])  
      for(int j=i;i*j<=MAX_P;j++)
        prime[i*j]=false;
}

int main(){
  int n;
  ll in;
  vector<ll> s;
  vector<ll> prime_v,prime_v3;
  map<ll,int> mm;

  Eratosthenes();

  for(ll i=2;i<4010;i++){
    if(prime[i]) prime_v.push_back(i);
    if(prime[i]) prime_v3.push_back(i*i*i);
  }

  scanf("%d",&n);

  for(int i=0;i<n;i++){
    scanf("%lld",&in);
    s.push_back(in);
  }

  for(int i=0;i<n;i++){
    ll t = s[i];

    for(int j=0;j<prime_v3.size();j++){
      if(t < prime_v3[j]) break;

      while(t%prime_v3[j]==0){
        t /= prime_v3[j];
      }
    }

    s[i] = t;
  }

  for(int i=0;i<n;i++){
    mm[s[i]]++;
  }

  sort(s.begin(),s.end());
  s.erase(unique(s.begin(),s.end()),s.end());

  n = s.size();

  int ans = 0;

  for(int i=0;i<n;i++){
    int f[1000] = {};

    ll t = s[i];

    for(int j=0;j<prime_v.size();j++){
      if(t%(prime_v[j]*prime_v[j])==0){
        t/=(prime_v[j]*prime_v[j]);
        f[j] = 2;
      }else if(s[i]%prime_v[j]==0){
        t /= prime_v[j];
        f[j] = 1;
      }else{
        f[j] = 0;
      }
    }

    if(t == 1){

      ll q = 1;

      for(int j=0;j<prime_v.size();j++){
        if(f[j]==1)
          q *= (ll) prime_v[j] * prime_v[j];
        else if(f[j]==2)
          q *= prime_v[j];
      }

      if(mm[q]==0){
        ans += mm[s[i]];
      }else if(s[i] > q){
        ans += max(mm[s[i]],mm[q]);
      }
    }else{
        ans += mm[s[i]];
    }

  }

  if(mm[1] > 0) ans ++;

  printf("%d\n",ans);

  return 0;
}

