void solve() {
    int n, ans = 0;
    cin >> n;
    vi a(n);
    for (int i = 0; i < n; i++) {
        cin >> a[i];
        int res = 1, x = a[i], d;
        for (d = 2; d * d * d <= a[i]; d++) {
            int cube = d * d * d;
            while (x % cube == 0) {
                a[i] /= cube;
                x /= cube;
            }
            if (x % (d * d) == 0) {
                if(res > inf / d)
                    res = 0;
                res *= d;
                x /= (d * d);
            }
            else if (res % d == 0){
                if(res > inf / (d * d))
                    res = 0;
                res *= d * d;
                x /= d;
            }
        }
        int y = sqrt(x);
        if(y > 1 && x % y == 0)
            res *= y;
        else {
            res *= x * x;
        }
        rev[a[i]] = res;
        mp[a[i]]++;
    }
    for (auto u : mp) {
        if (u.first == 1)
            continue;
        ans += max(u.second, mp[rev[u.first]]);
        mp[rev[u.first]] = 0;
        mp[u.first] = 0;
    }
    cout << ans + !!mp[1];
}

