		set<ll>::iterator it2=s.find(t);
		if(it2!=s.end()){
			ll sz1=M[nw],sz2=M[t];
			ans+=max(sz1,sz2);
			used[t]=1;
		}
		else ans+=M[nw];
	}
	if(M[1]>1) cout<<ans-M[1]+1<<endl;
	else cout<<ans<<endl;
	return 0;
}

