using namespace std;
void reduce(long long& v, long long primes[]) {
	for(int i = 0; i<326; i++) {
		long long prime = primes[i];
		long long cube = prime*prime*prime;
		if(cube>v) break;
		long long vc = v/cube;
		while(vc*cube == v) {
			v = vc;
			vc = v/cube;
		}
	}
}
void inv(long long& v, long long primes[]) {
	long ret = 1;
	int pl = 9592;
	long p = 0;
	long sq = 0;
	long vsq = 0;
	long vp = 0;
	for(int i = 0; i<pl; i++) {
		p = primes[i];
		sq = p*p;
		if(sq>v) break;
		if(ret*p>10000000000L) {
			v = -1;
			return;
		}

		vsq = v/sq;
		if(vsq*sq == v) {
			ret *= p;
			v = vsq;
			continue;
		}

		vp = v/p;
		if(vp*p == v) {
			ret *= sq;
			v = vp;
		}

	}
	v = (log(ret) + 2*log(v) >= 24) ? -1 : ret*v*v;
}
int main() {
	int n;
	cin >> n;
	int ind = 0;
	long long primes [9592];
	primes[ind] = 2;
	ind = ind + 1;
	for(long i = 3; i<=100000; i+=2) {
		double sqr = sqrt(i + 0.0);
		bool prime = true;
		for(int j = 1; j<ind; j++) {
			long p = primes[j];
			if(p>sqr) break;
			if(i%p == 0) {
				prime = false;
				break;
			}
		}
		if(prime) {
			primes[ind] = i;
			ind = ind + 1;
		}
	}

	std::unordered_map<long long, int> m;
	long long s [n];
	ind = 0;
	for(int i = 0; i<n; i++) {

		long long v;
		cin >> v;
		reduce(v,primes);
		if (m.find(v) == m.end()) {
			m[v] = 1;
			s[ind] = v;
			ind = ind + 1;
		} else {
			m[v] = m[v] + 1;
		}

	}

	std::unordered_set<long long> nope;
	int picked = 0;
	for(int i = 0; i<ind; i++) {
		long long v = s[i];
		if(v == 1) {
			picked++;
			continue;
		}

		if(nope.find(v) == nope.end()) {
			long long inverted = v;
			inv(inverted,primes);
			int max = m[v];
			if(inverted != -1) {
				if(m.find(inverted) != m.end()) {
					max = (max > m[inverted]) ? max : m[inverted];
					nope.insert(inverted);
				}
			}
			picked+=max;
		}
	}
	cout << picked << endl;
	return 0;
}

