using namespace std;
bool is_prime(long long n){
	if(n == 2 || n == 3) return true; 
	if(n % 6 != 1 && n % 6 != 5) return false; 
	long long t = n; 
	for(long long k = 2; k * k <= n; k++){
		if(t % k == 0) return false; 
	}
	return true; 
}
int main(){
	int N; cin >> N; 
	long long S[100010] = {}; 
	for(int i = 0; i < N; i++) cin >> S[i]; 
	long long O[100010] = {}; 
	long long T[100010] = {}; 
	map<pair<long long, long long>, int> M; 
	map<pair<long long, long long>, bool> B; 
	vector<long long> P; 
	for(long long i = 2; i < 100000; i++){
		if(is_prime(i)) P.push_back(i); 
	}
	for(int i = 0; i < N; i++){
		vector<pair<long long, int>> prime; 
		long long int now = S[i]; 
		for(long long k = 0; P[k] * P[k] <= S[i]; k++){
			int pow = 0; 
			while(now % P[k] == 0){
				pow ++; now /= P[k]; 
			}
			prime.push_back(make_pair(P[k], pow)); 
			if(now == 1) break; 
		}
		if(now > 1) prime.push_back(make_pair(now, 1)); 
		long long int once = 1; 
		long long int twice = 1; 
		for(int j = 0; j < prime.size(); j++){
			if(prime.at(j).second % 3 == 1) once *= prime.at(j).first; 
			else if(prime.at(j).second % 3 == 2) twice *= prime.at(j).first; 
		}
		O[i] = once; T[i] = twice;  
		M[make_pair(once, twice)] ++; 
	}
	int ans = 0; 
	if(M[make_pair(1, 1)]){
		ans ++; B[make_pair(1, 1)] = true; 
	}
	for(int i = 0; i < N; i++){
		if(B[make_pair(O[i], T[i])]) continue; 
		ans += max(M[make_pair(O[i], T[i])], M[make_pair(T[i], O[i])]); 
		B[make_pair(O[i], T[i])] = true; 
		B[make_pair(T[i], O[i])] = true; 
	}
	cout << ans << endl; 
}

