const ll MAX = 1e10;

ll nijo(ll x) {
    ll ng = 0;
    ll ok = 100000;
    while (ok-ng > 1) {
        ll mid = (ok+ng)/2;
        if (mid*mid >= x) ok = mid;
        else ng = mid;
    }
    if (ok*ok==x) return ok;
    return -1;
}

ll mul(ll x, ll y) {
    if (x==0 or y==0) return 0;
    if ((MAX+1)/y < x) return MAX+1;
    return x*y;
}

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int N; cin>> N;
    vector<ll> A(N);
    rep(i,N) cin >> A[i];

    map<ll,ll>cnt,P,check;
    rep(i,N) {
        ll p = 1, q = 1;
        for (ll j = 2; j*j*j <= MAX; j++) {
            ll m = j*j*j;
            while (A[i]%m==0) A[i] /= m;
            if (A[i]%(j*j)==0) {
                p *= j*j;
                q = mul(q,j);
                A[i] /= j*j;
            }
            else if (A[i]%j==0) {
                p *= j;
                q = mul(q,j*j);
                A[i] /= j;
            }
            if (A[i]==1) break;
        }
        if (A[i] != 1) {
            p *= A[i];
            ll val = nijo(A[i]);
            if (val==-1) q = mul(q,A[i]*A[i]);
            else q = mul(q,val);
        }
       cnt[p]++;
       P[p] = q;

    }
    int ans = 0;
    for (auto i :cnt) {
        if (check[i.first]) continue;
        check[i.first] = 1;
        if (i.first==1) {
            ans++;
            continue;
        }
        ll q = P[i.first];
        if (q==MAX+1 or !cnt.count(q)) ans += i.second;
        else {
            check[q] = 1;
            ans += max(i.second,cnt[q]);
        }
    }

    cout << ans << ln;
}

