    	ll o = 1;
    	for (int j = 0;j < P.size();j++) {
    		if (crt % P[j] != 0) continue;
    		int ct = 0;
    		while (crt % P[j] == 0) {
    			ct++;
    			crt /= P[j];
    		}
    		if (ct % 3 == 1) {
    			rem *= P[j];
    			o *= P[j] * P[j];
    		}
    		else if (ct % 3 == 2) {
    			rem *= P[j] * P[j];
    			o *= P[j];
    		}
    	}
    	B[i] = rem;
    	C[i] = o;
