    		H[o] = rem;
    	}
    	else {
    		if (sq(D[i])) {
    			ll a = sqrt(D[i]);
				while (a * a < D[i]) a++;
				while (a * a > D[i]) a--;
				G[D[i] * rem]++;
				H[D[i] * rem] = o * a;
				H[o * a] = D[i] * rem;
    		}
    		else {
    			if (D[i] > 1E5 || D[i] * D[i] > 1E12 / o) {
    				res++;
    			}
    			else {
    				G[D[i] * rem]++;
    				H[D[i] * rem] = o * D[i] * D[i];
    				H[o * D[i] * D[i]] = D[i] * rem;
    			}
    		}
    	}
    }
    if (ok == 1) res++;
