    	}
    	else {
    		ll a = it->second;
    		ll b = G[o];
    		if (a > b) res += a;
    		if (a == b) tmp += a; 
    	}
    }
    res += tmp / 2;
    cout << res << endl;
    return 0;
}

#include <iostream>
