using namespace std;

const int kMax = 2200;
const int kMaxPr = 500;
const double eps = 1e-12;

bitset < kMax > used;
void Init(vector < int > &prime) {

  int index = 0;
  for (int pr = 2; pr < kMax; pr ++) {
    if (used[pr]) {
      continue;
    }
    prime[++ index] = pr;

    for (int j = pr * 2; j < kMax; j += pr) {
      used[j] = true;
    }
  }

  prime[0] = index;
}

int main(int argc, char const *argv[]) {

  vector < int > prime(kMaxPr);
  Init(prime);

  int n;
  cin >> n;

  map < long long, long long > hash;
  map < long long, long long > comp;
  vector < long long > element(n + 1);

  hash[1] = 1;
  comp[1] = 1;
  for (int i = 1; i <= n; i ++) {
    cin >> element[i];
    long long k = element[i];
    hash[k] = 1ll;
    comp[k] = 1ll;

    if (k == 1ll) {
      continue;
    }

    for (int j = 1; j <= prime[0] and k != 1 and prime[j] <= k; j ++) {
      if (k % prime[j] != 0) {
        continue;
      }

      int elExp = 0;
      while (k % prime[j] == 0) {
        elExp ++;
        k /= prime[j];
      }

      elExp %= 3;
      if (elExp == 0) {
        continue;
      }

      if (elExp == 1) {
        hash[element[i]] *= 1ll * prime[j];
        comp[element[i]] *= 1ll * prime[j] * prime[j];
      }
      else {
        hash[element[i]] *= 1ll * prime[j] * prime[j];  
        comp[element[i]] *= 1ll * prime[j];
      }
    }

    if (k != 1) {
      hash[element[i]] *= 1ll * k;
      long long sq_root = floor(sqrt(k));
      if (sq_root * sq_root == k) {
        comp[element[i]] *= 1ll * sq_root;
      }
      else if (k > 1e5) {
        comp[element[i]] = 0;
      }
      else {
        comp[element[i]] *= 1ll * k * k;        
      }
    }
  }

  map < long long, int > frecv;
  for (int i = 1; i <= n; i ++) {
    frecv[hash[element[i]]] ++;
  }

  int to_remove = 0;
  for (auto &x : frecv) {
    long long k = x.first;
    int c = frecv[comp[k]];

    if (x.second == 0 or c == 0) {
      continue;
    }

    if (x.first == 1) {
      to_remove += x.second - 1;
      x.second = 0;
      continue;
    }

    to_remove += min(x.second, c);
    frecv[comp[k]] = 0;
    frecv[k] = 0;
  }
  cout << n - to_remove << '\n';
}

