const long long N = 1e10;

int n, ans;
vector<LL> primes;
map<PLL,int> num;
map<LL,int> square;

int main() {
	scanf("%d", &n);
	for (int i = 2; 1LL * i * i * i < N; i++) {
        bool flag = 0;
        for (int j = 0; j < primes.size() && primes[j] * primes[j] < i; j++) {
            if (i%primes[j] == 0) { flag = 1; break; }
        }
        if (!flag) primes.push_back(i), square[1LL*i*i] = 1;
	}

	while(n--) {
        LL x, v1 = 1, v2 = 1;
        scanf("%lld", &x);
