            while (x%primes[i] == 0) x /= primes[i], c++;
            c %= 3;
            if (c == 1) v1 *= primes[i] * primes[i], v2 *= primes[i];
            else if (c == 2) v1 *= primes[i], v2 *= primes[i] * primes[i];
        }
        if (square.count(x) == 1) v1 *= x * x, v2 *= x;
        else v1 *= x, v2 *= x * x;
        num[{v1,v2}]++;
	}

    while (!num.empty()) {
        pair<PLL,int> top = *num.begin();
