unordered_map<long, long> isp;
unordered_map<long, long> isps;

void addp() {
    for (long i = 3; i * i * i <= 1e10; i+=2) {
        bool fl = true;
        for (long p: primes) {
            if (i % p == 0) fl = false;
        }
        if (fl) primes.push_back(i);
    }
}

void addpl() {
    primesl[0] = 0;
    primesl[1] = 0;
    for (int i = 2; i < 100000; i++) {
        if (!primesl[i]) continue;
        for (int j = 2; i * j < 100000; j++) {
            primesl[i * j] = 0;
        }
    }

    for (int i = 2; i < 100000; i++) {
        if (primesl[i]) {
            long p = i;
            isp[p] = true;
            isps[p * p] = true;
        }
    }
}

long red(long s) {
    for (long p: primes) {
        while (s % (p * p * p) == 0) {
            s /= p * p * p;
        }
    }
    return s;
}

long findp(long s) {
    for (long p: primes) {
        while (s % p == 0) {
            s /= p;
        }
    }
    return s;
}

long brv(long s) {
    long ans = 1;
    for (long p: primes) {
        if (s % (p * p) == 0) {
            ans *= p;
        } else if (s % p == 0) {
            if (double(ans) * p * p > 1e10) return -1;
            ans *= p * p;
        }
        if (ans > 1e10) return -1;
    }
    return ans;
}

long opp(long s) {
    long p = findp(s);
    long b = s / p;
    long br = brv(b);
    if (br == -1) return -1;

    if (p == 1) return br;
    if (isp[p]) {
        if (double(br) * p * p > 1e10) return -1;
        return br * p * p;
    }
    if (isps[p]) {
        if (double(br) * sqrt(p) > 1e10) return -1;
        return br * long(sqrt(p));
    }
    return -1;
}

unordered_map<long, long> m;

int main() {
    addp();
    addpl();
    bool hasOne = false;
    int n;
    cin >> n;
    REP(i,n) {
        long a;
        cin >> a;
        a = red(a);
        if (a == 1) hasOne = true;
        else m[a]++;
    }

    long ans = 0;
    for (auto i = m.begin(); i != m.end(); i++) {
        if (i->second == 0) continue;
        long op = opp(i->first);
        if (op == -1) {
            ans += i->second;
            i->second = 0;
        } else {
            ans += max(i->second, m[op]);
            i->second = 0;
            m[op] = 0;
        }
    }
    cout << ans + hasOne << endl;
}

#include <bits/stdc++.h>

using ll = long long;

const int max_N = 1e5 + 21;

int n,ans;

bool vis[max_N];

std::vector<int>pri;

std::map<ll,int>Norm,Pair;

std::vector<ll>tmp;

inline void jzp(int n){
	for(int x=2;x<=n;++x){
		if(!vis[x])pri.push_back(x);
		for(auto&y:pri){
			if((ll)x*y>n)break;
			vis[x*y]=1;
			if(!(x%y))break;
		}
	}
}

inline void get_norm(ll x){
	for(auto&y:pri){
		ll z=1ll*y*y*y;
		if(z>x)break;
		while(!(x%z))x/=z;
	}
	if(++Norm[x]==1)
		tmp.push_back(x);
}

inline bool get_pair(__int128 x){
	__int128 res=1;
	for(auto&y:pri){
		__int128 z=(__int128)y*y*y;
		if(z<=x){
			while(!(x%z))x/=z;
			if(!(x%(y*y))){
				res*=y;
				x/=(y*y);
			}
			else if(!(x%y)){
				res*=(y*y);
				x/=y;
			}
		}
		else{
			__int128 w=(__int128)y*y;
			if(w>x){
				res*=(__int128)x*x;
				break;
			}
			else if(!(x%y)){
				if(x==w)res*=y;
				else res*=(__int128)x*x;
				break;
			}
		}
	}
	if(res>1e10){ans+=2; return 0;}
	if(++Pair[(ll)res]==1)
		tmp.push_back((ll)res);
	return 1;
}

int main(){
	jzp(1e5);
	scanf("%d",&n);
	while(n--){
		ll s;
		scanf("%lld",&s);
		if(get_pair(s))get_norm(s);
	}
	std::sort(tmp.begin(),tmp.end());
	tmp.erase(std::unique(tmp.begin(),tmp.end()),tmp.end());
	for(auto&x:tmp)
		if(x!=1){
			ans+=std::max(Norm[x],Pair[x]);
		}
	assert(~ans&1),ans>>=1;
	if(tmp[0]==1)++ans;
	printf("%d\n",ans);
	return 0;
}

