int prime[10000], top = 0;
int not_prime[MAXN];

void get_prime(int n)
{
	for (int i = 2; i <= n; i++) {
		if (!not_prime[i]) prime[++top] = i;
		for (int j = 1; j <= top && prime[j]*i <= n; j++) {
			not_prime[i*prime[j]] = 1;
			if (i%prime[j] == 0)
				break;
		}
	}
}

int n;
long long a[MAXN];
int powd[MAXN];
const int S = 1911589;

struct node {
	long long to;
	int next;
	int id;
} edge[MAXN*2];
int head[S], tot = 0;
inline void push(long long val, int id)
{
	int to = val%S;
	edge[++tot] = (node) {val, head[to], id}, head[to] = tot;
}
inline void visit(long long val, int i)
{
	int nd = val%S;
	for (register int i = head[nd]; i; i = edge[i].next) {
		long long to = edge[i].to;
		int id = edge[i].id;
		if (to == val)
			powd[id] = max(powd[id], i);
	}
}

pair<long long, long long> v;
map<pair<long long, long long>, int> stx, sty;

int main()
{
	get_prime(MAXM-1);
	ios::sync_with_stdio(false);
	cin >> n;
	for (int i = 1; i <= n; i++) {
		cin >> a[i];
		powd[i] = 1;
		for (int j = 1; j <= top; j++) {
			long long cur = (long long)prime[j]*prime[j]*prime[j];
			if (cur > a[i]) break;
			while (a[i]%cur == 0)
				a[i] /= cur;
		}
	}
	int B = 1300;
	for (register int i = 1; i <= B; i++)
		for (register int j = 1; j <= n; j++)
			if (a[j] % (i*i) == 0) 
				powd[j] = max(powd[j], i);
	for (register int i = B+1; i <= 100000; i++) {
		long long v = (long long)i*i;
		for (register long long j = v; j <= 10000000000; j += v)
			visit(j, i);
	}
	int cnt = 0;
	for (register int i = 1; i <= n; i++) {
		// cerr << powd[i] << " " << a[i] << endl;
		if (a[i] == 1) cnt = 1;
		else {
			auto v = make_pair(a[i]/powd[i]/powd[i], powd[i]);
			if (v.first < v.second) 
				stx[v]++;
			else sty[v]++, stx[make_pair(v.second, v.first)] = 0;
		}
	}
	for (register auto j : stx)
		cnt += max(j.second, sty[make_pair(j.first.second, j.first.first)]);
	cout << cnt << endl;
	return 0;
}

