LLI mult(LLI a,LLI b,LLI m) {
    LLI r = 0;
    while (b > 0) {
        if (b & 1) {
            r += a;
            if (r >= m) r -= m;
        }
        b >>= 1;
        a += a;
        if (a >= m) a -= m;
    }
    return r;
}
LLI modPow(LLI b,LLI e,LLI m) {
    LLI r = 1;
    while (e > 0) {
        if (e & 1) r = mult(r,b,m);
        e >>= 1;
        b = mult(b,b,m);
    }
    return r;
}
LLI gcd(LLI a,LLI b) {
    LLI t;
    while (a > 0) t = b % a,b = a,a = t;
    return b;
}
LLI millertest(LLI a,LLI n) {
    if (a > n-2) return 1;
    LLI d = n-1;
    int r,s = 0;
    while (!(d & 1)) d >>= 1,s++;
    LLI x = modPow(a,d,n);
    if ((x == 1) || (x == n-1)) return 1;
    for (r = 0; r < s-1; r++) {
        x = mult(x,x,n);
        if (x == 1) return 0;
        else if (x == n-1) return 1;
    }
    return 0;
}
int isPrime(LLI n) {
    if (n <= 1) return 0;
    else if (n <= 3) return 1;
    else if (!(n & 1)) return 0;
    if (!millertest(2,n)) return 0;
    if (!millertest(3,n)) return 0;
    if (!millertest(5,n)) return 0;
    if (!millertest(7,n)) return 0;
    if (!millertest(11,n)) return 0;
    if (!millertest(13,n)) return 0;
    if (!millertest(17,n)) return 0;
    if (!millertest(19,n)) return 0;
    if (!millertest(23,n)) return 0;
    if (!millertest(29,n)) return 0;
    if (!millertest(31,n)) return 0;
    if (!millertest(37,n)) return 0;
    return 1;
}
LLI findFactor(LLI n) {
    if (isPrime(n)) return n;
    LLI q = sqrt(n)+1e-9;
    if (q*q == n) return q;
    else q = max((LLI) (sqrt(q)+1e-9),64LL);
    int i,c = 2;
    LLI x,y;
    int s = 2;
    while (1) {
        i = 0,c = 2;
        x = y = s;
        while (1) {
            x = (mult(x,x,n)+1) % n;
            LLI d = gcd(abs(x-y),n);
            if ((d != 1) && (d != n)) return d;
            i++;
            if (i == c) y = x,c <<= 1;
            if (c > q) break;
        }
        s++;
    }
    return n;
}
vector<LLI> f;
LLI factor(LLI n) {
    LLI d = findFactor(n);
    if (d == n) f.push_back(n);
    else factor(d),factor(n/d);
    return 0;
}

