#define TOOMUCH 10000000000

int main(int,char**) {
    ios_base::sync_with_stdio(false);

    vector<bool> E(100000,true); E[0]=E[1]=false;
    vector<ll> PC;
    vector<int> P;
    for (int i = 2; i < 100000; i++) {
        if (E[i]) {
            for (ll j = (ll)i*i; j < 100000; j+=i) {
                E[j] = false;
            }
            if (i < 2500)
                PC.push_back((ll)i*i*i);
            P.push_back(i);
        }
    }

    int N;
    scanf("%d", &N);
    vector<ll> S(N);
    for(auto&s:S) scanf("%lld", &s);
    for(auto&s:S) for (auto&p:PC) while (s%p==0) s/=p;

    map<ll,int> C;
    for(auto&s:S) C[s]++;

    int ans = 0;
    for(auto iter = C.begin(); iter != C.end(); ++iter) {
        ll a = iter->x;
        if (a==1) { ans += 1; continue; }
        ll b = 1;
        for (auto &p: P) {
            if (a == 1) break;
            if (a % p==0) {
                if (b * p > TOOMUCH) { b = -1; break; }
                b *= p;
                a /= p;
                if (a % p == 0) {
                    a /= p;
                } else {
                    if (b * p > TOOMUCH) { b = -1; break; }
                    b *= p;
                }
            }
            if ((ll)p*p>a) break;
        }
        if (a != 1 && b != -1) {
            if (b * a < b) { b = -1; }
            else {
                b *= a;
                if (b * a < b) { b=-1; }
                else b *= a;
            }
        }

        auto bi = C.find(b);
        if (bi == C.end()) {
            ans += iter->y;
        } else if (bi->y < iter->y) {
            ans += iter->y;
        } else if (bi->y == iter->y && iter->x < b) {
            ans += iter->y;
        }
    }
    cout << ans << endl;
}

