const long long MAX = 10000000000LL;

int main()
{
    int n;
    cin >> n;

    map<long long, long long> square;
    for(long long i=2; i*i<=MAX; ++i)
        square[i*i] = i;

    map<map<long long, int>, int> m;
    for(int i=0; i<n; ++i){
        long long a;
        cin >> a;

        map<long long, int> x;
        for(long long j=2; j*j*j<=a; ++j){
            int cnt = 0;
            while(a % j == 0){
                a /= j;
                cnt = (cnt + 1) % 3;
            }
            if(cnt != 0)
                x[j] = cnt;
        }

        if(a > 1){
            if(square.find(a) != square.end())
                x[square[a]] = 2;
            else
                x[a] = 1;
        }

        ++ m[x];
    }

    int ans = 0;
    for(const auto& p : m){
        map<long long, int> x = p.first;
        if(x.size() == 0){
            ++ ans;
            continue;
        }
        if(x.begin()->second == 2)
            continue;

        for(auto& a : x)
            a.second = 3 - a.second;

        if(m.find(x) == m.end())
            ans += p.second;
        else
            ans += max(p.second, m[x]);
    }
    cout << ans << endl;

    return 0;
}

