std::vector<int> prime;
void MakePrime(int n) {
	prime.emplace_back(2);
	for (int i = 3; i < n; i += 2) {
		bool a = false;
		for (int j = 3; j <= std::sqrt(i); j += 2) {
			if (i%j == 0) {
				a = true;
			}
		}
		if (a == false) {
			prime.emplace_back(i);
		}
	}
}

LL calc_opponent(LL x){
    LL ret = 1;
    for(auto p : prime){
        LL cnt = 0;
        while(x % p == 0) ++cnt, x /= p;
        if(cnt == 0)continue;
        else if(cnt == 1)ret *= p * p;
        else ret *= p;
    }
    LL l = 1, r = 1000000LL;
    while(r - l > 1){
        LL mid = (l + r)/2;
        if(mid * mid > x)r = mid;
        else l = mid;
    }
    if(l * l == x){
        ret *= l;
    }else{
        if(x > 1000000LL)return -1;
        ret *= x * x;
        if(ret > 10000000000LL)return -1;
    }
    return ret;
}

