const int N = (int)1e5 + 5;
const long THR = (long)1e5 + 5;
const long MXF = 2160;
const long MX = (long)1e10;

int n;
long a[N];
map<long, pair<int, int>> mp;

int main() {

	scanf("%d", &n);

	for (int i = 0; i < n; i++) {
		scanf("%lld", a + i);
	}

	for (int i = 0; i < n; i++) {
		long cur = 1, op = 1;
		for (long j = 2; j * j <= a[i] and j < MXF; j++) {
			int cnt = 0;
			while (a[i] % j == 0) {
				cnt++; a[i] /= j;
			}
			cnt %= 3;
			if (cnt == 1) cur *= j, op *= j * j;
			else if (cnt == 2) cur *= j * j, op *= j;
			if (op > MX) op = 0;
		}
		long sq = (long)sqrt(a[i]);
		if (sq * sq == a[i]) cur *= a[i], op *= sq;
		else if ((sq + 1) * (sq + 1) == a[i]) cur *= a[i], op *= sq + 1;
		else cur *= a[i], op *= (a[i] < THR ? a[i] * a[i] : 0);
		if (cur < op or op == 0) mp[cur].first++;
		else if (cur > op) mp[op].second++;
		else mp[cur] = make_pair(1, 0);
		// printf("%lld %lld\n", cur, op);
	}

	int ans = 0;
	for (auto p : mp) {
		// printf("we got %lld got %d %d\n", p.first, p.second.first, p.second.second);
