			ori*=tmp;
		}
		else if(tmp*tmp<(1e18/rev))
		{
			ori*=tmp;
			rev*=tmp*tmp;
		}
		else
		{
			ori*=tmp;
			rev=-1;
		}
		con[ori]=rev;
		num[ori]++;

	}
