const int MAX_S = 10000000000;

int div3(int x) {
	for (int i = 2; i * i * i <= MAX_S; ++i) {
		int t = i * i * i;
		if (x < t) break;
		while (x%t == 0) x /= t;
	}
	return x;
}

int inv(int x) {
	return div3(x * x);
}

signed main() {
	INIT;
	VAR(int, n);
	VEC(int, s, n);
	std::map<int, int> cnt;
	REP(i, n) {
		s[i] = div3(s[i]);
		++cnt[s[i]];
	}
	int ans = 0;
	if (cnt[1] > 0) cnt[1] = 1;
	for (auto x : cnt) {
		int t = inv(x.first);
		if (cnt.count(t)) {
			ans += std::max(x.second, cnt[t]);
			cnt[x.first] = 0;
			cnt[t] = 0;
		}
		else {
			ans += x.second;
		}
	}
	OUT(ans)BR;
	return 0;
}

