void get1(ll s)
{
    ll i,j,k,l;
    x=y=1;
    for(i=0;i<v.size()&&v[i]<lim;i++)
    {
        k=0;
        ll u=v[i];
        while(s%u==0)
        {
            s/=u;
            k++;
            k%=3;
        }
        l=(3-k)%3;
        while(k--) x*=u;
        while(l--) y*=u;
    }

    if(s!=1)
    {
        if(sqr[s])
        {
            x*=s;
            y*=root[s];
        }
        else
        {
            x*=s;
            y*=s*s;
        }
    }
}

