map<long long, pair<int, int> > freq;

// <x after dividing it by all its cubic divisors, the one that pairs with newx>
pair<long long, long long> lulw(long long x) {
	long long y = 1, z = 1;
	for(int i = 0; i < cnt; ++ i) {
		if(1ll * primes[i] * primes[i] > x) break;
		if(x % primes[i]) continue;

		int cur = 0;
		while(x % primes[i] == 0) ++ cur, x /= primes[i];

		cur %= 3;
		for(int j = 0; j < cur; ++ j) z *= primes[i];
		for(int j = cur; j < 3; ++ j) y *= primes[i];
	}

	if(x > 1) y *= x * x, z *= x;
	return make_pair(z, y);
}

