		primes[cnt ++] = i;
		for(long long j = 1ll * i * i; j < N; j += i) ok[j] = 1;
	}

	iostream::sync_with_stdio(false);

	cin >> n;
	for(int i = 0; i < n; ++ i) {
		long long a; cin >> a;

		auto cur = lulw(a);
		if(cur.first < cur.second) ++ freq[cur.first].first;
			else ++ freq[cur.second].second;
	}

	int Ans = 0;
	for(auto it = freq.begin(); it != freq.end(); ++ it) {
		if(it->first == 1) ++ Ans;
			else Ans += max(it->second.first, it->second.second);
	}
	cout << Ans << '\n';
}

