struct Miller {
	const int v[7] = { 2,3,5,7,11,13,17 };
	bool check(int n) {
		if (n<2)return false;
		if (n != 2 && !(n & 1))return false;
		int d = n - 1;
		int s = 0;
		while (d % 2) {
			d /= 2; s++;
		}
		for (int a : v) {
			if (a == n)return true;
			if (modpow(a, d, n) != 1) {
				bool ok = true;
				rep(r, s) {
					if (modpow(a, d*(1ll << r), n) == n - 1) {
						ok = false; break;
					}
				}
				if (ok)return false;
			}
		}
		return true;
	}
};
struct Rho {
	mt19937 mt;
	Miller miller;
	int c;
	Rho() {
		mt.seed(clock());
	}
	inline int f(int x, int n) {
		return (x*x + c) % n;
	}
	int check(int n) {
		if (n == 4)return 2;
		c = mt() % n;
		int x = mt() % n;
		int y = x;
		int d = 1;
		while (d == 1) {
			x = f(x, n);
			y = f(f(y, n), n);
			d = gcd(abs(x - y), n);
		}
		if (d == n)return -1;
		return d;
	}
	vector<int>factor(int n) {
		if (n <= 1)return {};
		if (miller.check(n))return { n };
		int res = -1;
		while (res == -1) {
			res = check(n);
		}
		vector<int>fa = factor(res);
		vector<int>fb = factor(n / res);
		fa.insert(fa.end(), fb.begin(), fb.end());
		return fa;
	}
};
