bitset < kMax > used;

void Init(vector < int > &prime) {

  int index = 0;
  for (int pr = 2; pr < kMax; pr ++) {
    if (used[pr]) {
      continue;
    }
    prime[++ index] = pr;

    for (int j = pr * 2; j < kMax; j += pr) {
      used[j] = true;
    }
  }

  prime[0] = index;
}

