      while (k % prime[j] == 0) {
        elExp ++;
        k /= prime[j];
      }

      elExp %= 3;
      if (elExp == 0) {
        continue;
      }

      if (elExp == 1) {
        hash[element[i]] *= 1ll * prime[j];
        comp[element[i]] *= 1ll * prime[j] * prime[j];
      }
      else {
        hash[element[i]] *= 1ll * prime[j] * prime[j];  
        comp[element[i]] *= 1ll * prime[j];
      }
    }

    if (k != 1) {
      hash[element[i]] *= 1ll * k * k;
      comp[element[i]] *= 1ll * k;
    }
  }


  map < long long, int > frecv;
  for (int i = 1; i <= n; i ++) {
    frecv[hash[element[i]]] ++;
  }

  int to_remove = 0;
  for (auto x : frecv) {
    if (x.second == 0) {
      continue;
    }

    if (x.first == 1) {
      to_remove += x.second - 1;
      x.second = 0;
      continue;
    }

    int k = x.first;
    int c = frecv[comp[k]];
    if (c == 0) {
      continue;
    }

    if (x.second >= c) {
      to_remove += c;
    }
    else {
      to_remove += x.second;
    }
    frecv[comp[k]] = 0;
  }

  cout << n - to_remove << '\n';
}

