int Mod(int x, int p) {
	x %= p;
	while (x < 0) x += p;
	return x;
}

pii Hash(int n) {
	int N = n;
	int res = 1, rev = 1;
	for (int p: primes) {
		if (p > cbrt(n)) break;
		int a = 0;
		while (n % p == 0) n /= p, a++;
		res *= power(p, Mod(a, 3));
		if (a % 3 != 0) rev *= power(p, Mod(3 - a, 3));
		if (n == 1) break; 
	}
	if (n > 1e5) res = n, rev = n;
	if (n > 1) {
		if (sqrt(n) == (int)sqrt(n)) res *= n, rev *= (int)sqrt(n);
		else res *= n, rev *= n * n;
	}
	return mp(res, rev);
}

