void solve()
{
    //gen(100000);
    //return;
    int n;
    cin >> n;
    vector<LL> s(n);
    REP(i, n) {
        cin >> s[i];
    }
    auto primes = genPrimes(MAXP + 10);
    unordered_map<LL, int> counts;
    unordered_map<LL, LL> antiMap;
    int ans = 0;
    REP(i, n) {
        LL pattern = 1;
        LL antiPattern = 1;
        for (int p : primes) {
            int cnt = 0;
            while (s[i] % p == 0) {
                ++cnt;
                s[i] /= p;
            }
            cnt %= 3;
            pattern *= myPow(p, cnt);
            antiPattern *= myPow(p, (3 - cnt) % 3);
            assert(pattern > 0);
            assert(antiPattern > 0);
            if (antiPattern > MAXPATTERN) {
                break;
            }

            if (s[i] == 1) {
                break;
            }
            if (p > 2200) {
               LL x = sqrtl(s[i]) - 10;
                while (x * x < s[i]) {
                    ++x;
                }
                if (x * x == s[i]) {
                    pattern *= myPow(x, 2);
                    antiPattern *= myPow(x, 1);
                    s[i] /= x * x;
                }
                break;
            }
        }
        if (s[i] != 1) {
            ++ans;
        } else {
            assert(pattern > 0);
            assert(antiPattern > 0);
            ++counts[pattern];
            assert(antiMap[pattern] == 0 || antiMap[pattern] == antiPattern);
            assert(antiMap[antiPattern] == 0 || antiMap[antiPattern] == pattern);
            antiMap[pattern] = antiPattern;
            antiMap[antiPattern] = pattern;
        }
    }
    for (const auto& p : antiMap) {
        auto pattern = p.first;
        auto antiPattern = p.second;
        if (pattern > antiPattern) {
            continue;
        }

        if (pattern == antiPattern) {
            ans += min(counts[pattern], 1);
        } else {
            ans += max(counts[pattern], counts[antiPattern]);
        }
    }
    cout << ans << endl;
}

