ll tg(ll x){
	ll a=1,b=1;
	for(ll i=2;;i++){
		if(i*i*i>x)break;
		int cnt=0;
		while(x%i==0){
			x/=i;
			cnt++;
		}
		if(cnt==1)a*=i;
		else if(cnt==2)b*=i;
	}
	ll dt=(ll)floor(sqrt(x)+0.5);
	if(dt*dt==x)b*=dt;
	else a*=x;
	ll res=a*b;
	if(res>INF/a+1)res=INF;
	else res*=a;
	return res;
}


