numtype normalize(long long x){
	long long p=1,q=1;
	for(long long d=2;d*d<=x;d++){
		int cnt=0;
		for(;x%d==0;){x/=d;cnt++;}
		if(cnt%3==1)p*=d;
		if(cnt%3==2)q*=d;
	}
	if(x>1)p*=x;
	return make_pair(p,q);
}

numtype inv(numtype x){
	return make_pair(x.second,x.first);
}

