LL mul(LL b, LL e, LL m)
{
	b %= m;
	e %= m;
	LL t = b * e - LL((long double)b * e / m) * m;
	while (t < 0) t += m;
	while (t >= m) t -= m;
	return t;
}

LL Fpm(LL b, LL e, LL m)
{
	LL t = 1;
	for ( ; e; e >>= 1, b = mul(b, b, m))
		if (e & 1) t = mul(t, b, m);
	return t;
}

bool witness(int a, LL b)
{
	if (a == b) return 1;
	LL s = b - 1;
	int cnt = 0;
	while (!(s & 1)) s >>= 1, ++cnt;
	LL tmp = Fpm(a, s, b);
	if (tmp == 1) return 1;
	while (cnt)
	{
		if (tmp == b - 1) return 1;
		--cnt;
		tmp = mul(tmp, tmp, b);
		if (tmp == 1) return 0;
	}
	return 0;
}

