inline void rho(LL x)
{
	if (isprime(x))
	{
		all.insert(x);
		return;
	}
	if (x <= 100000000)
	{
		for (int i = 2; i * i <= x; ++i)
		{
			if (!(x % i)) all.insert(i);
			while (!(x % i)) x /= i;
		}
		if (x > 1) all.insert(x);
		return;
	}
	while (1)
	{
		LL x0 = 0, x1 = 0;
		int c = Rand();
		LL d = 1;
		int cnt = 0;
		while (d == 1)
		{
			x0 = mul(x0, x0, x);
			(x0 += c) %= x;
			d = __gcd(abs(x0 - x1), x);
			++cnt;
			if (!(cnt & (cnt - 1))) x1 = x0;
		}
		if (d != x)
		{
			rho(d);
			rho(x / d);
			break;
		}
	}
}

