pair <long long, long long> create(long long numar)
{
	long long ans=1;
	long long inv=1;
	long double logInv = 0;
	bool ok = true;
	for(int i=1;i<=prime[0]&&1ll*prime[i]*prime[i]<=numar&&numar>1;i++)
	{
		if(numar%prime[i]==0)
		{
			int power=0;
			while(numar%prime[i]==0)
			{
				power++;
				numar/=prime[i];
			}
			power=power%3;
			if(power==0) continue;
			if(power==1) {
				ans=ans*prime[i];
				if (ok) {
					inv = inv * prime[i] * prime[i];
					logInv += log2(prime[i] * prime[i]);
					if (logInv > 33.5) ok = false;
				}
			}
			else if(power==2) {
				ans=ans*(prime[i]*prime[i]);
				if (ok) {
					inv = inv * prime[i];
					logInv += log2(prime[i]);
					if (logInv > 33.5) ok = false;
				}
			}
		}
	}
	ans=ans*numar;
	inv = inv * numar * numar;
	logInv += log2(numar * numar);
	if (logInv > 33.5) ok = false;
	if (ok)
		return {ans, inv};
	return {ans, -1};
}

