ll a[N],bs[N];
int is[M],pri[M];
int n,ans,tot,tp;
bool t1=false;

map <ll,int> mp;

inline ll pw3(ll x){return x*x*x;}

inline ll f(ll x){
	ll res(1ll);
	for(int i=1;i<=tp&&pri[i]<=x;++i){
		int t=0;
		while(x%pri[i]==0)
			x/=pri[i],++t;
		if(t==1)res*=pri[i]*pri[i];
		else if(t==2)res*=pri[i];
	}
	if(x==1)return res;
	ll sqr=sqrt(x);
	if(sqr*sqr==x)return res*sqr;
	else if(res*x*x<=MX)return res*x*x;
	else return -1;
}

int main(){
