	IL bool Miller_Rabin(ll n){
		if((n%6)!=1&&(n%6)!=5) return false;
		mod=n;
		rep(i,0,8)if(n%pri[i]==0)return n==pri[i];
		ll r,t;
		for(r=n-1,t=0;~r&1;r>>=1,++t);
		rep(i,0,8){
			ll x=fpw(pri[i],r);
			for(int j=0;j<t&&x>1;++j){
				ll y=mul(x,x);
				if(y==1&&x!=n-1)return false;
				x=y;
			}
			if(x!=1)return false;
		}
		return true;
	}
	IL ll gcd(ll x,ll y){return !y?x:gcd(y,x%y);}
	IL ll func(ll x,ll a){return pls(mul(x,x),a);}
	IL ll Find(ll n,ll c){
		ll x=rand()%n+1, y=x, k=2;
		for(int i=1;;i++) {
			x=(mul(x,x)+c)%n;
			ll p=gcd(abs(y-x),n);
			if(p!=1) return p;
			if(i==k) k<<=1, y=x;
		}
	}
	IL void Pollard_Rho(ll n,vector<ll>&D){
		if(n==1||Miller_Rabin(n)){if(n!=1)D.pb(n);return;}
		ll d=n;while(d==n)d=Find(n,rand()%n);
		Pollard_Rho(n/d,D);Pollard_Rho(d,D);
	}
}
