inline ll ABS(ll a){return max(a, -a);}
inline ll gcd(ll a, ll b){return b?gcd(b, a%b):a;}
inline ll mul(ll a, ll b, ll p){
	ll x=(ld)a/p*b+1e-3;
	return ((a*b-x*p)%p+p)%p;
}
inline ll pow(ll y, ll x, ll p){
	ll s=1, t=y;
	while(x){if(x&1)s=mul(s, t, p); t=mul(t, t, p); x>>=1;}
	return s;
}
inline int check_p(ll a, ll r, ll sum, ll n){
	ll x=pow(a, r, n), now=x;
	for(int i=1; i<=sum; i++){
		x=mul(x, x, n);
		if(x==1&&now!=1&&now!=n-1)return 1;
		now=x;
	}
	if(x!=1)return 1;
	return 0;
}
inline int miller_rabin(ll n){
	if(n==2)return 1; if(n%2==0)return 0;
	ll r=n-1, sum=0; while(r%2==0){sum++; r>>=1;}
	for(int i=1; i<=10; i++)if(check_p(rand()%(n-1)+1, r, sum, n))return 0;
	return 1;
}
inline ll pollard_rho(ll a, ll n){
	ll k=2, x=rand()%(n-1)+1, y=x, p=1;
	for(ll i=1; p==1; i++){
		x=(mul(x, x, n)+a)%n;
		p=gcd(ABS(x-y), n);
		if(i==k){y=x; k<<=1;}
	}
	return p;
}
inline ll find_fac(ll n){
	if(n==1)return 1;
	if(miller_rabin(n))return n;
	ll t=n;
	while(t==n)t=pollard_rho(rand()%(n-1)+1, n);
	return t;
}

