ll isCube(ull x){
  double xxx = pow(x, 1.0/3);
  for(ll i=-3; i<=3; i++){
    ll y = (ll)xxx + i;
    if(y*y*y == (ll)x) return true;
  }
  return false;
}

ll calc(ull x, const vector<ull> y){
  int n = y.size();
  vector< vector<ll> > dp(2, vector<ll>(n+5, 0));
  dp[0][0] = 0;
  dp[1][0] = y[0];
  REP(i,1,n){
    dp[0][i] = max(dp[0][i-1], dp[1][i-1]);
    dp[1][i] = dp[0][i-1] + y[i];
  }
  return max(dp[0][n-1], dp[1][n-1]);
}

