typedef long long ll;
const ll INF=1LL<<50;
int n;
map<ll,int> M;
map<ll,int> cnt;
ll ans;
ll solve(ll x) {
	for (ll i=2;;i++) {
		ll t=i*i*i;
		if (t>x) break;
		while (x%t==0) x/=t;
	}
	return x;
}
ll T(ll x) {
	ll A=1,B=1;
	for (ll i=2;;i++) {
		if (i*i*i>x) break;
		int ss=0;
		while (x%i==0) {
			x/=i; ss++;
		}
		if (ss==1) A*=i; else if (ss==2) B*=i;
	}
	ll tmp=(ll)floor(sqrt(x)+0.5);
	if (tmp*tmp==x) B*=tmp;
	else A*=x;
	ll res=A*B;
	if (res>INF/A+1) res=INF; else res*=A;
	return res;
}

