	}
	ans=0;
	for (map<ll,int>::iterator it=M.begin();it!=M.end();it++) {
		ll x=it->first;
		if (cnt[x]) continue;
		ll t=T(x);
		if (x!=t) ans+=max(it->second,M[t]);
		else ans++;
		cnt[t]++;
	}
	printf("%lld\n",ans);
	return 0;
}

