typedef pair<ll, int> pli;
vi prime;
int ans = 0;
map<vector<pli>, int> mp;

vector<pli> prime_factor(ll num) {
  vector<pli> ret;
  for (auto &p : prime) {
    int cnt = 0;
    while (num % p == 0) {
      num /= p;
      cnt++;
    }
    cnt %= 3;
    if (cnt != 0) ret.emplace_back(p, cnt);
  }
  if (num != 1) {
    ll rt = sqrtl(num);
    if (rt * rt == num) ret.emplace_back(rt, 2);
    else ret.emplace_back(num, 1);
  }
  return ret;
}

void solve() {
  int n; cin >> n;
  vl arr(n); cin >> arr;

  vb is_prime(2201, true);
  REP(i,2,2200) {
    if (is_prime[i]) {
      prime.emplace_back(i);
      for (int j=i*2; j<=2200; j+=i) {
        is_prime[j] = false;
      }
    }
  }

  for (auto &num : arr) {
    mp[prime_factor(num)]++;
  }

  auto tmp = prime_factor(1);
  if (mp.count(tmp)) {
    ans = 1;
    mp.erase(tmp);
  }

  while (!mp.empty()) {
    auto a = mp.begin();
    auto b = a->first;
    for (auto &p : b) {
      p.second = 3 - p.second;
    }
    ans += max(a->second, mp[b]);
    mp.erase(a);
    mp.erase(b);
  }

  cout << ans << endl;
}


