void divide(lint x) {
    lint rev = 1, cur = 1;
    for (int i = 1; i <= total; ++i)
        if (x % prime[i] == 0) {
            int sum = 0;
            while (x % prime[i] == 0) {
                x /= prime[i];
                ++sum;
            }
            sum %= 3;
            if (sum != 0) {
                rev = rev * power(prime[i], 3 - sum);
                cur = cur * power(prime[i], sum);
            }
        }
    if (x != 1) {
        if (x >= M) {
            if (sqrt(x) * sqrt(x) != x) {
                ++ans;
                return ;
            }
            rev = rev * sqrt(x);
            cur = cur * x;
        }
        else {
            rev = rev * x * x;
            cur = cur * x;
        }
    }
    if (rev == cur) {
        ans += !record[cur];
        record[cur] = true;
        return ;
    }
    ans -= max(record[rev], record[cur]);
    ++record[cur];
    ans += max(record[rev], record[cur]);
}

