        pd.erase(unique(pd.begin(), pd.end()), pd.end());
        for(int k = 0; k < pd.size(); ++k)
        {
            c[k] = 0; while(x%pd[k] == 0) ++c[k], x /= pd[k];
            c[k] %= 3; b[i] *= qpow(pd[k], (3-c[k])%3, 1e10);
            a[i] *= qpow(pd[k], c[k], 1e10);
        }
        ++h[a[i]];
    }
    for(int i = 1; i <= n; ++i)
    {
        if(vis[a[i]]||vis[b[i]]||a[i] == 1) continue;
        vis[a[i]] = 1; ans += max(h[a[i]], h[b[i]]);
    }
