const int MAXX=3000;
const int MAXN=100010;
map<int ,int >num;
map<int ,bool >vis;
long long prime[MAXX],v[MAXX];
int n,tot,ans;
long long a[MAXN],b[MAXN];
inline void init(){
    for(int i=2;i<=MAXX;++i){
    	if(!v[i]){
    		prime[++tot]=i;
    		v[i]=i;
    	}
    	for(int j=1;j<=tot;++j){
    		if(i*prime[j]>MAXX||v[i]<prime[j])break;
    		v[i*prime[j]]=prime[j];
    	}
    }
}
inline void solve(long long x,int pos){
	long long u=1;
	long long v=1;
    for(int i=1;i<=tot;++i){
    	if(x%prime[i]==0){
        long long cnt=0;
        while(x%prime[i]==0){
           x/=prime[i];
           cnt++;
         }
          cnt%=3;
          if(cnt==1){
          	u*=prime[i];
          	v*=prime[i]*prime[i];
          }
          if(cnt==2){
          	u*=prime[i]*prime[i];
          	v*=prime[i];
          }
       }
       if(x==1)break;
    }
    if(x>1){
    	long long t=(long long)sqrt(x);
    	u*=x;
    	if((t*t)==x)v*=t;
    	else v*=x;
    }
    a[pos]=u;
    b[pos]=v;
    num[u]++;
}
int main(){
    init();
    scanf("%d",&n);
    for(int i=1;i<=n;++i)cin>>a[i];
    for(int i=1;i<=n;++i)solve(a[i],i);
    for(int i=1;i<=n;++i){
    	if(!vis[a[i]]){
    		vis[a[i]]=1;
    		vis[b[i]]=1;
    		if(a[i]==b[i])ans++;
    		else ans+=max(num[a[i]],num[b[i]]);
    	}
    }
    cout<<ans<<endl;	
    return 0;
}

