const int N = 1e5 + 4;
const int MX = cbrt(1e10) + 4;

ll m, cube, ans;
map<vector<pll>, int> cnt;
map<vector<pll>, bool> used;

vector<ll> cubes;

bool isCube(ll x) {
    return binary_search(all(cubes), x);
}

bool pused[N];
vector<ll> prime;

void factor(ll a) {
    vector<ll> p;
    int last = 0;
    for (int i = 0; i < size(prime); ++i) {
        ll pt = prime[i];
        if (pt * pt > a || pt > MX) {
            last = i;
            break;
        }
        while (a % pt == 0) {
            p.em_back(pt);
            a /= pt;
        }
    }
    if (a > 1) {
        if (a > 1e5) {
            ll sq = sqrt(a);
            if (sq * sq == a) {
                p.em_back(sq);
                p.em_back(sq);
            } else {
                ++ans;
                return;
            }
        } else {
            p.em_back(a);
        }
    }
    sort(all(p));

    vector<pll> res;
    for (int i = 0; i < size(p);) {
        int j = i;
        while (j < size(p) && p[i] == p[j]) {
            ++j;
        }
        if ((j - i) % 3 != 0) {
            res.em_back(p[i], (j - i) % 3);
        }
        i = j;
    }
    cnt[res]++;
}

void prepare() {
    for (int i = 2; i < N; ++i) {
        if (pused[i]) {
            continue;
        }
        for (ll j = (ll)i * i; j < N; j += i) {
            pused[j] = 1;
        }
    }
    for (int i = 2; i < N; ++i) if (!pused[i]) {
        prime.em_back(i);
    }

    for (ll i = 1; i < 1e4; ++i) {
        cubes.em_back(i * i * i);
    }
}

void read() {
    cin >> m;
    for (int i = 0; i < m; ++i) {
        ll a;
        cin >> a;
        if (isCube(a)) {
            ++cube;
        } else {
            factor(a);
        }
    }
}

void solve() {
    read();

    for (auto u : cnt) {
        auto fu = u.first;

        if (used[fu]) {
            continue;
        }

        auto fv = fu;
        for (pll& p : fv) {
            p.second = 3 - p.second;
        }

        int ucnt = u.second;
        int vcnt = (cnt.count(fv) ? cnt[fu] : 0);

        ans += max(ucnt, vcnt);

        used[fu] = used[fv] = 1;
    }

    cout << ans + (cube > 0) << "\n";
}

int main() {
    ios::sync_with_stdio(0);
    cout.tie(0), cin.tie(0);

    prepare();

    int z = 1;
    /// cin >> z;

    while (z--) {
        solve();
    }

    return 0;
}

