    for (int i = 0; i < 100010; i++)
        primes[i] = 1;
    primes[0] = primes[1] = 0;
    for(int i = 2; i < 100010; i++)
    {
        if (primes[i])
            for(long long j = (long long) i * i; j < 100010; j += i)
                primes[j] = 0;
    }
    vector<long long> Primes;
    for(long long i = 2; i < 3000; i++)
        if (primes[i])
            Primes.push_back(i);

    vector<long long> SS(N), SSS(N);
    for(int i = 0; i < N; i++)
    {
        long long s = S[i];
        long long ss = 1;
        long long sss = 1;
        for ( long long prime : Primes)
        {
            if (s % prime != 0)
                continue;

            int count = 0;
            while (s % prime == 0)
            {
                count += 1;
                s /= prime;
            }
            for (int c = 0; c < count % 3; c++)
                ss *= prime;

            int num_loop = (3 - (count % 3)) % 3;
            for (int c = 0; c < num_loop; c++)
                sss *= prime;

            if (s == 1)
                break;
            // cout << s << endl;
        }

        ss *= s;

        long long p = (long long) sqrt((double) s);
        if (primes[p])
            sss *= p; 
        else 
            sss *= s * s;

        SS[i] = ss;
        SSS[i] = sss;
        // cout << S[i] << ' ' << SS[i] << ' ' << SSS[i] << endl;
    }
    map<long long, int> count;
    for (int i = 0; i < N; i++)
            count[SS[i]] += 1;

    set<long long> used;
    int ans = 0;
    for (int i = 0; i < N; i++)
    {
        if (used.count(SS[i]))
            continue;
        else if (SS[i] == 1)
        {
            ans += 1;
            used.insert(1);
        }
        else
        {
            ans += max(count[SS[i]], count[SSS[i]]);
            used.insert(SS[i]);
            used.insert(SSS[i]);
        }
    }
    cout << ans << endl;
}

