using namespace std;

int v[maxn];

vector<int> primes;
vector<bool> comp;

void sieve(int n) {
    comp.resize(n);
    for (int i = 2; i <= n; ++i) {
        if (!comp[i]) {
            primes.push_back(i);
            for (int j = i; j <= n; j += i) {
                comp[j] = true;
            }
        }
    }
}

map<conf, conf> opposite;
map<conf, int> M;
set<conf> V;

conf get_repr(long long x) {
    conf ans = 1;
    conf op = 1;
    for (int j = 0; primes[j] * primes[j] <= x && j < primes.size(); ++j) {
        int i = primes[j];
        if (x % i == 0) {
            int cnt = 0;
            do {
                x /= i;
                ++cnt;
            } while (x % i == 0);
            int rem = cnt%3;
            if (rem == 1) {
                ans *= i;
                op *= i * i;
            } else if (rem == 2) {
                ans *= i * i;
                op *= i;
            }
        }
    }
    ans *= x;
    op *= x * x;
    opposite[ans] = op;
    return ans;
}

int main()
{
    sieve(100000);
    int n;
    cin >> n;
    for (int i = 1; i <= n; ++i) {
        long long x;
        cin >> x;
        auto repr = get_repr(x);
        M[repr]++;
    }

    int ans = 0;
    for (auto& el : M) {
        auto repr = el.first;
        if (V.find(repr) != V.end()) {
            continue;
        }
        if (repr == 1) {
            ans++;
            continue;
        }
        auto op = opposite[repr];
        int val1 = el.second;
        int val2;
        if (M.find(op) != M.end()) {
            val2 = M[op];
            V.insert(op);
        } else {
            val2 = 0;
        }
        ans += max(val1, val2);
    }
    cout << ans;
}

