void sieve(){
    for(int i = 0; i < 3000; i++)
        prime[i] = 1;
    for(int i = 2; i < 3000; i++){
        if(prime[i] == 1){
            p.pb(i);
            for(int j = 2 * i; j < 3000; j += i)
                prime[j] = 0;
        }
    }
}

int main() {
    cin.tie(0), ios::sync_with_stdio(0);
    sieve();
    cin >> n;
    for(int i = 1; i <= n; i++)
        cin >> s[i];
    for(int i = 1; i <= n; i++){
        if(s[i] == 1){
            ans = 1;
            used[i] = 1;
            continue;
        }
        for(long long j = 0; j < 3000; j++){
            if(j * j * j == s[i]){
                used[i] = 1;
                ans = 1;
                break;
            }
        }
    }
    for(int i = 1; i <= n; i++){
        if(used[i]) continue;
        long long sum1 = s[i], sum2 = 1, sum3 = 1;
        for(int j = 0; j < p.size(); j++){
            if(sum1 % p[j] == 0){
                int times = 0;
                while(sum1 % p[j] == 0){
                    sum1 /= p[j];
                    times++;
                }
                times %= 3;
                for(int l = 1; l <= times; l++)
                    sum3 *= p[j];
                if(times != 0){
                    for(int l = 1; l <= 3 - times; l++)
                        sum2 *= p[j];
                }
            }
        }
        long long rem = sqrt(sum1);
        if(rem * rem == sum1) {sum3 *= rem * rem; sum2 *= rem;}
        else {sum3 *= rem; sum2 *= rem * rem;}
        s[i] = sum3;
        mymap[sum3]++;
        opp[i] = sum2;
        //cout << s[i] << " " << opp[i] << "\n";
    }
    for(int i = 1; i <= n; i++){
        if(mymap.count(s[i]) == 1){
            if(mymap[s[i]] >= mymap[opp[i]]){
                ans += mymap[s[i]];
                mymap[opp[i]] = 0;
                mymap[s[i]] = 0;
            }
        }
    }
    cout << ans << "\n";
}

