pair<lint,lint> deleteCubes(lint x)
{
    lint Val=1,reVal=1;
    for (lint i = 2; i * i <= x; i++)
        if(x%i==0)
        {
            int cnt=0;
            while(x%i==0)
            {
                cnt++;
                x/=i;
            }
            cnt%=3;
            for (int j = 0; j < cnt; j++)
                Val*=i;
            if(cnt==1 || cnt==2)            
            for (int j = 0; j < 3-cnt; j++)
                reVal*=i;
        }
    if(x>1)
    {
        int cnt=1;
        for (int j = 0; j < cnt; j++)
            Val*=x;
        if(cnt==1 || cnt==2)            
        for (int j = 0; j < 3-cnt; j++)
            reVal*=x;
    }
    return MP(Val,reVal);
}

