int main() {
    int N;
	cin >> N;

    const int MAX_P = 1e5+10;
    vector<bool> sieve(MAX_P, true);
    vll primes;
    sieve[0] = sieve[1] = false;
    REP(i, 2, MAX_P) {
        if(sieve[i]) {
            primes.push_back(i);
            for(ll j = i+i; j <= MAX_P; j += i) {
                sieve[j] = false;
            }
        }
    }


    vll ary(N);
    map<ll, int> nums;
    rep(i, N) {
        cin >> ary[i];
        tr(p, primes) {
            ll t = (*p) * (*p) * (*p);
            if(t > ary[i])
                break;
            while(ary[i] % t == 0)
                ary[i] /= t;
        }

        nums[ary[i]]++;
    }

    vll dbl_prime;
    tr(it, primes)
        dbl_prime.push_back( (*it) * (*it) );

    cerr << dbl_prime.size() << endl;


    set<pll> n_p;
    tr(nu, nums) {
        if(nu->first != 1) {
            ll tmp = nu->first;
            tr(it, dbl_prime) {
                if(*it > tmp)
                    break;
                if(tmp % (*it) == 0) {
                    tmp = sqrt(nu->first);
                    break;
                }
            }
            if(tmp == nu->first)
                tmp *= tmp;

            ll n1 = nu->first, n2 = tmp;
            if(n1 > n2)
                swap(n1, n2);

            n_p.insert(mp(n1, n2));
        }
    }

    ll ans = 0;
    if(ary[1] > 0)
        ans++;
    tr(it, n_p) {
        ans += max(nums[it->first], nums[it->second]);
    }
    cout << ans << endl;

    return 0;
}

