vector< int > prime_table(int n) {
  vector< bool > prime(n + 1, true);
  vi res;
  if(n >= 0) prime[0] = false;
  if(n >= 1) prime[1] = false;
  for(int i = 2; i * i <= n; i++) {
    if(!prime[i]) continue;
    for(int j = i + i; j <= n; j += i) {
      prime[j] = false;
    }
  }

  rep(i,n+1){
    if(prime[i]) res.PB(i);
  }
  return res;
}




bool is_square(int n){
  ll l=0,r=110000;
  while(r-l>1){
    ll m=(r+l)/2;
    if(m*m>n) r=m;
    else l=m;
  }


  return (l*l==n);
}


