	allp.resize(unique(allp.begin(), allp.end()) - allp.begin());
	for (auto i : allp)
		if (i.ff == i.ss)
			ans++;
		else
			ans += max(mp[i.ff], mp[i.ss]);
	cout << ans << endl;
	return 0;
}

