inline ll qpow(ll x,ll k){
	ll ss=1,tmp=x;
	while(k > 0){
		if(k&1) ss*=tmp;
		tmp*=tmp; k/=2;
	}
	return ss;
}

inline bool check(ll x){
	return floor(sqrt(x))*floor(sqrt(x)) == x;
}

inline void work(ll x){
	ll ss=1,tss=1;
	go(i,tt+1,1){
		if(qpow(prime[i],3) > x) break;
		if(x%prime[i] != 0) continue;
		int j=0;
		while(x%prime[i] == 0) x/=prime[i],j++;
		j%=3;
		ss*=qpow(prime[i],j); tss*=qpow(prime[i],(3-j)%3);
	}
	if(check(x)) ss*=x,tss*=floor(sqrt(x));
	else ss*=x,tss*=(ll)x*(ll)x;
	if(mp.count(ss)) mp[ss]=mp[ss]+1;
	else{
		p[++cnt]=pt(ss,tss); mp[ss]=1;
	}
	return ;
}

