inline void init(){
    for(int i=2;i<=MAXX;++i){
    	if(!v[i]){
    		prime[++tot]=i;
    		v[i]=i;
    	}
    	for(int j=1;j<=tot;++j){
    		if(i*prime[j]>MAXX||v[i]<prime[j])break;
    		v[i*prime[j]]=prime[j];
    	}
    }
}
inline void solve(long long x,int pos){
	long long u=1;
	long long v=1;
    for(int i=1;i<=tot;++i){
    	if(x%prime[i]==0){
        int cnt=0;
        while(x%prime[i]==0){
           x/=prime[i];
           cnt++;
         }
          cnt%=3;
          if(cnt==1){
          	u*=prime[i];
          	v*=prime[i]*prime[i];
          }
          if(cnt==2){
          	u*=prime[i]*prime[i];
          	v*=prime[i];
          }
       }
       if(x==1)break;
    }
    if(x>1){
    	int t=sqrt(x);
    	u*=x;
    	if((t*t)==x)v*=t;
    	else v*=x;
    }
    a[pos]=u;
    b[pos]=v;
    num[u]++;
}
