bool miller_rabin(int64 n)
{
    if(n == 1) return false;
    for(int i = 0; i < 12; ++i) if(n%p[i] == 0) return n == p[i];
    int64 r; int t;
    for(r = n-1, t = 0; ~r&1; r >>= 1, ++t);
    for(int i = 0; i < 12; ++i)
    {
        int64 x = qpow(p[i], r, n), xs;
        for(int j = 1; j <= t; ++j)
        {
            xs = x*x%n;
            if(xs == 1&&x != 1&&x != n-1) return false;
            x = xs;
        }
        if(x != 1) return false;
    }
    return true;
}
