using namespace std;

map<__int64, __int64> match;
map<__int64, __int64> cnt;
__int64 arr[100050];
bool isPrime[100050];
vector<__int64> prime;
__int64 Slove(__int64 n)
{
    for(vector<__int64>::size_type i = 0; i < prime.size(); ++i)
    {
        while(n % (prime[i] * prime[i] * prime[i]) == 0)
            n /= prime[i] * prime[i] * prime[i];
    }
    return n;
}
int main()
{
    memset(isPrime, true, sizeof(isPrime));
    for(__int64 i = 2; i <= 100000; ++i)
    {
        if(!isPrime[i])
            continue;
        prime.push_back(i);
        for(__int64 j = i + i; j <= 100000; j += i)
            isPrime[j] = false;
    }
    __int64 n;
    scanf("%I64d", &n);
    for(__int64 i = 1; i <= n; ++i)
        scanf("%I64d", &arr[i]);
    __int64 ans = 0;
    for(__int64 i = 1; i <= n; ++i)
    {
        if(arr[i] == 1)
            ++cnt[1];
        else
        {
            __int64 b;
            __int64 a = Slove(arr[i]);
            if(a > 100000000)
                b = 0;
            else
                b = Slove(a * a);
            ++cnt[a];
            if(a > b)
                swap(a, b);
            if(a != 1)
                match[a] = b;
        }
    }
    if(cnt.find(1) != cnt.end())
        ans = 1;
    for(auto it = match.begin(); it != match.end(); ++it)
    {
        __int64 a, b;
        a = it->first;
        b = it->second;
        ans += max(cnt[a], cnt[b]);
        cnt[a] = 0;
        cnt[b] = 0;
    }
    printf("%I64d\n", ans);
    return 0;
}

