void addNum(long long x)
{
	Num num = {vector<int>(0), 0};
    for (long long p : primes) {
        if (x % p) continue;
        int r = 0;
        while (x % p == 0) {
            x /= p;
            ++r;
        }
		r %= 3;
		if (r > 0) {
            num.first.push_back(p);
            num.second = num.second * 2 + (r - 1);
		}
    }

    int y = sqrt(x);
    if (x == 1) {
		nums.push_back(num);
		return;
    }
    if (y * y == x) {
		num.first.push_back(y);
        num.second = num.second * 2 + 1;
        nums.push_back(num);
    } else {
		num.first.push_back(x);
        num.second = num.second * 2;
        nums.push_back(num);
    }
}

