using namespace std;

int n;
vector<__int128_t> s, t;

void init() {
  map<__int128_t, __int128_t> mp;
  vector<__int128_t> prime;
  bool f[101010];
  memset(f, true, sizeof f);

  f[0] = f[1] = false;
  for (int i = 2; i <= 100000; ++i) {
    if (f[i]) {
      if (i < 2200) prime.push_back(i);
      mp[(int64_t)i * i] = i;
      for (int j = 2 * i; j <= 100000; j += i) {
        f[j] = false;
      }
    }
  }

  for (int i = 0; i < n; ++i) {
    int64_t m;
    cin >> m;

    __int128_t a, b;
    a = b = 1;

    for (auto &p : prime) {
      int cnt = 0;
      while (m % p == 0) {
        ++cnt;
        m /= p;
      }

      cnt %= 3;
      for (int j = 0; j < cnt; ++j) a *= p;
      for (int j = (3 - cnt) % 3; j > 0; --j) b *= p;
    }

    if (mp.count(m)) {
      a *= mp[m];
      b *= m;
    } else {
      a *= (__int128_t)m * m;
      b *= m;
    }

    s.push_back(a);
    t.push_back(b);
  }
}

int main() {
  cin >> n;
  init();

  map<__int128_t, int> mp;
  map<__int128_t, __int128_t> po;
  for (int i = 0; i < n; ++i) {
    mp[s[i]]++;
    po[s[i]] = t[i];
  }

  int ans = n;
  for (auto &i : mp) {
    if (i.first == 1) {
      ans -= i.second - 1;
      continue;
    }

    __int128_t uku = po[i.first];
    if (mp.count(uku) && uku < i.first) {
      ans -= min(mp[uku], i.second);
    }
  }

  cout << ans << endl;
}

