            }
        }
        if (P[n]) c *= n, n = 1;
        c *= n * n;

        if (i.fi == 1) {
            res++;
        } else {
            res += max(i.se, M[c]);
            i.se = M[c] = 0;
        }
    }

    cout << res << rt;
}

