int jeb(int x)
{
	int res = x;
	for (auto it: prim) {
		int sz = it*it*it;
		if (sz > x)
			break;
		while (x%sz == 0)
			x /= sz;
	}
	return x;
}

int jeb2(int x)
{
	int res = 1;
	for (auto it: prim) {
		if (res > INF)
			return -1;
		if (it > x)
			break;
		if (x%it)
			continue;
		if (res*it > INF)
			return -1;
		if (x%(it*it) == 0) {
			res *= it;
			x /= it*it;
		}
		else {
			res *= it*it;
			x /= it;
		}
	}
	if (res > INF)
		return -1;
	if (x == 1)
		return res;
	if (pierw[x]) {
		if (res > INF/x)
			return -1;
		return res*x;
	}
	if (res*x > INF/x)
		return -1;
	return res*x*x;
}

bool sze(int x)
{
	int co = pow(x, 0.3);
	while (co*co*co < x)
		++co;
	while (co*co*co > x)
		--co;
	return co*co*co == x;
}

