LL a[maxn],t[maxn];int n,cnt,m,ans;
int prm[maxn],tot,is[maxn],ord[maxn];

void predo(int n) {
	for (int i=2;i<=n;i++)
	{
		if (!is[i]) prm[++tot]=i;
		for (int j=1;j<=tot;j++)
		{
			int num=prm[j]*i;
			if (num>n) break;
			if (i%prm[j]) is[num]=1;
			else {is[num]=1;break;}
		}
	}
}
void solve(LL n)
{
	LL u=1ll,v=1ll;
	for (int i=1;i<=tot;i++)
	if (n%prm[i]==0) {
		int cnt=0,x=prm[i];
		while (n%x==0) n/=x,++cnt;
		cnt%=3;
		if (cnt==1) u*=x,v*=x*x;
		if (cnt==2) u*=x*x,v*=x;
	}
	LL n_=sqrt(n);
	if (n_*n_==n) u*=n,v*=n_;
	else if (n>(int)1e5) {ans++;return ;}
	else {u*=n;v*=n*n;}
	if (u==1) ++cnt;
	else {t[++m]=min(u,v);a[m]=v;}
}

