vector<int>primes;
vector<int> prime_factorization(int x) {
	vector<int> factors;
	// xまでのeratosと同じ。ｘはgiven ｘまでの最大の素数。
	// だんだん左によってくる。だからsqrt(x)まででいい
	for (auto &p : primes) {
		while (x % p == 0) {
			x /= p;
			factors.emplace_back(p);
		}
	}
	if (x != 1)
		factors.emplace_back(x);
	return factors;
}
