int sqrt(int x){
	int l = 0, r = 1e9, res = 0;
	while(l <= r){
		int mid = (l + r) >> 1;
		if(mid * mid <= x) res = mid, l = mid + 1;
		else r = mid - 1;
	}
	return res;
}

int cbrt(int x){
	int l = 0, r = 1e6, res = 0;
	while(l <= r){
		int mid = (l + r) >> 1;
		if(mid * mid * mid <= x) res = mid, l = mid + 1;
		else r = mid - 1;
	}
	return res;
}

bool prime(int x){
	if(x < 2) return false;
	else if(x > 2){
		if(x % 2 == 0) return false;
		else for(int i = 3; i * i <= x; ++i) if(x % i == 0) return false;
