int complement(int x){ // calculate cubic complement
	int res = 1;
	for(auto num: p){
		int e = 0;
		while(x % num == 0) x /= num, e = (e + 1) % 3;
		e = (3 - e) % 3;
		while(e--){
			if(num > 9e18 / res) return -1;
			else res *= num;
		}
	}
	int f = sqrt(x);
	if(f * f == x){
		if(f > 9e18 / res) return -1;
		else res *= f;
	}
	else{
		if(f * f > 9e18 / res) return -1;
		else res *= f * f;
	}
	return res;
}

