long long solve(long long I) {
	long long ret = 1;
	for (long long i = 2; i <= 2500; i++) {
		long long U = 0; while (I%i == 0) { I /= i; U++; U %= 3; }
		for (int j = 0; j < (3 - U % 3) % 3; j++) {
			if (ret*i <= inf)ret *= i;
			else ret = inf;
		}
	}
	long long G = sqrtl(1.0L*I); if (G*G == I) { ret *= G; }
	else { if ((inf / I) <= ret)ret *= I; else ret = inf; }
	return min(ret, inf);
}
