	get_prime();
	Rep(i, n) {
		LL x, x1 = 1, x2 = 1;
		scanf("%lld", &x);
		Rep(j, cnt){
			int tmp = 0;
			while (!(x % prime[j])) x /= prime[j], tmp ++;
			//printf("%d %d\n", prime[j], cnt);
			tmp %= 3;
			if (tmp == 1) x1 *= prime[j], x2 *= prime[j] * prime[j];
			else if (tmp == 2) x1 *= prime[j] * prime[j], x2 *= prime[j];
			if (x2 > 1e10) { val[i] = true; break;}
		}
		if (!val[i] && x != 1) {
			LL tx = sqrt(x);
			if (tx * tx == x) x1 *= x, x2 *= tx;
			else if (log(x2) + log(x) + log(x) <= 11) x1 *= x, x2 *= x * x;
			else val[i] = true;
		}
		if (!val[i]){
			m[x1] ++;
			t1[i] = x1, t2[i] = x2;
		}
	}
	int ans = 0, ans0 = 0;
	Rep(i, n) {
		if (val[i]) ans ++;
		else {
		//	printf("%d %lld %lld %d %d\n", i, t1[i], t2[i], m[t1[i]], m[t2[i]]);
			if (m[t2[i]] < m[t1[i]]) ans ++;
			else if (m[t2[i]] == m[t1[i]]) ans0 ++;
		}
	}
	if (m[1] == 1) ans ++;
	printf("%d\n", ans + ans0 / 2);

	return 0;
}

