const int N = 1e7 + 100;

vi primes;

bool prime[N];

int cnt_big;
bool zero;

map<ll, map<int, int>> msks;
map<ll, int> len;

void smain() {
    primes.reserve(N);
    fill(prime, prime + N, true);
    for (int i = 2; i * i <= N; ++i) {
        if (!prime[i])
            continue;
        primes.push_back(i);
        for (int j = i * i; j < N; j += i) {
            prime[j] = false;
        }
    }

    int n;
    cin >> n;
    fori (i, n) {
        ll x;
        cin >> x;
        vector<pll> f;
        for (auto p : primes) {
            if (x % p == 0) {
                int cnt = 0;
                while (x % p == 0) {
                    x /= p;
                    cnt++;
                }
                f.push_back({p, cnt});
            }
        }
        if (x > 1) {
            if (binary_search(ALL(primes), x)) {
                f.push_back({x, 1});
            } else {
                cnt_big++;
                continue;
            }
        }
        sort(ALL(f));
        int cnt = 0;
        ll base = 1;
        int mask = 0;
        for (auto x : f) {
            if (x.second % 3 != 0) {
                base *= x.first;
                mask |= ((ll)x.second % 3 - 1) << cnt;
                cnt++;
            }
        }
        if (base == 1) {
            zero = 1;
        } else {
            msks[base][mask]++;
            len[base] = cnt;
        }
    }
    ll ans = cnt_big + zero;
    for (auto item : msks) {
        ll base = item.first;
        for (auto x : item.second) {
            int inv = x.first ^ ((1LL << len[base]) - 1);
            if (item.second.count(inv)) {
                if (inv < x.first)
                    ans += max(x.second, item.second[inv]);
            } else {
                ans += x.second;
            }
        }
    }
    cout << ans;
}

#include <bits/stdc++.h>

using namespace std;

typedef long long ll;

struct tp{ ll f, s, t; };

vector <tp> V;
ll F[101010], S[101010], T[101010], K[101010];
ll n,s,ans;

int main()
{
	ll i,j,k,a,b,c;
	ll l,r,f = 0;

	scanf("%lld",&n);

	for(i=0;i<n;i++){
		scanf("%lld",&a);
		b = c = 1;
		for(j=2;j<=2500 && j<=a;j++) if(a % j == 0){
			for(k=0;a%j == 0;k++) a /= j;
			if(k % 3 == 1) b *= j, c *= j * j;
			else if(k % 3 == 2) b *= j * j, c *= j;
		}
		if(a == 1 && b == 1) f = 1;
		else V.push_back({b, c, a});
	}

	sort(V.begin(), V.end(), [&](tp ca, tp cb){
		if(ca.f != cb.f) return ca.f < cb.f;
		else return ca.t < cb.t;
	});

	for(i=s=0;i<V.size();i++){
		if(!i || (V[i].f != V[i-1].f || V[i].t != V[i-1].t)){
			s ++;
			F[s] = V[i].f;
			S[s] = V[i].s;
			T[s] = V[i].t;
			K[s] = 1;
		}
		else K[s] ++;
	}

	for(i=1;i<=s;i++){
		if(F[i] > S[i] || T[i] > 1e9 || T[i] * T[i] > 1e10) continue;

		l = lower_bound(F+1, F+s+1, S[i]) - F;
		r = upper_bound(F+1, F+s+1, S[i]) - F;
		k = lower_bound(T+l, T+r, T[i] * T[i]) - T;
		if(T[k] == T[i] * T[i]){
			ans += max(K[i], K[k]);
			K[k] = 0;
		}
		else ans += K[i];
		K[i] = 0;
	}

	for(i=1;i<=s;i++) ans += K[i];

	printf("%lld\n",ans + f);

	return 0;
}

