void precompute () {
    for (int i=2; i*i<2200; i++) {
        if (p[i] == 1) continue;
        for (int j=i*i; j<2200; j+=i) {
            p[j] = i;
        }
    }
    for (int i=2; i<2200; i++) {
        if (p[i] == 0) v.push_back(i);
    }
}

void f (llint x) {
    vector < pair <llint, llint> > r;
    for (auto q : v) {
        llint cnt = 0;
        while (x % q == 0) {
            x /= q;
            cnt++;
        }
        if (cnt % 3 == 0) continue;
        r.push_back({q, cnt % 3});
    }
    if (x > 1) {
        llint k = sqrt(x);
        if (k * k == x) r.push_back({k, 2}); else r.push_back({x, 1});
    }
    if (r.empty()) {
        jen++;
        return;
    }
    llint tip = 0;
    if (r[0].second == 2) {
        tip = 1;
        for (int i=0; i<r.size(); i++) {
            r[i].second = 2 - r[i].second;
        }
    }
    llint a = 1, b = 1;
    for (int i=0; i<r.size(); i++) {
        a *= r[i].first;
        if (r[i].second == 2) b *= r[i].first;
    }
    mp[tip][{a, b}]++;
    st.insert({a, b});
}

