        {
            ans += count[SS[i]];
            used.insert(SS[i]);
        }
        else
        {
            if (SS[i] == 1)
            {
                ans += 1;
                used.insert(1);
            }
            else
            {
                ans += max(count[SS[i]], count[SSS[i]]);
                used.insert(SS[i]);
                used.insert(SSS[i]);
            }

        }
    }
