				while (D[i].a%prime[j]==0)
					D[i].a/=prime[j],cc++;
				cc%=3;
				if (cc)
				{
					D[i].norm*=prime[j];
					D[i].pair*=prime[j];
					if (D[i].pair>N2) D[i].pair=0;
					if (cc==1) D[i].pair*=prime[j];
					else D[i].norm*=prime[j];
					if (D[i].pair>N2) D[i].pair=0;
				}
			}
		if (mp.count(D[i].a))
		{
			D[i].pair*=mp[D[i].a];
			if (D[i].pair>N2) D[i].pair=0;
		}
		else
		{
			if (log(D[i].pair)+log(D[i].a)+log(D[i].a)>log(N2)) D[i].pair=0;
			else D[i].pair*=D[i].a*D[i].a;
		}
		D[i].norm*=D[i].a;
		D[i].a=1;
	}

	sort(D+1,D+n+1);
	mp.clear();
	for (i=1;i<=n;i++)
		mp[D[i].norm]++;
	for (i=1;i<=n;i++)
	{
		if (D[i].norm==1) {Ans1=1; continue;}
		Ans+=max(mp[D[i].norm],mp[D[i].pair]);
		mp[D[i].norm]=mp[D[i].pair]=0;
	}
	Ans+=Ans1;
	printf("%d\n",Ans);
}

