vector<pair<long long ,int>> remove_cube(long long k){
    LL div=1;
    vector<pair<long long ,int>> ret;
    for(int i=0; ;++i){
        if(primes[i]*primes[i]>k){
            if(div!=k)ret.push_back(make_pair(k/div,1));
            break;
        }
        if(k%primes[i]==0){
            ret.push_back(make_pair(primes[i],0));
            LL kk=k;
            while(kk%primes[i]==0){
                kk/=primes[i];
                div*=primes[i];
                (ret.end()-1)->second++;
            }
            (ret.end()-1)->second%=3;
        }
    }
    for(auto it=ret.begin(); it<ret.end(); ++it){
        if(it->SE==0){
            it=ret.erase(it);
        }else{
            ++it;
        }
    }
    if(ret.size()==0) ret.push_back(make_pair(1ll,0));
    return ret;
}

