    int64 res = 0,t = a;
    while(b) {
	if(b & 1) res = (res + t) % MOD;
	t = (t + t) % MOD;
	b >>= 1;
    }
    return res;
}
int64 fpow(int64 a,int64 c,int64 MOD) {
    int64 res = 1,t = a;
    while(c) {
	if(c & 1) res = mul(res,t,MOD);
	t = mul(t,t,MOD);
	c >>= 1;
    }
    return res;
}
