			if(q==1)	break;
			ll ttt=p[j]*p[j]*p[j],tt=p[j]*p[j],t=p[j];
			while(q%ttt==0)		q/=ttt;
			if(q%tt==0)	b[i]*=p[j],a[i]*=p[j]*p[j];
			else if(q%t==0)	b[i]*=p[j]*p[j],a[i]*=p[j];
			while(q%t==0)	q/=t;
		}
		if(q!=1)
		{
			ll x=(ll)sqrt(q);
			if(x*x == q)	b[i]*=x,a[i]*=x*x;
			else	b[i]*=x*x,a[i]*=x;
		}
	}
	for(int i=1;i<=n;i++)	s[a[i]]++;
	int	ans=0;// printf("%d\n",ans);
	for(int i=1;i<=n;i++)
	{
		if(!h[a[i]])
		{
			h[a[i]]=h[b[i]]=1;
			if(a[i]==b[i])	ans++;
			else	ans+=max(s[a[i]],s[b[i]]);
		}
	}
	printf("%d\n",ans);
	return 0;
}

