#include<bits/stdc++.h>
using namespace std;

vector<int> primes;
const int RT = 1e5+7;
const long long LIM = 1e10+10;
void sieve() {
    vector<bool> isp(RT, 1);
    for (int i=2; i<RT; i++)
        if (isp[i]) {
            primes.push_back(i);
            for (int j=2*i; j<RT; j+=i)
                isp[j] = 0;
        }
}

pair<long long, long long> process(long long x) {
    long long a = 1, b = 1;
    for (long long p: primes) {
        if (x%p)    continue;
        if (p*p*p > x)  break;
        int cnt = 0;
        while (x%p==0) x/=p, cnt++;

        if (cnt%3==1) {
            a *= p;
            if (b > LIM/(p*p))  b = LIM;
            else                b *= p*p;
        }
        if (cnt%3==2) {
            a *= p*p;
            if (b > LIM/p)  b = LIM;
            else            b *= p;
        }
    }

    if (x == 1)     return {a, b};

    long long rt = round(sqrt(x));
    if (rt*rt == x) {
        a *= rt*rt;
        if (b > LIM/rt)  b = LIM;
        else            b *= rt;
    }
    else {
        a *= x;
        if (b > (LIM/x)/x)  b = LIM;
        else                b*=x*x;
    }
    return {a, b};
}

const int N = 1e5+7;
long long a[N], b[N];

int main() {
    ios::sync_with_stdio(0);
    cin.tie(0);

    sieve();

    int n;
    cin>>n;

    map<long long, int> cnt;
    map<long long, long long> opp;

    for (int i=1; i<=n; i++) {
        long long x;
        cin>>x;

        auto pr = process(x);
        a[i] = pr.first;
        b[i] = pr.second;

        cnt[a[i]]++;
        opp[a[i]] = b[i];
        opp[b[i]] = a[i];
    }
    cnt[LIM] = 0;

    long long ans = 0;
    for (auto pr: opp) {
        long long a = pr.first, b = pr.second;
        if (a == b)     ans += min(1, cnt[a]+cnt[b]);
        else if (a < b) ans += max(cnt[a], cnt[b]);
    }
    cout<<ans<<endl;
}

