template <typename T> vector<pair<T, int> > factorize(T n) {
  vector<pair<T, int> > ret;
  for (T i = 2; i * i <= n; i++) {
    int e = 0;
    while (n % i == 0) {
      e++;
      n /= i;
    }
    if (e) ret.emplace_back(i, e);
  }
  if (n != 1) ret.emplace_back(n, 1);
  return ret;
}

