    ll x = 1;
    ll y = 1;
    forr(li, f) {
      li.snd %= 3;
      rep(j, li.snd) x *= li.fst;
      int z = (3 - li.snd) % 3;
      rep(j, z) y *= li.fst;
    }
    conv[a] = x;
    targ[x] = y;
    co[x]++;
    xs.push_back(x);
  }
  sort(ALL(xs));
  xs.erase(unique(xs.begin(), xs.end()), xs.end());

  int ans = 1;
