vector<ii> get(int x) {
	vector<ii> ret; 
	for(auto p : pr) {
		if(p * p > x) break; 
		if(x % p == 0) {
			int cnt = 0; 
			while(x % p == 0) {
				x /= p; 
				cnt++; 
			}
			cnt %= 3; 
			if(!cnt) continue; 
			ret.pb({p, cnt}); 
		}
	}
	if(x > 1) 
		ret.pb({x, 1});
	return ret; 
}

vector<ii> comple(vector<ii> x) {
	vector<ii> ret; 
	for(auto p : x) 
		ret.pb({p.fi, 3 - p.se});
	return ret; 
}

