	for(LL i=2;i*i*i<=x;i++)
		if(tx%i==0){
			int cnt=0;
			while(tx%i==0) tx/=i,cnt++;
			cnt%=3;
			for(int j=0;j<cnt;j++) y1*=i;
			cnt=(3-cnt)%3;
			for(int j=0;j<cnt;j++) y2*=i;
		}
	if(tx>1){
		LL temp=max((LL)(sqrt(tx)-2),1LL);
		for(LL i=0;i<4;i++)
			if((temp+i)*(temp+i)==tx){
				y1*=tx;
				y2*=temp+i;
				return make_pair(y1,y2);
			}
		y1*=tx;
		y2*=tx*tx;
	}
	return make_pair(y1,y2);
}

