vector<ll> k;
bool used[N];

int process(int v) {
	vector<int> cur;
	do {
		used[v] = true;
		cur.push_back(v);
		if (g[v].empty()) break;
		v = g[v][0];
	} while (true);
	vector<vector<int>> f(cur.size(), vector<int>(2, 0));
	f[0][0] = 0;
	f[0][1] = cnt[cur[0]];
	for (int i = 1; i < (int)cur.size(); i++) {
		f[i][0] = max(f[i - 1][0], f[i - 1][1]);
		f[i][1] = f[i - 1][0] + cnt[cur[i]];
	}
	return *max_element(all(f.back()));
}

bool isCube(ll x) {
	if (x == 1) return false;
	ll z = pow((double)x, (double)1 / 3) + 0.5;
	if (z * z * z == x) return true;
	return false;
}

