constexpr long long mod = 9_ten + 7;


vector<long long> Eratosthenes(long long N){
  vector<bool> v(N+1, true);
  v[0] = v[1] = false;
  long long sqN = sqrt(N);
  for(int i=2; i<=sqN; i++){
    if(v[i] == false) continue;
    for(long long j=i*i; j<=N; j+=i){
      v[j] = false;
    }
  }
  vector<long long> Prime;
  for(long long i=2; i<=N; i++){
    if(v[i]==true) Prime.push_back(i);
  }
  return Prime;
}


int main(){
  int n;
  cin >> n;
  vector<long long> v(n);
  for(int i=0; i<n; i++){
    scanf("%lld", &v[i]);
  }
  sort(v.begin(), v.end());

  auto P = Eratosthenes(100000);

  shuffle(P.begin(), P.end(), mt);

  vector<long long> cube;
  for(long long i=1; i*i*i <= 10_ten; i++){
    cube.push_back(i*i*i);
  }

  vector<vector<long long>> vp(n);
  vector<long long> vk(n, 0);

  long long ans = 0;
  bool zero = false;
  vector<pair<int,long long>> u;

  for(auto i : range(n) ){
    if(v[i] == 1) zero = true;
    else if( binary_search(cube.begin(), cube.end(), v[i] ) ) zero = true;
    else u.push_back({i, v[i]});
  }

  if(zero) ans++;

  map<vector<long long>, map<long long, long long>> G;

  for(auto p : P){
    if(u.size() == 0) break;
    vector<pair<int,long long>> u_;
    for(auto& x : u){
      if(x.second % p != 0){
        u_.push_back( x );
        continue;
      }

      int cnt = 0;
      while(x.second % p == 0){
        x.second /= p;
        cnt++;
      }

      if(cnt%3 != 0){
        if(cnt%3 == 2) vk[x.first] |= 1LL << (vp[x.first].size());
        vp[x.first].push_back( p );
      }

      if(x.second != 1){
        u_.push_back(x);
      }
    }

    swap(u, u_);
  }

  for(auto& x : u){
    vp[x.first].push_back( x.second );
  }

  for(int i=0; i<n; i++){
    if(vp[i].size() == 0) continue;
    G[ vp[i] ][ vk[i] ] += 1;
  }

  for(auto& ps : G){
    set<long long> used;
    for(auto& pr : ps.second){
      if( used.count( pr.first ) ) continue;
      auto inv = (~pr.first) & ((1LL<<ps.first.size()) - 1);

      if( ps.second.count( inv ) == 0 ){
        ans += pr.second;
      }else{
        ans += max(pr.second, ps.second[inv]);
        used.insert(inv);
      }
    }
  }

  println(ans);

  return 0;
}

