unordered_map <ll,pii> cnt;


vector < pii > Rev; 


void Sieve()
{

    for(int i = 2; i <= mk; i++) {
	    if(d[i]) Pr.push_back(i);
	    for(int j = 0 ; Pr[j] * i <=mk&& j < Pr.size() && Pr[j] <= d[i] ; j++) {
	    	d[i * Pr[j]] = Pr[j];
		}
	}
}
inline pair<ll,ll> root(ll x)
{
    ll val=1,reverse_val=1;
    for (auto i: Pr)
    {
        if(i*i>x) break;
        if(x%i==0)
        {
            int num=0;
            while(x%i==0)
            {
                num++;
                x/=i;
            }
            num%=3;
            val = val * pow(i , num);
            reverse_val = reverse_val * pow(i , 3 - num);
        }
    }
    if(x>1)
    {
        val *= x; 
        reverse_val *= x * x; 
    }
    return mp(val,reverse_val);
}


void solve()
{
    Sieve();
    int n;
    cin >> n;
    for (int i = 1; i <= n; i++)
    {
        ll x; cin >> x; 
        if(cnt.count(x)==0)
        {
            pair<ll,ll> cur= root(x);
            Rev.push_back(cur);
            cnt[x]=cur;
        }
        else
            Rev.push_back(cnt[x]);
            occurance[Rev.back().first]++;
    }
    ll ans=0;
    if(occurance[1]>=1) ans++;
    for (int i = 0; i < n; i++)
    {

        ll uwu = Rev[i].first;
        int cur_val = occurance[uwu];
        if(cur_val==0) continue;
        if(uwu==1) continue;
        ll rever = Rev[i].second;
        ans += max(cur_val, occurance[rever]);
        occurance[rever]=0;
        occurance[uwu]=0;
       /// cout <<  " Miku huhuhu"
    }
    cout << ans << endl;
}

int main()
{
    solve();
}

