		static int f[100],ff[100];
		int fcnt=0;
		for(int j=1; j<=pcnt && i>=p[j]; ++j) {
			if (i%p[j]==0) {
				f[++fcnt]=j;
				int cnt=0;
				while(i%p[j]==0) {
					++cnt;
					i/=p[j];
				}
				ff[fcnt]=cnt%3;
			}
		}
		if (i>1) {
			LL t=sqrtl(i);
			if (t*t==i) {
				f[++fcnt]=t;
				ff[fcnt]=2;
			} else {
				f[++fcnt]=i;
				ff[fcnt]=1;
			}
		}
		bool flag2=true;
		for(int j=1; j<=fcnt; ++j) {
			if (ff[j]>0) {
				flag2=false;
				break;
			}
		}
		if (flag2) {
			flag=true;
			continue;
		}
		ULL hnow=getHash(f,ff,fcnt);
		for(int j=1; j<=fcnt; ++j) {
			if (ff[j]>0) {
				ff[j]=3-ff[j];
			}
		}
		ULL to=getHash(f,ff,fcnt);
		debug(bak,hnow,to);
		if (x.count(hnow)==0) {
			x[hnow]=make_pair(to,1);	
		} else {
			massert(x[hnow].first==to);
			x[hnow].second++;
		}
	} 
	for(auto i:x) {
		ULL a=i.first,b=i.second.first;
