        vector <pair<long long, int> > w;

        if (isprime(a[i])) {
            w.push_back(make_pair(a[i], 1));
        } else {
            long long x = sqrt(a[i]);

            if (x * x == a[i]) {
                while (x > 1) {
                    if (w.size() >= 1 && w.back().first == b[x]) {
                        if (w.back().second == 1) {
                            w.pop_back();
                        } else {
                            w.back().second = 1;
                        }
                    } else {
                        w.push_back(make_pair(b[x], 2));
                    }

                    x /= b[x];
                }
            } else {
                for (j = 0; j < v.size() && a[i] > 1; j++) {
                    if (a[i] % v[j] == 0) {
                        int c = 0;

                        while (a[i] % v[j] == 0) {
                            c++;
                            a[i] /= v[j];
                        }

                        c %= 3;

                        if (c > 0) w.push_back(make_pair(v[j], c));

                        if (a[i] <= 1000000) break;

                        if (isprime(a[i])) {
                            w.push_back(make_pair(a[i], 1));
                            a[i] = 1;
                        }
                    }
                }

                if (a[i] > 1000000) {
                    w.push_back(make_pair(a[i], 1));
                    a[i] = 1;
                }

                while (a[i] > 1) {
                    if (w.size() >= 1 && w.back().first == b[a[i]]) {
                        if (w.back().second == 2) {
                            w.pop_back();
                        } else {
                            w.back().second++;
                        }
                    } else {
                        w.push_back(make_pair(b[a[i]], 1));
                    }

                    a[i] /= b[a[i]];
                }
            }
        }

        mp[w]++;
    }

    for (it = mp.begin(); it != mp.end(); it++) {
        if (it->first.size() == 0) {
            ans++;
        } else {
