typedef pair<ll, ll> p_ll;
const int nm = 3 * pow(10,3);
vector<bool> isp(nm, true);
vector<ll> primes;

void sieve() {
  isp[0] = false;
  isp[1] = false;
  for (int i=2; pow(i,2)<=nm; i++) {
    if (isp[i]) for(int j=2; i*j<=nm; j++) isp[i*j] = false;
  }
  rep(i,nm) if (isp[i]) primes.push_back(i);
}

int main() {
  int N; cin >>N;
  ll s[N]; rep(i,N) cin >> s[i];
  sieve();
  map<p_ll, ll> num;
  ll result = 0;
  rep(i,N) {
    p_ll p = make_pair(1,1);
    for (auto prime: primes) {
      while (s[i]%(ll)pow(prime,3)==0) {s[i]/=(ll)pow(prime,3);}
      if (s[i]%prime!=0) continue;
      s[i]/=prime;
      if (s[i]%prime==0) { s[i]/=prime; p.first*=(ll)pow(prime,2); p.second*=prime; }
      else { p.first*=prime; p.second*=(ll)pow(prime,2); }
    }
    if (s[i]!=1) {
      double sq = sqrt(s[i]);
      if (floor(sq)==sq) { p_ll ppp = make_pair(s[i],sq); num[ppp]++; }
      else result++;
    }
    else num[p]++;
    // cout << p.first << " " << p.second << endl;
  }
  for (auto x: num) {
    if (x.first.first==1) { result++; continue; }
    p_ll ppp = make_pair(x.first.second, x.first.first);
    if (num[ppp]) {
      if (x.first.first>x.first.second) continue;
      result += max(x.second, num[ppp]);
    }
    else result += x.second;
    // cout << x.first.first << "&" << x.first.second << "->" << x.second << endl;
  }
  cout << result << endl;
  return 0;
}

