ll norm(ll x) {
  for (int p : prime) {
    ll t = 1ll * p * p * p;
    if (t > x) break;
    while (x % t == 0) x /= t;
  }
  return x;
}

ll mul(ll a, ll b) {
  if (INF64 / b < a) return INF64;
  else return a * b;
}

ll conj(ll x) {
  ll res = 1;
  for (int p : prime) {
    if (1ll * p * p > x) break;
    if(x % p == 0) {
      if ((x / p) % p == 0) res = mul(res , p) , x /= p , x /= p;
      else res = mul(res , mul(p , p)) , x /= p;
    }
  }
  if (x > 1) res = mul(res, mul(x, x));
  return res;
}

