inline void jzp(int n){
	for(int x=2;x<=n;++x){
		if(!vis[x])pri.push_back(x);
		for(auto&y:pri){
			if(1ll*x*y>n)break;
			vis[x*y]=1;
			if(!(x%y))break;
		}
	}
}

inline void get_norm(ll x){
	for(auto&y:pri){
		ll z=1ll*y*y*y;
		if(z>x)break;
		while(!(x%z))x/=z;
	}
	if((++Norm[x]==1)&&!Pair[x])
		tmp.push_back(x);
}

inline void get_pair(ll x){
	ll res=1;
	for(auto&y:pri){
		ll z=1ll*y*y*y;
		if(z<=x){
			while(!(x%z))x/=z;
			if(!(x%(y*y))){
				res*=y,x/=(y*y);
				if(res>lmt){++ans; return;}
			}
			else if(!(x%y)){
				res*=(y*y),x/=y;
				if(res>lmt){++ans; return;}
			}
		}
		else{
			ll w=1ll*y*y;
			if(w>x){
				if(1.*res*x*x>lmt){++ans; return;}
				res*=(x*x); break;
			}
			else if(!(x%y)){
				if(x==w){
					res*=y;
					if(res>lmt){++ans; return;}
				}
				else{
					if(1.*res*x*x>lmt){++ans; return;}
					res*=(x*x);
				}
				break;
			}
		}
	}
	if((++Pair[res]==1)&&!Norm[res])
		tmp.push_back(res);
}

