void mult(ll& a, ll b) {
    if (limit / a < b)
        a = limit;
    else
        a *= b;
}

void add_number(ll x) {
    int i;
    ll op, aux;

    aux = x;

    for (auto e : divs) {
        while (x % e.second == 0) {
            x /= e.second;
            aux /= e.second;
        }

        while (aux % e.first == 0)
            aux /= e.first;

        if (aux < e.first) break;
    }


    op = 1LL;
    if (M[aux]) {
        mult(op, sqrt(aux));
    } else {
        mult(op, aux);
        mult(op, aux);
    }

    for (auto e : divs) {
        if (x % e.first == 0) {
            if (x % (e.first * e.first) == 0) {
                mult(op, e.first);
            } else {
                mult(op, e.first * e.first);
            }
        }

        if (x < e.first) break;
    }

    if (x < op)
        work.pb(mp(x, 0));
    else
        work.pb(mp(op, 1));
