void init_prime(int N){
    vector<int> vis(N, 0);
    prime.clear();
    vis[1] = 1;
    for(int i = 2;i < N;i++){
        if(!vis[i]){
            prime.push_back(i);
            for(int j = i * 2;j < N; j += i){
                vis[j] = 1;
            }
        }
    }
}

ll qpow(ll a, ll n){
    ll ret = 1;
    while(n > 0){
        if(n & 1){
            ret = ret * a;
        }
        a = a * a;
        n >>= 1;
    }
    return ret;
}

vector<pair<ll, int> > decom(ll v){
    vector<pair<ll, int> > ans;
    for(int i = 0;i < prime.size();i++){
        if(prime[i] > v)
            break;
        if(v % prime[i] == 0){
            int cnt = 0;
            while(v % prime[i] == 0){
                v /= prime[i];
                cnt++;
            }
            cnt %= 3;
            ans.eb(prime[i], cnt);
        }
    }
    if(v > 1){
        ll rt = (ll)(sqrt(v) + 0.5);
        if(rt * rt == v){
            ans.eb(rt, 2);
        }else{
            ans.eb(v, 1);
        }
    }
    return ans;
}

int Inv[3] = {0, 2, 1};

ll cal(vector<pair<ll, int> > rep, bool inv){
    ll ret = 1;
    for(auto p : rep){
        int cnt = p.se;
        if(inv)
            cnt = Inv[cnt];
        ret = ret * qpow(p.fi, cnt);
    }
    return ret;
}

