vector<bool> Eratosthenes(const int n) {
    vector<bool> r(n + 1, true);
    for (int i = 2; i * i <= n; ++i) {
        if (r[i]) {
            for (int j = i * 2; j <= n; j += i) r[j] = false;
        }
    }
    if (r.size() > 2) {
        r[0] = r[1] = false;
    } else if (r.size() > 1) {
        r[0] = false;
    }
    return r;
}

int N;
vector<bigint> A, B;

ll cubic[2525];
map<bigint, int> mp;

signed main() {

    REP(i, 2525) cubic[i] = i * i * i;

    vector<bool> sieve = Eratosthenes(2525);
    vector<int> prime;  REP(i, 2525) if (sieve[i]) prime.emplace_back(i);

    cin >> N;

    A.resize(N);
    REP(i, N) cin >> A[i];

    B.resize(N);
    REP(i, N) {
        for (auto& p: prime) {
            while (A[i] % cubic[p] == 0) {
                A[i] /= cubic[p];
            }
        }
        mp[A[i]]++;
        B[i] = A[i] * A[i];
        for (auto& p: prime) {
            while (B[i] % cubic[p] == 0) {
                B[i] /= cubic[p];
            }
        }
    }

    int res = 0;
    set<bigint> st;

    REP(i, N) {
        if (st.count(A[i])) continue;
        if (A[i] == 1) {
            res++;
            st.emplace(1);
        } else {
            res += max(mp[A[i]], mp[B[i]]);
            st.emplace(A[i]);
            st.emplace(B[i]);
        }
    }

    cout << res << endl;

}

