void prime_list(int sz){
  fill(arr, arr+sz+1, true);
  arr[0]=arr[1]=false;
  for(int i=4;i<=sz;i+=2) arr[i]=false;
  primes.pb(2); pc.pb(8);
  for(long i=3; i<=sz/2; i+=2){
    if(arr[i]){
      if(i*i*i<1e+10) pc.pb(i*i*i);
      primes.pb(i);
      for(long j=i*i; j<=sz; j+=i) arr[j]=false;
    }
  }
}

int main(){
  prime_list(100000);
  int n;
  cin>>n;
  vector<long> vec(n);
  rep(i,n){
    scanf("%ld", &(vec[i]));
    for(long c : pc){
      while(vec[i]%c==0) vec[i]/=c;
    }
  }

  sort(all(vec));
  int res=0;
  map<long, int> mp; // 数と個数
  map<long, long> ref; // 掛けると立方数になるペアの対応表
  rep(i, vec.size()){
    long d=vec[i];
    if(d==1){
      res=1;
      continue;
    }
    if(ref.find(d)!=ref.end()){
      mp[d]++;
      continue;
    }

    long inv=1; // かけたら立方数になる相手

    for(long p : primes){ //素因数分解
      int cnt=0;
      while(d%p==0){
        d/=p;
        cnt++;
      }
      if(cnt==1) inv *= p*p;
      if(cnt==2) inv *= p;
      if(d==1) break;
      //if(p>2500) break;
    }

    // N^(1/3) までの素因数を取り出したので，残る因数はそれ以上
    if(d!=1){
      /*long r = sqrt(d)+0.0001;
      if(d == r*r){
        inv *= r;
      } else {
        inv *= d*d;
      }*/ res++;continue;
    }

    mp[vec[i]]++;
    ref[vec[i]]=inv;
    ref[inv]=vec[i];
  }

  for(auto m : mp) if(m.se != 0){
    auto f = mp.find(ref[m.fi]);
    if(f!=mp.end()){
      res += max(m.se, f->se);
      f->se = 0;
    } else {
      res += m.se;
    }
  }

  cout << res << endl;

  return 0;
}

