inline ll sq(ll x)
{
	if(x<0) return -1;
	ll w=sqrt(x)-1;
	for(ll i=w;i<=w+2;++i)
		if(i>=0&&x==i*i) return i;
	return -1;
}
int ps[SZ],pn=0; bool np[SZ];
ll op(ll x)
{
	ll s=1;
	for(int i=1;ps[i]*(ll)ps[i]*ps[i]<=x;++i)
	{
		int c=0; while(x%ps[i]==0) x/=ps[i],++c;
		c=(3-c)%3; while(c--) s=s*ps[i];
	}
	if(x==1) return s; //1
	ll p=sq(x); if(p>0) return s*p; //p^2
	return s*x*x; //pq or p
}
ll fj(ll x)
{
	for(int i=1;ps[i]*(ll)ps[i]*ps[i]<=x;++i)
	{
		ll s=ps[i]*(ll)ps[i]*ps[i];
		while(x%s==0) x/=s;
	}
	return x;
}
