	for(int i=2;i<mini_prime.size();i++){
		if(mini_prime[i]==0){
			primes.push_back(i);
			mini_prime[i]=i;
			for(int j=i*2;j<mini_prime.size();j+=i)mini_prime[j]=i;
		}
	}

	int N;
	cin>>N;

	vector<long long> s(N);

	for(int i=0;i<N;i++){
		scanf("%lld",&s[i]);
	}

	map<long long,int> mp;

	for(int i=0;i<N;i++){
		for(long long j=2;j*j*j<=10000000000;j++){

			while(s[i]%(j*j*j)==0)s[i] /= j*j*j;
		}
		mp[s[i]] ++;
	}

	int ans = 0;

	for(long long i=2;i<=100000;i++){
		//cout<<i<<endl;
		map<int,int> num;
		int now = i;
		while(now!=1){
			num[mini_prime[now]]++;
			now /= mini_prime[now];
		}

