      k %= 3;

      if(k==1){
        now *= p[j];
        opp *= p[j];
        opp *= p[j];
      } else if(k==2){
        now *= p[j];
        now *= p[j];
        opp *= p[j];
      }
    }
    now *= S[i];
    opp *= S[i];
    opp *= S[i];

    if(now==1){
      res = 1;
      continue;
    }

    if(now < opp){
      mp[now].first++;
    } else {
      mp[opp].second++;
    }
  }

  for(map<ll,pair<int,int> >::iterator it = mp.begin(); it != mp.end(); it++){
    res += max(it->second.first, it->second.second);
  }
  writerLn(res);

