bool prime(int v)
{
    for (int d = 2; d * d <= v; ++d)
    {
        if (v % d == 0)
            return 0;
    }

    return 1;
}


int square(int v)
{
    int u = get_square(v);
    return u * u == v;
}


int get_square(int v)
{
    int c = sqrt(v);
    for (int i = max(0LL, c - 5); i <= c + 5; ++i)
        if (i * i == v)
            return i;

    return c;
}


