int jeb(int x)
{
	int res = x, odwr = 1;
	for (auto it: prim) {
		int sz = it*it*it;
		if (sz > x) {
			if (odwr != -1 && odwr*it > INF && x%it == 0)
				odwr = -1;
			if (odwr != -1) {
				if (x%(it*it) == 0)
					odwr *= it;
				else if (x%it == 0)
					odwr *= it*it;
			}
			break;
		}
		while (x%sz == 0)
			x /= sz;
		if (odwr != -1 && odwr*it > INF && x%it == 0)
			odwr = -1;
		if (odwr != -1) {
			if (x%(it*it) == 0)
				odwr *= it;
			else if (x%it == 0)
				odwr *= it*it;
		}
	}
	odw[x] = odwr;
	return x;
}

int jeb2(int x)
{
	int res = 1;
	for (auto it: prim) {
		if (res > INF)
			return -1;
		if (it > x)
			break;
		if (x%it)
			continue;
		if (res*it > INF)
			return -1;
		if (x%(it*it) == 0) {
			res *= it;
			x /= it*it;
		}
		else {
			res *= it*it;
			x /= it;
		}
	}
	return res > INF ? -1 : res;
}

bool sze(int x)
{
	int co = pow(x, 0.3);
	while (co*co*co < x)
		++co;
	while (co*co*co > x)
		--co;
	return co*co*co == x;
}

