using namespace std;

typedef long long ll;
typedef pair<int, int> pii;
const int maxn = 1e5 + 5;
const ll limit = 1e10;
int N, p_cnt, is_exceed[maxn], Ans;
int not_prime[maxn], prime[maxn];
ll S[maxn], T[maxn], p_2[maxn], p_3[maxn];

vector<pii> vec[maxn];
map<ll, int> mp, jsq;

void pre_work() {
  for (int i = 2; i <= 100000; i++) {
    if (!not_prime[i]) prime[++p_cnt] = i;
    for (int j = 1; j <= p_cnt && i * prime[j] <= 100000; j++) {
      not_prime[i * prime[j]] = 1;
      if (i % prime[j] == 0) break;
    }
  }
  for (int i = 1; i <= p_cnt; i++) mp[prime[i] * prime[i]] = prime[i];
  for (int i = 1; i <= p_cnt; i++) p_2[i] = 1LL * prime[i] * prime[i];
  for (int i = 1; i <= p_cnt; i++) p_3[i] = 1LL * p_2[i] * prime[i];
}

int main() {
  scanf("%d", &N), pre_work();
  for (int i = 1; i <= N; i++) scanf("%lld", &S[i]);
  for (int i = 1; i <= N; i++) {
    for (int j = 1; p_3[j] <= limit; j++) {
      while (!(S[i] % p_3[j])) S[i] /= p_3[j];
      int times = (!(S[i] % prime[j])) + (!(S[i] % p_2[j]));
      if (times) vec[i].push_back(make_pair(prime[j], times));
      while (!(S[i] % prime[j])) S[i] /= prime[j];
    }
    if (S[i] != 1) {
      if (!mp.count(S[i])) {
        Ans++, is_exceed[i] = 1;
        continue;
      }
      vec[i].push_back(make_pair(mp[S[i]], 2));
    }
    S[i] = T[i] = 1;
    for (S[i] = T[i] = 1; vec[i].size(); vec[i].pop_back()) {
      pii tail = vec[i].back();
      assert(tail.second == 1 || tail.second == 2);
      S[i] *= tail.first, T[i] *= tail.first;
      (tail.second == 2 ? S[i] : T[i]) *= tail.first;
    }
    jsq[S[i]]++;
  }
  if (jsq.count(1)) Ans++, jsq[1] = 0;
  for (int i = 1; i <= N; i++) {
    if (is_exceed[i] || !jsq[S[i]]) continue;
    Ans += max(jsq[S[i]], jsq[T[i]]);
    jsq[S[i]] = jsq[T[i]] = 0;
  }
  printf("%d\n", Ans);
  return 0;
}

