int read() {
  if (scanf("%d", &n) < 1) {
    return 0;
  }
  res = 0;
  pairs.clear();
  cnt.clear();
  for (int i = 0; i < n; ++i) {
    long long x;
    scanf("%lld", &x);

    long long nx = 1;
    long long y = 1;
    for (int i = 0; i < cntp; ++i) {
      int p = ps[i];
      if (p >= (int) 3e3) {
        break;
      }
      if (x % p) {
        continue;
      }
      int ti = 0;
      for (; x % p == 0; x /= p) {
        ++ti;
      }
      ti %= 3;
      if (ti) {
        for (int j = 0; j < ti; ++j) {
          nx *= p;
        }
        long long np = 1;
        for (int j = ti; j < 3; ++j) {
          np *= p;
        }
        if (y > (long long) 1e10 / np) {
          y = (long long) 1e10 + 1;
          break;
        }
        y *= np;
      }
    }
    if (y > (long long) 1e10) {
      ++res;
      continue;
    }

    if (x > 1) {
      long long p = sqrt(x);
      if (p * p == x) {
        nx *= x;
        y *= p;
      } else {
        if (y > (long long) 1e10 / x / x) {
          ++res;
          continue;
        }
        nx *= x;
        y *= x * x;
      }
    }

    x = nx;

    if (x == 1) {
      cnt[x] = 1;
    } else {
      cnt[x] += 1;
    }

    if (x > y) {
      swap(x, y);
    }
    pairs.insert(mp(x, y));
  }
  return 1;
}

