long long getInv (long long x) {
	x = getRad(x);
	long long y = 1;
	for (int i = 0; i < sz(p); ++i) {
		int num = 0;
		while (x % p[i] == 0) {
			x /= p[i];
			num++;
		}
		if (num == 1) {
			y = min(inf64, y * sqr(p[i]));
	   	} else if (num == 2) {
	   		y = min(inf64, y * p[i]);
	   	}
	}

	if (x > 1) {
		int sqrt_x = round(sqrt(x));
		if (sqrt_x * sqrt_x == x) {
			y = min(inf64, y * sqrt_x);
		} else if (x < sqrt(inf64)) {
			y = min(inf64, y * sqr(x));
		} else {
			y = inf64;
		}
	}

	return y;
}

