		    for(int i = 0 ; i < 2 ; ++i) {
			op = op * x;
			if(op > 1e10) goto fail;
		    }
		}
		else {
		    goto fail;
		}
	    }

	    if(op > num) ans -= min(zz[num],zz[op]);
	}
        fail:;
    }
    out(ans);enter;
}

