		b /= 10; cnt++;
	}
	return cnt <= 10;
}

pl ntn(ll a) {
	map<ll, int> res;
	for(ll i = 2; i <= 3000; i++) {
		while(a % i == 0) {
			res[-i]++;
			a /= i;
		}
	}
	int sa = (ll)sqrt(a);
	if(a != 1) {
		if(a == sa * sa) res[-sa] += 2;
		else res[-a]++;
	}
	// debug(vector<pl>(all(res)));

	pl pre1 = pl(1, 1);
	pl pre2 = pl(1, 1);
	bool fst = true;
	for(auto p : res) {
		p.sec %= 3;
		if(p.sec == 0) continue;
		ll v = -p.fst;
		if(fst) {
			update(pre1, v, p.sec);
			fst = false;
		}
		else update(pre2, v, p.sec);
	}
	// debug(pre1, pre2);
	if(ok(pre1.sec, pre2.sec)) {
		return pl(pre1.fst * pre2.fst, pre1.sec * pre2.sec);
	}
	else return pl(pre1.fst * pre2.fst, -1);
}

