const int N = 1e5 + 7;
const int A = 2200;


map<ll, ll> mp;
bool mark[N];
vector<ll> p;

int main()
{
	ios::sync_with_stdio(false);

	int n, ans = 0;
	cin >> n;
	for (int i=2; i<N; i++)
	{
		if (mark[i])
			continue;
		p.push_back(i);
		for (int j=i; j<N; j+=i)
			mark[j] = 1;
	}
	for (int i=0; i<n; i++)
	{
		ll x;
		cin >> x;
		for (int j=0; j<(int)p.size() && p[j] < A; j++)
		{
			ll t = p[j] * p[j] * p[j];
			while (x % t == 0)
				x /= t;
		}
		if (x == 1)
			ans = 1;
		else
			mp[x]++;
	}
	for (auto& x : mp)
	{
		ll tmp = x.first, y = x.first;
		ll num = 1;
		for (int i=0; i<(int)p.size(); i++)
		{
			if (tmp % (p[i] * p[i]) == 0)
				tmp /= p[i];
			else if (tmp % p[i] == 0)
				num *= p[i];
			while (y % p[i] == 0)
				y /= p[i];
		}
		if (y != 1)
			ans += x.second;
		else if (num * tmp > x.first)
			ans += max(x.second, mp.count(num * tmp) ? mp[num * tmp] : 0LL);
	}
	cout << ans << "\n";
	return 0;
}

