inline ll rd()
{
	ll x=0;char ch=getchar();
	for (;ch<'0'||ch>'9';ch=getchar());
	for (;ch>='0'&&ch<='9';ch=getchar()) x=x*10+ch-'0';
	return x;
}

inline ll gcd(ll x,ll y) { return (!y)?x:gcd(y,x%y); }

inline ll tms(ll x,ll y,ll p)
{
	ll hh=(ldb)x/p*y+1e-3;
	return ((x*y-hh*p)%p+p)%p;
}

inline ll ksm(ll x,ll y,ll p)
{
	ll res=1;
	for (;y;y>>=1,x=tms(x,x,p)) if (y&1) res=tms(res,x,p);
	return res;
}

inline bool check(ll x,ll y,ll z,ll n)
{
	ll hh=ksm(x,y,n),now=hh;
	for (ll i=1;i<=z;i++)
	{
		hh=tms(hh,hh,n);
		if (hh==1&&now!=1&&now!=n-1) return true;
		now=hh;
	}
	if (hh!=1) return true;
	return false;
}

inline bool miller_rabin(ll n)
{
	if (n==2) return true;
	if (n%2==0) return false;
	ll hh=n-1,hhh=0;
	while (hh%2==0) hh>>=1,hhh++;
	for (int i=1;i<=10;i++) if (check((ll)rand()*rand()%(n-1)+1,hh,hhh,n)) return false;
	return true;
}

inline ll pollard_rho(ll a,ll n)
{
	ll k=2,x=(ll)rand()*rand()%n,y=x,p=1;
	for (ll i=1;p==1;i++)
	{
		x=(tms(x,x,n)+a)%n;
		p=gcd(n,abs(x-y));
		if (i==k) y=x,k<<=1;
	}
	return p;
}

inline void find_fac(ll n)
{
	if (n==1) return;
	if (miller_rabin(n)) { ans[++tot]=n;return; }
	ll hh=n;
	while (hh==n) hh=pollard_rho((ll)rand()*rand()%(n-1)+1,n);
	find_fac(hh);find_fac(n/hh);
}

