vector<ll> p, Mat[MAXN];
bool isp[MAXN], se[MAXN];
int cnt[MAXN], sh, shr;

ll getmsk(ll t) {
	for (int i = 0; p[i] * p[i] * p[i] <= t; i++) {
		ll r = p[i] * p[i] * p[i];
		while (t % r == 0)
			t /= r;
	}
	return t;
}
ll rmsk(ll t) {
	ll m = 1;
	for (int i = 0; p[i] * p[i] <= t; i++) {
		if (t % (p[i] * p[i]) == 0)
			m *= p[i], t /= p[i] * p[i];
		else if (t % p[i] == 0)
			m *= p[i] * p[i], t /= p[i];
	}
	if (t != 1)
		m *= t * t;
	return m;
}

void dfs(int v, bool cl) {
	se[v] = 1;
	sh += cnt[v];
	if (cl)
		shr += cnt[v];
	for (int i = 0; i < Mat[v].size(); i++)
		if (!se[Mat[v][i]])
			dfs(Mat[v][i], !cl);
}

