LL powmod(LL a, LL n){
	if(n == 0) return 1;
	if(n % 2) return (a*powmod(a,n-1)) % MOD;
	LL c = powmod(a,n/2);
	return (c*c) % MOD;
}
map<LL,int> r;
void gen(LL k){
	if(r.find(k) == r.end()){
		r[k] = rand() % MOD + 1249;
	}
