  int n; cin >> n;
  V<lint> a(n); for (int i = 0; i < n; ++i) cin >> a[i];
  auto ps = sieve(2, 2154);
  for (int i = 0; i < n; ++i) {
    for (lint p : ps) {
      while (a[i] % (p * p * p) == 0) {
        a[i] /= p * p * p;
      }
    }
  }
  V<lint> cb;
  for (lint i = 2; i * i <= 1e10; ++i) {
    cb.push_back(i * i * i);
  }
  int res = 0;
  map<lint, int> mp;
  for (int i = 0; i < n; ++i) {
    if (a[i] == 1) {
      res = max(res, 1);
    } else {
      ++mp[a[i]];
    }
  }
  for (const auto& e : mp) {
    bool found = false;
    int l = lower_bound(begin(cb), end(cb), pow(e.first, 1.5)) - begin(cb);
    int u = upper_bound(begin(cb), end(cb), pow(e.first, 3)) - begin(cb);
    for (int i = l; i < u; ++i) {
      if (cb[i] % e.first == 0) {
        found = true;
        if (e.first > cb[i] / e.first) break;
        res += max(e.second, mp.count(cb[i] / e.first) ? mp[cb[i] / e.first] : 0);
        break;
      }
    }
    if (!found) {
      res += e.second;
    }
  }
  cout << res << '\n';
}

