using namespace std;

typedef pair<int, int> P;

int normalize(int s) {	//正整数n, mで「n * m^3 = s」と表すときの最大のmをMとおき、s/M^3を返す。
	int n, m;
	double eps1 = 1e-10;
	double eps2 = 1e-9;

	for (n = 1; n <= 316; n++) {
		if (s % n == 0) {
			double md = pow(s / n, 1.0 / 3) + eps1;
			int m = (int)md;
			if (md - m <= eps2) {
				return s / (m * m * m);
			}
		}
	}
	for (m = 316; m >= 1; m--) {
		if (s % (m * m * m) == 0) {
			return s / (m * m * m);
		}
	}
	return -1;
}

bitset<400000001> bset;
int primeCnt, primes[1000];
void prepare() {
	int i, j;

	for (i = 1; i <= 20000; i++) {
		bset[i * i] = 1;
	}

	bool isPrime[2201] = {false};
	for (i = 2; i <= 2200; i++) {
		isPrime[i] = true;
	}

	primeCnt = 0;
	for (i = 2; i <= 2200; i++) {
		if (isPrime[i]) {
			primes[primeCnt++] = i;
			for (j = i * 2; j <= 2200; j += i) {
				isPrime[j] = false;
			}
		}
	}
}

int findPair(int s) {	//正整数n, mで「n * m^2 = s」と表すときの最大のmをMとおき、(s / M^2)^2 * Mを返す。
	int n, m;
	double eps1 = 1e-10;
	double eps2 = 1e-9;

	for (n = 1; n <= 2200; n++) {
		if (s % n == 0) {
			if (n >= 50) {
				if (bset[s / n]) {
					m = (int)(sqrt((double)s / n) + eps1);
					return n * n * m;
				}
			}
			else {
				double md = sqrt((double)s / n) + eps1;
				int m = (int)md;
				if (md - m <= eps2) {
					return n * n * m;
				}
			}
		}
	}

	m = 1;
	for (int i = 0; i < primeCnt; i++) {
		int p = primes[i];
		if (s % (p * p) == 0) {
			m *= p;
		}
	}

	n = s / (m * m);
	if (n > 100000) return -1;
	return n * n * m;
}

int n;
int s[100000];
map<int, int> cntMp;
vector<P> pairs;

signed main() {
	int i;

	prepare();
	scanf("%lld", &n);
	rep(i, n) { scanf("%lld", s + i); s[i] = normalize(s[i]); cntMp[s[i]]++; }
	rep(i, n) {
		int t = findPair(s[i]);
		if (s[i] <= t) pairs.push_back(P(s[i], t));
		else pairs.push_back(P(t, s[i]));
	}
	sort(pairs.begin(), pairs.end());
	pairs.erase(unique(pairs.begin(), pairs.end()), pairs.end());

	int ans = 0;
	rep(i, pairs.size()) {
		int u = pairs[i].first;
		int v = pairs[i].second;
		if (u == 1) { ans++; continue; }
		ans += max(cntMp[u], cntMp[v]);
	}
	cout << ans << endl;
	return 0;
}

