            }
        }


        if (x != 1)
        {
//            eprintf("??\n");
            int pos = lower_bound(ps.begin(), ps.end(), x) - ps.begin();
            if (pos != (int) ps.size() && ps[pos] == x)
            {
                h1 ^= ph[pos].first;
                h2 ^= ph[pos].second;
            }
            else
            {
                int sqrt = getSqrt(x);

                if (sqrt == -1)
                {    
                    ans++;
                    continue;
                }

                pos = lower_bound(ps.begin(), ps.end(), sqrt) - ps.begin();
                h1 ^= ph[pos].second;
                h2 ^= ph[pos].first;
            }
        }

//        eprintf("%lld %lld\n", h1, h2);
        cnt[make_pair(h1, h2)]++;
        if (!cnt.count(make_pair(h2, h1)))
            cnt[make_pair(h2, h1)] = 0;
    }
 //   eprintf("!!\n");

    for (auto &p : cnt)
    {
        auto key = p.first;
        auto value = p.second;

        if (key.first == 0)
        {
            ans++;
            continue;
        }

        if (key.second < key.first)
            continue;

        ans += max(value, cnt[make_pair(key.second, key.first)]);

    }

    printf("%d\n", ans);


	return 0;
}

