vector <ll> Pr;
int d[mk + 5];

unordered_map <ll,int> occurance;

unordered_map <ll,pii> cnt;


vector < pii > Rev; 


void Sieve()
{

    for(int i = 2; i <= mk; i++) {
	    if(d[i]) Pr.push_back(i);
	    for(int j = 0 ; Pr[j] * i <=mk&& j < Pr.size() && Pr[j] <= d[i] ; j++) {
	    	d[i * Pr[j]] = Pr[j];
		}
	}
}
inline pair<ll,ll> root(ll x)
{
    ll val=1,reverse_val=1;
    for (auto i: Pr)
    {
        if(i*i>x) break;
        if(x%i==0)
        {
            int num=0;
            while(x%i==0)
            {
                num++;
                x/=i;
            }
            num%=3;
            for(int j = 0 ; j < num ; j++) val *= i;
            for(int j = 0 ; j < 3 - num) reverse_val *= i;
        }
    }
    if(x>1)
    {
    	int num = 1; 
    	for(int i = 0 ; i < num; i++) val *= x; 
    	for(int i = 0 ; i < 3 - num ; i++) reverse_val *= x; 
    }
    return mp(val,reverse_val);
}


void solve()
{
    Sieve();
    int n;
    cin >> n;
    for (int i = 1; i <= n; i++)
    {
        ll x; cin >> x; 
        if(cnt.count(x)==0)
        {
            pair<ll,ll> cur= root(x);
            Rev.push_back(cur);
            cnt[x]=cur;
        }
        else
            Rev.push_back(cnt[x]);
            occurance[Rev.back().first]++;
    }
    ll ans=0;
    if(occurance[1]>=1) ans++;
    for (int i = 0; i < n; i++)
    {

        ll value = Rev[i].first;
        int cur_val = occurance[value];
        if(cur_val==0) continue;
        if(value==1) continue;
        ll rever = Rev[i].second;
        ans += max(cur_val, occurance[rever]);
        occurance[rever]=0;
        occurance[value]=0;
       /// cout <<  " Miku huhuhu"
    }
    cout << ans << endl;
}

int main()
{
    solve();
}

