const int M = 3000;
bool used[M];
vector<int> ps;
map< pair<ll, ll>, int > mp;

void first() {
    for (int i = 2; i < M; i++) {
        if (used[i]) continue;
        for (int j = i * i; j < M; j += i) {
            used[j] = true;
        }
    }
    for (int i = 2; i < M; i++) {
        if (!used[i]) ps.push_back(i);
    }
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    first();
    int n;
    cin >> n;
    for (int i = 0; i < n; i++) {
        ll x;
        cin >> x;
        ll g1 = 1, g2 = 1;
        for (int j = 0; j < int(ps.size()); j++) {
            ll p = ps[j];
            if (p * p * p > x) break;
            int e = 0;
            while (x % p == 0) {
                x /= p;
                e++;
            }
            e %= 3;
            if (e == 1) g1 *= p;
            else if (e == 2) g2 *= p;
        }
        ll r = sqrt(x);
        if (r * r == x) g2 *= r;
        else g1 *= x;
        mp[make_pair(g1, g2)]++;
    }

    int ans = 0;
