  vector<long long> v(n);
  for(int i=0; i<n; i++){
    scanf("%lld", &v[i]);
  }
  auto P = Eratosthenes(100000);

  map<long long, long long> square;
  for(auto p : P){
    square[p*p] = p;
  }

  vector<long long> cube;
  for(long long i=2; i*i*i <= 10_ten; i++){
    cube.push_back(i*i*i);
  }

  vector<long long> vp(n, 1);
  vector<long long> vc(n, 0);
  vector<long long> vk(n, 0);

  long long ans = 0;
  bool zero = false;
  vector<pair<int,long long>> u;

  for(auto i : range(n)){
    for(auto c : cube){
      while( v[i] % c == 0 ){
        v[i] /= c;
      }
    }
  }

  for(auto i : range(n) ){
    if(v[i] == 1) zero = true;
    else u.push_back({i, v[i]});
  }

  if(zero) ans++;


  for(auto p : P){
    if( p >= 2155 ) break;
    if(u.size() == 0) break;
    vector<pair<int,long long>> u_;
    for(auto& x : u){
      if(x.second % p != 0){
        u_.push_back( x );
        continue;
      }

      int cnt = 0;
      while(x.second % p == 0){
        x.second /= p;
        cnt++;
      }

      if(cnt%3 != 0){
        if(cnt%3 == 2) vk[x.first] |= 1LL << (vc[x.first]);
        vp[x.first] *= p;
        vc[x.first] ++;
      }

      if(x.second != 1){
        u_.push_back(x);
      }
    }

    swap(u, u_);
  }

  for(auto& x : u){
    if( square.count(x.second) ){
      vk[x.first] |= 1LL << (vc[x.first]);
      vp[x.first] *= ( square[x.second] );
      vc[x.first]++;
    }else{
      vp[x.first] *= ( x.second );
      vc[x.first]++;
    }
  }

  map<pair<long long, long long>, map<long long, long long>> G;

  for(int i=0; i<n; i++){
    if(vc[i] == 0) continue;
    G[ {vp[i], vc[i]} ][ vk[i] ] += 1;
  }

  for(auto& ps : G){
    set<long long> used;
    for(auto& pr : ps.second){
      if( used.count( pr.first ) ) continue;
      auto inv = (~pr.first) & ((1LL<<ps.first.second) - 1);

      if( ps.second.count( inv ) == 0 ){
        ans += pr.second;
      }else{
        ans += max(pr.second, ps.second[inv]);
        used.insert(inv);
      }
    }
  }

  println(ans);

  return 0;
}

