    int cnt = 1;
    for (int i = 1; i < n; i++) {
        if (a[i].first == a[i - 1].first) {
            cnt++;
        } else {
            nums[id] = a[i - 1].first;
            inv[id] = a[i - 1].second;
            ccnt[id] = cnt;
            id++;
            cnt = 1;
        }
    }
    if (cnt != 0) {
        nums[id] = a[n - 1].first;
        inv[id] = a[n - 1].second;
        ccnt[id] = cnt;
        id++;
    }
    for (int i = 0; i < id; i++) {
        if (inv[i] == -1) continue;
        if(nums[i] == 1){
