i64 isqrt(i64 a) {
    i64 l = 0;
    i64 r = a;
    while (r - l > 1) {
        i64 m = (r + l) / 2;
        if (m * m > a) {
            r = m;
        } else {
            l = m;
        }
    }
    return l;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    rande.seed(chrono::steady_clock::now().time_since_epoch().count());

    int n;
    while (read(n)) {
        llvec a(n);
        read(a);

        i64 mxa = 0;
        fore(ai, a) {
            uax(mxa, ai);
        }

        llvec sp;
        for (i64 i = 2; i * i * i <= mxa; i++) {
            int c = 0;
            for (i64 j = 1; j * j <= i; j++) {
                if (i % j == 0) {
                    if (j * j == i) {
                        c++;
                    } else {
                        c += 2;
                    }
                }
            }
            if (c == 2) {
                sp.push_back(i);
            }
        }
        logs(mxa);
        logv(sp);
        vec<vec<llp>> fs(n);
        map<i64, int> cc;
        map<i64, i64> na;
        forn(i, n) {
            i64 an = 1;
            fore(p, sp) {
                llp cp{p, 0};
                while (a[i] % p == 0) {
                    a[i] /= p;
                    cp.second++;
                }
                cp.second %= 3;
                if (cp.second != 0) {
                    fs[i].push_back(cp);
                }
                forn(j, cp.second) {
                    an *= cp.first;
                }
            }
            if (a[i] != 1) {
                i64 sq = isqrt(a[i]);
                an *= a[i];
                if (sq * sq == a[i]) {
                    fs[i].emplace_back(sq, 2);
                } else {
                    fs[i].emplace_back(a[i], 1);
                }
            }
            cc[an]++;
            i64 aa = 1;
            for (auto [p, c] : fs[i]) {
                if (c == 2) {
                    aa *= p;
                } else {
                    aa *= p * p;
                }
            }
            na[an] = aa;
        }
        i64 ans = 0;
        set<i64> gs;
        fore(kv, cc) {
            auto nc = na.count(kv.first) && cc.count(na[kv.first]) ? cc[na[kv.first]] : 0;
            if (kv.first == 1) {
                ans += 1;
            } else {
                if (kv.second > nc) {
                    gs.insert(kv.first);
                } else if (kv.second == nc) {
                    gs.insert(min(kv.first, na[kv.first]));
                } else {
                    gs.insert(na[kv.first]);
                }
            }
        }
        logvp(cc);
        logvp(na);
        logv(gs);
        fore(g, gs) {
            ans += cc[g];
        }
        cout << ans << endl;
    }
}

