namespace rho{
	ll mul(ll x,ll y,ll z){
		x%=z,y%=z;
		if(z<=2e9)return (x*y%z+z)%z;
		return (x*y-(ll)(x/(long double)z*y)*z+z)%z;
	}
	ll qp(ll a,ll b,ll mo){ll ans=1;do{if(b&1)ans=mul(ans,a,mo);a=mul(a,a,mo);}while(b>>=1);return ans;}
	ll gcd(ll a,ll b){return b?gcd(b,a%b):a;}
	int pr[9]={2,3,5,7,11,13,17,19,23};
	ll tmp[100];int tot;
	ll ps[100],ds[100];int ptot;
	int mr(ll n){
	    if(n<=1)return 0;
	    for (int i=0,a;i<9;i++){
		if((a=pr[i])==n)return 1;
		ll t=n-1;int k=0;
		while(~t&1)t>>=1,k++;
		ll c=qp(a,t,n);
		if(c==1)continue;
		int bo=0;
		for (int i=0;i<k;i++){
		    if(c==n-1){bo=1;break;}
		    c=mul(c,c,n);
		}
		if(!bo)return 0;
	    }
	    return 1;
	}
	void rho(ll n){
	    if(mr(n))tmp[++tot]=n;
	    else{
		for (int c=12345;;c++){
		    ll x=0,y=0;
		    while(1){
			x=(mul(x,x,n)+c)%n;
			y=(mul(y,y,n)+c)%n;
			y=(mul(y,y,n)+c)%n;
			ll d=gcd(n,abs(x-y));
			if(d!=1){
			    if(d!=n){
				rho(d);
				rho(n/d);
				return;
			    }else break;
			}
		    }
		}
	    }
	}
	void facto(ll n){
		tot=0;
		for (int i=0;i<9;i++)while(n%pr[i]==0){
		    tmp[++tot]=pr[i];
		    n/=pr[i];
		}
		if(n>1)rho(n);
		sort(tmp+1,tmp+1+tot);
		ptot=0;
		for (int i=1;i<=tot;i++)
			if(i==1 || tmp[i]!=tmp[i-1]){
				ps[++ptot]=tmp[i];
				ds[ptot]=1;
			}else ds[ptot]++;
	}
};

