        if (yy >= 3){
            yy%=3;

        }
        n *= (ll)pow(xx,yy);
        if(yy!=0) {p *= (ll)pow(xx,3 - yy);}
    }
    np.push_back(n);
    np.push_back(p);
    return np;
}

