ll stupid_pow(ll base, int e) {
	ll ans=1;
	while (e>0) ans*=base, e--;
	return ans;
}

ll compute_norm(ll n) {
	ll i=1, ans=n;
	while (stupid_pow(i, 3)<=n) {
		ll tmp=stupid_pow(i, 3);
		if (n%tmp==0) ans=n/tmp;
		i++;
	}
	return ans;
}

bool is_square(ll n) {
	for (int i=0; primes[i]*primes[i]<=n; i++)
		if (primes[i]*primes[i]==n) return true;
	return false;
}

ll compute_pair(ll n) {
	ll ans=1;
	for (int i=0; primes[i]<2500; i++) {
		int e=0;
		while (n%primes[i]==0) e=(3+e-1)%3, n/=primes[i];
		ans*=stupid_pow(primes[i], e);
	}
	if (is_square(n)) ans*=sqrt(n);
	else ans*=n*n;
	return ans;
}

