    if(leftover * leftover != amt) {
      // printf("a %lld %d\n", x.first, x.second);
      // used.insert(x.first);
      // ret += x.second;
      continue;
    }
    if(pComp >= 100000) {
      // printf("b %lld %d\n", x.first, x.second);
      // used.insert(x.first);
      // ret += x.second;
      continue;
    }
    qComp *= leftover;
    ll real = pComp * pComp * qComp;
    if(dp.count(real)) {
      ret += max(dp[real], dp[x.first]);
      used.insert(real);
      used.insert(x.first);
    }
    else {
      used.insert(x.first);
      ret += x.second;
    }
  }
  return ret;
}

