#define MOD 1000000007
using namespace std;
typedef long long LL;
LL a[110000];
vector<LL> p1, p2;

LL powmod(LL a, LL n){
	if(n == 0) return 1;
	if(n % 2) return (a*powmod(a,n-1)) % MOD;
	LL c = powmod(a,n/2);
	return (c*c) % MOD;
}
map<LL,int> r;
void gen(LL k){
	if(r.find(k) == r.end()){
		r[k] = rand() % MOD + 1249;
	}
}
int main(){
	srand(15);
	int n;
	cin >> n;
	for(int i = 0; i < n; i++) cin >> a[i];
	map<LL,int> d;
	int n1 = 0;
	vector<int> q;
	for(int j = 2; j < 2200; j++){
		int ok = 1;
		for(int z = 2; z*z <= j; z++){
			if(j % z == 0){
				ok = 0;
				break;
			}
		}
		if(ok) q.push_back(j);
	}
	for(int z = 0; z < n; z++){
		p1.clear();
		p2.clear();
		for(int i = 0; i < q.size(); i++){
			LL j = q[i];
			LL p = j*j*j;
			while(a[z] % p == 0){
				a[z] /= p;
			}
			p = j;
			if(a[z] % (p*p) == 0){
				p2.push_back(p);
				a[z] /= (p*p);
			}
			if(a[z] % (p) == 0){
				p1.push_back(p);
				a[z] /= (p);
			}
		}
		if(a[z] > 1){
			LL c = sqrt(a[z]);
			if(c*c == a[z]){
				p2.push_back(c);
			} else {
				p1.push_back(a[z]);
			}
		}
		if(p1.empty() && p2.empty()){
			n1 = 1;
			continue;
		}
		LL h1 = 0;
		LL h2 = 0;
		for(int i = 0; i < p1.size(); i++){
			gen(p1[i]);
			//cout << p1[i] << " " << r[p1[i]] << endl;
			h1 += r[p1[i]];
		}
		h1 %= MOD;
		for(int i = 0; i < p2.size(); i++){
			gen(p2[i]);
			//cout << p2[i] << " " << r[p2[i]] << endl;
			h2 += r[p2[i]];
		}
		//cout << h1-h2 << endl;
		h2 %= MOD;
		d[h1-h2]++;
		d[h2-h1]++;
		d[h2-h1]--;
	}
	LL ans = 0;
	for(map<LL,int>::iterator it = d.begin(); it != d.end(); it++){
		ans += max(d[it->first],d[-it->first]);
	}
	ans /= 2;
	ans += n1;
	cout << ans << endl;
}

