using ll = __int128;

const int max_N = 1e5 + 21;

int n,ans;

bool vis[max_N];

std::vector<int>pri;

std::map<ll,int>Norm,Pair;

std::vector<ll>tmp;

inline void jzp(int n){
	for(int x=2;x<=n;++x){
		if(!vis[x])pri.push_back(x);
		for(auto&y:pri){
			if((ll)x*y>n)break;
			vis[x*y]=1;
			if(!(x%y))break;
		}
	}
}

inline void get_norm(ll x){
	for(auto&y:pri){
		ll z=1ll*y*y*y;
		if(z>x)break;
		while(!(x%z))x/=z;
	}
	if(++Norm[x]==1&&!Pair[x])
		tmp.push_back(x);
}

inline void get_pair(ll x){
	ll t=x,res=1;
	for(auto&y:pri){
		ll z=(ll)y*y*y;
		if(z<=t){
			while(!(x%z))x/=z;
			if(!(x%(y*y))){
				res*=y;
				x/=(y*y);	
			}
			else if(!(x%y)){
				res*=(y*y);
				x/=y;
			}
		}
		else{
			ll w=(ll)y*y;
			if(w>x){
				res*=((ll)x*x);
				break;
			}
			else if(!(x%y)){
				if(x==w)res*=y;
				else res*=((ll)x*x);
				break;
			}
		}
	}
	if(++Pair[res]==1&&!Norm[res])
		tmp.push_back(res);
}

int main(){
	jzp(1e5);
	scanf("%d",&n);
	while(n--){
		long long s;
		scanf("%lld",&s);
		get_norm(s),get_pair(s);
	}
	for(auto&x:tmp)
		if(x!=1){
			ans+=std::max(Norm[x],Pair[x]);
		}
	ans>>=1;
	if(Norm[1]>0)++ans;
	printf("%d\n",ans);
	return 0;
}

