#include <bits/stdc++.h>
using LL = long long;
const int N = 1e5 + 5;
int visited[N], p[N], tot;

void Prime() {
  for (int i = 2; i < N; i++) {
    if (!visited[i]) p[tot++] = i;
    for (int j = 0; j < tot && i * p[j] < N; j++) {
      visited[i * p[j]] = p[j];
      if (i % p[j] == 0) break;
    }
  }
}

int main() {
  std::ios::sync_with_stdio(0);
  Prime();
  int n;
  std::cin >> n;
  std::multiset<std::vector<std::pair<int, int>>> s;
  int zero = 0;
  for (int i = 0; i < n; i++) {
    LL x;
    std::cin >> x;
    std::vector<std::pair<int, int>> tmp;
    for (int j = 0; j < tot && 1LL * p[j] * p[j] <= x; j++) if (x % p[j] == 0) {
      int cnt = 0;
      while (x % p[j] == 0) {
        x /= p[j];
        cnt++;
      }
      cnt %= 3;
      if (cnt) {
        //std::cerr << p[j] << ' ' << cnt << std::endl;
        tmp.emplace_back(p[j], cnt);
      }
    }
    if (x == 1 && !tmp.size()) zero++;
    else if (x == 1) s.insert(tmp);
    else if (x != 1 && x < N) {
      tmp.emplace_back(x, 1);
      s.insert(tmp);
    }
  }
  std::cerr << "Zero: " << zero << std::endl;
  int nouse = 0;
  auto history = s;
  history.clear();
  for (auto &factor: s) {
    auto tmp = factor;
    if (history.count(factor)) continue;
    history.insert(factor);
    for (auto &p: tmp) {
      //std::cerr << p.first << ' ' << p.second << std::endl;
      p.second = (3 - p.second) % 3;
    }
    history.insert(tmp);
    nouse += std::min(s.count(factor), s.count(tmp));
  }
  std::cerr << "Nouse: " << nouse << std::endl;
  std::cout << n - zero - nouse + (zero > 0) << std::endl;
  return 0;
}

