int n;
ll s[N];
map<ll, ll> F;
map<ll, int> S;
int main() {
	prime();
	scanf("%d", &n);
	int ans = 0;
	rep(i, 0, n)
	{
		scanf("%lld", &s[i]);
		ll x = 1, y = 1;
		for (int j = 0; j < sz(pri) && pri[j] <= s[i]; ++j) {
			int c = 0;
			while (s[i] % pri[j] == 0)
				++c, s[i] /= pri[j];
			c %= 3;
			if (c == 1) {
				x *= pri[j], y *= pri[j] * pri[j];
			} else if (c == 2) {
				x *= pri[j] * pri[j], y *= pri[j];
			}
		}
		x *= s[i];
		if (x == 1) {
			ans = 1;
			continue;
		}
		++S[x];
		ll ss = sqrt(s[i]);
		if (ss * ss == s[i]) {
			y *= ss;
		} else if (s[i] <= (ll) (1e11) / s[i]) {
			y *= s[i] * s[i];
		} else {
			y = -1;
		}
		F[x] = y;
	}
	for (auto it : S)
		if (S.find(F[it.first]) == S.end()) {
			ans += it.second;
		} else if (F[it.first] > it.first) {
			ans += max(it.second, S[F[it.first]]);
		}
	printf("%d\n", ans);
	return 0;
}

