int main () {
	for (int i = 2; i < 3000; i ++) {
		bool F = 1;
		for (int j = 2; j*j <= i; j ++) 
			if (i%j == 0) {F = 0; break;}
		if (F) {
			p[L] = i;
			pb[L] = i*i;
			pc[L] = (ll)i*i*i;
			L ++;
		}
	}
	cin >> n;
	int S = 0;
	bool F1 = 0;
	for (int i = 0; i < n; i ++) {
		ll x;
		cin >> x;
		ll y = 1;
		ll x1 = 1;
		for (int j = 0; x != x1 && j < L; j ++) {
			while (x%pc[j] == 0) {
				x /= pc[j];
			}
			if (x%pb[j] == 0) {
				y *= p[j];
				x1 *= pb[j];
				if (y > INF) y = INF;
			} else
			if (x%p[j] == 0) {
				y *= pb[j];
				x1 *= p[j];
				if (y > INF) y = INF;
			}
		}
		x /= x1;
		if (y >= INF) {
			S ++; continue;
		}
		if (x != 1) {
			int c = sqrt(x); int cc = -1; 
			for (int d = max(1, c-10); d <= c+10; d ++)
				if ((ll)d*d == x) {
					cc = d; break;
				}
			if (cc == -1) {
				if (INF/x/x < y) {S ++; continue;}
				y *= x; y *= x;
			} else {
				y *= cc;
			}
		}
		if (y >= INF) {
			S ++; continue;
		}
		x *= x1;
		if (x == 1) {
			if (!F1) {
				F1 = 1;
				S ++;
			}
			continue;
		}
		F[x] ++;
		ra[x] = y;
	}

	for (map<ll,int>::iterator i = F.begin(); i != F.end(); i ++) {
		ll r = ra[i->fi];
		if (i->fi < r || F.find(r) == F.end()) {
			S += max(i->se, F[r]);
		}
	}
	cout << S << endl;
	return 0;
}

