const int MP = 100100;
vector<int> pr;

void first() {
    bool used[MP] = {};
    for (int i = 2; i < MP; i++) {
        if (used[i]) continue;
        pr.push_back(i);
        for (int j = 2*i; j < MP; j += i) {
            used[j] = true;
        }
    }
}

ull xor64(ull y) {
    y = y ^ (y<<13);
    y = y ^ (y>>7);
    y = y ^ (y<<17);
    return y;
}

ll pollard(ll n) {
    ll x = 2, y = 2, d = 1;
    while (d == 1) {
        x = xor64(x)%n;
        y = xor64(xor64(y)%n)%n;
        d = gcd(abs(x-y), n);
    }
    if (d == n) return -1;
    return d;
}

map<ll, int> factsmall(ll n) {
    map<ll, int> mp;
    for (int d: pr) {
        if (n < d*d) break;
        while (n % d == 0) {
            n /= d;
            mp[d]++;
        }
    }
    if (n > 1) mp[n]++;
    return mp;
}
map<ll, int> factc(ll n) {
    map<ll, int> mp;
    if (n <= TEN(10)) return factsmall(n);
    ll u = pollard(n);
    if (u == -1) {
        mp[n]++;
        return mp;
    }
    auto mp1 = factc(u);
    auto mp2 = factc(n/u);
    for (auto p: mp1) {
        mp[p.first] += p.second;
    }
    for (auto p: mp2) {
        mp[p.first] += p.second;
    }
    return mp;
}

