#include<bits/stdc++.h>
using namespace std;

typedef long long LL;
vector<LL> primes;
const LL CBRT = 2200;
LL cb[CBRT];
const LL LIM = 1e11+5;


void sieve() {
    vector<bool> isp(CBRT, 1);
    for (LL i=2; i<CBRT; i++)
        if (isp[i]) {
            primes.push_back(i);
            for (LL j=2*i; j<CBRT; j+=i)
                isp[j] = 0;
        }
    for (LL i=0; i<CBRT; i++)  cb[i] = 1LL*i*i*i;
}

pair<LL, LL> process(LL x) {
    if (x == 1)     return {1, 1};

    for (LL p:primes)
        while (x%cb[p]==0)  x/=cb[p];

    LL a = x;

    for (LL i=1; i<CBRT; i++)
        if (cb[i]%a==0)
            return {a, cb[i]/a};

    return {a, LIM};
}

