ull find_factor(ull z) {
    if (!(z&1)) return 2;
    ull c = rand() % z, x = 2, y = 2, d = 1;
    while (d == 1) {
        ull tp = (mul(y,y,z) + c) % z;
        y = (mul(tp,tp,z) + c) % z;
        x = (mul(x,x,z) + c) % z;
        d = __gcd(x>y ? x-y : y-x, z);
    }
    return d;
}
void rhofact(ull z) {
    if (z==1) return;
    if (isPrime(z)) { roz[z]++; return; }
    while(1) {
        ull f = find_factor(z);
        if (f != z) {
            rhofact(f);
            rhofact(z/f);
            break;
        }
    }
}

