vector<ll> primes;
vector<bool> mark(maxn, 0);

void sieve(){
  mark[1] = 1;
  for(int i = 2; i * i < maxn; i++){
    for(int j = 2; i * j < maxn; j++){
      mark[i * j] = 1;
    }
  }
  primes.push_back(2);
  for(int i = 3; i < maxn; i += 2){
    if(mark[i] == 0){
      primes.push_back(i);
    }
  }
}

ll fact(ll x){
  int p = 0;
  ll xx = 1;
  if(x % 2 == 0){
    while(x % 2 == 0){
      ++p;
      x /= 2;
    }
    p %= 3;
    xx = pow(2, p);
  }
  int sz = primes.size();
  for(int i = 1; primes[i] * primes[i] < x && i < sz; i++){
    if(x % primes[i] == 0){
      p = 0;
      while(x % primes[i]){
        ++p;
        x /= primes[i];
      }
      p %= 3;
      xx *= pow(primes[i], p);
    }
  }
  if(x > 1){
    xx *= x; 
  }
  return xx;
}

ll inv(ll x){
  ll xx = 1;
  int p = 0;
  while(x % 2 == 0){
    ++p;
    x /= 2;
  }
  p %= 3;
  if(p != 0){
    xx *= pow(2, 3 - p);
  }
  for(int i = 1; primes[i] * primes[i] < x; i++){
    if(x % primes[i] == 0){
      p = 0;
      while(x % primes[i] == 0){
        ++p;
        x /= primes[i];
      }
      p %= 3;
      if(p != 0){
        xx *= pow(primes[i], 3 - p);
      }
    }
  }
  if(x > 1){
    xx *= pow(x, 2);
  }
  return xx;
}

