  int n;
  scanf("%d", &n);
  sieve();
  for(int i = 1; i <= n; i++){
    scanf("%lld", &a[i]);
    a[i] = fact(a[i]);
    mp[a[i]]++;
  }
  int ans = n;
  for(int i = 1; i <= n; i++){
    ll x = inv(a[i]);
    if(mp[x] == 0 && mp[a[i]] == 0)continue;
    int cnt = mp[a[i]], cnt1 = mp[x];
    if(cnt > cnt1){
      ans -= cnt1;
    }else {
      ans -= cnt;
    }
    if(x == a[i])ans++;
    mp[x] = mp[a[i]] = 0;
  }
  cout << ans << endl;

  return 0;
}

