const int MAX = 100000 + 10;

bool pr[MAX];
vector<long long> prime;

map<long long,int> rec;
map<long long,int> mp;

void init(){
  for(int i = 2 ; i < 100000 ; i++){
    if(!pr[i]){
      prime.push_back((long long)i);
      for(int j = i+i ; j < 100000 ; j+=i){
        pr[j] = true;
      }
    }
  }
}

int main(){

  init();
  // 9592 prime numbers

  int n, ans = 0;
  scanf("%d", &n);
  for(int i = 0 ; i < n ; i++){
    long long t;
    scanf("%lld", &t);
    rec[t]++;
  }
  map<long long, int> :: iterator itr;
  for(itr = rec.begin(); itr != rec.end(); itr++){
    long long num = itr->first;
    int times = itr->second;
    long long now = num;
    long long boo = 1;
    for(int i = 0 ; i < (int)prime.size() && now >= prime[i] ; i++){
      int cnt = 0;
      while(now % prime[i] == 0){
        cnt++;
        now /= prime[i];
        if(cnt == 3){
          cnt = 0;
          num /= prime[i]*prime[i]*prime[i];
        }
      }
      if(cnt == 1) boo *= (long long)prime[i]*prime[i];
      else if(cnt == 2) boo *= prime[i];
    }
    if(now > 1){
      ans++;
    }else if(num == 1){
      if(mp[num] == 0){
        mp[num] = 1;
        ans++;
      }
    }else{
      int my_t = mp[num];
      int boo_t = mp[boo];
      mp[num] += times;
      if(boo_t == 0){
        ans += times;
      } else {
        if(my_t + times > boo_t){
          ans += my_t+times-boo_t;
        }
      }
    }
  }
  printf("%d\n", ans);
  return 0;
}

