list<int> Prime(int num) {
	list<int>P;
	for (int i = 5; i <= num; i += 6) {
		bool flag = true;
		for (auto j : P) {
			if (j*j > i) {
				break;
			}
			if (i%j == 0) {
				flag = false;
				break;
			}
		}
		if (flag)P.push_back(i);
		flag = true;
		for (auto j : P) {
			if (j*j > i + 2) {
				break;
			}
			if ((i + 2) % j == 0) {
				flag = false;
				break;
			}
		}
		if (flag)P.push_back(i + 2);
	}
	P.push_front(3);
	P.push_front(2);
	return P;
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);

	cin >> N;
	vector<unsigned long long int>v(N);
	vector<unsigned long long int>cube;
	auto P = Prime(100000);
	bool flag = false;
	map<unsigned long long int, int>m;
	for (auto &i : v) {
		cin >> i;
	}
	for (unsigned long long int i = 0; i*i*i <= 10000000000; i++) {
		cube.push_back(i*i*i);
	}
	for (auto i : v) {
		for (int j = 2; j < cube.size();j++) {
			while (i%cube[j] == 0)i /= cube[j];
		}
		if (i == 1) {
			flag = true;
			continue;
		}
		m[i]++;
	}
	for (unsigned long long int i = cube.size(); i*i*i <= 13000000000000000000; i++) {
		cube.push_back(i*i*i);
	}
	int ans = 0;
	for (auto i : m) {
		//cout << i.first << " " << i.second << endl;
		vector<long long int>box;
		unsigned long long int bag = i.first;
		for (auto j : P) {
			if (bag%j == 0) {
				box.push_back(j);
				bag /= j;
			}
			if (bag%j == 0) {
				bag /= j;
			}
		}
		if (bag > 1) {
			ans += i.second;
			continue;
		}
		unsigned long long int num = 1;
		for (int j = 1; j < box.size(); j++)num *= box[j];
		int cnt = 2;
		if (i.first % (box.front()*box.front()))cnt = 1;
		unsigned long long int nx = cube[num];
		unsigned long long int div = i.first/box.front();
		if (cnt == 2)div /= box.front();
		nx /= div;
		nx *= box.front();
		if (nx < i.first)continue;
		if (cnt == 1)nx *= box.front();
		if (m.find(nx) == m.end())ans += i.second;
		else ans += max(i.second, m[nx]);
	}
	if (flag)ans++;
	cout << ans << endl;
	return 0;
}

