typedef long long int ll;
int cucut=3000;
int sqcut=100010;
set<ll> sqofp;
ll a[111111];
int primechk[101000];
ll norm[111111];
ll part[111111];
map<pair<ll, ll>, int> fin;
ll ans;
bool exist1;
int n;

void preprocess(void)
{
	int i;
	for(i=2 ; i<=sqcut ; i++)
	{
		primechk[i]=1;
	}
	int j;
	for(i=2 ; i<=sqcut ; i++)
	{
		if(primechk[i]==1)
		{
			sqofp.insert(i*i);
			for(j=2 ; i*j<=sqcut ; j++)
			{
				primechk[i*j]=0;
			}
		}	
	}
}

ll getnorm(ll x)
{
	int i;
	for(i=2 ; i<=cucut ; i++)
	{
		if(primechk[i]==1)
		{
			while(x%(i*i*i)==0)
			{
				x=x/(i*i*i);
			}
		}
	}
	return x;
}

ll getpart(ll x)
{
	ll temp=x;
	ll ret=1;
	for(int i=2 ; i*i*i<=temp; i++)
	{
		int cnt=0;
		if(primechk[i]==1)
		{
			while(x%i==0)
			{
				x=x/i;
				cnt++;
			}
			if(cnt%3==1)
			{
				ret*=(i*i);
			}
			else if(cnt%3==2)
			{
				ret*=i;
			}
		}
	}
	if(sqofp.lower_bound(x)==sqofp.upper_bound(x))
	{
		ret*=(x*x);
	}
	else
	{
		ret*=(ll)sqrt(x);
	}
	return ret;
}

int main(void)
{
	cin>>n;
	int i, j;
	preprocess();
	for(i=1 ; i<=n ; i++)
	{
		scanf("%lld",&a[i]);
		norm[i]=getnorm(a[i]);
		part[i]=getpart(a[i]);
		if(part[i]==1 && exist1==false)
		{
			ans++; exist1=true;
		}
		else if(part[i]!=1)
		{
			fin[make_pair(part[i],norm[i])]++;
		}
	}
	for(map<pair<ll,ll>, int>::iterator it1=fin.begin() ; it1!=fin.end() ; it1++)
	{
		map<pair<ll,ll>, int>::iterator it2=fin.find(make_pair(it1->first.second,it1->first.first));
		if(it2==fin.end()) ans+=it1->second;
		else if(it1->second==it2->second)
		{
			if(it1->first.first>it2->first.first)
			{
				ans+=it1->second;
			}
		}
		else if(it1->second>it2->second)
		{
			ans+=it1->second;
		}
	}
	cout<<ans;
}

