using namespace std;
typedef long long int ll;

template<typename T>
map<T,ll> factorize(T x){
	map<T,ll> res;
	for(ll i=2;i*i<=x;i++){
		while(x%i==0){
			x/=i;
			res[i]++;
		}
	}
	if(x!=1) res[x]++;
	return res;
}
ll INF=1e12;

int main(){
	cin.tie(nullptr);
	ios::sync_with_stdio(false);
	int n; cin >> n;
	vector<ll> s(n);
	vector<ll> bb,cc;
	map<ll,int> mp;
	for(int i=0;i<n;i++){
		cin >> s[i];
		auto m=factorize(s[i]);
		ll b=1;
		for(auto p:m){
			for(int j=0;j<p.second%3;j++){
				b*=p.first;
			}
		}
		mp[b]++;
		bb.push_back(b);
		ll c=1;
		for(auto p:m){
			for(int j=0;j<(3-p.second%3)%3;j++){
				c*=p.first;
				if(c>INF)break;
			}
			if(c>INF)break;
		}
		if(c>INF)cc.push_back(INF);
		else cc.push_back(c);
	}
	int ans=0;
	for(int i=0;i<n;i++){
		if(mp[bb[i]]==0)continue;
		if(cc[i]==INF){
			ans+=mp[bb[i]];
		}
		else if(bb[i]==cc[i])ans++;
		else ans+=max(mp[bb[i]],mp[cc[i]]);
		mp[bb[i]]=mp[cc[i]]=0;
	}
	cout << ans << endl;
}

