const int N=1e5+5;
long long m,a[N];
map<long long,long long>ma,pos;
int n,ans,now,cnt,b[N],vi[N];
int main(){
	scanf("%d",&n);
	for(int i=2;i<N;i++){
		if(!vi[i])	b[++now]=i;
		for(int j=1;j<=now&&b[j]*i<N;j++){
			vi[i*b[j]]=1;
			if(i%b[j]==0)	break;
		}
	}
	for(int i=1;i<=n;i++){
		long long x,val=1,res=1;
		scanf("%lld",&x);
		int k=pow(x,1.0/3);
		for(int i=1;i<=now;i++)
			if(b[i]>k)	break;
			else{
				int d=0;
				while(x%b[i]==0)
					x/=b[i],++d;
				d%=3;
				if(!d)	continue;
				if(d==1)	val*=b[i],res*=b[i]*b[i];
				else	val*=b[i]*b[i],res*=b[i];
			}
		k=sqrt(x),val*=x;
		if(k*k==x)	res*=k;
		else	res*=x*x;
		pos[val]=res,++ma[val],a[++cnt]=res,a[++cnt]=val;
	}
	sort(a+1,a+cnt+1);
	n=unique(a+1,a+cnt+1)-a-1;
	for(int i=1;i<=n;i++){
		if(pos[a[i]]>a[i])	ans+=max(ma[a[i]],ma[pos[a[i]]]);
		else	if(pos[a[i]]==a[i])	++ans;
	}
	printf("%d\n",ans);
	return 0;
}

