using namespace std;

typedef long long s64;

const int MaxN = 100000;
const int MaxTN = 2154;

int n;
s64 a[MaxN][3];

map<s64, int> tab;

int pri_n, pri[MaxTN];
bool book[MaxTN + 1];

int pro[MaxTN][3];

inline void init_sieve(int n = MaxTN)
{
	for (int i = 2; i <= n; ++i)
	{
		if (!book[i])
		{
			pro[pri_n][0] = 1;
			pro[pri_n][1] = i;
			pro[pri_n][2] = i * i;
			pri[pri_n++] = i;
		}

		for (int j = 0; j < pri_n; ++j)
		{
			int p = pri[j], d = i * p;
			if (d > n)
				break;
			book[d] = true;

			if (i % p == 0)
				break;
		}
	}
}

int main()
{
//	freopen(".in", "r", stdin);
//	freopen(".out", "w", stdout);

	init_sieve();

	cin >> n;
	for (int i = 0; i < n; ++i)
	{
		scanf("%lld", &a[i][0]);

		s64 now = a[i][0];
		s64 simp = 1, anti = 1;
		for (int k = 0; k < pri_n; ++k)
			if (now % pri[k] == 0)
			{
				int d = 0;
				while (now % pri[k] == 0)
					now /= pri[k], ++d;
				d %= 3;

				simp *= pro[k][d];
				anti *= pro[k][(3 - d) % 3];
			}

		simp *= now;

		s64 v = (s64)sqrt(now);
		if (v * v == now)
			anti *= v;
		else
		{
			if (now >= (1ll << 32))
				while (true);
			anti *= now * now;
		}

		++tab[simp];
		a[i][1] = simp;
		a[i][2] = anti;
	}

	int res = 0, cnt = 0;
	for (int i = 0; i < n; ++i)
	{
		int u = a[i][1], x = tab[u];
		int v = a[i][2], y = tab[v];
		res += x > y || (x == y && u < v);
		cnt += u == 1 && v == 1;
	}

	cout << res + (cnt > 0) << endl;

	fclose(stdin);
	fclose(stdout);
	return 0;
}

