using namespace std;

typedef long long i64;
const int MAX_N = 100005;

int pr[MAX_N], tot;
i64 S[MAX_N];

void init_prime() {
  static bool vis[MAX_N];
  for (int i = 2; i < MAX_N; ++i) 
    if (!vis[i]) {
      pr[++tot] = i;
      for (int j = i; j < MAX_N; j += i)
	vis[j] = 1;
    }
}

int N;

map<i64, i64> back, NUM;
map<i64, i64>::iterator iter;

int main() {
  init_prime();

  scanf("%d", &N);
  for (int i = 1; i <= N; ++i) scanf("%lld", &S[i]);

  int res = 0;

  for (int i = 1; i <= N; ++i) {
    i64 temp = S[i], anti = 1;
    for (int j = 1; 1LL * pr[j] * pr[j] * pr[j] < temp; ++j) 
      if (temp % pr[j] == 0) {
	int cnt = 0;
	while (temp % pr[j] == 0) temp /= pr[j], S[i] /= pr[j], cnt++;
	cnt %= 3;
	if (cnt == 1) S[i] *= pr[j], anti *= pr[j] * pr[j];
	else if (cnt == 2) S[i] *= pr[j] * pr[j], anti *= pr[j];
      }

    int x = sqrtl(temp);
    if (1LL * x * x == temp) anti *= x;
    else anti *= temp * temp;

    if (temp > 1000000000) {
      res++;
      continue;
    }

    NUM[S[i]]++, back[S[i]] = anti, back[anti] = S[i];
  }

  for (iter = back.begin(); iter != back.end(); ++iter) {
    if (iter->first == 1) {
      res++;
      continue;
    }
    if (iter->first > iter->second) continue;
    res += max(NUM[iter->first], NUM[iter->second]);
  }

  printf("%d\n", res);

  return 0;
}

