	auto is_prime = [] (int n) -> bool
	{
		for(int i = 2; i * i <= n; ++i)
			if (n % i == 0)
				return false;
		return true;
	};

	primes.reserve(LIM);
	for(int i = 2; i <= LIM; ++i) {
		if (is_prime(i))
			primes.push_back(i);
	}
}

struct Entry 
{
	int prime;
	int pow;

	bool operator< (const Entry e) const
	{
		return tie(prime, pow) < tie(e.prime, e.pow);
	}
};

using Equiv = pair<vector<Entry>, LL>;

Equiv decompose(LL num)
{
	vector<Entry> ret;

	for(auto prime: primes) {
		if (num % prime == 0) {
			int p = 0;

			while(num % prime == 0) {
				p++;
				num /= prime;
			}

			p %= 3;

			if (p > 0)
				ret.push_back({prime, p});

		}
	}

	return {ret, num};
}

Equiv complement(const Equiv& equiv)
{
	vector<Entry> ret;
	for(auto e: equiv.first) {
		ret.push_back({e.prime, 3 - e.pow});
	}

	LL now = equiv.second;

	LL sol = 1;

	if (now > 1) {
		LL root = sqrt(now);

		sol = -1;

		for(int i = 0; i <= 1; ++i) {
			auto cur = root + i;
			if (cur * cur == now)
				sol = cur;
		}
	}

	return {ret, sol};
}

map<Equiv, int> normalize;

int main() 
{

	gen_primes();
	int N;
	cin >> N;
	vector<LL> v(N, 0);
	for(int i = 0; i < N; ++i)
		cin >> v[i];

	vector<Equiv> equivalence;
	equivalence.reserve(N);

	vector<int> freq(N, 0);
	for(int i = 0; i < N; ++i) {
		equivalence.push_back(decompose(v[i]));
		Equiv& ev = equivalence.back();

		int idx;

		auto it = normalize.find(ev);

		if (it == normalize.end()) {
			auto sz = normalize.size();
			normalize[ev] = sz;
			idx = sz;
		} else {
			idx = it->second;
		}

		freq[idx]++;
	}

	auto is_first = [] (const Equiv& equiv) -> bool 
	{
		if (equiv.first.empty())
			return equiv.second > 1;

		return  equiv.first[0].pow == 1 || equiv.second > 1;
	};

	int answer = N;

	for(auto &equiv_p: normalize) {

		auto &equiv = equiv_p.first;

		if (equiv.first.empty() && equiv.second == 1) {
			answer -= freq[equiv_p.second] - 1;
			continue;
		}


		if (is_first(equiv)) {
			auto comp = complement(equiv);

			int f1 = freq[equiv_p.second];

			auto it = normalize.find(comp);

			int f2 = (it == normalize.end() ? 0 : freq[it->second]);

			answer -= min(f1, f2);
		}
	}

	cout << answer << "\n";

	return 0;
}

