using namespace std;
typedef long long ll;

const int N=100005,inf=2e9;

namespace pollard_rho{
	ll seed;
	ll Rand(){
		if(!seed)seed=size_t(new char);
		seed^=seed<<13;
		seed^=seed>>17;
		seed^=seed<<5;
		return seed;
	}
	ll mult(ll x,ll y,ll z){
		if(x<inf&&y<inf)return (ll)x*y%z;
		ll r=0;
		while(y){if(y&1)(r+=x)%=z;(x<<=1)%=z;y>>=1;}
		return r;
	}
	ll power(ll a,ll t,ll n){
		ll r=1;
		while(t){
			if(t&1)r=mult(r,a,n);
			a=mult(a,a,n);t>>=1;
		}
		return r;
	}
	const int jp[]={2,3,5,7,11,13,17,19};
	bool judge(ll n){
		if(n==1)return false;
		for(int i=0;i<8;i++)if(n%jp[i]==0)return n==jp[i];
		ll r=n-1;int t=0;while(!(r&1))r>>=1,t++;
		for(int i=0;i<8;i++){
			ll x=power(jp[i],r,n),y;
			for(int j=0;j<t;j++){
				y=mult(x,x,n);
				if(y==1&&x!=1&&x!=n-1)return false;
				x=y;
			}
			if(x!=1)return false;
		}
		return true;
	}
	#define F(x) (mult(x,x,n)+1)
	ll gcd(ll x,ll y){return y?gcd(y,x%y):x;}
	ll find(ll n){
		for(int i=0;i<8;i++)if(n%jp[i]==0)return jp[i];
		ll x=Rand()%n,y=x;
		do{
			ll g=gcd((x-y+n)%n,n);
			if(g!=1&&g!=n)return g;
			x=F(x),x=F(x),y=F(y);
		}while(x!=y);
		return -1;
	}
	void rho(map<ll,int>&v,ll n){
		while(!(n&1))v[2]++,n>>=1;
		if(n==1)return;
		if(judge(n)){v[n]++;return;}
		ll d;while((d=find(n))==-1);
		rho(v,d),rho(v,n/d);
	}
}

