const int N = 200 * 1000 + 17;
const int MOD = 1000 * 1000 * 1000 + 7;

int n;
long long a[N];

bool read() {
    if (!(cin >> n))
        return false;

    for (int i = 0; i < n; ++i)
        cin >> a[i];

    return true;
}

void solve() {
    unordered_map<long long, int> cnt;
    unordered_map<long long, long long> E;
    cnt.rehash(4 * n);
    E.rehash(4 * n);

    for (int i = 0; i < n; ++i) {
        auto x = a[i];
        auto res = 1ll;
        auto enm = 1ll;

        for (auto d = 2ll; d * d * d <= x; ++d) {
            auto cnt = 0;
            for (; x % d == 0; x /= d, ++cnt) { }
            cnt %= 3;
            res *= (cnt == 0 ? 1ll : (cnt == 1 ? d : d * d));
            enm *= (cnt == 0 ? 1ll : (cnt == 1 ? d * d : d));
        }

        if (x > 1) {
            auto sq = static_cast<long long>(sqrtl((long double) x));
            for (; sq * sq < x; ++sq) { }
            for (; sq * sq > x; --sq) { }

            if (sq * sq == x) {
                res *= x;
                enm *= sq;
            } else {
                res *= x;
                enm *= x * x;
            }
        }

        ++cnt[res];

        if (!cnt.count(enm))
            cnt[enm] = 0;

        E[res] = enm;
        E[enm] = res;
    }

    int ans = 0;

    for (const auto& p : cnt)
        if (p.first == 1) {
            ans += min(1, p.second);
        } else if (p.first < E[p.first]) {
            ans += max(p.second, cnt[E[p.first]]);
        }

    cout << ans << endl;
}

int32_t main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    while (read())
        solve();

    return 0;
}

