void prelude() {
	memset(isp, 1, sizeof isp);
	isp[0] = isp[1] = 0;
	for( int i = 2; i < N; ++i )
		if( isp[i] )
			for( int j = i+i; j < N; j += i )
				isp[j] = 0;
}

int n;
map<ll,int> cnt, prm;

ll gcd( ll a, ll b ) {
	return b ? gcd(b, a%b) : a;
}

ll fpow( __int128 a, ll b, ll mod ) {
	__int128 c = 1;
	while(b) {
		if( b & 1 ) c = c * a % mod;
		a = a * a % mod;
		b >>= 1;
	}
	return ll(c);
}

bool miller_rabin( ll x ) {
	if( x < N ) return isp[x];
	for( int i = 0; i < 20; ++i ) {
		ll y = MR[i];
		if( fpow(y, x-1, x) != 1 )
			return false;
	}
	return true;
}

void pollard_rho( ll x ) {
	if( x <= 100 ) {
		for( int i = 2; i*i <= x; ++i )
			while( x % i == 0 )
				x /= i, ++prm[i];
		if( x != 1 ) ++prm[x];
		return;
	}
	if( miller_rabin(x) ) {
		++prm[x];
		return;
	}
	ll a = 0, b = 0;
	while(1) {
		while( a == b ) {
			a = rand() % MOD;
			b = (a * a + 1) % MOD;
		}
		ll g = gcd(x, a);
		if( g != 1 && g != x ) {
			pollard_rho(x/g);
			pollard_rho(g);
			break;
		}
		a = (a * a + 1) % MOD;
		b = (b * b + 1) % MOD;
		b = (b * b + 1) % MOD;
	}
}

