using namespace std;
typedef long long LL;

const int N=1e5+10;
const LL Inf=1e10+10;

LL s[N],cube[N];
int n,prime[N],cntprime;
bool notprime[N];
map<LL,int>app;
map<LL,LL>r;

void Init()
{
	scanf("%d",&n);
	for (int i=1;i<=n;++i) scanf("%lld",&s[i]);
}

void Euler()
{
	int n=2200;
	notprime[1]=1; cntprime=0;
	for (int i=2;i<=n;++i)
	{
		if (!notprime[i]) prime[++cntprime]=i,cube[cntprime]=1ll*i*i*i;
		for (int j=1;j<=cntprime && 1ll*i*prime[j]<=n;++j)
		{
			notprime[i*prime[j]]=1;
			if (!(i%prime[j])) break;	
		}
	}
}

void Solve()
{
	Euler();
	for (int i=1;i<=n;++i)
	{
		LL rev=1,d=s[i];
		for (int j=1;j<=cntprime && prime[j]<=s[i];++j)
		{
			while (!(s[i]%cube[j])) s[i]/=cube[j],d/=cube[j];
			if (!(s[i]%prime[j]))
			{
				s[i]/=prime[j];
				if (!(s[i]%prime[j])) s[i]/=prime[j],rev*=prime[j],rev=min(rev,Inf);
				else rev*=prime[j],rev=min(rev,Inf),rev*=prime[j],rev=min(rev,Inf);
			}
		}
		LL v=sqrt(s[i]);
		if (1ll*v*v==s[i]) rev=rev*v,rev=min(rev,Inf);
		else rev=rev*s[i],rev=min(rev,Inf),rev=rev*s[i],rev=min(rev,Inf);
		app[d]++; r[d]=rev;
		if (d>rev) swap(d,rev);
		if (d*d!=rev && rev!=Inf)
		{
			fprintf(stderr,"Error:%d %lld %lld\n",i,d,rev);
		}
	}
	int ans=0;
	for (auto a:app)
	{
		LL v=a.first; int ap=a.second;
		if (v==1) { ans++; continue; }
		if (v<=100000) 
		{
			LL rev=r[v];
			ans+=max(app[rev],ap);
			app[rev]=0; app[v]=0;
		}else ans+=ap;
	}
	printf("%d\n",ans);
}

int main()
{
	Init();
	Solve();
	return 0;
}

