		for (int j = 0; j < sz(pri) && pri[j] <= s[i]; ++j) {
			int c = 0;
			while (s[i] % pri[j] == 0)
				++c, s[i] /= pri[j];
			c %= 3;
			if (c == 1) {
				x *= pri[j], y *= pri[j] * pri[j];
			} else if (c == 2) {
				x *= pri[j] * pri[j], y *= pri[j];
			}
		}
