	RD(n);
	int flag = 0;
	for(int i = 1; i <= n; i ++) {
		RD(a[i]);
		if(ok[a[i]]) flag = 1;
		else all.PB(a[i]);
	}
	if(all.size() == 0) return 0 * printf("%d\n", flag);
	sort(ALL(all));
	int sz = all.size();
	int sum = 1, top = 0;
	b[++ top] = all[0]; 
	for(int i = 1; i < sz; i ++) {
		if(all[i] == all[i - 1]) sum ++;
		else {
			val[top] = sum;
			sum = 1;
			b[++ top] = all[i];
		}
	}
	val[top] = sum;
	int ans = 0;
