const LL MOD1 = 1e9 + 7;
const LL MOD2 = 1e9 + 9;
const LL BASE1 = 900000011;
const LL BASE2 = 1999999973;
map<LL, bool> ok;
LL a[N];
int val[N];
vector<LL> all;
LL b[N];
map<LL, int> cnt;
LL f[N];
LL calHash(LL num) {
	LL hash1 = 0, hash2 = 0;
	for(LL x = 2; x * x <= num; x ++) {
		if(num % x) continue;
		int c = 0;
		while(num % x == 0) num /= x, c ++;
		if(c % 3 == 0) continue;
		if(c % 3 == 1) hash1 = (hash1 * MOD1 + x * BASE1) % MOD1, hash2 = (hash2 * MOD2 + x * BASE1) % MOD2;
		if(c % 3 == 2) hash1 = (hash1 * MOD1 + x * BASE2) % MOD1, hash2 = (hash2 * MOD2 + x * BASE2) % MOD2;
	}
	if(num != 1) {
		hash1 = (hash1 * MOD1 + num * BASE1) % MOD1, hash2 = (hash2 * MOD2 + num * BASE1) % MOD2;
	}
	return (hash1 << 31) | hash2;
}
LL calvs(LL num) {
	LL hash1 = 0, hash2 = 0;
	for(LL x = 2; x * x <= num; x ++) {
		if(num % x) continue;
		int c = 0;
		while(num % x == 0) num /= x, c ++;
		if(c % 3 == 0) continue;
		if(c % 3 == 1) hash1 = (hash1 * MOD1 + x * BASE2) % MOD1, hash2 = (hash2 * MOD2 + x * BASE2) % MOD2;
		if(c % 3 == 2) hash1 = (hash1 * MOD1 + x * BASE1) % MOD1, hash2 = (hash2 * MOD2 + x * BASE1) % MOD2;
	}
	if(num != 1) hash1 = (hash1 * MOD1 + num * BASE2) % MOD1, hash2 = (hash2 * MOD2 + num * BASE2) % MOD2;
	return (hash1 << 31) | hash2;
}

int main() {
	for(LL i = 1; i <= LIM; i ++) {
		LL num = i * i * i;
		if(num > LIM) break;
		ok[num] = 1;
	}
	int n;
	RD(n);
	int flag = 0;
	for(int i = 1; i <= n; i ++) {
		RD(a[i]);
		if(ok[a[i]]) flag = 1;
		else all.PB(a[i]);
	}
	if(all.size() == 0) return 0 * printf("%d\n", flag);
	sort(ALL(all));
	int sz = all.size();
	int sum = 1, top = 0;
	b[++ top] = all[0]; 
	for(int i = 1; i < sz; i ++) {
		if(all[i] == all[i - 1]) sum ++;
		else {
			val[top] = sum;
			sum = 1;
			b[++ top] = all[i];
		}
	}
	val[top] = sum;
	int ans = 0;
	for(int i = 1; i <= top; i ++) {
		LL hash = calHash(b[i]);
		cnt[hash] += val[i];
		f[i] = hash;
	}
	for(int i = 1; i <= top; i ++) {
		LL x = f[i];
		if(cnt[x] == 0) continue;
		LL y = calvs(b[i]);
		ans += max(cnt[x], cnt[y]);
		cnt[x] = cnt[y] = 0;
	}
	ans += flag;
	printf("%d\n", ans);
}

