void init ()
{
	for (lli i = 2; i <= 3000; i++)
	{
		if (prime[i] != 0)
			continue;
		prim.pb(i);
		for (lli j = i * i; j <= 3000; j += i)
		{
			prime[j] = i;
		}
	}
}

void aciz (lli ind, lli x)
{
	vector<pair<lli,lli> > v;
	lli t = x;
	for (auto i : prim)
	{
		if (t % i != 0)
			continue;
		lli cnt = 0;
		while (t % i == 0)
		{
			cnt++;
			t /= i;
		}
		cnt %= 3;
		if (cnt != 0)
		{
			v.pb({i,cnt});
		}
	}

	lli tam = 1;
	lli sayi = 1;

	for (auto i : v)
	{
		for (lli j = 1; j <= i.second; j++)
			sayi *= i.first;
	}
	for (auto i : v)
	{
		for (lli j = 1; j <= ((3 - i.second) + 3) % 3; j++)
			tam *= i.first;
	}
	if (t != 1)
	{
		if ((lli)sqrt(t) * (lli)sqrt(t) == t)
		{
			sayi *= t;
			tam *= (lli)sqrt(t);
		}
		else
		{
			sayi *= t;
			tam *= t * t;
		}
	}
	arr[ind] = sayi;
	tamlayan[sayi] = tam;
	cnt[sayi]++;
}

