LL reduce(LL x) {
  LL res = 1;
  for(LL i = 2; i * i <= x; i++) if(x % i == 0) {
    int cnt = 0;
    while(x % i == 0) {
      x /= i;
      cnt++;
    }
    cnt %= 3;
    while(cnt--) {
      res *= i;
    }
  }
  return res * x;
}

LL comp(LL x) {
  LL res = 1;
  for(LL i = 2; i * i <= x; i++) if(x % i == 0) {
    int cnt = 0;
    while(x % i == 0) {
      x /= i;
      cnt++;
    }
    cnt %= 3;
    cnt = 3 - cnt;
    while(cnt--) {
      res *= i;
    }
  }
  if(x > 1) {
    return res * x * x;
  }
  return res;
}

