        for(int j = 0; j < pr.size() && 1LL * pr[j] * pr[j] * pr[j] <= S[i]; j++) {
            while(S[i] % (1LL * pr[j] * pr[j] * pr[j]) == 0) {
                S[i] /= (1LL * pr[j] * pr[j] * pr[j]);
            }
        }
        ll tmp = 1;
        for(int j = 0; j < pr.size() && 1LL * pr[j] * pr[j] <= S[i]; j++) {
            while(S[i] % (1LL * pr[j] * pr[j]) == 0) {
                tmp *= pr[j];
                S[i] /= (1LL * pr[j] * pr[j]);
            }
        }
        C[i] = pll(S[i], tmp);
        Cnt[ C[i] ]++;
    }

    int ans = Cnt[ pll(1, 1) ]? 1 : 0;
    Chk[ pll(1, 1) ] = 1;
    for(int i = 0; i < N; i++) {
        if(Chk[ C[i] ]) continue;

        ll t1 = C[i].first;
        ll t2 = C[i].second;

        ans += max(Cnt[ C[i] ], Cnt[ pll(t2, t1) ]);

        Chk[ C[i] ] = 1;
        Chk[ pll(t2, t1) ] = 1;
    }

    printf("%d", ans);
}

