std::map<pll, int> buc;

inline LL rint () {
	LL x = 0; char s = getchar ();
	for ( ; s < '0' || '9' < s; s = getchar () );
	for ( ; '0' <= s && s <= '9'; s = getchar () ) x = x * 10 + ( s ^ '0' );
	return x;
}

inline void sieve ( const int n ) {
	for ( int i = 2; i <= n; ++ i ) {
		if ( ! vis[i] ) pr[++ pn] = i;
		for ( int j = 1; j <= pn && i * pr[j] <= n; ++ j ) {
			vis[i * pr[j]] = true;
			if ( ! ( i % pr[j] ) ) break;
		}
	}
}

inline bool issqr ( const LL x ) {
	LL t = pow ( x, 1.0 / 3 );
	return t * t * t == x || ( t + 1 ) * ( t + 1 ) * ( t + 1 ) == x;
}

int main () {
	n = rint (), sieve ( MAXN );
	int ans = 0;
	for ( int i = 1; i <= n; ++ i ) {
		LL a = rint ();
		if ( issqr ( a ) ) { ans = 1; continue; }
		LL cur = 1, mtc = 1;
		for ( int j = 1; j <= pn && pr[j] <= a; ++ j ) {
			if ( a % pr[j] ) continue;
			LL t = pr[j] * pr[j] * pr[j];
			while ( ! ( a % t ) ) a /= t;
			int p = ! ( a % pr[j] ) + ! ( a % ( pr[j] * pr[j] ) );
			for ( int k = 1; k <= p; ++ k ) cur *= pr[j];
			for ( int k = 1; k <= ( 3 - p ) % 3; ++ k ) mtc *= pr[j];
			while ( ! ( a % pr[j] ) ) a /= pr[j];
		}
		++ buc[mkpr ( cur, a )], rev[cur] = mtc;
	}
	for ( auto val: buc ) {
		LL mtc = rev[val.first.first];
		if ( mtc == 1 || ! buc.count ( mkpr ( mtc, val.first.second ) ) ) ans += val.second;
		else if ( val.first.first < mtc ) {
			ans += std::max ( val.second, buc[mkpr ( mtc, val.first.second )] );
		}
	}
	printf ( "%d\n", ans );
	return 0;
}

