        while ( i < len ) {
            string k = "", v = "";
            while ( i < len && s[i] != '_' ) {
                k.push_back(s[i]);
                i++;
            }
            i++;
            while ( i < len && s[i] != '_' ) {
                v.push_back(s[i]);
                i++;
            }
            i++;
            r[stol(k)] = stol(v);
        }
        return r;
    };

