        for ( ll k = 2; k*k <= s && k < 2200; k++ ) {
            while ( s % k == 0 ) {
                ns[k] = (ns[k] + 1) % 3;
                s /= k;
            }
        }
        if ( s > 1 ) {
            ns[s] = (ns[s] + 1) % 3;
        }
        for ( auto it = ns.begin(); it != ns.end();) {
            if ( it->second == 0 ) {
                ns.erase(it++);
            } else {
                it++;
            }
        }
        m[enc_map(ns)]++;
    }

    ll ans = 0;
    set<string> checked;
    for ( auto mm : m ) {
        if ( mm.first == "" ) {
            ans += 1;
        } else {
            if ( checked.find(mm.first) == checked.end() ) {
                string k1 = mm.first;
                auto tmp = dec_map(k1);
                for ( auto& p : tmp ) {
                    p.second = (3 - p.second) % 3;
                }
                string k2 = enc_map(tmp);
                ans += max(m[k1], m[k2]);
                checked.insert(k1);
                checked.insert(k2);
            }
        }
    }
    return ans;
}

