//ここから編集する
class Solve {
public:
    int N;
    vector<ll> S;
    vector<ll> T;
    vector<ll> primes;

    void input() {
        cin >> N;
        S.resize(N);
        rep(i, 0, N) cin >> S[i];


        vector<ll> pf(3000, true);
        pf[0] = pf[1] = false;
        for (int i = 2; i < pf.size(); ++i) {
            if (pf[i]) {
                for (int j = i * 2; j < pf.size(); j += 2) {
                    pf[j] = false;
                }
            }
        }
        for (int i = 0; i < pf.size(); ++i) {
            if (pf[i]) primes.push_back(i);
        }


    }

    void solve() {
        input();

        map<ll, int> mp;
//        T = S;
        for (int i = 0; i < N; ++i) {
            ll tmp = S[i];
            for (auto p : primes) {
                ll p3 = p * p * p;
                while (tmp % p3 == 0) tmp /= p3;
            }
            mp[tmp]++;
        }

        //debug

        int ans = 0;
        for (auto &e : mp) {
            ll num = e.first;
            ll par = 1ll;
            if (num == 1) {
                ans++;
                continue;
            }

            for (auto p : primes) {
                if (num % (p * p) == 0) {
                    num /= (p * p);
                    par *= p;
                } else if (num % p == 0) {
                    num /= p;
                    par *= (p * p);
                }
            }

            //num = 1 or n^2 or n
            if (num == 1) {
                int add = max(e.second, mp[par]);
                ans += add;
                e.second = 0;
                mp[par] = 0;
                continue;
            }

            ll snum = (ll) round(sqrt(num));

            if (snum * snum == num) {
                // n^2
                par *= snum;
                int add = max(e.second, mp[par]);
                ans += add;
                e.second = 0;
                mp[par] = 0;
                continue;
            }

            //numは素数で確定
            if (num >= 100000) {
                //大きすぎる。たぴ。
                ans += e.second;
                e.second = 0;
                continue;
            } else {
                par *= (num * num);
                int add = max(e.second, mp[par]);
                ans += add;
                e.second = 0;
                mp[par] = 0;
                continue;
            }
        }

        cout << ans << endl;


    }
};


int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    cout << fixed << setprecision(10);

    Solve().solve();


    return 0;
}

