	for (int i=2;i<=N;i++)
	{
		if (!nprime[i]) c[++cnt]=i;
		for (int j=1;j<=cnt;j++)
		{
			if (i*c[j]>N) break;
			nprime[i*c[j]]=1;
			if (i%c[j]==0) break;
		}
	}
	for (int i=1;i<=n;i++)
	{
		ll t=a[i];b[i]=1;
		for (int j=1;t>1&&j<=cnt;j++)
		{
			int s=0;
			while (t%c[j]==0) {t/=c[j];s++;}
			for (int k=0;k<s%3;k++) b[i]*=c[j];
		}
		b[i]*=t;
	}
	sort(b+1,b+n+1);
	int l=1,ans=0;
	for (int i=2;i<=n+1;i++)
		if (i==n+1||b[i]!=b[i-1])
		{
			if (b[l]==1) {ans++;l=i;continue;}
			ll t1=b[l],t2=1;
			for (int j=1;t1>1&&j<=cnt;j++)
				if (t1%c[j]==0)
				{
					int s=0;
					while (t1%c[j]==0) {t1/=c[j];s++;}
					for (int k=0;k<3-s;k++) t2*=c[j];
				}
			if (t1>1)
			{
				ll t3=ll(sqrt(t1+0.5));
				if (t3*t3==t1)
					t2*=t3;
				else
				{
					t2*=t1;
					if (t1>100000) t2=1000000000000ll; else t2*=t1;
				}
			}
			int w=upper_bound(b+1,b+n+1,t2)-lower_bound(b+1,b+n+1,t2);
			if (i-l>w||(i-l==w&&b[l]>t2)) ans+=i-l;
			l=i;
		}
	printf("%d\n",ans);
	return 0;
}

