bool pr[500005];
int binpow(int a, int b, int modv)
{
	if(!b) return 1;
	int t = binpow(a, b/2, modv);
	if(b&1) return t*t%MOD[modv]*a%MOD[modv];
	return t*t%MOD[modv];
}
int C(int a, int b)
{
	return a*INT_MAX+b;
}
void ft(int x)
{
	vi temp(2, 0), temp1(2, 0);
	for(int p: P) 
	{
		if(p*p>x) break;
		if(x%p==0) 
		{
			int cnt=0;
			while(x%p==0)
			{
				x/=p;
				cnt++;
		 	}
		 	cnt%=3;
			if(cnt) 
			{
				for(int modv=0; modv<=1; modv++)
				{
					temp[modv]=(temp[modv]+cnt*binpow(3, p, modv)%MOD[modv])%MOD[modv]; 
					temp1[modv]=(temp1[modv]+(3-cnt)*(binpow(3, p, modv))%MOD[modv])%MOD[modv];
				}
			}
		}
	}
	if(x>1) 
	{
		for(int modv=0; modv<=1; modv++)
		{
			temp[modv]=(temp[modv]+binpow(3, x, modv))%MOD[modv];
			temp1[modv] = (temp1[modv]+2*binpow(3,x, modv)%MOD[modv])%MOD[modv];
		}
	}
	if(C(temp[0], temp[1])) m[C(temp[0], temp[1])]++, rev[C(temp[0], temp[1])] = C(temp1[0], temp1[1]);
	else cube++;
}
void sieve()
{
	for(int i=2; i<=(int) 5e5; i++)
		if(!pr[i])
		{
			P.eb(i);
			for(int j=2; i*j<(int) 5e5; j++) pr[i*j]=1;
		}
}
