inline void init(int n) {
	register int i, j;
	np[1] = 1; 
	for(i = 2; i <= n; ++i) {
		if(!np[i])
			p[++pn] = i;
		for(j = 1; j <= pn && i * p[j] <= n; ++j) {
			np[i * p[j]] = 1;
			if(i % p[j] == 0)
				break;
		}
	}
}

int main() {
	register int i, j; ll a; init(1e5);
	scanf("%d", &N);
	for(i = 1; i <= N; ++i) {
		ll x = 1, y = 1, t;
		scanf("%lld", &a);
		for(j = 1; j <= pn && p[j] * p[j] * p[j] <= a; ++j) {
			if(a % p[j] == 0) {
				t = 0;
				while(a % p[j] == 0) a /= p[j], ++t;
				if(t % 3 == 1) x *= p[j], y *= p[j] * p[j];
				if(t % 3 == 2) x *= p[j] * p[j], y *= p[j];
			}
		}
		x *= a;
		if((ll) sqrt(a) * (ll) sqrt(a) == a)
			y *= (ll) sqrt(a);
		else
			y *= a * a;
		if(x == 1) ans += (++cnt[1] == 1);
		else ans += (++cnt[x] > cnt[y]);
	}
	printf("%d\n", ans);
	return 0;
}

