template<typename T>
void readv(vector<T> &a){ REP(i, a.size()) cin >> a[i]; }
void readi(vector<int> &a){ REP(i, a.size()){cin >> a[i]; a[i]--;} }

vec prime_list(int MAX_N){

    vector<bool> is_prime(MAX_N + 1, true);
    vec prime(0);
    is_prime[0] = false;
    is_prime[1] = false;

    FOR(i, 2, MAX_N + 1){
        if(is_prime[i]){
            prime.push_back(i);
            int tmp = i * 2;
            while(tmp <= MAX_N){
                is_prime[tmp] = false;
                tmp += i;
            }
        }
    }

    return prime;
}

void factmod3(int n, int &a, int &b, vec &prime){
    a = 1; b = 1;
    REP(i, prime.size()){
        int c = 0;
        while(n % prime[i] == 0){
            c++;
            n /= prime[i];
        }
        if(c > 0){
            c %= 3;
            REP(j, c) a *= prime[i];
            REP(j, 3 - c) b *= prime[i];
        }
    }
    if(n > 1){
        REP(j, 1) a *= n;
        REP(j, 2) b *= n;
    }
}

signed main(){

    int N; cin >> N;
    vec s(N); readv(s);

    vec prime = prime_list(100000);

    map<int, int> m, dual;
    int a, b;
    REP(i, N){
        factmod3(s[i], a, b, prime);
        m[a] += 1;
        dual[a] = b;
    }

    int ans = 0;
    for(auto p: m){
        if(p.first == 1) ans++;
        else if(!(dual[p.first] < p.first && m[p.first] > 0))
        ans += max(m[p.first], m[dual[p.first]]);
    }
    cout << ans;

    return 0;
}

