i64 isqrt(i64 a) {
    __int128_t l = 0;
    __int128_t r = a;
    while (r - l > 1) {
        __int128_t m = (r + l) / 2;
        if (m * m > a) {
            r = m;
        } else {
            l = m;
        }
    }
    return l;
}

