int getSqrt(long long x)
{
    long long l = 0, r = x;
    while (r - l > 1)
    {
        long long m = (l + r) / 2;
        if (m * m <= x)
            l = m;
        else
            r = m;
    }
    if (l * l != x)
        return -1;
    return l;
}

