const ll infty = 10000000010;

void init() {
  fill(isprime, isprime+MAX_SIZE, true);
  isprime[0] = isprime[1] = false;
  for (auto i=2; i<MAX_SIZE; i++) {
    if (isprime[i]) {
      ll x = i;
      prime_num.push_back(x);
      squered.push_back(x*x);
      cubed.push_back(x*x*x);
      for (auto j=2; i*j<MAX_SIZE; j++) {
        isprime[i*j] = false;
      }
    }
  }
}

bool prime(long long x) { // 2 \leq x \leq MAX_SIZE^2
  if (x < MAX_SIZE) {
    return isprime[x];
  }
  for (auto e : prime_num) {
    if (x%e == 0) return false;
  }
  return true;
}

int N;
ll s[100010];
map<ll, int> M;

ll conj(ll k) {
  ll l = k;
  ll A = 1;
  ll B = 1;
  for (auto x : prime_num) {
    int t = 0;
    while (l % x == 0) {
      l /= x;
      t++;
    }
    if (t == 1) {
      A *= x;
    } else if (t == 2) {
      B *= x;
    }
  }
  ll red = k / (A * B * B);
  ll sq = sqrt(red);
  long long t = static_cast<long long>(sq);
  t = floor(t);
  // cerr << "red = " << red << " , sq = " << sq << endl;
  if (red == t * t) {
    B *= red;
  } else {
    A *= red;
  }
  return A * A * B;
}

int main() {
  init();
  cin >> N;
  int ans = 0;
  for (auto i = 0; i < N; i++) {
    cin >> s[i];
    for (auto x : cubed) {
      while (s[i]%x == 0) s[i] /= x;
    }
    if (M.find(s[i]) == M.end()) {
      M[s[i]] = 1;
    } else {
      M[s[i]]++;
    }
  }
  for (auto x : M) {
    ll k = x.first;
    int num = x.second;
    // cerr << k << " " << num << endl;
    if (k == 1 && num > 0) {
      ans += 1;
      continue;
    }
    ll c = conj(k);
    // cerr << "conj(" << k << ") = " << c << endl;
    if (M.find(c) == M.end()) {
      ans += num;
    } else {
      ans += max(num, M[c]);
      M[k] = 0;
      M[c] = 0;      
    }
  }
  cout << ans << endl;
}

#include <bits/stdc++.h>
using namespace std;


map<long long,int> pFactorize(long long n){
	map<long long,int> memo;

	for(long long i = 2 ; i*i <= n ; i++){
		while(n%i==0){
			memo[i]++;
			n/=i;
		}
	}
	if(n>1)memo[n]++;
	map<long long,int> res;
	for( auto i : memo ) if( i.second % 3 ) res[i.first] = i.second % 3;
	return res;
}
map<long long,int> inv(map<long long,int> x){
	map<long long,int> res;
	for( auto i : x ) res[i.first] = 3 - i.second;
	return res;
}
void output(map<long long,int> t){
	cout << "{";
	for( auto e : t ) cout << e.first << ":" << e.second << ",";
	cout << "}" << endl;
}
void solve(long long N, vector<long long> s){
	map<map<long long,int>,int> ps;
	for(int i = 0 ; i < s.size() ; i++){
		auto t = pFactorize(s[i]);

		ps[t]++;
	}
	long long ans = 0;
	while(ps.size()){
		auto it = ps.begin();
		auto r = inv(it->first);
		assert(it->second);
		// cout << "--" << endl;
		// output(it->first);
		// output(r);

		if( r == it->first ){
			ans++;
			ps.erase(it);
		}else{
			if( ps.count(r) ){
				ans += max(it->second,ps[r]);
				ps.erase(it);
				ps.erase(r);
			}else{
				ans += it->second;
				ps.erase(it);
			}
		}
	}
	cout << ans << endl;

}



