long long F(long long x)
{
	long long res=1;
	for(int j=1;j<=pcnt&&prime[j]*prime[j]<=x;j++)
		if(x%prime[j]==0)
		{
			int cnt=0;
			while(x%prime[j]==0)
				x/=prime[j],cnt++;
			cnt%=3;
			for(int k=1;k<=cnt;k++)
				res*=prime[j];
		}
	if(x!=1&&x<=prime[pcnt])
		res*=x;
	if(x>prime[pcnt])
		ans++,vis[res]=true;
	return res;
}

