bool iscubic(ll num){
    ll rt = pow((double)num, 1.0/3.0);
    for (ll i = max(0LL, rt - 2); i <= rt + 2; i++){
        if (i * i * i == num) return true;
    }
    return false;
}
const int MAXN = 100100;
bool isprime[MAXN];
vector<int> primes;
void sieve(){
    memset(isprime, true, sizeof isprime);
    isprime[0] = isprime[1] = false;
    for (ll i = 2; i < MAXN; i++){
        if (isprime[i]){
            primes.push_back(i);
            for (ll j = i * i; j < MAXN; j += i){
                isprime[j] = false;
            }
        }
    }
}

vector<pii> factorise(ll num){
    vector<pii> ans;
    for (int x : primes){
        int f = 0;
        if ((ll) x * x > num) break;
        while (num % x == 0){
            f += 1;
            num /= x;
        }
        f %= 3;
        if (f) ans.emplace_back(x, f);
    }
    if (num != 1) ans.emplace_back(num, 1);
    return ans;
}

vector<pii> invert(vector<pii> v){
    for (pii &x : v){
        x.Y = 3 - x.Y;
    }
    return v;
}

