unordered_map<ll, int> MP;
vector<pll> VA;
vector<pair<pll, int>> VB;

ll A[MAXN];

int Ans;
int N;

int main() {
	ios::sync_with_stdio(false);

	cin >> N;
	for(int i = 1; i <= N; i++) {
		cin >> A[i];
		if(1 == A[i]) {
			VA.eb(1, 1);
			continue;
		}

		vector<ll> FV;
		//facrun(FV, A[i]);

		{
			ll n = A[i];
			for(; !(n&1); n >>= 1) FV.eb(2);
			for(int i = 3; i < 2222; i += 2)
				for(; 0 == n%i; n /= i) FV.eb(i);
			if(1 < n) FV.eb(n);
		}
		vector<pair<ll, int>> V;
		for(ll v : FV) {
			if(V.empty() || V.back().first != v) {
				V.eb(v, 1);
			} else {
				V.back().second++;
			}
		}

		for(auto &v : V) v.second %= 3;

		ll n = 1; lll mm = 1;
		for(auto &v : V) {
			if(!v.second) continue;
			for(int i = 0; i < v.second; i++)
				n *= v.first;
			for(int i = 0; i < 3-v.second; i++)
				mm *= v.first;
		}

		if(MAXX < mm) mm = MAXX;

		VA.eb(n, mm);

		//fprintf(stderr, "TEST %d\n", i);
	}

	sorv(VA);

	{
		for(int i = 0; i < sz(VA);) {
			if(sz(VA) <= i+1 || VA[i] != VA[i+1]) {
				VB.eb(VA[i], 1);
				i++;
				continue;
			}
			VB.eb(VA[i], 0);
			for(ll c = VA[i].first; i < sz(VA) && VA[i].first == c; VB.back().second++, i++);
		}
	}

	for(auto &e : VB) {
		MP[e.first.first] = e.second;
	}

	for(auto &e : VB) {
		if(!MP[e.first.first]) continue;
		if(e.first.first == 1) {
			Ans++;
			MP[1] = 0;
			continue;
		}
		if(MAXX == e.first.second) {
			Ans += MP[e.first.first];
			MP[e.first.first] = 0;
			continue;
		}
		Ans += max(MP[e.first.first], MP[e.first.second]);
		MP[e.first.first] = MP[e.first.second] = 0;
	}

	cout << Ans << endl;
	return 0;
}

