const int L=1e5+1;
vector<LL> ps;
vector<LL> ps2;

const LL up=1e10;
int main() {
	vector<bool> comp(L);
	for(LL i=2;i<L;i++){
		if(comp[i])continue;
		ps.push_back(i);
		ps2.push_back(i*i);
		for(LL j=i*i;j<L;j+=i){
			comp[j]=true;
		}
	}
	////cerr/g << ps.size() << endl;
	int N;
	cin >> N;
	map<P,int> r;
	bool cb=false;

	LL ret=0;
	for(int i=0;i<N;i++){
		LL s;
		cin >> s;
		//LL org=s;
		LL s0=pow(s,1.0/3)+0.5;
		if(s0*s0*s0==s){
			//cerr/g << "cb" << org << endl;
			cb=true;
			continue;
		}

		auto j=lower_bound(ps.begin(),ps.end(),s)-ps.begin();
		if(j<ps.size()&&ps[j]==s){
			//cerr/g << ps[j] << ", " << ps[j] << ", " << ps2[j] << endl;
			r[P(ps[j],ps2[j])]++;
			continue;
		}
		j=lower_bound(ps2.begin(),ps2.end(),s)-ps2.begin();
		if(j<ps2.size()&&ps2[j]==s){
			//cerr/g << ps2[j] << ", " << ps2[j] << ", " << ps[j] << endl;
			r[P(ps2[j],ps[j])]++;
			continue;
		}

		LL m0=1;
		LL m1=1;
		LL m2=1;
		bool over=false;
		for(int i=0;i<ps.size()&&s>1;i++){
			LL p3=ps[i]*ps2[i];
			if(p3>up||(m0*p3>up&&m2*p3>up)){
				over=true;
				break;
			}
			int c=0;
			while(s%ps[i]==0){
				s/=ps[i];
				m0*=ps[i];
				c++;
			}
			if(c==0)continue;
			c%=3;
			if(c==1){
				m1*=ps[i];
				m2*=ps2[i];
			}
			else if(c==2){
				m1*=ps2[i];
				m2*=ps[i];
			}
			if(m2>up){
				over=true;
				break;
			}
			auto j=lower_bound(ps.begin(),ps.end(),s)-ps.begin();
			if(j<ps.size()&&ps[j]==s){
				s/=ps[j];
				m0*=ps[j];
				m1*=ps[j];
				m2*=ps2[j];
				if(m2>up){
					over=true;
					break;
				}
			}
			j=lower_bound(ps2.begin(),ps2.end(),s)-ps2.begin();
			if(j<ps2.size()&&ps2[j]==s){
				s/=ps2[j];
				m0*=ps2[j];
				m1*=ps2[j];
				m2*=ps[j];
				if(m2>up){
					over=true;
					break;
				}
			}
		}
		if(over){
			//cerr/g << "over " << org << endl;
			ret++;
			continue;
		}
		r[P(m1,m2)]++;
		//cerr/g << org << ", " << m1 << ", " << m2 << endl;
	}
	if(cb){
		ret++;
	}
	set<P> done;
	for(auto p:r){
		if(done.count(p.first))continue;
		P k=P(p.first.second,p.first.first);
		//cerr/g << "p " << p.first.first << ", " << p.first.second << endl;
		//cerr/g << "k " << k.first << ", " << k.second << endl;
		auto it=r.find(k);
		if(it !=r.end()){
			ret+=max(p.second,it->second);
			done.insert(k);
			//cerr/g << k.first << ", " << k.second << endl;
		}
		else{
			ret+=p.second;
		}
	}
	cout << ret << endl;

	return 0;
}

