const int SQRT  = 110000;
const int CBRT  = 2200;
const long MAXN = 1e10;
bool prime[SQRT];
vector<int> primes;
vector<long> squares;
int answer = 0;

pair<long, long> func(long x) {
	long a = 1, b = 1;
	for (long d : primes) {
		if (d * d * d > x) {
			break;
		}
		int cnt = 0;
		while (x % d == 0) {
			x /= d;
			++cnt;
		}
		cnt %= 3;

		if (cnt == 1) {
			if (d * d > MAXN) {
				++answer;
				return {0, 0};
			}
			a *= d;
			b *= d * d;
		} else if (cnt == 2) {
			if (d * d > MAXN) {
				++answer;
				return {0, 0};
			}
			a *= d * d;
			b *= d;
		}
		if (max(a, b) > MAXN) {
			++answer;
			return {0, 0};
		}
	}
	if (!binary_search(all(squares), x)) {
		if (x * x > MAXN) {
			++answer;
			return {0, 0};
		}
		a *= x;
		b *= x * x;
	} else {
		if (x > MAXN) {
			++answer;
			return {0, 0};
		}
		a *= x;
		b *= sqrt(x);
	}
	if (max(a, b) > MAXN) {
		++answer;
		return {0, 0};
	}
	assert(1 <= a && a <= MAXN);
	assert(1 <= b && b <= MAXN);
	return {a, b};
}


