		factorization::PR(a, X);
		for(ll c : X) L[c] += 1;

		__int128 op = 1, cur = 1;
		for(auto c : L){
			c.second %= 3;
			if( c.second == 1 ) op = op * c.first * c.first, cur = cur * c.first;
			else if( c.second == 2 ) op = op * c.first, cur = cur * c.first * c.first;
		}
		D[cur] += 1; E[op] = cur; E[cur] = op;
	}
	ll ans = 0;
	for(auto c : D){
		if( c.first == 1 ) ans += 2;
		else ans += max(D[c.first], D[E[c.first]]);
	}
	printf("%lld\n", ans / 2);
	return 0;
}

