void preProcess() {
	for (ll i = 2; i < MAX_N; i++) {
		if (lp[i] == 0) {
			lp[i] = i;
			pr[ind++] = i;
		}

		for (ll j = 0; j < ind && pr[j] <= lp[i] && i * pr[j] < MAX_N; j++)
			lp[i * pr[j]] = pr[j];
	}
}
pii calc (ll d) {
	ll res1 = 1, res2 = 1, tmp = 0;
	for (int i = 0; i < ind && pr[i] * pr[i] <= d; i++) {
		if (d % pr[i] == 0) {
			tmp = 0;
			int cnt = 0;
			while (d % pr[i] == 0) {
				cnt++;
				d /= pr[i];
			}

			cnt %= 3;
			if (cnt == 1) {
				res1 *= pr[i];
				res2 *= pr[i] * pr[i];
			}
			if (cnt == 2) {
				res1 *= pr[i] * pr[i];
				res2 *= pr[i];
			}
		}
		tmp++;
		if (tmp == 2000)
			break;
	}

	if (d != 1) {
		res1 *= d;
		res2 *= d * d;
	}
	return {res1, res2};
