vector<int> Prime(int num) {
	vector<int>P;
	P.push_back(2);
	P.push_back(3);
	for (int i = 5; i <= num; i += 6) {
		bool flag = true;
		for (auto j : P) {
			if (j < 5)continue;
			if (j*j > i) {
				break;
			}
			if (i%j == 0) {
				flag = false;
				break;
			}
		}
		if (flag)P.push_back(i);
		flag = true;
		for (auto j : P) {
			if (j < 5)continue;
			if (j*j > i + 2) {
				break;
			}
			if ((i + 2) % j == 0) {
				flag = false;
				break;
			}
		}
		if (flag)P.push_back(i + 2);
	}
	return P;
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);

	cin >> N;
	vector<long long int>v(N);
	vector<long long int>cube;
	auto P = Prime(100000);
	bool flag = false;
	unordered_map<long long int, int>m;
	for (auto &i : v) {
		cin >> i;
	}
	for (long long int i = 0; i*i*i <= 10000000000; i++) {
		cube.push_back(i*i*i);
	}
	for (auto i : v) {
		for (int j = 2; j < cube.size();j++) {
			while (i%cube[j] == 0)i /= cube[j];
		}
		if (i == 1) {
			flag = true;
			continue;
		}
		m[i]++;
	}
	vector<int>prime(100001);
	for (auto i : P)prime[i] = 1;
	int ans = 0;
	for (auto i : m) {
		vector<long long int>box;
		long long int bag = i.first;
		for (auto j : P) {
			if (bag < j*j) {
				if (bag >= 100000)break;
				if (prime[bag]) {
					box.push_back(bag);
					bag = 1;
				}
				break;
			}
			if (bag%j == 0) {
				box.push_back(j);
				bag /= j;
			}
			if (bag%j == 0) {
				bag /= j;
			}
			if (bag == 1)break;
		}
		if (bag > 1) {
			ans += i.second;
			continue;
		}
		long long int num = 1;
		for (auto j : box) {
			num *= j;
			if (num > 10000000000)break;
			if (i.first % (j*j)) {
				num *= j;
				if (num > 10000000000)break;
			}
		}
		if (m.find(num) == m.end()) {
			ans += i.second;
			continue;
		}
		if (num < i.first)continue;
		else ans += max(i.second, m[num]);
	}
	if (flag)ans++;
	cout << ans << endl;
	return 0;
}

