  memset(isPrime, true, sizeof(isPrime));
  isPrime[0] = isPrime[1] = false;
  for (int i = 2; i * i < SIZE; i++) 
    if (isPrime[i])
      for (int j = i * i; j < SIZE; j += i)
        isPrime[j] = false;
  REP(i, SIZE) if (isPrime[i]) primes.push_back(i);
}


map<ll, int> factorize(ll n) {
  map<ll, int> ps;
  for (int i = 0; primes[i] * primes[i] <= n; i++) {
    while (n % primes[i] == 0) {
      ++ps[ primes[i] ];
      n /= primes[i];
    }
  }
  if (n > 1) ++ps[n];
  map<ll, int> res;
  for (auto it = ps.begin(); it != ps.end(); ++it) {
    int k = it->second % 3;
    if (k != 0) {
      res[it->first] = k;
    }
  }
  return res;
}

ll inverse(ll n) {
  ll org_n = n;
  ll b = 1;
  for (int i = 0; primes[i] * primes[i] <= n; i++) {
    int c = 0;
    while (n % primes[i] == 0) {
      c++;
      n /= primes[i];
    }
    if (c > 0) REP(_, 3 - c%3) b *= primes[i];
  }
  if (n > 1) { b *= n * n; }
  return b;
}

ll norm(ll n) {
  ll org_n = n;
  ll res = 1;
  for (int i = 0; primes[i] * primes[i] <= n; i++) {
    int c = 0;
    while (n % primes[i] == 0) {
      c++;
      n /= primes[i];
    }
    REP(_, c%3) res *= primes[i];
  }
  if (n > 1) res *= n;
  return res;
}

