inline ll gi() {
    ll x=0,o=1;
    char ch=getchar();
    while(ch!='-'&&(ch<'0'||ch>'9')) ch=getchar();
    if(ch=='-') o=-1,ch=getchar();
    while(ch>='0'&&ch<='9') x=x*10+ch-'0',ch=getchar();
    return x*o;
}
inline void pre(int n) {
    for(int i=2;i<=n;i++) {
	if(!w[i]) p[++cnt]=i;
	for(int j=1;j<=cnt&&i*p[j]<=n;j++) {
	    w[i*p[j]]=1;
	    if(i%p[j]==0) break;
	}
    }
}
int main() {
    int n,t=0,ans=0;
    cin>>n;
    pre(100000);
    for(int i=1;i<=n;i++) {
	ll x=gi(),s1=0,s2=0;
	for(int j=1;p[j]<=320;j++)
	    if(x%p[j]==0) {
		int t=0,q=p[j];
		while(x%q==0) x/=q,++t;
		if(t%=3) {
		    s1=s1*hs+q,s2=s2*hs+q;
		    if(t==2) s1=s1*hs+q;
		    else s2=s2*hs+q;
		}
	    }
	if(x>1) {
	    ll y=sqrt(x)+1e-9;
	    if(y*y==x) s1=(s1*hs+y)*hs+y,s2=s2*hs+y;
	    else if(x<=100000&&!w[x]) s1=s1*hs+x,s2=(s2*hs+x)+x;
	    else {++ans;continue;}
	}
	if(!s1) {t=1;continue;}
	++g[s1];
	if(g[s1]>g[s2]) ++ans;
    }
    cout<<ans+t;
    return 0;
}

