bool is_prime(int x) {
	for(int i = 2; 1ll * i * i <= x; i ++)
		if(x % i == 0)
			return 0;
	return 1;
}

map<ll, int> square;
map<ll, vector<int> > ne, wa;
map<ll, int> ane, awa;
set<ll> st;
bool del[N];

main() {
	cin >> n;
	for(int i = 1; i <= n; i ++)
		cin >> a[i];
	for(int i = 1; i <= n; i ++) {
		for(ll x = (int)3e3; x >= 1; x --) {
			if(a[i] % (x * x * x) == 0)	{
				waste[i] = a[i] / (x * x * x);
				break;
			}
		}
	}
	for(int x = 2; x <= (int)5e3; x ++) {
		if(is_prime(x)) {
			pr.pb(x);
		}
	}
	for(int x = 2; x <= (int)1e5; x ++) 
	  if(is_prime(x))
			square[1ll * x * x] = x;

	for(int i = 1; i <= n; i ++) {
		ll tmp = a[i], tmp_need = 1;
		for(int it = 0; it < sz(pr); it ++) {
			int cnt = 0;
			while(tmp % pr[it] == 0) 
				cnt ++, tmp /= pr[it];
			cnt %= 3;
			if(cnt == 1) tmp_need *= pr[it] * pr[it];
			if(cnt == 2) tmp_need *= pr[it];			
		}
		if(!square.count(tmp))
			tmp_need *= tmp * tmp;
		else 
			tmp_need *= square[tmp];

		need[i] = tmp_need;
	}
	for(int i = 1; i <= n; i ++) {
		ne[need[i]].pb(i), wa[waste[i]].pb(i);
		ane[need[i]] ++, awa[waste[i]] ++;
		st.insert(need[i]);
		st.insert(waste[i]);
	}
	int res = 0;
	for(auto x : st) {
		if(x == 1) continue;
		res += max(ane[x], awa[x]);

	 	for(auto ind : ne[x])
	  	if(!del[ind])
	  		ane[need[ind]] --, awa[waste[ind]] --, del[ind] = 1;
	 	for(auto ind : wa[x])
	  	if(!del[ind])
	  		ane[need[ind]] --, awa[waste[ind]] --, del[ind] = 1;
	}
	if(sz(ne[1]) || sz(wa[1]))
		res ++;
	cout << res;
	return 0;  
}

