inline pair<ll,ll> root(ll x)     // find the root of x
{
    ll val=1,reverse_val=1;
    for (ll i: Pr)
    {
        if(i*i>x) break;
        if(x%i==0)
        {
            ll num=0;
            while(x%i==0)
            {
                num++;
                x/=i;
            }
            num%=3;
            for(ll j = 0 ; j < num ; j++) val *= i;
            if(num == 1 || num == 2)for(ll j = 0 ; j < 3 - num; j++) reverse_val *= i;
        }
    }
    if(x>1)
    {

        // x must be a prime 
    	ll num = 1; 
    	for(ll i = 0 ; i < num; i++) val *= x; 
    	for(ll i = 0 ; i < 3 - num ; i++) reverse_val *= x; 
    }
    return mp(val,reverse_val);
}


