LL a[N];
map<LL, int> MP;

void trans(LL x){
    LL p = 1;
    int c;
    for(LL i=2; i*i<=x; i++){
        c = 0;
        while(x % i == 0){
            x /= i;
            c++;
        }
        c %= 3;
        if(c == 1){
            p = p * i;
        } else if(c == 2){
            p = p * i * i;
        }
    }
    if(x > 1){
        if(x > lim){
            ans++;
            return;
        }
        p = p * x;
    }
    if(p == 1){
        flag = 1;
        return;
    }
    a[m++] = p;
    MP[p]++;
}

LL change(LL x){
    LL p = 1;
    int c;
    for(LL i = 2; i * i <= x; i++){
        c = 0;
        while(x % i == 0){
            x /= i;
            c++;
        }
        if(c == 1){
            p = p * i * i;
        } else if(c == 2){
            p = p * i;
        }
    }
    if(x > 1){
        p = p * x * x;
    }
    return p;
}

int main(){
    LL x, y;
    int c, d;
    while(~scanf("%d", &n)){
        m = ans = 0;
