                MP.erase(a[i]);
                y = change(a[i]);
                if(MP.count(y)){
                    d = MP[y];
                    MP.erase(y);
                } else {
                    d = 0;
                }
                ans += max(c, d);
            }
        }
        printf("%d\n", ans);
    }
    return 0;
}

