	return (n & 1) == 0;
}

//! Делит число на 2
template <class T>
void bisect(T & n)
{
	// n /= 2;
	n >>= 1;
}

//! Умножает число на 2
template <class T>
void redouble(T & n)
{
	// n *= 2;
	n <<= 1;
}

//! Возвращает true, если n - точный квадрат простого числа
template <class T>
bool perfect_square(const T & n)
{
	T sq = (T)ceil(sqrt((double)n));
	return sq*sq == n;
}

//! Вычисляет корень из числа, округляя его вниз
template <class T>
T sq_root(const T & n)
{
