namespace Sieve {
    constexpr int MAX = 5e6;
    vector<int> ps, pf, mu; // primes, min prime factor, moebius
    auto sieve_init = [](){
        pf.resize(MAX+1);
        iota(pf.begin(), pf.end(), 0);
        mu.resize(MAX+1,-1);
        mu[1] = 1;
        for (int i = 2; i <= MAX; ++i) {
            if (pf[i] == i) ps.push_back(i);
            for (int p : ps) {
                const int x = p*i;
                if (p > pf[i] || x > MAX) break;
                pf[x] = p;
                mu[x] = -mu[i];
                if (i%p == 0) mu[x] = 0;
            }
        }
        return 0;
    }();
    bool is_prime(int n) {
        assert(0 <= n); assert(n <= MAX);
        return pf[n] == n && n >= 2;
    }
    vector<pair<int,int> > prime_factor(int n) {
        assert(0 <= n); assert(n <= MAX);
        vector<pair<int,int> > ret;
        while (n > 1) {
            int p = pf[n], i = 0;
            while (pf[n] == p) ++i, n /= p;
            ret.emplace_back(p,i);
        }
        return ret;
    }
    vector<int> divisors(int n) {
        assert(0 <= n); assert(n <= MAX);
        vector<int> ret = {1};
        for (auto p : prime_factor(n)) {
            int m = ret.size();
            for (int i = 0; i < m; ++i) {
                for (int j = 0, v = 1;  j < p.second; ++j) {
                    v *= p.first;
                    ret.push_back(ret[i]*v);
                }
            }
        }
        return ret;
    }
