void get(long long x) {
	for(long long i=2; ; i++) {
		long long tmp = i*i*i;
		if(x < tmp) break;
		while(x % tmp == 0)  x /= tmp;
	}
	long long A = 1, B = 1;
	if(x%4 == 0) {
		B = 2;
		x /= 4;
	}
	else if(x%2 == 0) {
		A = 2;
		x /= 2;
	}
	for(int i=3; i <= sqrt(x) + 1; i+=2) {
		if(x%(i*i) == 0) {
			B *= i;
			x /= (i*i);
		}
		else if(x%i == 0) {
			A*= i;
			x /= i;
		}
	}
	A *= x;
	//cout << A << " " << B << endl;
	if(A == 1 && B == 1) f = 1;
	mp[{A, B}]++;
}

