    for(int i = 0; i < N; i++){
        long num;
        cin >> num;
        for(long j = 0; primes[j] * primes[j] * primes[j] <= num; ){
            if(num % (primes[j] * primes[j] * primes[j]) == 0){
                num /= primes[j] * primes[j] * primes[j];
            }else{
                j++;
            }
        }
        if(num == 1){
            is_in_1 = true;
        }else{
            nums[num]++;
        }
    }
    long ans = 0;
    for(auto item: nums){
        pair<long, int> i = item;
        long i_tmp = i.first;
        long not_square_num = 1, square_num = 1;
        for(long j = 0; primes[j] * primes[j] * primes[j] <= i.first; j++){
