                not_square_num *= primes[j];
                i_tmp /= primes[j] * primes[j];
            }else if(i.first % primes[j] == 0){
                square_num *= primes[j];
                i_tmp /= primes[j];
            }
        }
        square_num *= i_tmp;
        if(square_num >= 1e6){
            ans += i.second;
        }else{
