        // if (x % p == 0 and (x / p) % p == 0){
        if (x % (p * p) == 0){
            y *= p;
            x /= (p * p);
        }else if (x % p == 0){
            y *= (p * p);
            x /= (p);
        }
    }
    if (x != 1){
        y = y * (x * x);
    }
    return y;
}

