}

#include<bits/stdc++.h>
using namespace std;

typedef long long LL;
vector<LL> primes;
const int CBRT = 2200;
LL cb[CBRT];
const LL LIM = 1e11+5;


void sieve() {
    vector<bool> isp(CBRT, 1);
    for (int i=2; i<CBRT; i++)
        if (isp[i]) {
            primes.push_back(i);
            for (int j=2*i; j<CBRT; j+=i)
                isp[j] = 0;
        }
    for (int i=0; i<CBRT; i++)  cb[i] = 1LL*i*i*i;
}

pair<LL, LL> process(LL x) {
    if (x == 1)     return {1, 1};

    for (LL p:primes)
        while (x%cb[p]==0)  x/=cb[p];

    LL a = x;

    for (int i=1; i<CBRT; i++)
        if (cb[i]%a==0)
            return {a, cb[i]/a};

    return {a, LIM};
}

const int N = 1e5+7;
LL a[N], b[N];

int main() {
    ios::sync_with_stdio(0);
    cin.tie(0);

    sieve();

    int n;
    cin>>n;

    map<LL, int> cnt;
    map<LL, LL> opp;

    for (int i=1; i<=n; i++) {
        LL x;
        cin>>x;

        auto pr = process(x);
        a[i] = pr.first;
        b[i] = pr.second;

        cnt[a[i]]++;
        opp[a[i]] = b[i];
        opp[b[i]] = a[i];
    }
    cnt[LIM] = 0;

    LL ans = 0;
    for (auto pr: opp) {
        LL a = pr.first, b = pr.second;
        if (a == LIM)   continue;
        if (a == b)     ans += min(1, cnt[a]+cnt[b]);
        else if (a < b) ans += max(cnt[a], cnt[b]);
    }
    cout<<ans<<endl;
}

