	for(int i=1;i<=n;i++) RHO::fac(rd());
	int ans=0;
	for(it_m it=s1.begin();it!=s1.end();++it) 
		if((it->second)>s1[s2[it->first]] || ((it->second)==s1[s2[it->first]] && it->first>=s2[it->first])) ans+=it->second;
	cout<<ans+bz<<'\n'; 
}

