#include <bits/stdc++.h>

using namespace std;

#define N 100000
#define ll long long

int n, cnt, prime[N + 5], vis[N + 5], ans;
ll a[N + 5];
map<ll, int> rp, p2;
map<ll, ll> match;

void sieve() {
    vis[1] = 1;
    for (int i = 2; i <= N; ++i) {
        if (!vis[i])
            prime[++cnt] = i;
        for (int j = 1; j <= cnt && i * prime[j] <= N; ++j) {
            vis[i * prime[j]] = 1;
            if (i % prime[j] == 0)
                break;
        }
    }
    p2[1] = 1;
    for (int i = 1; i <= cnt; ++i)
        p2[1LL * prime[i] * prime[i]] = prime[i];
}

void pre() {
    // 预处理norm
    for (int i = 1; i <= n; ++i) {
        ll x = a[i], y = 1, z = 1;
        for (int j = 1; j <= cnt && 1LL * prime[j] * prime[j] * prime[j] <= x; ++j) {
            if (x % prime[j]) continue;
            int t = 0;
            while (x % prime[j] == 0) {
                x /= prime[j];
                t++;
            }
            t %= 3;
            if (t == 1) y = y * prime[j], z = z * prime[j] * prime[j];
            else if(t == 2) y = y * prime[j] * prime[j], z = z * prime[j];
        }
        rp[y * x]++;
        if (p2.count(x))
            match[y * x] = z * p2[x];
        else
            match[y * x] = z * x * x;
    }
}

void solve() {
    auto it = match.begin();
    while (it != match.end()) {
        if (it->first == 1) {
            ans++;
        }
        else if (rp.count(it->second)) {
            if (it->second > it->first)
                ans += max(rp[it->first], rp[it->second]);
        }
        else
            ans += rp[it->first];
        it++;
    }
}

