void init(){
    rep(i,MA) isPrime[i]=true;
    isPrime[0]=false;isPrime[1]=false;
    for(ll i=2;i<=MA;i++){
        if(isPrime[i]==false) continue;
        for(ll j=2;i*j<=MA;j++) isPrime[i*j]=false;
    }

    for(int i=2;i<=MA;i++){
        if(isPrime[i]){
