ll inverse(ll val){
    ll res=1;
    for(ll i=2;i<=100;i++){
        if(isPrime[i]==false) continue;
        int cnt=0;
        while(val%i==0){
            val/=i;
            cnt++;
        }
        cnt%=3;
        if(cnt==0) continue;
        while(cnt<3){
            cnt++;
            res*=i;
        }
    }
    return res;
}

