}

ll skrati(ll x){
	for(int i = 0;pr[i] * pr[i] * pr[i] <= x;i++){
		while(!(x % (pr[i] * pr[i] * pr[i])))
			x /= pr[i] * pr[i] * pr[i];
	}
	return x;
}

ll obrni(ll x){
	ll ret = 1;
	for(int i = 0;pr[i] * pr[i] * pr[i] <= x;i++){
		if(x % pr[i]) continue;
		ret *= pr[i]; x /= pr[i];
		if(x % pr[i])
			ret *= pr[i];
		else
			x /= pr[i];
	}
	ll kor = (ll)sqrtl(x);
	if(kor * kor == x)
		ret *= kor;
	else
		ret *= x * x;
	return ret;
}

