static void find(i64 x) {
	i64 &dual = van[x];
	i64 sqr, tx;
	int cnt;

	tx = x;
	dual = 1;
	for (auto i: primes) {
		if (x % i == 0) {
			cnt = 1;
			x/= i;
			if (x % i == 0) {
				cnt+= 1;
				x/= i; }

			switch (cnt) {
			case 1: {
				dual*= i * i;
