			case 2: {
				dual*= i;
				break; } } } }

	if (x == 1) {
		van[dual] = tx;
		return; }
	sqr = sqrt(x) + 0.5;

	if (sqr * sqr == x) {
		dual*= sqr;
		van[dual] = tx;
		return; }

	dual*= x * x;
	van[dual] = x; }

