      while (m % p == 0) {
        ++cnt;
        m /= p;
      }

      cnt %= 3;
      for (int j = 0; j < cnt; ++j) a *= p;
      for (int j = (3 - cnt) % 3; j > 0; --j) b *= p;
    }

    if (mp.count(m)) {
      a *= mp[m];
      b *= m;
    } else {
      a *= m * m;
      b *= m;
    }

    s.push_back(a);
    t.push_back(b);
  }
