typedef long long ll;
const int MAX=2510;

vector<ll> primes;
vector<bool> is_prime(MAX,true);
int sieve(){
    is_prime[0]=is_prime[1]=0;
    for (ll i=2;i<MAX;++i) if (is_prime[i]){
        primes.emplace_back(i);
        for (ll j=i*2;j<MAX;j+=i) is_prime[j]=false;
    }
    return primes.size();
}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    int m=sieve();
    vector<ll> cubics(m);
    for (int i=0;i<m;++i) cubics[i]=primes[i]*primes[i]*primes[i];
    int N; cin >> N;
    vector<ll> s(N);
    for (int i=0;i<N;++i) cin >> s[i];
    for (int j=0;j<m;++j)
        for (int i=0;i<N;++i)
            while(s[i]%cubics[j]==0)
                s[i]/=cubics[j];
    map<ll,int> cnt;
    for (int i=0;i<N;++i) ++cnt[s[i]];
    map<ll,bool> check;
    int ans=0;
    for (auto p:cnt){
        if (p.first==1){ans+=1; continue;}
        if (check[p.first]) continue;
        ll x=p.first,y=1;
        for (int j=0;j<m;++j) if (x%primes[j]==0){
            int div=3;
            while(x%primes[j]==0){--div; x/=primes[j];}
            for (int i=0;i<div;++i) y*=primes[j];
        }
        ll z=sqrt(x);
        if (z*z==x) y*=z;
        else y*=z*z;
        ans+=max(cnt[p.first],cnt[y]);
        check[p.first]=check[y]=true;
    }
    cout << ans << '\n';
}

