map<ll, int> factorize(ll n) {
  map<ll, int> ps;
  for (int i = 0; primes[i] * primes[i] <= n; i++) {
    while (n % primes[i] == 0) {
      ++ps[ primes[i] ];
      n /= primes[i];
    }
  }
  if (n > 1) ++ps[n];
  map<ll, int> res;
  for (auto it = ps.begin(); it != ps.end(); ++it) {
    int k = it->second % 3;
    if (k != 0) {
      res[it->first] = k;
    }
  }
  return res;
}

map<ll, int> inverse(const map<ll,int> a) {
  map<ll, int> b;
  for (auto it = a.begin(); it != a.end(); ++it) {
    b[ it->first ] = 3 - it->second;
  }
  return b;
}

