    ans += solve(a[i]);
  }
  for (auto cur : mp) {
    int w1 = cur.first.first, w2 = cur.first.second;
    if (w1 > w2) continue;
    if (w1 == 1 && w2 == 1) {
      ans++;
    } else {
      ans += max(mp[pi(w1, w2)], mp[pi(w2, w1)]);
    }
  }
  printf("%d\n", ans);
  return 0;
}

