#include <bits/stdc++.h>
using namespace std;
#define ll long long
#define N 300010
#define S 100000
int prime[N], snum = 325, pnum;
bool p[N];
void EulerSieve(int n) {
    for (int i = 2; i <= n; i++) {
        if (!p[i]) prime[++pnum] = i;
        for (int j = 1; j <= pnum; j++) {
            if (i * prime[j] > n) break;
            p[i * prime[j]] = true;
            if (i % prime[j] == 0) break;
        }
    }
}
ll s[N], a[N];
int n, len[N], k[N], num[N];
int id[N], ans;
bool cmp(int x, int y) { return a[x] < a[y]; }
int main() {
    EulerSieve(S);
    scanf("%d", &n);
    for (int i = 1; i <= n; i++) {
        scanf("%lld", &s[i]);
        k[i] = len[i] = 0, a[i] = 1;
        for (int j = 1; j <= snum; j++) {
            if (s[i] % prime[j]) continue;
            int m = 0;
            while (s[i] % prime[j] == 0) s[i] /= prime[j], m++;
            if (m %= 3) k[i] |= ((m & 1) << len[i]), len[i]++, a[i] *= prime[j];
        }
        if (s[i] > 1) {
            if (s[i] < S)
                k[i] |= (1 << len[i]), len[i]++, a[i] *= s[i];
            else {
                ll ss = sqrt(s[i]);
                if (ss * ss != s[i])
                    ans++, i--, n--;
                else
                    len[i]++, a[i] *= ss;
            }
        }
    }
    for (int i = 1; i <= n; i++) id[i] = i;
    sort(id + 1, id + n + 1, cmp);
    for (int l = 1, r = 1; l <= n; l = r + 1, r = l) {
        while (r < n && a[id[r]] == a[id[r + 1]]) r++;
        if (a[id[l]] == 1) {
            ans++;
            continue;
        }
        int maxn = (1 << len[id[l]]) - 1;
        for (int i = l; i <= r; i++) num[k[id[i]]]++;
        for (int i = l; i <= r; i++) {
            int x = k[id[i]], y = (maxn ^ k[id[i]]);
            if (num[x] >= num[y]) ans += num[x], num[x] = num[y] = 0;
        }
    }
    printf("%d\n", ans);
    return 0;
}

