void get(int x, int id) {
	int ans = 1, comp = 1; 
	for(auto p : pr) {
		if(p * p > x) break; 
		if(x % p == 0) {
			int cnt = 0; 
			while(x % p == 0) {
				x /= p; 
				cnt++; 
			}
			cnt %= 3; 
			if(!cnt) continue; 
			for(int i = 1; i <= cnt; i++) ans *= p; 
			for(int i = 1; i <= 3 - cnt; i++) comp *= p; 
		}
	}
	if(x > 1) {
		ans *= x; 
		comp *= x * x;
	}
	b[id] = {ans, comp}; 
}

