};

vector < long long > primes(int n) {
	vector < int > used(n);
	vector < long long > ans;
	ans.reserve(n);
	for (int i = 2; i < n; ++i) {
		if (!used[i]) {
			ans.push_back(i);
			for (int j = i + i; j < n; j += i) {
				used[j] = 1;
			}
		}
	}
	return ans;
}

vector < long long > pow_3 (int n) {
	vector < long long > ans (n);
	for (long long i = 0; i < n; ++i) {
		ans[i] = i * i * i;
	}
	return ans;
}

void del_pow_3 (vector < long long > &x, vector < long long > &pr) {
	for (int i = 0; i < x.size(); ++i) {
		if (c) cout << x[i] << " ";
		long long temp = x[i];
		long long res = 1;
		for (int j = 0; j < pr.size() && pr[j] < temp; ++j) {
			int cnt = 0;
			while (temp % pr[j] == 0) {
				cnt++;
				temp /= pr[j];
			}
			cnt %= 3;
			while (cnt) {
				cnt--;
				res *= pr[j];
			}
		}
		res *= temp;
		x[i] = res;
		if (c) cout << x[i] << endl;
	}
}

struct test_input read_data (){
	int n;
	cin >> n;
	vector < long long > x(n);
	for (auto &p: x) {
		cin >> p;
	}
