ll tp(ll x){

  ll A=1,B=1; bool f1=0,f2=0;

  for(int i=0;; i++){

    int cnt=0; ll q=prime[i];

    if(q==0){
      if(x==1) break;
      if(x>1){
        A*=x; f1=1;
      }
      break;
    }
    if(x==1) break;
    while(x%q==0){
      x/=q;
      cnt++;
    }

    if(cnt==1){ A*=q; f1=1;}
    else if(cnt==2){ B*=q*q; f2=1;}

  }

  if(f1&&!f2) return 1;
  else if(!f1&&f2) return 2;
  else if(f1&&f2){
    if(A*B<A*A*sqrt(B)) return 3;
    else return 4;
  }
  else if(!f1&&!f2) return 5;

}

ll pr(ll x){

  ll A=1,B=1; bool f1=0,f2=0;

  for(int i=0;; i++){

    int cnt=0; ll q=prime[i];

    if(q==0){
      if(x==1) break;
      if(x>1){
        A*=x; f1=1;
      }
      break;
    }
    if(x==1) break;
    while(x%q==0){
      x/=q;
      cnt++;
    }

    if(cnt==1){ A*=q; f1=1;}
    else if(cnt==2){ B*=q*q; f2=1;}

  }

  if(f1&&!f2) return A*A;
  else if(!f1&&f2) return sqrt(B);
  else if(f1&&f2) return A*A*sqrt(B);

}



