void pan(ll &x,ll &w){
	w=1;ll o=1;
	for(int i=1;i<=cnt&&1LL*prime[i]*prime[i]*prime[i]<=x;i++){
		int g=0;
		while(x%prime[i]==0) g++,x/=prime[i];
