	ll g=sqrt(x);
	if(g*g==x) o*=x,w*=g;
	else{
		o*=x;
		if(x<=100000) w*=x*x;
		else w=0;
	}
	if(mp.find(o)==mp.end()) mp[o]=0;
	mp[o]++;
	x=o;
}
