#define LIM 1E10

using namespace std;

#define R 2200

int n, pr[2005], p, ans;
LL s[100005], pal[100005];

map<LL, int> M;
map<LL, int> M_pal;

int main(){
	FI(i, 2, R){
		bool isp = true;
		for(int j = 2; j * j <= i; j++){
			if(i % j == 0) isp = false;
		}
		if(isp) pr[++p] = i;
	}

	scanf("%d", &n);
	FI(i, 1, n){
		scanf("%lld", &s[i]);
		FI(j, 1, p){
			LL u = 1LL * pr[j] * pr[j] * pr[j];
			while(s[i] % u == 0){
				s[i] /= u;
			}
		}
		//now (s[i] == 1) or (s[i] is perfect cube-free)
		LL prod_of_small = 1, tmp = s[i];
		pal[i] = 1;
		FI(j, 1, p){
			if(tmp % pr[j] == 0){
				LL u = 1LL * pr[j] * pr[j] * pr[j];
				while(tmp % pr[j] == 0){
					tmp /= pr[j];
					u /= pr[j];
					prod_of_small *= pr[j];
				}
				if(pal[i] == -1 || (1.0 * pal[i] * u > LIM)){
					pal[i] = -1;
				} else pal[i] *= u;
			}
		}
		if(tmp > 1){
			LL rt = sqrt(tmp);
			if(rt * rt == tmp && pal[i] != -1) pal[i] *= rt;
			else pal[i] = -1;
		}
	}
//	FI(i, 1, n) printf("%d: %lld %lld\n", i, s[i], pal[i]);
	FI(i, 1, n){
		if(!M.count(s[i])){
			M[s[i]] = 1;
			M_pal[s[i]] = pal[i];
		}
		else M[s[i]]++;
	}
	for(auto pi: M){
		LL u = pi.fi, cnt = pi.se;
		LL pa = M_pal[u];
		if(pa == -1) ans += cnt;
		else if(pa == u) ans++;
		else if(pa > u){
			if(M.count(pa)) ans += max(cnt, (LL)M[pa]);
			else ans += cnt;
		}
	}
	printf("%d\n", ans);
	return 0;
}

