using namespace std;
typedef long long int ll;

map <ll,int> mp;
map <ll,int>::iterator it;

ll to(ll x)
{
	for(ll i=2;;i++)
	{
		ll t=i*i*i;
		if(t>x) break;
		while(x%t==0) x/=t;
	}
	return x;
}
ll tg(ll x)//toしてる -> x=P*Q^2 に直したい -> そして、P^2*Qに
{
	ll A=1,B=1;
	for(ll i=2;;i++)
	{
		if(i*i*i>x) break;
		int cnt=0;
		while(x%i==0)
		{
			x/=i;
			cnt++;
		}
		if(cnt%2==1)
		{
			A*=i;
			cnt--;
		}
		for(int j=0;j<cnt/2;j++) B*=i;
	}
	//x/(A*B^2)=C*D^2だから、C=1 or D=1
	ll dt=(ll) floor(sqrt(x)+0.5);
	if(dt*dt==x) B*=dt;
	else A*=x;
	return A*A*B;
}
int main()
{
	int n;
	scanf("%d",&n);
	for(int i=0;i<n;i++)
	{
