map<int64, int64> pair_num;
map<int64, int> dict;
vector<int> primes;

vector<int64> primes3;


void factorize3(int64 x) {
    FOR(i, primes3.size()) {
        while (x % primes3[i] == 0) {
            x /= primes3[i];
        }
    }
    int64 xr = x * x;
    int64 number = x;
    FOR(i, primes3.size()) {
        while (xr % primes3[i] == 0) {
            xr /= primes3[i];
        }
    }
    int64 rev_number = xr;
    pair_num[number] = rev_number;
    pair_num[rev_number] = number;
    dict[number]++;
}

bool u[4001];

void prepare() {
    if (!primes.empty())
        return;
    primes3.reserve(4000);
    for (int i = 2; i < 4000; ++i) {
        if (!u[i]) {
            primes3.push_back(i * 1LL * i * 1LL * i);
            for (int j = i + i; j < 4000; j += i) {
                u[j] = true;
            }
        }
    }
}

void solve(istream& in, ostream& out) {
    prepare();
    dict.clear();
    int n = next<int>(in);
    vector<int64> a = next_vector<int64>(in, n);
    for (int64 el : a) { factorize3(el); }
    int res = 0;
    for (auto v : dict) {
        if (v.first == 1) {
            ++res;
            continue;
        }
        int64 rev_v = pair_num[v.first];
        res += max(v.second, dict[rev_v]);
        dict.erase(rev_v);
    }
    out << res << endl;
}


