inline ll fast_pot(ll a, ll b, ll mod) {
	ll res = 1;
	ll akta = a;
	while(b) {
		if(b%2==1) {
			res *= akta;
			res %= mod;
		}
		akta *= akta;
		akta %= mod;
		b/=2;
	}
	return res;
}

