            mq[(LL)i * i] = i;
        }
    map<pair<LL, LL>, int> mp;
    for(int i = 0; i < N; i += 1){
        long long s;
        cin >> s;
        LL d = 1, norm = s, pair = 1;
        for(int j = 0; p[j] * p[j] * p[j] <= s; j += 1){
            int r = 0;
            for(LL x = s; x % p[j] == 0; x /= p[j]){
                r = r + 1;
                d *= p[j];
            }
            for(int i = 0; i < r / 3 * 3; i += 1) norm /= p[j]; 
            for(int i = 0; i < (3 - r % 3) % 3; i += 1) pair *= p[j]; 
        }
        if(mq.count(s / d)) pair *= mq[s / d];
        else pair *= (s / d) * (s / d);
        mp[{norm, pair}] += 1;
    }
