bool v[N];
int p[M],c,n,d[N],l,r,A;
long long a[N+1],t,s;
int main()
{
	for(int i=2;i<N;i++)
	{
		if(!v[i])
			p[++c]=i;
		for(int j=1;i*p[j]<N&&j<=c;j++)
		{
			v[i*p[j]]=true;
			if(i%p[j]==0)
				break;
		}
	}
	cin>>n;
	for(int i=1;i<=n;i++)
		cin>>a[i];
	for(int i=1;i<=n;i++)
		for(long long j=2;j*j*j<=a[i];j++)
			while(a[i]%(j*j*j)==0)
				a[i]/=j*j*j;
	sort(a+1,a+n+1);
	for(int i=n;i>=1;i--)
		if(a[i]!=a[i+1])
			d[i]=1;
		else
			d[i]=d[i+1]+1;
	for(int i=1;i<=n;i++)
		if(a[i]==a[i-1])
			d[i]=d[i-1];
	for(int i=1;i<=n;i++)
	{
		t=a[i],s=1;
		for(int j=1;(long long)p[j]*p[j]<=t&&j<=c;j++)
			if(t%p[j]==0)
			{
				s*=p[j],t/=p[j];
				if(t%p[j]==0)
					t/=p[j];
			}
		if(t>1||s/(a[i]/s)>L/s)
			continue;
		t=s/(a[i]/s)*s,l=1,r=n;
		while(l<r)
			if(a[(l+r)/2]>=t)
				r=(l+r)/2;
			else
				l=(l+r)/2+1;
		if(a[l]==t&&(d[i]<d[l]||(d[i]==d[l]&&a[i]>a[l])))
			A--;
	}
	if(a[1]==1)
		A-=d[1]-1;
	cout<<A+n;
	return 0;
}

