#define MAX_N 3000
int prime[MAX_N];//i番目の素数
bool is_prime[MAX_N + 1];
int min_factor[MAX_N + 1];//最小の素因数
int sieve(int n) {
	int p = 0;
	memset(is_prime, true, sizeof(is_prime));
	is_prime[0] = is_prime[1] = false;
	min_factor[0] = 0;
	min_factor[1] = 1;
	for (int i = 2; i <= n; i++) {
		if (is_prime[i]) {
			min_factor[i] = i;
			prime[p++] = i;
			for (int j = 2 * i; j <= n; j += i) {
				is_prime[j] = false;
				if (min_factor[j] == 0)min_factor[j] = i;
			}
		}
	}
	return p;
}

int np;
vector<pair<long long, int> > prime_factor(long long n) {
	vector<pair<long long, int> > res;
	rep(i,np) {
		if (n == 1)break;
		int num = 0;
		while (n%prime[i]==0) {
			n /= prime[i];
			num++;
		}
		if(num%3)res.push_back(make_pair(prime[i], num%3));
	}
	if (n>1)res.push_back(make_pair(n, 1));
	return res;
}


vector<pair<long long, int>> pf[100000];



long long f(vector<pair<long long, int>> v) {
	long long res = 1;
	for (auto p : v) {
		rep(i,p.second) {
			res *= p.first;
		}
	}
	return res;
}


