		vector<pair<ll, int>> cur;
		for (auto it : cubes) {
			if (it > x) {
				break;
			}
			while (x % it == 0) {
				x /= it;
			}
		}
		if (x == 1) {
			was_cube = true;
			continue;
		}
		if (lol.find(x) != lol.end()) {
			cur = lol[x];
		}
		else {
			for (auto it : primes) {
				if (it * 1ll * it > x) {
					break;
				}
				if (x % it == 0) {
					x /= it;
					if (x % it == 0) {
						x /= it;
						cur.pb({it, 2});
					}
					else {
						cur.pb({it, 1});
					}
				}
			}
			if (x > 1) {
				cur.pb({x, 1});
			}
		}
		lol[x] = cur;
		calc[cur]++;
	}
	int ans = 0;
