			antiit.pb({kek.F, 3 - kek.S});
		}
		if (calc.find(antiit) != calc.end()) {
			used[it.F] = true;
			used[antiit] = true;
			ans += max(it.S, calc[antiit]);
		}
		else {
			ans += it.S * 2;
		}
	}
	ans /= 2;
	if (was_cube) {
		ans++;
	}
	cout << ans << '\n';
}

