void solve() {
    int n, ans = 0;
    cin >> n;
    vi a(n);
    for (int i = 0; i < n; i++) {
        cin >> a[i];
        int res = 1;
        for (int d = 2; d * d * d <= a[i]; d++) {
            while(a[i] % (d * d * d) == 0)
                a[i] /= (d * d * d);
        }
        int x = a[i];
        for (int d = 2; d * d * d <= x; d++) {
            int pw = 0;
            while(x % d == 0) {
                pw ++;
                x /= d;
            }
            if(pw == 1)
                res *= d * d;
            if(pw == 2)
                res *= d;
        }
        if(int s = sqrt(x); s * s == x) {
            res *= s;
        } else {
            res *= x * x;
        }
        mp[a[i]]++;
        rev[a[i]] = res;
    }
    for (auto u : mp) {
        if(u.first == 1)
            ans += !!u.second;
        else {
            ans += max(u.second, mp[rev[u.first]]);
            mp[rev[u.first]] = 0;
            mp[u.first] = 0;
        }
    }
    cout << ans;
}

