				}
				else if(inv <= inf) {
					inv *= p[j];
				}
				else break;
			}
		}
		int val = square_root(x);
		if (1LL * val * val == x) {
			x = 1;
			if(inv <= inf) inv *= val;
		}
		else {
			if (x >= inf) inv = inf;
			else {
				if (inv <= inf) inv *= x;
				if (inv <= inf) inv *= x;
			}
			x = 1;
		}
