typedef pair<int, int> P;

int normalize(int s) {	//正整数n, mで「n * m^3 = s」と表すときの最大のmをMとおき、s/M^3を返す。
	int n, m;
	double eps1 = 1e-10;
	double eps2 = 1e-9;

	for (n = 1; n <= 316; n++) {
		if (s % n == 0) {
			double md = pow(s / n, 1.0 / 3) + eps1;
			int m = (int)md;
			if (md - m <= eps2) {
				return s / (m * m * m);
			}
		}
	}
	for (m = 316; m >= 1; m--) {
		if (s % (m * m * m) == 0) {
			return s / (m * m * m);
		}
	}
	return -1;
}

bitset<400000001> bset;
void prepare() {
	int i;

	for (i = 1; i <= 20000; i++) {
		bset[i * i] = 1;
	}
}

int findPair(int s) {	//正整数n, mで「n * m^2 = s」と表すときの最大のmをMとおき、(s / M^2)^2 * Mを返す。
	int n, m;
	double eps1 = 1e-10;
	double eps2 = 1e-9;

	for (n = 1; n <= 2200; n++) {
		if (s % n == 0) {
			if (n >= 50) {
				if (bset[s / n]) {
					m = (int)(sqrt((double)s / n) + eps1);
					return n * n * m;
				}
			}
			else {
				double md = sqrt((double)s / n) + eps1;
				int m = (int)md;
				if (md - m <= eps2) {
					return n * n * m;
				}
			}
		}
	}
	for (m = 2200; m >= 1; m--) {
		if (s % (m * m) == 0) {
			n = s / (m * m);
			if (n > 100000) return -1;
			return n * n * m;
		}
	}
	return -1;
}

