bool is_sqr(ll x){
	ll g = static_cast<ll>(sqrt(x));
	for(ll r = max(0ll, g - 5); r <= g + 5; r++)
		if(r * r == g)
			return true;
	return false;
}

ll sqr(ll x){
	ll g = static_cast<ll>(sqrt(x));
	for(ll r = max(0ll, g - 5); r <= g + 5; r++)
		if(r * r == x)
			return r;
	return g;
}

ll pw(ll x, int c){
	switch(c){
		case 0:
			return 1;
		case 1:
			return x;
		case 2:
			return x * x;
		case 3:
			return 1;
	}
	return 0;
}

