using i64 = long long;

int main() {
    constexpr i64 lim = 10000000000;
    std::vector<i64> cubes, sq;
    for (i64 i = 1; ; i++) {
        i64 s = i * i, c = s * i;
        if (c > lim) break;
        sq.push_back(s);
        cubes.push_back(c);
    }

    int len = sq.size();

    int n;
    std::cin >> n;
    std::map<i64, int> cnt;
    for (int i = 0; i < n; i++) {
        i64 s;
        std::cin >> s;
        int from = std::upper_bound(cubes.begin(), cubes.end(), s) - cubes.begin() - 1;
        for (int j = from; j >= 0; j--) if (s % cubes[j] == 0) {
            cnt[s / cubes[j]]++;
            break;
        }
    }

    int ret = cnt[1] > 0;
    std::map<i64, bool> done;
    done[1] = true;
    for (auto e : cnt) {
        i64 m = e.first;
        int c = e.second;
        if (done[m]) continue;
        for (i64 x = 0; x < len; x++) {
            if (m % sq[x]) continue;
            i64 y = m / sq[x];
            if (x + 1 >= y) break;
            if ((x + 1) * y > lim / y) break;
            i64 other = (x + 1) * y * y;
            auto it = cnt.find(other);
            if (it == cnt.end()) continue;
            ret += std::max(it->second, c);
            done[m] = true;
            done[other] = true;
            break;
        }
    }

    for (auto e : cnt) if (!done[e.first]) ret += e.second;

    std::cout << ret << std::endl;

    return 0;
}

