#include <bits/stdc++.h>

using namespace std;

using ll = long long;

const int BUB = 4007;

ll norm(ll x) {
    for (int i = 2; i <= BUB; i++) {
        ll t = ll(i) * i * i;
        while (x % t == 0) {
            x /= t;
        }
    }
    return x;
}

ll inv(ll x) {
    ll ans = 1;
    for (int i = 2; i <= BUB; i++) {
        ll t = ll(i) * i * i;
        while (x % t == 0) {
            x /= t;
        }
        ll q = ll(i) * i;
        if (x % q == 0) {
            x /= q;
            ans *= i;
        } else if (x % i == 0) {
            x /= i;
            ans *= q;
        }
    }
    if (x != 1) {
        ll sq = sqrt(x);
        while (sq * sq < x) {
            sq++;
        }
        if (x % sq == 0) {
            ans *= sq;
        } else {
            ans = -1;
        }
    }
    return ans;
}


