bool isp[M];
bool cmp(LL x,LL y){return t[x]<t[y];}
int main(){
	memset(isp,true,sizeof(isp));
	for(LL i=2;i<MAXN;i++){
		if(!isp[i]) continue; pri[++m]=i;
		for(LL j=i;j<MAXN;j+=i) isp[j]=false;
	} n=read();
	for(LL j,i=1;i<=n;i++){
		for(p[i]=read(),sz[i]=0,j=t[i]=1;j<=m;j++){
			if(p[i]%pri[j]>0) continue; LL cnt=0;
			while(p[i]%pri[j]==0) p[i]/=pri[j],++cnt; cnt%=3;
			if(cnt) K[i]|=((cnt&1)<<sz[i]),sz[i]++,t[i]*=pri[j];
		} if(p[i]>1ll) res++,i--,n--;
	}
	for(LL i=1;i<=n;i++) od[i]=i; sort(od+1,od+n+1,cmp);
	for(LL l=1,r;l<=n;l=r+1){
		for(r=l;r<n&&t[od[r]]==t[od[r+1]];r++);
		if(!sz[od[l]]){res++;continue;}
		LL maxn=(1<<sz[od[l]])-1;
		for(LL i=l;i<=r;i++) mp[K[od[i]]]++;
		for(LL i=l;i<=r;i++){
			LL x=K[od[i]],ot=(maxn^K[od[i]]);
			if(mp[x]>=mp[ot]) ans+=mp[x],mp[x]=mp[ot]=0;
		}
		for(LL i=l;i<=r;i++) mp[K[od[i]]]=0;
	} printf("%lld\n",ans+res); return 0;
