const i64 M = 1000000000;

void solve() {
  int n;
  cin >> n;
  vector<i64> a(n);
  forn(i, n) cin >> a[i];
  unordered_map<i64, pair<i64, int> > M;
  unordered_map<i64, int> S;
  for(i64 x: a) S[x] += 1;
  for (const auto& e: S) {
    i64 x = e.fi;
    i64 ca = 1, cb = 1;
    // cerr << x << ": ";
    for (i64 j = 2; j * j * j <= x; ++j) {
      if (x % j == 0) {
        int i = 0;
        while (x % j == 0) { x /= j; i += 1; }
        i %= 3;
        forn(t, i) ca *= j;
        if (i > 0) forn(t, 3 - i) cb *= j;
      }
    }
    if (x > 1) {
      i64 sx = sqrtl((ld)x + 0.5);
      if (sx * sx == x) {
        ca *= x;
        cb *= sx;
      } else {
        ca *= x;
        cb *= x * x;
      }
    }
    // cerr << ca << " " << cb << '\n';
    M[ca].fi = cb;
    M[ca].se += e.se;
    M[cb].fi = ca;
  }
  int r = 0;
  for (const auto& e: M) if (e.fi != 1) {
    // cerr << e.fi << ':' << e.se.fi << ' ' << e.se.se << '\n';
    r += max(e.se.se, M[e.se.fi].se);
    // cerr << r << '\n';
  }
  r /= 2;
  r += min(1, M[1].se);
  cout << r << '\n';
}

