ll get1(ll s)
{
    ll g=1;
    for(ll i=2;i*i<=s;i++)
    {
        int k=0;
        while(s%i==0)
        {
            s/=i;
            k++;
            k%=3;
        }
        while(k--) g*=i;
    }
    if(s!=1) g*=s;
    return g;
}

ll get2(ll s)
{
    ll g=1;
    for(ll i=2;i*i<=s;i++)
    {
        int k=0;
        while(s%i==0)
        {
            s/=i;
            k++;
            k%=3;
        }
        k=(3-k)%3;
        while(k--) g*=i;
    }
    if(s!=1) g*=s*s;
    return g;
}

void calc(ll s)
{
    cnt1[get1(s)]++;
    cnt2[get2(s)]++;
}

