#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const int MAX=1e5+10;

vector<ll> primes;
vector<bool> is_prime(MAX,true);
int sieve(){
    is_prime[0]=is_prime[1]=0;
    for (ll i=2;i<MAX;++i) if (is_prime[i]){
        primes.emplace_back(i);
        for (ll j=i*2;j<MAX;j+=i) is_prime[j]=false;
    }
    return primes.size();
}

template<typename T>
map<T,int> prime_factor(T n){
    map<T,int> res;
    for (int i=0;primes[i]*primes[i]<=n;++i) if (n%primes[i]==0){
        int cnt=0;
        while(n%primes[i]==0){++cnt; n/=primes[i];}
        if (cnt%3!=0) res[primes[i]]=cnt%3;
    }
    if (n!=1) res[n]=1;
    return res;
}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    int m=sieve();
    int N; cin >> N;
    vector<ll> s(N);
    for (int i=0;i<N;++i) cin >> s[i];
    map<map<ll,int>,int> group;
    int ans=0;
    for (int i=0;i<N;++i){
        map<ll,int> m=prime_factor(s[i]);
        if (m.empty()) ans=1;
        else ++group[m];
    }
    map<map<ll,int>,int> check;
    for (auto x:group){
        if (check[x.first]) continue;
        map<ll,int> other;
        for (auto y:x.first) other[y.first]=3-y.second;
        ans+=max(x.second,group[other]);
        check[x.first]=check[other]=1;
    }
    cout << ans << '\n';
}

