			if (v % p != 0) continue;
			int cnt = 0;
			while (v % p == 0) {
				cnt++;
				v /= p;
			}
			if (cnt % 3 == 1) {
				val *= p;
				another *= p * p;
			}
			else if (cnt % 3 == 2) {
				val *= p * p;
				another *= p;
			}
		}
		if (v > 1) {
			LL tmp = sqrt(v);
			LL root = 0;
			for (int i = -1; i < 2; i++) if ((tmp + i) * (tmp + i) == v) root = tmp + i;
			val *= v;
			if (root) another *= root;
			else another *= v * v;
		}
		cnts[val].second = another;
		cnts[val].first++;
	}
	auto tmp = cnts;
