unordered_map<ll,ll> U,num,D; ll ans=0;

bool bat(ll x) {
    ll y=1,yy=1; ll &xx=U[x];
    for (int i=1; i<=tot && (ll)p[i]<=x; ++i)
        if (x%p[i]==0) {
            int t=0;
            while (x%p[i]==0) x=x/p[i],t++;
            t%=3;
            rep(j,0,t) y*=p[i];
            t=3-t,t%=3;
            rep(j,0,t) yy*=p[i];
        }
    if (x>1) {
        ans+=2;
        xx=-1;
        return 1;
    }
    xx=y;
    D[y]=yy,D[yy]=y;
    return 0;
}

