#include<bits/stdc++.h>
typedef long long ll;
ll gi(){
	ll x=0,f=1;
	char ch=getchar();
	while(!isdigit(ch))f^=ch=='-',ch=getchar();
	while(isdigit(ch))x=x*10+ch-'0',ch=getchar();
	return f?x:-x;
}
struct cxk{ll s,c,o;}s[100010];
int pr[100010],P;
bool yes[100010];
std::unordered_map<ll,ll>M;
cxk fuck(ll x){
	ll r=1,o=1;
	for(ll j=1;pr[j]<=2154;++j)
		if(x%pr[j]==0){
			int e=0;while(x%pr[j]==0)++e,x/=pr[j];
			e%=3;for(int i=0;i<e;++i)r*=pr[j];
			if(e)for(int i=e;i<3;++i)o*=pr[j];
		}
	if(x!=1){
		ll qt=int(sqrt(x)+0.5);
		if(qt*qt==x)o*=qt;
		else if(1.0*o*x*x>1e18)o=2e18;
		else o*=x*x;
	}
	return{r*x,1,o};
}
int main(){
	int n=gi(),ans=n;
	for(int i=2;i<=100000;++i){
		if(!yes[i])pr[++P]=i;
		for(int j=1;j<=P&&i*pr[j]<=100000;++j){
			yes[i*pr[j]]=1;
			if(i%pr[j]==0)break;
		}
	}
	for(int i=1;i<=n;++i)s[i]=fuck(gi()),s[i].c=1;
	std::sort(s+1,s+n+1,[](cxk a,cxk b){return a.s<b.s;});
	for(int i=1;i<=n;++i)if(s[i].s==s[i-1].s)s[i].c=s[i-1].c+1,s[i-1].c=-1;else s[i].c=1;
	for(int i=1;i<=n;++i)if(s[i].c==-1)s[i]=s[n],--n,--i;
	std::sort(s+1,s+n+1,[](cxk a,cxk b){return a.s<b.s;});
	for(int i=1;i<=n;++i){
		if(s[i].s==1)ans-=s[i].c-1;
		else{
			if(M.count(s[i].o))ans-=std::min(s[i].c,M[s[i].o]);
			M[s[i].s]=s[i].c;
		}
	}
	printf("%d\n",ans);
	return 0;
}

