	rep(i,0,n){
		vector<pair<int,int>> bs;
		for (int j = 0; j < sz(s) && s[j]*s[j] <= a[i]; ++j){
			int k = 0;
			while(a[i]%s[j] == 0){
				k++;
				a[i] /= s[j];
				if(k == 3) k = 0;
			}
			if(k) bs.push_back({s[j],k});
		}
		if(a[i] > 1){
			ll q = sqr(a[i]);
			if(q*q == a[i]) bs.push_back({q,2});
			else bs.push_back({a[i],1});
		}
		ll bsn = 1;
		ll rsn = 1;
		for(pair<int,int> w:bs){
			if(w.second == 1){
				bsn *= w.first;
				rsn *= w.first;
				rsn *= w.first;
			}
			if(w.second == 2){
				bsn *= w.first;
				bsn *= w.first;
				rsn *= w.first;
			}
		}
		if(bsn <= rsn) act[bsn]++;
		ful[min(bsn,rsn)]++;
	}
	int ans = 0;
	for(auto el:ful){
		if(el.first == 1) continue;
		ans += max(act[el.first],el.second-act[el.first]);
	}
	cout << ans+(act[1]>0);
	return 0;
}

#include<bits/stdc++.h>

using namespace std;

#define int long long

const int   N   = 1e6 + 1;

vector<int> p;
bool npr[N];
int n;
map<int,int> s, f;

void sieve()    {
	for(int i = 2 ; i < N ; ++i)
		if(!npr[i]) {
			p.push_back(i);
			for(int j = i * i ; j < N ; j += i)
				npr[j] = 1;
		}
}

signed main()   {
	ios_base::sync_with_stdio(0);
	cin.tie(0); cout.tie(0);

	sieve();

	cin >> n;
	int ans = 0;

	for(int i = 1 ; i <= n ; ++i)   {
		int x, y, z;    cin >> x;
		y = z = 1;
		for(int j = 0 ; p[j] * p[j] <= x ; ++j) {
			int exp = 0;
			while(x % p[j] == 0)    {
				++exp;
				x /= p[j];
			}
			exp %= 3;
			if(exp == 1)    y *= p[j],  z *= p[j] * p[j];
			if(exp == 2)    y *= p[j] * p[j],  z *= p[j];
		}
		if(x > N)   ans++;
		else    {
			if(x > 1)   {
				y *= x;
				z *= x * x;
			}
			s[y]++;
			f[y] = z;
			f[z] = y;
		}
	}

	if(s.count(1))  {
		ans++;
		s.erase(1);
	}

	auto it = s.begin();
	while(it != s.end())    {
		int x = it -> first;
		int y = f[x];
		if(s[x] < s[y]) swap(x,y);
		ans += s[x];
		s.erase(x);
		s.erase(y);
		it = s.lower_bound(x);
	}

	cout << ans << endl;
}

//Link : https://atcoder.jp/contests/arc055/tasks/arc055_c
#include <bits/stdc++.h>

using namespace std;
#define ll long long
#define N 1000001

bool isNotPrime[N];
void solve() {
  int n;scanf("%d ", &n);
  int cubic = 0,ret = 0;
  set<ll> sq;
  const ll maxi = 1e10;

  vector<int> prime;
  set<ll> cubicList;
  cubicList.insert(1);
  for(int i=2;i<N;++i) {
    if(!isNotPrime[i]) {
      ll x = i;
      x *=i;
      x *=i;
      if(x<=maxi) {
        prime.push_back(i);
        cubicList.insert(x);
      }
      for(int j=i+i;j<N;j+=i) {
        isNotPrime[j] = true;
      }
    }
  }
  for(ll i=1;i*i<=maxi;++i) {
    if(!isNotPrime[i])
      sq.insert(i*i);
  }
  map<ll,ll> op;
  map<ll,ll> pcount;
  for(int i=0;i<n;++i) {
    ll in;scanf("%lld ", &in);
    if(cubicList.count(in)) {
      cubic = 1;
      continue;
    } else {
      ll mn=1,mp=1;
      ll cur = in;
      for(int j = 0;j<prime.size();++j) {
        if(cur%prime[j]==0) {
          int cc = 0;
          while(cur%prime[j]==0) {
            ++cc;
            cur/= prime[j];
          }
          cc = cc%3;
          if(cc==1) {
            mn *= prime[j];
            mp *= prime[j];
            mp *= prime[j];
          } else if(cc==2) {
            mn *= prime[j];
            mn *= prime[j];
            mp *= prime[j];
          }
        }
      }
      if(cur!=1) {
        mn *= cur;
        ll s = sqrt(cur);
        if(s*s==cur) {
          mp *= s;
        } else {
          mp *= cur*cur;
        }
      }
      ++pcount[mn];
    }
  }

  for(map<ll,ll>::iterator it = op.begin();it!=op.end();++it) {
    ll x = it->first, y= it->second;
    if(x<y) {
      ret += max(pcount[x],pcount[y]);
    }
    pcount[x] = pcount[y] = 0;
  }
  assert(ret+cubic<=n);
  printf("%d\n", ret+cubic);
}
int main() {
    //freopen("input.txt","r",stdin);
    solve();
    return 0;
}

