pair<vll, vector<bool>> eratosthenes(ll n){
	vll primes;
	vector<bool> table(n+1);
	rep(i, 2, n){
		if (table[i]) continue;
		primes.push_back(i);
		for (ll j=2; i*j<=n; j++) table[i*j]=true;
	}
	return move(make_pair(move(primes), move(table)));
}


void solve()
{
	ll n;  cin >> n;
	vector<ll> s = cinv<ll>(n);

	ll m=2155;//(10^10)^(1/3)
	vll primes; vector<bool> cmptbl;  tie(primes, cmptbl) = eratosthenes(m);

	map<pll, ll> mp;
	rep(i, 0, n-1){
		ll v=s[i];
		ll x=1;//2乗
		ll y=1;//1乗
		each(p, primes){
			ll e=0;
			while (v%p==0){
				e++;
				v/=p;
			}
			e%=3;
			if (e==1) y*=p;
			if (e==2) x*=p;

			if (v==1) break;
		}
		if (v>1){
			//3乗はあり得ない。2乗があるとしたらvが平方数の場合のみ。
			dd qvd=sqrt(v);
			ll qv=(ll)(qvd+.1);
			if (qv*qv==v){
				x*=qv;
			}
			else{
				y*=v;
			}
		}
		mp[{x, y}]++;
	}

	ll ans=0;
	each(e, mp){
		pll pr; ll c;  tie(pr, c) = e;
		ll x; ll y;  tie(x, y) = pr;
		if (x>y)continue;
		if (x<y){
			ll d=0;
			if (mp.count({y,x})==1){
				d=mp[{y, x}];
			}
			ans+=max(c, d);
		}
		else{//x==y
			ans++;
		}
	}
	cout << ans << '\n';
}

int main(){
#if 1
	solve();
#else
	ll t;  cin >> t;
	rep(i, 0, t-1){
		solve();
	}
#endif
	return 0;
}

