long long rev_func(long long val) {
	if (val == 1) return 1;
	for (int i = 1; i <= 2154; i++) {
		long long cub = (long long)i * i * i;
		if (cub % val == 0) return cub / val;
	}
	return 0;
}
int main() {
	scanf("%d", &n);
	int i, j;
	for (i = 1; i <= n; i++) scanf("%lld", &s[i]);
	cnt[0] = 0;
	for (i = 1; i <= n; i++) {
		for (j = 2154; j >= 1; j--) {
			long long cub = (long long)j * j * j;
			if (s[i] % cub == 0) {
				s[i] /= cub; break;
			}
		}
		cnt[s[i]]++;
		long long rev = rev_func(s[i]);
		cnt[rev] = cnt[rev];
	}
	map<long long, int>::iterator iter;
	int ans = 0;
	for (iter = cnt.begin(); iter != cnt.end(); iter++) {
		long long num = (*iter).first;
		int count = (*iter).second;
		if (num == 0) continue;
		long long rev = rev_func(num);
		if (num == 1) {
			if (count > 0) ans++;
		}
		else {
			ans += max(cnt[num],cnt[rev]);
			cnt[num] = 0; cnt[rev] = 0;
		}
	}
	printf("%d", ans);
	return 0;
}

