int ef(int x){
	int l=1,r=n;
	while (l<r){
		int mid=(l+r)/2;
		if (a[mid]<x)l=mid+1;
		else r=mid;
	}
	if (a[l]!=x)return -1;
	return l;
}
signed main(){
	scanf("%lld",&n);
	for (int i=1;i<=n;i++){
		scanf("%d",&x);
		for (int j=2;j*j*j<=x;j++)
			while (x%(j*j*j)==0)x/=(j*j*j);
		a[i]=x;	
	} 
	sort(a+1,a+n+1);
	int tot=1;b[1]=1;
	for (int i=2;i<=n;i++){
		if (a[i]!=a[tot])a[++tot]=a[i];
		b[tot]++;
	}
	n=tot;
	for (int i=1;i<=n;i++){
		if (f[i])continue;
		if (a[i]==1){
			ans++;
			f[1]=1;
			continue;
		}
		x=a[i];
		int y=1,flag=1;
		for (int j=2;j*j*j<=x;j++){
			if (x%(j*j)==0){
				x/=(j*j);
				if (1e10/y<j){
					flag=0;
					break;
				}
				else y*=j;
			}
			if (x%j==0){
				x/=j;
				if (1e10/y/j<j){
					flag=0;
					break;
				}
				else y*=j*j;
			}
		}
		if ((int)sqrt(x)==sqrt(x)){
			int k=(int)sqrt(x);
			if (1e10/y<k)flag=0;
			else y*=k;
		}
		else {
			if (1e10/y/x<x)flag=0;
			else y*=x*x;
		}
		int p=ef(y);
