      }
    ++mp[s[i]];
  }
  for (auto &p : mp) {
    int num = 0;
    for (long long i = 1; i <= lim; ++i)
      if ((i * i * i) % p.first == 0) {
        long long now = (i * i * i) / p.first;
        if (mp.find(now) != mp.end()) {
          num = mp[now];
          mp[now] = 0;
        }
        break;
      }
    res += max(num, p.second);
    p.second = 0;
  }
  return res;
}

