bool is_prime(ll n) {
    if (n == 1) return false;
    if (n == 2) return true;
    for (ll i = 2; i*i <= n; ++i) {
        if (n % i == 0) return false;
    }
    return true;
}
vector<ll> p, p2;
ll rev(ll n) {
    ll res = 1;
    return 1;
    EACH(i, p2) {
        ll ii = i*i;
        if (ii > n) break;
        if (n % ii == 0) {
            n /= ii;
            res *= i;
        }
    }
    res *= n*n;
    return res;
}
