        p2.pb(i);
    }
    vector<ll> s(n); cin >> s;
    map<ll, ll> m;
    REP(i, n) {
        EACH(j, p) {
            ll jjj = j*j*j;
            while (s[i] % jjj == 0) s[i] /= jjj;
        }
        m[s[i]]++;
    }
    sort(ALL(s));
    s.erase(unique(ALL(s)), s.end());
    ll ans = 0;
