        ll rs = rev(s[i]);
        if (m[s[i]] == 0) continue;
        if (s[i] == rs) {
            ++ans;
        }
        else {
            ans += max(m[s[i]], m[rs]);
        }
        m[s[i]] = m[rs] = 0;
    }
    cout << ans << endl;
}

