// ローのアルゴリズム
// 計算結果はrho_retに保存される
map<ull,int> rho_ret; // {p, k}, pの素因数がk個存在
ull find_factor(ull z) {
    if (!(z&1)) return 2;
    ull c = rand() % z, x = 2, y = 2, d = 1;
    while (d == 1) {
        ull tp = (mul(y,y,z) + c) % z;
        y = (mul(tp,tp,z) + c) % z;
        x = (mul(x,x,z) + c) % z;
        d = __gcd(x>y ? x-y : y-x, z);
    }
    return d;
}
void rhofact_rec(ull z) {
    if (z==1) return;
    if (isPrime(z)) { rho_ret[z]++; return; }
    while(1) {
        ull f = find_factor(z);
        if (f != z) {
            rhofact_rec(f);
            rhofact_rec(z/f);
            break;
        }
    }
}
void rho(ull z) {
    rho_ret.clear();
    rhofact_rec(z);
}

int main(void) {
    cin.tie(0); ios::sync_with_stdio(false);
    ll n; cin >> n;
    vll a(n); rep(i, a.size()) cin >> a[i];
    map<ll, ll> memo_for, memo_rev;
    ll flag = 0;
    rep(i, n) {
        rho(a[i]);
        ll tmp_for = 1;
        for (auto& x : rho_ret) 
            rep(j, x.se % 3)
                tmp_for *= x.fi;
        flag |= tmp_for == 1;
        memo_for[tmp_for]++;

        long double tmp_rev = 1;
        for (auto& x : rho_ret) 
            rep(j, ((3 - x.se) % 3 + 3) % 3)
                tmp_rev *= x.fi;
        if (tmp_rev <= 1e10) {
            memo_rev[tmp_for] = tmp_rev;
            memo_rev[tmp_rev] = tmp_for;
        } else {
            memo_rev[tmp_for] = INF;
        }

    }

    for (auto x : memo_for) 
        if (!memo_for.count(memo_rev[x.fi])) 
            memo_for[memo_rev[x.fi]] = 0;

    ll ret = flag;
    for (auto x : memo_for) if (x.fi != 1 && x.fi < memo_rev[x.fi]) {
        ll l = x.se;
        ll r = memo_for[memo_rev[x.fi]];
        ret += max({l, r});
    }
    cout << ret << endl;
    return 0;
}

