void erast(){
    for(int i=0;i<=ma;i++){
        v[i] = 1;
    }
    for(int i=2;i*i<=ma;i++){
        if(v[i]){
            for(int j=0;i*(j+2)<=ma;j++){
                v[i*(j+2)]=0;
            }
        }
    }
    v[1] = false;
    for(ll i=2;i*i*i<=MAX;i++){
        if(v[i]){
            prime.push_back(i);
