        ll n = s;
        map<int,int> m;
        for(ll x:prime){
            if(x*x>s) break;
            while(n%x==0){
                n /= x;
                m[x]++;
            }
        }
        if(n!=1 && prime.back()>=n) m[n]++;
        if(n<=prime.back()){
            vec<P> v;
            bool iscube = true;
            for(auto& x:m){
                if(x.second%3) v.emplace_back(x.first,x.second%3);
                iscube &= x.second%3==0;
            }
            if(iscube) cube = true;
            else if(!v.empty()) mp[v]++;
        }else ans++;
    }
    ans += cube;
    int ans2 = 0;
    for(auto& v:mp){
        vec<P> other;
        for(auto& x:v.first) other.emplace_back(x.first,3-x.second);
        if(!mp.count(other)) ans += v.second;
        else ans2 += max(v.second,mp[other]);
    }
    ans += ans2/2;
    cout << ans << "\n";
}

