}

ll qmul(ll x,ll y,ll mod)
{
	ll res=0;
	while(y)
	{
		if(y&1) res=(res+x)%mod;
		x=(x+x)%mod;y=y/2;
	}
	return res;
}
ll qpow(ll x,ll y,ll mod)
{
	ll res=1;
	while(y)
	{
		if(y&1) res=res*x%mod;
		x=x*x%mod;y=y/2;
	}
	return res;
}
ll millerrabin=20;
ll isp(ll x)
{
	if(x<=2) return 1;int mb=millerrabin;
	while(mb--)
	{
		ll c=ran()%(x-2)+2;
		if(qpow(c,x-1,x)!=1) return 0;
	}

	return 1;
}
ll po;ll cnt1;
ll f(ll x,ll n)
{
	x=(qmul(x,x,n)+po)%n;
	return x;
}
ll rho(ll n)
{

	ll x=ran()%n,y=x;
	ll i=1,k=2;
	do{
		i++;
		x=f(x,n);
		if(y==x) return -1;
		ll d=__gcd(abs(y-x),n);
		if(d>1 and d<n) return d;
		if(i==k)k=k+k,y=x;
	}while(1);
	return -1;
}
void merge(vector<ll> &a,vector<ll> b)
{
	for(int i=0;i<b.size();i++) a.push_back(b[i]);
	return ;
}
vector<ll> pollar(ll n)
{
	vector<ll> v;
	if(isp(n)) v.push_back(n),n=1;
	if(n==1) return v;
	while(1)
	{
		po=ran()%n;ll t=rho(n);if(t==-1) continue;
		v=pollar(n/t);merge(v,pollar(t));break;
	}
	return v;
}
map<ll,ll> m,rev;
void solve(ll x)
{
	if(x==1) 
	{
		cnt1++;
		return ;
	}
		map<ll,ll> cast;
		vector<ll>t=pollar(x);
		for(int i=0;i<t.size();i++) cast[t[i]]++;
	ll rr=1;ll nr=1;
	for(map<ll,ll>::iterator it=cast.begin();it!=cast.end();it++)
	{
		if(it->first==1) continue;
		it->second%=3;
		if(it->second==0) continue;
		rr=rr*qpow(it->first,3-it->second,inf);
		nr=nr*qpow(it->first,it->second,inf);
	}
	if(nr==1)
	{
		cnt1++;
		return ;
	}
	m[nr]++;
	rev[nr]=rr;
}
int main()
{
	srand(time(0));
	int n;scanf("%d",&n);
	for(int i=1;i<=n;i++)
	{
		ll x;scanf("%lld",&x);
		solve(x);
	}
	ll ans=0;//cout<<"h";
	for(map<ll,ll>::iterator it=m.begin();it!=m.end();it++)
	{
		ll rr=rev[it->first];
		if(m.count(rr))
			ans+=max(it->second,m[rr]),it->second=m[rr]=0;
		else ans+=it->second,it->second=0;
	}
	cout<<ans+(cnt1>0);
	return 0;
}

