ll rev(ll a){
    ll yek=1;
    ll doo=1;
    for(auto v:t3){
        if(a%(v*v)==0){
            doo*=v;
            a/=(v*v);
        }
        if(a%v==0){
            yek*=v;
            a/=v;
        }
    }
    ll sq=sqrt(a);
    if(sq*sq==a){
        return sq*yek*yek*doo;
    }else{
