#include <bits/stdc++.h>
using namespace std;

using ll = long long;

int solve(vector<ll> values)
{
    auto S = *max_element(begin(values), end(values));
    auto small_primes = vector<ll>();
    auto small_prime_limit = static_cast<int>(cbrt(S)) + 1;
    auto large_prime_squares = unordered_map<ll, ll>();
    auto large_prime_limit = static_cast<int>(sqrt(S)) + 1;
    auto is_prime = vector<bool>(large_prime_limit+1, true);
    for (auto p = 2LL; p <= large_prime_limit; p++) if (is_prime[p])
    {
        if (p <= small_prime_limit) small_primes.push_back(p);
        else large_prime_squares[p*p] = p;
        for (auto k = 2*p; k <= large_prime_limit; k += p)
            is_prime[k] = false;
    }

    auto normalize = [&](ll x)
    {
        for (auto p : small_primes)
        {
            auto cube = p*p*p;
            while (x % cube == 0) x /= cube;
        }
        return x;
    };

    auto counts = unordered_map<ll, int>();
    for (auto x : values)
        counts[normalize(x)]++;

    auto dual = [&](ll x)
    {
        auto y = 1LL;
        for (auto p : small_primes)
        {
            if (x % (p*p) == 0) y *= p;
            else if (x % p == 0) y *= p*p;
            while (x % p == 0) x /= p;
        }
        if (large_prime_squares.count(x) == 1)
            y *= large_prime_squares[x];
        else y *= x*x;
        return y;
    };

    auto result = 0;
    for (auto kv : counts)
    {
        auto x = kv.first, y = dual(x);
        if (counts.count(y) == 0) result += counts[x];
        else if (x < y) result += max(counts[x], counts[y]);
    }
    if (counts[1]) result++;
    return result;
}

int main()
{
    int N; scanf("%d", &N);

    auto values = vector<ll>(N);
    for (auto& x : values) scanf("%lld", &x);

    printf("%d\n", solve(values));
}

