#include<bits/stdc++.h>
using namespace std;
typedef long long ll;
const ll U=1e10;
map<ll,int> cnt;
const int N=1e5+10;
int n,size,ans;ll q[N],inv[N];
int prime[N],num;
void init(){
	static bool isp[N];
	for (int i=2;i<N;i++)
	if (!isp[i]){
		prime[++num]=i;
		for (int j=i+i;j<N;j+=i) isp[j]=1;
	}
}
void insert(){
	ll x,v=1,I=1;
	scanf("%lld",&x);
	for (int i=1;i<=num&&(ll)prime[i]*prime[i]<=x;i++)
	if (x%prime[i]==0){
		int cnt=0,p=prime[i];
		while (x%p==0) cnt++,x/=p;
		cnt%=3;
		ll sqr=(ll)p*p;
		if (cnt==1){
			v*=p;
			if (I>U/sqr) I=U+1;else I*=sqr;
		}
		if (cnt==2){
			v*=sqr;
			if (I>U/p) I=U+1;else I*=p;
		}
	}
	if (x){
		v*=x;
		if (I>U/(x*x)) I=U+1;else I*=x*x;
	}
	cnt[q[++size]=v]++;
	inv[size]=I;
	//printf("%lld %lld\n",v,I);
}
int main()
{
	init();
	scanf("%d",&n);
	for (int i=1;i<=n;i++) insert();
	int ans=0;
	if (cnt[1]) ans++,cnt[1]=0;
	for (int i=1;i<=size;i++){
		ll v=q[i];
		ans+=max(cnt[v],cnt[inv[i]]);
		cnt[v]=cnt[inv[i]]=0;
	}
	printf("%d\n",ans);
	return 0;
}

