        ll x; cin>>x;
        if(x==1) cnt[1]++, rev[1]=1;
        else {
            ll val=1, rval=1;
            for(int i=2; 1LL*i*i*i<=x; i++) {
                if(x%i==0) {
                    int cnt=0;
                    while(x%i==0) x/=i, cnt++;
                    cnt%=3;
                    rep(j, cnt) val*=i;
                    rep(j, (3-cnt)%3) rval*=i;
                }
            }
            if(x>1) {
                if(sqrt(x)==trunc(sqrt(x))&&isprime[trunc(sqrt(x))]) rval*=trunc(sqrt(x));
                else rval*=x*x;
                val*=x;
            }
            cnt[val]++; rev[val]=rval;
        }
