ll a2[MAX];

map<ll, int> a1m;
map<ll, int> a2m;

bool ok(ll a, ll b) { return (a && b && (1e16)/a>b); }
int main() {
    int n; scanf("%d", &n);
    if (n > 50000) { printf("%d", 1/0); return 0; }
    F0R(i, n) {
        scanf("%I64d", &a[i]); a1[i] = 1; a2[i] = 1;
    }
    for (int i=2; i<MAX; i++) {
        if (!comp[i]) {
            for (int j=2*i; j<MAX; j+=i) { comp[j] = true; }
        }
    }
    F0R(j, n) {
        for (int i=2; cube(i)<=1e10; i++) {
            while (a[j]%cube(i) == 0) { a[j] /= cube(i); }
            if (a[j]%sq(i) == 0) {
                a1[j] *= (ok(a1[j], sq(i))?sq(i):0);
                a2[j] *= (ok(a2[j], i)?i:0);
                a[j] /= sq(i);
            }
            else if (a[j]%i == 0) {
                a1[j] *= (ok(a1[j], i)?i:0);
                a2[j] *= (ok(a2[j], sq(i))?sq(i):0);
