				}
				if(tmp==1){
					b*=fact[j];
					if(b>LINF){
						flag=false,i--,n--,ans++;
						break;
					}
				}
			}
		}
		if(flag){
			m[a[i]]=b;
		}
	}
	sort(a+1,a+n+1);
	for(int i=1,j=1;i<=n;i=j){
		for(;j<=n&&a[i]==a[j];j++);
		lint b=m[a[i]];
		if(a[i]==b){
			ans++;
		}else{
			lint* l=lower_bound(a+1,a+n+1,b);
			lint* r=lower_bound(a+1,a+n+1,b+1);
			if(l==r){
				ans+=j-i;
			}else if(a+i<l){
				ans+=max((int)(j-i),(int)(r-l));
			}
		}
	}
	printf("%d\n",ans);
	return 0;
}

