ll a[N],bs[N];
int is[M],pri[M];
int n,ans,tot,tp;
bool t1=false;

map <ll,int> mp;

inline ll pw3(ll x){return x*x*x;}

inline ll f(ll x){
	ll res(1ll);
	for(int i=1;i<=tp;++i){
		if(pri[i]>x)break;
		int t=0;
		while(x%pri[i]==0)
			x/=pri[i],++t;
		if(!t)continue;
		if(t==1)res*=pri[i]*pri[i];
		else res*=pri[i];
	}
	if(x==1)return res;
	ll sqr=sqrt(x);
	if(sqr*sqr==x)res*=sqr;
	else return -1;
}

int main(){
	read(n);
	for(int i=1;i<=n;++i)read(a[i]);
	for(int i=2;i<=2200;++i){
		if(!is[i])pri[++tp]=i;
		for(int j=1;j<=tp&&i*pri[j]<=2200;++j){
			is[i*pri[j]]=1;
			if(i%pri[j]==0)break;
		}
	}
	for(int i=1;i<=tp&&pw3(pri[i])<=MX;++i)
		bs[++tot]=pw3(pri[i]);
	for(int i=1;i<=n;++i){
		for(int j=1;j<=tot&&bs[j]<a[i];++j)
			while(a[i]%bs[j]==0)a[i]/=bs[j];
		if(a[i]==1)t1=true;
		else ++mp[a[i]];
	}
	sort(a+1,a+n+1);
	int i=1;
	while(a[i]==1&&i<=n)++i;
	for(;i<=n;++i){
		int las=i;
		while(a[i]==a[i+1])++i;
		ll tar=f(a[i]);
		if(tar==-1)ans+=i-las+1;
		else if(tar<a[i])continue;
		else ans+=max(i-las+1,mp[tar]);
	}
	printf("%d\n",ans+t1);
	return 0;
}

