typedef long long int lint;

map <lint, int> Map;

int main()
{
    int N;
    cin >> N;
    while (N --) {
        lint nr;
        cin >> nr;
        for (int i = 2200; i; -- i) {
            const lint cube = (1LL * i * i * i);
            if (nr % cube == 0) {
                nr /= cube;
                break;
            }
        }
        ++ Map[nr];
    }

    int ans = 0;
    for (const auto it: Map) {
        lint nr = it.first;
        lint minimum = 1E9 + 15;
        for (int i = 1; i <= 2200; ++ i) {
            const lint cube = (1LL * i * i * i);
            if (cube % nr == 0)
                minimum = min(minimum, cube / nr);
        }

        if (minimum == nr && Map[nr])
            ++ ans, Map[nr] = 0;
        else if (minimum < 1E9 + 10) {
            ans += max(Map[nr], Map[minimum]);
            Map[nr] = Map[minimum] = 0;
        }
        else
            ans += Map[nr];
    }

    cout << ans << '\n';
    return 0;
}

