#define REP(i,n) for(long (i)=0;(i)<(n);(i)++)
#define REPI(i,a,b) for(long (i)=(a);(i)<(b);(i)++)
#define INF numeric_limits<double>::infinity()
constexpr long MOD = 1e9 + 7;
using namespace std;
using P = pair<long, long>;
using VI = vector<long>;

VI primes = {2};
VI primesl = VI(100000, 1);
unordered_map<long, long> isps;

void addp() {
    for (long i = 3; i * i * i <= 1e10; i+=2) {
        bool fl = true;
        for (long p: primes) {
            if (i % p == 0) fl = false;
        }
        if (fl) primes.push_back(i);
    }
}

void addpl() {
    primesl[0] = 0;
    primesl[1] = 0;
    REPI(i,2,100000) {
        if (!primesl[i]) continue;
        for (long j = 2; i * j < 100000; j++) {
            primesl[i * j] = 0;
        }
    }

    REPI(i,2,100000) {
        if (primesl[i]) {
            isps[i * i] = true;
        }
    }
}

long red(long s) {
    for (long p: primes) {
        while (s % (p * p * p) == 0) {
            s /= p * p * p;
        }
    }
    return s;
}

long findp(long s) {
    for (long p: primes) {
        while (s % p == 0) {
            s /= p;
        }
    }
    return s;
}

long brv(long s) {
    long ans = 1;
    for (long p: primes) {
        if (s % (p * p) == 0) {
            ans *= p;
        } else if (s % p == 0) {
            if (double(ans) * p * p > 1e10) return -1;
            ans *= p * p;
        }
        if (ans > 1e10) return -1;
    }
    return ans;
}

long opp(long s) {
    long p = findp(s);
    long b = s / p;
    long br = brv(b);
    if (br == -1) return -1;

    if (p == 1) return br;
    if (isps[p]) {
        if (double(br) * sqrt(p) > 1e10) return -1;
        return br * long(sqrt(p));
    }
    if (double(br) * p * p > 1e10) return -1;
    if (isps[p * p]) {
        return br * p * p;
    }
    return -1;
}

unordered_map<long, long> m;

int main() {
    addp();
    addpl();
    bool hasOne = false;
    int n;
    cin >> n;
    REP(i,n) {
        long a;
        cin >> a;
        a = red(a);
        if (a == 1) hasOne = true;
        else m[a]++;
    }

    long ans = 0;
    for (auto i = m.begin(); i != m.end(); i++) {
        if (i->second == 0) continue;
        long op = opp(i->first);
        if (op == -1) {
            ans += i->second;
            m[i->first] = 0;
        } else {
            ans += max(i->second, m[op]);
            m[i->first] = 0;
            m[op] = 0;
        }
    }
    cout << ans + hasOne << endl;
}

