// sieve of Erastosthenes
bool arr[100001];
vector<long> pc;  //prime cubics
vector<long> primes;
void prime_list(int sz){
  fill(arr, arr+sz+1, true);
  arr[0]=arr[1]=false;
  for(int i=4;i<=sz;i+=2) arr[i]=false;
  primes.pb(2); pc.pb(8);
  for(long i=3; i<=sz/2; i+=2){
    if(arr[i]){
      if(i*i*i<1e+10) pc.pb(i*i*i);
      primes.pb(i);
      for(long j=i*i; j<=sz; j+=i) arr[j]=false;
    }
  }
}

int main(){
  prime_list(100000);
  int n;
  cin>>n;
  vector<long> vec(n);
  rep(i,n){
    scanf("%ld", &(vec[i]));
    for(long c : pc){
      while(vec[i]%c==0) vec[i]/=c;
    }
  }

  sort(all(vec));
  int res=0;

  map<map<long, int>, int> mp;
  rep(i, vec.size()){
    if(vec[i]==1){
      res=1;
      continue;
    }
    map<long, int> m; // vec[i]の因数分解
    for(long p : primes){
      while(vec[i]%p==0){
        m[p]++;
        vec[i]/=p;
      }
    }
    mp[m]++;
  }

  for(auto m : mp) if(m.se != 0){
    map<long, int> search;
    for(auto p : m.fi){ //1か2のはず
      if(p.se==2) search[p.fi]=1;
      else search[p.fi]=2;
    }
    auto f = mp.find(search);
    if(f!=mp.end()){
      res += max(m.se, f->se);
      f->se = 0;
    } else {
      res += m.se;
    }
  }

  cout << res << endl;

  return 0;
}

