void Init(){
	For(i,2,top+1){
		if (!v[i]) pri[++*pri]=i;
		for (int j=1;j<=*pri&&pri[j]*i<=top;j++){
			v[pri[j]*i]=1;
			if (i%pri[j]==0) break;
		}
	}
}
ll Mul(ll x,ll y){
	return 1.0*x*y<=oo?x*y:oo;
}
void gao(ll x){
	ll y,z;
	if (M.count(x)){
		y=M[x];
	} else{
		y=1;z=1;
		for (int i=1;i<=*pri&&1ll*pri[i]*pri[i]<=x;i++)
			if (x%pri[i]==0){
				int c=0;
				while (x%pri[i]==0) x/=pri[i],c++;
				c%=3;
				For(j,0,c) y*=pri[i];
				c=(3-c)%3;
				For(j,0,c) z=Mul(z,pri[i]);
			}
		if (x>1){
			if (x>top){
				y*=x;
				z=oo;
			} else{
				y*=x;
				z=Mul(z,x);
				z=Mul(z,x);
			}
		}
		M[x]=y;
		anti[y]=z;
		anti[z]=y;
	}
	num[y]++;
}

int main(){
	Init();
	n=IN();
	For(i,0,n) gao(IN());
	for (auto u:num){
		ll a=u.fi;
		if (!vis.count(a)){
			vis[a]=vis[anti[a]]=1;
			if (anti[a]==oo) res+=num[a];
			lf (anti[a]==a) res++;
			else res+=max(num[a],num[anti[a]]);
		}
	}
	printf("%d\n",res);
}

