template<class T>
T next(istream& in) {
    T ret;
    in >> ret;
    return ret;
}

template<class T>
vector<T> next_vector(istream& in, size_t n) {
    vector<T> ret(n);
    for (size_t i = 0; i < n; ++i) {
        ret[i] = next<T>(in);
    }
    return ret;
}


map<int64, int64> pair_num;
map<int64, int> dict;
vector<int> primes;

void add(int64& x, int64 what, int am) {
    if (am == 3 || am == 0) return;
    x *= what;
    if (am > 1) x *= what;
}

void factorize3(int64 x) {
    int64 number = 1, rev_number = 1;
    int cnt = 0;
    for (int p : primes) {
        if (p * 1L * p > x) {
            break;
        }
        if (x % p == 0) {
            while (x % p == 0) {
                ++cnt;
                if (cnt == 3) cnt = 0;
                x /= p;
            }
            add(number, p, cnt);
            add(rev_number, p, 3 - cnt);
        }
    }
//    while (x % 2 == 0) {
//        ++cnt;
//        if (cnt == 3) cnt = 0;
//        x /= 2;
//    }
//
//    add(number, 2, cnt);
//    add(rev_number, 2, 3 - cnt);
//    for (int64 i = 3; i * i <= x; i += 2) {
//        if (x % i == 0) {
//            cnt = 0;
//            while (x % i == 0) {
//                x /= i;
//                ++cnt;
//                if (cnt == 3) cnt = 0;
//            }
//            add(number, i, cnt);
//            add(rev_number, i, 3 - cnt);
//        }
//    }
    if (x != 1) {
        add(number, x, 1);
        add(rev_number, x, 2);
    }
    pair_num[number] = rev_number;
    pair_num[rev_number] = number;
    dict[number]++;
}

bool u[1000000];

void prepare() {
    primes.clear();
    memset(u, false, sizeof u);
    for (int i = 2; i < 1000000; ++i) {
        if (!u[i]) {
            primes.push_back(i);
            for (int j = i + i; j < 1000000; j += i) {
                u[j] = true;
            }
        }
    }
}

void solve(istream& in, ostream& out) {
    prepare();
    dict.clear();
    int n = next<int>(in);
    vector<int64> a = next_vector<int64>(in, n);
    for (int64 el : a) { factorize3(el); }
    int res = 0;
    for (auto v : dict) {
        if (v.first == 1) {
            ++res;
            continue;
        }
        int64 rev_v = pair_num[v.first];
        res += max(v.second, dict[rev_v]);
        dict.erase(rev_v);
    }
    out << res << endl;
}


