const ll MAX = 1e10;



ll nijo(ll x) {
    ll ng = 0;
    ll ok = 100000;
    while (ok-ng > 1) {
        ll mid = (ok+ng)/2;
        if (mid*mid >= x) ok = mid;
        else ng = mid;
    }
    if (ok*ok==x) return ok;
    return -1;
}

ll mul(ll x, ll y) {
    if (x==0 or y==0) return 0;
    if ((MAX+1)/y < x) return MAX+1;
    return x*y;
}


