bool is_cube(long long N){
  long long tv = 10000;
  long long fv = -1;
  while (tv - fv > 1){
    long long mid = (tv + fv) / 2;
    if (mid * mid * mid >= N){
      tv = mid;
    } else {
      fv = mid;
    }
  }
  return tv * tv * tv == N;
}
long long is_square(long long N){
  long long c = (long long) (sqrt(N) + 0.001);
  if (c * c == N){
    return c;
  } else if ((c + 1) * (c + 1) == N){
    return c + 1;
  } else if ((c - 1) * (c - 1) == N){
    return c - 1;
  } else {
    return -1;
  }
}
