vector<ll> generate_primes(ll N) {
    vector<int> is_prime(N, 1);
    vector<ll> primes;
    repeat(i, 2, N) {
        if(not is_prime[i]) continue;
        primes.push_back(i);
        for(ll j = i * 2; j < is_prime.size(); j += i) is_prime[j] = 0;        
    }
    return primes;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    auto primes = generate_primes(pow(1e10, 1.0/3.0)+10);
    set<ll> primes2;    
    for(ll p : generate_primes(sqrt(1e10) + 10)) primes2.insert(p*p);

    int N; cin >> N;
    vector<ll> S(N); cin >> S;

    map<ll, int> normalized_s;

    auto normalize = [&] (ll s) {
        for(ll p : primes) {
            ll ppp = p * p * p;
            while(s % ppp == 0) s /= ppp;            
            if(s == 1) break;
        }
        return s;
    };

    for(ll s : S) {
        normalized_s[normalize(s)]++;
    }

    int ans = 0;
    set<ll> used;
    for(auto s_ : normalized_s) {
        ll s = s_.first;
        if(used.count(s)) continue;

        ll t = normalize(s * s);
        used.insert(s);
        used.insert(t);

        int s_cnt = s_.second;
        int t_cnt = normalized_s.count(t) ? normalized_s[t] : 0;

        ans += s == t ? 1 : max(s_cnt, t_cnt);
    }
    cout << ans << endl;

    return 0;
}

