map <ll,ll> s,vis,sqr;

void init(){
    check[1]=1;
    sqr[1]=1;
    for(int i=2;i<=100000;i++){
        if(!check[i]) prime[++tot]=i,sqr[1ll*i*i]=i;
        for(int j=1;j<=tot&&prime[j]*i<=100000;j++){
            check[prime[j]*i]=1;
            if(i%prime[j]==0) break;
        }
    }
