LL n,x[N],ans;
LL p[N],tot,vis[N*10];
map<LL,P> mp;
void init()
{
	for(int i=2;i<=N;i++)
	{
		if(!vis[i]) p[++tot]=i;
		for(int j=1;j<=tot;j++)
		{
			vis[i*p[j]]=1;
			if(i%p[j]==0||i*p[j]>=N) break;
		}
	}
}
LL solve(LL now)
{
	LL pei=1,xin=1;
	for(int i=1;i<=400;i++)
	{
		if(now%p[i]!=0) continue;
		int flag=0;
		while(now%p[i]==0)
			flag++,now/=p[i];
		flag%=3;
		xin*=pow(p[i],flag);
		pei*=pow(p[i],(3-flag)%3);
	}
	if(now>=2700)
	{
		LL tmp = sqrt(now);
		if(tmp * tmp ==now) pei*=tmp;
		else pei=inf;
		xin*=now;
	}
	mp[xin].first++,mp[xin].second=pei;
}
