long long pl[100005],dpl[100005],trpl[100005],ls=0;
void makepl(){
  bool fl[2222]={0};
  long long i,j;
  for(i=2;i<2222;i++){
    if(fl[i]){continue;}
    pl[ls]=i;
    dpl[ls]=i*i;
    trpl[ls]=i*i*i;
    ls++;
    for(j=2*i;j<2222;j+=i){
      fl[j]=1;
    }
  }
  return;
}

long long llsqr(long long x){
  long long st=1,fi=1000000000,te;
  while(st<=fi){
    te=(st+fi)/2;
    if(te*te<x){st=te+1;}
    else{fi=te-1;}
  }
  return st;
}

