  scanf("%lld",&n);
  for(i=0;i<n;i++){
    scanf("%lld",&t);
    w=t;
    for(j=0;j<ls;j++){
      while(t%pl[j]==0){t/=pl[j];}
      while(w%trpl[j]==0){w/=trpl[j];}
    }
    if(t>100000){
      l=llsqr(t);
      if(l*l!=t){r++;continue;}
    }
    a[c]=w;
    c++;
  }
  if(c==0){
    printf("%lld\n",r);
    return 0;
  }
