    if(a[i-1]!=a[i]){
      dat[t].node=w;
      t++;
      w=1;
      dat[t].val=a[i];
    }
    else{w++;}
  }
  dat[t].node=w;
  t++;
  dat[t].val=llinf;
  for(i=0;i<t;i++){
    if(tfl[i]){continue;}
