    w=1;
    h=dat[i].val;
    for(j=0;j<ls;j++){
      while(h%pl[j]==0){h/=pl[j];}
      if(dat[i].val%pl[j]==0){
        if(dat[i].val%dpl[j]==0){
          w*=pl[j];
          if(w>10000000000){w=-1;break;}
        }
        else{
          w*=pl[j];
          if(w>10000000000){w=-1;break;}
          w*=pl[j];
          if(w>10000000000){w=-1;break;}
        }
      }
    }
    if(w==-1){r+=dat[i].node;continue;}
    if(h>100000){
      l=llsqr(h);
      w*=l;
      if(w>10000000000){w=-1;}
    }
    else{
      w*=h;
      if(w>10000000000){w=-1;}
      w*=h;
      if(w>10000000000){w=-1;}
    }
    if(w==-1){r+=dat[i].node;continue;}
    st=0;fi=t-1;
    while(st<=fi){
      te=(st+fi)/2;
      if(dat[te].val<w){st=te+1;}
      else{fi=te-1;}
    }
    if(dat[st].val!=w){r+=dat[i].node;continue;}
