fun killCube(s : Long) : Num {
    var q = s
    var r1 = 1L
    var r2 = 1L
    for (i in 2L..s) {
        val sq = i * i
        val c = sq * i
        if (c > q) break
        while (q % c == 0L) q /= c
        if (q % sq == 0L) {
            q /= sq
            r2 *= i
        } else if (q % i == 0L) {
            q /= i
            r1 *= i
        }
    }
    val sqrt = sqrt(q)
    if (sqrt == null) r1 *= q else r2 *= sqrt
    return Num(r1 * r2 * r2, r1, r2)
}

