    public static class Task implements Runnable {
        final FastIO io;
        final Debug debug;
        int inf = (int) 1e8;
        long lInf = (long) 1e18;
        double dInf = 1e50;

        public Task(FastIO io, Debug debug) {
            this.io = io;
            this.debug = debug;
        }

        @Override
        public void run() {
            solve();
        }

        public void solve() {
            int n = io.readInt();
            long[] s = new long[n];
            for (int i = 0; i < n; i++) {
                s[i] = io.readLong();
            }

            long limit = (long) 1e10;
            Map<Long, Integer> cntMap = new HashMap<>(n);
            Map<Long, Long> oppositeMap = new HashMap<>(n);
            NumberTheory.EulerSieve es = new NumberTheory.EulerSieve(100000);
            Map<Long, Integer> p2 = new HashMap<>(100000);
            for (int i = 0; i < es.primeLength; i++) {
                int p = es.primes[i];
                p2.put((long) p * p, p);
            }

            for (int i = 0; i < n; i++) {
                long v = s[i];
                long factor = 1;
                long opposite = 1;
                for (int j = 0; ; j++) {
                    long p = es.primes[j];
                    long p3 = p * p * p;
                    if (p3 > v) {
                        break;
                    }
                    int factorCnt = 0;
                    while (v % p3 == 0) {
                        v /= p3;
                    }
                    while (v % p == 0) {
                        v /= p;
                        factorCnt++;
                    }
                    for (int k = 0; k < factorCnt; k++) {
                        factor *= p;
                    }
                    for (int k = 0; k < (3 - factorCnt) % 3; k++) {
                        opposite = mul(opposite, p);
                    }
                }

                factor *= v;

                //p^2
                if (p2.containsKey(v)) {
                    opposite *= p2.get(v);
                } else {
                    opposite = mul(opposite, v);
                    opposite = mul(opposite, v);
                }
                oppositeMap.put(factor, opposite);
                cntMap.put(factor, cntMap.getOrDefault(factor, 0) + 1);
            }

            int ans = 0;
            for (Map.Entry<Long, Long> entry : oppositeMap.entrySet()) {
                if (entry.getKey() > entry.getValue()) {
                    continue;
                }
                if (entry.getKey().equals(entry.getValue())) {
                    ans++;
                } else {
                    ans += Math.max(cntMap.get(entry.getKey()), cntMap.getOrDefault(entry.getValue(), 0));
                }
            }

            io.cache.append(ans);
        }

        public long mul(long a, long b) {
            if (a > 1e11 / b) {
                return lInf;
            }
            return a * b;
        }
    }

    public static class NumberTheory {
        private static final Random RANDOM = new Random();

        public static class ExtLucasFactorial {
            int exp;
            int fact;
            int p;
            int pc;
            Modular modular;
            Power power;
            ExtGCD extGCD = new ExtGCD();
            int[] g;

            /**
             * O(pc)
             *
             * @param p  the prime
             * @param pc p^c
             * @param g  buffer
             */
            public ExtLucasFactorial(int p, int pc, int[] g) {
                this.p = p;
                this.pc = pc;
                this.g = g;
                modular = new Modular(pc);
                power = new Power(modular);
                g[0] = 1;
                g[1] = 1;
                for (int i = 2; i <= pc; i++) {
                    if (i % p == 0) {
                        g[i] = g[i - 1];
                    } else {
                        g[i] = modular.mul(g[i - 1], i);
                    }
                }
            }

            /**
             * return m! (mod pc) without any factor which is multiple of p.
             * <br>
             * O(\log_2^2{m})
             */
            private int fact(long m) {
                fact = 1;
                exp = 0;
                while (m > 1) {
                    exp += m / p;
                    fact = modular.mul(fact, power.pow(g[pc], m / pc));
                    fact = modular.mul(fact, g[(int) (m % pc)]);
                    m /= p;
                }
                return fact;
            }

            /**
             * Find C(m,n), it means choose n elements from a set whose size is m.
             * <br>
             * O(\log_2^2{m})
             */
            public int composite(long m, long n) {
                int v = fact(m);
                int e = exp;
                extGCD.extgcd(fact(n), pc);
                v = modular.mul(v, modular.valueOf(extGCD.getX()));
                e -= exp;
                extGCD.extgcd(fact(m - n), pc);
                v = modular.mul(v, modular.valueOf(extGCD.getX()));
                e -= exp;
                v = modular.mul(v, power.pow(p, e));
                return v;
            }
        }

        /**
         * Extend lucas algorithm
         */
        public static class ExtLucas {
            PollardRho pr = new PollardRho();
            Map<Integer, ExtLucasFactorial> factorialMap = new HashMap();

            public ExtLucas(int p) {
                Map<Integer, Integer> factors = pr.findAllFactors(p);
                for (Map.Entry<Integer, Integer> entry : factors.entrySet()) {
                    factorialMap.put(entry.getValue(), new ExtLucasFactorial(entry.getKey(), entry.getValue(), new int[entry.getValue() + 1]));
                }
            }

            /**
             * Get C(m, n) % p
             */
            public int composite(long m, long n) {
                ExtCRT extCRT = new ExtCRT();
                for (Map.Entry<Integer, ExtLucasFactorial> entry : factorialMap.entrySet()) {
                    extCRT.add(entry.getValue().composite(m, n), entry.getKey());
                }
                return (int) extCRT.r;
            }
        }

