         */
        public static class LongMillerRabin {
            LongModular modular;
            LongPower power;

            /**
             * Check whether n is a prime s times
             */
            public boolean mr(long n, int s) {
                if (n == 2) {
                    return true;
                }
                if (n % 2 == 0) {
