public class Main {

    static boolean prime[];

    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter w = new PrintWriter(System.out);

        int n = in.nextInt();

        long a[] = new long[n];
        for (int i = 0; i < n; i++)
            a[i] = in.nextLong();

        sieve(100100);
        int q[] = new int[100100];
        long p[] = new long[100100];
        long r[] = new long[100100];
        int ptr = 0;
        for (int i = 2; i < prime.length; i++) {
            if (prime[i]) {
                q[ptr] = i;
                r[ptr] = i * 1L * i;
                p[ptr++] = i * 1L * i * 1L * i;
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; p[j] <= a[i]; j++) {
                while (a[i] % p[j] == 0)
                    a[i] /= p[j];
            }
        }

        //now we have cube free numbers
        TreeMap<Pair, Integer> map = new TreeMap<Pair, Integer>();

        for (int i = 0; i < n; i++) {
            long A = 1, B = 1;
            //System.out.println(a[i]);
            for (int j = 0; r[j] <= a[i]; j++) {
                if (a[i] % q[j] == 0) {
                    if (a[i] % r[j] == 0) {
                        B *= q[j];
                        a[i] /= r[j];
                    }
                    else {
                        A *= q[j];
                        a[i] /= q[j];
                    }
                }
            }
            if (a[i] != 1)
                A *= a[i];
            //System.out.println(A + " " + B);
            Pair P = new Pair(A, B);
            if (!map.containsKey(P))
                map.put(P, 0);
            map.put(P, map.get(P) + 1);
        }

        int ans = 0;
        for (Pair P : map.keySet()) {
            Pair O = new Pair(P.y, P.x);
            if (P.x == 1 && P.y == 1) {
                ans += Math.min(1, map.get(P));
            }
            else if (!map.containsKey(O) || P.x > P.y) {
                int pp = map.get(P);
                int qq = map.containsKey(O) ? map.get(O) : 0; 
                ans += Math.max(pp, qq);
            }
        }

        w.println(ans);
        w.close();
    }

    public static void sieve(int n) {
        prime = new boolean[n + 1];
        Arrays.fill(prime, true);
        prime[0] = prime[1] = false;

        for (int i = 2; i * i <= n; i++)
            if (prime[i])
                for (int k = i * i; k <= n; k += i)
                    prime[k] = false;
    }

    static class Pair implements Comparable<Pair> {
        long x, y;

        Pair(long x, long y) {
            this.x = x;
            this.y = y;
        }

        public int compareTo(Pair o) {
            if (x != o.x)
                return Long.compare(x, o.x);
            return Long.compare(y, o.y);
        }

        public String toString() {
            return x + " " + y;
        }
    }

    static class InputReader {

        private final InputStream stream;
        private final byte[] buf = new byte[8192];
        private int curChar, snumChars;
        private SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int snext() {
            if (snumChars == -1)
                throw new InputMismatchException();
            if (curChar >= snumChars) {
                curChar = 0;
                try {
                    snumChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (snumChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = snext();
            while (isSpaceChar(c)) {
                c = snext();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = snext();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = snext();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public long nextLong() {
            int c = snext();
            while (isSpaceChar(c)) {
                c = snext();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = snext();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = snext();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public int[] nextIntArray(int n) {
            int a[] = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = nextInt();
            }
            return a;
        }

        public String readString() {
            int c = snext();
            while (isSpaceChar(c)) {
                c = snext();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = snext();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public String nextLine() {
            int c = snext();
            while (isSpaceChar(c))
                c = snext();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = snext();
            } while (!isEndOfLine(c));
            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            if (filter != null)
                return filter.isSpaceChar(c);
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private boolean isEndOfLine(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Created by Katushka on 11.03.2020.
 */
public class Main {

    static int[] readArray(int size, InputReader in) {
        int[] a = new int[size];
        for (int i = 0; i < size; i++) {
            a[i] = in.nextInt();
        }
        return a;
    }

    static long[] readLongArray(int size, InputReader in) {
        long[] a = new long[size];
        for (int i = 0; i < size; i++) {
            a[i] = in.nextLong();
        }
        return a;
    }

    private static long fastPow(long x, long y, long mod) {
        if (x == 1) {
            return 1;
        }
        if (y == 0) {
            return 1;
        }
        long p = fastPow(x, y / 2, mod) % mod;
        p = p * p % mod;
        if (y % 2 == 1) {
            p = p * x % mod;
        }
        return p;
    }


    static int[] sieveOfEuler(int size, List<Integer> primes) {
        int[] lp = new int[size];

        lp[1] = 1;

        for (int j = 2; j < lp.length; ++j) {
            if (lp[j] == 0) {
                lp[j] = j;
                primes.add(j);
            }
            for (Integer p : primes) {
                if (p > lp[j] || p * j >= size) {
                    break;
                }
                lp[p * j] = p;
            }
        }
        return lp;
    }

    public static void main(String[] args) throws FileNotFoundException {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        int n = in.nextInt();
        long[] s = readLongArray(n, in);
        long max = 0;
        for (long l : s) {
            max = Math.max(l, max);
        }

        Set<Long> cubes = new HashSet<>();
        for (long i = 1; i * i * i <= max; i++) {
            cubes.add(i * i * i);
        }
        Map<Long, Long> nonCube2cnt = new HashMap<>();
        Map<Long, Long> pairs = new HashMap<>();

        int cubesCnt = 0;
        long ans = 0;
        outer:
        for (int i = 0; i < n; i++) {
            long ss = s[i];
            long d = 2;
            long nonCube = 1;
            long peer = 1;
            while (d * d <= ss) {
                int cnt = 0;
                while (ss % d == 0) {
                    ss /= d;
                    cnt += 1;
                }
                cnt %= 3;
                if (cnt == 1) {
                    nonCube *= d;
                    peer *= d * d;
                } else if (cnt == 2) {
                    nonCube *= d * d;
                    peer *= d;
                }
                if (peer > max) {
                    ans += 1;
                    continue outer;
                }
                d += 1;
            }

            if (ss > 1) {
                if (ss > 1000000) {
                    ans += 1;
                    continue;
                }
                nonCube *= ss;
                peer *= ss * ss;

                if (peer > max) {
                    ans += 1;
                    continue;
                }
            }

            if (nonCube == 1) {
                cubesCnt++;
            } else {
                nonCube2cnt.put(nonCube, nonCube2cnt.getOrDefault(nonCube, 0L) + 1);
                pairs.put(nonCube, peer);
                pairs.put(peer, nonCube);
            }
        }

        ans += cubesCnt > 0 ? 1 : 0;
        for (Long aLong : nonCube2cnt.keySet()) {
            if (pairs.containsKey(aLong)) {
                long cnt1 = nonCube2cnt.get(aLong);
                Long peer = pairs.get(aLong);
                long cnt2 = nonCube2cnt.getOrDefault(peer, 0L);
                if (Math.max(cnt1, cnt2) > 1) {
                    ans += Math.max(cnt1, cnt2);
                } else {
                    ans += 1;
                }
                pairs.remove(aLong);
                pairs.remove(peer);
            }
        }
        out.println(ans);


        out.close();
    }


    private static void outputArray(long[] ans, PrintWriter out) {
        StringBuilder str = new StringBuilder();
        for (long an : ans) {
            str.append(an).append(' ');
        }
        out.println(str);
    }

    private static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                createTokenizer();
            }
            return tokenizer.nextToken();
        }

        private void createTokenizer() {
            try {
                tokenizer = new StringTokenizer(reader.readLine());
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        public String nextWord() {
            return next();
        }

        public String nextString() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public char nextChar() {
            return next().charAt(0);
        }

        public int[] nextInts() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                createTokenizer();
            }
            List<Integer> res = new ArrayList<>();
            while (tokenizer.hasMoreElements()) {
                res.add(Integer.parseInt(tokenizer.nextToken()));
            }
            int[] resArray = new int[res.size()];
            for (int i = 0; i < res.size(); i++) {
                resArray[i] = res.get(i);
            }
            return resArray;
        }
    }
}

import java.io.IOException;
