import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.math.BigInteger;
import java.util.*;

/**
 * Created by hama_du on 2016/08/21.
 */
public class Main {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);


        //debug(generatePrimes(1000000)[500]);

        int n = in.nextInt();
        long[] s = in.nextLongs(n);

        int[] p = generatePrimes(100010);

        Map<Long,Integer> deg = new HashMap<>();
        Map<Long,Long> amap = new HashMap<>();
        boolean one = false;

        for (int si = 0 ; si < n ; si++) {
            long S = s[si];
            if (S == 1) {
                one = true;
                continue;
            }
            long kay = 1;
            long anti = 1;
            for (int pi = 0 ; pi < 380 ; pi++) {
                int P = p[pi];
                if (S < P) {
                    break;
                }
                int cnt = 0;
                while (S % P == 0) {
                    S /= P;
                    cnt++;
                }
                cnt %= 3;
                if (cnt >= 1) {
                    kay *= Math.pow(P, cnt);
                    if (anti >= 1) {
                        anti *= Math.pow(P, 3-cnt);
                    }
                    if (anti > 1e11) {
                        anti = -1;
                    }
                }
            }
            if (S >= 2) {
                // S will be p0p1 or p0^2(p0 and p1 are some large primes)
                kay *= S;
                long ss = (long)Math.sqrt(S);
                if (ss * ss == S) {
                    if (anti >= 1) {
                        BigInteger anbig = BigInteger.valueOf(anti);
                        anbig = anbig.multiply(BigInteger.valueOf(ss));
                        if (anbig.compareTo(BigInteger.valueOf((long) 1e11)) < 0) {
                            anti = anbig.longValue();
                        } else {
                            anti = -1;
                        }
                    }
                } else {
                    if (anti >= 1) {
                        BigInteger anbig = BigInteger.valueOf(anti);
                        anbig = anbig.multiply(BigInteger.valueOf(S));
                        anbig = anbig.multiply(BigInteger.valueOf(S));
                        if (anbig.compareTo(BigInteger.valueOf((long) 1e11)) < 0) {
                            anti = anbig.longValue();
                        } else {
                            anti = -1;
                        }
                    }
                }
            }
            if (kay == 1) {
                one = true;
                continue;
            }
            deg.put(kay, deg.getOrDefault(kay, 0)+1);
            amap.put(kay, anti);
            amap.put(anti, kay);
        }

        int total = 0;
        Set<Long> done = new HashSet<>();
        for (long A : deg.keySet()) {
            if (A == -1 || done.contains(A)) {
                continue;
            }
            long B = amap.get(A);
            done.add(B);
            total += Math.max(deg.getOrDefault(A, 0), deg.getOrDefault(B, 0));
        }
        if (one) {
            total++;
        }
        out.println(total);
        out.flush();
    }

    static int[] generatePrimes(int upto) {
        boolean[] isp = new boolean[upto];
        Arrays.fill(isp, true);
        isp[0] = isp[1] = false;

        int pi = 0;
        for (int i = 2; i < upto ; i++) {
            if (isp[i]) {
                pi++;
                for (int j = i * 2; j < upto; j += i) {
                    isp[j] = false;
                }
            }
        }

        int[] ret = new int[pi];
        int ri = 0;
        for (int i = 2 ; i < upto ; i++) {
            if (isp[i]) {
                ret[ri++] = i;
            }
        }
        return ret;
    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int[] nextInts(int n) {
            int[] ret = new int[n];
            for (int i = 0; i < n; i++) {
                ret[i] = nextInt();
            }
            return ret;
        }


        private int[][] nextIntTable(int n, int m) {
            int[][] ret = new int[n][m];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    ret[i][j] = nextInt();
                }
            }
            return ret;
        }

        private long[] nextLongs(int n) {
            long[] ret = new long[n];
            for (int i = 0; i < n; i++) {
                ret[i] = nextLong();
            }
            return ret;
        }

        private long[][] nextLongTable(int n, int m) {
            long[][] ret = new long[n][m];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    ret[i][j] = nextLong();
                }
            }
            return ret;
        }

        private double[] nextDoubles(int n) {
            double[] ret = new double[n];
            for (int i = 0; i < n; i++) {
                ret[i] = nextDouble();
            }
            return ret;
        }

        private int next() {
            if (numChars == -1)
                throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public char nextChar() {
            int c = next();
            while (isSpaceChar(c))
                c = next();
            if ('a' <= c && c <= 'z') {
                return (char) c;
            }
            if ('A' <= c && c <= 'Z') {
                return (char) c;
            }
            throw new InputMismatchException();
        }

        public String nextToken() {
            int c = next();
            while (isSpaceChar(c))
                c = next();
            StringBuilder res = new StringBuilder();
            do {
                res.append((char) c);
                c = next();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public int nextInt() {
            int c = next();
            while (isSpaceChar(c))
                c = next();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = next();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c-'0';
                c = next();
            } while (!isSpaceChar(c));
            return res*sgn;
        }

        public long nextLong() {
            int c = next();
            while (isSpaceChar(c))
                c = next();
            long sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = next();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c-'0';
                c = next();
            } while (!isSpaceChar(c));
            return res*sgn;
        }

        public double nextDouble() {
            return Double.valueOf(nextToken());
        }

        public boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);
        }
    }

    static void debug(Object... o) {
        System.err.println(Arrays.deepToString(o));
    }
}

import java.io.*;
import java.util.*;

public class Main {

    static boolean prime[];

    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter w = new PrintWriter(System.out);

        int n = in.nextInt();

        long a[] = new long[n];
        for (int i = 0; i < n; i++)
            a[i] = in.nextLong();

        int N = 100100;
        sieve(N);
        int q[] = new int[N + 1];
        long p[] = new long[N + 1];
        long r[] = new long[N + 1];
        int ptr = 0;
        for (int i = 2; i <= N; i++) {
            if (prime[i]) {
                q[ptr] = i;
                r[ptr] = i * 1L * i;
                p[ptr++] = i * 1L * i * 1L * i;
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; p[j] <= a[i]; j++) {
                while (a[i] % p[j] == 0)
                    a[i] /= p[j];
            }
        }

        // now we have cube free numbers
        TreeMap<Pair, Integer> map = new TreeMap<Pair, Integer>();
        HashMap<Long, Long> AA = new HashMap<Long, Long>();
        HashMap<Long, Long> BB = new HashMap<Long, Long>();

        for (int i = 0; i < n; i++) {
            long A = 1, B = 1;

            if (AA.containsKey(a[i])) {
                A = AA.get(a[i]);
                B = BB.get(a[i]);
            } 

            else {
                long sav = a[i];
                for (int j = 0; r[j] <= a[i]; j++) {
                    if (a[i] % r[j] == 0) {
                        a[i] /= r[j];
                        B *= q[j];
                    }
                }
                //System.out.println(sav + " " + B + " " + a[i]);
                A = a[i];
                AA.put(sav, A);
                BB.put(sav, B);
            }

            Pair P = new Pair(A, B);
            if (!map.containsKey(P))
                map.put(P, 0);
            map.put(P, map.get(P) + 1);
        }

        int ans = 0;

        for (Pair P : map.keySet()) {

            Pair O = new Pair(P.y, P.x);
            if (P.x == 1 && P.y == 1) {
                ans += Math.min(1, map.get(P));
            } 

            else if (!map.containsKey(O) || P.x > P.y) {
                int pp = map.get(P);
                int qq = map.containsKey(O) ? map.get(O) : 0;
                ans += Math.max(pp, qq);
            }
        }

        w.println(ans);
        w.close();
    }

    public static void sieve(int n) {
        prime = new boolean[n + 1];
        Arrays.fill(prime, true);
        prime[0] = prime[1] = false;

        for (int i = 2; i * i <= n; i++)
            if (prime[i])
                for (int k = i * i; k <= n; k += i)
                    prime[k] = false;
    }

    static class Pair implements Comparable<Pair> {
        long x, y;

        Pair(long x, long y) {
            this.x = x;
            this.y = y;
        }

        public int compareTo(Pair o) {
            if (x != o.x)
                return Long.compare(x, o.x);
            return Long.compare(y, o.y);
        }

        public String toString() {
            return x + " " + y;
        }
    }

    static class InputReader {

        private final InputStream stream;
        private final byte[] buf = new byte[8192];
        private int curChar, snumChars;
        private SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int snext() {
            if (snumChars == -1)
                throw new InputMismatchException();
            if (curChar >= snumChars) {
                curChar = 0;
                try {
                    snumChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (snumChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = snext();
            while (isSpaceChar(c)) {
                c = snext();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = snext();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = snext();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public long nextLong() {
            int c = snext();
            while (isSpaceChar(c)) {
                c = snext();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = snext();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = snext();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public int[] nextIntArray(int n) {
            int a[] = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = nextInt();
            }
            return a;
        }

        public String readString() {
            int c = snext();
            while (isSpaceChar(c)) {
                c = snext();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = snext();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public String nextLine() {
            int c = snext();
            while (isSpaceChar(c))
                c = snext();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = snext();
            } while (!isEndOfLine(c));
            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            if (filter != null)
                return filter.isSpaceChar(c);
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private boolean isEndOfLine(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);
        }
    }
}

