			for(int k: entry.getKey())list.add(k>primes.size() ? k/(primes.size()+1): k*(primes.size()+1));
			ans2 += Math.max(entry.getValue(), cnt.getOrDefault(list, 0));
			used.add(list);
		}
		out.println(ans+ans2);
	}




