			}
		}

		int[] res = new int[cnt];
		for(int i = 2, j = 0; i <= n; i++) {
			if(p[i]) {
				res[j++] = i;
			}
		}

		return res;
	}

	private static boolean[] eratosthenes(int n) {
		final boolean[] p = new boolean[n + 1];
		Arrays.fill(p, true);
		p[0] = p[1] = false;
		for(int i = 2; i*i <= n; i++) {
			if(p[i]) {
				for(int j = i*i; j <= n; j += i) {
					p[j] = false;
				}
			}
		}
		return p;
	}

