        boolean[] sieve = new boolean[mx];
        int[] list = new int[mx];
        long[] sqpr = new long[mx];
        int c = 0;
        Arrays.fill(sieve, true);
        sieve[0] = sieve[1] = false;
        sqpr[1] = 1;
        for(int p = 2; p < mx; p++) {
            sqpr[p] = p*(long)p;
            if (sieve[p]) {
                if (p < 2200) list[c++] = p;
                for (int q = p + p; q < mx; q += p)
                    sieve[q] = false;
            }
        }
        list = Arrays.copyOf(list, c);
        long[] A = new long[N];
        long MAX = (long)1e10+2;

        TreeMap<Long, Integer> mp = new TreeMap<>();
        TreeMap<Long, Long> con = new TreeMap<>();
        for(int i = 0; i< N; i++){
            A[i] = nl();
            long x = A[i];
            long norm = 1, conj = 1;
            for(int p:list){
                int cnt = 0;
                while(x%p == 0){x /= p;cnt++;}
                cnt %= 3;
                if(cnt == 0)continue;
                if(cnt == 1){
                    norm *= p;
                    conj = mul(conj, p, MAX);
                    conj = mul(conj, p, MAX);
                }else if(cnt == 2){
                    norm *= p*p;
                    conj = mul(conj, p, MAX);
                }
            }
            if(x > 1){
                int ind = Arrays.binarySearch(sqpr, x);
                if(ind == -1{
                    norm *= x;
                    conj = mul(conj, x, MAX);
                    conj = mul(conj, x, MAX);
                }else{
                    norm *= x;
                    conj = mul(conj, ind, MAX);
                }
            }
            mp.put(norm, mp.getOrDefault(norm, 0)+1);
            con.put(norm, conj);
        }
        int ans = 0;
        for(Map.Entry<Long, Integer> e:mp.entrySet()){
            long norm = e.getKey();
            long conj = con.get(norm);
            int c1 = mp.getOrDefault(norm, 0), c2 = mp.getOrDefault(conj, 0);
            if(norm == conj){
                ans++;
            }else if(norm < conj)ans += Math.max(c1, c2);
        }
        pn(ans);
    }
