		}
		long x = pow_mod(a, d, N);
		if (x == 1) return false;
		while (R-->0) {
			if (x == N - 1) return false;
			x = mod_mul(x, x, N);
		}
		return true;
	}

	boolean isProbablePrime(long N) {
		if (N < MAX_N) return isPrime[(int)N];
		for (int i = 0; i < 5; i++) {
			long a = (long) (Math.random() * (N - 1) + 1);
			if (isProbableComposite(a, N))
				return false;
		}
		return true;
	}

	// a * b % m;
	long mod_mul(long a, long b, long m) {
		long res = 0;
		while (b > 0) {
			if ((b & 1) == 1) {
				res += a;
				if (res < 0 || m <= res) {
					res = res - m;
				}
			}
			b >>= 1;
			a <<= 1;
			if (a < 0 || m <= a) {
				a = a - m;
			}
		}
		return res;
	}

	long pow_mod(long a, long b, long p) {
		long res = 1;
		while (b > 0) {
			if ((b & 1) == 1) res = mod_mul(res, a, p);
			a = mod_mul(a, a, p);
			b >>= 1;
		}
		return res;
	}

	/**
	 * nの因数をひとつ求める．n が素数のときは無限ループするので事前に素数判定をしてから使う
	 * @param n
	 * @return
	 */
	long pollardRho(long n) {
		LOOP:
		for (int c = 1; ; ) {
			if (c >= 5)
				return n;

			long x = 1, y = 0, p = 1;
			long two = 1;

			for (int i = 1; p == 1; i++) {
				if (i == two) {
					y = x;
					two <<= 1;
				}
				x = mod_mul(x, x, n) + c;
				if (x >= n) x -= n;

				if (x == y) {
					c++;
					continue LOOP;
				}
				p = gcd(Math.abs(x - y), n);
			}
			return p;
		}
	}


	long[] factorize(long n) {
		if (isProbablePrime(n)) {
			return new long[] { n };
		}

		long[] res = new long[80];
		int len = 0;

		final int NAIVE_BOUND = 1 << 3;
		for (int i = 0; primes[i] < NAIVE_BOUND && primes[i] * primes[i] <= n; i++) {
			final long p = primes[i];
			while (n % p == 0) {
				n /= p;
				res[len++] = p;
			}
		}

		if (n != 1) {
			if (isProbablePrime(n)) {
				res[len++] = n;
			} else {
				long p = pollardRho(n);
				if (p == n) {
					res[len++] = n;
				} else {
					for (long fi : factorize(p))
						res[len++] = fi;
					for (long fi : factorize(n / p))
						res[len++] = fi;
				}
			}
		}

		res = Arrays.copyOf(res, len);
		Arrays.sort(res);
		return res;

	}
