class Main{ 

	static void solve(){
		int n = ni();
		long[] s = nla(n);
		boolean[] isPrime = new boolean[100001];
		Arrays.fill(isPrime, true);
		for(int i=2;i<=100000;++i){
			if(!isPrime[i])continue;
			for(int j=i*2;j<=100000;j+=i)isPrime[j]=false;
		}
		List<Integer> primes = new ArrayList<>();
		for(int i=2;i<=100000;++i)if(isPrime[i])primes.add(i);
		Set<Long> under1e5 = new HashSet<>();
		for(int p: primes)under1e5.add((long)p);
		under1e5.add(1L);
		List<Long> cubep = new ArrayList<>();
		for(int p : primes){
			if((long)p*p*p>(long)1e10)break;
			cubep.add((long)p);
		}

		Map<Long, Long> reve = new HashMap<>();
		Map<Long , Integer> cnt = new HashMap<>();
		int ans = 0;
		boolean zero=true;
		for(int i=0;i<n;++i){
			long ss = s[i];
			long rev = 1;
			for(int k=0;k<cubep.size();++k){
				long p= cubep.get(k);
				while(s[i]%(p*p*p)==0)s[i]/=(p*p*p);
				if(s[i]%p==0){
					if(s[i]%(p*p)==0)rev*=p;
					else rev*=p*p;
				}
				while(s[i]%p==0)s[i]/=p;
			}
			if(!under1e5.contains(s[i])){
				++ans;continue;
			}
			if((long)(Math.sqrt(s[i]))*(long)(Math.sqrt(s[i]))==s[i])rev*=s[i];
			else rev*=(s[i]*s[i]);
//			out.println(s[i]+" "+rev);
			if(rev==1){
				if(zero)++ans;
				zero=false;continue;
			}
			reve.put(ss, rev);
			cnt.put(ss, cnt.getOrDefault(ss, 0)+1);
		}

		int ans2 = 0;
		Set<Long> used = new HashSet<>();
		for(Map.Entry<Long , Integer> entry: cnt.entrySet()){
			if(used.contains(entry.getKey()))continue;
			ans2 += Math.max(entry.getValue(), cnt.getOrDefault(reve.get(entry.getKey()), 0));
			used.add(reve.get(entry.getKey()));
		}
//		out.println(ans+" "+ans2);
		out.println(ans+ans2);
	}




