import java.util.StringTokenizer;
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.io.OutputStream;
import java.util.HashMap;
import java.util.HashSet;
import java.util.ArrayList;
import java.util.Collections;
public class Main {
	public static ArrayList<Long> primes = new ArrayList<>();
	private static class Pair implements Comparable<Pair> {
		long v;
		long red;
		int a;
		boolean cube;
		public Pair(long v) {
			this.v = v;
			long cbr = (long)Math.cbrt(v);
			cube = (cbr*cbr*cbr == v);
			a = cube ? 0 : 1;
			red = cube ? -1 : reduce(v);
		}
		public int compareTo(Pair p) {
			return p.a-a;
		}
	}
	public static void main(String args[]) {
		Sc sc = new Sc(System.in);
		int n = sc.nI();
		HashMap<Long,Pair> map = new HashMap<>();
		ArrayList<Pair> pairs = new ArrayList<>();
		primes.add(2L);
		for(long i = 3; i<=100000; i+=2) {
			long sqrt = (long) Math.sqrt(i);
			boolean prime = true;
			for(int j = 1; j<primes.size(); j++) {
				long p = primes.get(j);
				if(p>sqrt) break;
				if(i%p == 0) {
					prime = false;
					break;
				}
			}
			if(prime) primes.add(i);
		}

		for(int i = 0; i<n; i++) {
			long v = sc.nL();
			if(map.containsKey(v)) {
				Pair p = map.get(v);
				if(!p.cube) p.a++;
			} else {
				Pair p = new Pair(v);
				map.put(v,p);
				pairs.add(p);
			}
		}
		Collections.sort(pairs);
		HashSet<Long> set = new HashSet<>();
		int picked = 0;
		for(Pair p:pairs) {
			long sqrt = (long)Math.sqrt(p.v);
			boolean isc = p.cube;
			if(!set.contains(p.red)) {
				if(!isc) {
					picked+=p.a;
					long inv = inv(p.red);
					if(inv != -1) {
						if(!set.contains(inv)) set.add(inv);
					}
				} else {
					picked++;
					break;
				}
			}
		}
		System.out.println(picked);

	}
	public static long inv(long v) {
		long ret = 1;
		for(int i = 0; ; i++) {
			long p = primes.get(i);
			long sq = p*p;
			if(sq>v) break;
			if(v%sq == 0) {
				ret *= p;
				v /= sq;
			} else if(v%p == 0) {
				ret *= sq;
				v /= p;
			}
			if(ret>10000000000L) return -1;
		}
		return (v>100000) ? -1 : ret*v*v;
	}
	public static long reduce(long v) {
		for(int i = 0; ; i++) {
			long p = primes.get(i);
			long cube = p*p*p;
			if(cube>v) break;
			while(v%cube == 0) {
				v /= cube;
			}
		}
		return v;
	}
}
class Sc {
    public Sc(InputStream i) {
        r = new BufferedReader(new InputStreamReader(i));
    }

    public boolean hasM() {
        return peekToken() != null;
    }

    public int nI() {
        return Integer.parseInt(nextToken());
    }

    public double nD() { 
        return Double.parseDouble(nextToken());
    }

    public long nL() {
        return Long.parseLong(nextToken());
    }

    public String n() {
        return nextToken();
    }

    private BufferedReader r;
    private String line;
    private StringTokenizer st;
    private String token;

    private String peekToken() {
        if (token == null) 
            try {
                while (st == null || !st.hasMoreTokens()) {
                    line = r.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                }
                token = st.nextToken();
            } catch (IOException e) { }
        return token;
    }

    private String nextToken() {
        String ans = peekToken();
        token = null;
        return ans;
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map.Entry;
import java.util.NoSuchElementException;
import java.util.function.IntUnaryOperator;
import java.util.function.LongUnaryOperator;

import lib.util.collections.IntArrayList;

import static java.lang.Math.max;



public class Main {
    public static void main(String[] args) {
        StringBuilder out = new StringBuilder();
        solve(out);
        PrintWriter pw = new PrintWriter(System.out);
        pw.println(out);
        pw.flush();
        pw.close();
    }

    public static void solve(StringBuilder out) {
        int[] div = eratosthenesDivisors(100000);
        IntArrayList prm = eratosthenes(100000, div);
        int n = In.ni();
        long[] s = In.nl(n);
        int[] rh = new int[n];
        int[] h = new int[n];
        boolean cb = false;
        HashMap<Integer, Integer> hm = new HashMap<>();
        HashMap<Integer, Integer> rhm = new HashMap<>();
        HashSet<Long> rm = new HashSet<>();
        for (int i = 0; i < n; i++) {
            HashMap<Long, Integer> m = primeFactorization(s[i], prm);
            for (Entry<Long, Integer> e : m.entrySet()) {
                long k = e.getKey();
                int v = e.getValue() % 3;
                if (v == 0) rm.add(k);
                else m.put(k, v == 1 ? 1 : -1);
            }
            for (long k : rm) m.remove(k);
            rm.clear();
            h[i] = m.hashCode();
            if (m.size() > 0) hm.put(h[i], hm.getOrDefault(h[i], 0) + 1);
            else cb = true;
            for (Entry<Long, Integer> e : m.entrySet()) m.put(e.getKey(), -e.getValue());
            rh[i] = m.hashCode();
            if (m.size() > 0) rhm.put(rh[i], rhm.getOrDefault(rh[i], 0) + 1);
        }
        int a = 0;
        int b = 0;
        for (Entry<Integer, Integer> e : rhm.entrySet()) {
            int rhash = e.getKey();
            int rnum = e.getValue();
            if (hm.containsKey(rhash)) {
                a += max(rnum, hm.get(rhash));
            } else {
                b += rnum;
            }
        }
        out.append(a / 2 + b + (cb ? 1 : 0));
    }

    /**
     * Enumarate primes equal to or less than n.
     * @param n
     * @return {@code ArrayList} that holds primes.
     */
    public static IntArrayList eratosthenes(final int n, final int[] div) {
        final IntArrayList result = new IntArrayList();
        for (int i = 2; i <= n; i++) if (div[i] == i) result.add(i);
        return result;
    }
    /**
     * execute eratosthenes's prime-enumerate algorithm. a[i] holds the greatest
     * divisor of i. if a[i] = i, i is a prime number. This arrary enables you to
     * prime-factorize in O(log n) time.
     * @param n
     * @return divisor array.
     */
    public static int[] eratosthenesDivisors(final int n) {
        final int[] divisors = new int[n + 1];
        if (n <= 0) return null;
        for (int i = 1; i <= n; i++) {
            if ((i & 1) != 0) divisors[i] = i;
            else divisors[i] = 2;
        }
        for (int i = 3; i <= n; i += 2) {
            if (divisors[i] == i) for (long j = (long) i * i; j <= n; j += i << 1) divisors[(int) j] = i;
        }
        return divisors;
    }

    /**
     * Caluculate prime-factorization in O(sqrt(n)) time.
     * @param n
     * @return {@code HashMap} of {prime: index}
     */
    public static HashMap<Long, Integer> primeFactorization(long n, IntArrayList prm) {
        final HashMap<Long, Integer> primes = new HashMap<>();
        for (int p : prm) {
            int q = 0;
            while (n % p == 0) {n /= p; q++;}
            if (q > 0) primes.put((long) p, q);
        }
        if (n > 1) primes.put(n, 1);
        return primes;
    }
}


