				long p = primes.get(j);
				if(p>sqrt) break;
				if(i%p == 0) {
					prime = false;
					break;
				}
			}
			if(prime) {
				primes.add(i);
				squares.add(i*i);
				cubes.add(i*i*i);
			}
		}
		HashMap<Long,Pair> map = new HashMap<>();
		ArrayList<Pair> pairs = new ArrayList<>();

		for(int i = 0; i<n; i++) {
			long v = sc.nL();
			if(map.containsKey(v)) {
				Pair p = map.get(v);
				p.a++;
			} else {
				Pair p = new Pair(v);
				map.put(v,p);
				pairs.add(p);
			}
		}

		HashMap<Long,Pair> map2 = new HashMap<>();

		ArrayList<Pair> redpairs = new ArrayList<>();

		for(Pair p: pairs) {
			long red = reduce(p.red);
			if(map2.containsKey(red)) {
				Pair pp = map2.get(red);
				pp.a += p.a;
			} else {
				Pair pp = new Pair(red);
				pp.a = p.a;
				map2.put(red,pp);
				redpairs.add(pp);
			}
		}

		Collections.sort(redpairs);
		HashSet<Long> set = new HashSet<>();
		int picked = 0;
		for(Pair p:redpairs) {
			if(p.red == 1) {
				picked++;
				continue;
			}
			if(!set.contains(p.red)) {
				picked+=p.a;
				long inv = inv(p.red);
				if(inv != -1) {
					if(!set.contains(inv)) set.add(inv);
				}
			}
		}

		System.out.println(picked);
	}
	public static long inv(long v) {
		long ret = 1;
		for(int i = 0; i<primes.size() ; i++) {
			long p = primes.get(i);
			long sq = squares.get(i);
			if(sq>v) break;
			if(v%sq == 0) {
				ret *= p;
				v /= sq;
			} else if(v%p == 0) {
				ret *= sq;
				v /= p;
			}
			if(ret>10000000000L) return -1;
		}
		return (v>100000) ? -1 : ret*v*v;
	}
	public static long reduce(long v) {
		for(int i = 0; i<primes.size(); i++) {
			long cube = cubes.get(i);
			if(cube>v) break;
			while(v%cube == 0) {
				v /= cube;
			}
		}
		return v;
	}
}
