		ArrayList<Integer> primes = new ArrayList<>();
		for(int i=0;i<isPrime.length;i++) {
			if (isPrime[i]) {
				if ((long) i * i * i > SMAX) {
					break;
				}
				primes.add(i);
			}
		}
		ArrayList<Long> cube = new ArrayList<>();
		for(int p: primes) {
			long c = (long) p * p * p;
			if (c > SMAX) {
				cube.add(c);
			}
		}

		HashMap<Long,Long> map = new HashMap<>();
		HashMap<Long,Integer> count = new HashMap<>();

		IO io = new IO();
		int n = io.nextInt();
		boolean containsCube = false;
		for(int i=0;i<n;i++) {
			long x = io.nextLong();
			long norm = 1;
			long pair1 = 1; //オーバーフロー対策のためにpair1 * pair2でpairを表す
			long pair2 = 1;
			for(int p: primes) {
				int exp = 0;
				while(x % p == 0) {
					x /= p;
					exp++;
				}
				exp %= 3;
				if (exp == 1) {
					norm *= p;
					pair1 *= p;
					pair2 *= p;
				}else if(exp == 2) {
					norm *= p * p;
					pair1 *= p;
				}
			}
			if (x != 1) {
				int sqrt = (int) Math.sqrt(x);
				if (sqrt * sqrt == x && isPrime[sqrt]) {
					norm *= x;
					pair1 *= sqrt;
				}else{
					norm *= x;
					pair1 *= x;
					pair2 *= x;
				}
			}
			if (norm == 1) {
				containsCube = true;
				continue;
			}
			Integer c = count.get(norm);
			count.put(norm, c == null ? 1 : c + 1);
			if (of(pair1,pair2)) {
				map.put(norm, -1L);
			}else if(norm < pair1 * pair2){
				map.put(norm, pair1 * pair2);
			}
		}
//		System.out.println(count);
//		System.out.println(map);
		int ans = containsCube ? 1 : 0;
		for(Entry<Long, Long> e:map.entrySet()) {
			int a = count.get(e.getKey());
			int b = count.getOrDefault(e.getValue(),0);
			ans += Math.max(a, b);
		}
		System.out.println(ans);
	}

	public static boolean[] isPrimeArray(int max) {
		boolean[] isPrime = new boolean[max+1];
		Arrays.fill(isPrime, true);
		isPrime[0] = isPrime[1] = false;
		for(int i=2;i*i<=max;i++) {
			if (isPrime[i]) {
				int j = i * 2;
				while(j<=max) {
					isPrime[j] = false;
					j += i;
				}
			}
		}
		return isPrime;
	}


