	public static long inv(long v) {
		long ret = 1;
		long p = 0;
		long sq = 0;
		long vsq = 0;
		long vp = 0;
		for(int i = 0; i<326 && v != 1; i++) {
			p = primes[i];
			sq = squares[i];
			if(ret>10000000000L) return -1;
			vsq = v/sq;
			if(vsq*sq == v) {
				ret *= p;
				v = vsq;
				continue;
			}

			vp = v/p;
			if(vp*p == v) {
				ret *= sq;
				v = vp;
			}
		}
		if(v!=1) {
			int sqrt = (int) Math.sqrt(v);
			if(sqrt*sqrt == v) {
				ret *= v;
				v = 1;
			} else if(primeset.contains(v))
				return (Math.log(ret) + 2*Math.log(v) > 24) ? -1 : ret*v*v;
			else return -1;
		} 


		return (ret >= 10000000000L) ? -1 : ret;
	}
	public static long reduce(long v) {
		for(int i = 0; i<326; i++) {
			long cube = cubes[i];
			if(cube>v) break;
			long vc = v/cube;
			while(vc*cube == v) {
				v = vc;
				vc = v/cube;
			}
		}
		return v;
	}
	private static class FHMap {
