		}

		public void put(P p) {
			int w = (int) (p.k%mod);
			while(true) {
				if(map[w] == null) {
					map[w] = p;
					size++;
					return;
				} else if(map[w].k == p.k) {
					map[w] = p;
					return;
				}
				w = (int) ((w + 1)%mod);
			}
		}
		public Pair get(long k) {
			int w = (int) (k%mod);
			while(true) {
				if(map[w] == null) {
					return null;
				} else if(map[w].k == k) {
					return map[w].v;
				}
				w = (int)((w + 1)%mod);
			}
		}
	}
