			int sum = 0;
			key = 1;
			for(int i = 0; i < prime.length; i++){
				int cnt = 0;
				while(value % prime[i] == 0){
					value /= prime[i];
					cnt++;
				}
				m[i] = cnt % 3;
				sum += m[i];
				int kk = 1;
				for(int j = 0; j < m[i]; j++){
					kk *= prime[i];
				}
				key *= kk;
			}
			m[prime.length] = value - 1;

			h = Arrays.hashCode(m);
			zero = sum == 0;
		}
