	public int[] createPrime(int max){
		boolean[] f = new boolean[max + 1];
		for(int i = 2; i * i <= max; i++){
			if(!f[i]){
				for(int j = i * i; j <= max; j += i){
					f[j] = true;
				}
			}
		}

		int cnt = 0;
		for(int i = 2; i <= max; i++){
			if(!f[i]){
				cnt++;
			}
		}

		int[] primes = new int[cnt];
		int idx = 0;
		for(int i = 2; i <= max; i++){
			if(!f[i]){
				primes[idx++] = i;
			}
		}
		return primes;
