import java.io.IOException; 
import java.io.InputStream; 
import java.io.PrintWriter; 
import java.util.*;

class Main{ 

	static void solve(){
		int n = ni();
		long[] s = nla(n);
		boolean[] isPrime = new boolean[100001];
		Arrays.fill(isPrime, true);
		for(int i=2;i<=100000;++i){
			if(!isPrime[i])continue;
			for(int j=i*2;j<=100000;j+=i)isPrime[j]=false;
		}
		List<Integer> primes = new ArrayList<>();
		for(int i=2;i<=100000;++i)if(isPrime[i])primes.add(i);
		Map<Integer, Integer> reve = new HashMap<>();

		Map<Integer , Integer> cnt = new HashMap<>();
		int ans = 0;
		boolean zero=true;
		List<Integer> list = new ArrayList<>();
		List<Integer> rev = new ArrayList<>();
		for(int i=0;i<n;++i){
			list.clear();
			rev.clear();
			for(int k=0;k<primes.size();++k){
				int p= primes.get(k);
				int c = 0;
				while(s[i]%p==0){
					++c;s[i]/=p;
				}
				if(c%3 > 0){
					list.add((k+1) * (c%3==2 ? primes.size()+1: 1));
					rev.add((k+1) * (c%3==2 ? 1: (primes.size()+1)));
				}
				if(s[i]==1)break;
			}
			if(s[i]!=1){
				++ans;continue;
			}
			if(list.isEmpty()){
				if(zero)++ans;
				zero=false;continue;
			}
			int lhash=list.hashCode(), rhash=rev.hashCode();
			reve.put(lhash, rhash);
			cnt.put(lhash, cnt.getOrDefault(lhash, 0)+1);
		}

		int ans2 = 0;
		Set<Integer> used = new HashSet<>();
		for(Map.Entry<Integer , Integer> entry: cnt.entrySet()){
			if(used.contains(entry.getKey()))continue;
			ans2 += Math.max(entry.getValue(), cnt.getOrDefault(reve.get(entry.getKey()), 0));
			used.add(reve.get(entry.getKey()));
		}
		out.println(ans+ans2);
	}




