/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author ilyakor
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        TaskD solver = new TaskD();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskD {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.nextInt();
            //int n = 1000 * 100;
            int[] pr = PrimesGenerator.getPrimes(101000);
            HashSet<Long> prs = new HashSet<>();
            for (int p : pr) prs.add((long) p);
            HashMap<Long, Integer> d = new HashMap<>();
            HashMap<Long, Long> op = new HashMap<>();
            for (int i = 0; i < n; ++i) {
                long x = in.nextLong();
                //long x = 9999999967L;
                long y = 1, oy = 1;
                if (prs.contains(x)) {
                    y *= x;
                    oy *= x;
                    oy *= x;
                } else {
                    long up = (long) Math.pow(2E10 / x, 3.0 / 3.0) + 10;
                    for (int p : pr) {
                        if (p > x) break;
                        if (p > up) break;
                        int c = 0;
                        while (x % p == 0) {
                            x /= p;
                            ++c;
                        }
                        c %= 3;
                        if (c == 0) continue;
                        if (c == 1) {
                            y *= p;
                            oy *= p;
                            oy *= p;
                        } else {
                            y *= p;
                            y *= p;
                            oy *= p;
                        }
                    }
                    if (x != 1) {
                        y *= x;
                        oy = 0;
                    }
                }


                if (d.containsKey(y)) {
                    d.put(y, d.get(y) + 1);
                } else {
                    d.put(y, 1);
                    op.put(y, oy);
                }
            }

            HashSet<Long> used = new HashSet<>();
            int res = 0;
            for (long x : d.keySet()) {
                if (x == 1) {
                    ++res;
                    continue;
                }
                if (used.contains(x)) continue;
                long ox = op.get(x);
                int val = d.get(x);
                int oval = d.containsKey(ox) ? d.get(ox) : 0;
                res += Math.max(val, oval);
                used.add(x);
                used.add(ox);
            }
            out.printLine(res);
        }

    }

    static class PrimesGenerator {
        public static int[] getPrimes(int n) {
            boolean[] prime = new boolean[n + 1];
            Arrays.fill(prime, 2, n + 1, true);
            for (int i = 2; i * i <= n; i++) {
                if (prime[i]) {
                    for (int j = i * i; j <= n; j += i) {
                        prime[j] = false;
                    }
                }
            }
            int[] primes = new int[n + 1];
            int cnt = 0;
            for (int i = 0; i < prime.length; i++)
                if (prime[i])
                    primes[cnt++] = i;

            return Arrays.copyOf(primes, cnt);
        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) {
                    writer.print(' ');
                }
                writer.print(objects[i]);
            }
        }

        public void printLine(Object... objects) {
            print(objects);
            writer.println();
        }

        public void close() {
            writer.close();
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buffer = new byte[10000];
        private int cur;
        private int count;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public static boolean isSpace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public int read() {
            if (count == -1) {
                throw new InputMismatchException();
            }
            try {
                if (cur >= count) {
                    cur = 0;
                    count = stream.read(buffer);
                    if (count <= 0)
                        return -1;
                }
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            return buffer[cur++];
        }

        public int readSkipSpace() {
            int c;
            do {
                c = read();
            } while (isSpace(c));
            return c;
        }

        public int nextInt() {
            int sgn = 1;
            int c = readSkipSpace();
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res = res * 10 + c - '0';
                c = read();
            } while (!isSpace(c));
            res *= sgn;
            return res;
        }

        public long nextLong() {
            long sgn = 1;
            int c = readSkipSpace();
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res = res * 10L + (long) (c - '0');
                c = read();
            } while (!isSpace(c));
            res *= sgn;
            return res;
        }

    }
}

import java.util.*;

public class Main {
	static class Factor {
		ArrayList<Long> f = new ArrayList<>();
		ArrayList<Integer> p = new ArrayList<>();
	}
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		long[] s = new long[N];
		for(int i=0; i<N; i++)
			s[i] = sc.nextLong();

		long[] norm = s.clone();
		HashMap<Long, Integer> cnt = new HashMap<>();
		HashMap<Long, Factor> map = new HashMap<>();
		for(int i=0; i<N; i++) {
			Factor fac = new Factor();
			long div = s[i];
			for(long j=2; j*j*j<=div; j++) {
				int k=0;
				while(div%j==0) {
					div /= j;
					k++;
					if(k%3==0)
						norm[i] /= j*j*j;
				}
				if(k%3>0) {
					fac.f.add(j);
					fac.p.add(k%3);
				}
			}
			long sqrt = (long)Math.floor(Math.sqrt(div+0.5));
			if(sqrt*sqrt==div && sqrt>1) {
				fac.f.add(sqrt);
				fac.p.add(2);
			} else {
				fac.f.add(div);
				fac.p.add(1);
			}
			if(!cnt.containsKey(norm[i])) {
				cnt.put(norm[i], 1);
				map.put(norm[i], fac);
			} else {
				cnt.put(norm[i], cnt.get(norm[i])+1);
			}
		}

		int ans = 0;

		for(Long key : cnt.keySet()) {
			if(key==1) {
				ans++;
			} else {
				int normCnt = cnt.get(key);
				long pair = 1;
				Factor cur = map.get(key);
				for(int i=0; i<cur.f.size(); i++) {
					for(int j=0; j<3-cur.p.get(i); j++) {
						double check = (double)pair*cur.f.get(i);
						if(check>10000000000l)
							pair = 0;
						else
							pair *= cur.f.get(i);
					}
				}
				int pairCnt = cnt.containsKey(pair) ? cnt.get(pair) : 0;
				if(normCnt > pairCnt || (normCnt==pairCnt && key>pair))
					ans += normCnt;
			}
		}

		System.out.println(ans);
		sc.close();
	}
}

import java.io.IOException;
