	public static long inv(long v) {
		long ret = 1;
		long div = 1;
		for(int i = 0; i<primes.length; i++) {
			long p = primes[i];
			long sq = squares[i];
			if(sq>v) break;
			long vp = v/p;
			long vsq = v/sq;
			if(vsq*sq == v) {
				ret *= p;
				v = vsq;
			} else if(vp == v*p) {
				ret *= sq;
				v = vp;
			}
			if(ret>10000000000L) return -1;
		}
		return (Math.log(ret) + 2*Math.log(v) >= 24) ? -1 : ret*v*v;
	}
	public static long reduce(long v) {
		for(int i = 0; i<326; i++) {
			long cube = cubes[i];
			if(cube>v) break;
			long vc = v/cube;
			while(vc*cube == v) {
				v = vc;
				vc = v/cube;
			}
		}
		return v;
	}
	private static class FHMap {
