        public void solve() {
            int n = io.readInt();
            long[] s = new long[n];
            for (int i = 0; i < n; i++) {
                s[i] = io.readLong();
            }

            long limit = (long) 1e10;
            Map<Long, Integer> cntMap = new HashMap<>(n);
            Map<Long, Long> oppositeMap = new HashMap<>(n);
            NumberTheory.EulerSieve es = new NumberTheory.EulerSieve(100000);
            Map<Long, Integer> p2 = new HashMap<>(100000);
            for (int i = 0; i < es.primeLength; i++) {
                int p = es.primes[i];
                p2.put((long) p * p, p);
            }

            for (int i = 0; i < n; i++) {
                long v = s[i];
                long factor = 1;
                long opposite = 1;
                for (int j = 0; ; j++) {
                    long p = es.primes[j];
                    long p3 = p * p * p;
                    if (p3 > v) {
                        break;
                    }
                    int factorCnt = 0;
                    while (v % p3 == 0) {
                        v /= p3;
                    }
                    while (v % p == 0) {
                        v /= p;
                        factorCnt++;
                    }
                    for (int k = 0; k < factorCnt; k++) {
                        factor *= p;
                    }
                    for (int k = 0; k < (3 - factorCnt) % 3; k++) {
                        opposite = mul(opposite, p);
                    }
                }

                factor *= v;

                //p^2
                if (p2.containsKey(v)) {
                    opposite *= p2.get(v);
                } else {
                    opposite = mul(opposite, v);
                    opposite = mul(opposite, v);
                }
                oppositeMap.put(factor, opposite);
                cntMap.put(factor, cntMap.getOrDefault(factor, 0) + 1);
            }

            int ans = 0;
            for (Map.Entry<Long, Long> entry : oppositeMap.entrySet()) {
                if (entry.getKey() > entry.getValue() && cntMap.containsKey(entry.getValue())) {
                    continue;
                }
                if (entry.getKey().equals(entry.getValue())) {
                    ans++;
                } else {
                    ans += Math.max(cntMap.getOrDefault(entry.getKey(), 0), cntMap.getOrDefault(entry.getValue(), 0));
                }
            }

            io.cache.append(ans);
        }

        public long mul(long a, long b) {
            if (a > 1e11 / b) {
                return lInf;
            }
            return a * b;
        }
