	long gcd(long a, long b) {
		while (b != 0) {
			long t = a % b;
			a = b;
			b = t;
		}
		return a;
	}
	boolean isProbableComposite(long a, long N) {
		long d = N - 1;
		int R = 0;
		while ((d & 1) == 0) {
			++R;
			d >>= 1;
		}
		long x = pow_mod(a, d, N);
		if (x == 1) return false;
		while (R-->0) {
			if (x == N - 1) return false;
			x = mod_mul(x, x, N);
		}
		return true;
	}

	boolean isProbablePrime(long N) {
		if (N < MAX_N) return isPrime[(int)N];
		for (int i = 0; i < 5; i++) {
			long a = (long) (Math.random() * (N - 1) + 1);
			if (isProbableComposite(a, N))
				return false;
		}
		return true;
	}

	// a * b % m;
	long mod_mul(long a, long b, long m) {
		long res = 0;
		while (b > 0) {
			if ((b & 1) == 1) {
				res += a;
				if (res < 0 || m <= res) {
					res = res - m;
				}
			}
			b >>= 1;
			a <<= 1;
			if (a < 0 || m <= a) {
				a = a - m;
			}
		}
		return res;
	}

	long pow_mod(long a, long b, long p) {
		long res = 1;
		while (b > 0) {
			if ((b & 1) == 1) res = mod_mul(res, a, p);
			a = mod_mul(a, a, p);
			b >>= 1;
		}
		return res;
	}

