			long x = 1, y = 0, p = 1;
			long two = 1;

			for (int i = 1; p == 1; i++) {
				if (i == two) {
					y = x;
					two <<= 1;
				}
				x = mod_mul(x, x, n) + c;
				if (x >= n) x -= n;

				if (x == y) {
					c++;
					continue LOOP;
				}
				p = gcd(Math.abs(x - y), n);
			}
			return p;
		}
	}


	long[] factorize(long n) {
		if (isProbablePrime(n)) {
			return new long[] { n };
		}

		long[] res = new long[80];
		int len = 0;

		final int NAIVE_BOUND = 1 << 3;
		for (int i = 0; primes[i] < NAIVE_BOUND && primes[i] * primes[i] <= n; i++) {
			final long p = primes[i];
			while (n % p == 0) {
				n /= p;
				res[len++] = p;
			}
		}

		if (n != 1) {
			if (isProbablePrime(n)) {
				res[len++] = n;
			} else {
				long p = pollardRho(n);
				if (p == n) {
					res[len++] = n;
				} else {
					for (long fi : factorize(p))
						res[len++] = fi;
					for (long fi : factorize(n / p))
						res[len++] = fi;
				}
			}
		}

		res = Arrays.copyOf(res, len);
		Arrays.sort(res);
		return res;

	}
	static void tr(Object... os) { System.err.println(deepToString(os)); }

	public static void main(String[] args) throws Exception {
		new Main().run();
	}

	MyScanner sc = null;
	PrintWriter out = null;
	public void run() throws Exception {
		sc = new MyScanner(System.in);
		out = new PrintWriter(System.out);
		for (;sc.hasNext();) {
			solve();
			out.flush();
		}
		out.close();
	}

	class MyScanner {
		String line;
		BufferedReader reader;
		StringTokenizer tokenizer;

		public MyScanner(InputStream stream) {
			reader = new BufferedReader(new InputStreamReader(stream));
			tokenizer = null;
		}
		public void eat() {
			while (tokenizer == null || !tokenizer.hasMoreTokens()) {
				try {
					line = reader.readLine();
					if (line == null) {
						tokenizer = null;
						return;
					}
					tokenizer = new StringTokenizer(line);
				} catch (IOException e) {
					throw new RuntimeException(e);
				}
			}
		}
		public String next() {
			eat();
			return tokenizer.nextToken();
		}
		public String nextLine() {
			try {
				return reader.readLine();
			} catch (IOException e) {
				throw new RuntimeException(e);
			}
		}
		public boolean hasNext() {
			eat();
			return (tokenizer != null && tokenizer.hasMoreElements());
		}
		public int nextInt() {
			return Integer.parseInt(next());
		}
		public long nextLong() {
			return Long.parseLong(next());
		}
		public double nextDouble() {
			return Double.parseDouble(next());
		}
		public int[] nextIntArray(int n) {
			int[] a = new int[n];
			for (int i = 0; i < n; i++) a[i] = nextInt();
			return a;
		}
	}
}

