                    conj = mul(conj, x, MAX);
                    conj = mul(conj, x, MAX);
                }else{
                    norm *= x;
                    conj = mul(conj, sq, MAX);
                }
            }
            mp.put(norm, mp.getOrDefault(norm, 0)+1);
            con.put(norm, conj);
        }
        int ans = 0;
