import java.util.Set;


public class Main {

	private static int[] primes = sieveAtkin(100000);

	public static void main(String[] args) {

		FastScanner sc = new FastScanner();
		int N = sc.nextInt();
		long[] s = sc.nextLongList(N);

		long[][] t = new long[N][];
		for (int i = 0; i < N; i ++) {
			t[i] = factorize(s[i]);
		}

		Set<Long> set = new HashSet<>();
		int count = 0;
		for (long[] x : t) {
			if (!set.contains(x[1])) {
				set.add(x[0]);
				count ++;
			}
		}
		System.out.println(count);

	}

	public static int[] sieveAtkin(int size) {
		boolean[] isPrime = new boolean[size + 1];
		int sqrtN = (int) Math.sqrt(size);
		int n;
		for (int x = 1; x <= sqrtN; ++x) {
			for (int y = 1; y <= sqrtN; ++y) {
				n = 4 * x * x + y * y;
				if (n <= size && (n % 12 == 1 || n % 12 == 5)) {
					isPrime[n] = !isPrime[n];
				}
				n = 3 * x * x + y * y;
				if (n <= size && n % 12 == 7) {
					isPrime[n] = !isPrime[n];
				}
				n = 3 * x * x - y * y;
				if (x > y && n <= size && n % 12 == 11) {
					isPrime[n] = !isPrime[n];
				}
			}
		}

		for (n = 5; n <= sqrtN; ++n) {
			if (isPrime[n]) {
				for (int k = n * n; k <= size; k += n * n) {
					isPrime[k] = false;
				}
			}
		}
		isPrime[2] = isPrime[3] = true;

		int[] ret = new int[size];
		int count = 0;
		for (int i = 1; i < size; i ++) {
			if (isPrime[i]) {
				ret[count ++] = i;
			}
		}
		return Arrays.copyOf(ret, count);
	}

	public static long[] factorize(long n) {
		int rp = (int)(Math.sqrt(n) * 1.1);
		long[] factors = {1L, 1L};
		for (int i = 0; primes[i] <= rp; i ++) {
			int p = primes[i];
			int count = 0;
			while (n % p == 0) {
				count ++;
				n /= p;
			}
			count %= 3;
			if (count > 0) {
				if (count == 1) {
					factors[0] *= p;
					factors[1] *= p * p;
				} else {
					factors[0] *= p * p;
					factors[1] *= p;
				}
			}
			if (n == 1) {
				break;
			}
		}
		if (n != 1) {
			factors[0] *= n;
			factors[1] *= n * n;
		}

		return factors;
	}
}



