				picked+=p.a;
				long inv = inv(p.red);
				if(inv != -1) {
					if(!set.contains(inv)) set.add(inv);
				}
			}
		}

		System.out.println(picked);
	} catch (Exception e) {}

	}
	public static long inv(long v) {
		long ret = 1;
		for(int i = 0; ; i++) {
			long p = primes.get(i);
			long sq = p*p;
			if(sq>v) break;
			if(v%sq == 0) {
				ret *= p;
				v /= sq;
			} else if(v%p == 0) {
				ret *= sq;
				v /= p;
			}
			if(ret>10000000000L) return -1;
		}
		return (v>100000) ? -1 : ret*v*v;
	}
	public static long reduce(long v) {
		for(int i = 0; ; i++) {
			long p = primes.get(i);
			long cube = p*p*p;
			if(cube>v) break;
			while(v%cube == 0) {
				v /= cube;
			}
		}
		return v;
	}
}
class Sc {
