public class Program
{
    private int N;
    private long[] S;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        S = new long[N];
        for (int i = 0; i < N; i++)
        {
            S[i] = sc.NextLong();
        }

        var c = new HashMap<BigInteger, int>();
        var p = new HashMap<BigInteger, BigInteger>();
        int ans = 0;
        foreach (long l in S)
        {
            long tmpl = l;
            BigInteger norm = 1;
            BigInteger pair = 1;

            for (long i = 2; i * i <= tmpl; i++)
            {
                if (tmpl % i == 0)
                {
                    int cnt = 0;
                    while (tmpl % i == 0)
                    {
                        cnt++;
                        tmpl /= i;
                    }

                    if (cnt % 3 == 1)
                    {
                        norm *= i;
                        pair *= i * i;
                    }
                    else if (cnt % 3 == 2)
                    {
                        norm *= i * i;
                        pair *= i;
                    }
                }
            }

            norm *= tmpl;
            pair *= (BigInteger) tmpl * tmpl;


            if (norm == 1)
            {
                ans = 1;
            }
            else
            {
                c[norm]++;
                p[norm] = pair;
            }

            // Console.WriteLine($"{l} {norm}");
        }

        var keys = c.Keys.ToArray();
        foreach (BigInteger bigInteger in keys)
        {

            // Console.WriteLine($"{bigInteger}:{c[bigInteger]} {p[bigInteger]}:{c[p[bigInteger]]}");
            ans += Math.Max(c[bigInteger], c[p[bigInteger]]);
            c[bigInteger] = 0;
            c[p[bigInteger]] = 0;
        }

        Console.WriteLine(ans);
    }

    public static void Main(string[] args)
    {
        new Program().Solve();
    }
}

