      else if(numberList.Count() == 0)
      {
        numberList.Add(numbers[i][0]);
        numberPartnerList.Add(numbers[i][1]);
        numberCountList.Add(1);
      }else if(numberList[numberList.Count()-1] == numbers[i][0])
      {
        numberCountList[numberList.Count()-1]++;
      }else
      {
        numberList.Add(numbers[i][0]);
