	class Problem : IDisposable
	{
		bool IsGCJ;
		int Repeat;
		Scanner sc;
		Printer pr;
		public Problem(bool isGCJ, Scanner scanner, Printer printer)
		{
			sc = scanner;
			pr = printer;
			IsGCJ = isGCJ;
			if (isGCJ) Repeat = sc.Get<int>();
			else Read();
		}
		public Problem(bool isGCJ) : this(isGCJ, new Scanner(), new Printer()) { }
		public Problem(bool isGCJ, Scanner scanner) : this(isGCJ, scanner, new Printer()) { }
		public Problem(bool isGCJ, Printer printer) : this(isGCJ, new Scanner(), printer) { }
		public void Solve()
		{
			if (IsGCJ) for (var i = 0; i < Repeat; i++) { Read(); pr.Write("Case #" + (i + 1) + ": "); SolveOne(); }
			else SolveOne();
		}
		public void Dispose()
		{
			sc.Dispose();
			pr.Dispose();
		}
		public int Size { get { return 1; } }
		public const long Mod = 1000000007;
		RandomSFMT rand = Program.rand;
		int N;
		long[] s;
		void Read()
		{
			sc.Read(out N);
			s = sc.ReadManyLines<long>(N);
		}
		void SolveOne()
		{
			var ps = Func.GetPrimes(101000);
			var p2 = new Dictionary<long, int>();
			foreach (var p in ps) p2.Add(p * (long)p, p);
			var n = new long[N];
			var cnt = new Dictionary<long, int>();
			var d = new Dictionary<long, long>();
			for (var i = 0; i < N; i++)
			{
				var num = s[i];
				var fact = new List<int>();
				var t = 1L;
				for (var j = 0; j < ps.Count; j++)
				{
					var x = ps[j];
					var cube = x * (long)x * x;
					if (cube > num) break;
					if (num % x == 0)
					{
						fact.Add(x);
						while (num % cube == 0) num /= cube;
						if (num % (x * (long)x) == 0) t *= x;
						else if (num % x == 0) t *= x * (long)x;
					}
				}
				n[i] = num;
				if (!d.ContainsKey(n[i]))
				{
					foreach (var p in fact) while (num % p == 0) num /= p;
					var lim = 10000000100L / t;
					var lim2 = (int)(Math.Sqrt(lim) + 10);
					if (p2.ContainsKey(num)) { if (p2[num] < lim) t *= p2[num]; else t = -1; }
					else { if (num < lim2) t *= num * num; else t = -1; }
					d[n[i]] = t;
					cnt[n[i]] = 0;
				}
				cnt[n[i]]++;
			}
			var sum = 0;
			var set = new HashSet<long>(n);
			var done = new HashSet<long>();
			if (set.Contains(1)) { sum++; set.Remove(1); }
			foreach (var x in set)
			{
				if (done.Contains(x)) continue;
				var y = d[x];
				if (cnt.ContainsKey(y)) sum += Math.Max(cnt[x], cnt[y]);
				else sum += cnt[x];
				done.Add(x);
				done.Add(y);
			}
			pr.WriteLine(sum);
		}
	}
