public class Program
{
    private int N;
    private long[] S;

    private List<long> Primes;
    private Dictionary<long, long> PrimeSquare;
    private HashMap<long, int> Cnt;
    private HashMap<long, long> Pair;
    private int Ans;
    private bool OneFlag;

    private void Scan()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        S = new long[N];
        for (int i = 0; i < N; i++)
        {
            S[i] = sc.NextLong();
        }
    }

    /// <summary>
    /// 10^5までの素数&2乗列挙
    /// </summary>
    private void SetPrime()
    {
        Primes = new List<long>();
        MathEx.Sieve(100000, Primes);
        PrimeSquare = new Dictionary<long, long>();

        foreach (long l in Primes)
        {
            PrimeSquare[l * l] = l;
        }
    }

    // pairが10^10強ならfalse
    // lからlを立方数でできるだけ割ったnormとnorm * pair が立方数になるpairを求める pairがオーバーフローする可能性あり
    private bool Calc(long l, out long norm, out long pair)
    {
        norm = 1;
        BigInteger tmpPair = 1;
        foreach (long prime in Primes)
        {
            long pow3 = prime * prime * prime;
            if (pow3 > l)
            {
                break;
            }


            while (l % pow3 == 0)
            {
                l /= pow3;
            }
            long pow2 = prime * prime;
            if (l % pow2 == 0)
            {
                norm *= pow2;
                tmpPair *= prime;
                l /= pow2;
            }
            else if (l % prime == 0)
            {
                norm *= prime;
                tmpPair *= pow2;
                l /= prime;
            }
        }

        long sqrt;
        if (PrimeSquare.TryGetValue(l, out sqrt))
        {
            tmpPair *= sqrt;
        }
        else
        {
            tmpPair *= l;
            tmpPair *= l;
        }

        norm *= l;

        if (tmpPair <= 10000000000)
        {
            pair = (long) tmpPair;
            return true;
        }
        else
        {
            pair = -1;
            return false;
        }
    }

    private void Count()
    {
        Ans = 0;
        OneFlag = false;
        Cnt = new HashMap<long, int>();
        Pair = new HashMap<long, long>();
        foreach (long l in S)
        {
            long norm, pair;
            bool b = Calc(l, out norm, out pair);
            if (b)
            {
                if (norm == 1)
                {
                    OneFlag = true;
                }
                else
                {
                    Cnt[norm]++;
                    Pair[norm] = pair;
                }
            }
            else
            {
                Ans++;
            }
        }

        if (OneFlag)
        {
            Ans++;
        }
    }

    private void CalcAnser()
    {
        var keys = Cnt.Keys.ToArray();
        foreach (long l in keys)
        {
            Ans += Math.Max(Cnt[l], Cnt[Pair[l]]);
            Cnt[l] = 0;
            Cnt[Pair[l]] = 0;
        }
    }

    public void Solve()
    {
        Scan();
        SetPrime();
        Count();
        CalcAnser();
        Console.WriteLine(Ans);
    }

    public static void Main(string[] args)
    {
        new Program().Solve();
    }
}

