    public long[][] powmat(long[][] A, long n)
    {
        var E = new long[A.Length][];
        for (int i = 0; i < A.Length; i++)
        {
            E[i] = new long[A.Length];
            E[i][i] = 1;
        }
        if (n == 0) return E;
        var t = powmat(A, n / 2);
        if ((n & 1) == 0) return mulmat(t, t);
        return mulmat(mulmat(t, t), A);
    }
    public long[] mulmat(long[][] A, long[] x)
    {
        var ans = new long[A.Length];
        for (int i = 0; i < A.Length; i++) for (int j = 0; j < x.Length; j++) ans[i] = (ans[i] + x[j] * A[i][j]) % Mod;
        return ans;
    }
    public long[][] mulmat(long[][] A, long[][] B)
    {
        var ans = new long[A.Length][];
        for (int i = 0; i < A.Length; i++)
        {
            ans[i] = new long[B[0].Length];
            for (int j = 0; j < B[0].Length; j++) for (int k = 0; k < B.Length; k++) ans[i][j] = (ans[i][j] + A[i][k] * B[k][j]) % Mod;
        }
        return ans;
    }
    public long powmod(long a, long b)
    {
        if (a >= Mod) return powmod(a % Mod, b);
        if (a == 0) return 0;
        if (b == 0) return 1;
        var t = powmod(a, b / 2);
        if ((b & 1) == 0) return t * t % Mod;
        return t * t % Mod * a % Mod;
    }
    public long gcd(long a, long b)
    {
        while (b > 0) { var t = a % b; a = b; b = t; }
        return a;
    }
    public long lcm(long a, long b) { return a * (b / gcd(a, b)); }
    public long Comb(int n, int r)
    {
        if (n < 0 || r < 0 || r > n) return 0;
        if (n - r < r) r = n - r;
        if (r == 0) return 1;
        if (r == 1) return n;
        var numerator = new int[r];
        var denominator = new int[r];
        for (int k = 0; k < r; k++)
        {
            numerator[k] = n - r + k + 1;
            denominator[k] = k + 1;
        }
        for (int p = 2; p <= r; p++)
        {
            int pivot = denominator[p - 1];
            if (pivot > 1)
            {
                int offset = (n - r) % p;
                for (int k = p - 1; k < r; k += p)
                {
                    numerator[k - offset] /= pivot;
                    denominator[k] /= pivot;
                }
            }
        }
        long result = 1;
        for (int k = 0; k < r; k++) if (numerator[k] > 1) result = result * numerator[k] % Mod;
        return result;
    }
}

using System;
using System.Linq;//リストの使用
using System.Collections.Generic;
using System.Text;//テキストの高速出力に必要
class Program
{

	static void Main()
	{
		int n = int.Parse(Console.ReadLine());
		long[] nums = new long[n];
    for(int i = 0; i < n; i++) nums[i] = long.Parse(Console.ReadLine());
    long[][] numbers = new long[n][];
    long answer = 0;
    for(int i = 0; i < n; i++)
    {
      numbers[i] = new long[2];
      numbers[i][0] = nums[i];
      numbers[i][1] = 1;
    }

    List<long> primes = GetPrimeList(2500);

    List<long> numberList = new List<long>();
    List<long> numberPartnerList = new List<long>();
    List<long> numberCountList = new List<long>();

    for(int i = 0; i < n; i++)
    {
      for(int j = 0; j < primes.Count(); j++)
      {
        while(numbers[i][0] % (primes[j]*primes[j]*primes[j]) == 0)
        {
          numbers[i][0] /= (primes[j]*primes[j]*primes[j]);
          nums[i] /= primes[j]*primes[j]*primes[j];
        }

        if(numbers[i][0] % (primes[j]*primes[j]) == 0)
        {
          numbers[i][1] *= primes[j];
          nums[i] /= primes[j]*primes[j];
        }else if(numbers[i][0] % primes[j] == 0)
        {
          numbers[i][1] *= primes[j]*primes[j];
          nums[i] /= primes[j];
        }
      }
      if(nums[i] != 1) numbers[i][1] = -1;
    }

    Array.Sort(numbers, (a, b) => a[0].CompareTo(b[0]));

    for(int i = 0; i < n; i++)
    {
      if(numbers[i][1] == -1) answer++;
      else if(numberList.Count() == 0)
      {
        numberList.Add(numbers[i][0]);
        numberPartnerList.Add(numbers[i][1]);
        numberCountList.Add(1);
        //Console.WriteLine(numbers[i][0]+" "+numbers[i][1]);
      }else if(numberList[numberList.Count()-1] == numbers[i][0])
      {
        numberCountList[numberList.Count()-1]++;
      }else
      {
        numberList.Add(numbers[i][0]);
        numberPartnerList.Add(numbers[i][1]);
        numberCountList.Add(1);
        //Console.WriteLine(numbers[i][0]+" "+numbers[i][1]);
      }
    }
    if(numberList[0] == 1)
    {
      answer++;
      numberList.RemoveAt(0);
      numberPartnerList.RemoveAt(0);
      numberCountList.RemoveAt(0);
    }

    //Console.WriteLine(answer);

    long[,] compressNums = new long[2*numberList.Count(),2];

    for(int i = 0; i < numberList.Count(); i++)
    {
      compressNums[i,0] = numberList[i];
      compressNums[i,1] = i;
      compressNums[numberList.Count()+i,0] = numberPartnerList[i];
      compressNums[numberList.Count()+i,1] = numberList.Count()+i;
    }
    compressNums = CoordinateCompression(compressNums);

    long[] answers = new long[2*numberList.Count()];
    for(int i = 0; i < numberList.Count(); i++)
    {
      answers[compressNums[i,2]] = numberCountList[i];
    }
    for(int i = 0; i < numberList.Count(); i++)
    {
      if(answers[compressNums[numberList.Count()+i,2]] != 0)
      {
        answers[compressNums[numberList.Count()+i,2]]
          = Math.Max(answers[compressNums[numberList.Count()+i,2]],numberCountList[i]);
        answers[compressNums[i,2]] = 0;
      }
    }

    for(int i = 0; i < 2*numberList.Count(); i++) answer += answers[i];
		Console.WriteLine(answer);
	}

  static long[,] CoordinateCompression(long[,] vertexesOriginal)
    //1次元の座標圧縮。配列は0-indexで引数[x,順番]から[x,順番,圧縮x]を返す。
    //例えば、{2,4,4,3}は{0,2,2,1}を返す。
  {
    long n = vertexesOriginal.GetLength(0);//多次元配列の長さの取得
    long xCount = 1;//圧縮後のxの個数
    long[] compressedXmemo = new long[n];
    long[][] vertexes = new long[n][];
    for(long i = 0; i < n; i++)
    {
      vertexes[i] = new long[3];
      for(long j = 0; j < 2; j++)
      {
        vertexes[i][j] = vertexesOriginal[i,j];//配列をジャグ配列に置換
      }
    }

    Array.Sort(vertexes, (a, b) => a[0].CompareTo(b[0]));//x座標でソート
    vertexes[0][2] = 0;
    compressedXmemo[0] = vertexes[0][0];
    for(long i = 1; i < n; i++)
    {
      if(vertexes[i][0] == vertexes[i-1][0])//x座標が同じ
      {
        vertexes[i][2] = xCount - 1;
      }else
      {
        xCount++;
        vertexes[i][2] = xCount - 1;
        compressedXmemo[xCount-1] = vertexes[i][0];
      }
    }
    long[] compressedX = new long[xCount];
    for(long i = 0; i < xCount; i++) compressedX[i] = compressedXmemo[i];

    Array.Sort(vertexes, (a, b) => a[1].CompareTo(b[1]));//もとの番号順でソート

    long[,] answer = new long[n,3];
    for(long i = 0; i < n; i++)
    {
      for(long j = 0; j < 3; j++)
      {
        answer[i,j] = vertexes[i][j];//ジャグ配列から戻す
      }
    }

    return answer;//[x,順番,圧縮x]を返す。
  }

  static List<long> GetPrimeList(long maxPrime)//「引数1以上」max以下の素数のリストを返す。エラトステネスの篩を用いる。
  {
    List<long> answers = new List<long>();
    bool[] isPrimes = new bool[maxPrime];//素数リスト
    isPrimes[0] = false;//1は素数でないのでfalse
    for(long i = 1; i < maxPrime; i++) isPrimes[i] = true;//素数と仮定してtrue

    for(long i = 2; i <= Math.Sqrt(maxPrime); i++)
    {
      if(isPrimes[i-1])
      {
        for (long j = i*2; j <= maxPrime; j+=i)
        {
          isPrimes[j-1] = false;//素数でないのでfalse
        }
      }
    }

    for(int i = 0; i < maxPrime; i++)
    {
      if(isPrimes[i]) answers.Add(i+1);
    }

    return answers;
  }

}

