        var pr = new bool[lim];
        for (int i = 2; i < lim; i++)
            pr[i] = true;
        for (int i = 2; i * i < lim; i++)
        {
            if (pr[i])
            {
                for (int j = i * i; j < lim; j += i)
                    pr[j] = false;
            }
        }
        tri = new List<long>();
        for (int i = 2; i < lim; i++)
        {
            if (pr[i])
                tri.Add(i * (long)i * i);
        }
        var dic = new SortedDictionary<long, int>();
        for (int i = 0; i < n; i++)
        {
            s[i] = conv(sc.Long);
            if (dic.ContainsKey(s[i]))
                ++dic[s[i]];
            else
                dic.Add(s[i], 1);
        }
        var key = new long[dic.Count]; // num
        var val = new int[dic.Count]; // cnt
        int cnt = 0;
        foreach (var item in dic)
        {
            key[cnt] = item.Key;
            val[cnt] = item.Value;
            ++cnt;
        }
        Array.Sort(val, key);
        var ng = new SortedSet<long>();
        int ans = 0;
        for (int i = cnt - 1; i >= 0; i--)
        {
            if (key[i] == 1)
            {
                ++ans;
                continue;
            }
            if (ng.Contains(key[i])) continue;

            ng.Add(conv(key[i] * key[i]));
            ans += val[i];
        }
        sw.WriteLine(ans);
        sw.Flush();
    }
    static long conv(long a)
    {
        long b = a;
        for (int i = 0; i < tri.Count; i++)
        {
            if (b < tri[i]) return b;
            if (b % tri[i] == 0)
            {
                b /= tri[i];
                --i;
            }
        }
        return b;
    }

    static void swap<T>(ref T a, ref T b) { var t = a; a = b; b = t; }
    static void swap<T>(IList<T> a, int i, int j) { var t = a[i]; a[i] = a[j]; a[j] = a[i]; }
    static T Max<T>(params T[] a) { return a.Max(); }
    static T Min<T>(params T[] a) { return a.Min(); }

    static T[] copy<T>(IList<T> a)
    {
        var ret = new T[a.Count];
        for (int i = 0; i < a.Count; i++) ret[i] = a[i];
        return ret;
    }
