          nums[i] /= primes[j]*primes[j]*primes[j];
        }

        if(numbers[i][0] % (primes[j]*primes[j]) == 0)
        {
          numbers[i][1] *= primes[j];
          nums[i] /= primes[j]*primes[j];
        }else if(numbers[i][0] % primes[j] == 0)
        {
