        numberPartnerList.Add(numbers[i][1]);
        numberCountList.Add(1);
        //Console.WriteLine(numbers[i][0]+" "+numbers[i][1]);
      }
    }
    if(numberList.Count() > 0)
    {
    if(numberList[0] == 1)
    {
      answer++;
      numberList.RemoveAt(0);
      numberPartnerList.RemoveAt(0);
      numberCountList.RemoveAt(0);
    }
    }

    //Console.WriteLine(answer);

    if(numberList.Count() > 0)
    {
    long[,] compressNums = new long[2*numberList.Count(),2];

