    {
      if(answers[compressNums[numberList.Count()+i,2]] != 0)
      {
        answers[compressNums[numberList.Count()+i,2]]
          = Math.Max(answers[compressNums[numberList.Count()+i,2]],numberCountList[i]);
        answers[compressNums[i,2]] = 0;
      }
