class Program
{
    public void Proc()
    {
        Reader.IsDebug = false;
        int inputCount = int.Parse(Reader.ReadLine());

        for (int i = 0; i < inputCount; i++)
        {
            long num = long.Parse(Reader.ReadLine());
            NumList.Add(num);
        }
        NumList.Sort();

        int ans = this.GetAns(string.Empty, new Dictionary<long, bool>(), 0, 0);
        Console.WriteLine(ans);

    }


    private int GetAns(string keyString, Dictionary<long, bool> key, int idx, long lastKey) {
        if (idx >= this.NumList.Count)
        {
            return 0;
        }
        if(!dic.ContainsKey(keyString)) {
            dic.Add(keyString, new Dictionary<int,int>());
        }
        if(dic[keyString].ContainsKey(idx)) {
            return dic[keyString][idx];
        }

        long num = NumList[idx];
        int ans = 0;
        bool canAdd = true;
        foreach (long k in key.Keys)
        {
            if (!GetCanBoth(k, num))
            {
                canAdd = false;
                break;
            }

        }
        if (canAdd)
        {
            string newKey = keyString;
            long newLastKey = lastKey;
            bool added = false;
            if(lastKey != num) {
                newKey += "#" + num;
                newLastKey = num;
                key.Add(num, true);
                added = true;
            }
            ans = this.GetAns(newKey, key, idx + 1, newLastKey) + 1;
            if (added)
            {
                key.Remove(num);
            }
        }
        ans = Math.Max(ans, this.GetAns(keyString, key, idx + 1, lastKey));
        this.dic[keyString][idx] = ans;
        return ans;

    }

