            {
                CanBoth.Add(num1, new Dictionary<long, bool>());
            }
            CanBoth[num1][num2] = true;
            return true;
        }
        else
        {
            if (!CanBoth.ContainsKey(num1))
            {
                CanBoth.Add(num1, new Dictionary<long, bool>());
            }
            CanBoth[num1][num2] = false;
            return false;

        }
    }


    private long RippouRoot(long num, long max, long min)
    {
        long temp = (max + min) / 2;
        if(temp*temp*temp == num) {
            return temp;
        }
        if (max * max * max == num)
        {
            return max;
        }
        if (min * min * min == num)
        {
            return min;
        }
        if (temp * temp * temp > num)
        {
            if (max - min <= 1)
            {
                return -1;
            }
            else
            {
                return RippouRoot(num, temp, min);
            }
        }
        else
        {
            if (max - min <= 1)
            {
                return -1;
            }
            else
            {
                return RippouRoot(num, max, temp);
            }

        }

    }


