public class Program
{
    private int N;
    private long[] S;

    private List<int> Primes = new List<int>();

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        S = new long[N];
        for (int i = 0; i < N; i++)
        {
            S[i] = sc.NextLong();
        }

        // S[i]の各素因数の次数をmod3した数の個数
        var c = new HashMap<long, int>();

        // S[i]の各素因数の次数をmod3した数 normに p[norm]をかけると立方数になる
        var p = new HashMap<long, long>();

        // sqrt(10^10) = 10^5までの素数表を作成
        MathEx.Sieve(100000, Primes);

        var dict = new Dictionary<long, long>();

        foreach (int i in Primes)
        {
            dict[(long) i * i] = i;
        }

        bool flag = false;
        long ans = 0;
        foreach (long l in S)
        {
            long tmpL = l;
            bool overflowFlag = false;
            BigInteger pair = 1;
            long norm = 1;
            foreach (int i in Primes)
            {
                long pow3 = (long) i * i * i;
                if (pow3 > tmpL)
                {
                    break;
                }

                while (tmpL % pow3 == 0)
                {
                    tmpL /= pow3;
                }

                long pow2 = (long) i * i;

                if (tmpL % pow2 == 0)
                {
                    norm *= pow2;
                    pair *= norm;
                    tmpL /= pow2;
                }
                else if (tmpL % i == 0)
                {
                    norm *= i;
                    pair *= pow2;
                    tmpL /= i;
                }
            }


            long o;
            if (dict.TryGetValue(tmpL,out o))
            {
                // tmpLが平方数
                norm *= tmpL;
                pair *= o;
            }
            else
            {
                // tmpLが素数 or 2素数の積
                norm *= tmpL;
                pair *= tmpL;
                pair *= tmpL;
            }

            if (norm == 1)
            {
                flag = true;
            }
            else if (pair > 10000000000)
            {
                ans++;
            }
            else
            {
                c[norm]++;
                p[norm] = (long)pair;
            }
        }


        var keys = c.Keys.ToArray();

        foreach (long key in keys)
        {
            ans += Math.Max(c[key], c[p[key]]);
            c[key] = 0;
            c[p[key]] = 0;
        }

        if (flag) ans++;
        Console.WriteLine(ans);
    }

    public static void Main(string[] args)
    {
        new Program().Solve();
    }
}

