func max(x,y int) int {
  if x > y { return x }
  return y
}
var p []int64
func norm(s int64) (int64,int64) {
  a,b := int64(1),int64(1)
  for i:=0;i<len(p);i++ {
    if s < p[i] { break }
    x := 0
    for s%p[i] == 0 {
      s /= p[i]
      x++
    }
    x %= 3
    if x == 1 {
      a *= p[i]
      b *= p[i]*p[i]
    } else if x == 2 {
      a *= p[i]*p[i]
      b *= p[i]
    }
  }
  if s != 1 {
    a *= s
    t := int64(math.Sqrt(float64(s)+0.5))
    if t*t == s {
      b *= t
    } else {
      b *= s*s
    }
  }
  return a,b
}
