  for i:=0;i<n+1;i++ {
    if x[i] { continue }
    for j:=i;j<n+1;j+=i { x[j] = true }
    x[i] = false
  }
  for i:=0;i<n+1;i++ {
    if x[i] { continue }
    p = append(p,int64(i))
  }
}

