struct BarrettULong {
    ulong value, m;
    int lg;
    this(ulong value) {
        import core.bitop : bsr;
        this.value = value;
        if (value <= 1) return;
        lg = value.bsr;
        if (1UL<<lg != value) lg++;
        version(X86_64) {
            version(LDC) {
                inv = inlineIR!(`
                    %r0 = zext i64 %0 to i128 
                    %r1 = add i128 %r0, 18446744073709551615
                    %r2 = udiv i128 %r1, %r0
                    %r3 = trunc i128 %r2 to i64
                    ret i64 %r3`, ulong)(value);
            } else version(D_InlineAsm_X86_64) {
                ulong buf = (2<<(lg-1))-value;
                ulong res;
                asm {
                    mov RDX, buf;
                    mov RAX, 0;
                    div value;
                    inc RAX;
                    mov res, RAX;
                }
                m = res;
            } else {
                pragma(msg, "BarrettULong is slow");
            }
        } else {
            pragma(msg, "BarrettULong is slow in x86");
        }
    }
    ulong opBinaryRight(string op:"/")(ulong x) const {
        assert(value != 0);
        if (value == 1) return x;
        ulong r;
        version(X86_64) {
            version(LDC) {
                r = inlineIR!(`
                    %r0 = zext i64 %0 to i128 
                    %r1 = zext i64 %1 to i128
                    %r2 = mul i128 %r1, %r0
                    %r3 = lshr i128 %r2, 64
                    %r4 = trunc i128 %r3 to i64
                    ret i64 %r4`, ulong)(inv, x);
            } else version(D_InlineAsm_X86_64) {
                ulong buf = m;
                ulong res;
                asm {
                    mov RAX, buf;
                    mul x;
                    mov res, RDX;
                }
                r = (res + ((x-res)>>1)) >> (lg-1);
            } else {
                r = x/value;
            }
        } else {
            r = x/value;
        }
        return r;
    }
    ulong opBinaryRight(string op:"%")(ulong x) const {
        return x - x/this*value;
    }
}

