int[] primeList(int n) {
    bool[] used = new bool[n+1];
    FastAppender!(int[]) ans;
    foreach (i; 2..n+1) {
        if (used[i]) continue;
        ans ~= i;
        foreach (j; iota(i, n+1, i)) {
            used[j] = true;
        }
    }
    return ans.data;
}

int[long] fastFactor(ulong x, in BarrettULong[] primes) {
    int[long] mp;
    foreach (p; primes) {
        while (x%p == 0) {
            mp[p.value]++;
            x=x/p;
        }
    }
    if (x) mp[x]++;
    return mp;
}

long mul(long x, long y) {
    if (10L^^12 / x < y) return 10L^^12;
    return x*y;
}

