            while(v%p==0) v/=p, ++c;
            c%=3;
            if(c!=0)
            {
                foreach(_;0..c) a*=p;
                foreach(_;0..3-c) r*=p;
            }
        }
        if(v>1){ a*=v; r=-1; }
        AS[k]=a;
        RS[k]=r;
        if(a !in b) b[a]=1;
        else ++b[a];
        if(r !in b) b[r]=0;
