int[] primeList(int n) {
    bool[] used = new bool[n+1];
    FastAppender!(int[]) ans;
    foreach (i; 2..n+1) {
        if (used[i]) continue;
        ans ~= i;
        foreach (j; iota(i, n+1, i)) {
            used[j] = true;
        }
