    return ans.data;
}

int[long] fastFactor(ulong x, in BarrettULong[] primes) {
    int[long] mp;
    foreach (p; primes) {
        while (x%p == 0) {
            mp[p.v]++;
            x=x/p;
        }
    }
    if (x) mp[x]++;
    return mp;
}

long mul(long x, long y) {
    if (10L^^12 / x < y) return 10L^^12;
    return x*y;
}

int main() {
    auto sc = new Scanner(stdin);
    auto pr = primeList(100_100);
    auto bpr = pr.map!(x => BarrettULong(x)).array;
