            c %= 3;
            if (c == 1) {
                d0 = mul(d0, p);
                d1 = mul(d1, p);
                d1 = mul(d1, p);
            } else if (c == 2) {
                d0 = mul(d0, p);
                d0 = mul(d0, p);
                d1 = mul(d1, p);
            }
        }
        if (d0 == 1) {
