struct BarrettULong {
    ulong v, u;
    this(ulong x) {
        this.v = x;
        if (x == 1) return;
        version(LDC) {
            u = inlineIR!(`
                %r0 = zext i64 %0 to i128 
                %r1 = add i128 %r0, 18446744073709551615
                %r2 = udiv i128 %r1, %r0
                %r3 = trunc i128 %r2 to i64
                ret i64 %r3`, ulong)(x);
        } else {
            asm {
                mov RBX, this;
                mov RDX, 1;
                mov RAX, x;
                dec RAX;
                div x;
                mov u[RBX], RAX;
            }
        }
    }
    ulong opBinaryRight(string op:"/")(ulong x) const {
        assert(v != 0);
        if (v == 1) return x;
        ulong r;
        version(LDC) {
            r = inlineIR!(`
                %r0 = zext i64 %0 to i128 
                %r1 = zext i64 %1 to i128
                %r2 = mul i128 %r1, %r0
                %r3 = lshr i128 %r2, 64
                %r4 = trunc i128 %r3 to i64
                ret i64 %r4`, ulong)(u, x);
        } else {
            asm {
                mov RBX, this;
                mov RAX, u[RBX];
                mul x;
                mov r, RDX;
            }
        }
        return r;
    }
    ulong opBinaryRight(string op:"%")(ulong x) const {
        return x - x/this*v;
    }
}
