int[] primeList(int n) {
    bool[] used = new bool[n+1];
    FastAppender!(int[]) ans;
    foreach (i; 2..n+1) {
        if (used[i]) continue;
        ans ~= i;
        foreach (j; iota(i, n+1, i)) {
            used[j] = true;
        }
    }
    return ans.data;
}

int[long] fastFactor(ulong x, in BarrettULong[] primes) {
    int[long] mp;
    foreach (p; primes) {
        while (x%p == 0) {
            mp[p.value]++;
            x=x/p;
        }
    }
    if (x) mp[x]++;
    return mp;
}

long mul(long x, long y) {
    if (10L^^12 / x < y) return 10L^^12;
    return x*y;
}

int main() {
    auto sc = new Scanner(stdin);
    auto pr = primeList(100_100);
    auto bpr = pr.map!(x => BarrettULong(x)).array;
    int n;
    sc.read(n);
    int[2][long] g;
    bool one = false;
    foreach (i; 0..n) {
        long s;
        sc.read(s);
//        writeln(fastFactor(s, bpr));
        long d0 = 1, d1 = 1;
        foreach (p, c; fastFactor(s, bpr)) {
            c %= 3;
            if (c == 1) {
                d0 = mul(d0, p);
                d1 = mul(d1, p);
                d1 = mul(d1, p);
            } else if (c == 2) {
                d0 = mul(d0, p);
                d0 = mul(d0, p);
                d1 = mul(d1, p);
            }
        }
        if (d0 == 1) {
            one = true;
            continue;
        }
        if (d0 < d1) {
            if (d0 in g) {
                g[d0][0]++;
            } else {
                g[d0] = [1, 0];
            }
        } else {
            if (d1 in g) {
                g[d1][1]++;
            } else {
                g[d1] = [0, 1];
            }
        }
    }

    int ans = 0;
    if (one) ans++;
    foreach (u; g) {
        ans += max(u[0], u[1]);
    }
    writeln(ans);
    return 0;
}
