		if (f.count(tmp)) {
			ans += max(f[a[i]], f[tmp]);
			was[tmp] = 1;
		} 
		else {
			ans += f[a[i]];
		}
		was[a[i]] = 1;
	}
	cout << ans << '\n';
}

