def prime_sieve(end):
    assert end > 1
    is_prime = [True for i in range(end)]
    is_prime[0], is_prime[1] = False, False
    primes = list()
    for i in range(2,end):
        if is_prime[i]:
            primes.append(i)
            for j in range(2 * i, end, i):
                is_prime[j] = False
    return primes

def prime_factorize(n,primes):
  res = []
  for i in primes:
    tmp = 0
    while not (n%i):
      n //= i
      tmp += 1
    res.append(tmp%3)
  res.append(n)
  return tuple(res)


