def eratosthenes(n):
    isp = [True] * (n + 1)
    for i in range(2, n):
        if i * i > n:
            break
        if isp[i]:
            for i in range(i * 2, n + 1, i):
                isp[i] = False
    return [i for i in range(2, n + 1) if isp[i]]

