def eratosthenes_sieve(n):
    table = [0] * (n + 1)
    prime_list = []

    for i in xrange(2, n + 1):
        if table[i] == 0:
            prime_list.append(i)
            for j in xrange(i + i, n + 1, i):
                table[j] = 1

    return prime_list

def trial_division_sqrt(n):
    prime_count = collections.Counter()

    for i in xrange(2, int(math.sqrt(n)) + 2):
        while n % i == 0:
            n /= i
            prime_count[i] += 1
    if n > 1:
        prime_count[n] += 1

    for p, c in prime_count.iteritems():
        prime_count[p] = c % 3

    return prime_count

def trial_division_prime(n, prime_list):
    prime_count = collections.Counter()

    for i in prime_list:
        if i * i > n:
