fn run<I: Input, O: Write>(mut kin: I, mut out: O) {
    macro_rules! output { ($($args:expr),+) => { write!(&mut out, $($args),+).unwrap(); }; }
    macro_rules! outputln {
        ($($args:expr),+) => { output!($($args),+); outputln!(); };
        () => { output!("\n"); if cfg!(debug_assertions) { out.flush().unwrap(); } }
    }

    let n: usize = kin.input();
    let s: Vec<usize> = kin.seq(n);

    let ps = primes(100000);
    let mut map = BTreeMap::new();
    for &x in &s {
        let mut x = x;
        let mut y = 1;
        for &p in &ps {
            if p * p > x {
                break;
            }
            let mut k = 0;
            while x % p == 0 {
                x /= p;
                k += 1;
            }
            for _ in 0..k % 3 {
                y *= p;
            }
        }
        y *= x;
        *map.entry(y).or_insert(0) += 1;
    }

    let mut ans = 0;
    let mut used = BTreeSet::new();
    for (&x, &c) in map.iter() {
        if x == 1 {
            ans += 1;
            continue;
        }
        if used.contains(&x) {
            continue;
        }
        let mut x = x;
        let mut y = 1usize;
        for &p in &ps {
            if p * p > x {
                break;
            }
            let mut k = 0;
            while x % p == 0 {
                x /= p;
                k += 1;
            }
            if k == 1 {
                y = y.saturating_mul(p.saturating_mul(p));
            }
            if k == 2 {
                y = y.saturating_mul(p);
            }
        }
        y = y.saturating_mul(x.saturating_mul(x));

        if let Some(&d) = map.get(&y) {
            used.insert(y);
            ans += c.max(d);
        } else {
            ans += c;
        }
    }

    outputln!("{}", ans);

    // eprintln!("{:?}", map);
}

pub fn primes(n: usize) -> Vec<usize> {
    // 1, 7, 11, 13, 17, 19, 23, 29
    const SKIP: [u8; 8] = [6, 4, 2, 4, 2, 4, 6, 2];
    const XTOI: [u8; 15] = [
        0, 0, 0, 1, 0, 2, 3, 0, 4, 5, 0, 6, 0, 0, 7,
    ];
    let mut sieve = vec![0u8; n / 30 + 1];
    let mut ps = vec![2, 3, 5];
    if n <= 4 {
        ps.truncate([0, 0, 1, 2, 2][n]);
        return ps;
    }
    let mut x = 7;
    let mut i = 1;
    while x <= n {
        if sieve[i / 8] & 1 << i % 8 == 0 {
            ps.push(x);
            let mut j = i;
            let mut y = x * x;
            while y <= n {
                sieve[y / 30] |= 1 << XTOI[y / 2 % 15];
                y += x * SKIP[j % 8] as usize;
                j += 1;
            }
        }
        x += SKIP[i % 8] as usize;
        i += 1;
    }
    ps
}

