fn generate_primes(upto: usize) -> (Vec<i64>, Vec<bool>) {
    let mut is_prime = vec![true; upto+1];
    is_prime[0] = false;
    is_prime[1] = false;
    for i in 2..upto+1 {
        if is_prime[i] {
            let mut ii = i * i;
            while ii <= upto {
                is_prime[ii] = false;
                ii += i;
            }
        }
    }

    let mut primes = vec![];
    for i in 0..upto+1 {
        if is_prime[i] {
            primes.push(i as i64);
        }
    }
    (primes, is_prime)
}

const LIMIT: i64 = 1e10 as i64;


fn solve(a: Vec<i64>, b: Vec<i64>, one: bool) -> i64 {
    let mut totalmap = HashMap::new();
    let mut amap = HashMap::new();
    let mut flag = 1;
    for list in vec![&a, &b] {
        for &a in list {
            let key = flag*a;
            if let Some(&w) = totalmap.get(&key) {
                totalmap.insert(key, w+1);
            } else {
                totalmap.insert(key, 1i64);
            }
        }
        flag *= -1;
    }
    for &a in &a {
        if let Some(&w) = amap.get(&a) {
            amap.insert(a, w+1);
        } else {
            amap.insert(a, 1i64);
        }
    }

    let mut total = 0;
    for (key, count) in totalmap {
        let ac = *amap.get(&key).unwrap_or(&0);
        let bc = count-ac;
        if one {
            if key < 0 {
                continue;
            }
            if key == 0 {
                total += 1;
            } else {
                let mac = *amap.get(&-key).unwrap_or(&0);
                total += max(ac, mac);
            }
        } else {
            total += max(ac, bc);
        }
    }
    total
}


fn main() {
    input! {
