    };

    let (p, _) = generate_primes(100000);
    let pn = p.len();
    let mut low_primes = vec![];
    let mut high_primes = vec![];
    for i in 0..pn {
        if p[i] < 2155 {
            low_primes.push(p[i]);
        } else {
            high_primes.push(p[i]);
        }
    }

    let ln = low_primes.len();
    let hn = high_primes.len();

    let mut nlist = vec![];
    for i in 0..n {
        let mut w = a[i];
        let mut norm = 1;
        let mut cnorm = 1;
        for j in 0..ln {
            let mut ct = 0;
            while w >= low_primes[j] && w % low_primes[j] == 0 {
                w /= low_primes[j];
                ct += 1;
            }
            ct %= 3;
            for c in 0..ct {
                norm *= low_primes[j];
            }
            for c in 0..((3-ct)%3) {
                cnorm *= low_primes[j];
            }
        }
        nlist.push((norm, cnorm, w));
    }
    nlist.sort();

    let mut wmap = HashMap::<i64, Vec<usize>>::new();
    for i in 0..n {
        if wmap.contains_key(&nlist[i].2) {
            wmap.get_mut(&nlist[i].2).unwrap().push(i);
        } else {
            wmap.insert(nlist[i].2, vec![]);
        }
    }
    let mut visited = vec![false; n];
    for h in 0..hn {
        let hi = h as i64;
        let p0 = high_primes[h];
        let p1 = high_primes[h]*high_primes[h];
        for &idx in wmap.get(&p0).unwrap_or(&vec![]) {
            visited[idx] = true;
            nlist[idx].2 = 1000+hi;
        }
        for &idx in wmap.get(&p1).unwrap_or(&vec![]) {
            visited[idx] = true;
            nlist[idx].2 = -(1000+hi);
        }
    }
    for i in 0..n {
        if !visited[i] {
            if nlist[i].2 != 1 {
                nlist[i].2 = 1;
            } else {
                nlist[i].2 = 0;
            }
        }
    }

    let mut id_map = HashMap::new();
    let mut groups = vec![];
    {
        let mut i = 0;
        while i < n {
            let mut w = vec![];
            let mut j = i;
            while j < n && nlist[i].0 == nlist[j].0 {
                w.push(nlist[j].2);
                j += 1;
            }
            id_map.insert(nlist[i].0, groups.len());
            groups.push((nlist[i].0, nlist[i].1, w));
            i = j;
        }
    }

    // debug!(groups);

    let mut ans = 0;
    let gn = groups.len();
    for i in 0..gn {
        if let Some(&j) = id_map.get(&groups[i].1) {
            if i < j {
                ans += solve(groups[i].2.clone(), groups[j].2.clone(), false);
            } else if i == j {
                ans += solve(groups[i].2.clone(), vec![], true);
            }
        } else {
            ans += solve(groups[i].2.clone(), vec![], false);
        }
    }
    println!("{}", ans);
}

use std::io;
use std::collections::BTreeSet;
use std::collections::BTreeMap;
use std::cmp;

const MAX_S: usize = 10000000000;
const MAX_Q: usize = 100000;

fn main() {
    let primes = {
        let mut is_prime = vec![true; 1000000];
        is_prime[0] = false;
        is_prime[1] = false;
        for i in 2..is_prime.len() {
            if !is_prime[i] {
                continue;
            }
            let mut c = i * 2;
            while c < is_prime.len() {
                is_prime[c] = false;
                c += i;
            }
        }
        let mut primes = Vec::new();
        for i in 0..is_prime.len() {
            if is_prime[i] {
                primes.push(i);
            }
        }
        primes
    };

    let p2_map = {
        let mut map = BTreeMap::new();
        for p in &primes {
            let p = *p;
            map.insert(p * p, p);
        }
        map
    };

    let n = read_values::<usize>()[0];

    let mut count_map = BTreeMap::new();
    let mut pair_map = BTreeMap::new();

    let mut one = 0;

    for _ in 0..n {
        let mut s = read_values::<usize>()[0];
        let mut v = Vec::new();

        for p in primes.iter() {
            let p = *p;
            let p3 = p * p * p;
            if p3 > s {
                break;
            }
            while s % p3 == 0 {
                s /= p3;
            }

            if s % (p * p) == 0 {
                v.push((p, 2));
                s /= (p * p);
            } else if s % p == 0 {
                v.push((p, 1));
                s /= p;
            }
        }
        if s != 1 {
            match p2_map.get(&s) {
                Some(p) => v.push((*p, 2)),
                _ => v.push((s, 1)),
            }
        }

        let mut norm = 1;
        let mut pair = 1;
        for t in &v {
            let (p, count) = *t;
            if count == 1 {
                norm *= p;
                if p >= MAX_Q || pair >= MAX_S || pair * p >= MAX_S {
                    pair = 0;
                }
                pair *= (p * p);
            } else {
                norm *= p * p;
                if pair >= MAX_S || pair * p >= MAX_S {
                    pair = 0;
                }
                pair *= p;
            }
        }

        if pair != 0 {
            pair_map.insert(pair, norm);
            pair_map.insert(norm, pair);
        }

        if norm == 1 {
            one = 1;
        } else if count_map.contains_key(&norm) {
            let c = *count_map.get(&norm).unwrap();
            count_map.insert(norm, c + 1);
        } else {
            count_map.insert(norm, 1);
        }
    }

    let mut ans = one;
    let mut viewed_set = BTreeSet::new();
    for key in count_map.keys() {
        if viewed_set.contains(key) {
            continue;
        }

        match pair_map.get(key) {
            Some(pair) => {
                let c1 = *count_map.get(key).unwrap();
                let c2 = match count_map.get(pair) {
                    Some(c2) => *c2,
                    _ => 0,
                };
                viewed_set.insert(*key);
                viewed_set.insert(*pair);
                ans += cmp::max(c1, c2);
            }
            _ => {
                ans += *count_map.get(key).unwrap();
                viewed_set.insert(*key);
            }
        }
    }

    println!("{}", ans);
}

