fn generate_primes(upto: usize) -> (Vec<i64>, Vec<bool>) {
    let mut is_prime = vec![true; upto+1];
    is_prime[0] = false;
    is_prime[1] = false;
    for i in 2..upto+1 {
        if is_prime[i] {
            let mut ii = i * i;
            while ii <= upto {
                is_prime[ii] = false;
                ii += i;
            }
        }
    }

    let mut primes = vec![];
    for i in 0..upto+1 {
        if is_prime[i] {
            primes.push(i as i64);
        }
    }
    (primes, is_prime)
}

const LIMIT: i64 = 1e10 as i64;


fn solve(a: Vec<i64>, b: Vec<i64>, one: bool) -> i64 {
    let mut totalmap = HashMap::new();
    let mut amap = HashMap::new();
    let mut flag = 1;
    for list in vec![&a, &b] {
        for &a in list {
            let key = flag*a;
            if let Some(&w) = totalmap.get(&key) {
                totalmap.insert(key, w+1);
            } else {
                totalmap.insert(key, 1i64);
            }
        }
        flag *= -1;
    }
    for &a in &a {
        if let Some(&w) = amap.get(&a) {
            amap.insert(a, w+1);
        } else {
            amap.insert(a, 1i64);
        }
    }

    let mut total = 0;
    for (key, count) in totalmap {
        let ac = *amap.get(&key).unwrap_or(&0);
        let bc = count-ac;
        if one {
            if key < 0 {
                continue;
            }
            if key == 0 {
                total += 1;
            } else {
                let mac = *amap.get(&-key).unwrap_or(&0);
                total += max(ac, mac);
            }
        } else {
            total += max(ac, bc);
        }
    }
    total
}


fn main() {
    input! {
        n: usize,
        a: [i64; n]
    };

    let (p, _) = generate_primes(100000);
    let pn = p.len();
    let mut low_primes = vec![];
    let mut high_primes = vec![];
    for i in 0..pn {
        if p[i] < 2155 {
            low_primes.push(p[i]);
        } else {
            high_primes.push(p[i]);
        }
    }

    let ln = low_primes.len();
    let hn = high_primes.len();

    let mut nlist = vec![];
    for i in 0..n {
        let mut w = a[i];
        let mut norm = 1;
        let mut cnorm = 1;
        for j in 0..ln {
            let mut ct = 0;
            while w >= low_primes[j] && w % low_primes[j] == 0 {
                w /= low_primes[j];
                ct += 1;
            }
            ct %= 3;
            for c in 0..ct {
                norm *= low_primes[j];
            }
            for c in 0..((3-ct)%3) {
                cnorm *= low_primes[j];
            }
        }
        nlist.push((norm, cnorm, w));
    }
    nlist.sort();

    let mut wmap = HashMap::<i64, Vec<usize>>::new();
    for i in 0..n {
        if wmap.contains_key(&nlist[i].2) {
            wmap.get_mut(&nlist[i].2).unwrap().push(i);
        } else {
            wmap.insert(nlist[i].2, vec![]);
        }
    }
    let mut visited = vec![false; n];
    for h in 0..hn {
        let hi = h as i64;
        let p0 = high_primes[h];
        let p1 = high_primes[h]*high_primes[h];
        for &idx in wmap.get(&p0).unwrap_or(&vec![]) {
            visited[idx] = true;
            nlist[idx].2 = 1000+hi;
        }
        for &idx in wmap.get(&p1).unwrap_or(&vec![]) {
            visited[idx] = true;
            nlist[idx].2 = -(1000+hi);
        }
    }
    for i in 0..n {
        if !visited[i] {
            if nlist[i].2 != 1 {
                nlist[i].2 = 1;
            } else {
                nlist[i].2 = 0;
            }
        }
    }

    let mut id_map = HashMap::new();
    let mut groups = vec![];
    {
        let mut i = 0;
        while i < n {
            let mut w = vec![];
            let mut j = i;
            while j < n && nlist[i].0 == nlist[j].0 {
                w.push(nlist[j].2);
                j += 1;
            }
            id_map.insert(nlist[i].0, groups.len());
            groups.push((nlist[i].0, nlist[i].1, w));
            i = j;
        }
    }

    // debug!(groups);

    let mut ans = 0;
    let gn = groups.len();
    for i in 0..gn {
        if let Some(&j) = id_map.get(&groups[i].1) {
            if i < j {
                ans += solve(groups[i].2.clone(), groups[j].2.clone(), false);
            } else if i == j {
                ans += solve(groups[i].2.clone(), vec![], false);
            }
        } else {
            ans += solve(groups[i].2.clone(), vec![], false);
        }
    }
    println!("{}", ans);
}

