fn generate_primes(upto: usize) -> (Vec<i64>, Vec<bool>) {
    let mut is_prime = vec![true; upto+1];
    is_prime[0] = false;
    is_prime[1] = false;
    for i in 2..upto+1 {
        if is_prime[i] {
            let mut ii = i * i;
            while ii <= upto {
                is_prime[ii] = false;
                ii += i;
            }
        }
    }

    let mut primes = vec![];
    for i in 0..upto+1 {
        if is_prime[i] {
            primes.push(i as i64);
        }
    }
    (primes, is_prime)
}

const LIMIT: i64 = 1e10 as i64;

fn solve(a: Vec<i64>, b: Vec<i64>, one: bool) -> i64 {
    let mut totalmap = HashMap::new();
    let mut amap = HashMap::new();
    let mut flag = 1;
    for list in vec![&a, &b] {
        for &a in list {
            let key = flag*a;
            if let Some(&w) = totalmap.get(&key) {
                totalmap.insert(key, w+1);
            } else {
                totalmap.insert(key, 1i64);
            }
        }
        flag *= -1;
    }
    for &a in &a {
        if let Some(&w) = amap.get(&a) {
            amap.insert(a, w+1);
        } else {
            amap.insert(a, 1i64);
        }
    }

    let mut total = 0;
    for (key, count) in totalmap {
        let ac = *amap.get(&key).unwrap_or(&0);
        let bc = count-ac;
        if one {
            if key < 0 {
                continue;
            }
            if key == 0 {
                total += 1;
            } else {
                let mac = *amap.get(&-key).unwrap_or(&0);
                // debug!(key, ac, mac);
                total += max(ac, mac);
            }
        } else {
            total += max(ac, bc);
        }
    }
    total
}


fn main() {
    input! {
        n: usize,
        a: [i64; n]
    };

    let (p, _) = generate_primes(1000000);
    let pn = p.len();

    let low_primes = p.clone().into_iter().filter(|&x| x < 2200).collect::<Vec<_>>();

    let mut p3map_all = HashMap::<i64, i64>::new();
    for i in 1..2500 {
        p3map_all.insert(i*i*i, i);
    }

    let mut p3map = HashMap::<i64, i64>::new();
    let mut p2map = HashMap::<i64, i64>::new();
    let mut p1map = HashMap::<i64, i64>::new();
    for i in 0..pn {
        p3map.insert(p[i]*p[i]*p[i], p[i]);
        p2map.insert(p[i]*p[i], p[i]);
        p1map.insert(p[i], p[i]);
    }


    // 2155
    let mut singular = 0;
    let mut map = HashMap::<(i64, i64), i64>::new();
    let mut ans = 0;
    let mut has_p3 = false;
    for i in 0..n {
        if p3map_all.contains_key(&a[i]) {
            has_p3 = true;
            continue;
        }
        let mut aa = a[i];
        let mut base = 1;
        let mut antibase = 1;
        for &p in &low_primes {
            let mut count = 0;
            while aa % p == 0 {
                aa /= p;
                count += 1;
            }
            count %= 3;
            base *= p.pow(count);
            antibase *= p.pow((3-count)%3);
        }
        if aa >= 2 {
            if let Some(&p) = p1map.get(&aa) {
                base *= p;
                antibase *= p*p;
            } else if let Some(&p) = p2map.get(&aa) {
                base *= p*p;
                antibase *= p;
            } else {
                singular += 1;
                continue;
            }
        }

        assert!(base != 1);
        if let Some(&mut x) = map.get_mut(&(base, antibase)) {
            map.insert((base, antibase), x+1);
        } else {
            map.insert((base, antibase), 1);
        }
    }

    let mut half = 0;
    for (&(k0, k1), &v) in &map {
        if let Some(&u) = map.get(&(k1, k0)) {
            ans += max(v, u);
        } else {
            half += v;
        }
    }
    ans /= 2;
    ans += half;
    ans += singular;
    ans += ifv!(has_p3, 1, 0);
    println!("{}", ans);
}

