    let mut has_cube = false;
    for i in 0..n {
        let mut aa = a[i];
        let mut normalized = 1;
        let mut anti = 1;
        let mut is_cube = true;
        for pi in 0..pn {
            let p = primes[pi];
            if aa < p || p > 3200 {
                break
            }

            let mut cnt = 0;
            while aa % p == 0 {
                aa /= p;
                cnt += 1;
            }
            if cnt % 3 == 1 {
                normalized *= p;
                anti *= p;
                anti *= p;
                is_cube = false;
            } else if cnt % 3 == 2 {
                normalized *= p;
                normalized *= p;
                anti *= p;
                is_cube = false;
            }
        }

        let mut cango = false;
        if aa >= 2 {
            is_cube = false;
            if aa < is_prime.len() as i64 && is_prime[aa as usize] {
                normalized *= aa;
                anti *= aa;
                anti *= aa;
                cango = true;
            } else {
                let leftp = (aa as f64).sqrt() as i64;
                if leftp * leftp == aa {
                    normalized *= aa;
                    anti *= leftp;
                    cango = true;
                }
            }
        } else {
            cango = true;
        }

        if !is_cube {
            if cango {
                insert(normalized, anti, &mut anti_map, &mut count_map);
            } else {
                ans += 1;
            }
        }
        has_cube |= is_cube;
    }


    // println!("{:?}", anti_map);
