fn main() {
    let n: usize = read();
    let a: Vec<i64> = readn(n);

    let primes = generate_primes(100010);
    let pn = primes.len();


    let mut anti_map = HashMap::new();
    let mut count_map: HashMap<i64, usize> = HashMap::new();

    let mut ans = 0;
    let mut has_cube = false;
    for i in 0..n {
        let mut aa = a[i];
        let mut normalized = 1;
        let mut anti = 1;
        let mut is_cube = true;
        for pi in 0..pn {
            let p = primes[pi];
            if aa < p {
                break
            }
            let mut cnt = 0;
            while aa % p == 0 {
                aa /= p;
                cnt += 1;
            }
            if cnt % 3 == 1 {
                normalized *= p;
                anti *= p;
                anti *= p;
                is_cube = false;
            } else if cnt % 3 == 2 {
                normalized *= p;
                normalized *= p;
                anti *= p;
                is_cube = false;
            }
        }
        if aa >= 2 {
            ans += 1;
        } else if !is_cube {
            anti_map.insert(normalized, anti);

            match count_map.get(&normalized) {
                Some(&n) => count_map.insert(normalized, n+1),
                _        => count_map.insert(normalized, 1),
            };
        }
        has_cube |= is_cube;
    }

    let mut processed = HashSet::new();
    for (num, &v0) in count_map.iter() {
        let anti = anti_map.get(&num).unwrap();
        if processed.contains(num) || processed.contains(anti) {
            continue
        }
        let zero = &0;
        let v1 = *count_map.get(&anti).unwrap_or(zero);
